-- A palette is a ladder: every grey is the background stepped a fixed way
-- towards the text colour, so one background, one text and one accent make a
-- whole theme. The steps differ, so no two keys ever share a colour - the
-- Theme page recolours by value and relies on that.
local C = { void = Color3.fromRGB(0, 0, 0), white = Color3.fromRGB(255, 255, 255) }
local THEME = {
	keys = { "window", "card", "panel", "field", "line", "hover", "border", "chip", "track",
		"faint", "sub", "icon", "knob", "value", "text", "accent", "onAccent" },
	order = { "Onyx", "Graphite", "Carbon", "Slate", "Ash", "Midnight", "Ocean", "Mint", "Forest", "Gold",
		"Amber", "Crimson", "Rose", "Sakura", "Violet" },
}
do
	-- the steps up from the background; wide enough that cards, fields and
	-- pictures on them never sink into one black
	local STEPS = { card = 0.04, panel = 0.05, field = 0.09, line = 0.095, hover = 0.12, border = 0.13,
		chip = 0.16, track = 0.19, faint = 0.37, sub = 0.56, icon = 0.61, knob = 0.67, value = 0.85 }
	local function rgb(c)
		return Color3.fromRGB(math.floor(c.R * 255 + 0.5), math.floor(c.G * 255 + 0.5), math.floor(c.B * 255 + 0.5))
	end
	THEME.rgb = rgb
	function THEME.ladder(base, text, accent)
		local p = { window = rgb(base), text = rgb(text), accent = rgb(accent), onAccent = rgb(base:Lerp(Color3.new(), 0.25)) }
		for key, k in pairs(STEPS) do p[key] = rgb(base:Lerp(text, k)) end
		return p
	end
	local L, c = THEME.ladder, Color3.fromRGB
	-- Onyx first: dark, never black. The rest are starting points the colour
	-- cards under them can change.
	THEME.presets = {
		Onyx = L(c(19, 19, 22), c(238, 238, 241), c(242, 242, 245)),
		Graphite = L(c(26, 26, 30), c(242, 242, 244), c(244, 244, 246)),
		Carbon = L(c(21, 21, 21), c(236, 236, 236), c(240, 240, 240)),
		Slate = L(c(20, 23, 29), c(232, 236, 244), c(226, 234, 248)),
		Ash = L(c(36, 36, 40), c(244, 244, 246), c(250, 250, 252)),
		Midnight = L(c(14, 17, 28), c(232, 238, 255), c(96, 156, 255)),
		Ocean = L(c(12, 19, 25), c(232, 248, 255), c(56, 200, 240)),
		Mint = L(c(13, 21, 19), c(234, 252, 247), c(94, 234, 186)),
		Forest = L(c(14, 20, 13), c(242, 252, 236), c(150, 230, 90)),
		Gold = L(c(20, 17, 13), c(255, 250, 238), c(232, 196, 96)),
		Amber = L(c(21, 17, 12), c(255, 246, 232), c(255, 176, 64)),
		Crimson = L(c(21, 13, 13), c(255, 238, 238), c(240, 62, 72)),
		Rose = L(c(21, 15, 19), c(255, 236, 244), c(255, 120, 170)),
		Sakura = L(c(25, 19, 23), c(255, 242, 247), c(255, 176, 206)),
		Violet = L(c(18, 14, 27), c(244, 238, 255), c(168, 124, 255)),
	}
	for key, color in pairs(THEME.presets.Onyx) do C[key] = color end
	-- names a few older places still use
	function THEME.alias()
		C.tab, C.accentLight, C.tabActive, C.danger = C.sub, C.accent, C.accent, C.text
	end
	THEME.alias()
	-- what everything was drawn with at load: features that captured a colour
	-- then are translated from it
	THEME.boot = {}
	for _, key in ipairs(THEME.keys) do THEME.boot[key] = C[key] end
end

