local COL_GAP = K.L.GAP

local function new(class, props, parent)
	local o = Instance.new(class)
	for k, v in pairs(props) do o[k] = v end
	o.Parent = parent
	return o
end

local function corner(o, r)
	return new("UICorner", { CornerRadius = r == "full" and UDim.new(1, 0) or UDim.new(0, r) }, o)
end

local function stroke(o, color, transparency)
	return new("UIStroke", { Color = color, Transparency = transparency or 0, ApplyStrokeMode = Enum.ApplyStrokeMode.Border }, o)
end

local function pad(o, t, b, l, r)
	return new("UIPadding", {
		PaddingTop = UDim.new(0, t),
		PaddingBottom = UDim.new(0, b),
		PaddingLeft = UDim.new(0, l),
		PaddingRight = UDim.new(0, r),
	}, o)
end

-- a 1px edge in the border grey (t = transparency, for softer ones)
function K.hair(o, t)
	return new("UIStroke", {
		Color = C.border,
		Transparency = math.clamp(((t or 0.9) - 0.9) * 8, 0, 0.9),
		ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
	}, o)
end

-- The watermark's glass, for any frame: lit from above, so the fill falls off
-- towards the bottom, and the edge is a bevel - bright along the top, sinking
-- into a dark rim down the sides. `depth` is how dark the bottom gets; `bare`
-- leaves the edge alone (for frames whose edge means something, like a pick).
function K.sheen(o, depth, bare)
	depth = depth or 0.82
	new("UIGradient", {
		Name = "Glass",
		Rotation = 90,
		Color = ColorSequence.new(Color3.new(1, 1, 1), Color3.new(depth, depth, depth)),
	}, o)
	if bare then return nil end
	local edge = o:FindFirstChildOfClass("UIStroke")
		or new("UIStroke", { ApplyStrokeMode = Enum.ApplyStrokeMode.Border, Thickness = 1 }, o)
	edge.Color = C.knob
	new("UIGradient", {
		Name = "Bevel",
		Rotation = 90,
		Color = ColorSequence.new({
			ColorSequenceKeypoint.new(0, Color3.new(1, 1, 1)),
			ColorSequenceKeypoint.new(0.3, Color3.new(0.32, 0.32, 0.32)),
			ColorSequenceKeypoint.new(1, Color3.new(0.2, 0.2, 0.2)),
		}),
		Transparency = NumberSequence.new({
			NumberSequenceKeypoint.new(0, 0.5),
			NumberSequenceKeypoint.new(0.3, 0.35),
			NumberSequenceKeypoint.new(1, 0.15),
		}),
	}, edge)
	return edge
end

-- one live tween per property; the newest wins
local running = setmetatable({}, { __mode = "k" })
local function tween(o, time, props, style, direction)
	LPH_ATTRIBUTES(VM(NONE))
	local list = running[o]
	if not list then
		list = {}
		running[o] = list
	end
	for prop in pairs(props) do
		if list[prop] then list[prop]:Cancel() end
	end
	local t = TweenService:Create(o, TweenInfo.new(time, style or Enum.EasingStyle.Quad, direction or Enum.EasingDirection.Out), props)
	running[o] = list
	for prop in pairs(props) do
		list[prop] = t
	end
	t.Completed:Once(function()
		for prop in pairs(props) do
			if list[prop] == t then list[prop] = nil end
		end
		if not next(list) and running[o] == list then running[o] = nil end
	end)
	t:Play()
	return t
end
K.running = running

-- every piece of text in the menu starts here
function K.text(parent, props)
	local o = new("TextLabel", {
		BackgroundTransparency = 1,
		FontFace = K.face.medium,
		TextColor3 = C.text,
		TextSize = 13,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextTruncate = Enum.TextTruncate.AtEnd,
	}, parent)
	for k, v in pairs(props or {}) do o[k] = v end
	return o
end

local function decode64(data)
	LPH_ATTRIBUTES(VM(NONE))
	local native = (crypt and type(crypt.base64decode) == "function" and crypt.base64decode)
		or (crypt and type(crypt.base64) == "table" and type(crypt.base64.decode) == "function" and crypt.base64.decode)
		or (type(base64_decode) == "function" and base64_decode)
		or (type(base64) == "table" and type(base64.decode) == "function" and base64.decode)
		or (syn and syn.crypt and type(syn.crypt.base64) == "table" and type(syn.crypt.base64.decode) == "function" and syn.crypt.base64.decode)
	if type(native) == "function" then
		local ok, out = pcall(native, data)
		if ok and type(out) == "string" then return out end
	end
	local map, chars = {}, "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
	for i = 1, 64 do map[chars:byte(i)] = i - 1 end
	data = data:gsub("[^A-Za-z0-9+/]", "")
	local out = table.create(math.ceil(#data / 4))
	local nextCheck, deadline = #data > 500000 and 32769 or math.huge, os.clock() + 0.008
	for i = 1, #data, 4 do
		if i >= nextCheck then
			nextCheck += 32768
			if os.clock() >= deadline then task.wait(); deadline = os.clock() + 0.008 end
		end
		local a, b, c, d = data:byte(i, i + 3)
		a, b, c, d = map[a], map[b], map[c], map[d]
		if not b then break end
		local first = a * 4 + math.floor(b / 16)
		if d then
			out[#out + 1] = string.char(first, (b % 16) * 16 + math.floor(c / 4), (c % 4) * 64 + d)
		elseif c then
			out[#out + 1] = string.char(first, (b % 16) * 16 + math.floor(c / 4))
		else
			out[#out + 1] = string.char(first)
		end
	end
	return table.concat(out)
end

-- Everything this menu writes lives in one folder of its own, well clear of
-- the Salad Visuals one. Configs are .yan files inside it.
local ROOT = "Salad MM2"
K.CACHE = ROOT .. "/cache"
K.CONFIG_DIR = ROOT .. "/configs"
K.CONFIG_EXT = ".yan"

function K.ensureFolders()
	pcall(function()
		if not isfolder(ROOT) then makefolder(ROOT) end
		if not isfolder(K.CACHE) then makefolder(K.CACHE) end
		if not isfolder(K.CONFIG_DIR) then makefolder(K.CONFIG_DIR) end
	end)
end
K.ensureFolders()

-- the menu used to write into "Inertia": carry the old setups over once
pcall(function()
	if not isfolder("Inertia") then return end
	for _, name in ipairs({ "last.txt" }) do
		if isfile("Inertia/" .. name) and not isfile(ROOT .. "/" .. name) then
			writefile(ROOT .. "/" .. name, readfile("Inertia/" .. name))
		end
	end
	if isfile("Inertia/favorites.json") and not isfile(ROOT .. "/favorites" .. K.CONFIG_EXT) then
		writefile(ROOT .. "/favorites" .. K.CONFIG_EXT, readfile("Inertia/favorites.json"))
	end
	if isfolder("Inertia/configs") and type(listfiles) == "function" then
		for _, path in ipairs(listfiles("Inertia/configs")) do
			local name = string.match(tostring(path), "([^/\\]+)%.json$")
			if name and not isfile(K.CONFIG_DIR .. "/" .. name .. K.CONFIG_EXT) then
				writefile(K.CONFIG_DIR .. "/" .. name .. K.CONFIG_EXT, readfile(path))
			end
		end
	end
end)

local function localAsset(file, fetch)
	file = K.CACHE .. "/" .. file
	local ok, data = pcall(function() return isfile(file) and readfile(file) end)
	if not (ok and data) then
		data = fetch()
		if data then pcall(writefile, file, data) end
	end
	if data then
		local fine, asset = pcall(getcustomasset, file)
		if fine and type(asset) == "string" and asset ~= "" then return asset end
	end
end

-- The pictures ship inside the script (assets.lua above): the icon atlas, a
-- soft shadow and a round glow, unpacked once into the cache.
K.art = {}
do
	for name, blob in pairs(SALAD_ART) do
		local ext = string.sub(name, 1, 4) == "font" and ".ttf" or ".png"
		K.art[name] = localAsset("salad-" .. name .. "-" .. ART_VERSION .. ext, function() return decode64(blob) end)
	end
	SALAD_ART = nil
end

-- The type is Inter (SIL OFL), shipped above and registered as a family of
-- four weights; the Theme page can swap it for one of Roblox's own. Without
-- file access Inter falls back to Builder Sans.
do
	local A = K.art
	local base = "rbxasset://fonts/families/"
	-- a short list of faces that each look clearly different from the rest
	K.fonts = {
		-- (Gotham is drawn with Montserrat these days, so only one of them)
		order = { "Inter", "Montserrat", "Nunito", "Ubuntu", "Titillium Web", "Josefin Sans", "Michroma", "Roboto Mono" },
		family = {
			Inter = base .. "BuilderSans.json", Montserrat = base .. "Montserrat.json",
			Nunito = base .. "Nunito.json", ["Titillium Web"] = base .. "TitilliumWeb.json",
			["Josefin Sans"] = base .. "JosefinSans.json", Ubuntu = base .. "Ubuntu.json",
			Michroma = base .. "Michroma.json", ["Roboto Mono"] = base .. "RobotoMono.json",
		},
	}
	if A.font400 and A.font500 and A.font600 and A.font700 then
		local path = K.CACHE .. "/salad-inter-" .. ART_VERSION .. ".json"
		pcall(writefile, path, HttpService:JSONEncode({
			name = "Inter",
			faces = {
				{ name = "Regular", weight = 400, style = "normal", assetId = A.font400 },
				{ name = "Medium", weight = 500, style = "normal", assetId = A.font500 },
				{ name = "SemiBold", weight = 600, style = "normal", assetId = A.font600 },
				{ name = "Bold", weight = 700, style = "normal", assetId = A.font700 },
			},
		}))
		local ok, family = pcall(getcustomasset, path)
		if ok and type(family) == "string" and family ~= "" then K.fonts.family.Inter = family end
	end
	function K.facesOf(family)
		local W = Enum.FontWeight
		local f = {
			regular = Font.new(family, W.Regular), medium = Font.new(family, W.Medium),
			semi = Font.new(family, W.SemiBold), bold = Font.new(family, W.Bold), heavy = Font.new(family, W.Bold),
		}
		-- leftovers from the mono captions read as plain text now
		f.mono, f.monoBold = f.medium, f.semi
		return f
	end
	pcall(function() K.face = K.facesOf(K.fonts.family.Inter) end)
	K.face.mono, K.face.monoBold = K.face.medium, K.face.semi
	K.fonts.boot = K.face.medium.Family
end

-- Icons are Tabler (MIT), outline drawn at a fine 1.6 stroke, filled for a
-- few states. Names the features pass from older icon sets map through ALIAS.
local Icons = {
