		plus = "plus", ["refresh-cw"] = "refresh", check = "check", ["volume-2"] = "volume", ["trash-2"] = "trash",
		copy = "copy", clipboard = "clipboard", ["circle-dot"] = "circle-dot", crown = "crown",
		["mouse-scrollwheel"] = "mouse", send = "send", ["play-large"] = "player-play", music = "music",
		["dots-three"] = "dots", ["caret-down"] = "chevron-down", ["magnifying-glass"] = "search",
		["gear-six"] = "settings", trash = "trash", ["arrow-clockwise"] = "refresh", ["external-link"] = "external-link",
		["share-network"] = "share", ["selection-all"] = "select-all", broom = "eraser", knife = "blade",
		["paper-plane-tilt"] = "send", ["chat-circle-dots"] = "message-circle", ["person-simple-run"] = "run",
	},
	-- before the atlas unpacks, or on an executor without getcustomasset
	fallback = {
