}
K.Icons = Icons

function Icons.set(img, name, fill)
	name = Icons.alias[name] or name
	local at = (fill and Icons.at[name .. "@fill"]) or Icons.at[name]
	if K.art.atlas and at then
		img.Image = K.art.atlas
		img.ImageRectOffset = Vector2.new(at[1], at[2])
		img.ImageRectSize = Vector2.new(Icons.cell, Icons.cell)
	else
		local id = Icons.fallback[name]
		img.Image = id and ("rbxassetid://" .. id) or ""
		img.ImageRectOffset = Vector2.zero
		img.ImageRectSize = Vector2.zero
	end
	return img
end

function Icons.has(name)
	name = Icons.alias[name] or name
	return Icons.at[name] ~= nil
end

function K.glyph(parent, name, size, color, props)
	local o = new("ImageLabel", {
		Size = UDim2.fromOffset(size, size),
		BackgroundTransparency = 1,
		ImageColor3 = color or C.icon,
		ScaleType = Enum.ScaleType.Fit,
	}, parent)
	Icons.set(o, name)
	for k, v in pairs(props or {}) do o[k] = v end
	return o
end

-- the soft drop shadow under floating things; `spread` is how far it reaches
function K.shadow(parent, spread, transparency, z)
	if not K.art.shadow then return nil end
	spread = spread or 28
	return new("ImageLabel", {
		Name = "Shadow",
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.new(0.5, 0, 0.5, math.floor(spread * 0.25)),
		Size = UDim2.new(1, spread * 2, 1, spread * 2),
		BackgroundTransparency = 1,
		Image = K.art.shadow,
		ImageColor3 = Color3.new(0, 0, 0),
		ImageTransparency = transparency or 0.3,
		ScaleType = Enum.ScaleType.Slice,
		SliceCenter = Rect.new(64, 64, 96, 96),
		SliceScale = spread / 40,
		ZIndex = z or 0,
	}, parent)
end

-- The mark: a small white tile with a dark "s". The wordmark is the tile and
-- the name beside it.
function K.logo(parent, size, props)
	local tile = new("Frame", {
		Name = "Logo",
		Size = UDim2.fromOffset(size, size),
		BackgroundColor3 = C.accent,
		BorderSizePixel = 0,
	}, parent)
	corner(tile, math.floor(size * 0.3))
	K.text(tile, {
		Name = "Glyph",
		Size = UDim2.fromScale(1, 1),
		Position = UDim2.fromOffset(0, -math.floor(size * 0.04)),
		FontFace = K.face.bold,
		Text = "s",
		TextSize = math.floor(size * 0.78),
		TextColor3 = C.onAccent,
		TextXAlignment = Enum.TextXAlignment.Center,
		TextTruncate = Enum.TextTruncate.None,
		ZIndex = tile.ZIndex,
	})
	for k, v in pairs(props or {}) do tile[k] = v end
	tile:GetPropertyChangedSignal("ZIndex"):Connect(function() tile.Glyph.ZIndex = tile.ZIndex end)
	return tile
end

-- The brand: the SALAD brush mark, as wide as its strokes. Without the
-- picture it falls back to the tile and the name in type.
K.LOGO_ASPECT = 350 / 128
function K.brushmark(parent, height, props)
	local o = new("ImageLabel", {
		Name = "Brush",
		Size = UDim2.fromOffset(math.floor(height * K.LOGO_ASPECT + 0.5), height),
		BackgroundTransparency = 1,
		Image = K.art.logo or "",
		ImageColor3 = Color3.new(1, 1, 1),
		ScaleType = Enum.ScaleType.Fit,
	}, parent)
	for k, v in pairs(props or {}) do o[k] = v end
	return o
end

function K.wordmark(parent, size, props)
	if K.art.logo then return K.brushmark(parent, size + 10, props) end
	local o = new("Frame", {
		Name = "Wordmark",
		Size = UDim2.fromOffset(0, size + 8),
		AutomaticSize = Enum.AutomaticSize.X,
		BackgroundTransparency = 1,
	}, parent)
	new("UIListLayout", {
		FillDirection = Enum.FillDirection.Horizontal,
		VerticalAlignment = Enum.VerticalAlignment.Center,
		SortOrder = Enum.SortOrder.LayoutOrder,
		Padding = UDim.new(0, math.floor(size * 0.55)),
	}, o)
	local tile = K.logo(o, size + 6, { LayoutOrder = 1 })
	local name = K.text(o, {
		Name = "Name",
		LayoutOrder = 2,
		Size = UDim2.fromOffset(0, size + 8),
		AutomaticSize = Enum.AutomaticSize.X,
		FontFace = K.face.semi,
		Text = "salad",
		TextSize = size,
		TextColor3 = C.text,
		TextTruncate = Enum.TextTruncate.None,
	})
	for k, v in pairs(props or {}) do o[k] = v end
	local function z()
		tile.ZIndex = o.ZIndex
		name.ZIndex = o.ZIndex
	end
	o:GetPropertyChangedSignal("ZIndex"):Connect(z)
	z()
	return o
end

