local uiConnections = {}
local function connectUI(signal, callback, owner)
	local connection = signal:Connect(callback)
	uiConnections[connection] = true
	if owner then
		owner.Destroying:Connect(function()
			connection:Disconnect()
			uiConnections[connection] = nil
		end)
	end
	return connection
end
K.uiConnections = uiConnections
gui.Destroying:Connect(function()
	for connection in pairs(uiConnections) do connection:Disconnect() end
	table.clear(uiConnections)
end)

-- one quiet tick for every press; the menu-sound presets in the visuals
-- layer take over through SFX.hook
local SFX
do
	local folder = new("Folder", { Name = "InertiaSounds" }, SoundService)
	env.__InertiaSounds = folder
	local cache = {}
	local function play(id, pitch, volume)
		local key = id .. pitch
		local s = cache[key]
		if not s then
			s = new("Sound", { SoundId = id, PlaybackSpeed = pitch, Volume = volume }, folder)
			cache[key] = s
		end
		if not pcall(SoundService.PlayLocalSound, SoundService, s) then s:Play() end
	end
	local TICK = "rbxassetid://6895079853"
	SFX = {
		click = function() if SFX.hook then SFX.hook(true) else play(TICK, 1.15, 0.16) end end,
		on = function() if SFX.hook then SFX.hook(true) else play(TICK, 1.4, 0.22) end end,
		off = function() if SFX.hook then SFX.hook(false) else play(TICK, 0.9, 0.16) end end,
		ready = function() play("rbxassetid://4590662766", 1.5, 0.35) end,
		play = play,
	}
end

-- how big the menu draws: a PC follows the screen (and the saved choice), a
-- phone fits the window into the screen
local baseScale
local followScale = {}
K.view = function()
	return env.SALAD_FAKE_VIEWPORT or workspace.CurrentCamera.ViewportSize
end
do
	local view = K.view()
	if MOBILE then
		baseScale = math.clamp(view.Y / 410, 0.62, 1)
		K.autoScale = baseScale
	else
		baseScale = math.clamp(math.min(view.X / 1920, view.Y / 1080) * 1.02, 0.78, 1.15)
		K.autoScale = baseScale
		pcall(function()
			local saved = tonumber(readfile(ROOT .. "/scale.txt"))
			if saved then baseScale = math.clamp(saved, 0.7, 1.3) end
		end)
	end
end

-- the world behind the open menu: darker, and blurred if asked
local glass = { blur = 12, dim = 0.35, blurEnabled = false }
do
	local old = env.__InertiaMenuBlur
	if old then pcall(function() old:Destroy() end) end
	glass.fx = Instance.new("BlurEffect")
	glass.fx.Name = "SaladMenuBlur"
	glass.fx.Size = 0
	glass.fx.Enabled = false
	glass.fx.Parent = workspace.CurrentCamera
	env.__InertiaMenuBlur = glass.fx
	connectUI(workspace:GetPropertyChangedSignal("CurrentCamera"), function()
		if glass.fx then glass.fx.Parent = workspace.CurrentCamera end
	end)
	glass.shade = new("Frame", {
		Name = "Shade",
		Size = UDim2.fromScale(1, 1),
		BackgroundColor3 = Color3.new(0, 0, 0),
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Visible = false,
	}, gui)
	glass.open = false
	function glass.apply(animate)
		local blurred = glass.open and glass.blurEnabled and glass.blur > 0
		local blurSize = blurred and glass.blur or 0
		if blurred then glass.fx.Enabled = true end
		if animate and glass.fx.Size ~= blurSize then
			local fade = tween(glass.fx, 0.35, { Size = blurSize }, K.ease.out)
			if not blurred then
				fade.Completed:Connect(function() if not (glass.open and glass.blurEnabled) then glass.fx.Enabled = false end end)
			end
		else
			local active = running[glass.fx]
			if active and active.Size then active.Size:Cancel() end
			glass.fx.Size = blurSize
			glass.fx.Enabled = blurred
		end
		local target = glass.open and (1 - glass.dim) or 1
		if animate and (target < 1 or glass.shade.Visible) then
			glass.shade.Visible = true
			local fade = tween(glass.shade, glass.open and 0.35 or 0.2, { BackgroundTransparency = target }, K.ease.out)
			if target == 1 then
				fade.Completed:Connect(function(state)
					if state == Enum.PlaybackState.Completed and not glass.open then glass.shade.Visible = false end
				end)
			end
		else
			local active = running[glass.shade]
			if active and active.BackgroundTransparency then active.BackgroundTransparency:Cancel() end
			glass.shade.BackgroundTransparency = target
			glass.shade.Visible = target < 1
		end
	end
end
K.glass = glass
gui.Destroying:Connect(function() glass.fx:Destroy() end)

-- The window. `root` is what the features watch: Visible means "the menu is
-- open", and their Drawing objects hide while it is.
local root = new("Frame", {
	Name = "Window",
	AnchorPoint = Vector2.new(0.5, 0.5),
	Position = UDim2.fromScale(0.5, 0.5),
	Size = UDim2.fromOffset(K.L.W, K.L.H),
	BackgroundTransparency = 1,
	Visible = false,
	ZIndex = 2,
}, gui)
local scaler = new("UIScale", { Scale = baseScale }, root)

-- Drawings (the ESP's boxes, names, lines) keep drawing while the menu is
-- open, but never over it: last thing every frame, any drawing that lands on
-- the window, a floating panel, the watermark or the hotkeys is hidden. The
-- renderers set their pieces again each frame, so they come back the moment
-- the menu is out of the way.
local Drawing = { source = Drawing, live = setmetatable({}, { __mode = "k" }), want = setmetatable({}, { __mode = "k" }) }
function Drawing.new(kind)
	local raw = Drawing.source.new(kind)
	local proxy = {}
	Drawing.want[proxy] = raw.Visible
	local function remove()
		Drawing.live[proxy] = nil
		local ok = pcall(function() raw:Destroy() end)
		if not ok then pcall(function() raw:Remove() end) end
	end
	setmetatable(proxy, {
		__index = function(_, key)
			if key == "Visible" then return Drawing.want[proxy] end
			if key == "Destroy" or key == "Remove" then return remove end
			return raw[key]
		end,
		__newindex = function(_, key, value)
			if key == "Visible" then
				Drawing.want[proxy] = value
				raw.Visible = value
			else
				raw[key] = value
			end
		end,
	})
	Drawing.live[proxy] = { raw = raw, kind = kind }
	return proxy
end
do
	local function inside(p, r)
		return p.X >= r[1] and p.X <= r[3] and p.Y >= r[2] and p.Y <= r[4]
	end
	local function covered(raw, kind, r)
		if kind == "Line" then
			local a, b = raw.From, raw.To
			return inside(a, r) or inside(b, r) or inside((a + b) / 2, r)
		elseif kind == "Square" or kind == "Image" then
			local at, size = raw.Position, raw.Size
			return at.X < r[3] and at.X + size.X > r[1] and at.Y < r[4] and at.Y + size.Y > r[2]
		elseif kind == "Triangle" then
			return inside(raw.PointA, r) or inside(raw.PointB, r) or inside(raw.PointC, r)
		elseif kind == "Quad" then
			return inside(raw.PointA, r) or inside(raw.PointB, r) or inside(raw.PointC, r) or inside(raw.PointD, r)
		end
		return inside(raw.Position, r)
	end
	-- screen rectangles of whatever menu pieces are showing, in the space the
	-- drawings use (the whole screen, top bar included)
	local function rects()
		local list = {}
		local origin = gui.AbsolutePosition
		local function add(o)
			if not (o and o.Parent and o.Visible) then return end
			local at, size = o.AbsolutePosition - origin, o.AbsoluteSize
			list[#list + 1] = { at.X - 2, at.Y - 2, at.X + size.X + 2, at.Y + size.Y + 2 }
		end
		if root.Visible then add(root) end
		for _, o in ipairs(K.layer:GetChildren()) do
			if o:IsA("GuiObject") then add(o) end
		end
		for _, name in ipairs({ "SaladWatermark", "SaladKeybinds" }) do
			local o = gui:FindFirstChild(name)
			if o and o.GroupTransparency < 0.95 then add(o) end
		end
		return list
	end
	-- connected before any feature: RenderStepped runs the newest handler
	-- first, so this one has the last word every frame
	connectUI(game:GetService("RunService").RenderStepped, function()
		local list = rects()
		for proxy, entry in pairs(Drawing.live) do
			if Drawing.want[proxy] then
				local raw, hide = entry.raw, false
				for _, r in ipairs(list) do
					local ok, hit = pcall(covered, raw, entry.kind, r)
					if ok and hit then hide = true break end
				end
				if raw.Visible == hide then raw.Visible = not hide end
			end
		end
	end)
end

-- where things wait while nobody looks: hidden pages and the bodies of closed
-- option sheets. Outside the window, so dragging it moves only what shows.
K.attic = new("Frame", { Name = "Attic", Visible = false, Size = UDim2.fromOffset(K.L.W, K.L.H) }, gui)

-- floating things (lists, the colour picker, menus, dialogs) live on this
-- layer in screen space, scaled like the window
K.layer = new("Frame", {
	Name = "Layer",
	Size = UDim2.fromScale(1, 1),
	BackgroundTransparency = 1,
	ZIndex = 50,
}, gui)
K.layerScale = new("UIScale", { Scale = baseScale }, K.layer)
local function syncLayer()
	K.layerScale.Scale = scaler.Scale
	K.layer.Size = UDim2.fromScale(1 / scaler.Scale, 1 / scaler.Scale)
end
connectUI(scaler:GetPropertyChangedSignal("Scale"), syncLayer)
syncLayer()

-- GUI-space pixels (the space AbsolutePosition lives in) -> layer units
function K.toLayer(p)
	return (Vector2.new(p.X, p.Y) - K.layer.AbsolutePosition) / scaler.Scale
end

function K.inside(o, p)
	if not (o and o.Parent) then return false end
	local a, s = o.AbsolutePosition, o.AbsoluteSize
	return p.X >= a.X and p.X <= a.X + s.X and p.Y >= a.Y and p.Y <= a.Y + s.Y
end

-- The pointer in AbsolutePosition's space. GetMouseLocation counts from the
-- very top of the screen; GUI space starts under Roblox's top bar, and an
-- input's own Position is already in GUI space.
function K.pointer(input)
	if input and (input.UserInputType == Enum.UserInputType.Touch
		or input.UserInputType == Enum.UserInputType.MouseButton1
		or input.UserInputType == Enum.UserInputType.MouseButton2
		or input.UserInputType == Enum.UserInputType.MouseMovement) then
		return Vector2.new(input.Position.X, input.Position.Y)
	end
	return UIS:GetMouseLocation() - game:GetService("GuiService"):GetGuiInset()
end

function K.isPress(input)
	return input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch
end

-- the height of Roblox's own top bar: anything pinned to the top sits under it
function K.topInset()
	local ok, inset = pcall(function() return game:GetService("GuiService"):GetGuiInset() end)
	return ok and inset.Y or 36
end

-- A shadow for something that sizes itself (AutomaticSize, a list layout):
-- a scale-sized child would feed its size back, so this follows as a sibling.
function K.trailShadow(target, spread, transparency)
	if not K.art.shadow then return nil end
	local shadow = new("ImageLabel", {
		Name = "Shadow",
		BackgroundTransparency = 1,
		Image = K.art.shadow,
		ImageColor3 = Color3.new(0, 0, 0),
		ImageTransparency = transparency or 0.45,
		ScaleType = Enum.ScaleType.Slice,
		SliceCenter = Rect.new(64, 64, 96, 96),
		ZIndex = math.max(target.ZIndex - 1, 0),
	}, target.Parent)
	local function follow()
		local parent = target.Parent
		if not parent then return end
		local origin = (parent:IsA("GuiObject") or parent:IsA("LayerCollector")) and parent.AbsolutePosition or Vector2.zero
		local scale = target:FindFirstChildOfClass("UIScale")
		local px = spread * (scale and scale.Scale or 1)
		shadow.Position = UDim2.fromOffset(target.AbsolutePosition.X - origin.X - px, target.AbsolutePosition.Y - origin.Y - px * 0.8)
		shadow.Size = UDim2.fromOffset(target.AbsoluteSize.X + px * 2, target.AbsoluteSize.Y + px * 2)
		shadow.SliceScale = px / 40
		shadow.Visible = target.Visible
	end
	target:GetPropertyChangedSignal("AbsolutePosition"):Connect(follow)
	target:GetPropertyChangedSignal("AbsoluteSize"):Connect(follow)
	target:GetPropertyChangedSignal("Visible"):Connect(follow)
	target.Destroying:Connect(function() shadow:Destroy() end)
	task.defer(follow)
	return shadow
end

-- press feel: the thing dips a hair and springs back
function K.press(hit, target)
	local scale = new("UIScale", { Scale = 1 }, target or hit)
	hit.MouseButton1Down:Connect(function() tween(scale, 0.08, { Scale = 0.96 }) end)
	hit.MouseButton1Up:Connect(function() tween(scale, 0.3, { Scale = 1 }, K.ease.spring) end)
	hit.MouseLeave:Connect(function() tween(scale, 0.2, { Scale = 1 }) end)
	return scale
end

-- a plain icon button: no fill until the pointer comes
function K.iconButton(parent, name, size, props)
	size = size or 30
	local b = new("ImageButton", {
		Size = UDim2.fromOffset(size, size),
		BackgroundColor3 = C.hover,
		BackgroundTransparency = 1,
		AutoButtonColor = false,
		Image = "",
		ZIndex = 6,
	}, parent)
	corner(b, math.floor(size * 0.3))
	local ic = K.glyph(b, name, math.floor(size * 0.55), C.sub, {
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		ZIndex = 7,
	})
	for k, v in pairs(props or {}) do b[k] = v end
	b.MouseEnter:Connect(function()
		tween(b, 0.15, { BackgroundTransparency = 0 })
		tween(ic, 0.15, { ImageColor3 = C.text })
	end)
	b.MouseLeave:Connect(function()
		tween(b, 0.2, { BackgroundTransparency = 1 })
		tween(ic, 0.2, { ImageColor3 = b:GetAttribute("Lit") and C.text or C.sub })
	end)
	K.press(b, ic)
	return b, ic
end

-- ====================================================================== 10_window.lua
-- ------------------------------------------------------------------ window --
-- root > shell (a UIScale + offset for the open motion) > main. While the
-- window opens or closes, main rides inside a CanvasGroup so it fades as one
-- piece; the rest of the time it sits straight in the shell, where text stays
-- crisp. main: top bar, page tabs, content (and the dock on a phone).
local L = K.L
K.RS = game:GetService("RunService")
K.shell = new("Frame", { Name = "Shell", Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1 }, root)
K.pop = new("UIScale", { Scale = 1 }, K.shell)
K.windowShadow = K.shadow(K.shell, 50, 0.2, 0)
pcall(function()
	K.fade = new("CanvasGroup", {
		Name = "Fade",
		Size = UDim2.fromScale(1, 1),
		BackgroundTransparency = 1,
		Visible = false,
		ZIndex = 1,
	}, K.shell)
end)

local main = new("Frame", {
	Name = "Main",
	Size = UDim2.fromScale(1, 1),
	BackgroundColor3 = C.window,
	BackgroundTransparency = 0,
	BorderSizePixel = 0,
	Active = true,
	ClipsDescendants = true,
	ZIndex = 1,
}, K.shell)
corner(main, L.RADIUS)
K.mainEdge = stroke(main, C.border, 0)
K.sheen(main, 0.84)
K.main = main

-- the backdrop under the pages: a faint light falling from the top edge and
-- two soft lights drifting slowly, clipped to the window's round corners
do
	local ok, back = pcall(new, "CanvasGroup", {
		Name = "Backdrop", Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, ZIndex = 0,
	}, main)
	if ok then
		corner(back, L.RADIUS)
	else
		back = new("Frame", { Name = "Backdrop", Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, ZIndex = 0 }, main)
	end
	local fall = new("Frame", {
		Size = UDim2.new(1, 0, 0, 240), BackgroundColor3 = C.text, BackgroundTransparency = 0.95, BorderSizePixel = 0,
	}, back)
	new("UIGradient", { Rotation = 90, Transparency = NumberSequence.new(0, 1) }, fall)
	local lights = {}
	if K.art.glow then
		for i, at in ipairs({ { 0.15, 0.05, 0.9, 0.9 }, { 0.88, 0.95, 0.75, 0.93 } }) do
			lights[i] = { at = at, img = new("ImageLabel", {
				AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(at[1], at[2]),
				Size = UDim2.fromScale(at[3], at[3]), SizeConstraint = Enum.SizeConstraint.RelativeXX,
				BackgroundTransparency = 1, Image = K.art.glow, ImageColor3 = C.text, ImageTransparency = at[4],
			}, back) }
		end
	end
	connectUI(K.RS.RenderStepped, function()
		if not root.Visible then return end
		local t = os.clock()
		for i, light in ipairs(lights) do
			local at = light.at
			light.img.Position = UDim2.fromScale(at[1] + 0.07 * math.sin(t * 0.13 + i * 2.1), at[2] + 0.06 * math.cos(t * 0.1 + i))
		end
	end, back)
end

