-- --------------------------------------------------------------- scrolling --
-- On a PC pages glide: the wheel moves a target and every frame closes part
-- of the gap. The smallest list under the pointer that can still scroll gets
-- the notch and keeps it, no handing over to the page behind. Phones scroll
-- natively.
K.scrollers = setmetatable({}, { __mode = "k" })
K.scrollMotion = setmetatable({}, { __mode = "k" })
K.wheelBlockers = setmetatable({}, { __mode = "k" })
K.frontPanels = setmetatable({}, { __mode = "k" })
function K.frontAt(pointer)
	for panel in pairs(K.frontPanels) do
		if K.inside(panel, pointer) then
			local parent, visible = panel, true
			while parent do
				if parent:IsA("GuiObject") and not parent.Visible then visible = false; break end
				if parent:IsA("ScreenGui") then visible = parent.Enabled; break end
				parent = parent.Parent
			end
			if visible then return true end
		end
	end
	return false
end
function K.scroller(sf)
	sf.ScrollBarImageColor3 = C.chip
	if MOBILE then
		sf.ScrollingEnabled = true
		sf.ElasticBehavior = Enum.ElasticBehavior.WhenScrollable
		return sf
	end
	sf.ScrollingEnabled = false
	sf.ScrollBarImageTransparency = 1
	K.scrollers[sf] = { target = sf.CanvasPosition.Y, shown = 0 }
	return sf
end

do
	-- CanvasPosition is in the window's own units; Absolute* sizes are screen
	-- pixels, scaled by every UIScale above (menu size, the open/close pop).
	-- Mixed, a smaller menu never reached the bottom and a bigger one aimed
	-- past it and never settled, so the wheel went dead for a moment.
	local function unit(sf)
		local s, o = 1, sf
		while o and o ~= gui do
			local u = o:FindFirstChildOfClass("UIScale")
			if u then s *= u.Scale end
			o = o.Parent
		end
		return math.max(s, 0.01)
	end
	local function room(sf)
		return math.max(sf.AbsoluteCanvasSize.Y - sf.AbsoluteWindowSize.Y, 0) / unit(sf)
	end
	local function onScreen(sf, pointer)
		if not sf.Parent or sf:IsDescendantOf(K.attic) then return false end
		local o = sf
		while o and o ~= gui do
			if o:IsA("GuiObject") and not o.Visible then return false end
			if pointer and o:IsA("GuiObject") and o.ClipsDescendants and not K.inside(o, pointer) then return false end
			o = o.Parent
		end
		return o == gui
	end
	connectUI(UIS.InputChanged, function(input)
		if input.UserInputType ~= Enum.UserInputType.MouseWheel or not root.Visible then return end
		local p = K.pointer()
		if K.frontAt(p) then return end
		local surface, z
		for _, panel in ipairs(K.layer:GetChildren()) do
			if panel:IsA("GuiObject") and panel.Visible and K.inside(panel, p) and (not z or panel.ZIndex > z) then
				surface, z = panel, panel.ZIndex
			end
		end
		if not surface and K.sheetFrame and K.sheetFrame.Visible then
			if not K.inside(K.sheetFrame, p) then return end
			surface = K.sheetFrame
		end
		if not surface then
			for widget in pairs(K.wheelBlockers) do
				if K.inside(widget, p) and onScreen(widget, p) then return end
			end
		end
		-- the innermost list under the pointer takes the notch; one already at
		-- its end (and not still gliding) hands it to the list behind it, so a
		-- gallery at its bottom no longer pins the page
		local lists = {}
		for sf in pairs(K.scrollers) do
			if K.inside(sf, p) and onScreen(sf, p) and (not surface or sf:IsDescendantOf(surface)) and room(sf) > 0 then
				lists[#lists + 1] = sf
			end
		end
		table.sort(lists, function(a, b) return a.AbsoluteSize.X * a.AbsoluteSize.Y < b.AbsoluteSize.X * b.AbsoluteSize.Y end)
		local down = input.Position.Z < 0
		local best
		for _, sf in ipairs(lists) do
			local at, gliding = sf.CanvasPosition.Y, K.scrollMotion[sf] ~= nil
			if gliding or (down and at < room(sf) - 0.5) or (not down and at > 0.5) then best = sf; break end
		end
		if not best then return end
		local state = K.scrollers[best]
		local step = math.max(56, best.AbsoluteWindowSize.Y / unit(best) * 0.2)
		local current = best.CanvasPosition.Y
		if not K.scrollMotion[best] or math.abs(state.target - current) > step * 4 then state.target = current end
		state.target = math.clamp(state.target - input.Position.Z * step, 0, room(best))
		state.shown = os.clock()
		K.scrollMotion[best] = state
	end)
	connectUI(K.RS.RenderStepped, function(dt)
		LPH_ATTRIBUTES(VM(NONE))
		if not root.Visible then return end
		local clock, glide, fade = os.clock(), 1 - math.exp(-dt * 15), 1 - math.exp(-dt * 10)
		for sf, state in pairs(K.scrollMotion) do
			if sf.Parent then
				if not onScreen(sf) then continue end
				local max = room(sf)
				if state.target > max then state.target = max end
				local y = sf.CanvasPosition.Y
				local gap = state.target - y
				if math.abs(gap) > 0.5 then
					sf.CanvasPosition = Vector2.new(sf.CanvasPosition.X, y + gap * glide)
				elseif gap ~= 0 then
					sf.CanvasPosition = Vector2.new(sf.CanvasPosition.X, state.target)
				end
				local want = (clock - state.shown < 0.9 and max > 0) and 0.4 or 1
				local now = sf.ScrollBarImageTransparency
				if math.abs(now - want) > 0.01 then
					sf.ScrollBarImageTransparency = now + (want - now) * fade
				elseif want == 1 and math.abs(gap) <= 0.5 then
					K.scrollMotion[sf] = nil
				end
			else
				K.scrollers[sf] = nil
				K.scrollMotion[sf] = nil
			end
		end
	end)
	function K.scrollTo(sf, y, instant)
		local state = K.scrollers[sf]
		if not state then
			sf.CanvasPosition = Vector2.new(0, y)
			return
		end
		state.target = math.clamp(y, 0, room(sf))
		state.shown = os.clock()
		K.scrollMotion[sf] = state
		if instant then sf.CanvasPosition = Vector2.new(0, state.target) end
	end
end

-- ------------------------------------------------------------- categories --
local TABS = {
	{ name = "Combat", icon = "crosshair", subs = { "Main" } },
	{ name = "Visuals", icon = "eye", subs = { "Players", "World", "Effects" } },
	{ name = "Player", icon = "run", subs = { "Main" } },
	{ name = "Style", icon = "shirt", subs = { "Auras", "Trails", "Cosmetics", "Skins", "Avatar", "Animations" } },
	{ name = "Misc", icon = "layout-grid", subs = { "Tools", "Servers", "Music" } },
	{ name = "Chat", icon = "message-circle", subs = { "Room" }, aside = true },
	{ name = "Favorites", icon = "star", subs = { "Saved" }, aside = true },
	-- the menu's own settings: the gear opens them
	{ name = "Settings", icon = "settings", subs = { "Menu", "Theme" }, aside = true },
}

local tabs, current = {}, nil
local registry, bindables = {}, {}
local galleryByPath = {}
local refreshKeyList, rebuildFavs
K.searchIndex = {}
K.binds = {}
K.current = function() return current end
local notify

function K.releaseHold(control)
	if not control.held then return end
	control.held = false
	local item = registry[control.path]
	if item then item.set(false) end
end

function K.assignBind(control, keyName)
	K.releaseHold(control)
	control.listening = false
	if control.bindKey then K.binds[control.bindKey] = nil end
	control.bindKey = keyName
	if keyName then
		local previous = K.binds[keyName]
		if previous and previous ~= control then
			K.releaseHold(previous)
			previous.bindKey = nil
			if previous.paintBind then previous.paintBind() end
		end
		K.binds[keyName] = control
	end
	if control.paintBind then control.paintBind() end
	if refreshKeyList then refreshKeyList() end
end

local function paintTab(tab, hovered)
	local on = tab == current
	if tab.label then
		tween(tab.label, 0.2, { TextColor3 = on and C.text or (hovered and C.value or C.sub) })
	end
	if tab.utility then
		tab.utility:SetAttribute("Lit", on)
		local ic = tab.utility:FindFirstChildOfClass("ImageLabel")
		if ic then
			K.Icons.set(ic, tab.iconName, on)
			tween(ic, 0.2, { ImageColor3 = on and C.text or C.sub })
		end
	end
	if tab.pill then
		local s = tab.pill
		tween(s.bg, 0.3, { BackgroundTransparency = on and 0 or 1 }, K.ease.out)
		tween(s.icon, 0.3, { ImageColor3 = on and C.onAccent or (hovered and C.text or C.sub) })
		K.Icons.set(s.icon, tab.iconName, on)
		tween(s.name, 0.3, { TextTransparency = on and 0 or 1 })
		tween(s.button, 0.38, { Size = UDim2.fromOffset(on and (50 + s.name.TextBounds.X / math.max(scaler.Scale, 0.01)) or 42, 38) }, K.ease.out)
	end
end

-- the pill under the open category
function K.markTab(tab, instant)
	local pill = K.catPill
	if MOBILE or not tab.label then
		pill.Visible = false
		return
	end
	pill.Visible = true
	local s = math.max(scaler.Scale * K.pop.Scale, 0.01)
	local b = tab.button
	local x = (b.AbsolutePosition.X - K.top.AbsolutePosition.X) / s
	local pos, size = UDim2.new(0, x, 0.5, 0), UDim2.fromOffset(b.AbsoluteSize.X / s, 32)
	if instant or pill.Size.X.Offset < 1 then
		pill.Position, pill.Size = pos, size
	else
		tween(pill, 0.42, { Position = pos, Size = size }, K.ease.out)
	end
end

-- the page swap: the new page drifts in from the side it lies on
function K.showPage(page, instant, dx)
	local veil = K.pageVeil
	local active = running[veil]
	if active and active.BackgroundTransparency then active.BackgroundTransparency:Cancel() end
	page.Parent = K.content
	page.Visible = true
	if instant then
		page.Position = UDim2.new()
		veil.Visible = false
		return
	end
	page.Position = UDim2.fromOffset(dx or 0, 0)
	tween(page, 0.42, { Position = UDim2.new() }, K.ease.out)
	veil.BackgroundTransparency = 0
	veil.Visible = true
	tween(veil, 0.3, { BackgroundTransparency = 1 }, K.ease.out).Completed:Connect(function(state)
		if state == Enum.PlaybackState.Completed then veil.Visible = false end
	end)
	if K.stagger then K.stagger(page) end
end

function K.hidePage(page)
	page.Visible = false
	page.Parent = K.attic
end

-- the page area starts lower when a category has pages to pick from
function K.layoutContent(tab, instant)
	local pages = #tab.subs > 1
	local top = L.TOP + (pages and L.SUB or 0)
	K.subbar.Visible = pages
	local goalPos = UDim2.fromOffset(0, top)
	local goalSize = UDim2.new(1, 0, 1, -top - L.DOCK)
	local rulePos = UDim2.fromOffset(0, top - 1)
	if instant then
		K.content.Position, K.content.Size = goalPos, goalSize
		K.headRule.Position = rulePos
	else
		tween(K.content, 0.35, { Position = goalPos, Size = goalSize }, K.ease.out)
		tween(K.headRule, 0.35, { Position = rulePos }, K.ease.out)
	end
end

-- the page words are rebuilt for each category
K.trayButtons = {}
function K.buildTray(tab)
	for _, b in ipairs(K.trayButtons) do b:Destroy() end
	table.clear(K.trayButtons)
	if #tab.subs <= 1 then return end
	for index, sub in ipairs(tab.subs) do
		local b = new("TextButton", {
			LayoutOrder = index,
			Size = UDim2.fromOffset(0, K.SEG),
			AutomaticSize = Enum.AutomaticSize.X,
			BackgroundTransparency = 1,
			AutoButtonColor = false,
			FontFace = K.face.semi,
			Text = sub.name,
			TextSize = 12,
			TextColor3 = (tab.active == index) and C.text or C.sub,
			ZIndex = 6,
		}, K.trayList)
		pad(b, 0, 0, 14, 14)
		b.MouseEnter:Connect(function()
			if tab.active ~= index then tween(b, 0.15, { TextColor3 = C.value }) end
		end)
		b.MouseLeave:Connect(function()
			tween(b, 0.2, { TextColor3 = tab.active == index and C.text or C.sub })
		end)
		b.MouseButton1Click:Connect(function() K.selectSub(tab, index) end)
		b:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
			if current == tab and tab.active == index then K.markSub(tab, true) end
		end)
		sub.tabButton = b
		K.trayButtons[#K.trayButtons + 1] = b
	end
end

function K.markSub(tab, instant)
	LPH_ATTRIBUTES(VM(NONE))
	local sub = tab.subs[tab.active or 1]
	local b = sub and sub.tabButton
	if not (b and b.Parent) then return end
	for index, other in ipairs(tab.subs) do
		if other.tabButton then
			local color = index == tab.active and C.text or C.sub
			if other.inkTarget ~= color then
				other.inkTarget = color
				if other.tabButton.TextColor3 ~= color then tween(other.tabButton, 0.2, { TextColor3 = color }) end
			end
		end
	end
	task.defer(function()
		if not b.Parent then return end
		local s = math.max(scaler.Scale * K.pop.Scale, 0.01)
		local x = (b.AbsolutePosition.X - K.tray.AbsolutePosition.X) / s + K.tray.CanvasPosition.X / s
		local pos, size = UDim2.new(0, x, 0.5, 0), UDim2.fromOffset(b.AbsoluteSize.X / s, K.SEG)
		if instant or K.traySlide.Size.X.Offset < 1 then
			K.traySlide.Position, K.traySlide.Size = pos, size
		else
			tween(K.traySlide, 0.38, { Position = pos, Size = size }, K.ease.out)
		end
	end)
end

function K.selectSub(tab, index, instant, animatePage)
	if tab.active == index and not instant then return end
	local previous = tab.active or index
	tab.active = index
	for i, sub in ipairs(tab.subs) do
		if i ~= index and sub.page.Parent ~= K.attic then K.hidePage(sub.page) end
	end
	if tab == current then
		local skip = instant and not animatePage
		K.showPage(tab.subs[index].page, skip, index >= previous and 18 or -18)
		if K.reflow then K.reflow(tab.subs[index]) end
		K.markSub(tab, skip)
		if not skip then SFX.click() end
	end
	if K.closeAll then K.closeAll() end
end

local function selectTab(tab, instant, subIndex)
	if current == tab then
		if subIndex then K.selectSub(tab, subIndex, instant) end
		return
	end
	if tab.name == "Favorites" and rebuildFavs then pcall(rebuildFavs) end
	local before = current
	if before and before.onClose then pcall(before.onClose) end
	current = tab
	for _, other in ipairs(tabs) do
		paintTab(other, false)
		if other ~= tab then
			for _, sub in ipairs(other.subs) do
				if sub.page.Parent ~= K.attic then K.hidePage(sub.page) end
			end
		end
	end
	K.buildTray(tab)
	K.traySlide.Size = UDim2.fromOffset(0, K.SEG)
	K.layoutContent(tab, instant or before == nil)
	K.markTab(tab, instant)
	local dir = before and ((tab.order or 0) >= (before.order or 0) and 26 or -26) or 0
	tab.active = tab.active or 1
	local index = subIndex or tab.active
	tab.active = nil
	K.selectSub(tab, index, true, not instant)
	if not instant and dir ~= 0 then
		local page = tab.subs[index].page
		page.Position = UDim2.fromOffset(dir, 0)
		tween(page, 0.45, { Position = UDim2.new() }, K.ease.out)
	end
	if tab.onOpen then pcall(tab.onOpen) end
end

for index, data in ipairs(TABS) do
	local tab = { name = data.name, subs = {}, iconName = data.icon, order = index }
	-- on a phone the gear in the top bar opens Settings, so the dock skips it
	if MOBILE and data.name ~= "Settings" then
		local b = new("TextButton", {
			LayoutOrder = index,
			Size = UDim2.fromOffset(42, 38),
			BackgroundTransparency = 1,
			AutoButtonColor = false,
			Text = "",
			ClipsDescendants = true,
			ZIndex = 41,
		}, K.dockList)
		local bg = new("Frame", {
			Size = UDim2.fromScale(1, 1),
			BackgroundColor3 = C.accent,
			BackgroundTransparency = 1,
			BorderSizePixel = 0,
			ZIndex = 41,
		}, b)
		corner(bg, "full")
		local icon = K.glyph(b, data.icon, 19, C.sub, {
			AnchorPoint = Vector2.new(0, 0.5),
			Position = UDim2.new(0, 11, 0.5, 0),
			ZIndex = 42,
		})
		local name = K.text(b, {
			Position = UDim2.fromOffset(37, 0),
			Size = UDim2.new(0, 0, 1, 0),
			AutomaticSize = Enum.AutomaticSize.X,
			FontFace = K.face.semi,
			Text = data.name,
			TextSize = 12,
			TextColor3 = C.onAccent,
			TextTransparency = 1,
			TextTruncate = Enum.TextTruncate.None,
			ZIndex = 42,
		})
		tab.pill = { button = b, bg = bg, icon = icon, name = name }
		tab.button = b
		if data.name == "Chat" then tab.unread = K.dot(b) end
		b.MouseButton1Click:Connect(function()
			if current ~= tab then selectTab(tab); SFX.click() end
		end)
	elseif data.aside then
		-- Chat, Favorites and Settings sit with the tools on the right
		tab.utility = ({ Chat = K.chatButton, Favorites = K.favButton, Settings = K.settingsButton })[data.name]
		tab.button = tab.utility
		if data.name == "Chat" then tab.unread = K.dot(tab.utility) end
		tab.utility.MouseButton1Click:Connect(function()
			if current ~= tab then selectTab(tab); SFX.click() end
		end)
	else
		local b = new("TextButton", {
			LayoutOrder = index,
			Size = UDim2.new(0, 0, 1, 0),
			AutomaticSize = Enum.AutomaticSize.X,
			BackgroundTransparency = 1,
			AutoButtonColor = false,
			Text = "",
			ZIndex = 7,
		}, K.cats)
		pad(b, 0, 0, 14, 14)
		tab.label = K.text(b, {
			Size = UDim2.new(0, 0, 1, 0),
			AutomaticSize = Enum.AutomaticSize.X,
			Text = data.name,
			TextSize = 13,
			TextColor3 = C.sub,
			TextTruncate = Enum.TextTruncate.None,
			ZIndex = 7,
		})
		tab.button = b
		-- a font that loads late or changes moves the words: the pill follows
		b:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
			if current == tab then K.markTab(tab, true) end
		end)
		b:GetPropertyChangedSignal("AbsolutePosition"):Connect(function()
			if current == tab then K.markTab(tab, true) end
		end)
		b.MouseEnter:Connect(function() paintTab(tab, true) end)
		b.MouseLeave:Connect(function() paintTab(tab, false) end)
		b.MouseButton1Click:Connect(function()
			if current ~= tab then selectTab(tab); SFX.click() end
		end)
	end
	for subIndex, subName in ipairs(data.subs) do
		local page = new("Frame", {
			Name = data.name .. "/" .. subName,
			Size = UDim2.fromScale(1, 1),
			BackgroundTransparency = 1,
			Visible = false,
		}, K.attic)
		tab.subs[subIndex] = { name = subName, page = page, columns = {}, cards = {} }
		K.searchIndex[#K.searchIndex + 1] = { label = subName, where = data.name, tab = tab, sub = subIndex }
	end
	tabs[index] = tab
end

K.jump = function(tabName, subName)
	for _, t in ipairs(tabs) do
		if t.name == tabName then
			for i, sub in ipairs(t.subs) do
				if sub.name == subName or subName == nil then
					selectTab(t, false, i)
					return
				end
			end
		end
	end
end


-- once Inter has loaded, the words have their real widths: line the
-- markers up again
task.spawn(function()
	pcall(function()
		local params = Instance.new("GetTextBoundsParams")
		params.Text = "Visuals"
		params.Font = K.face.medium
		params.Size = 13
		game:GetService("TextService"):GetTextBoundsAsync(params)
	end)
	task.wait(0.1)
	if current then
		K.markTab(current, true)
		K.markSub(current, true)
	end
end)

-- ---------------------------------------------------------- moving around --
function K.clampRoot()
	local viewport = K.view()
	local halfW = root.AbsoluteSize.X / 2
	local halfH = root.AbsoluteSize.Y / 2
	local minX, maxX = halfW + 8, viewport.X - halfW - 8
	local minY, maxY = halfH + 8, viewport.Y - halfH - 8
	if minX > maxX then minX, maxX = viewport.X / 2, viewport.X / 2 end
	if minY > maxY then minY, maxY = viewport.Y / 2, viewport.Y / 2 end
	local x = root.Position.X.Scale * viewport.X + root.Position.X.Offset
	local y = root.Position.Y.Scale * viewport.Y + root.Position.Y.Offset
	root.Position += UDim2.fromOffset(math.clamp(x, minX, maxX) - x, math.clamp(y, minY, maxY) - y)
end

K.desired = Vector2.new(L.W, L.H)
function K.fitRoot()
	local viewport = K.view()
	local s = scaler.Scale
	if MOBILE then
		root.Size = UDim2.fromOffset(math.floor((viewport.X - 20) / s), math.floor((viewport.Y - 16) / s))
		root.Position = UDim2.fromScale(0.5, 0.5)
		return
	end
	local maxW = math.max(L.MINW, math.floor((viewport.X - 40) / s))
	local maxH = math.max(L.MINH, math.floor((viewport.Y - 60) / s))
	root.Size = UDim2.fromOffset(math.clamp(K.desired.X, L.MINW, maxW), math.clamp(K.desired.Y, L.MINH, maxH))
	K.clampRoot()
end

function K.setMenuScale(v)
	local viewport = K.view()
	baseScale = math.max(0.4, math.min(v, (viewport.X - 40) / L.MINW, (viewport.Y - 60) / L.MINH))
	scaler.Scale = baseScale
	K.fitRoot()
	for _, o in ipairs(followScale) do o.Scale = baseScale * (o:GetAttribute("Follow") or 0.92) end
	pcall(writefile, ROOT .. "/scale.txt", tostring(baseScale))
end

do
	local dragging, start, origin
	connectUI(UIS.InputBegan, function(input)
		if not K.isPress(input) or not root.Visible or UIS:GetFocusedTextBox() then return end
		local p = K.pointer(input)
		if K.frontAt(p) then return end
		if not K.inside(main, p) then return end
		for _, panel in ipairs(K.layer:GetChildren()) do
			if panel:IsA("GuiObject") and panel.Visible and K.inside(panel, p) then return end
		end
		for _, object in ipairs(main:GetDescendants()) do
			local control = object:IsA("GuiButton") or object:IsA("TextBox") or object:IsA("ViewportFrame")
			if input.UserInputType == Enum.UserInputType.Touch then control = control or object:IsA("ScrollingFrame") end
			if control and K.inside(object, p) then
				local visible, parent = true, object
				while parent and parent ~= main do
					if parent:IsA("GuiObject") and (not parent.Visible or (parent.ClipsDescendants and not K.inside(parent, p))) then visible = false; break end
					parent = parent.Parent
				end
				if visible then return end
			end
		end
		dragging, start, origin = input, input.Position, root.Position
	end)
	connectUI(UIS.InputChanged, function(input)
		if dragging and (input == dragging or input.UserInputType == Enum.UserInputType.MouseMovement) then
			local delta = input.Position - start
			root.Position = UDim2.new(origin.X.Scale, origin.X.Offset + delta.X, origin.Y.Scale, origin.Y.Offset + delta.Y)
			K.clampRoot()
			if K.closeFloating then K.closeFloating() end
		end
	end)
	connectUI(UIS.InputEnded, function(input)
		if input == dragging or input.UserInputType == Enum.UserInputType.MouseButton1 then dragging = nil end
	end)
end

-- the corner resizes (PC): three dots that light up under the pointer
if not MOBILE then
	local grip = new("TextButton", {
		AnchorPoint = Vector2.new(1, 1),
		Position = UDim2.new(1, -4, 1, -4),
		Size = UDim2.fromOffset(18, 18),
		BackgroundTransparency = 1,
		Text = "",
		ZIndex = 20,
	}, main)
	local dots = {}
	for i, spec in ipairs({ { 12, 12 }, { 7, 12 }, { 12, 7 } }) do
		dots[i] = new("Frame", {
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.fromOffset(spec[1], spec[2]),
			Size = UDim2.fromOffset(2, 2),
			BackgroundColor3 = C.chip,
			BorderSizePixel = 0,
			ZIndex = 21,
		}, grip)
		corner(dots[i], "full")
	end
	grip.MouseEnter:Connect(function() for _, d in ipairs(dots) do tween(d, 0.15, { BackgroundColor3 = C.text }) end end)
	grip.MouseLeave:Connect(function() for _, d in ipairs(dots) do tween(d, 0.2, { BackgroundColor3 = C.chip }) end end)
	local resizing, start, startSize, startPos
	grip.InputBegan:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1 then
			resizing, start = input, input.Position
			startSize = Vector2.new(root.Size.X.Offset, root.Size.Y.Offset)
			startPos = root.Position
		end
	end)
	connectUI(UIS.InputChanged, function(input)
		if resizing and input.UserInputType == Enum.UserInputType.MouseMovement then
			local s = scaler.Scale
			local d = (input.Position - start) / s
			local screen = K.view() / s
			local w = math.clamp(startSize.X + d.X, L.MINW, math.max(L.MINW, screen.X - 40 / s))
			local h = math.clamp(startSize.Y + d.Y, L.MINH, math.max(L.MINH, screen.Y - 60 / s))
			K.desired = Vector2.new(w, h)
			root.Size = UDim2.fromOffset(w, h)
			root.Position = startPos + UDim2.fromOffset((w - startSize.X) * s / 2, (h - startSize.Y) * s / 2)
			K.clampRoot()
			if K.closeFloating then K.closeFloating() end
		end
	end)
	connectUI(UIS.InputEnded, function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1 then resizing = nil end
	end)
end

connectUI(root:GetPropertyChangedSignal("AbsoluteSize"), function()
	if current and K.reflow then K.reflow(current.subs[current.active or 1]) end
	if current then K.markTab(current, true); K.markSub(current, true) end
end)
connectUI(workspace.CurrentCamera:GetPropertyChangedSignal("ViewportSize"), function()
	if MOBILE then
		baseScale = math.clamp(K.view().Y / 410, 0.62, 1)
		scaler.Scale = baseScale
	end
	K.fitRoot()
end)

-- ------------------------------------------------------------------ toasts --
-- Short lines at the bottom middle of the screen: a dark capsule, a dot and
-- the words. They rise in, stack upwards and sink away.
do
	local stack = new("Frame", {
		Name = "Toasts",
		AnchorPoint = Vector2.new(0.5, 1),
		Position = UDim2.new(0.5, 0, 1, -28),
		Size = UDim2.fromOffset(420, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		ZIndex = 200,
	}, gui)
	local s = new("UIScale", { Scale = baseScale * 0.92 }, stack)
	s:SetAttribute("Follow", 0.92)
	followScale[#followScale + 1] = s
	new("UIListLayout", {
		SortOrder = Enum.SortOrder.LayoutOrder,
		HorizontalAlignment = Enum.HorizontalAlignment.Center,
		VerticalAlignment = Enum.VerticalAlignment.Bottom,
		Padding = UDim.new(0, 6),
	}, stack)
	K.toasts = stack
	local order = 0
	local live = {}
	function notify(text, duration)
		text = tostring(text or "")
		if text == "" then return end
		duration = tonumber(duration) or math.clamp(1.6 + #text / 32, 2, 5)
		for _, t in ipairs(live) do
			if t.text == text and t.frame.Parent then
				t.until_ = os.clock() + duration
				return
			end
		end
		order += 1
		local holder = new("Frame", {
			LayoutOrder = order,
			Size = UDim2.fromOffset(0, 36),
			AutomaticSize = Enum.AutomaticSize.X,
			BackgroundTransparency = 1,
			ZIndex = 200,
		}, stack)
		local pill = new("Frame", {
			Position = UDim2.fromOffset(0, 14),
			Size = UDim2.fromOffset(0, 36),
			AutomaticSize = Enum.AutomaticSize.X,
			BackgroundColor3 = C.panel,
			BackgroundTransparency = 1,
			BorderSizePixel = 0,
			ZIndex = 201,
		}, holder)
		corner(pill, "full")
		local edge = stroke(pill, C.border, 1)
		K.sheen(pill, 0.84)
		pad(pill, 0, 0, 14, 16)
		new("UIListLayout", {
			FillDirection = Enum.FillDirection.Horizontal,
			VerticalAlignment = Enum.VerticalAlignment.Center,
			SortOrder = Enum.SortOrder.LayoutOrder,
			Padding = UDim.new(0, 10),
		}, pill)
		local dot = new("Frame", {
			LayoutOrder = 1,
			Size = UDim2.fromOffset(6, 6),
			BackgroundColor3 = C.accent,
			BackgroundTransparency = 1,
			BorderSizePixel = 0,
			ZIndex = 202,
		}, pill)
		corner(dot, "full")
		local label = K.text(pill, {
			LayoutOrder = 2,
			Size = UDim2.fromOffset(0, 36),
			AutomaticSize = Enum.AutomaticSize.X,
			RichText = true,
			Text = text,
			TextSize = 13,
			TextTransparency = 1,
			TextTruncate = Enum.TextTruncate.None,
			ZIndex = 202,
		})
		local entry = { frame = holder, text = text, until_ = os.clock() + duration }
		table.insert(live, entry)
		tween(pill, 0.45, { Position = UDim2.new(), BackgroundTransparency = 0 }, K.ease.out)
		tween(edge, 0.45, { Transparency = 0 })
		tween(dot, 0.45, { BackgroundTransparency = 0 })
		tween(label, 0.35, { TextTransparency = 0 })
		while #live > 4 do
			local old = table.remove(live, 1)
			old.until_ = 0
		end
		task.spawn(function()
			while os.clock() < entry.until_ do task.wait(0.1) end
			for i, t in ipairs(live) do if t == entry then table.remove(live, i) break end end
			tween(pill, 0.25, { Position = UDim2.fromOffset(0, 10), BackgroundTransparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
			tween(edge, 0.2, { Transparency = 1 })
			tween(dot, 0.2, { BackgroundTransparency = 1 })
			tween(label, 0.2, { TextTransparency = 1 })
			task.wait(0.22)
			holder.AutomaticSize = Enum.AutomaticSize.None
			holder.Size = UDim2.fromOffset(holder.AbsoluteSize.X / math.max(s.Scale, 0.01), 36)
			tween(holder, 0.2, { Size = UDim2.fromOffset(holder.Size.X.Offset, 0) }, K.ease.out)
			task.wait(0.22)
			holder:Destroy()
		end)
	end
end

-- ====================================================================== 20_controls.lua
-- ---------------------------------------------------------------- floating --
-- One slot for a floating list / picker / menu. The sheet (right side of the
-- window) is separate and stacks. A click outside closes what floats.
K.slot = { popup = nil, dialog = nil }

function K.closePopup()
	local p = K.slot.popup
	if not p then return end
	K.slot.popup = nil
	if K.activeSlider and p.frame and K.activeSlider.row:IsDescendantOf(p.frame) then K.stopSlider() end
	if p.onClose then pcall(p.onClose) end
	if p.frame and p.frame.Parent then
		local frame = p.frame
		tween(frame, 0.1, { Position = frame.Position + UDim2.fromOffset(0, -4) })
		task.delay(0.07, function() frame:Destroy() end)
	end
end

function K.closeFloating()
	K.closePopup()
	if K.slot.dialog then K.slot.dialog.close() end
	if K.closeSearch then K.closeSearch() end
end

function K.closeAll()
	K.closeFloating()
	if K.closeSheets then K.closeSheets(true) end
end

-- a floating panel: shadow, black glass, a grey edge, a short drop in
function K.float(width, height, z, parent)
	z = z or 60
	local holder = new("Frame", {
		Size = UDim2.fromOffset(width, height),
		BackgroundTransparency = 1,
		ZIndex = z,
	}, parent or K.layer)
	K.shadow(holder, 26, 0.3, z)
	local box = new("Frame", {
		Name = "Box",
		Size = UDim2.fromScale(1, 1),
		BackgroundColor3 = C.panel,
		BorderSizePixel = 0,
		ClipsDescendants = true,
		ZIndex = z + 1,
	}, holder)
	corner(box, 10)
	stroke(box, C.border, 0)
	K.sheen(box, 0.86)
	local veil = new("Frame", {
		Size = UDim2.fromScale(1, 1),
		BackgroundColor3 = C.panel,
		BorderSizePixel = 0,
		ZIndex = z + 40,
	}, box)
	tween(veil, 0.2, { BackgroundTransparency = 1 }).Completed:Connect(function() veil:Destroy() end)
	return holder, box
end

-- where a floating panel of `size` goes next to `anchor` (layer units out)
function K.place(anchor, size, side)
	local s = scaler.Scale
	local screen = K.view() / s
	local a = K.toLayer(anchor.AbsolutePosition)
	local as = anchor.AbsoluteSize / s
	local x = side == "end" and (a.X + as.X - size.X) or a.X
	local y = a.Y + as.Y + 6
	if y + size.Y > screen.Y - 8 then y = a.Y - size.Y - 6 end
	x = math.clamp(x, 8, math.max(8, screen.X - size.X - 8))
	y = math.clamp(y, 8, math.max(8, screen.Y - size.Y - 8))
	return x, y
end

-- drop the new floating panel in from a few pixels above
function K.drop(holder, x, y)
	holder.Position = UDim2.fromOffset(x, y - 6)
	tween(holder, 0.25, { Position = UDim2.fromOffset(x, y) }, K.ease.out)
end

-- the pick list behind dropdowns and multi-selects
function K.listPopup(anchor, options, isOn, onPick, multi)
	K.closePopup()
	local ITEM = MOBILE and 34 or 30
	local searchable = #options > 12
	local width = math.max(anchor.AbsoluteSize.X / scaler.Scale + 24, 200)
	local listH = math.min(#options * (ITEM + 2) + 8, MOBILE and 220 or 290)
	local height = listH + (searchable and 38 or 0)
	local holder, box = K.float(width, height, 100)
	K.drop(holder, K.place(anchor, Vector2.new(width, height), "end"))
	local filter
	if searchable then
		filter = new("TextBox", {
			Position = UDim2.fromOffset(12, 0),
			Size = UDim2.new(1, -24, 0, 36),
			BackgroundTransparency = 1,
			ClearTextOnFocus = false,
			FontFace = K.face.medium,
			PlaceholderText = "Filter",
			PlaceholderColor3 = C.faint,
			Text = "",
			TextSize = 12,
			TextColor3 = C.text,
			TextXAlignment = Enum.TextXAlignment.Left,
			ZIndex = 103,
		}, box)
		rule(box, { Position = UDim2.fromOffset(0, 36), ZIndex = 103 })
	end
	local list = new("ScrollingFrame", {
		Position = UDim2.fromOffset(0, searchable and 38 or 0),
		Size = UDim2.new(1, 0, 1, searchable and -38 or 0),
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		CanvasSize = UDim2.new(),
		AutomaticCanvasSize = Enum.AutomaticSize.Y,
		ScrollBarThickness = 2,
		ScrollBarImageColor3 = C.sub,
		ScrollingDirection = Enum.ScrollingDirection.Y,
		Active = true,
		ZIndex = 102,
	}, box)
	K.scroller(list)
	pad(list, 5, 5, 5, 5)
	new("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 2) }, list)
	local items = {}
	for i, option in ipairs(options) do
		local on = isOn(option)
		local item = new("TextButton", {
			LayoutOrder = i,
			Size = UDim2.new(1, 0, 0, ITEM),
			BackgroundColor3 = C.hover,
			BackgroundTransparency = 1,
			AutoButtonColor = false,
			Text = "",
			ZIndex = 103,
		}, list)
		corner(item, 7)
		local label = K.text(item, {
			Position = UDim2.fromOffset(10, 0),
			Size = UDim2.new(1, -36, 1, 0),
			Text = option,
			TextSize = 13,
			TextColor3 = on and C.text or C.sub,
			ZIndex = 104,
		})
		local mark = K.glyph(item, "check", 13, C.text, {
			AnchorPoint = Vector2.new(1, 0.5),
			Position = UDim2.new(1, -9, 0.5, 0),
			ImageTransparency = on and 0 or 1,
			ZIndex = 104,
		})
		item.MouseEnter:Connect(function()
			tween(item, 0.12, { BackgroundTransparency = 0 })
			tween(label, 0.12, { TextColor3 = C.text })
		end)
		item.MouseLeave:Connect(function()
			tween(item, 0.18, { BackgroundTransparency = 1 })
			tween(label, 0.18, { TextColor3 = isOn(option) and C.text or C.sub })
		end)
		item.MouseButton1Click:Connect(function()
			onPick(option)
			if multi then
				tween(mark, 0.14, { ImageTransparency = isOn(option) and 0 or 1 })
			end
		end)
		items[#items + 1] = { item = item, text = string.lower(option) }
		if i <= 14 then
			label.TextTransparency = 1
			task.delay(0.01 * i, function()
				if label.Parent then tween(label, 0.18, { TextTransparency = 0 }) end
			end)
		end
	end
	if filter then
		filter:GetPropertyChangedSignal("Text"):Connect(function()
			local q = string.lower(filter.Text)
			for _, it in ipairs(items) do
				it.item.Visible = q == "" or string.find(it.text, q, 1, true) ~= nil
			end
		end)
		if not MOBILE then task.defer(function() filter:CaptureFocus() end) end
	end
	for i, option in ipairs(options) do
		if isOn(option) then
			task.defer(function() K.scrollTo(list, math.max(0, (i - 3) * (ITEM + 2)), true) end)
			break
		end
	end
	K.slot.popup = { frame = holder, owner = anchor }
	return holder
end

-- ------------------------------------------------------------------ sheet --
-- A panel floats in from the right edge of the window for anything with more
-- to say than a row: a function's extra settings, the configs. Sheets stack;
-- the top one shows, a back arrow returns. The window behind dims.
do
	local INSET = MOBILE and 8 or 10
	local W = 340
	local function goal(open)
		if MOBILE then
			return open and UDim2.new(0, INSET, 0, L.TOP + INSET) or UDim2.new(1, 24, 0, L.TOP + INSET)
		end
		return open and UDim2.new(1, -(W + INSET), 0, L.TOP + INSET) or UDim2.new(1, 24, 0, L.TOP + INSET)
	end
	local holder = new("Frame", {
		Name = "Sheet",
		Position = goal(false),
		Size = MOBILE and UDim2.new(1, -INSET * 2, 1, -(L.TOP + L.DOCK + INSET))
			or UDim2.new(0, W, 1, -(L.TOP + INSET * 2)),
		BackgroundTransparency = 1,
		Visible = false,
		ZIndex = 60,
	}, main)
	K.shadow(holder, 26, 0.25, 60)
	local sheet = new("Frame", {
		Name = "Box",
		Size = UDim2.fromScale(1, 1),
		BackgroundColor3 = C.panel,
		BorderSizePixel = 0,
		ClipsDescendants = true,
		ZIndex = 61,
	}, holder)
	corner(sheet, 12)
	stroke(sheet, C.border, 0)
	K.sheen(sheet, 0.86)
	-- the dim over the window: the window's own shape, so its corners stay round
	local scrim = new("TextButton", {
		Name = "Scrim",
		Size = UDim2.fromScale(1, 1),
		BackgroundColor3 = C.void,
		BackgroundTransparency = 1,
		AutoButtonColor = false,
		Text = "",
		Visible = false,
		ZIndex = 55,
	}, main)
	corner(scrim, L.RADIUS)
	local head = new("Frame", { Size = UDim2.new(1, 0, 0, 50), BackgroundTransparency = 1, ZIndex = 62 }, sheet)
	rule(head, { AnchorPoint = Vector2.new(0, 1), Position = UDim2.fromScale(0, 1), ZIndex = 62 })
	local back = K.iconButton(head, "arrow-left", 28, {
		AnchorPoint = Vector2.new(0, 0.5),
		Position = UDim2.new(0, 10, 0.5, 0),
		Visible = false,
		ZIndex = 63,
	})
	local title = K.text(head, {
		Position = UDim2.fromOffset(18, 0),
		Size = UDim2.new(1, -70, 1, 0),
		FontFace = K.face.semi,
		TextSize = 14,
		Text = "",
		ZIndex = 63,
	})
	local close = K.iconButton(head, "x", 28, {
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.new(1, -10, 0.5, 0),
		ZIndex = 63,
	})
	local scroll = new("ScrollingFrame", {
		Position = UDim2.fromOffset(0, 51),
		Size = UDim2.new(1, 0, 1, -51),
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		CanvasSize = UDim2.new(),
		AutomaticCanvasSize = Enum.AutomaticSize.Y,
		ScrollBarThickness = 2,
		ScrollingDirection = Enum.ScrollingDirection.Y,
		Active = true,
		ZIndex = 61,
	}, sheet)
	K.scroller(scroll)
	K.sheetFrame = holder

	local stack = {}
	local shown, fitConn
	-- the panel is as tall as what it holds, up to the window's height
	local function fit(animate)
		if not shown then return end
		local s = math.max(scaler.Scale * K.pop.Scale, 0.01)
		local full = holder.Parent.AbsoluteSize.Y / s - (MOBILE and (L.TOP + L.DOCK + INSET) or (L.TOP + INSET * 2))
		local want = math.min(math.floor(shown.body.AbsoluteSize.Y / s) + 51 + 12, full)
		local size = MOBILE and UDim2.new(1, -INSET * 2, 0, want) or UDim2.fromOffset(W, want)
		if animate then tween(holder, 0.25, { Size = size }, K.ease.out) else holder.Size = size end
	end
	local function show(top, dir)
		if shown then shown.y = scroll.CanvasPosition.Y end
		shown = top
		K.scrollMotion[scroll] = nil
		for _, child in ipairs(scroll:GetChildren()) do
			if child:IsA("GuiObject") then child.Parent = K.attic end
		end
		if fitConn then fitConn:Disconnect(); fitConn = nil end
		if not top then return end
		top.body.Parent = scroll
		fitConn = top.body:GetPropertyChangedSignal("AbsoluteSize"):Connect(function() fit(true) end)
		task.defer(fit, holder.Visible)
		title.Text = top.title
		back.Visible = #stack > 1
		title.Position = UDim2.fromOffset(#stack > 1 and 44 or 18, 0)
		K.scrollTo(scroll, top.y or 0, true)
		task.defer(function() if shown == top then K.scrollTo(scroll, top.y or 0, true) end end)
		if dir then
			top.body.Position = UDim2.fromOffset(dir * 24, 0)
			tween(top.body, 0.35, { Position = UDim2.new() }, K.ease.out)
		end
	end
	local function slide(open)
		if open then
			holder.Visible, scrim.Visible = true, true
			tween(holder, 0.45, { Position = goal(true) }, K.ease.out)
			tween(scrim, 0.3, { BackgroundTransparency = 0.5 })
		else
			tween(scrim, 0.22, { BackgroundTransparency = 1 })
			tween(holder, 0.28, { Position = goal(false) }, Enum.EasingStyle.Quart, Enum.EasingDirection.In).Completed:Connect(function(state)
				if state == Enum.PlaybackState.Completed and #stack == 0 then
					holder.Visible, scrim.Visible = false, false
				end
			end)
		end
	end
	-- body: a Frame (AutomaticSize Y) that lives in the attic while closed
	function K.openSheet(name, body, opts)
		opts = opts or {}
		K.closePopup()
		for i, entry in ipairs(stack) do
			if entry.body == body then
				if i == #stack then return end
				-- open already: go back to it
				for j = #stack, i + 1, -1 do
					local gone = table.remove(stack, j)
					if gone.onClose then pcall(gone.onClose) end
				end
				show(stack[#stack], -1)
				return
			end
		end
		if opts.replace then K.closeSheets(false) end
		stack[#stack + 1] = { title = name, body = body, onClose = opts.onClose, owner = opts.owner }
		show(stack[#stack], #stack > 1 and 1 or nil)
		if #stack == 1 then slide(true) end
	end
	function K.popSheet()
		local gone = table.remove(stack)
		if gone and gone.onClose then pcall(gone.onClose) end
		if #stack == 0 then
			show(nil)
			slide(false)
		else
			show(stack[#stack], -1)
		end
	end
	function K.closeSheets(animate)
		if #stack == 0 then return end
		for i = #stack, 1, -1 do
			local gone = stack[i]
			stack[i] = nil
			if gone.onClose then pcall(gone.onClose) end
		end
		show(nil)
		if animate == false then
			holder.Visible, scrim.Visible = false, false
			holder.Position = goal(false)
			scrim.BackgroundTransparency = 1
		else
			slide(false)
		end
	end
	function K.sheetOpen(body)
		for _, entry in ipairs(stack) do if entry.body == body then return true end end
		return false
	end
	back.MouseButton1Click:Connect(function() SFX.click(); K.popSheet() end)
	close.MouseButton1Click:Connect(function() SFX.click(); K.closeSheets(true) end)
	scrim.MouseButton1Click:Connect(function() K.closeSheets(true) end)
end

