		{ 0x9E3779B9, 0x85EBCA6B },
		{ 0x243F6A88, 0xC2B2AE35 },
		{ 0xB7E15162, 0x27D4EB2F },
		{ 0x85EBCA6B, 0x165667B1 },
	}

	local lut = nil

	local function alphabet()
		if lut then
			return lut
		end

		local abc = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
		lut = {}

		for i = 1, #abc do
			lut[sbyte(abc, i)] = i - 1
		end

		return lut
	end

	local function unb64(text)
		local tbl = alphabet()
		local out, n = {}, 0
		local acc, bits = 0, 0

		for i = 1, #text do
			local c = sbyte(text, i)
			local v = tbl[c]

			if v then
				acc = acc * 64 + v
				bits = bits + 6

				if bits >= 8 then
					bits = bits - 8
					local div = 2 ^ bits
					local byte = math.floor(acc / div)
					acc = acc - byte * div
