local function safeClone(inst)
	local archivable = inst.Archivable
	if not archivable then
		if not pcall(function() inst.Archivable = true end) then return nil end
	end
	local ok, clone = pcall(inst.Clone, inst)
	if not archivable then
		pcall(function() inst.Archivable = archivable end)
	end
	if not ok then return nil end
	return clone
end

local function isValidBodyPart(p)
	if not p or not p.Parent then return false end
	if not p:IsA("BasePart") then return false end
	if p.Name == "HumanoidRootPart" or p.Name == "GlowShell" then return false end
	local s = p.Size
	if s.X == 0 and s.Y == 0 and s.Z == 0 then return false end
	return true
end

local function getCharacterParts(char, out)
	local parts = out or {}
	cl(parts)
	if not char or not char.Parent then
		return parts
	end
	
	local children = gc(char)
	local n = 0
	
	for i = 1, #children do
		local child = children[i]
		if R15_PARTS[child.Name] and child:IsA("BasePart") then
			if isValidBodyPart(child) then
				n = n + 1
				parts[n] = child
			end
		end
	end
	
	return parts
end

local function getBB(parts)
	if not parts or #parts == 0 then
		return nil, nil
	end
	
	local mn, mx
	local validCount = 0
	
	for i = 1, #parts do
		local part = parts[i]
		if part and part.Parent then
			local sz = part.Size
			
			if sz.X ~= 0 or sz.Y ~= 0 or sz.Z ~= 0 then
				local half = sz * 0.5
				local pp = part.Position
				local minPos = pp - half
				local maxPos = pp + half
				
				if not mn then
					mn = minPos
					mx = maxPos
				else
					mn = m3(mn, minPos)
					mx = m3x(mx, maxPos)
				end
				
				validCount = validCount + 1
			end
		end
	end
	
	if validCount == 0 or not mn or not mx then
		return nil, nil
	end
	
	local center = (mn + mx) * 0.5
	local size = mx - mn
	local front = Vector3.new(center.X, center.Y, mx.Z)
	
	return CFrame.new(center, front), size
end

local function w2sc(w)
	local s, inB = w2s(cam, w)
	return Vector2.new(s.X, s.Y), inB, s.Z
end

local function calcCorn(cf, sz, out, cornsOut)
	local corn = cornsOut or cr(#VERTS)
	local mnX, mnY = vs.X, vs.Y
	local mxX, mxY = 0, 0
	for i = 1, #VERTS do
		local p = w2sc((cf + sz*0.5*VERTS[i]).Position)
		corn[i] = p
		local px, py = p.X, p.Y
		if px < mnX then mnX = px end
		if py < mnY then mnY = py end
		if px > mxX then mxX = px end
		if py > mxY then mxY = py end
	end
	local fmnX, fmnY = fl(mnX), fl(mnY)
	local fmxX, fmxY = fl(mxX), fl(mxY)
	local res = out or {}
	res.corners = corn
	res.tl = Vector2.new(fmnX, fmnY)
	res.tr = Vector2.new(fmxX, fmnY)
	res.bl = Vector2.new(fmnX, fmxY)
	res.br = Vector2.new(fmxX, fmxY)
	return res
end

local function calcCornViewport(cf, sz, vpCam, vpFrame)
	local hrp = cf.Position
	local distance = (vpCam.CFrame.Position - hrp).Magnitude
	
	local vpfSize = vpFrame.AbsoluteSize
	local vpfPos = vpFrame.AbsolutePosition
	
	if vpfSize.X <= 0 or vpfSize.Y <= 0 then
		return {
			corners = {},
			tl = Vector2.new(0, 0),
			tr = Vector2.new(0, 0),
			bl = Vector2.new(0, 0),
			br = Vector2.new(0, 0)
		}
	end
	
	local fov = vpCam.FieldOfView or 70
	local num = math.tan(math.rad(fov / 2))
	local factorY = vpfSize.Y / (2 * distance * num)
	local factorX = vpfSize.X / (2 * distance * num * (vpfSize.X / vpfSize.Y))
	
	local boxHeight = sz.Y * factorY * 1.15
	local boxWidth = sz.X * factorX
	
	local guiInset = guiService:GetGuiInset()
	local offsetY = guiInset.Y
	
	local centerX = vpfPos.X + (vpfSize.X / 2)
	local centerY = vpfPos.Y + (vpfSize.Y / 2)
	
	local minX = centerX - (boxWidth / 2)
	local minY = centerY - (boxHeight / 2) + offsetY
	local maxX = centerX + (boxWidth / 2)
	local maxY = centerY + (boxHeight / 2) + offsetY
	
	return {
		corners = {
			Vector2.new(minX, minY), Vector2.new(maxX, minY),
			Vector2.new(maxX, maxY), Vector2.new(minX, maxY),
			Vector2.new(minX, minY), Vector2.new(maxX, minY),
			Vector2.new(maxX, maxY), Vector2.new(minX, maxY)
		},
		tl = Vector2.new(fl(minX), fl(minY)),
		tr = Vector2.new(fl(maxX), fl(minY)),
		bl = Vector2.new(fl(minX), fl(maxY)),
		br = Vector2.new(fl(maxX), fl(maxY))
	}
end

