local maskRect = {}
local maskN = 0
local maskWas = 0

local dmin, dmax = math.min, math.max
local v2 = Vector2.new

local MASK_HYST = 6

local TRACK = {
	Line = { Visible = true, From = true, To = true },
	Square = { Visible = true, Position = true, Size = true },
	Image = { Visible = true, Position = true, Size = true },
	Text = { Visible = true, Position = true },
	Circle = { Visible = true, Position = true },
	Triangle = { Visible = true, PointA = true, PointB = true, PointC = true }
}

local reg = {}
local regN = 0
local mreg = {}
local mregN = 0
local stOf = {}
local pmeta

local function maskHit(x1, y1, x2, y2, m)
	for i = 1, maskN do
		local r = maskRect[i]
		if x1 < r[3] + m and x2 > r[1] - m and y1 < r[4] + m and y2 > r[2] - m then
			return true
		end
	end
	return false
end

local function maskUpd()
	maskN = 0
	local src = getgenv and getgenv().salad_drawmask
	if type(src) ~= "table" then return end
	local n = #src
	if n == 0 then return end
	local ins = guiService:GetGuiInset()
	for i = 1, n do
		local f = src[i]
		if typeof(f) == "Instance" and f.Parent and f.Visible then
			local p, s = f.AbsolutePosition, f.AbsoluteSize
			if s.X > 0.5 and s.Y > 0.5 then
				maskN = maskN + 1
				local r = maskRect[maskN]
				if not r then
					r = {}
					maskRect[maskN] = r
				end
				r[1] = p.X + ins.X
				r[2] = p.Y + ins.Y
				r[3] = r[1] + s.X
				r[4] = r[2] + s.Y
			end
		end
	end
end


local function clipSeg(a, b)
	local x0, y0, x1, y1 = a.X, a.Y, b.X, b.Y
	local cut = false

	for i = 1, maskN do
		local r = maskRect[i]
		local dx, dy = x1 - x0, y1 - y0
		local t0, t1 = 0, 1
		local ok = true

		if dx == 0 then
			if x0 < r[1] or x0 > r[3] then ok = false end
		else
			local ta, tb = (r[1] - x0) / dx, (r[3] - x0) / dx
			if ta > tb then ta, tb = tb, ta end
			if ta > t0 then t0 = ta end
			if tb < t1 then t1 = tb end
		end

		if ok then
			if dy == 0 then
				if y0 < r[2] or y0 > r[4] then ok = false end
			else
				local ta, tb = (r[2] - y0) / dy, (r[4] - y0) / dy
				if ta > tb then ta, tb = tb, ta end
				if ta > t0 then t0 = ta end
				if tb < t1 then t1 = tb end
			end
		end

		if ok and t0 <= t1 then
			local ln = (dx * dx + dy * dy) ^ 0.5
			if t0 * ln < 1 and (1 - t1) * ln < 1 then
				return nil
			end
			if t0 >= 1 - t1 then
				x1 = x0 + dx * t0
				y1 = y0 + dy * t0
			else
				x0 = x0 + dx * t1
				y0 = y0 + dy * t1
			end
			cut = true
		end
	end

	if not cut then
		return a, b
	end

	return v2(x0, y0), v2(x1, y1)
end


local function clipBox(p, s)
	local x1, y1 = p.X, p.Y
	local x2, y2 = x1 + s.X, y1 + s.Y
	local cut = false

	for i = 1, maskN do
		local r = maskRect[i]

		if x1 < r[3] and x2 > r[1] and y1 < r[4] and y2 > r[2] then
			local best = 0
			local bx1, by1, bx2, by2

			if r[2] > y1 then
				local ey = dmin(y2, r[2])
				local ar = (x2 - x1) * (ey - y1)
				if ar > best then best, bx1, by1, bx2, by2 = ar, x1, y1, x2, ey end
			end

			if r[4] < y2 then
				local sy = dmax(y1, r[4])
				local ar = (x2 - x1) * (y2 - sy)
				if ar > best then best, bx1, by1, bx2, by2 = ar, x1, sy, x2, y2 end
			end

			if r[1] > x1 then
				local ex = dmin(x2, r[1])
				local ar = (ex - x1) * (y2 - y1)
				if ar > best then best, bx1, by1, bx2, by2 = ar, x1, y1, ex, y2 end
			end

			if r[3] < x2 then
				local sx = dmax(x1, r[3])
				local ar = (x2 - sx) * (y2 - y1)
				if ar > best then best, bx1, by1, bx2, by2 = ar, sx, y1, x2, y2 end
			end

			if best <= 1 then
				return nil
			end

			x1, y1, x2, y2 = bx1, by1, bx2, by2
			cut = true
		end
	end

	if not cut then
		return p, s
	end

	return v2(x1, y1), v2(x2 - x1, y2 - y1)
end

local function flush(s)
	local d, w = s.d, s.w

	for k in next, s.tr do
		if k ~= "Visible" then
			d[k] = w[k]
		end
	end

	s.hid = false
	d.Visible = true
end

local function resolve(s)
	local d, w, cls = s.d, s.w, s.cls

	if not w.Visible then
		d.Visible = false
		s.hid = false
		return
	end

	if maskN == 0 then
		flush(s)
		return
	end

	if cls == "Line" then
		local a, b = clipSeg(w.From, w.To)
		if not a then
			d.Visible = false
			s.hid = true
			return
		end
		d.From = a
		d.To = b
		s.hid = false
		d.Visible = true
		return
	end

	if cls == "Square" and d.Filled then
		local p, sz = clipBox(w.Position, w.Size)
		if not p then
			d.Visible = false
			s.hid = true
			return
		end
		d.Position = p
		d.Size = sz
		s.hid = false
		d.Visible = true
		return
	end

	local x1, y1, x2, y2

	if cls == "Text" then
		local p, tb = w.Position, d.TextBounds
		x1 = d.Center and (p.X - tb.X * 0.5) or p.X
		x2 = x1 + tb.X
		y1 = p.Y
		y2 = p.Y + tb.Y
	elseif cls == "Circle" then
		local p, rad = w.Position, d.Radius
		x1, y1, x2, y2 = p.X - rad, p.Y - rad, p.X + rad, p.Y + rad
	elseif cls == "Triangle" then
		local a, b, c = w.PointA, w.PointB, w.PointC
		x1, x2 = dmin(a.X, b.X, c.X), dmax(a.X, b.X, c.X)
		y1, y2 = dmin(a.Y, b.Y, c.Y), dmax(a.Y, b.Y, c.Y)
	else
		local p, sz = w.Position, w.Size
		x1, y1, x2, y2 = p.X, p.Y, p.X + sz.X, p.Y + sz.Y
	end

	if maskHit(x1, y1, x2, y2, s.hid and MASK_HYST or 0) then
		d.Visible = false
		s.hid = true
		return
	end

	flush(s)
end

local function unregDraw(t)
	local s = stOf[t]
	if not s then return end
	local last = reg[regN]
	local ls = stOf[last]
	reg[s.i] = last
	if ls then ls.i = s.i end
	reg[regN] = nil
	regN = regN - 1
	if s.mi > 0 then
		local mlast = mreg[mregN]
		local mls = stOf[mlast]
		mreg[s.mi] = mlast
		if mls then mls.mi = s.mi end
		mreg[mregN] = nil
		mregN = mregN - 1
	end
	stOf[t] = nil
end

local function premove(t)
	local s = stOf[t]
	if not s then return end
	unregDraw(t)
	pcall(s.d.Remove, s.d)
end

pmeta = {
	__index = function(t, k)
		local s = stOf[t]
		if not s then return nil end
		if k == "Remove" or k == "Destroy" then return premove end
		if s.tr[k] then return s.w[k] end
		return s.d[k]
	end,
	__newindex = function(t, k, v)
		local s = stOf[t]
		if not s then return end
		if not s.tr[k] then
			s.d[k] = v
		elseif maskN == 0 or s.mi == 0 then
			s.w[k] = v
			s.d[k] = v
		else
			s.w[k] = v
			resolve(s)
		end
	end
}

local function regDraw(cls, msk)
	local d = Drawing.new(cls)
	local tr = TRACK[cls] or TRACK.Square
	local w = {}

	for k in next, tr do
		local ok, val = pcall(function() return d[k] end)
		if ok then w[k] = val end
	end

	if w.Visible == nil then w.Visible = false end

	for k in next, tr do
		if k ~= "Visible" and w[k] == nil then
			w[k] = v2()
		end
	end

	local t = setmetatable({}, pmeta)

	regN = regN + 1
	reg[regN] = t

	local st = { d = d, cls = cls, tr = tr, w = w, hid = false, i = regN, mi = 0 }

	stOf[t] = st

	if msk then
		mregN = mregN + 1
		mreg[mregN] = t
		st.mi = mregN
	end

	return t
end

local function maskStep()
	if not pcall(maskUpd) then
		maskN = 0
	end

	if mregN > 0 and (maskN > 0 or maskWas > 0) then
		for i = mregN, 1, -1 do
			local t = mreg[i]
			local s = stOf[t]
			if s and not pcall(resolve, s) then
				unregDraw(t)
			end
		end
	end

	maskWas = maskN
end

local Esp = {}
Esp.__index = Esp

function Esp.new(p, itf)
	local self = setmetatable({}, Esp)
	self.plr = assert(p, "No player")
	self.itf = assert(itf, "No interface")
	self.msk = (itf._clones ~= nil and itf._clones[p] ~= nil) and true or false
	self:init()
	return self
end

function Esp:_c(cls, props)
	local d = regDraw(cls, self.msk)
	for prop, val in next, props do
		pcall(function() d[prop] = val end)
	end
	self.bin[#self.bin + 1] = d
	return d
end

