			ab = self:_c("Line", { Thickness = 1, Visible = false }),
			at = self:_c("Text", { Center = true, Visible = false }),
		}
	}

	self.customW2s = function(pos)
		local viewport = self.viewport
		local activeCam = self.activeCam
		if viewport then
			local vpSize = viewport.AbsoluteSize
			if vpSize.X < 1 or vpSize.Y < 1 then
				return Vector2.new(0, 0), false, 0
			end
			local rel = activeCam.CFrame:PointToObjectSpace(pos)
			if rel.Z > -0.05 then
				return Vector2.new(0, 0), false, 0
			end
			local tan = math.tan(math.rad((activeCam.FieldOfView or 70) * 0.5))
			local dep = -rel.Z
			local nx = rel.X / (dep * tan * (vpSize.X / vpSize.Y))
			local ny = rel.Y / (dep * tan)
			local base = viewport.AbsolutePosition + guiService:GetGuiInset()
			local sx = base.X + vpSize.X * (0.5 + nx * 0.5)
			local sy = base.Y + vpSize.Y * (0.5 - ny * 0.5)
			return Vector2.new(sx, sy), true, dep
		else
			local s, inB = w2s(activeCam, pos)
			return Vector2.new(s.X, s.Y), inB, s.Z
		end
	end
end

function Esp:Dest()
	for i = 1, #self.bin do
		self.bin[i]:Remove()
	end
	if self.arC then self.arC:Destroy() end
	if self.av then self.av:Destroy() end
	if self.gf then self.gf:Destroy() end
	if self.ob then self.ob:Destroy() end
	if self.obk then self.obk:Destroy() end
	self:disconnectCharEvents()
	cl(self)
end

function Esp:disconnectCharEvents()
	for _, conn in pairs(self.charConnections) do
		if conn and conn.Disconnect then
			conn:Disconnect()
		end
	end
	self.charConnections = {}
end

function Esp:setupCharEvents(char)
	self:disconnectCharEvents()
	
	if not char then return end
	
	local function onChild(child)
		if R15_PARTS[child.Name] then
			self.cacheValid = false
		end
	end
	
	self.charConnections.childAdded = char.ChildAdded:Connect(onChild)
	self.charConnections.childRemoved = char.ChildRemoved:Connect(onChild)
end

function Esp:validateCache()
	if not self.char or not self.char.Parent then
		return false
	end
	
	if self.cacheValid == false then
		return false
	end
	
	if #self.charCache == 0 then
		return false
	end
	
	for i = 1, math.min(3, #self.charCache) do
		local part = self.charCache[i]
		if not part or not part.Parent or part.Parent ~= self.char then
			return false
		end
	end
	
	return true
end

function Esp:rebuildCache()
	local cache = self.charCache
	if not cache then
		cache = {}
		self.charCache = cache
	end
	if not self.char or not self.char.Parent then
		cl(cache)
		return
	end
	
	getCharacterParts(self.char, cache)
	self.cacheValid = true
end

function Esp:gradTxt(pool, text, cx, topY, sz, fnt, out, oc, tr, c1, c2, off)
	local n = #text
	local widths = self._gw or {}
	self._gw = widths
	local caches = self._gwc
	if not caches then
		caches = {}
		self._gwc = caches
	end
	local pc = caches[pool]
	if not pc then
		pc = { c = {}, s = {}, f = {}, w = {} }
		caches[pool] = pc
	end
	local pcc, pcs, pcf, pcw = pc.c, pc.s, pc.f, pc.w
	local total = 0
	for i = 1, n do
		local o = pool[i]
		if not o then
			o = self:_c("Text", { Center = false, Visible = false })
			pool[i] = o
		end
		local bt = sb(text, i)
		if pcc[i] ~= bt or pcs[i] ~= sz or pcf[i] ~= fnt then
			if pcs[i] ~= sz then
				o.Size = sz
				pcs[i] = sz
			end
			if pcf[i] ~= fnt then
				o.Font = fnt
				pcf[i] = fnt
			end
			if pcc[i] ~= bt then
				local chs = CHR[bt]
				if not chs then
					chs = sch(bt)
					CHR[bt] = chs
				end
				o.Text = chs
				pcc[i] = bt
			end
			pcw[i] = o.TextBounds.X
		end
		local wv = pcw[i]
		widths[i] = wv
		total = total + wv
	end
	for i = n + 1, #pool do pool[i].Visible = false end
	local x = cx - total*0.5
	for i = 1, n do
		local o = pool[i]
		o.Color = gradS(c1, c2, n > 1 and (i-1)/(n-1) or 0, off)
		o.Transparency = tr
		o.Outline = out
		o.OutlineColor = oc
		o.Position = Vector2.new(x, topY)
		o.Visible = true
		x = x + widths[i]
	end
	pool.__vis = true
end

function Esp:hideGrad(pool)
	if not pool.__vis then return end
	pool.__vis = false
	for i = 1, #pool do pool[i].Visible = false end
end

function Esp:drawSegs(segs, tr, oon, ocol, otr, osegs)
	osegs = osegs or segs
	if oon then
		for i = 1, #osegs do
			local s = osegs[i]
			local k = self.cnk[i]
			if not k then
				k = self:_c("Line", { Thickness = 3, ZIndex = 100, Visible = false })
				self.cnk[i] = k
			end
			k.From = s[1]
			k.To = s[2]
			k.Color = ocol
			k.Transparency = otr
			k.Visible = true
		end
	end
	for i = 1, #segs do
		local s = segs[i]
		local o = self.cn[i]
		if not o then
			o = self:_c("Line", { Thickness = 1, ZIndex = 101, Visible = false })
			self.cn[i] = o
		end
		o.From = s[1]
		o.To = s[2]
		o.Color = s[3]
		o.Transparency = tr
		o.Visible = true
	end
	for i = #segs + 1, #self.cn do self.cn[i].Visible = false end
	for i = (oon and #osegs or 0) + 1, #self.cnk do self.cnk[i].Visible = false end
	self.cn.__vis = #segs > 0
	self.cnk.__vis = (oon and #osegs > 0) and true or false
end

function Esp:hideRects(pool)
	if not pool.__vis then return end
	pool.__vis = false
	for i = 1, #pool do pool[i].Visible = false end
end

function Esp:rect(pool, i, pos, size, col, tr, z)
	if size.X <= 0 or size.Y <= 0 then
		return i
	end
	local o = pool[i]
	if not o then
		o = self:_c("Square", { Filled = true, Visible = false, ZIndex = z })
		pool[i] = o
		zSet[o] = z
	end
	o.Position = pos
	o.Size = size
	o.Color = col
	o.Transparency = tr
	ensureZ(o, z)
	o.Visible = true
	pool.__vis = true
	return i + 1
end

function Esp:drawCorners(corn, c1, c2, grd, tr, ocol, oon, otr)
	local tl, br = corn.tl, corn.br
	local x1, y1 = tl.X, tl.Y
	local x2, y2 = br.X - 1, br.Y - 1
	local W, H = x2 - x1 + 1, y2 - y1 + 1
	if W <= 0 or H <= 0 then
		self:hideRects(self.rs)
		self:hideRects(self.rso)
		return
	end
	local lx = fl(W * 0.25)
	local ly = fl(H * 0.25)
	if lx < 1 then lx = 1 end
	if ly < 1 then ly = 1 end
	local CH = y2 - y1
	if CH <= 0 then CH = 1 end
	local idx = 1
	local oi = 1
	if oon then
		oi = self:rect(self.rso, oi, Vector2.new(x1 - 1, y1 - 1), Vector2.new(lx + 2, 3), ocol, otr, 100)
		oi = self:rect(self.rso, oi, Vector2.new(x2 - lx, y1 - 1), Vector2.new(lx + 2, 3), ocol, otr, 100)
		oi = self:rect(self.rso, oi, Vector2.new(x1 - 1, y2 - 1), Vector2.new(lx + 2, 3), ocol, otr, 100)
		oi = self:rect(self.rso, oi, Vector2.new(x2 - lx, y2 - 1), Vector2.new(lx + 2, 3), ocol, otr, 100)
		oi = self:rect(self.rso, oi, Vector2.new(x1 - 1, y1 - 1), Vector2.new(3, ly + 2), ocol, otr, 100)
		oi = self:rect(self.rso, oi, Vector2.new(x2 - 1, y1 - 1), Vector2.new(3, ly + 2), ocol, otr, 100)
		oi = self:rect(self.rso, oi, Vector2.new(x1 - 1, y2 - ly), Vector2.new(3, ly + 2), ocol, otr, 100)
		oi = self:rect(self.rso, oi, Vector2.new(x2 - 1, y2 - ly), Vector2.new(3, ly + 2), ocol, otr, 100)
	end
	local colTop = boxCol(grd, c1, c2, y1, y1, CH)
	local colBot = boxCol(grd, c1, c2, y2, y1, CH)
	idx = self:rect(self.rs, idx, Vector2.new(x1, y1), Vector2.new(lx, 1), colTop, tr, 101)
	idx = self:rect(self.rs, idx, Vector2.new(x2 - lx + 1, y1), Vector2.new(lx, 1), colTop, tr, 101)
	idx = self:rect(self.rs, idx, Vector2.new(x1, y2), Vector2.new(lx, 1), colBot, tr, 101)
	idx = self:rect(self.rs, idx, Vector2.new(x2 - lx + 1, y2), Vector2.new(lx, 1), colBot, tr, 101)
	local N = grd and math.min(6, ly) or 1
	for s = 1, N do
		local a1, a2 = fl(ly*(s-1)/N), fl(ly*s/N)
		if a2 <= a1 then a2 = a1 + 1 end
		local yt1, yt2 = y1 + a1, y1 + a2
		local yb1, yb2 = y2 - a2 + 1, y2 - a1 + 1
		local ct = boxCol(grd, c1, c2, (yt1 + yt2)*0.5, y1, CH)
		local cb = boxCol(grd, c1, c2, (yb1 + yb2)*0.5, y1, CH)
		idx = self:rect(self.rs, idx, Vector2.new(x1, yt1), Vector2.new(1, yt2 - yt1), ct, tr, 101)
		idx = self:rect(self.rs, idx, Vector2.new(x2, yt1), Vector2.new(1, yt2 - yt1), ct, tr, 101)
		idx = self:rect(self.rs, idx, Vector2.new(x1, yb1), Vector2.new(1, yb2 - yb1), cb, tr, 101)
		idx = self:rect(self.rs, idx, Vector2.new(x2, yb1), Vector2.new(1, yb2 - yb1), cb, tr, 101)
	end
	for n = idx, #self.rs do self.rs[n].Visible = false end
	for n = (oon and oi or 1), #self.rso do self.rso[n].Visible = false end
end

function Esp:drawGradBox(corn, c1, c2, tr, ocol, oon, otr)
	local tl, br = corn.tl, corn.br
	local x1, y1 = tl.X, tl.Y
	local x2, y2 = br.X - 1, br.Y - 1
	local W, H = x2 - x1 + 1, y2 - y1 + 1
	if W <= 0 or H <= 0 then
		self:hideRects(self.rs)
		self:hideRects(self.rso)
		return
	end
	local N = math.min(24, H)
	local idx = 1
	idx = self:rect(self.rs, idx, Vector2.new(x1, y1), Vector2.new(W, 1), c1, tr, 101)
	idx = self:rect(self.rs, idx, Vector2.new(x1, y2), Vector2.new(W, 1), c2, tr, 101)
	for s = 1, N do
		local a1, a2 = fl(H*(s-1)/N), fl(H*s/N)
		if a2 <= a1 then a2 = a1 + 1 end
		local ya, yb = y1 + a1, y1 + a2
		local cm = lc(c1, c2, ((a1 + a2)*0.5)/H)
		idx = self:rect(self.rs, idx, Vector2.new(x1, ya), Vector2.new(1, yb - ya), cm, tr, 101)
		idx = self:rect(self.rs, idx, Vector2.new(x2, ya), Vector2.new(1, yb - ya), cm, tr, 101)
	end
	for n = idx, #self.rs do self.rs[n].Visible = false end
	self:hideRects(self.rso)
end

function Esp:gLine(pool, a, b, c1, c2, tr, thick)
	local N = 10
	for i = 1, N do
		local f1, f2 = (i-1)/N, i/N
		local o = pool[i]
		if not o then
			o = self:_c("Line", { Thickness = thick, Visible = false })
			pool[i] = o
		end
		o.From = l2(a, b, f1)
		o.To = l2(a, b, f2)
		o.Color = lc(c1, c2, (f1+f2)*0.5)
		o.Transparency = tr
		o.Visible = true
	end
	for i = N + 1, #pool do pool[i].Visible = false end
end
function Esp:Upd()
    local itf = self.itf
    local sh = sharedFor(itf, self.plr)
    local opt = sh.opt
    self.opt = opt
    if not self.plr or not self.plr.Parent then
        self.en = false
        self.char = nil
        self.onSc = false
        if self.charCache then cl(self.charCache) else self.charCache = {} end
        self.cacheValid = false
        self.skpts = nil
        self._hd = nil
        self:disconnectCharEvents()
        return
    end
    
    local newChar = sh.char
    if newChar ~= self.char then
        self.char = newChar
        if self.charCache then cl(self.charCache) else self.charCache = {} end
        self.cacheValid = false
        self.childCnt = 0
        self.cacheChar = nil
        self.skpts = nil
        self.dir = nil
        self._hd = nil
        self._arSnap = true
        self:setupCharEvents(newChar)
    end
    
    self.en = sh.en

    if not self.en then
        self.onSc = false
        self.cacheValid = false
        self.skpts = nil
        return
    end

    self.hp, self.maxHp = itf.getHp(self.plr)
    self.arm = itf.getArm(self.plr)
	self.wep = opt.wep and itf.getWep(self.plr) or nil

    local hd = self._hd
    if not hd or hd.Parent ~= self.char then
        hd = self.char and fc(self.char, "Head") or nil
        self._hd = hd
    end
    if not hd or not hd.Parent then
        cl(self.charCache)
        self.cacheValid = false
        self.skpts = nil
        self.onSc = false
        return
    end

    local activeCam = cam
    local cloneInfo = sh.clone
    local viewport = cloneInfo and cloneInfo.viewport
    
    if viewport then
        if not genv.VISUALS_TAB_OPEN then
            self.onSc = false
            return
        end
        activeCam = viewport.CurrentCamera or cam
    end

    self.viewport = viewport
    self.activeCam = activeCam

    local _, onSc, dep = self.customW2s(hd.Position)
    self.onSc = onSc
    self.dis = dep

    if itf.shSet.limDis and dep > itf.shSet.maxDis then
        self.onSc = false
    end

    if self.onSc then
		if opt.skel then
			self:updateSkel()
		else
			self.skpts = nil
		end
        
        if #self.charCache == 0 or not self.cacheValid then
            self:rebuildCache()
        end
        
        if #self.charCache == 0 then
            self.onSc = false
            return
        end
        
        local cf, sz = getBB(self.charCache)
        
        if not cf or not sz then
            self.onSc = false
            self.cacheValid = false
            return
        end
        
        if viewport then
            self.corn = calcCornViewport(cf, sz, activeCam, viewport)
        else
            self.corn = calcCorn(cf, sz, self._cornT, self._cornPts)
        end
    elseif opt.offAr and not cloneInfo then
        local sp, _, sd = self.customW2s(hd.Position)
        local d = sp - vs*0.5
        if sd <= 0 then d = -d end
        local dm = d.Magnitude
        if dm > 0.001 then
            self.dir = d/dm
        else
            local cf = activeCam.CFrame
            local flt = fm(cf.Position, cf.RightVector, Vector3.yAxis)
            local obj = pos(flt, hd.Position)
            local pl = Vector2.new(obj.X, obj.Z)
            local pm = pl.Magnitude
            self.dir = pm > 0.001 and pl/pm or self.dir or Vector2.new(0, -1)
        end
    end
end
function Esp:Ren(dt)
	local onSc = self.onSc or false
	local en = self.en or false
	if en then
		self._blank = false
	elseif self._blank then
		return
	else
		self._blank = true
	end
	local v = self.draw.v
	local b3d = self.draw.b3d
	local itf = self.itf
	local opt = self.opt
	local corn = self.corn
	local shSet = itf.shSet
	local tSz = shSet.tSz
	local tFnt = shSet.tFnt
	local ten = itf.tSet.en
	local cloneInfo = itf._clones[self.plr]

	local boxOn = en and onSc and opt.box
	local corner = opt.boxType == "Corners"
	local grd = opt.boxGrd
	if not boxOn then
		v.b.Visible = false
		v.bo.Visible = false
		self.ob.Visible = false
		self.obk.Visible = false
		self:hideGrad(self.cn)
		self:hideGrad(self.cnk)
		self:hideRects(self.rs)
		self:hideRects(self.rso)
	elseif corner then
		v.b.Visible = false
		v.bo.Visible = false
		self.ob.Visible = false
		self.obk.Visible = false
		self:hideGrad(self.cn)
		self:hideGrad(self.cnk)
		self:drawCorners(corn,
			grd and opt.boxGrdCol[1] or parseC(self, opt.boxCol[1]),
			opt.boxGrdCol[2], grd, opt.boxCol[2],
			parseC(self, opt.boxOCol[1], true), opt.boxO, opt.boxOCol[2])
	elseif grd then
		v.b.Visible = false
		self.ob.Visible = false
		self.obk.Visible = false
		self:hideGrad(self.cn)
		self:hideGrad(self.cnk)
		self:drawGradBox(corn,
			opt.boxGrdCol[1], opt.boxGrdCol[2], opt.boxCol[2],
			parseC(self, opt.boxOCol[1], true), opt.boxO, opt.boxOCol[2])
		v.bo.Visible = opt.boxO
		if v.bo.Visible then
			local bo = v.bo
			bo.Position = corn.tl
			bo.Size = corn.br - corn.tl
			bo.Color = parseC(self, opt.boxOCol[1], true)
			bo.Transparency = opt.boxOCol[2]
			ensureZ(bo, 100)
		end
	else
		self.ob.Visible = false
		self.obk.Visible = false
		self:hideGrad(self.cn)
		self:hideGrad(self.cnk)
		self:hideRects(self.rs)
		self:hideRects(self.rso)
		v.b.Visible = true
		local b = v.b
		b.Position = corn.tl
		b.Size = corn.br - corn.tl
		b.Color = parseC(self, opt.boxCol[1])
		b.Transparency = opt.boxCol[2]
		ensureZ(b, 101)
		v.bo.Visible = opt.boxO
		if v.bo.Visible then
			local bo = v.bo
			bo.Position = corn.tl
			bo.Size = corn.br - corn.tl
			bo.Color = parseC(self, opt.boxOCol[1], true)
			bo.Transparency = opt.boxOCol[2]
			ensureZ(bo, 100)
		end
	end

	local fillOn = boxOn and opt.boxF
	if fillOn and opt.boxFGrd then
		v.bf.Visible = false
		self.gf.Position = UDim2.fromOffset(corn.tl.X, corn.tl.Y)
		self.gf.Size = UDim2.fromOffset(corn.br.X - corn.tl.X, corn.br.Y - corn.tl.Y)
		local gc1, gc2 = opt.boxFGrdCol[1], opt.boxFGrdCol[2]
		if self._gfgA ~= gc1 or self._gfgB ~= gc2 then
			self._gfgA = gc1
			self._gfgB = gc2
			self.gfg.Color = ColorSequence.new(gc1, gc2)
		end
		self.gf.BackgroundTransparency = 1 - opt.boxFCol[2]
		self.gf.Visible = true
	else
		self.gf.Visible = false
		v.bf.Visible = fillOn
		if fillOn then
			local bf = v.bf
			bf.Position = corn.tl
			bf.Size = corn.br - corn.tl
			bf.Color = parseC(self, opt.boxFCol[1])
			bf.Transparency = opt.boxFCol[2]
		end
	end

	local hbOn = en and onSc and opt.hb
	v.hbo.Visible = hbOn and opt.hbo
	if hbOn then
		local fr = corn.tl - HB_OFF
		local to = corn.bl - HB_OFF
		local top = l2(to, fr, self.hp/self.maxHp)

		if opt.hbGrd then
			v.hb.Visible = false
			self:gLine(self.ghb, top, to, opt.hbGrdCol[1], opt.hbGrdCol[2], 1, 1)
		else
			self:hideGrad(self.ghb)
			v.hb.Visible = true
			local hb = v.hb
			hb.To = to
			hb.From = top
			hb.Color = lc(opt.dyCol, opt.hlCol, self.hp/self.maxHp)
		end

		local hbo = v.hbo
		hbo.To = to + HO_OFF
		hbo.From = fr - HO_OFF
		hbo.Color = parseC(self, opt.hboCol[1], true)
		hbo.Transparency = opt.hboCol[2]
	else
		v.hb.Visible = false
		self:hideGrad(self.ghb)
	end

	local htOn = en and onSc and opt.hb and opt.ht
	if htOn then
		local fr = corn.tl - HB_OFF
		local to = corn.bl - HB_OFF
		local ht = v.ht
		local hpR = rd(self.hp)
		if self._hpN ~= hpR then
			self._hpN = hpR
			self._hpS = hpR .. "hp"
		end
		ht.Text = self._hpS
		ht.Size = tSz
		ht.Font = tFnt
		ht.Outline = opt.htOut
		ht.OutlineColor = parseC(self, opt.htOCol, true)
		local anchor = l2(to, fr, self.hp/self.maxHp) - HT_OFF
		if opt.htGrd then
			ht.Visible = false
			self:gradTxt(self.gtH, ht.Text, anchor.X - ht.TextBounds.X*0.5, anchor.Y - ht.TextBounds.Y*0.5, tSz, tFnt, opt.htOut, parseC(self, opt.htOCol, true), opt.htCol[2], opt.htGrdCol[1], opt.htGrdCol[2], self.ph)
		else
			self:hideGrad(self.gtH)
			ht.Visible = true
			ht.Color = parseC(self, opt.htCol[1])
			ht.Transparency = opt.htCol[2]
			ht.Position = anchor - ht.TextBounds*0.5
		end
	else
		v.ht.Visible = false
		self:hideGrad(self.gtH)
	end

	v.ab.Visible = en and onSc and opt.ab
	v.abo.Visible = v.ab.Visible and opt.abo
	if v.ab.Visible then
		local fr = corn.tr + AB_OFF
		local to = corn.br + AB_OFF
		local maxArm = 200

		local ab = v.ab
		ab.To = to
		ab.From = l2(to, fr, self.arm/maxArm)
		ab.Color = opt.abCol[1]

		local abo = v.abo
		abo.To = to + AO_OFF
		abo.From = fr - AO_OFF
		abo.Color = parseC(self, opt.aboCol[1], true)
		abo.Transparency = opt.aboCol[2]
	end

	v.at.Visible = en and onSc and opt.at
	if v.at.Visible then
		local fr = corn.tr + AB_OFF
		local to = corn.br + AB_OFF
		local maxArm = 200

		local at = v.at
		local armR = rd(self.arm)
		if self._armN ~= armR then
			self._armN = armR
			self._armS = armR .. "ap"
		end
		at.Text = self._armS
		at.Size = tSz
		at.Font = tFnt
		at.Color = parseC(self, opt.atCol[1])
		at.Transparency = opt.atCol[2]
		at.Outline = opt.atOut
		at.OutlineColor = parseC(self, opt.atOCol, true)
		at.Position = l2(to, fr, self.arm/maxArm) - Vector2.new(0, at.TextBounds.Y * 0.5) + AT_OFF
	end

	local nameOn = en and onSc and opt.name
	if nameOn then
		local n = v.n
		n.Size = tSz
		n.Font = tFnt
		n.Outline = opt.nOut
		n.OutlineColor = parseC(self, opt.nOCol, true)
		n.Text = self.plr.DisplayName
		local cx = (corn.tl.X + corn.tr.X)*0.5
		local topY = (corn.tl.Y + corn.tr.Y)*0.5 - n.TextBounds.Y - N_OFF.Y
		if opt.nGrd and not n.Text:find("[^%z\1-\127]") then
			n.Visible = false
			self:gradTxt(self.gtN, n.Text, cx, topY, tSz, tFnt, opt.nOut, parseC(self, opt.nOCol, true), opt.nCol[2], opt.nGrdCol[1], opt.nGrdCol[2], self.ph)
		else
			self:hideGrad(self.gtN)
			n.Visible = true
			n.Color = parseC(self, opt.nCol[1])
			n.Transparency = opt.nCol[2]
			n.Position = Vector2.new(cx, topY)
		end
	else
		v.n.Visible = false
		self:hideGrad(self.gtN)
	end

	local avOn = en and onSc and opt.av
	self.av.Visible = avOn
	if avOn then
		local as = tSz + 6
		self.av.Size = UDim2.fromOffset(as, as)
		local uid = self.plr.UserId
		if self.avId ~= uid then
			self.avId = uid
			self.av.Image = "rbxthumb://type=AvatarHeadShot&id=" .. tostring(uid) .. "&w=48&h=48"
		end
		local cx = (corn.tl.X + corn.tr.X)*0.5
		local midY = (corn.tl.Y + corn.tr.Y)*0.5
		if opt.name then
			local nh = v.n.TextBounds.Y
			self.av.Position = UDim2.fromOffset(cx + v.n.TextBounds.X*0.5 + as*0.5 + 4, midY - nh*0.5 - N_OFF.Y)
		else
			self.av.Position = UDim2.fromOffset(cx, midY - as*0.5 - N_OFF.Y)
		end
	end

	local flagOff = 0
	local flagOn = en and onSc and ten.flag
	if flagOn then
		local role = itf.roles[self.plr.Name]
		if role == "Murderer" or role == "Sheriff" then
			local fl = v.fl
			local mur = role == "Murderer"
			fl.Size = tSz
			fl.Font = tFnt
			fl.Outline = true
			fl.OutlineColor = Color3.new()
			fl.Text = mur and "MURDERER" or "SHERIFF"
			local colT = mur and ten.flagMurCol or ten.flagShfCol
			local grd = mur and ten.flagMurGrd or ten.flagShfGrd
			local grdCol = mur and ten.flagMurGrdCol or ten.flagShfGrdCol
			local cx = (corn.bl.X + corn.br.X)*0.5
			local topY = (corn.bl.Y + corn.br.Y)*0.5 + D_OFF.Y
			if grd then
				fl.Visible = false
				self:gradTxt(self.gtF, fl.Text, cx, topY, tSz, tFnt, true, Color3.new(), colT[2], grdCol[1], grdCol[2], self.ph)
			else
				self:hideGrad(self.gtF)
				fl.Visible = true
				fl.Color = colT[1]
				fl.Transparency = colT[2]
				fl.Position = Vector2.new(cx, topY)
			end
			flagOff = fl.TextBounds.Y
		else
			v.fl.Visible = false
			self:hideGrad(self.gtF)
		end
	else
		v.fl.Visible = false
		self:hideGrad(self.gtF)
	end

	local distOn = en and onSc and self.dis and opt.dis
	if distOn then
		local d = v.d
		local disR = rd(self.dis)
		if self._disN ~= disR then
			self._disN = disR
			self._disS = disR .. " studs"
		end
		d.Text = self._disS
		d.Size = tSz
		d.Font = tFnt
		d.Outline = opt.dOut
		d.OutlineColor = parseC(self, opt.dOCol, true)
		local cx = (corn.bl.X + corn.br.X)*0.5
		local topY = (corn.bl.Y + corn.br.Y)*0.5 + D_OFF.Y + flagOff
		if opt.dGrd then
			d.Visible = false
			self:gradTxt(self.gtD, d.Text, cx, topY, tSz, tFnt, opt.dOut, parseC(self, opt.dOCol, true), opt.dCol[2], opt.dGrdCol[1], opt.dGrdCol[2], self.ph)
		else
			self:hideGrad(self.gtD)
			d.Visible = true
			d.Color = parseC(self, opt.dCol[1])
			d.Transparency = opt.dCol[2]
			d.Position = Vector2.new(cx, topY)
		end
	else
		v.d.Visible = false
		self:hideGrad(self.gtD)
	end

	v.w.Visible = en and onSc and opt.wep and self.wep ~= nil
	if v.w.Visible then
		local w = v.w
		w.Text = self.wep
		w.Size = tSz
		w.Font = tFnt
		w.Color = parseC(self, opt.wCol[1])
		w.Transparency = opt.wCol[2]
		w.Outline = opt.wOut
		w.OutlineColor = parseC(self, opt.wOCol, true)
		w.Position = (corn.bl + corn.br)*0.5 + (v.d.Visible and D_OFF + Vector2.yAxis*v.d.TextBounds.Y or Vector2.zero)
	end

	v.tr.Visible = en and onSc and opt.tr
	v.tro.Visible = v.tr.Visible and opt.tro
	if v.tr.Visible then
		local tr = v.tr
		tr.Color = parseC(self, opt.trCol[1])
		tr.Transparency = opt.trCol[2]
		tr.To = (corn.bl + corn.br)*0.5
		tr.From =
			opt.trOrg == "Middle" and vs*0.5 or
			opt.trOrg == "Top" and vs*Vector2.new(0.5, 0) or
			opt.trOrg == "Bottom" and vs*Vector2.new(0.5, 1)

		local tro = v.tro
		tro.Color = parseC(self, opt.troCol[1], true)
		tro.Transparency = opt.troCol[2]
		tro.To = tr.To
		tro.From = tr.From
	end

	local dir = self.dir
	if en and (not onSc) and opt.offAr and dir and not cloneInfo then
		local img = arGet()
		local mag = math.sqrt(dir.X*dir.X + dir.Y*dir.Y)
		if img ~= "" and mag > 1e-4 then
			local sz = opt.offArSz or 42
			local cx, cy = vs.X*0.5, vs.Y*0.5
			local dis = opt.offArDis or 260
			local lim = math.max(0, math.min(cx, cy) - sz*0.5)
			if dis > lim then dis = lim end
			local dx, dy = dir.X/mag, dir.Y/mag
			local rk = roleKey(self)
			local rc = rk == "Mur" and opt.offArColMur or rk == "Shf" and opt.offArColShf or rk == "Hero" and opt.offArColHero or rk == "None" and opt.offArColNone or opt.offArColInno
			local arC = self.arC
			local arI = self.arI
			arC.Size = UDim2.fromOffset(rd(sz), rd(sz))
			arC.Position = UDim2.fromOffset(rd(cx + dx*dis), rd(cy + dy*dis))
			arC.Visible = true
			if arI.Image ~= img then arI.Image = img end
			arI.Rotation = math.deg(math.atan2(dy, dx)) + 90
			arI.ImageColor3 = parseC(self, rc[1], true)
			arI.ImageTransparency = 1 - rc[2]
			arI.Visible = true
		else
			self.arC.Visible = false
		end
	else
		self.arC.Visible = false
	end

	local b3dEn = en and onSc and opt.b3d
	if b3dEn then
		self._b3dOff = false
		local b3col = parseC(self, opt.b3dCol[1])
		local b3tr = opt.b3dCol[2]
		local cs3 = corn.corners
		for i = 1, #b3d do
			local f = b3d[i]
			for i2 = 1, #f do
				local ln = f[i2]
				ln.Visible = true
				ln.Color = b3col
				ln.Transparency = b3tr
			end

			local l1 = f[1]
			l1.From = cs3[i]
			l1.To = cs3[i == 4 and 1 or i+1]

			local l2 = f[2]
			l2.From = cs3[i == 4 and 1 or i+1]
			l2.To = cs3[i == 4 and 5 or i+5]

			local l3 = f[3]
			l3.From = cs3[i == 4 and 5 or i+5]
			l3.To = cs3[i == 4 and 8 or i+4]
		end
	elseif not self._b3dOff then
		self._b3dOff = true
		for i = 1, #b3d do
			local f = b3d[i]
			for i2 = 1, #f do
				f[i2].Visible = false
			end
		end
	end
	local skelEn = en and onSc and opt.skel
	local skel = self.draw.skel
	local gskel = self.draw.gskel

	if skelEn and self.skpts then
		self._skOff = false
		local pts = self.skpts
		local w2sFunc = self.customW2s or w2sc
		drwln(self, opt, w2sFunc, skel.hd, pts.hd, pts.ur)
		drwln(self, opt, w2sFunc, skel.nt, pts.ur, pts.lr)
		drwln(self, opt, w2sFunc, skel.ls, pts.ur, pts.lua)
		drwln(self, opt, w2sFunc, skel.rs, pts.ur, pts.rua)
		drwln(self, opt, w2sFunc, skel.la, pts.lua, pts.lfa)
		drwln(self, opt, w2sFunc, skel.ra, pts.rua, pts.rfa)
		drwln(self, opt, w2sFunc, skel.ll, pts.lr, pts.lul)
		drwln(self, opt, w2sFunc, skel.rl, pts.lr, pts.rul)
		drwln(self, opt, w2sFunc, skel.bh, pts.lul, pts.lll)
		if not self.draw.skel.rlb then
			self.draw.skel.rlb = self:_c("Line", { Thickness = 2, Visible = false })
			self.draw.gskel.rlb = self:_c("Line", { Thickness = 3, Visible = false })
			table.insert(self.bin, self.draw.skel.rlb)
			table.insert(self.bin, self.draw.gskel.rlb)
		end
		
		drwln(self, opt, w2sFunc, skel.rlb, pts.rul, pts.rll)
		
		if opt.gskel then
			drwln(self, opt, w2sFunc, gskel.hd, pts.hd, pts.ur)
			drwln(self, opt, w2sFunc, gskel.nt, pts.ur, pts.lr)
			drwln(self, opt, w2sFunc, gskel.ls, pts.ur, pts.lua)
			drwln(self, opt, w2sFunc, gskel.rs, pts.ur, pts.rua)
			drwln(self, opt, w2sFunc, gskel.la, pts.lua, pts.lfa)
			drwln(self, opt, w2sFunc, gskel.ra, pts.rua, pts.rfa)
			drwln(self, opt, w2sFunc, gskel.ll, pts.lr, pts.lul)
			drwln(self, opt, w2sFunc, gskel.rl, pts.lr, pts.rul)
			drwln(self, opt, w2sFunc, gskel.bh, pts.lul, pts.lll)
			drwln(self, opt, w2sFunc, gskel.rlb, pts.rul, pts.rll)
			
			for _, ln in pairs(gskel) do
				if ln.Visible then
					ln.Color = parseC(self, opt.gskelCol[1], true)
					ln.Transparency = opt.gskelCol[2]
				end
			end
		else
			for _, ln in pairs(gskel) do ln.Visible = false end
		end
	elseif not self._skOff then
		self._skOff = true
		for _, ln in pairs(skel) do ln.Visible = false end
		for _, ln in pairs(gskel) do ln.Visible = false end
	end
end
function Esp:updateSkel()
    if not self.char or not self.onSc then 
        self.skpts = nil
        return 
    end
    
    local char = self.char
    local sp = self._skparts
    if not sp then
        sp = {}
        self._skparts = sp
    end
    
    if self._skchar ~= char or not self.cacheValid then
        self._skchar = char
        sp.hd = findPart(char, "Head")
        sp.ur = findPart(char, "UpperTorso") or findPart(char, "Torso")
        sp.lr = findPart(char, "LowerTorso") or findPart(char, "Torso")
        sp.lua = findPart(char, "LeftUpperArm") or findPart(char, "Left Arm")
        sp.rua = findPart(char, "RightUpperArm") or findPart(char, "Right Arm")
        sp.lfa = findPart(char, "LeftLowerArm") or findPart(char, "LeftHand")
        sp.rfa = findPart(char, "RightLowerArm") or findPart(char, "RightHand")
        sp.lul = findPart(char, "LeftUpperLeg") or findPart(char, "Left Leg")
        sp.rul = findPart(char, "RightUpperLeg") or findPart(char, "Right Leg")
        sp.lll = findPart(char, "LeftLowerLeg") or findPart(char, "LeftFoot")
        sp.rll = findPart(char, "RightLowerLeg") or findPart(char, "RightFoot")
    end
    
    local hd = sp.hd
    if not hd or not hd.Parent then
        self.skpts = nil
        return
    end
    
    local skpts = self._skpts
    if not skpts then
        skpts = {}
        self._skpts = skpts
    end
    cl(skpts)
    
    local ur, lr = sp.ur, sp.lr
    local lua, rua = sp.lua, sp.rua
    local lfa, rfa = sp.lfa, sp.rfa
    local lul, rul = sp.lul, sp.rul
    local lll, rll = sp.lll, sp.rll
    
    skpts.hd = hd.CFrame.Position
    if ur and ur.Parent then skpts.ur = ur.CFrame.Position end
    if lr and lr.Parent then skpts.lr = lr.CFrame.Position end
    if lua and lua.Parent then skpts.lua = lua.CFrame.Position end
    if rua and rua.Parent then skpts.rua = rua.CFrame.Position end
    if lfa and lfa.Parent then skpts.lfa = lfa.CFrame.Position end
    if rfa and rfa.Parent then skpts.rfa = rfa.CFrame.Position end
    if lul and lul.Parent then skpts.lul = lul.CFrame.Position end
    if rul and rul.Parent then skpts.rul = rul.CFrame.Position end
    if lll and lll.Parent then skpts.lll = lll.CFrame.Position end
    if rll and rll.Parent then skpts.rll = rll.CFrame.Position end
    
    self.skpts = skpts
end

local Chromatic = {
	Presets = {
		Chromatic = {
			{Scale = 1.012, Alpha = 0.025, Material = Enum.Material.Foil, Reflectance = 0.12, ColorMode = "Base"}
		},
		Pearlescent = {
