			{Scale = 1.018, Alpha = 0.42, Material = Enum.Material.Neon, Reflectance = 0, ColorMode = "Pearl"}
		},
		Chrome = {
			{Scale = 1.008, Alpha = 0.02, Material = Enum.Material.Metal, Reflectance = 0.55, ColorMode = "Base"},
			{Scale = 1.018, Alpha = 0.55, Material = Enum.Material.Glass, Reflectance = 0.35, ColorMode = "Highlight"}
		},
		Crystal = {
			{Scale = 1.006, Alpha = 0.2, Material = Enum.Material.Glass, Reflectance = 0.22, ColorMode = "Base"},
			{Scale = 1.02, Alpha = 0.62, Material = Enum.Material.Neon, Reflectance = 0, ColorMode = "Highlight"}
		},
		Candy = {
			{Scale = 1.007, Alpha = 0.03, Material = Enum.Material.SmoothPlastic, Reflectance = 0.32, ColorMode = "Base"},
			{Scale = 1.016, Alpha = 0.5, Material = Enum.Material.Neon, Reflectance = 0.05, ColorMode = "Candy"}
		}
	}
}

local CHROM_STATE_STRIDE = 3
local CHROM_PAD_X = 180
local CHROM_PAD_Y = 220
local CHROM_HIDE_DELAY = 90
local CHROM_SHOW_BUDGET = 2

function Chromatic:Ensure(count)
	local worlds = self.Worlds
	if not worlds then
		worlds = {}
		self.Worlds = worlds
		self.Views = {}
	end
	local have = #worlds
	if have >= count then return end
	local sky = game:GetService("Lighting"):FindFirstChildOfClass("Sky")
	for i = have + 1, count do
		local view = Instance.new("ViewportFrame")
		view.Name = "ChromaticLayer" .. i
		view.Size = UDim2.fromScale(1, 1)
		view.BackgroundTransparency = 1
		view.BorderSizePixel = 0
		view.ZIndex = i
		view.Ambient = Color3.new(1, 1, 1)
		view.LightColor = Color3.new(1, 1, 1)
		view.LightDirection = Vector3.new(-1, -1, -1)
		view.CurrentCamera = ws.CurrentCamera
		view.Parent = avGui
		if sky then sky:Clone().Parent = view end
		local world = Instance.new("WorldModel")
		world.Name = "ChromaticWorld"
		world.Parent = view
		self.Views[i] = view
		self.Worlds[i] = world
	end
end

function Chromatic:BeginFrame()
	if self.Frame == frameId then return self.Camera end
	self.Frame = frameId
	self.ShowBudget = CHROM_SHOW_BUDGET
	local camera = ws.CurrentCamera
	self.Camera = camera
	if not camera then return nil end
	self.Origin = camera.CFrame.Position
	local size = camera.ViewportSize
	self.MaxX = size.X + CHROM_PAD_X
	self.MaxY = size.Y + CHROM_PAD_Y
	local views = self.Views
	if views then
		for i = 1, #views do
			if views[i].CurrentCamera ~= camera then
				views[i].CurrentCamera = camera
			end
		end
	end
	return camera
end

function Chromatic:TakeShow()
	local budget = self.ShowBudget
	if not budget or budget <= 0 then return false end
	self.ShowBudget = budget - 1
	return true
end

local Cham = {}
Cham.__index = Cham

function Cham.new(p, itf)
	local self = setmetatable({}, Cham)
	self.plr = assert(p, "No player")
	self.itf = assert(itf, "No interface")
	self:init()
	return self
end

function Cham:init()
	self.hl = Instance.new("Highlight", gui)
	self.hl.Enabled = false
	self.hl.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
	self.matCache = {}
	self.acc = math.random() * 0.15
	self.charConnections = {}
	self.parts = {}
	self.partsValid = false
	self.chromaticDirty = true
end

function Cham:Dest()
	if self.hl then self.hl:Destroy() end
	self:ClearChromatic()
	self:ClearOcclusion()
	self:RestoreMaterials()
	self:disconnectCharEvents()
	cl(self)
end

function Cham:disconnectCharEvents()
	if not self.charConnections then return end
	for _, conn in pairs(self.charConnections) do
		if conn and conn.Disconnect then
			conn:Disconnect()
		end
	end
	self.charConnections = {}
end

function Cham:setupCharEvents(char)
	self:disconnectCharEvents()
	if not char then return end
	local function onPart(desc)
		if isCP(desc) then
			self.partsValid = false
			self.chromaticDirty = true
		end
	end
	self.charConnections.descendantAdded = char.DescendantAdded:Connect(onPart)
	self.charConnections.descendantRemoving = char.DescendantRemoving:Connect(onPart)
end

function Cham:getParts(char)
	if self.partsChar ~= char then
		self.partsChar = char
		self.partsValid = false
		local matCache = self.matCache
		if matCache then
			for part in pairs(matCache) do
				if not part.Parent then matCache[part] = nil end
			end
		end
		self:setupCharEvents(char)
	end
	local parts = self.parts
	if not parts then
		parts = {}
		self.parts = parts
	end
	if not self.partsValid then
		cl(parts)
		local descs = char:GetDescendants()
		local n = 0
		for i = 1, #descs do
			local part = descs[i]
			if isCP(part) then
				n = n + 1
				parts[n] = part
			end
		end
		self.partsValid = true
	end
	return parts
end

function Cham:SaveMaterials(char)
	if not char then return end
	local parts = self:getParts(char)
	local matCache = self.matCache
	for i = 1, #parts do
		local part = parts[i]
		if isCP(part) and not matCache[part] then
			local entry = {
				Material = part.Material,
				Color = part.Color,
				Reflectance = part.Reflectance
			}
			if part:IsA("MeshPart") then
				local ok, tex = pcall(function() return part.TextureID end)
				if ok then entry.TextureID = tex end
			end
			local mesh = part:FindFirstChildWhichIsA("SpecialMesh")
			if mesh then
				entry.Mesh = mesh
				entry.MeshTexture = mesh.TextureId
			end
			local surf = part:FindFirstChildWhichIsA("SurfaceAppearance")
			if surf then entry.Surface = surf end
			local variant = part.MaterialVariant
			if variant ~= "" then entry.Variant = variant end
			matCache[part] = entry
		end
	end
end

function Cham:RestoreMaterials()
	for part, data in pairs(self.matCache) do
		local surf = data.Surface
		if surf and surf.Parent ~= part and part and part.Parent then
			pcall(function() surf.Parent = part end)
		end
		if part and part.Parent then
			part.Material = data.Material
			part.Color = data.Color
			part.Reflectance = data.Reflectance
			if data.Variant then pcall(function() part.MaterialVariant = data.Variant end) end
			if data.TextureID then pcall(function() part.TextureID = data.TextureID end) end
		end
		local mesh = data.Mesh
		if mesh and mesh.Parent and data.MeshTexture then
			mesh.TextureId = data.MeshTexture
		end
	end
	cl(self.matCache)
end

function Cham:ApplyMaterials(char, col)
	if not char then return end
	self:SaveMaterials(char)
	local parts = self:getParts(char)
	local matCache = self.matCache
	for i = 1, #parts do
		local part = parts[i]
		if isCP(part) then
			local data = matCache[part]
			if data then
				local surf = data.Surface
				if surf and surf.Parent then
					pcall(function() surf.Parent = nil end)
				end
				if data.Variant then pcall(function() part.MaterialVariant = "" end) end
				if data.TextureID and data.TextureID ~= "" then
					pcall(function() part.TextureID = "" end)
				end
				local mesh = data.Mesh
				if mesh and mesh.Parent and data.MeshTexture ~= "" then
					mesh.TextureId = ""
				end
			end
			part.Reflectance = 0
			part.Material = Enum.Material.ForceField
			part.Color = col
		end
	end
end

local function chromaticColor(color, config)
	if config.ColorMode == "Pearl" then
		return color:Lerp(Color3.fromRGB(255, 125, 245), 0.45)
	elseif config.ColorMode == "Highlight" then
		return color:Lerp(Color3.new(1, 1, 1), 0.68)
	elseif config.ColorMode == "Candy" then
		return color:Lerp(Color3.fromRGB(255, 55, 125), 0.38)
	end
	return color
end

local function cloneChromaticPart(source, config, color)
	local clone = safeClone(source)
	if not clone then return nil end
	local children = clone:GetChildren()
	for i = 1, #children do
		if not children[i]:IsA("DataModelMesh") then
			children[i]:Destroy()
		end
	end
	local mesh = clone:FindFirstChildWhichIsA("DataModelMesh")
	if mesh then
		mesh.Scale = mesh.Scale * config.Scale
		if mesh:IsA("FileMesh") then mesh.TextureId = "" end
	else
		clone.Size = clone.Size * config.Scale
	end
	if clone:IsA("MeshPart") then clone.TextureID = "" end
	clone.MaterialVariant = ""
	clone.Anchored = true
	clone.Massless = true
	clone.CanCollide = false
	clone.CanQuery = false
	clone.CanTouch = false
	clone.CastShadow = false
	clone.LocalTransparencyModifier = 0
	clone.Material = config.Material
	clone.Reflectance = config.Reflectance
	clone.Transparency = config.Alpha
	clone.Color = chromaticColor(color, config)
	clone.CFrame = source.CFrame
	return clone
end

function Cham:SetChromaticParented(parented)
	local state = self.chromatic
	if not state or state.Parented == parented then return end
	state.Parented = parented
	local models = state.Models
	local parents = state.Parents
	for i = 1, #models do
		models[i].Parent = parented and parents[i] or nil
	end
	state.HideAt = nil
	if parented then state.Tick = CHROM_STATE_STRIDE end
end

function Cham:ClearChromatic()
	local state = self.chromatic
	if state then
		local models = state.Models
		for i = 1, #models do
			models[i]:Destroy()
		end
	end
	self.chromatic = nil
	self.chromaticChar = nil
	self.chromaticDirty = true
end

function Cham:ApplyChromatic(char, color, style)
	if not char then return end
	style = Chromatic.Presets[style] and style or "Chromatic"
	local configs = Chromatic.Presets[style]
	local parts = self:getParts(char)
	local partCount = #parts
	local layerCount = #configs
	local state = self.chromatic
	local rebuild = not state or self.chromaticChar ~= char or self.chromaticDirty or state.Count ~= partCount or state.Style ~= style
	if rebuild then
		self:ClearChromatic()
		Chromatic:Ensure(layerCount)
		local worlds = Chromatic.Worlds
		local models = cr(layerCount)
		local parents = cr(layerCount)
		local layers = cr(layerCount)
		local alphas = cr(layerCount)
		state = {
			Char = char,
			Models = models,
			Parents = parents,
			Layers = layers,
			Alphas = alphas,
			Sources = {},
			Cframes = {},
			Hidden = {},
			N = 0,
			LayerCount = layerCount,
			Count = partCount,
			Color = color,
			Style = style,
			Configs = configs,
			Parented = false,
			Tick = CHROM_STATE_STRIDE
		}
		for layer = 1, layerCount do
			local world = worlds[layer]
			local model = Instance.new("Model")
			model.Name = "ChromaticChr"
			models[layer] = model
			parents[layer] = world
			layers[layer] = {}
			alphas[layer] = configs[layer].Alpha
		end
		local characterMeshes = {}
		local meshCount = 0
		local children = char:GetChildren()
		for i = 1, #children do
			if children[i]:IsA("CharacterMesh") then
				meshCount = meshCount + 1
				characterMeshes[meshCount] = children[i]
			end
		end
		if meshCount > 0 then
			local sourceHumanoid = char:FindFirstChildOfClass("Humanoid")
			for layer = 1, layerCount do
				local model = models[layer]
				local humanoid = sourceHumanoid and sourceHumanoid:Clone() or Instance.new("Humanoid")
				humanoid:ClearAllChildren()
				humanoid.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
				humanoid.Parent = model
				for i = 1, meshCount do
					local mesh = characterMeshes[i]:Clone()
					mesh.BaseTextureId = 0
					mesh.OverlayTextureId = 0
					mesh.Parent = model
				end
			end
		end
		local sources = state.Sources
		local cfs = state.Cframes
		local hidden = state.Hidden
		local staged = cr(layerCount)
		local n = 0
		for i = 1, partCount do
			local source = parts[i]
			if isCP(source) and not isDeformable(source) then
				local ok = true
				for layer = 1, layerCount do
					local clone = cloneChromaticPart(source, configs[layer], color)
					staged[layer] = clone
					if not clone then ok = false end
				end
				if ok then
					n = n + 1
					sources[n] = source
					cfs[n] = staged[1].CFrame
					hidden[n] = false
					for layer = 1, layerCount do
						local clone = staged[layer]
						clone.Parent = models[layer]
						layers[layer][n] = clone
					end
				else
					for layer = 1, layerCount do
						local clone = staged[layer]
						if clone then clone:Destroy() end
					end
				end
			end
		end
		state.N = n
		self.chromatic = state
		self.chromaticChar = char
		self.chromaticDirty = false
	elseif state.Color ~= color then
		state.Color = color
		local layers = state.Layers
		local n = state.N
		for layer = 1, state.LayerCount do
			local clones = layers[layer]
			local col = chromaticColor(color, configs[layer])
			for i = 1, n do
				clones[i].Color = col
			end
		end
	end
end

function Cham:ClearOcclusion()
	if self.occModel then self.occModel:Destroy() self.occModel = nil end
	if self.losHl then self.losHl:Destroy() self.losHl = nil end
	if self.occHl then self.occHl:Destroy() self.occHl = nil end
	self.occChar = nil
end

function Cham:ApplyOcclusion(char, visCol, visT, occCol, occT)
	if not char then return end
	if not char:IsDescendantOf(ws) then
		self:ClearOcclusion()
		return
	end
	if self.occChar ~= char or not self.occModel or not self.occModel.Parent then
		self:ClearOcclusion()
		self.occChar = char
		local model = Instance.new("Model")
		model.Name = "ChamsChr"
		local parts = self:getParts(char)
		for i = 1, #parts do
			local child = parts[i]
			local cloned = (isCP(child) and not isDeformable(child)) and safeClone(child) or nil
			if cloned then
				cloned:ClearAllChildren()
				cloned.Anchored = false
				cloned.CanCollide = false
				cloned.CanQuery = false
				cloned.CanTouch = false
				cloned.Massless = true
				cloned.CastShadow = false
				cloned.LocalTransparencyModifier = 0
				if cloned:IsA("MeshPart") then pcall(function() cloned.TextureID = "" end) end
				cloned.Size = cloned.Size * 0.99
				cloned.CFrame = child.CFrame
				cloned.Parent = model
				local weld = Instance.new("WeldConstraint")
				weld.Part0 = cloned
				weld.Part1 = child
				weld.Parent = cloned
			end
		end
		model.Parent = ws
		self.occModel = model

		local los = Instance.new("Highlight")
		los.DepthMode = Enum.HighlightDepthMode.Occluded
		los.OutlineTransparency = 1
		los.Adornee = char
		los.Parent = gui
		self.losHl = los

		local occ = Instance.new("Highlight")
		occ.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
		occ.OutlineTransparency = 1
		occ.Adornee = model
		occ.Parent = gui
		self.occHl = occ
	end
	self.losHl.FillColor = visCol
	self.losHl.FillTransparency = visT
	self.occHl.FillColor = occCol
	self.occHl.FillTransparency = occT
end

function Cham:Upd(dt)
	local hl = self.hl
	local itf = self.itf
	if not self.plr or not self.plr.Parent then
		if self._hlOn ~= false then
			self._hlOn = false
			hl.Enabled = false
		end
		self:ClearChromatic()
		self:ClearOcclusion()
		self:RestoreMaterials()
		return
	end

	local sh = sharedFor(itf, self.plr)
	local char = sh.char
	local opt = sh.opt
	local en = sh.en

	local cloneInfo = sh.clone
	local rkk = RK_KEYS[roleKey(self)]

	local hlOn = (en and opt.chams and not cloneInfo) and true or false
	if self._hlOn ~= hlOn then
		self._hlOn = hlOn
		hl.Enabled = hlOn
	end
	if hlOn then
		local fcol = opt[rkk.chamsF]
		local ocol = opt[rkk.chamsO]
		local fCol = parseC(self, fcol[1])
		local fTr = fcol[2]
		local oCol = parseC(self, ocol[1], true)
		local oTr = opt.chamsOutlineEnabled == false and 1 or ocol[2]
		if self._hlAd ~= char then
			self._hlAd = char
			hl.Adornee = char
		end
		if self._hlFC ~= fCol then
			self._hlFC = fCol
			hl.FillColor = fCol
		end
		if self._hlFT ~= fTr then
			self._hlFT = fTr
			hl.FillTransparency = fTr
		end
		if self._hlOC ~= oCol then
			self._hlOC = oCol
			hl.OutlineColor = oCol
		end
		if self._hlOT ~= oTr then
			self._hlOT = oTr
			hl.OutlineTransparency = oTr
		end
	end

	self.acc = (self.acc or 0) + (dt or 0)
	if self.acc < 0.15 then return end
	self.acc = 0

	if en and opt.matChams and char and self.plr ~= lp then
		if opt.matChamsType == "Flat" then
			self:ClearChromatic()
			self:RestoreMaterials()
			if cloneInfo then
				self:ClearOcclusion()
			else
				local visCol = opt[rkk.matVis]
				local occCol = opt[rkk.matOcc]
				self:ApplyOcclusion(char,
					parseC(self, visCol[1]), visCol[2],
					parseC(self, occCol[1]), occCol[2])
			end
		elseif opt.matChamsType == "Chromatic" then
			self:ClearOcclusion()
			self:RestoreMaterials()
			if cloneInfo then
				self:ClearChromatic()
			else
				self:ApplyChromatic(char, parseC(self, opt[rkk.matCol]), opt.matChamsStyle or "Chromatic")
			end
		else
			self:ClearChromatic()
			self:ClearOcclusion()
			self:ApplyMaterials(char, parseC(self, opt[rkk.matCol]))
		end
	else
		self:ClearChromatic()
		self:ClearOcclusion()
		self:RestoreMaterials()
	end
end

function Cham:Ren()
	local state = self.chromatic
	if not state then return end
	local sh = sharedFor(self.itf, self.plr)
	local opt = sh.opt
	if not (sh.en and opt.matChams and opt.matChamsType == "Chromatic" and not sh.clone and self.plr ~= lp and sh.char == state.Char) then
		self:SetChromaticParented(false)
		return
	end
	local camera = Chromatic:BeginFrame()
	if not camera then
		self:SetChromaticParented(false)
		return
	end
	local char = state.Char
	local root = state.Root
	if not root or root.Parent ~= char then
		root = fc(char, "HumanoidRootPart") or fc(char, "UpperTorso") or fc(char, "Torso")
		if root and not isA(root, "BasePart") then root = nil end
		state.Root = root
	end
	if not root then
		self:SetChromaticParented(false)
		return
	end
	local rootPos = root.Position
	local settings = self.itf.shSet
	if settings.limDis and (rootPos - Chromatic.Origin).Magnitude > settings.maxDis then
		self:SetChromaticParented(false)
		return
	end
	local point = w2s(camera, rootPos)
	local onScreen = point.Z > 0
		and point.X > -CHROM_PAD_X and point.X < Chromatic.MaxX
		and point.Y > -CHROM_PAD_Y and point.Y < Chromatic.MaxY
	if onScreen then
		state.HideAt = nil
		if not state.Parented then
			if not Chromatic:TakeShow() then return end
			self:SetChromaticParented(true)
		end
	elseif state.Parented then
		local hideAt = state.HideAt
		if not hideAt then
			state.HideAt = frameId + CHROM_HIDE_DELAY
		elseif frameId >= hideAt then
			self:SetChromaticParented(false)
			return
		end
	else
		return
	end

	local n = state.N
	if n == 0 then return end
	local tick = state.Tick + 1
	local refresh = tick >= CHROM_STATE_STRIDE
	state.Tick = refresh and 0 or tick

	local sources = state.Sources
	local cfs = state.Cframes
	local hidden = state.Hidden
	local layers = state.Layers
	local alphas = state.Alphas
	local layerCount = state.LayerCount

	if layerCount == 1 then
		local clones = layers[1]
		local alpha = alphas[1]
		for i = 1, n do
			local source = sources[i]
			local isHidden = hidden[i]
			if refresh then
				local nowHidden
				if source.Parent then
					nowHidden = source.Transparency >= 1 or source.LocalTransparencyModifier >= 1
				else
					nowHidden = true
				end
				if isHidden ~= nowHidden then
					isHidden = nowHidden
					hidden[i] = nowHidden
					clones[i].Transparency = nowHidden and 1 or alpha
				end
			end
			if not isHidden then
				local cf = source.CFrame
				if cfs[i] ~= cf then
					cfs[i] = cf
					clones[i].CFrame = cf
				end
			end
		end
	else
		for i = 1, n do
			local source = sources[i]
			local isHidden = hidden[i]
			if refresh then
				local nowHidden
				if source.Parent then
					nowHidden = source.Transparency >= 1 or source.LocalTransparencyModifier >= 1
				else
					nowHidden = true
				end
				if isHidden ~= nowHidden then
					isHidden = nowHidden
					hidden[i] = nowHidden
					for layer = 1, layerCount do
						layers[layer][i].Transparency = nowHidden and 1 or alphas[layer]
					end
				end
			end
			if not isHidden then
				local cf = source.CFrame
				if cfs[i] ~= cf then
					cfs[i] = cf
					for layer = 1, layerCount do
						layers[layer][i].CFrame = cf
					end
				end
			end
		end
	end
end
local Inst = {}
Inst.__index = Inst

function Inst.new(i, opt)
	local self = setmetatable({}, Inst)
	self.inst = assert(i, "No instance")
	self.opt = assert(opt, "No options")
	self:init()
	return self
end

function Inst:init()
	local opt = self.opt
	opt.en = opt.en == nil and true or opt.en
	opt.txt = opt.txt or "{name}"
	opt.txtCol = opt.txtCol or { Color3.new(1,1,1), 1 }
	opt.txtOut = opt.txtOut == nil and true or opt.txtOut
	opt.txtOCol = opt.txtOCol or Color3.new()
	opt.txtSz = opt.txtSz or 14
	opt.txtFnt = opt.txtFnt or 2
	opt.limDis = opt.limDis or false
	opt.maxDis = opt.maxDis or 150
	opt.txtGrd = opt.txtGrd or false
	opt.txtGrdCol = opt.txtGrdCol or { Color3.new(1,1,1), Color3.new(1,0,0) }

	self.txt = regDraw("Text")
	self.txt.Center = true
	self.gtxt = {}
	self.ph = math.random()
end

function Inst:drawGrad(text, cx, cy, sz, fnt, out, oc, tr, c1, c2, off)
	local pool = self.gtxt
	local n = #text
	local widths = self._gw or {}
	self._gw = widths
	local total = 0
	for i = 1, n do
		local o = pool[i]
		if not o then
			o = regDraw("Text")
			o.Center = false
			pool[i] = o
		end
		if o.Size ~= sz then o.Size = sz end
		if o.Font ~= fnt then o.Font = fnt end
		local ch = text:sub(i, i)
		if o.Text ~= ch then o.Text = ch end
		local wd = o.TextBounds.X
		widths[i] = wd
		total = total + wd
	end
	for i = n + 1, #pool do pool[i].Visible = false end
	local x = cx - total*0.5
	for i = 1, n do
		local o = pool[i]
		o.Color = gradS(c1, c2, n > 1 and (i-1)/(n-1) or 0, off)
		o.Transparency = tr
		o.Outline = out
		o.OutlineColor = oc
		o.Position = Vector2.new(x, cy)
		o.Visible = true
		x = x + widths[i]
	end
end

function Inst:hideGrad()
	for i = 1, #self.gtxt do self.gtxt[i].Visible = false end
end

function Inst:Dest()
	if self._dead then return end
	self._dead = true
	pcall(self.txt.Remove, self.txt)
	local pool = self.gtxt
	for i = 1, #pool do
		pcall(pool[i].Remove, pool[i])
	end
	cl(pool)
end

function Inst:Ren()
	if self._dead then return end
	local inst = self.inst
	if not inst or not inst.Parent then
		return self:Dest()
	end

	local txt = self.txt
	local opt = self.opt
	if not opt.en then
		txt.Visible = false
		self:hideGrad()
		return
	end

	local w = gp(inst).Position
	local pos, vis, dep = w2sc(w)
	if opt.limDis and dep > opt.maxDis then
		vis = false
	end

	if not vis then
		txt.Visible = false
		self:hideGrad()
		return
	end

	local s = opt.txt
		:gsub("{name}", inst.Name)
		:gsub("{distance}", rd(dep))
		:gsub("{position}", tostring(w))

	if opt.txtGrd and not s:find("[^%z\1-\127]") then
		txt.Visible = false
		self:drawGrad(s, pos.X, pos.Y, opt.txtSz, opt.txtFnt, opt.txtOut, opt.txtOCol, opt.txtCol[2], opt.txtGrdCol[1], opt.txtGrdCol[2], self.ph)
	else
		self:hideGrad()
		txt.Visible = true
		txt.Position = pos
		txt.Color = opt.txtCol[1]
		txt.Transparency = opt.txtCol[2]
		txt.Outline = opt.txtOut
		txt.OutlineColor = opt.txtOCol
		txt.Size = opt.txtSz
		txt.Font = opt.txtFnt
		txt.Text = s
	end
end

