function Itf.AddInst(i, opt)
	local c = Itf._objCache
	if c[i] then
		warn("Instance handler exists.")
	else
		c[i] = { Inst.new(i, opt) }
	end
	return c[i][1]
end

function Itf.Load()
	assert(not Itf._loaded, "Already loaded.")

	local function add(p)
		Itf._objCache[p] = {
			Esp.new(p, Itf),
			Cham.new(p, Itf)
		}
	end

	local function rem(p)
		local o = Itf._objCache[p]
		if o then
			for i = 1, #o do
				o[i]:Dest()
			end
			Itf._objCache[p] = nil
		end
	end

	local ps = plrs:GetPlayers()
	for i = 1, #ps do
		add(ps[i])
	end

	Itf.pAdd = plrs.PlayerAdded:Connect(add)
	Itf.pRem = plrs.PlayerRemoving:Connect(rem)
	local menuHidden = false
	Itf.mainRender = run.RenderStepped:Connect(function(dt)
		if root.Visible then
			if not menuHidden then
				menuHidden = true
				for _, objs in next, Itf._objCache do
					local cham = objs[2]
					if cham and getmetatable(cham) == Cham then
						cham.hl.Enabled = false
						cham._hlOn = false
						cham:ClearChromatic()
						cham:ClearOcclusion()
						cham:RestoreMaterials()
					end
				end
			end
			return
		end
		menuHidden = false
		cam = ws.CurrentCamera
		if not cam then return end
		frameId = frameId + 1
		vs = cam.ViewportSize
		maskStep()
		for _, objs in next, Itf._objCache do
			for i = 1, #objs do
				local obj = objs[i]
				if obj.Upd then
					obj:Upd(dt)
				end
				if obj.Ren then
					obj:Ren(dt)
				end
			end
		end
	end)
	
	local validatorIndex = 1
	local validatorDelay = 0
	local allPlayers = {}
	Itf.cacheValidator = run.Heartbeat:Connect(function(dt)
		validatorDelay = validatorDelay + dt
		if validatorDelay < 0.1 then return end
		validatorDelay = 0
		
		cl(allPlayers)
		local pn = 0
		for plr, _ in next, Itf._objCache do
			pn = pn + 1
			allPlayers[pn] = plr
		end
		
		if pn == 0 then return end
		
		local checksPerFrame = math.max(1, math.ceil(pn / 10))
		
		for i = 1, checksPerFrame do
			validatorIndex = validatorIndex + 1
			if validatorIndex > pn then
				validatorIndex = 1
			end
			
			local plr = allPlayers[validatorIndex]
			local objs = Itf._objCache[plr]
			
			if objs and objs[1] and objs[1].validateCache then
				if not objs[1]:validateCache() then
					objs[1].cacheValid = false
				end
			end
		end
	end)
	
	Itf._loaded = true
end

function Itf.AddClone(cloneModel, realPlayer, viewport)
	if not Itf._loaded then return end
	
	local fakePlayer = setmetatable({
		Character = cloneModel,
		DisplayName = realPlayer.DisplayName,
		Name = "__CLONE__" .. realPlayer.Name,
		UserId = realPlayer.UserId,
		Parent = realPlayer.Parent,
		Team = realPlayer.Team
	}, {__index = realPlayer})
	
	Itf._clones[fakePlayer] = {
		viewport = viewport,
		isClone = true
	}
	
	Itf._objCache[fakePlayer] = {
		Esp.new(fakePlayer, Itf),
		Cham.new(fakePlayer, Itf)
	}
	
	return fakePlayer
end

function Itf.RemoveClone(fakePlayer)
	if not Itf._loaded or not fakePlayer then return end
	
	local o = Itf._objCache[fakePlayer]
	if o then
		for i = 1, #o do
			o[i]:Dest()
		end
		Itf._objCache[fakePlayer] = nil
	end
	
	Itf._clones[fakePlayer] = nil
end

function Itf.UpdateClone(fakePlayer, newClone)
	if not Itf._loaded or not fakePlayer then return end
	
	if Itf._clones[fakePlayer] then
		fakePlayer.Character = newClone
	end
end

function Itf.Unload()
	assert(Itf._loaded, "Not loaded.")

	if Itf.mainRender then
		Itf.mainRender:Disconnect()
		Itf.mainRender = nil
	end
	
	if Itf.cacheValidator then
		Itf.cacheValidator:Disconnect()
		Itf.cacheValidator = nil
	end

	for idx, o in next, Itf._objCache do
		for i = 1, #o do
			o[i]:Dest()
		end
		Itf._objCache[idx] = nil
	end

	Itf.pAdd:Disconnect()
	Itf.pRem:Disconnect()
	Itf._loaded = false
end

function Itf.getWep(p)
	local char = p and p.Character
	local tool = typeof(char) == "Instance" and char:FindFirstChildOfClass("Tool")
	return tool and tool.Name or nil
end

function Itf.isFr(p)
	return p.Team and p.Team == lp.Team
end

function Itf.getTC(p)
	return p.Team and p.Team.TeamColor and p.Team.TeamColor.Color
end

function Itf.getChar(p)
	return p.Character
end

function Itf.getHp(p)
	local char = p and Itf.getChar(p)
	if not char then return 100, 100 end
	local e = charInfo(char)
	local hum = e.hum
	if not hum or hum.Parent ~= char then
		hum = fcc(char, "Humanoid")
		e.hum = hum
	end
	if hum then
		return hum.Health, hum.MaxHealth
	end
	return 100, 100
end

function Itf.getArm(p)
    local char = p and Itf.getChar(p)
    if not char then return 0 end
    local e = charInfo(char)
    local arm = e.arm
    if not arm or not arm.Parent then
        local be = fc(char, "BodyEffects")
        arm = be and fc(be, "Armor") or nil
        e.arm = arm
    end
    if arm then
        return arm.Value
    end
    return 0
end

return Itf
	end)()

task.spawn(function()
	for _, obj in ipairs(workspace:GetDescendants()) do
		if (obj:IsA("BasePart") and obj.Name == "GlowShell")
			or (obj:IsA("Model") and (obj.Name == "GlowChr" or obj.Name == "ChamsChr")) then
			pcall(function() obj:Destroy() end)
		end
	end
end)

local roleThreadConns = {}
local roleThread = task.spawn(function()
	local rs = game:GetService("ReplicatedStorage")
	local players = game:GetService("Players")

	local round_module = nil
	local function get_module()
		if round_module then return round_module end
		local ok, m = pcall(function()
			return require(rs:WaitForChild("Modules"):WaitForChild("CurrentRoundClient"))
		end)
		if ok and type(m) == "table" then round_module = m end
		return round_module
	end

	local map = {}
	local role_dirty = false

	local function rebuild()
		if not (esp and esp.tSet and (esp.tSet.en.flag or esp.tSet.en.chams or esp.tSet.en.matChams or esp.tSet.en.offAr)) then return end
		local m = get_module()
		local data = m and m.PlayerData
		table.clear(map)
		if type(data) == "table" then
			for name, d in pairs(data) do
				if type(d) == "table" and d.Role then
					if not ((d.Role == "Sheriff" or d.Role == "Hero") and d.Dead) then
						map[name] = d.Role
					end
				end
			end
		end
		for _, p in ipairs(players:GetPlayers()) do
			local char = p.Character
			local bp = p:FindFirstChildOfClass("Backpack")
			local hasGun = (char and char:FindFirstChild("Gun")) or (bp and bp:FindFirstChild("Gun"))
			if hasGun and map[p.Name] ~= "Murderer" and map[p.Name] ~= "Hero" then
				map[p.Name] = "Sheriff"
			end
		end
		esp.roles = map
	end

	local m = get_module()
	if m and m.PlayerDataChanged then
		pcall(function()
			roleThreadConns[#roleThreadConns + 1] = m.PlayerDataChanged.Event:Connect(function()
				role_dirty = true
			end)
		end)
	end

	local hooked_containers = setmetatable({}, { __mode = "k" })

	local function hook_gun_container(container)
		if not container or hooked_containers[container] then return end
		hooked_containers[container] = true
		roleThreadConns[#roleThreadConns + 1] = container.ChildAdded:Connect(function(c)
			if c.Name == "Gun" then role_dirty = true end
		end)
		roleThreadConns[#roleThreadConns + 1] = container.ChildRemoved:Connect(function(c)
			if c.Name == "Gun" then role_dirty = true end
		end)
	end
	local function hook_char(char)
		hook_gun_container(char)
	end
	local function hook_player(p)
		if p.Character then hook_char(p.Character) end
		roleThreadConns[#roleThreadConns + 1] = p.CharacterAdded:Connect(function(char)
			hook_char(char)
			hook_gun_container(p:FindFirstChildOfClass("Backpack"))
			role_dirty = true
		end)
		hook_gun_container(p:FindFirstChildOfClass("Backpack"))
		roleThreadConns[#roleThreadConns + 1] = p.ChildAdded:Connect(function(child)
			if child:IsA("Backpack") then
				hook_gun_container(child)
				role_dirty = true
			end
		end)
	end
	for _, p in ipairs(players:GetPlayers()) do
		pcall(hook_player, p)
	end
	roleThreadConns[#roleThreadConns + 1] = players.PlayerAdded:Connect(function(p)
		pcall(hook_player, p)
	end)

	while task.wait(0.15) do
		role_dirty = false
		rebuild()
	end
end)

