		Callback = function(model, item)
			local plr = game:GetService("Players").LocalPlayer

			_G.VIEWPORT_PLAYER = plr
			_G.VIEWPORT_CLONE = model
			_G.VIEWPORT_FRAME = item.viewport
			if esp._loaded and type(env.__FBVisualsPaintPreview) ~= "function" then
				if _G.FAKE_PLAYER then esp.RemoveClone(_G.FAKE_PLAYER) end
				_G.FAKE_PLAYER = esp.AddClone(model, plr, item.viewport)
			end
			if type(env.__FBVisualsPaintPreview) == "function" then
				task.defer(env.__FBVisualsPaintPreview)
