		local skybox_name = "Jungle"

		getgenv().WORLD_TIME_ENABLED = false
		getgenv().WORLD_EXPOSURE_ENABLED = false
		getgenv().WORLD_SKYBOX_ENABLED = false

		local skyboxes = {
