				if basic and basic.get() then basic.set(false) end
			end
			esp.tSet.en.en = v
			if v and not esp._loaded then
				esp.Load()
				if _G.VIEWPORT_CLONE and _G.VIEWPORT_PLAYER and _G.VIEWPORT_FRAME and type(env.__FBVisualsPaintPreview) ~= "function" then
					_G.FAKE_PLAYER = esp.AddClone(_G.VIEWPORT_CLONE, _G.VIEWPORT_PLAYER, _G.VIEWPORT_FRAME)
				end
			elseif not v and esp._loaded then
				if _G.FAKE_PLAYER then
					esp.RemoveClone(_G.FAKE_PLAYER)
					_G.FAKE_PLAYER = nil
				end
				esp.Unload()
			end
		end
