			if getgenv().WORLD_SKYBOX_ENABLED then
				for _, sky in ipairs(lighting:GetChildren()) do
					if sky:IsA("Sky") and sky.Name == "CustomSky" then sky:Destroy() end
				end
				getgenv().WORLD_SKYBOX_ENABLED = false
			end
		end)
		if esp and esp._loaded then pcall(function() esp.Unload() end) end
	end
end

