	-- Potassium and other executors expose either Destroy or the older Remove on
	-- Drawing objects. All cleanup paths go through one compatibility helper.
	local function destroyAny(object)
		if not object then return end;
		drawn[object] = nil;
		pcall(function() object.Visible = false end);
		local destroyed = pcall(function() object:Destroy() end);
		if not destroyed then pcall(function() object:Remove() end) end;
	end;

	-- Large games can contain hundreds of thousands of descendants. Building one
	-- giant GetDescendants array and then yielding for every small slice used to
	-- hold startup open for several seconds. Walk only the requested roots in the
	-- background and release the scheduler between bounded batches instead.
	local function scanDescendantsAsync(label, roots, visit, keepGoing, batchSize)
		local stack = {};
		if typeof(roots) == "Instance" then roots = { roots } end;
		for index = #(roots or {}), 1, -1 do stack[#stack + 1] = roots[index] end;
		batchSize = math.max(64, tonumber(batchSize) or 512);

		return task.spawn(function()
			local ok, err = pcall(function()
				local remaining = batchSize;
				while #stack > 0 and ALIVE and GLOBAL.__InertiaFBGeneration == INIT_GENERATION do
					if keepGoing and not keepGoing() then return end;
					local node = stack[#stack];
					stack[#stack] = nil;
					local gotChildren, children = pcall(function() return node:GetChildren() end);
					if gotChildren then
						for index = #children, 1, -1 do
							local child = children[index];
							if visit(child) ~= false then stack[#stack + 1] = child end;
							remaining -= 1;
							if remaining <= 0 then
								remaining = batchSize;
								task.wait();
								if keepGoing and not keepGoing() then return end;
							end;
						end;
					end;
				end;
			end);
			if not ok and ALIVE and GLOBAL.__InertiaFBGeneration == INIT_GENERATION then
				recordError((label or "background scan") .. ": " .. tostring(err));
			end;
		end);
	end;

