	-- ------------------------------------------------------------- remote ----
	-- Everything arrives at start in two blobs (bundle.pack and sky.pack, fetched
	-- in parallel). Each body is written out, traded for an asset id, pulled into
	-- the engine and only then deleted, so once the load is done nothing of ours
	-- is left sitting in the workspace and nothing is fetched later. A sky's six
	-- faces stay in memory until that sky is picked.
	local Remote = {};
	Remote.Status = { build = BUILD_ID, reused = 0, written = 0, failed = 0, timeouts = 0, removed = 0, retained = 0 };
	function Remote.current() return ALIVE and GLOBAL.__InertiaFBGeneration == INIT_GENERATION end;
	local pendingInvocations = 0;
	function Remote.invoke(fn, seconds)
		if not Remote.current() then return false, nil, "cancelled" end;
		if pendingInvocations >= 16 then return false, nil, "busy" end;
		pendingInvocations += 1;
		local done, abandoned, result = false, false, nil;
		task.spawn(function()
			local values = table.pack(pcall(fn));
			pendingInvocations -= 1;
			if not abandoned then result = values; done = true end;
		end);
		local deadline = os.clock() + seconds;
		while not done and Remote.current() and os.clock() < deadline do task.wait(0.03) end;
		if not done or not Remote.current() then
			abandoned = true;
			-- Native executor HTTP/preload calls may resume their thread later.
			-- Discard late results instead of cancelling that resumable coroutine.
			return false, nil, Remote.current() and "timeout" or "cancelled";
		end;
		return result[1], result[2];
	end;
	function Remote.io(fn)
		if Remote.Status.cacheBlocked then return false, nil end;
		local ok, value, reason = Remote.invoke(fn, 3);
		if reason == "timeout" then
			Remote.Status.cacheBlocked = true;
			Remote.Status.lastIssue = "cache I/O timed out; UI continues without the cache";
		end;
		return ok, value;
	end;

	local pendingObjectLoads = 0;
	local UNWANTED = {
		LuaSourceContainer = true, ScreenGui = true,
		RemoteEvent = true, RemoteFunction = true, BindableEvent = true, BindableFunction = true,
		ClickDetector = true, ProximityPrompt = true,
	};
	local function strip(root)
		if typeof(root) ~= "Instance" then return end;
		for class in pairs(UNWANTED) do
			if root:IsA(class) then pcall(function() root:Destroy() end); return end;
		end;
		for _, descendant in ipairs(root:GetDescendants()) do
			for class in pairs(UNWANTED) do
				if descendant:IsA(class) then pcall(function() descendant:Destroy() end); break end;
			end;
		end;
	end;
	Remote.strip = strip;
	function Remote.objects(fn, seconds)
		if not Remote.current() or pendingObjectLoads >= 8 then return false, nil end;
		pendingObjectLoads += 1;
		local done, expired, ok, objects = false, false, false, nil;
		task.spawn(function()
			local success, roots = pcall(fn);
			pendingObjectLoads -= 1;
			if expired or not Remote.current() then
				if type(roots) == "table" then
					for _, root in ipairs(roots) do pcall(function() root:Destroy() end) end;
				end;
				return;
			end;
			if type(roots) == "table" then
				for _, root in ipairs(roots) do strip(root) end;
			end;
			ok, objects, done = success, roots, true;
		end);
		local deadline = os.clock() + (seconds or 12);
		while not done and Remote.current() and os.clock() < deadline do task.wait(0.03) end;
		if not done or not Remote.current() then expired = true; return false, nil end;
		return ok, objects;
	end;

	do
		local HttpService = game:GetService("HttpService");

		Remote.base = type(GLOBAL.VISUALS_REMOTE) == "string" and GLOBAL.VISUALS_REMOTE or "";
		Remote.api = type(GLOBAL.VISUALS_API) == "string" and GLOBAL.VISUALS_API or "https://inertiahub.xyz";
		Remote.packUrls = {};

		if Remote.base ~= "" and not string.find(Remote.base, "/$") then
			Remote.base = Remote.base .. "/";
		end;

		local grab = (syn and syn.request) or (http and http.request)
			or (getgenv and (rawget(getgenv(), "http_request") or rawget(getgenv(), "request")))
			or http_request or request;

		local requestSerial, failedUntil = 0, {};

		-- every fetch from the host is counted, so the loading badge knows
		-- when there is something on the wire
		Remote.Load = { active = 0, done = 0, total = 0, listeners = {} };
		function Remote.busy()
			local L, open = Remote.Load, true;
			L.active += 1;
			L.total += 1;
			for _, fn in ipairs(L.listeners) do pcall(fn) end;
			return function()
				if not open then return end;
				open = false;
				L.active = math.max(L.active - 1, 0);
				L.done += 1;
				for _, fn in ipairs(L.listeners) do pcall(fn) end;
			end;
		end;

		local function fetchUrl(url, seconds)
			seconds = seconds or 12;
			if not Remote.current() or (failedUntil[url] or 0) > os.clock() then return nil end;
			local original = url;
			if Remote.base ~= "" and url:sub(1, #Remote.base) == Remote.base then
				requestSerial += 1;
				url = url .. (url:find("?", 1, true) and "&" or "?") .. "v=" .. BUILD_ID
					.. "&request=" .. INIT_GENERATION .. "-" .. requestSerial .. "-" .. tostring(DateTime.now().UnixTimestampMillis);
			end;
			if type(grab) == "function" then
				local ok, res = Remote.invoke(function()
					return grab({ Url = url, Method = "GET", Timeout = seconds,
						Headers = { ["Cache-Control"] = "no-cache", Accept = "application/octet-stream" } });
				end, seconds);

				if ok and type(res) == "table" and (tonumber(res.StatusCode) or 0) == 200
					and type(res.Body) == "string" and #res.Body > 0 and not res.Body:match("^%s*<") then
					return res.Body;
				end;
			end;

			if not Remote.current() then return nil end;
			local ok, body = Remote.invoke(function() return game:HttpGet(url, true) end, seconds);
			if ok and type(body) == "string" and #body > 0 and not body:match("^%s*<") then return body end;
			failedUntil[original] = os.clock() + 15;
			Remote.Status.lastIssue = "asset HTTP failed or timed out";
			return nil;
		end;

		local function download(url, seconds)
			if not Remote.current() or (failedUntil[url] or 0) > os.clock() then return nil end;
			local finish = Remote.busy();
			local ok, body = pcall(fetchUrl, url, seconds);
			finish();
			return ok and body or nil;
		end;

		Remote.download = download;

		-- 109 of the hosted files have spaces in the name. Encoded per segment so
		-- the slashes survive.
		local function urlPath(rel)
			local out = {};

			for piece in string.gmatch(rel, "[^/]+") do
				out[#out + 1] = (string.gsub(piece, "[^%w%-%._~]", function(c)
					return string.format("%%%02X", string.byte(c));
				end));
			end;

			return table.concat(out, "/");
		end;

		Remote.urlPath = urlPath;
		local custom = getcustomasset or getsynasset or (syn and syn.get_custom_asset)
			or (fluxus and fluxus.get_custom_asset);
		Remote.custom = custom;

		-- getcustomasset only reads real files, so every body has to touch the
		-- disk once on its way to an id. It lands here under a random opaque
		-- name. The extension
		-- stays because Roblox picks the decoder from it.
		local STORE = ROOT .. "/.assets";

		local function slug(text)
			LPH_ATTRIBUTES(VM(NONE));
			local hasher = rawget(GLOBAL, "crypt");

			if hasher and hasher.hash then
				local ok, hex = pcall(hasher.hash, text, "sha256");

				if ok and type(hex) == "string" and #hex >= 32 then return string.sub(hex, 1, 28) end;
			end;

			-- no crypt on this executor: a plain rolling hash is still opaque
			-- enough that a filename says nothing about its contents
			local a, b = 0x1505, 0x7fff;

			for index = 1, #text do
				local byte = string.byte(text, index);

				a = (a * 33 + byte) % 0xFFFFFFFF;
				b = (b * 31 + byte * index) % 0xFFFFFFFF;
				if index % 65536 == 0 then task.wait(); if not Remote.current() then return nil end end;
			end;

			return string.format("%08x%08x%04x", a, b, #text % 0xFFFF);
		end;

		local named, relativePaths, pendingAssets, retryAfter, assetBusy = {}, {}, {}, {}, {};

		function Remote.store() return STORE end;
