			local path = STORE .. "/" .. slug("logical-v2:" .. rel) .. (ext and ("." .. string.lower(ext)) or "");

			named[rel] = path;
			relativePaths[path] = rel;

			return path;
		end;

		local cacheFolderReady = false;
		local function folderFor()
			if cacheFolderReady then return true end;
			if Remote.Status.cacheBlocked then return false end;
			local function ensure(path)
				local ok, exists = Remote.io(function() return isfolder(path) end);
				if ok and exists then return true end;
				Remote.io(function() return makefolder(path) end);
				ok, exists = Remote.io(function() return isfolder(path) end);
				return ok and exists == true;
			end;
			if not (isfolder and makefolder) or not ensure(ROOT) then return false end;
			if ensure(STORE) then cacheFolderReady = true; return true end;
