			return decoded;
		end;

		local function isData(rel)
			local ext = string.lower(string.match(rel, "%.(%w+)$") or "");

			return ext == "json" or ext == "txt" or ext == "bin";
		end;

		local held, settling, nextHeld = {}, false, 1;
		local assetProbed, assetKeep, preloadBlocked = false, false, false;
		local temporary = {};
		local ContentProvider = game:GetService("ContentProvider");
