				-- not block unloading the UI if an executor stops responding.
				task.spawn(function() pcall(kill, path) end);
				return true;
			end;
			local ok = Remote.io(function() return kill(path) end);
			if not ok then return false end;
			if type(isfile) == "function" then
				local checked, exists;
				if unloading then checked, exists = pcall(isfile, path)
				else checked, exists = Remote.io(function() return isfile(path) end) end;
				if not checked or exists then return false end;
