			["murder/sounds/sparkle.ogg"] = 21582, ["murder/sounds/mc bow.ogg"] = 10428,
			["murder/sounds/click.ogg"] = 9756, ["murder/sounds/break.ogg"] = 6928,
			["murder/sounds/rust.ogg"] = 8211, ["murder/sounds/chirp.mp3"] = 26782,
			["murder/sounds/bell.wav"] = 42154, ["murder/sounds/bubble.wav"] = 32812,
			["murder/sounds/cod.wav"] = 11752, ["murder/sounds/connect.mp3"] = 18328,
			["murder/sounds/crowbar.wav"] = 140870, ["murder/sounds/bow.wav"] = 68098,
			["murder/sounds/pulse soft.wav"] = 152168, ["murder/sounds/metal soft.wav"] = 8910,
			["murder/sounds/headshot.wav"] = 68340, ["murder/sounds/voice.ogg"] = 34672,
