			return out;
		end;
		GLOBAL.salad_asset_bytes = function(name, body) return Remote.volatile("murder/sounds/" .. tostring(name), body) end;

		local function unmask(blob, seed)
			LPH_ATTRIBUTES(VM(NONE));
			local b = buffer.fromstring(blob);
			local n = buffer.len(b);
			local bxor, lshift, rshift = bit32.bxor, bit32.lshift, bit32.rshift;
			local readu32, writeu32 = buffer.readu32, buffer.writeu32;
			local x, i, stop, tick = seed, 4, n - 4, os.clock();
			while i <= stop do
