				writeu32(b, i, bxor(readu32(b, i), x));
				i += 4;
				if i % 16384 == 0 and os.clock() - tick > 0.004 then
					task.wait();
					if not Remote.current() then return nil end;
					tick = os.clock();
				end;
			end;
			x = bxor(x, lshift(x, 13)); x = bxor(x, rshift(x, 17)); x = bxor(x, lshift(x, 5));
			for at = i, n - 1 do
				buffer.writeu8(b, at, bxor(buffer.readu8(b, at), rshift(x, (at - i) * 8) % 256));
			end;
