		local signingPacks = false;
		function Remote.signPacks()
			if Remote.api == "" then return false end;
			if signingPacks then
				local deadline = os.clock() + 45;
				repeat task.wait(0.05) until not signingPacks or not Remote.current() or os.clock() >= deadline;
				return Remote.packUrls["bundle.pack"] ~= nil or Remote.packUrls["sky.pack"] ~= nil;
			end;
