			local ok, any = pcall(function()
				local requestPacks = GLOBAL.SALAD_ASSET_REQUEST;
				local body = type(requestPacks) == "function" and requestPacks("PACK", "packs") or nil;
				if type(body) ~= "string" or body == "" then return false end;
				local parsed, answer = pcall(function() return HttpService:JSONDecode(body) end);
				local urls = parsed and type(answer) == "table" and answer.ok and type(answer.data) == "table" and answer.data.urls;
				if type(urls) ~= "table" then return false end;
				local found = false;
				for _, pack in ipairs(Remote.packs) do
					local url = urls[pack];
					if type(url) == "string" and url:sub(1, 8) == "https://" then
						Remote.packUrls[pack] = url;
						found = true;
					end;
				end;
				return found;
			end);
			signingPacks = false;
			return ok and any or false;
		end;

		function Remote.sync(pack, report)
			local function decodePack(blob)
			LPH_ATTRIBUTES(VM(NONE));
			if type(blob) == "string" and string.sub(blob, 1, 4) == "SVP2" and PACK_SEEDS[pack] then
				blob = unmask(blob, PACK_SEEDS[pack]);
			end;

			if type(blob) ~= "string" or #blob < 8 or string.sub(blob, 1, 4) ~= "SVP1" then
				return 0, 1;
			end;

			local a, b, c, d = string.byte(blob, 5, 8);
			local headLen = a + b * 256 + c * 65536 + d * 16777216;
			if #blob > 256 * 1024 * 1024 or headLen < 2 or headLen > 1024 * 1024 or 8 + headLen > #blob then return 0, 1 end;

			local ok, head = pcall(function()
				return HttpService:JSONDecode(string.sub(blob, 9, 8 + headLen));
			end);

			if not (ok and type(head) == "table" and type(head.e) == "table") then
				return 0, 1;
			end;

			local list = head.e;
			local at = 8 + headLen;
			local total = #list;
			if total > 2048 then return 0, 1 end;
			local names, expected, slice = {}, 0, os.clock();
			local crypto = GLOBAL.crypt;
			local binaryHash = false;
			if crypto and type(crypto.hash) == "function" then
				local fine, digest = pcall(crypto.hash, "a\0b", "sha256");
				binaryHash = fine and digest == "59b271ae1bbcb1d31d41929817f4b16fb439eb4f31520b5ad1d5ce98920a7138";
			end;
			Remote.Status.integrity = binaryHash and "sha256" or "structure (executor hash is not binary-safe)";
			for index, entry in ipairs(list) do
				if type(entry) ~= "table" then return 0, 1 end;
				local rel, offset, size = entry[1], entry[2], entry[3];
				if type(rel) ~= "string" or #rel > 512 or rel == "" or rel:find("..", 1, true)
					or rel:find("\\", 1, true) or rel:sub(1, 1) == "/" or rel:find("[%z\1-\31]") or names[rel]
					or type(offset) ~= "number" or offset ~= offset or offset < 0 or offset % 1 ~= 0
					or type(size) ~= "number" or size ~= size or size < 1 or size % 1 ~= 0 or size > 32 * 1024 * 1024
					or (Remote.manifest and Remote.manifest.files and Remote.manifest.files[rel] ~= size)
					or offset ~= expected or offset + size > #blob - at then return 0, 1 end;
				if entry[4] ~= nil then
					if type(entry[4]) ~= "string" or #entry[4] ~= 64 or entry[4]:find("[^%da-f]") then return 0, 1 end;
					if binaryHash then
						local fine, digest = pcall(crypto.hash, blob:sub(at + offset + 1, at + offset + size), "sha256");
						if not fine or digest ~= entry[4] then return 0, 1 end;
					end;
				end;
				expected += size;
				names[rel] = true;
				if index % 8 == 0 and os.clock() - slice >= 0.008 then
					task.wait();
					if not ALIVE or GLOBAL.__InertiaFBGeneration ~= INIT_GENERATION then return 0, 1 end;
					slice = os.clock();
				end;
			end;
			if expected ~= #blob - at then return 0, 1 end;
			Remote.catalog = Remote.catalog or {};
			for rel in pairs(names) do Remote.catalog[rel] = true end;
			local done, failed, lastPct = 0, 0, 0;

			for index = 1, total do
				if not ALIVE or GLOBAL.__InertiaFBGeneration ~= INIT_GENERATION then settle(); return done, failed end;
				local entry = list[index];
				local rel, offset, size = entry[1], entry[2], entry[3];
				local body = string.sub(blob, at + offset + 1, at + offset + size);

				local kept;

				if isData(rel) then
					bodies[rel] = body;
					kept = true;
				else
					if not ids[rel] then pendingAssets[rel] = body; retryAfter[rel] = nil end;
					kept = true;
				end;

				if kept then done = done + 1 else failed = failed + 1 end;

				-- a hundred and sixty writes back to back hold the frame long
				-- enough that the game looks hung
				local pct = math.floor(index / total * 10);

				if pct > lastPct then
					lastPct = pct;

					if report then report(index, total) end;

					task.wait();
				end;
			end;

			settle();

			Remote.Status.failed = failed;
			return done, failed;
			end;
			if type(isfile) == "function" and type(readfile) == "function" then
				local copy = ROOT .. "/packs/" .. pack;
				local ok, found = Remote.io(function() return isfile(copy) end);
				if ok and found then
					local readOk, localPack = Remote.invoke(function() return readfile(copy) end, 30);
					if readOk and type(localPack) == "string" then
						local valid, done, missing = pcall(decodePack, localPack);
						if valid and missing == 0 and done > 0 then return done, 0 end;
					end;
				end;
			end;
			if not Remote.current() then return 0, 1 end;
			if Remote.base == "" and not Remote.packUrls[pack] then Remote.signPacks() end;
			local source = Remote.packUrls[pack] or (Remote.base ~= "" and (Remote.base .. pack));
			local blob = source and download(source, 240) or nil;
			if not blob then return 0, 1 end;
			local valid, done, missing = pcall(decodePack, blob);
			if valid then return done, missing end;
			Remote.Status.lastIssue = "asset pack decode failed";
			return 0, 1;
		end;

		onUnload("asset cache", function()
			for path in pairs(temporary) do drop(path, true) end;
			table.clear(held); table.clear(temporary);
			table.clear(pendingAssets); table.clear(encodedAssets); table.clear(bodies); table.clear(ids); table.clear(byPath);
		end);
	end;

	function Remote.bootstrap()
		local started = os.clock();
		Remote.Status.stage = "fetching";
		pcall(Remote.purge);

		local failed, pending = 0, 0;
		for _, pack in ipairs(Remote.packs) do
			pending += 1;
			task.spawn(function()
				local ok, _, missing = pcall(Remote.sync, pack);
				if not ok or (missing or 0) > 0 then
					failed += 1;
					warn("[visuals] " .. pack .. " unavailable");
				end;
				pending -= 1;
			end);
		end;
		while pending > 0 and Remote.current() do task.wait(0.1) end;

		Remote.Status.failed = failed;
		Remote.Status.stage = failed == 0 and "ready" or "failed";
		if failed > 0 then Remote.Status.lastIssue = "asset pack unavailable" end;
		Remote.Status.elapsed = os.clock() - started;
	end;
	local trackedConns = {}
	local FBCards = {}
	local SaladUI = {}
	SaladUI.ScreenGui = (function()
		local g = new("ScreenGui", { Name = "FBVisuals", ResetOnSpawn = false, ZIndexBehavior = Enum.ZIndexBehavior.Sibling })
		if not pcall(function() g.Parent = gethui and gethui() or game:GetService("CoreGui") end) or not g.Parent then
			g.Parent = LP:WaitForChild("PlayerGui")
		end
		return g
	end)()
	-- Highlights are not drawn inside a ScreenGui, and this gui sits in one, so
	-- every chams highlight lives in a folder under the camera; it follows the
	-- camera if the game swaps it
	SaladUI.FXHost = (function()
		local f = Instance.new("Folder")
		f.Name = HttpService:GenerateGUID(false):gsub("-", ""):sub(1, 12)
		f.Parent = workspace.CurrentCamera
		connectUI(workspace:GetPropertyChangedSignal("CurrentCamera"), function()
			if workspace.CurrentCamera then f.Parent = workspace.CurrentCamera end
		end)
		gui.Destroying:Connect(function() f:Destroy() end)
		return f
	end)()
	-- the preview panel hangs off this menu's window
	SaladUI.WindowFrame = root
	SaladUI.Mobile = MOBILE
	SaladUI.AccentColor = C.accent
	SaladUI.Lib = lib
	SaladUI.Flags = visualFlags
	SaladUI.BuiltInBold = K.face.bold
	SaladUI.BuiltInRegular = K.face.medium
	local function setFlag(flag, value)
		local entry = lib.pool[flag]
		if entry and entry.set then pcall(entry.set, value) end
	end
	local function userPicked()
		return not (lib.configApplying or lib.quiet) and os.clock() - (lib.appliedAt or -math.huge) > 0.5
	end
	function SaladUI.RandomString()
		local t = {}
		for i = 1, 12 do t[i] = string.char(math.random(97, 122)) end
		return table.concat(t)
	end
	-- no icon font here: an icon label stays empty rather than reading "Label"
	function SaladUI.ApplyIcon(label) pcall(function() label.Text = "" end) end
	function SaladUI:AddSignal(c)
		trackedConns[#trackedConns + 1] = c
		return c
	end
	SaladUI.AddPlayerSignal = SaladUI.AddSignal

	-- Every Add* runs through here. A card and each of its option panels get a
	-- name pool of their own, so a panel's "Size" never collides with the card's.
	local function FBRows(sec)
		local used = {}
		local function rememberFlag(name, cfg)
			if type(cfg.Flag) == "string" and cfg.Flag ~= "" then
				local control = registry[sec.path .. "/" .. name]
				if control then
					control.GetValue = function() return control.get() end
					control.SetValue = function(_, value) control.set(value) end
					visualFlags[cfg.Flag] = control
				end
			end
		end
		local function report(cfg)
			return function(value)
				if cfg.Callback then cfg.Callback(value) end
				if SaladUI.OnToggleChanged then
					pcall(SaladUI.OnToggleChanged, value, cfg.Flag, not lib.quiet and not lib.configApplying)
				end
			end
		end
		local function uname(base, kind)
			base = tostring(base or "item")
			if not used[base] then used[base] = true return base end
			if kind == "color" and not used[base .. " color"] then
				used[base .. " color"] = true
				return base .. " color"
			end
			local i = 2
			while used[base .. " " .. i] do i += 1 end
			base = base .. " " .. i
			used[base] = true
			return base
		end
		local function FBRow(label)
			label = tostring(label or "item")
			local row = {}
			local n = 0
			local lastRow, lastName, lastOptions
			function row:SetVisible(v)
				if lastRow then lastRow.Visible = v == true end
			end
			function row:SetValue(v)
				local control = lastName and registry[sec.path .. "/" .. lastName]
				if control and control.set then control.set(v) end
			end
			function row:GetValue()
				local control = lastName and registry[sec.path .. "/" .. lastName]
				return control and control.get and control.get() or nil
			end
			function row:SetValues(values)
				if not lastOptions or type(values) ~= "table" then return end
				table.clear(lastOptions)
				for _, value in ipairs(values) do lastOptions[#lastOptions + 1] = tostring(value) end
				if not table.find(lastOptions, row:GetValue()) then row:SetValue(lastOptions[1] or "") end
			end
			local function ctlName(cfg, kind)
				cfg = cfg or {}
				if cfg.Name ~= nil then return uname(cfg.Name, kind) end
				n += 1
				if n == 1 then return uname(label, kind) end
				return uname(label .. " " .. kind)
			end
			function row:AddToggle(cfg)
				cfg = cfg or {}
				local name = ctlName(cfg, "toggle")
				local _, holder = sec:toggle(name, cfg.Default and true or false, report(cfg))
				lastRow, lastName = holder, name
				rememberFlag(name, cfg)
				return row
			end
			function row:AddSlider(cfg)
				cfg = cfg or {}
				local step = 1
				local r = tonumber(cfg.Rounding)
				if r and r > 0 then step = 1 / (10 ^ r) end
				local name = ctlName(cfg, "slider")
				local _, holder = sec:slider(name, tonumber(cfg.Min) or 0, tonumber(cfg.Max) or 100, tonumber(cfg.Default) or 0, report(cfg), type(cfg.Type) == "string" and cfg.Type or "", step)
				lastRow, lastName = holder, name
				rememberFlag(name, cfg)
				return row
			end
			function row:AddDropdown(cfg)
				cfg = cfg or {}
				local vals = {}
				for i, v in ipairs(cfg.Values or {}) do vals[i] = tostring(v) end
				local def = cfg.Default
				if type(def) == "table" then def = def[1] end
				if cfg.Multi then
					local name = ctlName(cfg, "select")
					sec:multi(name, vals, def, report(cfg))
					lastName = name
					rememberFlag(name, cfg)
				else
					local name = ctlName(cfg, "select")
					local _, holder = sec:dropdown(name, vals, def ~= nil and tostring(def) or vals[1] or "", report(cfg))
					lastRow, lastName = holder, name
					rememberFlag(name, cfg)
				end
				lastOptions = vals
				return row
			end
			function row:AddColorPicker(cfg)
				cfg = cfg or {}
				local name = ctlName(cfg, "color")
				if lastRow and lastRow ~= sec.header and not lastRow:FindFirstChild("Swatch") then
					sec:inlineColor(lastRow, name, cfg.Default or C.accent, report(cfg))
				else
					sec:color(name, cfg.Default or C.accent, report(cfg))
				end
				rememberFlag(name, cfg)
				return row
			end
			function row:AddTextInput(cfg)
				cfg = cfg or {}
				local name = ctlName(cfg, "text")
				local holder = rowBase(sec.body, 60)
				local caption = rowLabel(holder, name, 0)
				caption.Size = UDim2.new(1, 0, 0, 24)
				local box = new("TextBox", {
					Name = "Input",
					Position = UDim2.fromOffset(0, 26),
					Size = UDim2.new(1, 0, 0, 30),
					BackgroundColor3 = C.field,
					BorderSizePixel = 0,
					ClearTextOnFocus = false,
					FontFace = K.face.medium,
					Text = tostring(cfg.Default or ""),
					TextSize = 12,
					TextColor3 = C.text,
					TextXAlignment = Enum.TextXAlignment.Left,
					TextTruncate = Enum.TextTruncate.AtEnd,
					PlaceholderText = tostring(cfg.Placeholder or name),
					PlaceholderColor3 = C.faint,
				}, holder)
				corner(box, 8)
				pad(box, 0, 0, 10, 10)
				local inputEdge = stroke(box, C.text, 1)
				box.Focused:Connect(function() inputEdge.Transparency = 0.6 end)
				box.FocusLost:Connect(function() inputEdge.Transparency = 1 end)
				local applying, committed = false, box.Text
				local function set(value)
					applying = true
					box.Text = tostring(value or "")
					applying = false
					committed = box.Text
					if cfg.Callback and not lib.secrets[cfg.Flag] then task.spawn(cfg.Callback, box.Text) end
				end
				sec:register(name, function() return box.Text end, set)
				local control = registry[sec.path .. "/" .. name]
				if control then control.secret = lib.secrets[cfg.Flag] == true end
				rememberFlag(name, cfg)
				box.FocusLost:Connect(function()
					if not applying and box.Text ~= committed then
						committed = box.Text
						if cfg.Callback then task.spawn(cfg.Callback, box.Text) end
					end
				end)
				lastRow, lastName = holder, name
				return row
			end
			function row:AddButton(cfg)
				cfg = cfg or {}
				sec:button(ctlName(cfg, "button"), cfg.Callback)
				return row
			end
			function row:AddKeybind(cfg)
				cfg = cfg or {}
				local name = ctlName(cfg, "keybind")
				sec:keybind(name, cfg.Default, report(cfg))
				lastName = name
				rememberFlag(name, cfg)
				return row
			end
			-- the extras of a feature belong behind the "..." on its own row,
			-- not spilled down the card under names like "Size 2"
			function row:AddOption(_, optionTitle)
				if not lastRow then
					local holder = rowBase(sec.body)
					rowLabel(holder, label, 0, "settings")
					lastRow, lastName = holder, uname(label)
				end
				return FBRows(sec:options(lastRow, lastName, optionTitle))(label)
			end
			function row:AddLabel(text, visible)
				if visible then sec:label(text) end
				return FBRow(text)
			end
			return row
		end
		return FBRow
	end

	-- A feature that would be a card on its own becomes one row of a shared
	-- card: its first row stays in the card, everything after it goes behind
	-- that row's dots.
	local function FBSplit(cardRows)
		local split, first, panelRows = {}, nil, nil
		local function panel()
			if not panelRows then
				local open = first.__open
				panelRows = open(first, 1)
			end
			return panelRows
		end
		local function start(label)
			first = cardRows:AddLabel(label)
			first.__open = first.AddOption
			function first:AddOption() return panel() end
			for _, method in ipairs({ "AddSlider", "AddDropdown", "AddButton", "AddKeybind" }) do
				first[method] = function(_, cfg)
					local target = panel()
					target[method](target, cfg)
					return first
				end
			end
			return first
		end
		function split:AddLabel(text)
			if not first then return start(text) end
			return panel():AddLabel(text)
		end
		for _, method in ipairs({ "AddToggle", "AddSlider", "AddDropdown", "AddColorPicker", "AddButton", "AddKeybind" }) do
			split[method] = function(_, cfg)
				if not first then
					local row = start((cfg and cfg.Name) or "item")
					row[method](row, cfg)
					return split
				end
				local target = panel()
				target[method](target, cfg)
				return split
			end
		end
		function split:AddOption() return panel() end
		return split
	end

	local function FBSection(tab, sub, col, title, reuse)
		local sec = UI.section(tab, sub, col, title, reuse)
		if not reuse then FBCards[#FBCards + 1] = sec.card end
		local section = FBRows(sec)(title)
		function section:SetVisible(v) sec.card.Visible = v == true end
		return section
	end

	local function FBPage(tab, sub, col, span)
		local page = {}
		local placed = 0
		local opened = Instance.new("BindableEvent")
		page.Signal = opened.Event
		function page.open(v) opened:Fire(v) end
		local _, view = findSub(tab, sub)
		local shown = false
		local function wake()
			local visible = root.Visible and view.page.Visible and view.page.Parent == K.content
			if shown == visible then return end
			shown = visible
			page.open(visible)
		end
		trackedConns[#trackedConns + 1] = root:GetPropertyChangedSignal("Visible"):Connect(wake)
		trackedConns[#trackedConns + 1] = view.page:GetPropertyChangedSignal("Visible"):Connect(wake)
		trackedConns[#trackedConns + 1] = view.page.AncestryChanged:Connect(wake)
		onUnload("gallery " .. sub, function() opened:Destroy() end)
		function page:AddGallery(cfg)
			cfg = cfg or {}
			local cell = tonumber(cfg.Cell) or 64
			local action = cfg.Action
			if type(action) == "table" then
				action = { icon = action.icon or action.Icon, callback = action.callback or action.Callback }
			end
			if cfg.Name == "Character" then cfg.Name = "Accessories" end
			if cfg.Name == "Cosmetics" then cfg.Name = "Wearables" end
			local g = UI.gallery(tab, sub, col, {
				Name = cfg.Name or "list",
				Multi = cfg.Multi,
				Thumb = cfg.Thumb,
				Height = cfg.Height,
				Cell = cell,
				Values = cfg.Values,
				Default = cfg.Default,
				Callback = function(value)
					if cfg.Callback then cfg.Callback(value) end
					if SaladUI.OnToggleChanged then
						pcall(SaladUI.OnToggleChanged, value, cfg.Flag, not lib.quiet and not lib.configApplying)
					end
				end,
				Empty = cfg.Empty,
				Reset = cfg.Reset,
				Context = cfg.Context,
				Action = action,
				Tools = cfg.Tools,
				Search = cfg.Search,
				Buttons = cfg.Buttons,
			})
			if type(cfg.Flag) == "string" and cfg.Flag ~= "" then
				visualFlags[cfg.Flag] = registry[tab .. "/" .. sub .. "/" .. (cfg.Name or "list")]
			end
			if span and g.frame then
				placed += 1
				K.span(tab, sub, g.frame, span)
			end
			local w = {}
			function w:set(v) g.set(v) end
			function w:setdata(v) g.setdata(v) end
			function w:get() return g.get() end
			function w:SetValue(v) g.set(v) end
			function w:SetData(v) g.setdata(v) end
			function w:GetValue() return g.get() end
			function w:SetDefault(v) g.set(v, true) end
			function w:Clear() g.clear() end
			function w:All() g.all() end
			function w:Refresh() g.refresh() end
			function w:Search(q) g.search(q) end
			function w:Generate() g.refresh() end
			if g.frame then FBCards[#FBCards + 1] = g.frame end
			do
				local d = cfg.Default
				local empty = d == nil or (type(d) == "table" and next(d) == nil) or (type(d) == "string" and d == "")
				if not empty then g.set(d) end
			end
			return w
		end
		return page
	end

	local Visuals = {
		Auras = FBPage("Style", "Auras", 2, true),
		Trails = FBPage("Style", "Trails", 2, true),
		Cosmetics = FBPage("Style", "Cosmetics", 2, true),
		Models = FBPage("Style", "Avatar", 3),
		Character = FBPage("Style", "Avatar", 2),
	}

	-- cards of their own only for features with a handful of controls; the
	-- one-switch features share a card, one row each
	local chamsCard = FBSection("Visuals", "Players", 1, "Chams")
	local skyCard = FBSection("Visuals", "World", 3, "Sky")
	local hitCard = FBSection("Visuals", "Effects", 2, "Kill Effects")
	-- what the local player sees over the game rather than in it
	local screenCard = FBSection("Visuals", "Effects", 3, "Screen")
	local lookCard = FBSection("Style", "Avatar", 1, "Appearance", true)
	local cosmeticsCard = FBSection("Style", "Cosmetics", 1, "Cosmetics")
	local musicCard = FBSection("Misc", "Music", 1, "Now Playing")
	local Sections = {
		ESP = FBSection("Visuals", "Players", 2, "Player ESP"),
		Chams = chamsCard,
		Items = FBSplit(chamsCard),
		Guns = FBSection("Visuals", "Players", 3, "Gun Chams"),
		Shaders = FBSection("Visuals", "World", 1, "Shaders"),
		Lighting = FBSection("Visuals", "World", 2, "Lighting"),
		Stars = FBSplit(skyCard),
		Starfall = FBSplit(skyCard),
		Glyphs = FBSection("Visuals", "World", 1, "Glyphs"),
		Weather = FBSection("Visuals", "World", 2, "Weather"),
		Circles = FBSection("Visuals", "Effects", 1, "Jump / Land"),
		KillFx = hitCard,
		BulletTracer = FBSplit(hitCard),
		WorldMisc = FBSection("Visuals", "Effects", 3, "Game Sounds"),
		Extras = FBSplit(cosmeticsCard),
		Screen = FBSplit(screenCard),
		ScreenInfo = FBSplit(screenCard),
		Cursor = FBSplit(screenCard),
		Camera = FBSection("Visuals", "World", 3, "Camera"),
