local ESP = { Settings = S, WindowFrame = function() return root end };

if not Remote.current() then bootstrap.Stop(); return end;

task.spawn(function() if Remote.current() then Remote.bootstrap() end end);
bootstrap.stage = "features";

local function drawNew(class)
	local object = Drawing.new(class);
	drawn[object] = class;
	return object;
end;

local Render = {};

do
	local camera = workspace.CurrentCamera;

	function Render.camera()
		local current = workspace.CurrentCamera;

		if current ~= camera then camera = current end;

		return camera;
	end;

	function Render.basis()
		local cam = Render.camera();

		if not cam then return nil end;

		local cf = cam.CFrame;
		local viewport = cam.ViewportSize;
		local half = math.tan(math.rad(cam.FieldOfView) * 0.5);

		return {
			pos = cf.Position,
			look = cf.LookVector,
			right = cf.RightVector,
			up = cf.UpVector,
			midX = viewport.X * 0.5,
			midY = viewport.Y * 0.5,
			scale = (viewport.Y * 0.5) / half,
			viewport = viewport,
		};
	end;

	local NEAR = 0.6;

	function Render.segment(basis, a, b)
		local function depthOf(p)
			return (p.X - basis.pos.X) * basis.look.X
				+ (p.Y - basis.pos.Y) * basis.look.Y
				+ (p.Z - basis.pos.Z) * basis.look.Z;
		end;

		local da, db = depthOf(a), depthOf(b);

		if da < NEAR and db < NEAR then return nil end;

		if da < NEAR then
			a = a:Lerp(b, (NEAR - da) / (db - da));
			da = NEAR;
		elseif db < NEAR then
			b = b:Lerp(a, (NEAR - db) / (da - db));
			db = NEAR;
		end;

		local ax, ay = Render.project(basis, a);
		local bx, by = Render.project(basis, b);

		return ax, ay, bx, by, (da + db) * 0.5;
	end;

	function Render.project(basis, point)
		local dx = point.X - basis.pos.X;
		local dy = point.Y - basis.pos.Y;
		local dz = point.Z - basis.pos.Z;
		local depth = dx * basis.look.X + dy * basis.look.Y + dz * basis.look.Z;

		if depth <= 0.05 then return 0, 0, depth end;

		local inv = basis.scale / depth;

		return basis.midX + (dx * basis.right.X + dy * basis.right.Y + dz * basis.right.Z) * inv,
			basis.midY - (dx * basis.up.X + dy * basis.up.Y + dz * basis.up.Z) * inv,
			depth;
	end;

	function Render.pool(class, setup)
		local items, used = {}, 0;
		local pool = {};

		function pool.take()
			used = used + 1;

			local item = items[used];

			if not item then
				item = drawNew(class);

				if setup then setup(item) end;

				items[used] = item;
			end;

			return item;
		end;

		function pool.reset() used = 0 end;

		function pool.done()
			for index = used + 1, #items do
				local item = items[index];

				if item and item.Visible then item.Visible = false end;
			end;
		end;

		function pool.wipe()
			for index = 1, #items do destroyAny(items[index]) end;

			table.clear(items);

			used = 0;
		end;

		function pool.count() return used end;

		return pool;
	end;

	function Render.gui(label, order)
		local gui = Instance.new("ScreenGui");
		gui.Name = SaladUI.RandomString();
		gui.ResetOnSpawn = false;
		gui.IgnoreGuiInset = true;
		gui.DisplayOrder = order or 0;
		gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling;
		gui.Enabled = true;

		pcall(function() gui:SetAttribute(TAG, INIT_GENERATION) end);

		local parent = SaladUI.ScreenGui and SaladUI.ScreenGui.Parent;

		gui.Parent = parent or ((gethui and gethui()) or game:GetService("CoreGui"));
		-- drawn under the menu (lower DisplayOrder), never switched off for it

		onUnload("gui:" .. tostring(label), function()
			if gui then gui:Destroy() end;
		end);

		return gui;
	end;
end;

ESP.Render = Render;

function Render.FxDepth(effect, through)
	if effect:IsA("BillboardGui") or effect:IsA("SurfaceGui") then
		effect.AlwaysOnTop = through == true;
	elseif effect:IsA("Highlight") then
		effect.DepthMode = through and Enum.HighlightDepthMode.AlwaysOnTop or Enum.HighlightDepthMode.Occluded;
	elseif effect:IsA("Beam") or effect:IsA("ParticleEmitter") then
		local offset = through and 100000 or 0;
		if effect.ZOffset ~= offset then effect.ZOffset = offset end;
	end;
end;
function Render.DepthTree(root, through)
	Render.FxDepth(root, through);
	for _, effect in ipairs(root:GetDescendants()) do Render.FxDepth(effect, through) end;
end;

ESP.Visibility = {};
do
	local cache = setmetatable({}, { __mode = "k" });
	function ESP.Visibility.Part(camera, part, target)
		if not (camera and part and part.Parent and part:IsA("BasePart") and target) then return false end;
		local origin, position = camera.CFrame.Position, part.Position;
		local direction = position - origin;
		local distance = direction.Magnitude;
		if distance ~= distance or distance == math.huge then return false end;
		if distance < 0.001 then return true end;
		local now, own = os.clock(), LocalPlayer.Character;
		local saved = cache[part];
		if saved and saved.Target == target and saved.Own == own and saved.Camera == camera
			and now < saved.Expires and (origin - saved.Origin).Magnitude < 0.5
			and (position - saved.Position).Magnitude < 0.5 then return saved.Visible end;
		local params = saved and saved.Params or RaycastParams.new();
		params.FilterType = Enum.RaycastFilterType.Exclude;
		params.IgnoreWater = true;
		local ignored = { target };
		if own and own ~= target then ignored[#ignored + 1] = own end;
		local visible = false;

		for _ = 1, 8 do
			params.FilterDescendantsInstances = ignored;
			local ok, hit = pcall(workspace.Raycast, workspace, origin, direction, params);
			if not ok then break end;
			if not hit then visible = true; break end;
			local object = hit.Instance;
			if object and object:IsA("BasePart") and object.Transparency >= 0.99 then
				ignored[#ignored + 1] = object;
			else break end;
		end;
		cache[part] = { Target = target, Own = own, Camera = camera, Origin = origin,
			Position = position, Expires = now + 0.08, Visible = visible, Params = params };
		return visible;
	end;
	function ESP.Visibility.Character(camera, char, root)
		if not char then return false end;
		local head = char:FindFirstChild("Head");
		local torso = char:FindFirstChild("UpperTorso") or char:FindFirstChild("Torso");
		return ESP.Visibility.Part(camera, head, char) or ESP.Visibility.Part(camera, root, char)
			or ESP.Visibility.Part(camera, torso, char);
	end;
end;

function ESP.Grad(c1, c2, p, off)
	return c1:Lerp(c2, math.sin((p or 0) * math.pi + os.clock() * 2 + (off or 0) * 6.283) * 0.5 + 0.5);
end;

do
	local Camera = workspace.CurrentCamera;
	local bundles, highlights, highlightState = {}, {}, {};

	local function inTarget(target, isSelf)
		return target == "All" or (isSelf and target == "Self") or (not isSelf and target == "Other");
	end;

	ESP.Wants = inTarget;

	local ARROW_SKINS = {
		Triangle = { file = Remote.file("images/triangle.png"), rotation = 90, scale = 1,
			rectOffset = Vector2.new(82, 87), rectSize = Vector2.new(638, 638), canvasSize = Vector2.new(807, 807) },
		["Triangle 2"] = { file = Remote.file("images/triangle2.png"), rotation = 90, scale = 1,
			rectOffset = Vector2.new(66, 76), rectSize = Vector2.new(380, 380), canvasSize = Vector2.new(512, 512) },
		["Triangle 3"] = { file = Remote.file("images/triangle3.png"), rotation = 0, scale = 1,
			rectOffset = Vector2.new(22, 25), rectSize = Vector2.new(190, 190), canvasSize = Vector2.new(240, 240) },
		Arrows = { file = Remote.file("images/arrows.png"), rotation = 90, scale = 1,
			rectOffset = Vector2.new(5, 6), rectSize = Vector2.new(110, 110), canvasSize = Vector2.new(120, 120) },
		White = { file = Remote.file("images/white.png"), rotation = 0, scale = 1,
			rectOffset = Vector2.new(19, 14), rectSize = Vector2.new(484, 484), canvasSize = Vector2.new(512, 512) },
		["Arrow 3"] = { file = Remote.file("images/arrow3.png"), rotation = 90, scale = 1,
			rectOffset = Vector2.new(85, 92), rectSize = Vector2.new(58, 58), canvasSize = Vector2.new(240, 240) },
		Arrow = { file = Remote.file("images/arrow.png"), rotation = -90, scale = 1,
			rectOffset = Vector2.new(14, 15), rectSize = Vector2.new(41, 41), canvasSize = Vector2.new(70, 70) },
		["Arrows 3"] = { file = Remote.file("images/arrows_new.png"), rotation = 90, scale = 1,
			rectOffset = Vector2.new(14, 23), rectSize = Vector2.new(186, 186), canvasSize = Vector2.new(209, 216) },
		["12213"] = { file = Remote.file("images/12213.png"), rotation = 90, scale = 1,
			rectOffset = Vector2.new(31, 41), rectSize = Vector2.new(448, 448), canvasSize = Vector2.new(512, 512) },
		Arr = { file = Remote.file("images/arr.png"), rotation = 90, scale = 1,
			rectOffset = Vector2.new(47, 51), rectSize = Vector2.new(418, 418), canvasSize = Vector2.new(512, 512) },
		GPS = { file = Remote.file("images/gps.png"), rotation = 90, scale = 1,
			rectOffset = Vector2.new(83, 79), rectSize = Vector2.new(86, 86), canvasSize = Vector2.new(240, 240) },
		["Arrow Glow"] = { file = Remote.file("images/arrow_glow.png"), rotation = 90, scale = 1,
			rectOffset = Vector2.new(51, 90), rectSize = Vector2.new(360, 360), canvasSize = Vector2.new(461, 512) },
	};

	ESP.ArrowSkins = ARROW_SKINS;

	local arrowUrls, arrowRequests, arrowRetryAt = {}, {}, {};

	local FALLBACK_ARROW = { rotation = 0, scale = 1 };

	local function arrowSkin(requestedSkin)
		local skin = requestedSkin or ARROW_SKINS[S.ArrowImage] or ARROW_SKINS.Triangle;

		local url = arrowUrls[skin.file] or Remote.cachedId(skin.file);
		if url then arrowUrls[skin.file] = url; return url, skin end;

		if not arrowRequests[skin.file] and os.clock() >= (arrowRetryAt[skin.file] or 0) then
			arrowRequests[skin.file] = true;
			arrowRetryAt[skin.file] = os.clock() + 15;
			task.spawn(function()
				local ok, id = pcall(Remote.id, skin.file);
				if Remote.current() and ok and type(id) == "string" and id ~= "" then
					arrowUrls[skin.file] = id;
				end;
				arrowRequests[skin.file] = nil;
			end);
		end;

		url = arrowUrls[skin.file];
		return url or "rbxassetid://4918373417", url and skin or FALLBACK_ARROW;
	end;

	ESP.ArrowSkin = arrowSkin;

	local arrowGui = Instance.new("ScreenGui");
	arrowGui.Name = SaladUI.RandomString();
	arrowGui.ResetOnSpawn = false;
	arrowGui.IgnoreGuiInset = true;
	arrowGui.ZIndexBehavior = Enum.ZIndexBehavior.Global;
	arrowGui.DisplayOrder = -4;
	arrowGui.Enabled = true;
	arrowGui:SetAttribute(TAG, INIT_GENERATION);
	pcall(function() arrowGui.Parent = SaladUI.ScreenGui.Parent end);
	-- under the menu, never off for it

	ESP.ArrowGui = arrowGui;
	local ARROW_BLOOM_SKIN = { file = Remote.file("particles/p_glow.png"), rotation = 0, scale = 1 };

	local function arrowBloomStyle(value)
		local amount = math.clamp(value / 100, 0, 1);
		return 2.4, 1 - amount * 0.65;
	end;
	ESP.ArrowBloomStyle = arrowBloomStyle;

	local function arrowImage()
		local image = Instance.new("ImageLabel");
		image.Name = SaladUI.RandomString();
		image.Parent = arrowGui;
		image.AnchorPoint = Vector2.new(0.5, 0.5);
		image.BackgroundTransparency = 1;
		image.BorderSizePixel = 0;
		image.ScaleType = Enum.ScaleType.Fit;
		image.ZIndex = 2;
		image.Visible = false;
		image.Image = arrowSkin();

		local halo = Instance.new("ImageLabel");
		halo.Name = "Bloom";
		halo.AnchorPoint = Vector2.new(0.5, 0.5);
		halo.Position = UDim2.fromScale(0.5, 0.5);
		halo.Size = UDim2.fromScale(2.4, 2.4);
		halo.BackgroundTransparency = 1;
		halo.BorderSizePixel = 0;
		halo.ScaleType = Enum.ScaleType.Fit;
		halo.ZIndex = 1;
		halo.ImageTransparency = 1;
		halo.Visible = false;
		halo.Parent = image;

		return image;
	end;

	local function square(filled)
		local sq = drawNew("Square");
		sq.Thickness = 1;
		sq.Filled = filled;
		sq.Visible = false;
		return sq;
	end;

	local function bundleOf(player)
		if bundles[player] then return bundles[player] end;

		local b = {
			name = drawNew("Text"),
			arrow = arrowImage(),
			bones = {},
			fill = square(true),
			bars = {},
			outlines = {},
			edges = {},
		};

		b.name.Size = 14;
		b.name.Center = true;
		b.name.Outline = true;
		b.name.Font = 2;
		b.name.Visible = false;

		b.player = player;
		bundles[player] = b;

		return b;
	end;

	-- MM2 hands the client the round's roles through CurrentRoundClient; a held
	-- knife or gun answers the same question while that module is still loading.
	-- One lookup per player per half second is plenty: roles change on round
	-- boundaries, not on frames.
	local roleModule, roleCache, roleStamp = nil, {}, 0;
	local ROLE_NAMES = { Murderer = true, Sheriff = true, Hero = true, Innocent = true, None = true };

	local function roleOf(player)
		local now = os.clock();

		if now - roleStamp > 0.5 then roleStamp = now; table.clear(roleCache) end;

		local cached = roleCache[player];

		if cached then return cached end;

		if not roleModule then
			pcall(function()
				local modules = game:GetService("ReplicatedStorage"):FindFirstChild("Modules");
				local found = modules and modules:FindFirstChild("CurrentRoundClient");

				if found then
					roleModule = require(found);
					local changed = roleModule and roleModule.PlayerDataChanged;
					if changed and changed.Event then
						SaladUI:AddSignal(changed.Event:Connect(function()
							table.clear(roleCache); roleStamp = 0;
						end));
					end;
				end;
			end);
		end;

		local role;
		local data = type(roleModule) == "table" and roleModule.PlayerData or nil;
		local row = type(data) == "table" and data[player.Name] or nil;

		-- the shitaro hub's reading: a dead sheriff or hero has no role, everyone
		-- else keeps theirs; whoever holds the gun and is not the murderer (or
		-- the hero) is the sheriff
		if type(row) == "table" and ROLE_NAMES[row.Role] and not ((row.Role == "Sheriff" or row.Role == "Hero") and row.Dead) then
			role = row.Role;
		end;

		local char = player.Character;
		local backpack = player:FindFirstChildOfClass("Backpack");
		local hasGun = (char and char:FindFirstChild("Gun")) or (backpack and backpack:FindFirstChild("Gun"));
		if hasGun and role ~= "Murderer" and role ~= "Hero" then role = "Sheriff" end;

		role = role or "None";
		roleCache[player] = role;

		return role;
	end;

	function ESP.RoleColor(player, fallback)
		if not S.RoleColors or not player then return fallback end;

		local role = roleOf(player);

		if role == "Murderer" then return S.RoleMurderer end;
		if role == "Hero" then return S.RoleHero end;
		if role == "Sheriff" then return S.RoleSheriff end;
		if role == "Innocent" then return S.RoleInnocent end;
		return S.RoleNone;
	end;

	-- the role colour of the player the loop is drawing right now, nil while
	-- role colours are off so the pickers keep their say
	local tint = nil;

	local function hideSkeleton(b)
		LPH_ATTRIBUTES(VM(NONE));
		if b.skeletonVisible == false then return end;
		for _, bone in ipairs(b.bones) do if bone.Visible then bone.Visible = false end end;
		b.skeletonVisible = false;
	end;

	local function hideBox(b)
		b.name.Visible = false;
		b.fill.Visible = false;

		for _, piece in ipairs(b.bars) do piece.Visible = false end;
		for _, piece in ipairs(b.outlines) do piece.Visible = false end;
		for _, piece in ipairs(b.edges) do piece.Visible = false end;
	end;

	local extents = setmetatable({}, { __mode = "k" });
	local BODY_NAMES = {
		Head=true, Torso=true, UpperTorso=true, LowerTorso=true,
		["Left Leg"]=true, ["Right Leg"]=true,
		LeftUpperLeg=true, LeftLowerLeg=true, LeftFoot=true,
		RightUpperLeg=true, RightLowerLeg=true, RightFoot=true,
	};

	local function getExtents(char, root)
		local held = extents[char];

		if held and os.clock() - held.at < 0.5 then return held end;

		local inv = root.CFrame:Inverse();
		local lo = Vector3.new(math.huge, math.huge, math.huge);
		local hi = Vector3.new(-math.huge, -math.huge, -math.huge);
		local any = false;

		for _, part in ipairs(char:GetChildren()) do
			if part:IsA("BasePart") and BODY_NAMES[part.Name] then
				local cf = inv * part.CFrame;
				local half = part.Size * 0.5;
				local rv, uv, lv = cf.RightVector, cf.UpVector, cf.LookVector;

				local spread = Vector3.new(
					math.abs(rv.X) * half.X + math.abs(uv.X) * half.Y + math.abs(lv.X) * half.Z,
					math.abs(rv.Y) * half.X + math.abs(uv.Y) * half.Y + math.abs(lv.Y) * half.Z,
					math.abs(rv.Z) * half.X + math.abs(uv.Z) * half.Y + math.abs(lv.Z) * half.Z
				);

				lo = lo:Min(cf.Position - spread);
				hi = hi:Max(cf.Position + spread);
				any = true;
			end;
		end;

		if not any then return nil end;

		local half = (hi - lo) * 0.5;

		local torso = char:FindFirstChild("UpperTorso") or char:FindFirstChild("Torso") or root;
		local height = math.clamp(half.Y * 2, 0.5, 24);
		half = Vector3.new(math.clamp(torso.Size.X * 0.6, height * 0.16, height * 0.24), height * 0.5, math.clamp(torso.Size.Z * 0.55, 0.15, height * 0.16));

		held = { at = os.clock(), center = Vector3.new(0, (lo.Y + hi.Y) * 0.5, 0), half = half };
		extents[char] = held;

		return held;
	end;

	local CORNERS = {
		Vector3.new(-1, -1, -1), Vector3.new(1, -1, -1), Vector3.new(1, -1, 1), Vector3.new(-1, -1, 1),
		Vector3.new(-1, 1, -1), Vector3.new(1, 1, -1), Vector3.new(1, 1, 1), Vector3.new(-1, 1, 1),
	};

	local screenCorners = {};
	local BOX_EDGES = {{1,2},{2,3},{3,4},{4,1},{5,6},{6,7},{7,8},{8,5},{1,5},{2,6},{3,7},{4,8}};
	local function clipNear(a, b)
		local near = 0.1;
		if a.Z > -near and b.Z > -near then return nil end;
		if a.Z > -near then a = a:Lerp(b, (-near-a.Z)/(b.Z-a.Z)) end;
		if b.Z > -near then b = b:Lerp(a, (-near-b.Z)/(a.Z-b.Z)) end;
		return a, b;
	end;
	local function projectPoint(point, camera, viewport)
		local focal = viewport.Y / (2 * math.tan(math.rad(camera.FieldOfView) * 0.5));
		return Vector2.new(viewport.X * 0.5 + point.X * focal / -point.Z, viewport.Y * 0.5 - point.Y * focal / -point.Z);
	end;
	local function clipViewport(a, b, viewport)
		local dx, dy = b.X - a.X, b.Y - a.Y;
		local low, high = 0, 1;
		for _, pair in ipairs({{-dx,a.X},{dx,viewport.X-a.X},{-dy,a.Y},{dy,viewport.Y-a.Y}}) do
			local p, q = pair[1], pair[2];
			if p == 0 then if q < 0 then return nil end;
			else
				local t = q / p;
				if p < 0 then low = math.max(low,t) else high = math.min(high,t) end;
				if low > high then return nil end;
			end;
		end;
		return a:Lerp(b,low), a:Lerp(b,high);
	end;
	local function projectBox(char, camera, viewport)
		local root = char and char:FindFirstChild("HumanoidRootPart");
		if not root or not camera or viewport.X <= 0 or viewport.Y <= 0 then return nil end;
		local box = getExtents(char, root);
		if not box then return nil end;
		local relative = camera.CFrame:Inverse() * root.CFrame;
		for index, corner in ipairs(CORNERS) do
			screenCorners[index] = relative * (box.center + corner * box.half);
		end;
		local minX, minY, maxX, maxY = math.huge, math.huge, -math.huge, -math.huge;
		local segments, projected = {}, 0;
		for _, edge in ipairs(BOX_EDGES) do
			local a, b = clipNear(screenCorners[edge[1]], screenCorners[edge[2]]);
			if a then
				a, b = projectPoint(a,camera,viewport), projectPoint(b,camera,viewport);
				projected += 1;
				minX, minY = math.min(minX,a.X,b.X), math.min(minY,a.Y,b.Y);
				maxX, maxY = math.max(maxX,a.X,b.X), math.max(maxY,a.Y,b.Y);
				a, b = clipViewport(a,b,viewport);
				if a then segments[#segments + 1] = {a,b} end;
			end;
		end;
		if projected == 0 or maxX < 0 or minX > viewport.X or maxY < 0 or minY > viewport.Y then return nil end;
		minX, minY = math.max(minX,0), math.max(minY,0);
		maxX, maxY = math.min(maxX,viewport.X), math.min(maxY,viewport.Y);
		if maxX-minX < 1 or maxY-minY < 1 then return nil end;
		return Vector2.new(minX,minY), Vector2.new(maxX-minX,maxY-minY), segments;
	end;
	ESP.ProjectBox = projectBox;
	ESP.BodyExtents = getExtents;

	local function screenBox(char)
		return projectBox(char, Camera, Camera.ViewportSize);
	end;

	local R15_BONES = {
		{ "Head", "UpperTorso" }, { "UpperTorso", "LowerTorso" },
		{ "UpperTorso", "LeftUpperArm" }, { "LeftUpperArm", "LeftLowerArm" }, { "LeftLowerArm", "LeftHand" },
		{ "UpperTorso", "RightUpperArm" }, { "RightUpperArm", "RightLowerArm" }, { "RightLowerArm", "RightHand" },
		{ "LowerTorso", "LeftUpperLeg" }, { "LeftUpperLeg", "LeftLowerLeg" }, { "LeftLowerLeg", "LeftFoot" },
		{ "LowerTorso", "RightUpperLeg" }, { "RightUpperLeg", "RightLowerLeg" }, { "RightLowerLeg", "RightFoot" },
	};

	local R6_BONES = {
		{ "Head", "Torso" },
		{ "Torso", "Left Arm" }, { "Torso", "Right Arm" },
		{ "Torso", "Left Leg" }, { "Torso", "Right Leg" },
	};

	local function getBone(b, index)
		LPH_ATTRIBUTES(VM(NONE));
		if not b.bones[index] then
			local line = drawNew("Line");
			line.Thickness = 1;
			line.Visible = false;
			b.bones[index] = line;
		end;

		return b.bones[index];
	end;

	local function drawSkeleton(b, char)
		LPH_ATTRIBUTES(VM(NONE));
		local rig = b.skeletonRig;
		local rebuild = not rig or rig.char ~= char;
		if rig and not rebuild then
			for _, part in ipairs(rig.parts) do
				if part.Parent ~= char then rebuild = true; break end;
			end;
			if rig.missing and os.clock() >= rig.retry then rebuild = true end;
		end;
		if rebuild then
			local bones = char:FindFirstChild("UpperTorso") and R15_BONES or R6_BONES;
			rig = { char = char, parts = {}, links = {}, points = {}, projected = {}, retry = os.clock() + 0.5 };
			local indices = {};
			for i, names in ipairs(bones) do
				local link = {};
				for side, name in ipairs(names) do
					local part = char:FindFirstChild(name);
					if part and part:IsA("BasePart") then
						local index = indices[part];
						if not index then index = #rig.parts + 1; rig.parts[index] = part; indices[part] = index end;
						link[side] = index;
					else rig.missing = true end;
				end;
				rig.links[i] = link;
				getBone(b, i);
			end;
			b.skeletonRig = rig;
		end;
		local cf, view = Camera.CFrame, Camera.ViewportSize;
		local focal = view.Y * 0.5 / math.tan(math.rad(Camera.FieldOfView) * 0.5);
		local midX, midY = view.X * 0.5, view.Y * 0.5;
		local function project(point)
			return Vector2.new(midX - point.X * focal / point.Z, midY + point.Y * focal / point.Z);
		end;
		for i, part in ipairs(rig.parts) do
			local point = cf:PointToObjectSpace(part.Position);
			rig.points[i] = point;
			rig.projected[i] = point.Z < -0.05 and project(point) or false;
		end;
		local color = tint or S.SkeletonColor;
		local any = false;
		for i, link in ipairs(rig.links) do
			local line = b.bones[i];
			local a, c;
			if link[1] and link[2] then
				a, c = rig.projected[link[1]], rig.projected[link[2]];
				if not a or not c then
					local from, to = clipNear(rig.points[link[1]], rig.points[link[2]]);
					if from then a, c = project(from), project(to) end;
				end;
			end;
			local visible = a and c and math.max(a.X, c.X) >= 0 and math.min(a.X, c.X) <= view.X
				and math.max(a.Y, c.Y) >= 0 and math.min(a.Y, c.Y) <= view.Y or false;
			if visible then
				line.From, line.To = a, c;
				if line.Color ~= color then line.Color = color end;
				any = true;
			end;
			if line.Visible ~= visible then line.Visible = visible end;
		end;
		for i = #rig.links + 1, #b.bones do
			if b.bones[i].Visible then b.bones[i].Visible = false end;
		end;
		b.skeletonVisible = any;
	end;

	local function arrowLayout(viewport, point, skin)
		if viewport.X <= 0 or viewport.Y <= 0 then return nil end;
		local center = Vector2.new(viewport.X / 2, viewport.Y / 2);
		local direction = Vector2.new(point.X, -point.Y);
		local length = direction.Magnitude;
		if length ~= length or length == math.huge then return nil end;
		local unit = length > 0.0001 and direction / length or Vector2.new(0, 1);
		local size = S.ArrowSize * skin.scale;
		local radius = math.max(0, math.min(S.ArrowRadius,
			math.min(viewport.X, viewport.Y) * 0.5 - size * 0.707107 - 4));
		return center + unit * radius, size,
			(math.deg(math.atan2(unit.Y, unit.X)) + skin.rotation + S.ArrowTurn) % 360;
	end;

	ESP.ArrowLayout = arrowLayout;

	local function arrowCrop(image, skin)
		local offset, size = skin.rectOffset or Vector2.zero, skin.rectSize or Vector2.zero;
		local source, content = skin.canvasSize, image.ContentImageSize;
		if source and content.X > 0 and content.Y > 0 then
			local x, y = content.X / source.X, content.Y / source.Y;
			offset = Vector2.new(math.round(offset.X * x), math.round(offset.Y * y));
			size = Vector2.new(math.max(1, math.round(size.X * x)), math.max(1, math.round(size.Y * y)));
		end;
		return offset, size;
	end;

	ESP.ArrowCrop = arrowCrop;

	local function drawArrow(b, root)
		local url, skin = arrowSkin();
		local at, size, rotation = arrowLayout(Camera.ViewportSize,
			Camera.CFrame:PointToObjectSpace(root.Position), skin);
		if not at then b.arrow.Visible = false; return end;

		b.arrow.Image = url;
		local offset, cropSize = arrowCrop(b.arrow, skin);
		b.arrow.ImageRectOffset = offset;
		b.arrow.ImageRectSize = cropSize;
		b.arrow.Position = UDim2.fromOffset(at.X, at.Y);
		b.arrow.Size = UDim2.fromOffset(size, size);
		b.arrow.Rotation = rotation;
		b.arrow.ImageColor3 = tint or S.ArrowColor;
		local halo = b.arrow.Bloom;
		halo.Visible = S.ArrowBloom > 0;
		if halo.Visible then
			local bloomUrl = arrowSkin(ARROW_BLOOM_SKIN);

			halo.Visible = bloomUrl ~= "rbxassetid://4918373417";
			if halo.Visible then
				local _, transparency = arrowBloomStyle(S.ArrowBloom);
				halo.Image = bloomUrl;
				halo.ImageTransparency = transparency;
				halo.ImageColor3 = tint or S.ArrowColor;
			end;
		end;
		b.arrow.Visible = true;
	end;

	local function rect(pool, index, at, size, color, thickness)
		local piece = pool[index];

		if not piece then
			piece = drawNew("Square");
			piece.Filled = true;
			piece.Thickness = 1;
			pool[index] = piece;
		end;

		piece.Position = at;
		piece.Size = size;
		piece.Color = color;
		piece.Visible = true;

		return index + 1;
	end;

	local function line(pool, index, from, to, color, thickness)
		local piece = pool[index];

		if not piece then
			piece = drawNew("Line");
			pool[index] = piece;
		end;

		piece.From = from;
		piece.To = to;
		piece.Color = color;
		piece.Thickness = thickness;
		piece.Visible = true;

		return index + 1;
	end;

	local function hidePool(pool, from)
		for i = from, #pool do pool[i].Visible = false end;
	end;

	local DARK = Color3.fromRGB(0, 0, 0);

	local function drawBox(b, at, size, corners)
		local x1, y1 = math.floor(at.X), math.floor(at.Y);
		local x2, y2 = math.floor(at.X + size.X), math.floor(at.Y + size.Y);
		local w, h = x2 - x1, y2 - y1;

		if w <= 0 or h <= 0 then
			hidePool(b.bars, 1);
			hidePool(b.outlines, 1);
			hidePool(b.edges, 1);
			b.fill.Visible = false;
			return;
		end;

		b.fill.Visible = S.BoxFilled;
		b.fill.Position, b.fill.Size = Vector2.new(x1, y1), Vector2.new(w, h);
		b.fill.Color = tint or S.BoxColor;
		b.fill.Transparency = S.BoxFillOpacity / 100;

		local thick = S.BoxThickness;
		local color = tint or S.BoxColor;
		local style = S.BoxStyle;
		local i, o, e = 1, 1, 1;

		if style == "3D" and corners then

			for pass = 1, 2 do
				local shade = (pass == 1) and DARK or color;
				local weight = (pass == 1) and (thick + 2) or thick;

				for _, edge in ipairs(corners) do
					e = line(b.edges, e, edge[1], edge[2], shade, weight);
				end;
			end;
		elseif style == "Corner" or style == "Bracket" then

			local tall = style == "Bracket";
			local lx = math.max(1, math.floor(w * 0.28));
			local ly = tall and h or math.max(1, math.floor(h * 0.28));

			o = rect(b.outlines, o, Vector2.new(x1 - 1, y1 - 1), Vector2.new(lx + 2, thick + 2), DARK);
			o = rect(b.outlines, o, Vector2.new(x2 - lx - 1, y1 - 1), Vector2.new(lx + 2, thick + 2), DARK);
			o = rect(b.outlines, o, Vector2.new(x1 - 1, y2 - thick - 1), Vector2.new(lx + 2, thick + 2), DARK);
			o = rect(b.outlines, o, Vector2.new(x2 - lx - 1, y2 - thick - 1), Vector2.new(lx + 2, thick + 2), DARK);
			o = rect(b.outlines, o, Vector2.new(x1 - 1, y1 - 1), Vector2.new(thick + 2, ly + 2), DARK);
			o = rect(b.outlines, o, Vector2.new(x2 - thick - 1, y1 - 1), Vector2.new(thick + 2, ly + 2), DARK);

			i = rect(b.bars, i, Vector2.new(x1, y1), Vector2.new(lx, thick), color);
			i = rect(b.bars, i, Vector2.new(x2 - lx, y1), Vector2.new(lx, thick), color);
			i = rect(b.bars, i, Vector2.new(x1, y2 - thick), Vector2.new(lx, thick), color);
			i = rect(b.bars, i, Vector2.new(x2 - lx, y2 - thick), Vector2.new(lx, thick), color);
			i = rect(b.bars, i, Vector2.new(x1, y1), Vector2.new(thick, ly), color);
			i = rect(b.bars, i, Vector2.new(x2 - thick, y1), Vector2.new(thick, ly), color);

			if not tall then
				o = rect(b.outlines, o, Vector2.new(x1 - 1, y2 - ly - 1), Vector2.new(thick + 2, ly + 2), DARK);
				o = rect(b.outlines, o, Vector2.new(x2 - thick - 1, y2 - ly - 1), Vector2.new(thick + 2, ly + 2), DARK);

				i = rect(b.bars, i, Vector2.new(x1, y2 - ly), Vector2.new(thick, ly), color);
				i = rect(b.bars, i, Vector2.new(x2 - thick, y2 - ly), Vector2.new(thick, ly), color);
			end;
		else
			o = rect(b.outlines, o, Vector2.new(x1 - 1, y1 - 1), Vector2.new(w + 2, thick + 2), DARK);
			o = rect(b.outlines, o, Vector2.new(x1 - 1, y2 - thick - 1), Vector2.new(w + 2, thick + 2), DARK);
			o = rect(b.outlines, o, Vector2.new(x1 - 1, y1 - 1), Vector2.new(thick + 2, h + 2), DARK);
			o = rect(b.outlines, o, Vector2.new(x2 - thick - 1, y1 - 1), Vector2.new(thick + 2, h + 2), DARK);

			i = rect(b.bars, i, Vector2.new(x1, y1), Vector2.new(w, thick), color);
			i = rect(b.bars, i, Vector2.new(x1, y2 - thick), Vector2.new(w, thick), color);
			i = rect(b.bars, i, Vector2.new(x1, y1), Vector2.new(thick, h), color);
			i = rect(b.bars, i, Vector2.new(x2 - thick, y1), Vector2.new(thick, h), color);
		end;

		hidePool(b.bars, i);
		hidePool(b.outlines, o);
		hidePool(b.edges, e);
	end;

	local clearChromatic, clearOcclusion;
	local itemHighlights, itemHeld = {}, {};
	local matClock = {};
	local itemClock = {};

	local seenChar = {};

	local function charChanged(player, char)
		if seenChar[player] == char then return false end;

		seenChar[player] = char;

		return true;
	end;
	local function drop(player)
		local b = bundles[player];

		if player.Character then
			pcall(ESP.Restore, player.Character);
		end;

		if type(clearChromatic) == "function" then clearChromatic(player) end;
		if type(clearOcclusion) == "function" then clearOcclusion(player) end;
		matClock[player] = nil;
		itemClock[player] = nil;
		seenChar[player] = nil;

		if itemHighlights[player] then
			itemHighlights[player]:Destroy();
			itemHighlights[player] = nil;
		end;

		if itemHeld[player] then
			if type(clearChromatic) == "function" then clearChromatic(itemHeld[player]) end;
			pcall(ESP.Restore, itemHeld[player]);
			itemHeld[player] = nil;
		end;

		if b then
			destroyAny(b.name);
			destroyAny(b.arrow);

			for _, bone in ipairs(b.bones) do destroyAny(bone) end;
			destroyAny(b.fill);

			for _, piece in ipairs(b.bars) do destroyAny(piece) end;
			for _, piece in ipairs(b.outlines) do destroyAny(piece) end;
			for _, piece in ipairs(b.edges) do destroyAny(piece) end;

			bundles[player] = nil;
		end;

		if highlights[player] then
			highlights[player]:Destroy();
			highlights[player] = nil;
		end;
		highlightState[player] = nil;
	end;

	local MATERIAL_STYLES = {
		ForceField = { material = Enum.Material.ForceField, reflectance = 0, transparency = 0, tint = true },
		Flat = { material = Enum.Material.SmoothPlastic, reflectance = 0, transparency = 0, tint = true },
		Glass = { material = Enum.Material.Glass, reflectance = 0.12, transparency = 0.28, tint = true },
		Ice = { material = Enum.Material.Ice, reflectance = 0.1, transparency = 0.16, tint = true },
		Ghost = { material = Enum.Material.SmoothPlastic, reflectance = 0.02, transparency = 0.58, tint = true },

		Marble = { material = Enum.Material.Marble, reflectance = 0.04, transparency = 0, tint = true },
		Foil = { material = Enum.Material.Foil, reflectance = 0.12, transparency = 0, tint = true },
		Metal = { material = Enum.Material.Metal, reflectance = 0.3, transparency = 0, tint = true },
		Wood = { material = Enum.Material.Wood, reflectance = 0, transparency = 0, tint = true },
	};

	ESP.MaterialStyles = MATERIAL_STYLES;
	function ESP.MaterialAlpha(baseTransparency, extraTransparency)
		local alpha = tonumber(extraTransparency) or 0;
		if alpha ~= alpha or alpha == math.huge or alpha == -math.huge then alpha = 0 end;
		alpha = math.clamp(alpha, 0, 1);
		return 1 - (1 - baseTransparency) * (1 - alpha);
	end;
	function ESP.ResolveMaterialStyle(name, extraTransparency)
		local base = MATERIAL_STYLES[name] or MATERIAL_STYLES.ForceField;

		return { material = base.material, reflectance = base.reflectance,
			transparency = ESP.MaterialAlpha(base.transparency, extraTransparency), tint = base.tint, keepTexture = base.keepTexture };
	end;

	ESP.MaterialOrder = { "ForceField", "Flat", "Glass", "Ice", "Ghost", "Marble", "Foil", "Metal", "Wood" };

	ESP.ChromaticOrder = { "Chromatic", "Pearlescent", "Chrome", "Crystal", "Candy" };

	ESP.StyleOrder = {};

	for _, name in ipairs(ESP.MaterialOrder) do ESP.StyleOrder[#ESP.StyleOrder + 1] = name end;
	for _, name in ipairs(ESP.ChromaticOrder) do ESP.StyleOrder[#ESP.StyleOrder + 1] = name end;

	local cache = {};

	local function entry(model)
		if not cache[model] then
			cache[model] = { parts = {}, hidden = {}, meshes = {} };
		end;

		return cache[model];
	end;

	ESP.PaintCache = function(model) return cache[model] end;

	local function restore(model)
		if model == nil then
			local models = {};
			for owned in pairs(cache) do models[#models + 1] = owned end;
			for _, owned in ipairs(models) do restore(owned) end;
			return;
		end;
		local data = cache[model];
		if not data then return end;

		for part, orig in pairs(data.parts) do
			if part.Parent then
				part.Material = orig.Material;
				if orig.MaterialVariant ~= nil then pcall(function() part.MaterialVariant = orig.MaterialVariant end) end;
				part.Color = orig.Color;
				part.Transparency = orig.Transparency;
				part.Reflectance = orig.Reflectance;

				if orig.TextureID then
					pcall(function() part.TextureID = orig.TextureID end);
				end;
			end;
		end;

		for mesh, texture in pairs(data.meshes or {}) do
			if mesh.Parent then pcall(function() mesh.TextureId = texture end) end;
		end;

		for inst, parent in pairs(data.hidden) do
			if parent and parent.Parent then pcall(function() inst.Parent = parent end)
			else pcall(function() inst:Destroy() end) end;
		end;

		cache[model] = nil;
	end;

	local function paint(model, styleName, color)
		local style = (type(styleName) == "table" and styleName) or MATERIAL_STYLES[styleName];

		if not style then
			restore(model);
			return;
		end;

		local data = entry(model);

		for _, inst in ipairs(model:GetDescendants()) do
			if inst:IsA("BasePart") then
				if not data.parts[inst] then
					data.parts[inst] = {
						Material = inst.Material,
						MaterialVariant = inst.MaterialVariant,
						Color = inst.Color,
						Transparency = inst.Transparency,
						Reflectance = inst.Reflectance,
						TextureID = inst:IsA("MeshPart") and inst.TextureID or nil,
					};
				end;

				if data.parts[inst].Transparency < 1 then

					data.parts[inst].Wanted = style.material or data.parts[inst].Material;

					inst.Material = style.material or data.parts[inst].Material;
					if not style.keepTexture then pcall(function() inst.MaterialVariant = "" end) end;
					inst.Reflectance = style.reflectance;
					inst.Transparency = style.transparency;

					inst.Color = style.tint and color or data.parts[inst].Color;
					if inst:IsA("MeshPart") and not style.keepTexture then
						pcall(function() inst.TextureID = "" end);
					end;

					if not style.keepTexture then
						local mesh = inst:FindFirstChildOfClass("SpecialMesh");

						if mesh then
							if data.meshes[mesh] == nil then data.meshes[mesh] = mesh.TextureId end;

							if mesh.TextureId ~= "" then
								pcall(function() mesh.TextureId = "" end);
							end;
						end;
					end;
				end;
			elseif not style.keepTexture and (inst:IsA("Shirt") or inst:IsA("Pants") or inst:IsA("ShirtGraphic")
				or inst:IsA("Decal") or inst:IsA("Texture") or inst:IsA("SurfaceAppearance")) then

				if data.hidden[inst] == nil and inst.Parent then
					data.hidden[inst] = inst.Parent;
					pcall(function() inst.Parent = nil end);
				end;
			end;
		end;
	end;

	ESP.Paint = paint;
	ESP.Restore = restore;

	local revision, applied, painted = 0, {}, {};

	ESP.Restyle = function() revision = revision + 1 end;

	local CHROM_STATE_STRIDE = 3;
	local CHROM_PAD_X = 180;
	local CHROM_PAD_Y = 220;
	local CHROM_HIDE_DELAY = 90;
	local CHROM_SHOW_BUDGET = 2;

	local CHROMATIC_PRESETS = {
		Chromatic = {
			{ Scale = 1.012, Alpha = 0.025, Material = Enum.Material.Foil, Reflectance = 0.12, ColorMode = "Base" },
		},
		Pearlescent = {
			{ Scale = 1.006, Alpha = 0.04, Material = Enum.Material.SmoothPlastic, Reflectance = 0.18, ColorMode = "Base" },
			{ Scale = 1.018, Alpha = 0.42, Material = Enum.Material.Neon, Reflectance = 0, ColorMode = "Pearl" },
		},
		Chrome = {
			{ Scale = 1.008, Alpha = 0.02, Material = Enum.Material.Metal, Reflectance = 0.55, ColorMode = "Base" },
			{ Scale = 1.018, Alpha = 0.55, Material = Enum.Material.Glass, Reflectance = 0.35, ColorMode = "Highlight" },
		},
		Crystal = {
			{ Scale = 1.006, Alpha = 0.2, Material = Enum.Material.Glass, Reflectance = 0.22, ColorMode = "Base" },
			{ Scale = 1.02, Alpha = 0.62, Material = Enum.Material.Neon, Reflectance = 0, ColorMode = "Highlight" },
		},
		Candy = {
			{ Scale = 1.007, Alpha = 0.03, Material = Enum.Material.SmoothPlastic, Reflectance = 0.32, ColorMode = "Base" },
			{ Scale = 1.016, Alpha = 0.5, Material = Enum.Material.Neon, Reflectance = 0.05, ColorMode = "Candy" },
		},
	};

	ESP.ChromaticPresets = CHROMATIC_PRESETS;

	local R15_PARTS = {
		Head = true, UpperTorso = true, LowerTorso = true,
		LeftUpperArm = true, LeftLowerArm = true, LeftHand = true,
		RightUpperArm = true, RightLowerArm = true, RightHand = true,
		LeftUpperLeg = true, LeftLowerLeg = true, LeftFoot = true,
		RightUpperLeg = true, RightLowerLeg = true, RightFoot = true,
		Torso = true, ["Left Arm"] = true, ["Right Arm"] = true,
		["Left Leg"] = true, ["Right Leg"] = true,
	};

	local function isBP(name)
		return R15_PARTS[name] == true;
	end;

	local function isCP(part)
		return part:IsA("BasePart") and part.Name ~= "HumanoidRootPart" and part.Name ~= "GlowShell";
	end;

	local function isDeformable(part)
		if part:FindFirstChildWhichIsA("WrapLayer") then return true end;
		if isBP(part.Name) then return false end;
		if part:FindFirstChildWhichIsA("Bone") then return true end;

		local ok, skinned = pcall(function() return part.HasSkinnedMesh end);

		return ok and skinned == true;
	end;

	local function tryClone(inst)
		local archivable = inst.Archivable;

		if not archivable then
			if not pcall(function() inst.Archivable = true end) then return nil end;
		end;

		local ok, clone = pcall(inst.Clone, inst);

		if not archivable then
			pcall(function() inst.Archivable = archivable end);
		end;

		if not ok then return nil end;

		return clone;
	end;

	local chromGui = Instance.new("ScreenGui");
	chromGui.Name = SaladUI.RandomString();
	chromGui.ResetOnSpawn = false;
	chromGui.IgnoreGuiInset = true;
	chromGui.DisplayOrder = -5;
	chromGui.Enabled = true;
	chromGui:SetAttribute(TAG, INIT_GENERATION);
	pcall(function() chromGui.Parent = SaladUI.ScreenGui.Parent end);
	-- under the menu (DisplayOrder -5), never off for it

	ESP.ChromaticGui = chromGui;

	local Chromatic = { Presets = CHROMATIC_PRESETS };
	local frameId = 0;

	function Chromatic:Ensure(count)
		local worlds = self.Worlds;

		if not worlds then
			worlds = {};
			self.Worlds = worlds;
			self.Views = {};
		end;

		local have = #worlds;
		if have >= count then return end;
		local sky = game:GetService("Lighting"):FindFirstChildOfClass("Sky");

		for i = have + 1, count do
			local view = Instance.new("ViewportFrame");
			view.Name = "ChromaticLayer" .. i;
			view.Size = UDim2.fromScale(1, 1);
			view.BackgroundTransparency = 1;
			view.BorderSizePixel = 0;
			view.ZIndex = i;
			view.Ambient = Color3.new(1, 1, 1);
			view.LightColor = Color3.new(1, 1, 1);
			view.LightDirection = Vector3.new(-1, -1, -1);
			view.CurrentCamera = workspace.CurrentCamera;
			view.Parent = chromGui;

			if sky then sky:Clone().Parent = view end;

			local world = Instance.new("WorldModel");
			world.Name = "ChromaticWorld";
			world.Parent = view;

			self.Views[i] = view;
			self.Worlds[i] = world;
		end;
	end;

	function Chromatic:BeginFrame()
		if self.Frame == frameId then return self.Camera end;

		self.Frame = frameId;
		self.ShowBudget = CHROM_SHOW_BUDGET;

		local camera = workspace.CurrentCamera;
		self.Camera = camera;

		if not camera then return nil end;

		self.Origin = camera.CFrame.Position;

		local size = camera.ViewportSize;
		self.MaxX = size.X + CHROM_PAD_X;
		self.MaxY = size.Y + CHROM_PAD_Y;

		local views = self.Views;

		if views then
			for i = 1, #views do
				if views[i].CurrentCamera ~= camera then
					views[i].CurrentCamera = camera;
				end;
			end;
		end;

		return camera;
	end;

	function Chromatic:TakeShow()
		local budget = self.ShowBudget;
		if not budget or budget <= 0 then return false end;
		self.ShowBudget = budget - 1;
		return true;
	end;

	local function chromaticColor(color, config)
		if config.ColorMode == "Pearl" then
			return color:Lerp(Color3.fromRGB(255, 125, 245), 0.45);
		elseif config.ColorMode == "Highlight" then
			return color:Lerp(Color3.new(1, 1, 1), 0.68);
		elseif config.ColorMode == "Candy" then
			return color:Lerp(Color3.fromRGB(255, 55, 125), 0.38);
		end;
		return color;
	end;

	ESP.ChromaticColor = chromaticColor;

	local function cloneChromaticPart(source, config, color)
		local clone = tryClone(source);
		if not clone then return nil end;

		local children = clone:GetChildren();

		for i = 1, #children do
			if not children[i]:IsA("DataModelMesh") then
				children[i]:Destroy();
			end;
		end;

		local mesh = clone:FindFirstChildWhichIsA("DataModelMesh");

		if mesh then
			mesh.Scale = mesh.Scale * config.Scale;
			if mesh:IsA("FileMesh") then mesh.TextureId = "" end;
		else
			clone.Size = clone.Size * config.Scale;
		end;

		if clone:IsA("MeshPart") then clone.TextureID = "" end;

		clone.MaterialVariant = "";
		clone.Anchored = true;
		clone.Massless = true;
		clone.CanCollide = false;
		clone.CanQuery = false;
		clone.CanTouch = false;
		clone.CastShadow = false;
		clone.LocalTransparencyModifier = 0;
		clone.Material = config.Material;
		clone.Reflectance = config.Reflectance;
		clone.Transparency = config.Alpha;
		clone.Color = chromaticColor(color, config);
		clone.CFrame = source.CFrame;

		return clone;
	end;
	ESP.CloneChromaticPart = cloneChromaticPart;
	ESP.ChromaticSourceAllowed = function(part) return isCP(part) and not isDeformable(part) end;

	local chrom = {};

	local function setChromaticParented(state, parented)
		if not state or state.Parented == parented then return end;

		state.Parented = parented;

		local models, parents = state.Models, state.Parents;

		for i = 1, #models do
			models[i].Parent = parented and parents[i] or nil;
		end;

		state.HideAt = nil;

		if parented then state.Tick = CHROM_STATE_STRIDE end;
	end;

	clearChromatic = function(player)
		local state = chrom[player];
		if not state then return end;

		for i = 1, #state.Models do
			state.Models[i]:Destroy();
		end;

		chrom[player] = nil;
	end;

	local function getParts(char)
		local parts, n = {}, 0;

		for _, inst in ipairs(char:GetDescendants()) do
			if isCP(inst) then
				n = n + 1;
				parts[n] = inst;
			end;
		end;

		return parts, n;
	end;

	local function applyChromatic(player, char, color, style, extraTransparency)
		if not char then return end;

		style = CHROMATIC_PRESETS[style] and style or "Chromatic";

		local configs = CHROMATIC_PRESETS[style];
		local parts, partCount = getParts(char);
		local layerCount = #configs;
		local state = chrom[player];
		local rebuild = not state or state.Char ~= char or state.Count ~= partCount or state.Style ~= style;
		if not rebuild then
			for index, part in ipairs(parts) do if state.PartIdentity[index] ~= part then rebuild = true; break end end;
		end;

		if rebuild then
			clearChromatic(player);
			Chromatic:Ensure(layerCount);

			local worlds = Chromatic.Worlds;
			local models, parents, layers, alphas = {}, {}, {}, {};

			state = {
				Char = char,
				Models = models,
				Parents = parents,
				Layers = layers,
				Alphas = alphas,
				Sources = {},
				Cframes = {},
				Hidden = {},
				N = 0,
				LayerCount = layerCount,
				Count = partCount,
				PartIdentity = table.clone(parts),
				Color = color,
				Style = style,
				Configs = configs,
				Parented = false,
				Tick = CHROM_STATE_STRIDE,
			};

			for layer = 1, layerCount do
				local model = Instance.new("Model");
				model.Name = "ChromaticClone";

				models[layer] = model;
				parents[layer] = worlds[layer];
				layers[layer] = {};
				alphas[layer] = configs[layer].Alpha;
			end;

			local characterMeshes, meshCount = {}, 0;

			for _, child in ipairs(char:GetChildren()) do
				if child:IsA("CharacterMesh") then
					meshCount = meshCount + 1;
					characterMeshes[meshCount] = child;
				end;
			end;

			if meshCount > 0 then
				local sourceHumanoid = char:FindFirstChildOfClass("Humanoid");

				for layer = 1, layerCount do
					local humanoid = (sourceHumanoid and sourceHumanoid:Clone()) or Instance.new("Humanoid");
					humanoid:ClearAllChildren();
					humanoid.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None;
					humanoid.Parent = models[layer];

					for i = 1, meshCount do
						local mesh = characterMeshes[i]:Clone();
						mesh.BaseTextureId = 0;
						mesh.OverlayTextureId = 0;
						mesh.Parent = models[layer];
					end;
				end;
			end;

			local sources, cfs, hidden = state.Sources, state.Cframes, state.Hidden;
			local staged = {};
			local n = 0;

			for i = 1, partCount do
				local source = parts[i];

				if isCP(source) and not isDeformable(source) then
					local ok = true;

					for layer = 1, layerCount do
						local clone = cloneChromaticPart(source, configs[layer], color);
						staged[layer] = clone;

						if not clone then ok = false end;
					end;

					if ok then
						n = n + 1;
						sources[n] = source;
						cfs[n] = staged[1].CFrame;
						hidden[n] = false;

						for layer = 1, layerCount do
							staged[layer].Parent = models[layer];
							layers[layer][n] = staged[layer];
						end;
					else
						for layer = 1, layerCount do
							if staged[layer] then staged[layer]:Destroy() end;
						end;
					end;
				end;
			end;

			state.N = n;
			chrom[player] = state;
		elseif state.Color ~= color then
			state.Color = color;

			for layer = 1, state.LayerCount do
				local clones = state.Layers[layer];
				local col = chromaticColor(color, configs[layer]);

				for i = 1, state.N do
					clones[i].Color = col;
				end;
			end;
		end;
		for layer = 1, state.LayerCount do
			local alpha = ESP.MaterialAlpha(configs[layer].Alpha, extraTransparency);
			if state.Alphas[layer] ~= alpha then
				state.Alphas[layer] = alpha;
				for index = 1, state.N do state.Layers[layer][index].Transparency = state.Hidden[index] and 1 or alpha end;
			end;
		end;
	end;

	local function renderChromatic(player)
		local state = chrom[player];
		if not state then return end;

		local camera = Chromatic:BeginFrame();

		if not camera then
			setChromaticParented(state, false);
			return;
		end;

		local char = state.Char;
		local root = state.Root;

		if not root or root.Parent ~= char then
			root = char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("UpperTorso") or char:FindFirstChild("Torso")
				or char:FindFirstChildWhichIsA("BasePart");
			if root and not root:IsA("BasePart") then root = nil end;
			state.Root = root;
		end;

		if not root then
			setChromaticParented(state, false);
			return;
		end;
		-- through walls unless switched off; then only what is in sight
		if S.MatWalls == false and not ESP.Visibility.Character(camera, char, root) then
			setChromaticParented(state, false);
			return;
		end;
		local point = camera:WorldToViewportPoint(root.Position);
		local onScreen = point.Z > 0
			and point.X > -CHROM_PAD_X and point.X < Chromatic.MaxX
			and point.Y > -CHROM_PAD_Y and point.Y < Chromatic.MaxY;

		if onScreen then
			state.HideAt = nil;

			if not state.Parented then
				if not Chromatic:TakeShow() then return end;
				setChromaticParented(state, true);
			end;
		elseif state.Parented then
			local hideAt = state.HideAt;

			if not hideAt then
				state.HideAt = frameId + CHROM_HIDE_DELAY;
			elseif frameId >= hideAt then
				setChromaticParented(state, false);
				return;
			end;
		else
			return;
		end;

		local n = state.N;
		if n == 0 then return end;

		local tick = state.Tick + 1;
		local refresh = tick >= CHROM_STATE_STRIDE;
		state.Tick = refresh and 0 or tick;

		local sources, cfs, hidden = state.Sources, state.Cframes, state.Hidden;
		local layers, alphas, layerCount = state.Layers, state.Alphas, state.LayerCount;

		for i = 1, n do
			local source = sources[i];
			local isHidden = hidden[i];

			if refresh or source.Parent then
				local nowHidden;

				if source.Parent then
					nowHidden = source.Transparency >= 1 or source.LocalTransparencyModifier >= 1;
				else
					nowHidden = true;
				end;

				if isHidden ~= nowHidden then
					isHidden = nowHidden;
					hidden[i] = nowHidden;

					for layer = 1, layerCount do
						layers[layer][i].Transparency = nowHidden and 1 or alphas[layer];
					end;
				end;
			end;

			if not isHidden then
				local cf = source.CFrame;

				if cfs[i] ~= cf then
					cfs[i] = cf;

					for layer = 1, layerCount do
						layers[layer][i].CFrame = cf;
					end;
				end;
			end;
		end;
	end;

	ESP.Chromatic = {
		Apply = applyChromatic,
		Render = renderChromatic,
		Clear = clearChromatic,
		Tick = function() frameId = frameId + 1 end,
		States = chrom,
	};

	local function items(player, char, enable)

		local now = os.clock();

		if itemClock[player] and now - itemClock[player] < 0.15 then
			if enable and CHROMATIC_PRESETS[S.ItemStyle] and char then
				local held = char:FindFirstChildWhichIsA("Tool");
				if held then renderChromatic(held) end;
			end;

			return;
		end;

		itemClock[player] = now;

		local tool = enable and char and char:FindFirstChildWhichIsA("Tool") or nil;
		local hl = itemHighlights[player];

		if itemHeld[player] and itemHeld[player] ~= tool then
			clearChromatic(itemHeld[player]);
			if itemHeld[player].Parent then restore(itemHeld[player]) end;
			itemHeld[player] = nil;
		end;

		if not tool then
			if hl then hl.Enabled = false end;
			return;
		end;

		local material = MATERIAL_STYLES[S.ItemStyle];

		if material then
			if not hl then
				hl = Instance.new("Highlight");
				hl.Name = SaladUI.RandomString();
				hl.Parent = SaladUI.FXHost;
				itemHighlights[player] = hl;
			end;
			hl.Adornee = tool;
			hl.Enabled = true;
			hl.DepthMode = S.ItemWalls == false and Enum.HighlightDepthMode.Occluded or Enum.HighlightDepthMode.AlwaysOnTop;
			hl.FillColor = S.ItemColor;
			hl.OutlineColor = S.ItemColor;
			hl.FillTransparency = 1;
			hl.OutlineTransparency = S.ItemOutline == false and 1 or 0.15;
		elseif hl then
			hl.Enabled = false;
		end;

		itemHeld[player] = tool;

		if CHROMATIC_PRESETS[S.ItemStyle] then
			restore(tool);
			applyChromatic(tool, tool, S.ItemColor, S.ItemStyle);
			renderChromatic(tool);
		else
			clearChromatic(tool);
			paint(tool, material and S.ItemStyle or nil, S.ItemColor);
		end;
	end;

	local occl = {};

	clearOcclusion = function(player)
		local state = occl[player];
		if not state then return end;

		if state.Model then state.Model:Destroy() end;
		if state.Los then state.Los:Destroy() end;
		if state.Occ then state.Occ:Destroy() end;

		occl[player] = nil;
	end;

	local function applyOcclusion(player, char)
		if not (char and char:IsDescendantOf(workspace)) then
			clearOcclusion(player);
			return;
		end;

		local state = occl[player];

		if not state or state.Char ~= char or not state.Los or not state.Los.Parent then
			clearOcclusion(player);

			local los = Instance.new("Highlight");
			los.DepthMode = Enum.HighlightDepthMode.Occluded;
			los.OutlineTransparency = 1;
			los.Adornee = char;
			los.Parent = SaladUI.FXHost;

			state = { Los = los, Char = char };
			occl[player] = state;
		end;

		state.Los.FillColor = S.MatVisColor;
		state.Los.FillTransparency = S.MatVisT / 100;
	end;

	ESP.ClearOcclusion = clearOcclusion;

	for _, leftover in ipairs(workspace:GetChildren()) do
		if leftover.Name == "ChamsClone" and leftover:IsA("Model") then
			leftover:Destroy();
		end;
	end;

	do
		local host = SaladUI.ScreenGui.Parent;

		if host then
			for _, gui in ipairs(host:GetChildren()) do
				if gui ~= chromGui and gui:IsA("ScreenGui") then
					for _, child in ipairs(gui:GetChildren()) do
						if child:IsA("ViewportFrame") and string.match(child.Name, "^ChromaticLayer") then
							gui:Destroy();
							break;
						end;
					end;
				end;
			end;
		end;
	end;

	local function dropMaterials(player)
		if painted[player] then
			restore(painted[player]);
			painted[player], applied[player] = nil, nil;
		end;
	end;

	local function chams(player, char, enable)
		local hl = highlights[player];
		local state = highlightState[player];

		if not enable then
			if hl and hl.Enabled then hl.Enabled = false end;
			if state then state.Enabled = false end;
			return;
		end;

		if not hl then
			hl = Instance.new("Highlight");
			hl.Name = SaladUI.RandomString();
			hl.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop;
			hl.Parent = SaladUI.FXHost;
			highlights[player] = hl;
			state = {};
			highlightState[player] = state;
		end;
		state = state or {};
		highlightState[player] = state;
		if state.Char ~= char then state.Char = char; hl.Adornee = char end;
		if not state.Enabled or not hl.Enabled then state.Enabled = true; hl.Enabled = true end;
		local walls = S.ChamsWalls ~= false;
		if state.Walls ~= walls then
			state.Walls = walls;
			hl.DepthMode = walls and Enum.HighlightDepthMode.AlwaysOnTop or Enum.HighlightDepthMode.Occluded;
		end;
		local fill = ESP.RoleColor(player, S.ChamsFill);
		if state.Fill ~= fill then state.Fill = fill; hl.FillColor = fill end;
		local fillTransparency = S.ChamsFillT / 100;
		if state.FillTransparency ~= fillTransparency then state.FillTransparency = fillTransparency; hl.FillTransparency = fillTransparency end;
		if state.Outline ~= S.ChamsOutline then state.Outline = S.ChamsOutline; hl.OutlineColor = S.ChamsOutline end;
		local outlineTransparency = S.ChamsOutlineEnabled and S.ChamsOutlineT / 100 or 1;
		if state.OutlineTransparency ~= outlineTransparency then state.OutlineTransparency = outlineTransparency; hl.OutlineTransparency = outlineTransparency end;
	end;

	local wallGlow = {};
	local function dropWall(player)
		local hl = wallGlow[player];
		if hl then hl:Destroy(); wallGlow[player] = nil end;
	end;
	ESP.DropMaterialWalls = function() for player in pairs(wallGlow) do dropWall(player) end end;
	local function keepWall(player, char)
		local hl = wallGlow[player];
		if not (hl and hl.Parent) then
			hl = Instance.new("Highlight");
			hl.Name = SaladUI.RandomString();
			hl.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop;
			hl.Parent = SaladUI.FXHost;
			wallGlow[player] = hl;
		end;
		if hl.Adornee ~= char then hl.Adornee = char end;
		hl.FillColor, hl.OutlineColor = S.MatColor, S.MatColor;
		hl.FillTransparency = math.clamp(0.45 + S.MatTransparency * 0.5, 0, 0.95);
		hl.OutlineTransparency = S.MatOutline == false and 1 or 0.35;
		hl.Enabled = true;
	end;
	Players.PlayerRemoving:Connect(dropWall);

	local function matChams(player, char, enable)
		if not enable or S.MatType == "Chromatic" or S.MatWalls == false then
			dropWall(player);
		else
			keepWall(player, char);
		end;
		if not enable then
			clearChromatic(player);
			clearOcclusion(player);
			dropMaterials(player);
			matClock[player] = nil;
			seenChar[player] = nil;

			return;
		end;
		local tickNow = os.clock();
		if seenChar[player] == char and applied[player] == revision and matClock[player] and tickNow - matClock[player] < 0.15 then return end;

		if painted[player] == char then
			local data = ESP.PaintCache and ESP.PaintCache(char);
			local stale = false;

			if data then
				local seen = 0;

				for part, orig in pairs(data.parts) do
					if part.Parent then
						seen = seen + 1;

						if orig.Wanted and part.Material ~= orig.Wanted then stale = true; break end;
					end;
				end;

				if not stale then
					local live = 0;

					for _, d in ipairs(char:GetDescendants()) do
						if d:IsA("BasePart") then live = live + 1 end;
					end;

					if live ~= seen then stale = true end;
				end;
			end;

			if stale then applied[player] = nil end;
		end;

		if charChanged(player, char) then
			matClock[player] = nil;
			itemClock[player] = nil;

			clearChromatic(player);
			clearOcclusion(player);
			dropMaterials(player);
		end;

		if S.MatType == "Chromatic" then
			local now = os.clock();

			if not matClock[player] or now - matClock[player] >= 0.15 then
				matClock[player] = now;

				clearOcclusion(player);
				dropMaterials(player);
				applyChromatic(player, char, S.MatColor, S.MatStyle, S.MatTransparency);
			end;

			renderChromatic(player);

			return;
		end;

		local now = os.clock();
		if matClock[player] and now - matClock[player] < 0.15 then return end;
		matClock[player] = now;

		clearChromatic(player);

		if S.MatType == "Texture" then

			clearOcclusion(player);

			if painted[player] ~= char then
				if painted[player] then restore(painted[player]) end;
				painted[player], applied[player] = char, nil;
			end;

			if applied[player] ~= revision then
				paint(char, {
					material = nil,
					reflectance = 0,
					transparency = 0,
					tint = true,
					keepTexture = true,
				}, S.MatColor);

				applied[player] = revision;
			end;

			return;
		end;

		if S.MatType == "Flat" then
			dropMaterials(player);
			applyOcclusion(player, char);

			return;
		end;

		clearOcclusion(player);

		if painted[player] ~= char then
			if painted[player] then restore(painted[player]) end;
			painted[player], applied[player] = char, nil;
		end;

		if applied[player] ~= revision then
			paint(char, ESP.ResolveMaterialStyle(S.MatMaterial, S.MatTransparency), S.MatColor);

			applied[player] = revision;
		end;
	end;

	local chamsBloom;

	function ESP.UpdateChamsBloom()
		local want = S.MatChams and (S.MatBloom or 0) > 0;

		if chamsBloom and chamsBloom.Parent == nil then chamsBloom = nil end;

		if want and not chamsBloom then
			chamsBloom = Instance.new("BloomEffect");
			chamsBloom.Name = SaladUI.RandomString();
			chamsBloom.Parent = game:GetService("Lighting");
		end;

		if not chamsBloom then return end;

		chamsBloom.Enabled = want and ALIVE or false;

		if want then
			chamsBloom.Intensity = S.MatBloom;
			chamsBloom.Size = 24;
			chamsBloom.Threshold = 0.9;
		end;
	end;

	task.spawn(function()
		while ALIVE do
			task.wait(1);

			if not ALIVE then break end;

			if chamsBloom and chamsBloom.Parent == nil then pcall(ESP.UpdateChamsBloom) end;
		end;
	end);

	onUnload("chams bloom", function()
		if chamsBloom then pcall(function() chamsBloom:Destroy() end); chamsBloom = nil end;
	end);

	local loopFailures = 0;
	local loopResume = 0;
	local renderWasActive = false;
	local menuHidden = false;

	SaladUI:AddSignal(RunService.RenderStepped:Connect(function() LPH_ATTRIBUTES(VM(NONE));

		if not SaladUI.ScreenGui.Parent then return end;
		if root.Visible then
			if not menuHidden then
				menuHidden = true;
				for _, b in pairs(bundles) do hideSkeleton(b); hideBox(b); b.arrow.Visible = false end;
				for player, highlight in pairs(highlights) do
					highlight.Enabled = false;
					if highlightState[player] then highlightState[player].Enabled = false end;
				end;
				for _, highlight in pairs(itemHighlights) do highlight.Enabled = false end;
				for player in pairs(chrom) do clearChromatic(player) end;
				for player in pairs(occl) do clearOcclusion(player) end;
				for player in pairs(painted) do dropMaterials(player) end;
				for player, tool in pairs(itemHeld) do
					clearChromatic(tool);
					restore(tool);
					itemHeld[player] = nil;
				end;
			end;
			return;
		end;
		menuHidden = false;
		local renderActive = S.Enabled or S.Chams or S.MatChams or S.ItemChams;
		if not renderActive then
			if renderWasActive then
				renderWasActive = false;
				for player in pairs(bundles) do pcall(drop, player) end;
				for player in pairs(highlights) do pcall(drop, player) end;
				table.clear(bundles);
				table.clear(highlights);
			end;
			return;
		end;
		renderWasActive = true;
		Camera = workspace.CurrentCamera;
		if not Camera then return end;
		if loopFailures > 30 then
			if os.clock() < loopResume then return end;

			loopFailures = 0;
		end;

		local ok, err = pcall(function()

		frameId = frameId + 1;

		for _, player in ipairs(Players:GetPlayers()) do
			local isSelf = player == LocalPlayer;
			local char = player.Character;
			local root = char and char:FindFirstChild("HumanoidRootPart");
			local human = char and char:FindFirstChildWhichIsA("Humanoid");
			local alive = root and human and human.Health > 0;

			tint = S.RoleColors and ESP.RoleColor(player, nil) or nil;

			chams(player, char, S.Chams and alive and inTarget(S.ChamsTarget, isSelf));
			matChams(player, char, S.MatChams and alive and inTarget(S.ChamsTarget, isSelf));
			items(player, char, S.ItemChams and alive and inTarget(S.ItemTarget, isSelf));

			local b = bundleOf(player);
			-- drawn through walls: what the ESP is for
			local draw = S.Enabled and alive and inTarget(S.Target, isSelf);
			local at, size, corners;

			if draw and (S.Box or S.Name) then
				at, size, corners = screenBox(char);
			end;

			if not draw then b.arrow.Visible = false end;

			if draw and S.Skeleton then
				drawSkeleton(b, char);
			else
				hideSkeleton(b);
			end;

			if draw and S.Arrows and root and not isSelf then
				local point = Camera:WorldToViewportPoint(root.Position);
				local onScreen = point.Z > 0
					and point.X >= 0 and point.X <= Camera.ViewportSize.X
					and point.Y >= 0 and point.Y <= Camera.ViewportSize.Y;

				if onScreen then
					b.arrow.Visible = false;
				else
					drawArrow(b, root);
				end;
			else
				b.arrow.Visible = false;
			end;

			if draw and S.Box and at then
				drawBox(b, at, size, corners);
			else
				hideBox(b);
			end;

			if draw and (S.Name or S.Distance) and at then

				local dist = (S.Distance and root)
					and math.round((root.Position - Camera.CFrame.Position).Magnitude) or nil;
				local labelName = S.Name and player.DisplayName or "";

				if b.nameDist ~= dist or b.nameFor ~= labelName then
					b.nameDist, b.nameFor = dist, labelName;

					b.name.Text = dist and (labelName ~= "" and (labelName .. "  " .. dist .. "m") or (dist .. "m")) or labelName;
				end;

				b.name.Color = tint or S.NameColor;
				b.name.Position = Vector2.new(at.X + size.X / 2, at.Y - 16);
				b.name.Visible = true;
			else
				b.name.Visible = false;
			end;

		end;

		end);

		if ok then
			loopFailures = 0;
		else
			loopFailures = loopFailures + 1;
			loopResume = os.clock() + 2;

			if loopFailures == 1 then
				recordError("render: " .. tostring(err));

				warn("[visuals] render loop: " .. tostring(err));
			end;
		end;
	end));

	SaladUI:AddSignal(Players.PlayerRemoving:Connect(drop));

	ESP.Clear = function()
		for player in pairs(bundles) do drop(player) end;
		for player in pairs(highlights) do drop(player) end;
	end;
end;
