local Preview = {
	Model = function() return _G.VIEWPORT_CLONE end,
	Refresh = function()
		if type(GLOBAL.__FBPreviewRefresh) == "function" then GLOBAL.__FBPreviewRefresh() end
	end,
};

guard("gunchams", function()
	LPH_ATTRIBUTES(VM(NONE));
	if not Sections.Guns then return end;
	local G = {
		On = false,
		Outline = Color3.fromRGB(255, 190, 60),
		Fill = 0.75,
		Aura = true,
		AuraType = "ForceField",
		AuraColor = Color3.fromRGB(255, 150, 40),
		AuraSpread = 1, AuraSize = 1, AuraSpeed = 1, AuraRate = 1, AuraOpacity = 0.75, AuraGlow = 2,
		Circle = false, CircleStyle = "Soft Ring", CircleColor = Color3.fromRGB(255, 190, 60),
		CircleSize = 4, CircleOpacity = 1, CircleGlow = 2, CircleHeight = 0.06,
		CircleRotation = 0, CircleGround = true, CircleThroughWalls = false,
		Text = true,
		TextColor = Color3.fromRGB(255, 220, 140),
	};

	ESP.GunChams = G;

	local candidates, live = {}, {};
	G.Live = live;
	G.AuraTypes = { "ForceField", "Neon", "Glass", "Metal", "Sparkle", "Fire", "Smoke" };
	local auraTextures = {
		Glow = "p_glow", Bloom = "p_bloom", Stars = "p_star", Sparks = "p_sparkle",
		Hearts = "p_heart", Snow = "p_snowflake", Lightning = "p_lightning",
		Petals = "p_petal1", Flowers = "p_flower1", Leaves = "p_leaf1",
		Bubbles = "p_bubble", Crown = "p_crown", Fireflies = "p_firefly", Flames = "p_flame3",
	};
	for _, name in ipairs({ "Glow", "Bloom", "Stars", "Sparks", "Hearts", "Snow", "Lightning",
		"Petals", "Flowers", "Leaves", "Bubbles", "Crown", "Fireflies", "Flames" }) do
		G.AuraTypes[#G.AuraTypes + 1] = name;
	end;
	Render.gui("gunchams", -6);
	local shells = Instance.new("Folder");

	shells.Name = SaladUI.RandomString();
	shells.Parent = workspace.CurrentCamera;
	SaladUI:AddSignal(workspace:GetPropertyChangedSignal("CurrentCamera"):Connect(function()
		if ALIVE then shells.Parent = workspace.CurrentCamera end;
	end));

	local conns = {};
	local frameConnection;
	local scanGeneration = 0;
	local sweep = 0;

	local function anchorPart(object)
		if object:IsA("BasePart") then return object end;
		if object:IsA("Model") then return object.PrimaryPart or object:FindFirstChildWhichIsA("BasePart", true) end;

		return object:FindFirstChild("Handle") or object:FindFirstChildWhichIsA("BasePart", true);
	end;

	local function ours(object)
		if object:GetAttribute("VisualsGunAura") or object:IsDescendantOf(shells) then return true end;
		for _, player in ipairs(Players:GetPlayers()) do
			if player.Character and object:IsDescendantOf(player.Character) then return true end;
		end;

		return false;
	end;

	local function watch(object)
		if object.Name ~= "GunDrop" or ours(object) then return end;
		if object:IsA("BasePart") or object:IsA("Model") or object:IsA("Tool") then
			candidates[object] = true;
		end;
	end;

	local function forget(object)
		if object.Name == "GunDrop" then candidates[object] = nil end;
	end;

	local function seed(token)
		table.clear(candidates);
		scanDescendantsAsync("gun chams scan", workspace, watch, function()
			return token == scanGeneration and (G.On or G.Circle);
		end, 512);
	end;

	local function restoreNativeAura(record)
		record.NativeActive = false;
		if record.NativeAdded then record.NativeAdded:Disconnect(); record.NativeAdded = nil end;
		for object, saved in pairs(record.Native or {}) do
			if saved.Connection then saved.Connection:Disconnect() end;
			if object.Parent then pcall(function() object[saved.Property] = saved.Value end) end;
		end;
		record.Native = nil;
	end;

	local function nativeAuraProperty(effect, part)
		if effect:GetAttribute("VisualsGunAura") then return nil end;
		if effect:IsA("ParticleEmitter") or effect:IsA("Beam") or effect:IsA("Trail")
			or effect:IsA("Sparkles") or effect:IsA("Fire") or effect:IsA("Smoke")
			or effect:IsA("Light") or effect:IsA("Highlight")
			or effect:IsA("BillboardGui") or effect:IsA("SurfaceGui") then return "Enabled", false end;
		if effect:IsA("BasePart") and effect ~= part then
			local c, name = effect.Color, effect.Name:lower();
			local green = c.G > c.R * 1.15 and c.G > c.B * 1.15;
			local auraName = name:find("aura", 1, true) or name:find("glow", 1, true) or name:find("ring", 1, true) or name:find("effect", 1, true);
			if green and (auraName or effect.Material == Enum.Material.Neon or effect.Material == Enum.Material.ForceField) then
				return "Transparency", 1;
			end;
		end;
	end;

	local function hideNativeAura(record, object, part, effect)
		if record.Native and record.Native[effect] then return end;
		local property, hidden = nativeAuraProperty(effect, part);
		if not property then return end;
		record.Native = record.Native or {};
		local saved = { Property = property, Value = effect[property] };
		record.Native[effect] = saved;
		saved.Connection = effect:GetPropertyChangedSignal(property):Connect(function()
			if not (record.NativeActive and G.On and G.Aura and effect.Parent and effect:IsDescendantOf(object)) then return end;
			if effect[property] ~= hidden then
				saved.Value = effect[property];
				effect[property] = hidden;
			end;
		end);
		effect[property] = hidden;
	end;

	local function suppressNativeAura(record, object, part)
		record.NativeActive = true;
		if not record.NativeAdded then
			record.NativeAdded = object.DescendantAdded:Connect(function(effect)
				if record.NativeActive then hideNativeAura(record, object, record.AuraPart or part, effect) end;
			end);
			record.NativeSweep = 0;
		end;
		local clock = os.clock();
		if clock < record.NativeSweep then return end;
		record.NativeSweep = clock + 0.25;
		for effect, saved in pairs(record.Native or {}) do
			if not effect.Parent or not effect:IsDescendantOf(object) then
				saved.Connection:Disconnect();
				if effect.Parent then pcall(function() effect[saved.Property] = saved.Value end) end;
				record.Native[effect] = nil;
			end;
		end;
		for _, effect in ipairs(object:GetDescendants()) do hideNativeAura(record, object, part, effect) end;
	end;

	local function clearCustomAura(record)
		if record.shell then record.shell:Destroy(); record.shell = nil end;
		if record.AuraEffect then record.AuraEffect:Destroy(); record.AuraEffect = nil end;
		record.AuraPart, record.AuraType = nil, nil;
		record.AuraSettings = nil;
	end;
	local function clearAura(record)
		clearCustomAura(record);
		restoreNativeAura(record);
	end;

	local function drop(object)
		local entry = live[object];

		if not entry then return end;

		live[object] = nil;

		if entry.glow then pcall(function() entry.glow:Destroy() end) end;
		clearAura(entry);
		if entry.Circle then entry.Circle.Part:Destroy(); entry.Circle = nil end;

		destroyAny(entry.label);
	end;

	local function clearAll()
		for object in pairs(live) do drop(object) end;
	end;

	local function makeShell(part)
		local archivable = part.Archivable;

		if not archivable and not pcall(function() part.Archivable = true end) then return nil end;

		local ok, clone = pcall(part.Clone, part);

		if not archivable then pcall(function() part.Archivable = archivable end) end;
		if not ok or not clone then return nil end;

		for _, child in ipairs(clone:GetChildren()) do
			if not child:IsA("DataModelMesh") then child:Destroy() end;
		end;

		local mesh = clone:FindFirstChildWhichIsA("DataModelMesh");

		if mesh then
			pcall(function() mesh.TextureId = "" end);
		end;

		pcall(function() clone.TextureID = "" end);
		clone.Name = "VisualsGunAuraShell";
		clone:SetAttribute(TAG, INIT_GENERATION);
		clone.MaterialVariant = "";
		clone:SetAttribute("VisualsGunAura", true);
		clone.Anchored = true;
		clone.CanCollide = false;
		clone.CanQuery = false;
		clone.CanTouch = false;
		clone.CastShadow = false;
		clone.Massless = true;

		return clone;
	end;

	local function updateAura(record, object, part, visible)
		if not G.Aura then clearAura(record); return end;
		if visible == false then

			clearCustomAura(record);
			suppressNativeAura(record, object, part);
			return;
		end;
		local kind = table.find(G.AuraTypes, G.AuraType) and G.AuraType or "ForceField";
		local node = record.shell or record.AuraEffect;
		if record.AuraType ~= kind or record.AuraPart ~= part or not node or not node.Parent then
			clearCustomAura(record);
			local ok, effect = pcall(function()
				if auraTextures[kind] then
					local attach = Instance.new("Attachment");
					attach:SetAttribute("VisualsGunAura", true);
					local emitter = Instance.new("ParticleEmitter");
					emitter:SetAttribute("VisualsGunAura", true);
					emitter.Enabled = false;
					emitter.LightEmission, emitter.LightInfluence = 1, 0;
					emitter.Lifetime = NumberRange.new(0.6, 1.2);
					emitter.Transparency = NumberSequence.new({
						NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(0.15, 0.25),
						NumberSequenceKeypoint.new(0.7, 0.4), NumberSequenceKeypoint.new(1, 1),
					});
					emitter.Parent, attach.Parent = attach, part;
					task.defer(function()
						local url = Remote.id(Remote.file("particles/" .. auraTextures[kind] .. ".png"));
						if ALIVE and live[object] == record and record.AuraEffect == attach and attach.Parent and url then
							emitter.Texture, emitter.Enabled = url, G.On and G.Aura;
						end;
					end);
					return attach;
				end;
				if kind == "Sparkle" or kind == "Fire" or kind == "Smoke" then
					local effect = Instance.new(kind == "Sparkle" and "Sparkles" or kind);
					effect:SetAttribute("VisualsGunAura", true);
					if kind == "Fire" then effect.Size, effect.Heat = 1.2, 0.3 end;
					if kind == "Smoke" then effect.Size, effect.Opacity, effect.RiseVelocity = 0.75, 0.12, 0.4 end;
					effect.Parent = part;
					return effect;
				end;
				local shell = makeShell(part);
				if shell then shell.Parent = shells end;
				return shell;
			end);
			if not ok or not effect then restoreNativeAura(record); return end;
			if effect:IsA("BasePart") then record.shell = effect else record.AuraEffect = effect end;
			record.AuraType, record.AuraPart = kind, part;
		end;
		if record.shell then
			local shell = record.shell;
			local mesh = shell:FindFirstChildWhichIsA("DataModelMesh");
			local sourceMesh = part:FindFirstChildWhichIsA("DataModelMesh");
			local factor = (1 + 0.08 * G.AuraSpread) * G.AuraSize;
			if mesh and sourceMesh then mesh.Scale = sourceMesh.Scale * factor;
			else shell.Size = part.Size * factor end;
			shell.CFrame, shell.Color = part.CFrame, G.AuraColor;
			shell.Material = Enum.Material[kind];
			shell.Reflectance = kind == "Metal" and 0.3 or kind == "Glass" and 0.12 or 0;
			shell.Transparency = 1 - G.AuraOpacity;
			shell.LocalTransparencyModifier = 0;
		elseif auraTextures[kind] then
			local emitter = record.AuraEffect:FindFirstChildOfClass("ParticleEmitter");
			local settings = { G.AuraColor, G.AuraSpread, G.AuraSpeed, G.AuraSize, G.AuraRate, G.AuraGlow, G.AuraOpacity };
			local changed = not record.AuraSettings;
			for i, value in ipairs(settings) do if not record.AuraSettings or value ~= record.AuraSettings[i] then changed = true end end;
			if emitter and changed then
				record.AuraSettings = settings;
				emitter.Color = ColorSequence.new(G.AuraColor);
				emitter.Speed = NumberRange.new(0.15 * G.AuraSpread * G.AuraSpeed, 1.5 * G.AuraSpread * G.AuraSpeed);
				emitter.SpreadAngle = Vector2.new(180, 180);
				emitter.Size = NumberSequence.new(0.3 * G.AuraSize);
				emitter.Rate, emitter.Brightness = 24 * G.AuraRate, G.AuraGlow;
				emitter.Transparency = NumberSequence.new({
					NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(0.15, 1 - G.AuraOpacity),
					NumberSequenceKeypoint.new(0.7, 1 - G.AuraOpacity * 0.6), NumberSequenceKeypoint.new(1, 1),
				});
			end;
		elseif kind == "Sparkle" then record.AuraEffect.SparkleColor = G.AuraColor;
		elseif kind == "Fire" then
			record.AuraEffect.Size, record.AuraEffect.Heat = 1.2 * G.AuraSize * G.AuraSpread, 0.3 * G.AuraSpeed;
			record.AuraEffect.Color = G.AuraColor;
			record.AuraEffect.SecondaryColor = G.AuraColor:Lerp(Color3.new(1, 1, 1), 0.35);
		else
			record.AuraEffect.Color = G.AuraColor;
			record.AuraEffect.Size = 0.75 * G.AuraSize * G.AuraSpread;
			record.AuraEffect.Opacity, record.AuraEffect.RiseVelocity = 0.2 * G.AuraOpacity, 0.4 * G.AuraSpeed;
		end;
		suppressNativeAura(record, object, part);
	end;

	local function found()
		local list = {};

		for object in pairs(candidates) do
			if object.Name == "GunDrop" and object.Parent and not ours(object) then
				local part = anchorPart(object);

				if part then
					list[#list + 1] = {
						object = object,
						part = part,
						adorn = (object:IsA("BasePart") or object:IsA("Model")) and object or part,
					};
				end;
			end;
		end;

		return list;
	end;

	local guns = {};

	local function step(dt)
		if not (ALIVE and (G.On or G.Circle)) then
			if next(live) then clearAll() end;

			return;
		end;

		sweep = sweep + dt;

		if sweep >= 0.25 then
			sweep = 0;
			guns = found();

			local seen = {};

			for _, entry in ipairs(guns) do seen[entry.object] = true end;
			for object in pairs(live) do
				if not seen[object] then drop(object) end;
			end;
		end;

		local camera = Render.camera();

		if not camera then return end;

		for _, entry in ipairs(guns) do
			local object, part = entry.object, entry.part;

			if not (object.Parent and part and part.Parent) then
				drop(object);
			else
				local record = live[object];
				local visible = ESP.Visibility.Part(camera, part, object);

				if not record then record = {}; live[object] = record end;

				if not record.glow then
					local glow = Instance.new("Highlight");

					glow.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop;
					glow.Parent = SaladUI.FXHost;

					record.glow = glow;
				end;

				record.glow.Adornee = entry.adorn;
				record.glow.OutlineColor = G.Outline;
				record.glow.OutlineTransparency = G.OutlineOn == false and 1 or 0;
				record.glow.FillColor = G.Outline;
				record.glow.FillTransparency = math.clamp(G.Fill, 0, 1);
				-- through walls unless switched off
				record.glow.Enabled = G.On;
				record.glow.DepthMode = G.Walls == false and Enum.HighlightDepthMode.Occluded or Enum.HighlightDepthMode.AlwaysOnTop;

				if G.On then updateAura(record, object, part, visible) else clearAura(record) end;
				if G.Circle and ESP.StaticGunCircle then
					ESP.StaticGunCircle(record, object, part, dt);
				elseif record.Circle then record.Circle.Part:Destroy(); record.Circle = nil end;

				if G.On and G.Text then
					if not record.label then
						local text = drawNew("Text");

						text.Center = true;
						text.Outline = true;
						text.Size = 14;
						text.Font = 2;

						record.label = text;
					end;

					local at, onScreen = camera:WorldToViewportPoint(part.Position);

					if visible and onScreen and at.Z > 0 then
						record.label.Text = "Gun";
						record.label.Color = G.TextColor;
						record.label.Position = Vector2.new(at.X, at.Y);
						record.label.Visible = true;
					else
						record.label.Visible = false;
					end;
				elseif record.label then
					record.label.Visible = false;
				end;
			end;
		end;
	end;

	local function start()
		if conns[1] then return end;
		scanGeneration += 1;
		local token = scanGeneration;
		sweep = 0.25;
		conns[#conns + 1] = workspace.DescendantAdded:Connect(watch);
		conns[#conns + 1] = workspace.DescendantRemoving:Connect(forget);
		frameConnection = RunService.RenderStepped:Connect(step);
		seed(token);
	end;

	local function stop()
		scanGeneration += 1;
		for _, conn in ipairs(conns) do pcall(function() conn:Disconnect() end) end;
		if frameConnection then pcall(function() frameConnection:Disconnect() end); frameConnection = nil end;
		table.clear(conns);
		table.clear(candidates);

		guns = {};

		clearAll();
	end;
	G.SetTracking = function() if G.On or G.Circle then start() else stop() end end;

	local row = Sections.Guns:AddLabel("Dropped Gun");

	row:AddToggle({
		Name = "Dropped Gun",
		Default = false,
		Flag = "gun_chams",
		Callback = function(v)
			G.On = v;

			G.SetTracking();
		end,
	});

	row:AddColorPicker({
		Default = G.Outline,
		Flag = "gun_chams_color",
		Callback = function(v) G.Outline = v end,
	});
	local gunOptions = row:AddOption(1);
	gunOptions:AddLabel("Through Walls"):AddToggle({
		Default = true, Flag = "gun_chams_walls",
		Callback = function(v) G.Walls = v end,
	});
	gunOptions:AddLabel("Outline"):AddToggle({
		Default = true, Flag = "gun_chams_outline",
		Callback = function(v) G.OutlineOn = v end,
	});

	Sections.Guns:AddLabel("Fill"):AddSlider({
		Min = 0, Max = 100, Default = 75, Rounding = 0, Size = 100, Type = "%",
		Flag = "gun_chams_fill",
		Callback = function(v) G.Fill = v / 100 end,
	});

	local auraRow = Sections.Guns:AddLabel("Aura");

	auraRow:AddToggle({
		Name = "Aura",
		Default = true,
		Flag = "gun_chams_aura",
		Callback = function(v)
			G.Aura = v;
			if not v then for _, record in pairs(live) do clearAura(record) end end;
		end,
	});

	auraRow:AddColorPicker({
		Default = G.AuraColor,
		Flag = "gun_chams_aura_color",
		Callback = function(v) G.AuraColor = v end,
	});
	local auraOptions = auraRow:AddOption(1);
	auraOptions:AddLabel("Style"):AddDropdown({
		Default = "ForceField", Values = G.AuraTypes, Flag = "gun_chams_aura_type",
		Callback = function(v) G.AuraType = table.find(G.AuraTypes, v) and v or "ForceField" end,
	});
	for _, setting in ipairs({
		{ "Spread", "AuraSpread", "spread", 0, 800, 100 },
		{ "Size", "AuraSize", "size", 10, 500, 100 },
		{ "Speed", "AuraSpeed", "speed", 0, 500, 100 },
		{ "Rate", "AuraRate", "rate", 0, 400, 100 },
		{ "Opacity", "AuraOpacity", "opacity", 0, 100, 75 },
		{ "Glow", "AuraGlow", "glow", 0, 600, 200 },
	}) do
		local key = setting[2];
		auraOptions:AddLabel(setting[1]):AddSlider({
			Min = setting[4], Max = setting[5], Default = setting[6], Rounding = 0,
			Flag = "gun_chams_aura_" .. setting[3], Callback = function(v) G[key] = v / 100 end,
		});
	end;

	local textRow = Sections.Guns:AddLabel("Label");

	textRow:AddToggle({
		Name = "Label",
		Default = true,
		Flag = "gun_chams_text",
		Callback = function(v) G.Text = v end,
	});

	textRow:AddColorPicker({
		Default = G.TextColor,
		Flag = "gun_chams_text_color",
		Callback = function(v) G.TextColor = v end,
	});

	ESP.ClearGunChams = onUnload("gunchams", function()
		G.On = false;
		G.Circle = false;

		stop();

		pcall(function() shells:Destroy() end);
	end);
end);
local function paintPreview()
	local model = Preview.Model and Preview.Model();
	if not model then return end;

	ESP.Restore(model);

	if S.MatChams and S.MatType ~= "Chromatic" then
		ESP.Paint(model, ESP.ResolveMaterialStyle(S.MatMaterial, S.MatTransparency), S.MatColor);
	elseif S.Chams and S.ChamsFillT < 100 then
		ESP.Paint(model, {
			material = Enum.Material.SmoothPlastic,
			reflectance = 0,
			transparency = S.ChamsFillT / 100,
			tint = true,
		}, S.ChamsFill);
	end;

	local tool = model:FindFirstChildWhichIsA("Tool");
	if tool and S.ItemChams and ESP.MaterialStyles[S.ItemStyle] then
		ESP.Paint(tool, S.ItemStyle, S.ItemColor);
	end;
	if Preview.Chromatic then Preview.Chromatic() end;
end;

Preview.Paint = paintPreview;
Preview.Queue = function() if Preview.Paint then Preview.Paint() end end;
guard("preview parity", function()
	LPH_ATTRIBUTES(VM(NONE));
	local overlay, viewport, model, camera;
	local lines, sprites, particles, emitters, body, bones, layers = {}, {}, {}, {}, {}, {}, {};
	local used, timer, dirtyAt, emitterCursor = 0, 0, nil, 0;
	local nameTag, distanceTag, fill;
	local beams, beamImages, cometImages = {}, {}, {};
	local cometFile = Remote.file("particles/comet_bloom.png");
	local BODY = { Head=true, Torso=true, UpperTorso=true, LowerTorso=true,
		["Left Arm"]=true,["Right Arm"]=true,["Left Leg"]=true,["Right Leg"]=true,
		LeftUpperArm=true,LeftLowerArm=true,LeftHand=true,RightUpperArm=true,RightLowerArm=true,RightHand=true,
		LeftUpperLeg=true,LeftLowerLeg=true,LeftFoot=true,RightUpperLeg=true,RightLowerLeg=true,RightFoot=true };
	local BONES = {
		{"Head","UpperTorso"},{"UpperTorso","LowerTorso"},
		{"UpperTorso","LeftUpperArm"},{"LeftUpperArm","LeftLowerArm"},{"LeftLowerArm","LeftHand"},
		{"UpperTorso","RightUpperArm"},{"RightUpperArm","RightLowerArm"},{"RightLowerArm","RightHand"},
		{"LowerTorso","LeftUpperLeg"},{"LeftUpperLeg","LeftLowerLeg"},{"LeftLowerLeg","LeftFoot"},
		{"LowerTorso","RightUpperLeg"},{"RightUpperLeg","RightLowerLeg"},{"RightLowerLeg","RightFoot"},
		{"Head","Torso"},{"Torso","Left Arm"},{"Torso","Right Arm"},{"Torso","Left Leg"},{"Torso","Right Leg"},
	};
	local function make(class, props)
		local item = Instance.new(class);
		item.Name = SaladUI.RandomString();
		for key, value in pairs(props) do item[key] = value end;
		item.Parent = overlay;
		return item;
	end;
	local function resetLayers()
		for _, layer in ipairs(layers) do layer:Destroy() end;
		table.clear(layers);
	end;
	Preview.Chromatic = function()
		resetLayers();
		local clone = Preview.Model();
		local presets = ESP.ChromaticPresets;
		if not clone or not S.MatChams or S.MatType ~= "Chromatic" or not presets then return end;
		local configs = presets[S.MatStyle] or presets.Chromatic;
		local color = ESP.RoleColor and ESP.RoleColor(LocalPlayer,S.MatColor) or S.MatColor;
		for _, config in ipairs(configs) do
			local layer = Instance.new("Model");
			layer.Name = "PreviewMaterial";
			for _, source in ipairs(clone:GetDescendants()) do
				if source:IsA("BasePart") and ESP.ChromaticSourceAllowed(source) then
					local part = ESP.CloneChromaticPart(source,config,color);
					if part then part.Transparency = 1-(1-config.Alpha)*(1-S.MatTransparency); part.Parent = layer end;
				end;
			end;
			layer.Parent = clone.Parent;
			layers[#layers+1] = layer;
		end;
	end;
	local function label()
		return make("TextLabel",{ AnchorPoint=Vector2.new(.5,.5),BackgroundTransparency=1,
			Font=Enum.Font.GothamMedium,TextSize=14,TextStrokeTransparency=.45,
			Size=UDim2.fromOffset(240,18),Visible=false,ZIndex=8 });
	end;
	local function attach(vp)
		if overlay then overlay:Destroy() end;
		viewport = vp;
		overlay = Instance.new("Frame");
		overlay.Name = "PreviewEffects";
		overlay.Size = UDim2.fromScale(1,1);
		overlay.BackgroundTransparency = 1;
		overlay.BorderSizePixel = 0;
		overlay.ClipsDescendants = true;
		overlay.ZIndex = 5;
		overlay.Parent = vp.Parent;
		nameTag, distanceTag = label(), label();
		fill = make("Frame",{BorderSizePixel=0,Visible=false,ZIndex=6});
		table.clear(lines); table.clear(sprites); table.clear(particles);
		table.clear(beamImages); table.clear(cometImages);
	end;
	local function scan(clone)
		model = clone;
		table.clear(body); table.clear(bones); table.clear(emitters); table.clear(particles);
		for _, sprite in ipairs(sprites) do sprite.Visible = false end;
		for _, part in ipairs(clone:GetChildren()) do if part:IsA("BasePart") and BODY[part.Name] then body[#body+1]=part end end;
		for _, names in ipairs(BONES) do
			local a,b=clone:FindFirstChild(names[1]),clone:FindFirstChild(names[2]);
			if a and b then bones[#bones+1]={a,b} end;
		end;
		table.clear(beams);
		for _, effect in ipairs(clone:GetDescendants()) do
			if effect:IsA("ParticleEmitter") and effect.Texture ~= "" then emitters[#emitters+1]={effect,0}
			elseif effect:IsA("Beam") and #beams < 16 then beams[#beams+1]=effect end;
		end;
		Preview.Chromatic();
	end;
	local function project(point, size)
		LPH_ATTRIBUTES(VM(NONE));
		local p=camera.CFrame:PointToObjectSpace(point);
		if p.Z>=-.05 then return nil end;
		local scale=size.Y/(2*math.tan(math.rad(camera.FieldOfView)/2))/-p.Z;
		return Vector2.new(size.X/2+p.X*scale,size.Y/2-p.Y*scale),scale;
	end;
	local function line(a,b,color,thick)
		LPH_ATTRIBUTES(VM(NONE));
		if not a or not b then return end;
		used+=1;
		local item=lines[used];
		if not item then item=make("Frame",{AnchorPoint=Vector2.new(.5,.5),BorderSizePixel=0,ZIndex=7}); lines[used]=item end;
		local d=b-a;
		item.BackgroundColor3=color; item.BackgroundTransparency=0; item.Visible=true;
		item.Position=UDim2.fromOffset((a.X+b.X)/2,(a.Y+b.Y)/2);
		item.Size=UDim2.fromOffset(d.Magnitude,thick);
		item.Rotation=math.deg(math.atan2(d.Y,d.X));
	end;
	local function sequence(seq,t)
		LPH_ATTRIBUTES(VM(NONE));
		local points=seq.Keypoints;
		for i=2,#points do
			local a,b=points[i-1],points[i];
			if t<=b.Time then
				local f=(t-a.Time)/math.max(.0001,b.Time-a.Time);
				if typeof(a.Value)=="Color3" then return a.Value:Lerp(b.Value,f) end;
				return a.Value+(b.Value-a.Value)*f;
			end;
		end;
		return points[#points].Value;
	end;
	local function range(value) return value.Min+(value.Max-value.Min)*math.random() end;
	local function particlesTick(dt,size)
		LPH_ATTRIBUTES(VM(NONE));
		local budget=4;
		emitterCursor = #emitters > 0 and (emitterCursor % #emitters + 1) or 0;
		for offset=0,#emitters-1 do
			local record=emitters[(emitterCursor+offset-1)%#emitters+1];
			local e=record[1];
			if e.Parent and e.Enabled and e.Rate>0 then
				record[2]=math.min(record[2]+math.min(18,e.Rate)*dt,2);
				if record[2]>=1 and budget>0 and #particles<64 then
					local mount=e.Parent;
					local cf=mount:IsA("Attachment") and mount.WorldCFrame or (mount:IsA("BasePart") and mount.CFrame);
					if cf then
						record[2]-=1; budget-=1;
						local angle=math.rad(e.SpreadAngle.X)*(math.random()-.5);
						local dir=e.EmissionDirection==Enum.NormalId.Top and Vector3.yAxis or e.EmissionDirection==Enum.NormalId.Bottom and -Vector3.yAxis or -Vector3.zAxis;
						local velocity=cf:VectorToWorldSpace(CFrame.Angles(angle,angle,angle):VectorToWorldSpace(dir))*range(e.Speed);
						particles[#particles+1]={e=e,p=cf.Position,v=velocity,t=0,life=math.max(.1,range(e.Lifetime)),rotation=range(e.Rotation),spin=range(e.RotSpeed)};
					end;
				end;
			end;
		end;
		for i=#particles,1,-1 do
			local p=particles[i]; p.t+=dt;
			if p.t>=p.life or not p.e.Parent then table.remove(particles,i)
			else p.v=(p.v+p.e.Acceleration*dt)*math.exp(-p.e.Drag*dt); p.p+=p.v*dt; p.rotation+=p.spin*dt end;
		end;
		for i,p in ipairs(particles) do
			local sprite=sprites[i];
			if not sprite then sprite=make("ImageLabel",{BackgroundTransparency=1,AnchorPoint=Vector2.new(.5,.5),ZIndex=5}); sprites[i]=sprite end;
			local point,scale=project(p.p,size);
			sprite.Visible=point~=nil;
			if point then
				local phase=math.clamp(p.t/p.life,0,1);
				local width=math.clamp(sequence(p.e.Size,phase)*scale,1,160);
				sprite.Image=p.e.Texture;
                local color=sequence(p.e.Color,phase);
                if p.e.LightInfluence==0 then
                    local gain=math.max(0,p.e.Brightness);
                    color=Color3.new(math.clamp(color.R*gain,0,1),math.clamp(color.G*gain,0,1),math.clamp(color.B*gain,0,1));
                end;
                sprite.ImageColor3=color;
				sprite.ImageTransparency=math.clamp(sequence(p.e.Transparency,phase),0,1);
				sprite.Position=UDim2.fromOffset(point.X,point.Y); sprite.Size=UDim2.fromOffset(width,width); sprite.Rotation=p.rotation;
			end;
		end;
		for i=#particles+1,#sprites do sprites[i].Visible=false end;
	end;
	local function beamsTick(size)
		LPH_ATTRIBUTES(VM(NONE));
		local count = 0;
		for _, beam in ipairs(beams) do
			local a,b=beam.Attachment0,beam.Attachment1;
			if beam.Parent and beam.Enabled and a and b and a.Parent and b.Parent then
				local p0,p3=a.WorldPosition,b.WorldPosition;
				local p1=p0+a.WorldCFrame.RightVector*beam.CurveSize0;
				local p2=p3-b.WorldCFrame.RightVector*beam.CurveSize1;
				local segments=math.clamp(beam.Segments,1,4);
				local previous=project(p0,size);
				for i=1,segments do
					local t=i/segments; local u=1-t;
					local current,scale=project(p0*(u*u*u)+p1*(3*u*u*t)+p2*(3*u*t*t)+p3*(t*t*t),size);
					if previous and current and count < 64 then
						count+=1;
						local image=beamImages[count];
						if not image then image=make("ImageLabel",{AnchorPoint=Vector2.new(.5,.5),BorderSizePixel=0,BackgroundTransparency=1,ZIndex=5}); beamImages[count]=image end;
						local delta=current-previous; local phase=(i-.5)/segments;
						local alpha=math.clamp(sequence(beam.Transparency,phase),0,1);
						local color=sequence(beam.Color,phase);
						image.Visible=true; image.Position=UDim2.fromOffset((previous.X+current.X)/2,(previous.Y+current.Y)/2);
						image.Size=UDim2.fromOffset(delta.Magnitude+1,math.clamp((beam.Width0+(beam.Width1-beam.Width0)*phase)*scale,1,160));
						image.Rotation=math.deg(math.atan2(delta.Y,delta.X)); image.Image=beam.Texture;
						image.ImageColor3=color; image.ImageTransparency=alpha;
						image.BackgroundColor3=color; image.BackgroundTransparency=beam.Texture=="" and alpha or 1;
					end;
					previous=current;
				end;
			end;
		end;
		for i=count+1,#beamImages do beamImages[i].Visible=false end;
	end;
	local function cometTick(size)
		LPH_ATTRIBUTES(VM(NONE));
		local A=ESP.Aura; local count=0;
		local torso=model and (model:FindFirstChild("UpperTorso") or model:FindFirstChild("Torso") or model:FindFirstChild("HumanoidRootPart"));
		local texture=A and A.On and A.Types.Comet and torso and Remote.cachedId(cometFile);
		if texture then
			local samples=math.clamp(math.floor(A.TrailLength/6),6,12);
			local distance=math.max(1.5,(camera.CFrame.Position-torso.Position).Magnitude);
			local time=DateTime.now().UnixTimestampMillis;
			local base=math.clamp(A.BloomSize*A.Size*size.Y/720/distance,1,160);
			for i=0,samples-1 do
				local angle=.1*(time-i*1.5*300/samples*A.TrailStep)/(30/A.Speed);
				local s,c=math.sin(angle)*A.Radius,math.cos(angle)*A.Radius;
				local phase=i/samples;
				local diameter=math.max(1,base*(1-phase)^1.1);
				local alpha=math.clamp((1-phase*phase)*.4*A.Glow*.5,0,.95);
				for _, offset in ipairs({Vector3.new(s,c,-c),Vector3.new(-s,s,-c),Vector3.new(-s,-s,c)}) do
					count+=1;
					local image=cometImages[count];
					if not image then image=make("ImageLabel",{BackgroundTransparency=1,BorderSizePixel=0,AnchorPoint=Vector2.new(.5,.5),ZIndex=5}); cometImages[count]=image end;
					local point=project(torso.Position+offset,size);
					image.Visible=point~=nil and alpha>.005;
					if point then
						image.Image=texture; image.ImageColor3=A.Color; image.ImageTransparency=1-alpha;
						image.Position=UDim2.fromOffset(point.X,point.Y); image.Size=UDim2.fromOffset(diameter,diameter); image.Rotation=(time/5+i*5)%180;
					end;
				end;
			end;
		end;
		for i=count+1,#cometImages do cometImages[i].Visible=false end;
	end;
	local function draw(size)
		LPH_ATTRIBUTES(VM(NONE));
		used=0; fill.Visible=false; nameTag.Visible=false; distanceTag.Visible=false;
		if S.Enabled then
			local lo=Vector3.new(math.huge,math.huge,math.huge); local hi=-lo;
			for _, p in ipairs(body) do
				for x=-1,1,2 do for y=-1,1,2 do for z=-1,1,2 do
					local point=p.CFrame*(p.Size*Vector3.new(x,y,z)/2); lo=lo:Min(point); hi=hi:Max(point);
				end end end;
			end;
			if #body>0 then
				local corners={}; local min=Vector2.new(math.huge,math.huge); local max=-min;
				for x=0,1 do for y=0,1 do for z=0,1 do
					local point=project(Vector3.new(x==0 and lo.X or hi.X,y==0 and lo.Y or hi.Y,z==0 and lo.Z or hi.Z),size);
					corners[#corners+1]=point; if point then min=min:Min(point); max=max:Max(point) end;
				end end end;
				if max.X>min.X then
					local a,b=min-Vector2.new(2,2),max+Vector2.new(2,2);
					local color=ESP.RoleColor and ESP.RoleColor(LocalPlayer,S.BoxColor) or S.BoxColor;
					local thick=math.clamp(S.BoxThickness,1,4);
					if S.Box then
						if S.BoxStyle=="3D" then
							for _, edge in ipairs({{1,2},{1,3},{1,5},{2,4},{2,6},{3,4},{3,7},{4,8},{5,6},{5,7},{6,8},{7,8}}) do line(corners[edge[1]],corners[edge[2]],color,thick) end;
						else
							local tl,tr,bl,br=a,Vector2.new(b.X,a.Y),Vector2.new(a.X,b.Y),b;
							if S.BoxStyle=="Corner" or S.BoxStyle=="Bracket" then
								local dx,dy=(b.X-a.X)*.28,(S.BoxStyle=="Bracket" and b.Y-a.Y or (b.Y-a.Y)*.28);
								for _, p in ipairs({{tl,1,1},{tr,-1,1},{bl,1,-1},{br,-1,-1}}) do line(p[1],p[1]+Vector2.new(dx*p[2],0),color,thick); line(p[1],p[1]+Vector2.new(0,dy*p[3]),color,thick) end;
							else line(tl,tr,color,thick); line(tr,br,color,thick); line(br,bl,color,thick); line(bl,tl,color,thick) end;
						end;
						fill.Visible=S.BoxFilled; fill.BackgroundColor3=color; fill.BackgroundTransparency=1-S.BoxFillOpacity/100;
						fill.Position=UDim2.fromOffset(a.X,a.Y); fill.Size=UDim2.fromOffset(b.X-a.X,b.Y-a.Y);
					end;
					if S.Name then nameTag.Visible=true; nameTag.Text=LocalPlayer.DisplayName; nameTag.TextColor3=ESP.RoleColor(LocalPlayer,S.NameColor); nameTag.Position=UDim2.fromOffset((a.X+b.X)/2,a.Y-10) end;
					if S.Distance then distanceTag.Visible=true; distanceTag.Text=string.format("%dm",math.floor((camera.CFrame.Position-(lo+hi)/2).Magnitude+.5)); distanceTag.TextColor3=S.NameColor; distanceTag.Position=UDim2.fromOffset((a.X+b.X)/2,b.Y+10) end;
				end;
			end;
			if S.Skeleton then for _, bone in ipairs(bones) do line(project(bone[1].Position,size),project(bone[2].Position,size),ESP.RoleColor(LocalPlayer,S.SkeletonColor),1) end end;
		end;
		for i=used+1,#lines do lines[i].Visible=false end;
	end;
	Preview.ReadAura=function() dirtyAt=os.clock() end;
	Preview.Queue=function(flag)
		if type(flag)=="string" then
			for _, prefix in ipairs({"model","korblox","headless","hairless","no_accessories","character","cosmetic","aura","china","trail","skin"}) do
				if flag:sub(1,#prefix)==prefix then dirtyAt=os.clock(); return end;
			end;
		end;
		if Preview.Paint then Preview.Paint() end;
	end;
	SaladUI:AddSignal(RunService.RenderStepped:Connect(function(dt)
		LPH_ATTRIBUTES(VM(NONE));
		local vp,clone=_G.VIEWPORT_FRAME,Preview.Model();
		local active=GLOBAL.VISUALS_TAB_OPEN==true and vp and vp.Parent and clone and clone.Parent;
		if not active then if overlay then overlay.Visible=false end; timer=0; return end;
		if vp~=viewport or not overlay or not overlay.Parent then attach(vp) end;
		overlay.Visible=true;
		if dirtyAt and os.clock()-dirtyAt>.2 and not SaladUI.Lib.configApplying then dirtyAt=nil; Preview.Refresh(); return end;
		if clone~=model then scan(clone) end;
		camera=vp.CurrentCamera;
		if not camera then return end;
		timer+=dt; if timer<1/30 then return end;
		local elapsed=math.min(timer,.1); timer=0;
		local size=vp.AbsoluteSize; if size.X<8 or size.Y<8 then return end;
		draw(size); particlesTick(elapsed,size); beamsTick(size); cometTick(size);
	end));
	task.defer(function()
		if ESP.GameFX and ESP.GameFX.OnChange then ESP.GameFX.OnChange(Preview.ReadAura) end;
	end);
	onUnload("preview parity",function() resetLayers(); if overlay then overlay:Destroy() end end);
end);

ESP.Preview = Preview;
