guard("shaders", function()
	LPH_ATTRIBUTES(VM(NONE));
	local Lighting = game:GetService("Lighting");

	local bloom, rays, blur, grade, depth;
	local keepers = {};

	local function effect(class, props, adopt)
		local inst;

		local function make(old)
			local fresh = Instance.new(class);

			fresh.Name = SaladUI.RandomString();
			fresh.Enabled = false;

			for key, value in pairs(props) do fresh[key] = value end;

			if old then
				for key in pairs(props) do
					pcall(function() fresh[key] = old[key] end);
				end;

				pcall(function() fresh.Enabled = old.Enabled end);
			end;

			fresh.Parent = Lighting;

			return fresh;
		end;

		inst = make(nil);

		keepers[#keepers + 1] = function()
			if inst.Parent ~= Lighting then
				inst = make(inst);

				adopt(inst);
			end;
		end;

		return inst;
	end;

	bloom = effect("BloomEffect", { Intensity = 0.6, Size = 24, Threshold = 0.9 },
		function(v) bloom = v end);
	rays = effect("SunRaysEffect", { Intensity = 0.15, Spread = 0.9 },
		function(v) rays = v end);
	blur = effect("BlurEffect", { Size = 8 },
		function(v) blur = v end);
	grade = effect("ColorCorrectionEffect", { Brightness = 0, Contrast = 0.1, Saturation = 0.2, TintColor = Color3.fromRGB(255, 255, 255) },
		function(v) grade = v end);
	depth = effect("DepthOfFieldEffect", { FarIntensity = 0, NearIntensity = 0, FocusDistance = 70, InFocusRadius = 55 },
		function(v) depth = v end);
	local CLOUD = { On = false, Cover = 0.2, Density = 0.4, Color = Color3.new(1, 1, 1) };
	local cloudMine, cloudSaved;
	local function applyCloud()
		local terrain = workspace:FindFirstChildOfClass("Terrain");
		if not terrain then return end;
		if not CLOUD.On then
			if cloudMine then cloudMine.Parent = nil end;
			if cloudSaved then pcall(function() cloudSaved.Parent = terrain end); cloudSaved = nil end;
			return;
		end;
		if not cloudMine then cloudMine = Instance.new("Clouds"); cloudMine.Name = SaladUI.RandomString() end;
		local existing = terrain:FindFirstChildOfClass("Clouds");
		if existing and existing ~= cloudMine then cloudSaved = existing; existing.Parent = nil end;
		cloudMine.Cover, cloudMine.Density, cloudMine.Color = CLOUD.Cover, CLOUD.Density, CLOUD.Color;
		cloudMine.Parent = terrain;
	end;
	onUnload("shader clouds", function()
		CLOUD.On = false; pcall(applyCloud);
		if cloudMine then cloudMine:Destroy(); cloudMine = nil end;
	end);

	task.spawn(function()
		while ALIVE do
			task.wait(1);

			if not ALIVE then break end;

			for _, keeper in ipairs(keepers) do pcall(keeper) end;
		end;
	end);

	local AIR = {
		On = false, Density = 0.3, Haze = 0, Glare = 0,
		Color = Color3.fromRGB(199, 199, 199), Decay = Color3.fromRGB(106, 112, 125),
	};

	local airMine;
	local airSaved = {};
	local function restoreAir()
		if airMine then airMine.Parent = nil end;
		for instance, parent in pairs(airSaved) do
			pcall(function() instance.Parent = parent end);
			airSaved[instance] = nil;
		end;
	end;
	local function applyAir()
		local fog = ESP.Fog;
		local fogOn = fog and fog.On;
		if not (AIR.On or fogOn) then restoreAir(); return end;
		if not airMine then
			airMine = Instance.new("Atmosphere");
			airMine.Name = SaladUI.RandomString();
		end;
		for _, instance in ipairs(Lighting:GetChildren()) do
			if instance:IsA("Atmosphere") and instance ~= airMine then
				airSaved[instance] = instance.Parent;
				instance.Parent = nil;
			end;
		end;
		airMine.Density = math.clamp(fogOn and fog.Density / 100 or AIR.Density, 0, 1);
		airMine.Offset = math.clamp(fogOn and (fog.Offset or 0) or (AIR.Offset or 0), -1, 1);
		airMine.Color = fogOn and fog.Color or AIR.Color;
		airMine.Haze = AIR.On and math.clamp(AIR.Haze, 0, 10) or 0;
		airMine.Glare = AIR.On and math.clamp(AIR.Glare, 0, 10) or 0;
		airMine.Decay = AIR.On and AIR.Decay or Color3.fromRGB(106, 112, 125);
		airMine.Parent = Lighting;
	end;
	SaladUI:AddSignal(Lighting.ChildAdded:Connect(function(instance)
		if instance:IsA("Atmosphere") and instance ~= airMine and (AIR.On or (ESP.Fog and ESP.Fog.On)) then
			airSaved[instance] = instance.Parent;
			instance.Parent = nil;
		end;
	end));

	ESP.ApplyAir = applyAir;
	ESP.Air = AIR;

	onUnload("atmosphere", function()
		AIR.On = false;

		if ESP.Fog then ESP.Fog.On = false end;

		pcall(applyAir);
		if airMine then pcall(function() airMine:Destroy() end); airMine = nil end;
	end);

	ESP.Shaders = setmetatable({}, {__index=function(_, key)
		if key == "bloom" then return bloom elseif key == "rays" then return rays elseif key == "blur" then return blur elseif key == "grade" then return grade elseif key == "depth" then return depth end;
	end});

	ESP.ClearShaders = function()
		ESP.ShaderLighting = nil;
		if ESP.RestoreFog then pcall(ESP.RestoreFog) end;
		if ESP.RestoreLighting then pcall(ESP.RestoreLighting) end;

		if ESP.RestoreSky then pcall(ESP.RestoreSky) end;

		bloom:Destroy();
		rays:Destroy();
		blur:Destroy();
		grade:Destroy();
		depth:Destroy();
		CLOUD.On = false; applyCloud();

		AIR.On = false;

		if ESP.Fog then ESP.Fog.On = false end;

		pcall(applyAir);
	end;

	local function rgb(r, g, b) return Color3.fromRGB(r, g, b) end;

	local PRESETS = {
