		{id="Unusual/VerdantLaurel",g="evade",kind="Unusual",label="Verdant Laurel",image="rbxassetid://132790033099748"},
		{id="Unusual/OakBlessing",g="evade",kind="Unusual",label="Oak Blessing",image="rbxassetid://110236140125732"},
		{id="Unusual/EasterEggHunter",g="evade",kind="Unusual",label="Easter Egg Hunter",image="rbxassetid://103784839343919"},
		{id="Unusual/LotusRift",g="evade",kind="Unusual",label="Lotus Rift",image="rbxassetid://123940738438234"},
		{id="Unusual/MonarchWings",g="evade",kind="Unusual",label="Monarch Wings",image="rbxassetid://73715962984251"},
		{id="Cosmetic/LeviathanAnchor",g="evade",kind="Cosmetic",label="Leviathan Anchor",image="rbxassetid://94146244556464"},
		{id="Unusual/RetroSunset",g="evade",kind="Unusual",label="Retro Sunset",image="rbxassetid://106466437282098"},
		{id="Unusual/TropicalNatureCrown",g="evade",kind="Unusual",label="Tropical Nature Crown",image="rbxassetid://136815544544764"},
		{id="Unusual/SunnyDay",g="evade",kind="Unusual",label="Sunny Day",image="rbxassetid://75344077957401"},
		{id="Unusual/DuckyWaterFall",g="evade",kind="Unusual",label="Ducky WaterFall",image="rbxassetid://126390064469383"},
		{id="Unusual/BlazingSun",g="evade",kind="Unusual",label="Blazing Sun",image="rbxassetid://125398027841020"},
		{id="Unusual/SkylineVinyl",g="evade",kind="Unusual",label="Skyline Vinyl",image="rbxassetid://109696031257894"},
		{id="Unusual/OceanSymphony",g="evade",kind="Unusual",label="Ocean Symphony",image="rbxassetid://124244987665503"},
		{id="Unusual/LuminescentJellyfish",g="evade",kind="Unusual",label="Luminescent Jellyfish",image="rbxassetid://85112817012734"},
		{id="Cosmetic/GhostlyAnchor",g="evade",kind="Cosmetic",label="Ghostly Anchor",image="rbxassetid://82798669195289"}
	};

	local FX = { Catalog = CATALOG, ById = {}, Loaded = {}, TrailMoving = false };
	ESP.GameFX = FX;
	for _, entry in ipairs(CATALOG) do FX.ById[entry.id] = entry end;

	---------------------------------------------------------------- data --
	local REF = {};
	local ENVIRONMENT = {
		math = math,
		R = function(i) return setmetatable({ i }, REF) end,
		V3 = Vector3.new, V2 = Vector2.new, C3 = Color3.new, CF = CFrame.new,
		BC = function(n) return BrickColor.new(n) end,
		UD = function(s, o) return UDim.new(s, o) end,
		UD2 = function(a, b, c, d) return UDim2.new(a, b, c, d) end,
		RC = function(a, b, c, d) return Rect.new(a, b, c, d) end,
		NR = function(a, b) return NumberRange.new(a, b) end,
		E = function(t, n)
			local ok, v = pcall(function() return Enum[t][n] end);
			return ok and v or nil;
		end,
		CS = function(t)
			local k = {};
			for i = 1, #t, 4 do k[#k + 1] = ColorSequenceKeypoint.new(t[i], Color3.new(t[i + 1], t[i + 2], t[i + 3])) end;
			return ColorSequence.new(k);
		end,
		NS = function(t)
			local k = {};
			for i = 1, #t, 3 do k[#k + 1] = NumberSequenceKeypoint.new(t[i], t[i + 1], t[i + 2]) end;
			return NumberSequence.new(k);
		end,
		FT = function(family, weight, style)
			local ok, f = pcall(Font.new, family, Enum.FontWeight[weight], Enum.FontStyle[style]);
			return ok and f or nil;
		end,
		FC = function(names)
			local list = {};
			for _, n in ipairs(names) do list[#list + 1] = Enum.NormalId[n] end;
			return Faces.new(unpack(list));
		end,
		AX = function(names)
			local list = {};
			for _, n in ipairs(names) do list[#list + 1] = Enum.Axis[n] end;
			return Axes.new(unpack(list));
		end,
		PP = function(d, f, e, fw, ew) return PhysicalProperties.new(d, f, e, fw, ew) end,
	};

	local loading = {};
	local function loadGame(name)
		if FX.Loaded[name] then return FX.Loaded[name] end;
		if loading[name] then
			local deadline = os.clock() + 60;
			repeat task.wait(0.05) until not loading[name] or not ALIVE or os.clock() > deadline;
			return FX.Loaded[name];
		end;
		loading[name] = true;
		local ok, result = pcall(function()
			local body = Remote.body("fx/" .. name .. ".bin");
			local path = "fxdata/" .. name .. ".lua";
			if not body and isfile and readfile then
				local okF, has = pcall(isfile, path);
				if okF and has then
					local okR, text = pcall(readfile, path);
					if okR then body = text end;
				end;
			end;
			if type(body) ~= "string" or body:sub(1, 7) ~= "return " then error("fx/" .. name .. ".bin did not arrive") end;
			local chunk, err = loadstring(body, "@fx_" .. name);
			if not chunk then error(err) end;
			setfenv(chunk, setmetatable({}, { __index = ENVIRONMENT }));
			local data = chunk();
			local byId = {};
			for _, item in ipairs(data.items) do byId[item.id] = item end;
			return byId;
		end);
		loading[name] = nil;
		if not ok then recordError("game fx " .. name .. ": " .. tostring(result)); return nil end;
		FX.Loaded[name] = result;
		return result;
	end;

	---------------------------------------------------------------- body --
	-- both games' effects are built for R6; on R15 each R6 part lands where
	-- its centre would be
	local ALIAS = { LeftArm = "Left Arm", RightArm = "Right Arm", LeftLeg = "Left Leg", RightLeg = "Right Leg" };
	local R15 = {
		Torso = "UpperTorso",
		["Left Arm"] = "LeftUpperArm", ["Right Arm"] = "RightUpperArm",
		["Left Leg"] = "LeftUpperLeg", ["Right Leg"] = "RightUpperLeg",
	};

	local function limb(char, name)
		name = ALIAS[name] or name;
		local p = char:FindFirstChild(name);
		if p and p:IsA("BasePart") then return p, CFrame.new() end;
		-- a drawn rig without a root part: the R6 torso sits exactly there
		if name == "HumanoidRootPart" then return limb(char, "Torso") end;
		local stand = R15[name];
		local q = stand and char:FindFirstChild(stand);
		if not (q and q:IsA("BasePart")) then return nil end;
		if name == "Torso" then
			local root = char:FindFirstChild("HumanoidRootPart");
			return q, CFrame.new(root and q.CFrame:PointToObjectSpace(root.Position) or Vector3.zero);
		end;
		return q, CFrame.new(0, -q.Size.Y / 2, 0);
	end;

	local R6_BODY = { "Torso", "Right Arm", "Left Arm", "Right Leg", "Left Leg", "Head" };
	local function bodyParts(char)
		local out = {};
		for _, n in ipairs(R6_BODY) do
			local p = char:FindFirstChild(n);
			if p and p:IsA("BasePart") then out[#out + 1] = p end;
		end;
		if #out <= 1 then
			for _, p in ipairs(char:GetChildren()) do
				if p:IsA("BasePart") and p.Name ~= "HumanoidRootPart" and not table.find(out, p) then out[#out + 1] = p end;
			end;
		end;
		return out;
	end;

	-- the model the body is actually drawn on: the character, or in games
	-- that draw it on a separate rig (Evade keeps it in workspace.Rigs)
	local function shown(m)
		local torso = m and (m:FindFirstChild("Torso") or m:FindFirstChild("UpperTorso") or m:FindFirstChild("HumanoidRootPart"));
		return torso ~= nil and torso:IsA("BasePart");
	end;
	local function drawn(m)
		for _, n in ipairs({ "Torso", "UpperTorso", "Head" }) do
			local p = m:FindFirstChild(n);
			if p and p:IsA("BasePart") and p.Transparency < 1 then return true end;
		end;
		return false;
	end;
	local function wearer()
		local char = LocalPlayer.Character;
		local rigs = workspace:FindFirstChild("Rigs");
		local rig = rigs and rigs:FindFirstChild(LocalPlayer.Name);
		if char and char.Parent and shown(char) and drawn(char) then return char end;
		if rig and rig:IsA("Model") and shown(rig) then return rig end;
		if char and char.Parent and shown(char) then return char end;
		return nil;
	end;
	FX.Wearer = wearer;

	--------------------------------------------------------------- build --
	-- AssetService takes Content now; the bare string it was given failed and
	-- left a plain MeshPart - a box - for every mesh of an aura. Both services
	-- are tried, each with a deadline (some meshes never answer); a mesh
	-- neither hands over is drawn as a SpecialMesh on a Part instead.
	local meshCache = {};
	local function within(seconds, fn)
		local done, value = false, nil;
		task.spawn(function()
			local ok, made = pcall(fn);
			value, done = ok and made or nil, true;
		end);
		local deadline = os.clock() + seconds;
		while not done and os.clock() < deadline do task.wait(0.05) end;
		return typeof(value) == "Instance" and value or nil;
	end;
	local function meshPart(id)
		local uri = "rbxassetid://" .. (string.match(id, "(%d+)%s*$") or "");
		local base = meshCache[uri];
		if base == nil then
			base = within(6, function()
				return game:GetService("InsertService"):CreateMeshPartAsync(uri, Enum.CollisionFidelity.Box, Enum.RenderFidelity.Precise);
			end) or within(6, function()
				return AssetService:CreateMeshPartAsync(Content.fromUri(uri));
			end) or false;
			meshCache[uri] = base;
		end;
		if base then return base:Clone() end;
		local part, mesh = Instance.new("Part"), Instance.new("SpecialMesh");
		mesh.MeshType, mesh.MeshId = Enum.MeshType.FileMesh, uri;
		mesh.Parent = part;
		return part, mesh;
	end;

	-- A plain block whose only job is to hold effects. The games hide these
	-- from their own code; rebuilt as dumped they showed as a box round the
	-- particles (Evade's gem auras, Christmas Tree, Snowflakes...).
	local HOLDS = { Attachment = true, ParticleEmitter = true, Beam = true, Trail = true, Bone = true, Folder = true,
		PointLight = true, SpotLight = true, SurfaceLight = true, Fire = true, Smoke = true, Sparkles = true };
	local SHOWS = { SpecialMesh = true, BlockMesh = true, CylinderMesh = true, Decal = true, Texture = true, SurfaceGui = true };
	local function carrier(node)
		local holds = false;
		for _, c in ipairs(node.k or {}) do
			if SHOWS[c.c] then return false end;
			if HOLDS[c.c] then holds = true end;
		end;
		return holds;
	end;

	local function build(node, ctx)
		if node.limb then
			local target = limb(ctx.char, node.n);
			if not target then return nil end;
			ctx.map[node.i] = target;
			for _, c in ipairs(node.k or {}) do
				local child = build(c, ctx);
				if child then ctx.limbKids[#ctx.limbKids + 1] = { child, target, node.cf } end;
			end;
			return nil;
		end;
		local inst, standIn;
		if node.c == "MeshPart" and node.m and node.m ~= "" then
			inst, standIn = meshPart(node.m);
		else
			local ok, made = pcall(Instance.new, node.c);
			if not ok then return nil end;
			inst = made;
		end;
		inst.Name = node.n;
		ctx.map[node.i] = inst;
		for k, v in pairs(node.p) do
			if getmetatable(v) == REF then
				ctx.refs[#ctx.refs + 1] = { inst, k, v[1] };
			else
				pcall(function() inst[k] = v end);
			end;
		end;
		if node.a then
			for k, v in pairs(node.a) do pcall(inst.SetAttribute, inst, k, v) end;
		end;
		if standIn then
			-- a SpecialMesh draws at the mesh's own size times Scale; the dump
			-- kept that size (InitialSize), and without it nothing beats a box
			local native = node.z;
			if typeof(native) == "Vector3" and native.X > 0 and native.Y > 0 and native.Z > 0 then
				standIn.Scale = inst.Size / native;
			else
				inst.Transparency = 1;
			end;
			if type(node.p.TextureID) == "string" then standIn.TextureId = node.p.TextureID end;
		end;
		if node.c == "Part" and inst.Shape == Enum.PartType.Block and carrier(node) then
			inst.Transparency = 1;
		end;
		if inst:IsA("BasePart") then
			-- worn, never simulated: nothing here may push or weigh the body
			inst.Anchored, inst.CanCollide, inst.CanTouch, inst.CanQuery = false, false, false, false;
			inst.Massless = true;
		end;
		for _, c in ipairs(node.k or {}) do
			if c.c == "SurfaceAppearance" then
				-- a SurfaceAppearance made on the client never loads; its
				-- colour map on the mesh is the closest that renders
				local map = c.p.ColorMap;
				if type(map) == "string" and map ~= "" then
					if standIn then
						if standIn.TextureId == "" then standIn.TextureId = map end;
					elseif inst:IsA("MeshPart") and inst.TextureID == "" then
						pcall(function() inst.TextureID = map end);
					end;
				end;
			else
				local child = build(c, ctx);
				if child then child.Parent = inst end;
			end;
		end;
		return inst;
	end;

	local function partsUnder(root)
		local out = root:IsA("BasePart") and { root } or {};
		for _, d in ipairs(root:GetDescendants()) do
			if d:IsA("BasePart") then out[#out + 1] = d end;
		end;
		return out;
	end;

	------------------------------------------------------------- tuning --
	-- what every emitter, beam, trail and light started as, so the sliders
	-- scale from the original instead of compounding
	local tuning = { aura = {}, trail = {}, cosmetic = {} };


	local function scaled(sequence, factor)
		if factor == 1 then return sequence end;
		local points = {};
		for i, k in ipairs(sequence.Keypoints) do
			points[i] = NumberSequenceKeypoint.new(k.Time, k.Value * factor, k.Envelope * factor);
		end;
		return NumberSequence.new(points);
	end;

	local function movedFrame(frame, offset, scale)
		return CFrame.new(frame.Position * scale + offset) * (frame - frame.Position);
	end;

	local function captureCosmeticTransforms(l)
		l.transforms = {};

		-- everything this effect brought with it, so the joint that ties the
		-- piece to the body can be told apart from the ones holding it together
		local ours, mine = {}, {};
		for _, object in ipairs(l.worn or {}) do
			ours[object] = true;
			mine[#mine + 1] = object;
			for _, d in ipairs(object:GetDescendants()) do
				ours[d] = true;
				mine[#mine + 1] = d;
			end;
		end;

		-- every piece of it, because the joint to the body is often on a part
		-- deeper in rather than on the one that was placed
		for _, object in ipairs(mine) do
			if object:IsA("BasePart") then
				local mesh = object:FindFirstChildOfClass("SpecialMesh");
				local hang, firstSide;

				-- the joint may live on the limb, on the piece or anywhere else,
				-- so it is looked up from the part itself
				for _, joint in ipairs(object:GetJoints()) do
					if joint:IsA("Weld") or joint:IsA("Motor6D") then
						local far = (joint.Part0 == object) and joint.Part1 or joint.Part0;

						if far and not ours[far] then
							hang, firstSide = joint, joint.Part0 == object;
							break;
						end;
					end;
				end;

				l.transforms[object] = {
					kind = "part", cframe = object.CFrame, size = object.Size,
					mesh = mesh, meshScale = mesh and mesh.Scale or nil,
					joint = hang, first = firstSide,
					c0 = hang and hang.C0 or CFrame.new(), c1 = hang and hang.C1 or CFrame.new(),
				};
			elseif object:IsA("Attachment") then
				l.transforms[object] = { kind = "attachment", cframe = object.CFrame };
			end;
		end;
	end;

	local function applyCosmeticTransforms(l, t)
		if l.group ~= "cosmetic" then return end;

		local offset = Vector3.new(tonumber(t.x) or 0, tonumber(t.y) or 0, tonumber(t.z) or 0);
		local scale = math.clamp(tonumber(t.scale) or 1, 0.25, 2.5);

		for object, base in pairs(l.transforms or {}) do
			if object.Parent then
				pcall(function()
					if base.kind == "attachment" then
						object.CFrame = movedFrame(base.cframe, offset, scale);
						return;
					end;

					object.Size = base.size * scale;
					if base.mesh and base.mesh.Parent and base.meshScale then base.mesh.Scale = base.meshScale * scale end;

					local joint = base.joint;

					if joint and joint.Parent then
						-- only the body side of the joint moves, so the piece
						-- travels and the character stays put
						if base.first then
							joint.C1 = movedFrame(base.c1, offset, scale);
						else
							joint.C0 = movedFrame(base.c0, offset, scale);
						end;
					end;
				end);
			end;
		end;
	end;

	-- One record per piece the sliders or a colour can reach, holding what it
	-- started as, so the sliders scale from the original instead of compounding.
	local function recordOf(d)
		if d:IsA("ParticleEmitter") then
			return { d, rate = d.Rate, bright = d.Brightness, size = d.Size, speed = d.Speed,
				spin = d.RotSpeed, life = d.Lifetime, color = d.Color };
		elseif d:IsA("Beam") then
			return { d, color = d.Color, bright = d.Brightness };
		elseif d:IsA("Trail") then
			return { d, color = d.Color, life = d.Lifetime, bright = d.Brightness };
		elseif d:IsA("Light") then
			return { d, color = d.Color, bright = d.Brightness };
		elseif d:IsA("Fire") then
			return { d, color = d.Color, color2 = d.SecondaryColor };
		elseif d:IsA("Smoke") then
			return { d, color = d.Color };
		elseif d:IsA("Sparkles") then
			return { d, color = d.SparkleColor };
		elseif d:IsA("Highlight") then
			return { d, color = d.FillColor, color2 = d.OutlineColor };
		elseif (d:IsA("BasePart") or d:IsA("Decal")) and d.Transparency < 1 then
			return { d, transparency = d.Transparency, color = d:IsA("Decal") and d.Color3 or d.Color,
				texture = d:IsA("MeshPart") and d.TextureID or nil };
		end;
	end;

	-- Colour only. A piece is left exactly as the effect keeps it until a
	-- colour is chosen; what it wears at that moment is what comes back when
	-- the colour is taken off, so an effect that repaints itself (RNS Ring
	-- takes the torso's colour) is not reset to how it was built.
	local function paintOne(r, color)
		local d = r[1];

		if not color then
			if not r.tinted then return end;
			r.tinted = false;
			if d:IsA("ParticleEmitter") or d:IsA("Beam") or d:IsA("Trail") or d:IsA("Light") or d:IsA("Smoke") then
				d.Color = r.color;
			elseif d:IsA("Decal") then d.Color3 = r.color;
			elseif d:IsA("BasePart") then
				d.Color = r.color;
				if r.texture then d.TextureID = r.texture end;
			elseif d:IsA("Fire") then d.Color, d.SecondaryColor = r.color, r.color2;
			elseif d:IsA("Sparkles") then d.SparkleColor = r.color;
			elseif d:IsA("Highlight") then d.FillColor, d.OutlineColor = r.color, r.color2;
			end;
			return;
		end;

		if not r.tinted then
			r.tinted = true;
			if d:IsA("ParticleEmitter") or d:IsA("Beam") or d:IsA("Trail") or d:IsA("Light") or d:IsA("Smoke") then
				r.color = d.Color;
			elseif d:IsA("Decal") then r.color = d.Color3;
			elseif d:IsA("BasePart") then
				r.color = d.Color;
				if d:IsA("MeshPart") then r.texture = d.TextureID end;
			elseif d:IsA("Fire") then r.color, r.color2 = d.Color, d.SecondaryColor;
			elseif d:IsA("Sparkles") then r.color = d.SparkleColor;
			elseif d:IsA("Highlight") then r.color, r.color2 = d.FillColor, d.OutlineColor;
			end;
		end;

		local flat = color.Keypoints[1].Value;
		if d:IsA("ParticleEmitter") or d:IsA("Beam") or d:IsA("Trail") then
			if d.Color ~= color then d.Color = color end;
		elseif d:IsA("Decal") then
			if d.Color3 ~= flat then d.Color3 = flat end;
		elseif d:IsA("BasePart") then
			if d.Color ~= flat then d.Color = flat end;
			-- a texture would hide the tint, so a recoloured mesh goes plain
			if r.texture and d.TextureID ~= "" then d.TextureID = "" end;
		elseif d:IsA("Fire") then
			if d.Color ~= flat then d.Color, d.SecondaryColor = flat, flat end;
		elseif d:IsA("Sparkles") then
			if d.SparkleColor ~= flat then d.SparkleColor = flat end;
		elseif d:IsA("Highlight") then
			if d.FillColor ~= flat then d.FillColor, d.OutlineColor = flat, flat end;
		elseif d:IsA("Light") or d:IsA("Smoke") then
			if d.Color ~= flat then d.Color = flat end;
		end;
	end;

	-- someone else's piece wears their colour, never ours
	local function tuneOf(l)
		local t = tuning[l.group] or {};
		if l.guest then return {}, l.tint end;
		return t, t.color;
	end;

	local function tuneOne(r, t, color)
		local d = r[1];
		if not d.Parent then return end;
		local glow, rate, amount, size, speed, life = t.glow or 1, t.rate or 1, t.amount or 1, t.size or 1, t.speed or 1, t.life or 1;
		local opacity = t.opacity or 1;
		pcall(function()
			if d:IsA("ParticleEmitter") then
				d.Rate = r.rate * rate * amount;
				d.Brightness = r.bright * glow;
				d.Size = scaled(r.size, size);
				local s = math.clamp(speed, 0.05, 5);
				d.Speed = NumberRange.new(r.speed.Min * s, r.speed.Max * s);
				d.RotSpeed = NumberRange.new(r.spin.Min * s, r.spin.Max * s);
				d.Lifetime = NumberRange.new(math.max(0.05, r.life.Min * life / s), math.max(0.06, r.life.Max * life / s));
			elseif d:IsA("Trail") then
				d.Lifetime = math.max(0.05, r.life * life);
				d.Brightness = r.bright * glow;
			elseif d:IsA("Beam") or d:IsA("Light") then
				d.Brightness = r.bright * glow;
			elseif d:IsA("BasePart") or d:IsA("Decal") then
				d.Transparency = 1 - (1 - r.transparency) * opacity;
			end;
			paintOne(r, color);
		end);
	end;

	local function applyTune(l)
		local t, color = tuneOf(l);
		for _, r in ipairs(l.tune or {}) do tuneOne(r, t, color) end;
		applyCosmeticTransforms(l, t);
	end;

	-- the effects' own scripts repaint some pieces every so often; a chosen
	-- colour is put back over theirs, and nothing else is touched
	local function holdTint(l)
		local list = l.tune;
		if not list then return end;
		local _, color = tuneOf(l);
		if #list > 200 then
			for i = #list, 1, -1 do
				if not list[i][1].Parent then table.remove(list, i) end;
			end;
		end;
		if not color then return end;
		for _, r in ipairs(list) do
			if r[1].Parent then pcall(paintOne, r, color) end;
		end;
	end;

	-- what the effect is made of now, and whatever its own scripts add to it
	-- later: those pieces take the sliders and the colour as well
	local guardTextureNode;
	local function remember(l, roots)
		local list = {};
		l.tune = list;
		local function take(d)
			local r = recordOf(d);
			if not l.guest and l.group == "trail" and FX.TrailMoving == false and r then
				if d:IsA("ParticleEmitter") or d:IsA("Trail") or d:IsA("Beam") or d:IsA("Light")
					or d:IsA("Fire") or d:IsA("Smoke") or d:IsA("Sparkles") then
					r.motionSaved, r.motionHidden = d.Enabled, true;
					d.Enabled = false;
				elseif (d:IsA("BasePart") or d:IsA("Decal")) and r.transparency then d.Transparency = 1 end;
			end;
			if r then list[#list + 1] = r end;
			if guardTextureNode then guardTextureNode(d) end;
			return r;
		end;
		function l.watch(root)
			take(root);
			for _, d in ipairs(root:GetDescendants()) do take(d) end;
			l.conns[#l.conns + 1] = root.DescendantAdded:Connect(function(d)
				local r = take(d);
				if r and l.alive then
					local t, color = tuneOf(l);
					tuneOne(r, t, color);
				end;
			end);
		end;
		for _, r in ipairs(roots) do l.watch(r) end;
	end;

	--------------------------------------------------------------- ports --
	-- the effects' own scripts, ported from the decompiled originals
	local PORTS = {};
	-- The effects' own scripts, ported from the decompiled originals. Each one
	-- gets ctx: char, parent (what script.Parent was), limb(name), conn(c),
	-- undo(fn), alive(), made(inst). The logic and numbers are the game's.

	-- Echo: every four seconds a glass bubble swells off the torso and fades
	PORTS["Echo/DistortionThing"] = function(ctx)
		local Torso = ctx.limb("Torso")
		local holder = ctx.live.roots.Torso
		local mesh = holder and holder:WaitForChild("EchoBubbleMesh", 5)
		if not (Torso and mesh) then return end
		local folder = workspace:FindFirstChild(ctx.player.Name .. "_distortion") or Instance.new("Folder")
		folder.Name = ctx.player.Name .. "_distortion"
		folder.Parent = workspace
		ctx.made(folder)
		local acc = 5
		ctx.conn(RunService.RenderStepped:Connect(function(dt)
			acc = acc + dt
			if acc < 4 then return end
			acc = 0
			if not Torso or Torso.Parent == nil then return end
			local bubble = mesh:Clone()
			bubble.CFrame = Torso.CFrame
			bubble.Anchored, bubble.CanCollide, bubble.CanTouch, bubble.CanQuery = false, false, false, false
			local weld = bubble:FindFirstChild("Weld")
			if weld then weld.Part0, weld.Part1 = Torso, bubble end
			bubble.Massless = true
			bubble.Parent = folder
			bubble.Material = Enum.Material.Glass
			bubble.Size = Vector3.new(6, 6, 6)
			bubble.Transparency = 1
			local hl = Instance.new("Highlight")
			hl.Enabled = false
			hl.Parent = bubble
			game:GetService("Debris"):AddItem(bubble, 11)
			TweenService:Create(bubble, TweenInfo.new(3, Enum.EasingStyle.Sine, Enum.EasingDirection.In), {
				Transparency = 6, Size = Vector3.new(7, 7, 7),
			}):Play()
			task.delay(2, function()
				if bubble.Parent then
					TweenService:Create(bubble, TweenInfo.new(8, Enum.EasingStyle.Sine, Enum.EasingDirection.Out), {
						Transparency = 1, Size = Vector3.new(8, 8, 8),
					}):Play()
				end
			end)
		end))
	end

	-- RNS Ring: the particles take the torso's colour
	PORTS["RNS_Ring/TorsoRecolor"] = function(ctx)
		local holder = ctx.live.roots.HumanoidRootPart
		local main = holder and holder:WaitForChild("Main", 5)
		if not main then return end
		local colours = ctx.char:FindFirstChild("Body Colors") or ctx.char:FindFirstChildOfClass("BodyColors")
		local torso = ctx.limb("Torso")
		local c = (colours and colours.TorsoColor3) or (torso and torso.Color) or Color3.new(1, 1, 1)
		for _, d in ipairs(main:GetDescendants()) do
			if d:IsA("ParticleEmitter") then d.Color = ColorSequence.new(c) end
		end
	end

	-- Voidbroken: the limbs go, leaving the aura in their place
	local function hideLimbs(ctx, dropAccessories)
		for _, p in ipairs(bodyParts(ctx.char)) do
			if p.Name ~= "Head" then
				local was = p.Transparency
				p.Transparency = 1
				ctx.undo(function() if p.Parent then p.Transparency = was end end)
			end
		end
		if dropAccessories then
			-- the original destroys them; hidden instead so taking it off gives them back
			for _, acc in ipairs(ctx.char:GetChildren()) do
				if acc:IsA("Accessory") then
					for _, d in ipairs(acc:GetDescendants()) do
						if d:IsA("BasePart") or d:IsA("Decal") then
							local was = d.Transparency
							d.Transparency = 1
							ctx.undo(function() if d.Parent then d.Transparency = was end end)
						end
					end
				end
			end
		end
	end
	PORTS["Voidbroken/Body"] = function(ctx) hideLimbs(ctx, false) end
	PORTS["VoidbrokenFull/Body"] = function(ctx) hideLimbs(ctx, true) end

	-- Mart Orbit: five rings turning at their own rates
	PORTS["MartOrbit/MartOrbitHandler"] = function(ctx)
		local p = ctx.parent
		local spin = { ["1"] = 1.2, ["2"] = 1.8, ["3"] = 1.6, ["4"] = 1.9, ["5"] = 1.3 }
		local rings = {}
		for name, rate in pairs(spin) do
			local a = p:FindFirstChild(name)
			if a then rings[a] = { rate, a.CFrame } end
		end
		local t = Vector3.zero
		ctx.conn(RunService.RenderStepped:Connect(function(dt)
			t = t + Vector3.new(math.pi, math.pi, math.pi) * dt
			for a, v in pairs(rings) do
				a.CFrame = v[2] * CFrame.Angles(t.X / 1e19, t.Y / v[1], 0)
			end
		end))
	end

	-- Sparkly Duet: two sparkles tumbling around each other
	PORTS["SparklyDuet/SparklyDuetHandler"] = function(ctx)
		local p = ctx.parent
		local a = p:FindFirstChild("1") and p["1"]:FindFirstChild("1Number")
		local b = p:FindFirstChild("2") and p["2"]:FindFirstChild("2Number")
		if not (a and b) then return end
		local t = Vector3.zero
		ctx.conn(RunService.RenderStepped:Connect(function(dt)
			t = t + Vector3.new(math.pi, math.pi, math.pi) * dt
			local turn = CFrame.Angles(t.X / 4, t.Y / 2, 0)
			a.CFrame = a.CFrame * turn
			b.CFrame = b.CFrame * turn
		end))
	end

	-- Guardian and Blooming trails: the path only lays while running, thicker
	-- the faster you go
	local function pathTrail(first, second)
		return function(ctx)
			local root = ctx.char:WaitForChild("HumanoidRootPart", 5)
			local hum = ctx.char:WaitForChild("Humanoid", 5)
			local holder = ctx.live.roots.HumanoidRootPart
			local path = holder and holder:WaitForChild("Main", 5)
			path = path and path:WaitForChild("Path", 5)
			local a = path and path:WaitForChild(first, 5)
			local b = path and path:WaitForChild(second, 5)
			if not (root and hum and a and b) then return end
			local rate = a.Rate
			local conn
			conn = ctx.conn(RunService.RenderStepped:Connect(function()
				if hum:GetState() == Enum.HumanoidStateType.Dead or not (a.Parent and b.Parent) then
					conn:Disconnect()
					return
				end
				local running = hum:GetState() == Enum.HumanoidStateType.Running
				a.Enabled, b.Enabled = running, running
				local r = math.min((root.AssemblyLinearVelocity * Vector3.new(1, 0, 1)).Magnitude * 2, rate)
				r = r <= 3 and 0 or r
				a.Rate, b.Rate = r, r
			end))
		end
	end
	PORTS["GuardianTrail/GuardianTrailScript"] = pathTrail("Blue", "Red")
	PORTS["BloomingBlossom/BloomingBlossomScript"] = pathTrail("Green", "Purple")

	-- Ooey Gooey: the goo trail breathes in and out
	local function breathe(ctx)
		local tr = ctx.parent
		local t = 0
		ctx.conn(RunService.RenderStepped:Connect(function(dt)
			t = t + dt
			tr.Lifetime = (math.sin(t * math.pi) + 1) / 2 / 2 + 1
		end))
	end
	PORTS["OoeyGooey/Origin"] = breathe
	PORTS["OoeyGooey/AnimateOoeyGooey"] = breathe

	-- Evade's cosmetic scripts, ported from the decompiled originals. The ones
	-- that play an animation get the game's own animation first; Roblox only
	-- serves it inside Evade, so anywhere else the model turns on its joints
	-- instead of standing still.

	local function playOrSpin(ctx, animName, spinRate, randomStart)
		local model = ctx.parent
		local controller = model:FindFirstChildOfClass("AnimationController")
		local id = ctx.anims[animName]
		if controller and id then
			local animator = controller:FindFirstChildOfClass("Animator") or controller
			local anim = Instance.new("Animation")
			anim.AnimationId = id
			local ok, track = pcall(function() return animator:LoadAnimation(anim) end)
			if ok and track then
				track:Play(0)
				local t0 = os.clock()
				repeat task.wait(0.1) until track.Length > 0 or os.clock() - t0 > 3 or not ctx.alive()
				if track.Length > 0 then
					if randomStart then track.TimePosition = Random.new(tick()):NextNumber(0, track.Length) end
					ctx.undo(function() pcall(function() track:Stop(0) end) end)
					return
				end
				pcall(function() track:Stop(0) end)
			end
		end
		if not spinRate then return end
		local joints = {}
		for _, j in ipairs(model:GetDescendants()) do
			if j:IsA("Motor6D") then joints[#joints + 1] = { j, j.C0 } end
		end
		local t = randomStart and math.random() * 10 or 0
		ctx.conn(RunService.RenderStepped:Connect(function(dt)
			t = t + dt
			for _, v in ipairs(joints) do v[1].C0 = v[2] * CFrame.Angles(0, t * spinRate, 0) end
		end))
	end

	-- circling rings of stars, beams, cats and arrows around the root
	PORTS["spins/Script"] = function(ctx) playOrSpin(ctx, "Animation", 1.4, true) end
	-- Silvery and Federation crowns
	PORTS["Model/Script"] = function(ctx)
		task.wait()
		playOrSpin(ctx, "Voidstar", 0.8, false)
	end
	PORTS["NeonSign/LocalScript"] = function(ctx) playOrSpin(ctx, "Animation", nil, false) end

	local RAINBOW = {
		Color3.fromRGB(255, 52, 52), Color3.fromRGB(216, 140, 63), Color3.fromRGB(239, 235, 95),
		Color3.fromRGB(137, 216, 102), Color3.fromRGB(105, 177, 216), Color3.fromRGB(112, 98, 216),
	}
	local function cycleOutline(ctx, hl)
		local info = TweenInfo.new(1, Enum.EasingStyle.Linear, Enum.EasingDirection.Out)
		while ctx.alive() and hl.Parent and hl.Parent.Parent do
			for _, c in ipairs(RAINBOW) do
				if not ctx.alive() then return end
				TweenService:Create(hl, info, { OutlineColor = c }):Play()
				task.wait(0.5)
			end
		end
	end

	-- Glow: the whole body outlined, running through the rainbow
	PORTS["Glow/LocalScript"] = function(ctx)
		task.wait(1)
		local hl = ctx.parent
		hl.Adornee = ctx.char
		cycleOutline(ctx, hl)
	end
	-- Glow Solid: the same outline, one colour
	PORTS["GlowSolid/LocalScript"] = function(ctx)
		task.wait(1)
		ctx.parent.Adornee = ctx.char
	end
	-- Grunt: its own model outlined in the rainbow
	PORTS["Grunt/LocalScript"] = function(ctx) cycleOutline(ctx, ctx.parent) end

	--------------------------------------------------------------- equip --
	local live, wanted, busy = {}, {}, {};
	local current = nil;

	local function unequip(id, store)
		store = store or live;
		local l = store[id];
		if not l then return end;
		store[id] = nil;
		l.alive = false;
		for _, c in ipairs(l.conns) do pcall(function() c:Disconnect() end) end;
		for i = #l.undo, 1, -1 do pcall(l.undo[i]) end;
		for _, inst in ipairs(l.made) do pcall(function() inst:Destroy() end) end;
	end;

	local function resolveAt(l, at)
		if at == "" then return l.char end;
		local node = nil;
		for seg in string.gmatch(at, "[^%.]+") do
			if node == nil then node = l.roots[seg] else node = node:FindFirstChild(seg) end;
			if not node then return nil end;
		end;
		return node;
	end;

	local function runScripts(item, l, owner)
		for _, s in ipairs(l.scripts or {}) do
			local holder = s.at:match("([^%.]+)$") or "";
			local port = PORTS[item.key .. "/" .. s.n] or PORTS[holder .. "/" .. s.n];
			local parent = resolveAt(l, s.at);
			if port and parent then
				local ctx = {
					char = l.char, player = owner or LocalPlayer, parent = parent, live = l, anims = s.anims or {},
					limb = function(n) return (limb(l.char, n)) end,
					conn = function(c)
						if not l.alive or not ALIVE then pcall(function() c:Disconnect() end); return c end;
						l.conns[#l.conns + 1] = c; return c
					end,
					undo = function(fn)
						if not l.alive or not ALIVE then pcall(fn); return end;
						l.undo[#l.undo + 1] = fn
					end,
					alive = function() return l.alive and ALIVE end,
					made = function(inst)
						if not l.alive or not ALIVE then pcall(function() inst:Destroy() end); return inst end;
						l.made[#l.made + 1] = inst; if l.watch then l.watch(inst) end; return inst
					end,
				};
				task.spawn(function()
					if not l.alive or not ALIVE then return end;
					local ok, err = pcall(port, ctx);
					if not ok then recordError("game fx " .. item.key .. "/" .. s.n .. ": " .. tostring(err)) end;
				end);
			end;
		end;
	end;

	-- A texture that never arrives draws every particle as a see-through
	-- square (a few moderated ones: the gem auras, the sharks, some trails).
	-- The engine fetches it once the effect exists; when that fails the effect
	-- becomes a square. Hide failed textures in both existing and later effects.
	local ContentProvider = game:GetService("ContentProvider");
	local deadTextures, waitingTextures, textureWatches = {}, {}, {};
	local HIDDEN = NumberSequence.new(1);
	local function hideEffect(d)
		pcall(function() d.Transparency = HIDDEN; d.Enabled = false end);
	end;
	function guardTextureNode(d)
		if not (d:IsA("ParticleEmitter") or d:IsA("Beam") or d:IsA("Trail")) or d.Texture == "" then return end;
		local tex = d.Texture;
		local ok, status = pcall(ContentProvider.GetAssetFetchStatus, ContentProvider, tex);
		if deadTextures[tex] or (ok and (status == Enum.AssetFetchStatus.Failure or status == Enum.AssetFetchStatus.TimedOut)) then
			deadTextures[tex] = true;
			hideEffect(d);
		elseif ok and status ~= Enum.AssetFetchStatus.Success then
			local queue = waitingTextures[tex];
			if not queue then
				queue = setmetatable({}, { __mode = "k" });
				waitingTextures[tex] = queue;
				local signalOk, signal = pcall(ContentProvider.GetAssetFetchStatusChangedSignal, ContentProvider, tex);
				if not signalOk then waitingTextures[tex] = nil; return end;
				local watch;
				watch = signal:Connect(function(now)
					if now == Enum.AssetFetchStatus.Success then
						watch:Disconnect();
						waitingTextures[tex] = nil;
					elseif now == Enum.AssetFetchStatus.Failure or now == Enum.AssetFetchStatus.TimedOut then
						watch:Disconnect();
						waitingTextures[tex] = nil;
						deadTextures[tex] = true;
						for e in pairs(queue) do hideEffect(e) end;
					end;
				end);
				textureWatches[#textureWatches + 1] = watch;
			end;
			queue[d] = true;
		end;
	end;
	FX.ProtectTexture = guardTextureNode;
	onUnload("fx textures", function()
		for _, watch in ipairs(textureWatches) do watch:Disconnect() end;
		table.clear(textureWatches);
	end);

	local function equip(id, item, char, group, store, owner, valid)
		local trees, scripts = item.trees, item.scripts;
		if item.mode == "rig" then
			local r15 = char:FindFirstChild("UpperTorso") ~= nil;
			local v = r15 and (item.r15 or item.r6) or (item.r6 or item.r15);
			trees, scripts = {}, v and v.scripts or {};
			for i, node in ipairs(v and v.limbs or {}) do trees[i] = node end;
			if item.aura then trees[#trees + 1] = item.aura end;
		end;
		local ctx = { map = {}, refs = {}, char = char, limbKids = {} };
		local roots = {};
		for _, node in ipairs(trees) do
			local r = build(node, ctx);
			if r then roots[#roots + 1] = r end;
		end;
		-- building takes a moment; check the body is still the one we built for.
		-- a guest has their own body and their own wish list, so the local
		-- wearer/wanted test only applies to our own pieces.
		local stale = store and not char.Parent or (not store and (char ~= wearer() or wanted[id] ~= group));
		if stale or not ALIVE or (valid and not valid()) then
			for _, r in ipairs(roots) do pcall(function() r:Destroy() end) end;
			for _, k in ipairs(ctx.limbKids) do pcall(function() k[1]:Destroy() end) end;
			return;
		end;
		local l = { item = item, char = char, made = {}, conns = {}, undo = {}, roots = {}, worn = {}, transforms = {}, alive = true, scripts = scripts, group = group,
			guest = store ~= nil };
		local prefix = item.kind == "Trail" and "Trail_" or "Aura_";
		local placed, worn = {}, {};

		for _, root in ipairs(roots) do
			if item.mode == "parts" and root:IsA("BasePart") then
				local templateName = root.Name;
				local body, off = limb(char, templateName);
				if not body then body, off = limb(char, "HumanoidRootPart") end;
				if body then
					local shift = body.CFrame * off * root.CFrame:Inverse();
					for _, p in ipairs(partsUnder(root)) do p.CFrame = shift * p.CFrame end;
					-- only a carrier; the game hides it as well
					root.Transparency = 1;
					root.Name = prefix .. templateName;
					l.roots[templateName] = root;
					placed[#placed + 1] = { root, body, off };
				else
					root:Destroy();
				end;
			elseif item.mode == "rig" and root:IsA("BasePart") then
				-- a RELICS aura: welded to the mount at the mount's first attachment
				local mount = limb(char, "HumanoidRootPart");
				if mount then
					root.Name = "Aura";
					local anchor = Instance.new("Attachment");
					anchor.Name = "AuraMount";
					anchor.Parent = root;
					local first = mount:FindFirstChildOfClass("Attachment");
					local c0 = first and first.CFrame or CFrame.new();
					for _, p in ipairs(partsUnder(root)) do
						p.CFrame = mount.CFrame * c0 * root.CFrame:Inverse() * p.CFrame;
					end;
					root.Transparency = 1;
					placed[#placed + 1] = { root, mount, c0, true };
				else
					root:Destroy();
				end;
			elseif item.mode == "attach" and root:IsA("Attachment") then
				local body, off = limb(char, "Torso");
				if body then
					root.CFrame = off * root.CFrame;
					root.Name = item.kind == "Trail" and "Trail" or "AuraAttachment";
					placed[#placed + 1] = { root, body };
				else
					root:Destroy();
				end;
			elseif item.mode == "trail" and root:IsA("Trail") then
				local body, off = limb(char, "Torso");
				if body then
					local w = tonumber(item.width) or 1;
					local a0, a1 = Instance.new("Attachment"), Instance.new("Attachment");
					a0.Name, a1.Name = "LeftTrail", "RightTrail";
					a0.CFrame, a1.CFrame = off * CFrame.new(-w, 0, 0), off * CFrame.new(w, 0, 0);
					a0.Parent, a1.Parent = body, body;
					root.Attachment0, root.Attachment1 = a0, a1;
					l.made[#l.made + 1] = a0;
					l.made[#l.made + 1] = a1;
					placed[#placed + 1] = { root, body };
				else
					root:Destroy();
				end;
			else
				root:Destroy();
			end;
		end;

		-- template limb contents move into the real limbs: loose parts keep
		-- their place relative to the limb, and an attachment the limb already
		-- has by that name hands the new one its position
		for _, k in ipairs(ctx.limbKids) do
			local child, target, cf = k[1], k[2], k[3];
			if cf then
				local shift = target.CFrame * cf:Inverse();
				for _, p in ipairs(partsUnder(child)) do p.CFrame = shift * p.CFrame end;
			end;
			if child:IsA("Attachment") then
				local same = target:FindFirstChild(child.Name);
				if same and same:IsA("Attachment") then child.CFrame = same.CFrame end;
			end;
			l.roots[target.Name] = target;
		end;

		-- references go in once everything sits where it will be worn, so
		-- weld constraints take the right offsets
		for _, r in ipairs(ctx.refs) do
			local target = ctx.map[r[3]];
			if target then pcall(function() r[1][r[2]] = target end) end;
		end;

		for _, k in ipairs(ctx.limbKids) do
			k[1].Parent = k[2];
			l.made[#l.made + 1] = k[1];
			worn[#worn + 1] = k[1];
		end;

		for _, p in ipairs(placed) do
			local root, body, off = p[1], p[2], p[3];
			root.Parent = body;
			if off then
				-- Part0 is the limb and Part1 the piece, both ways round: the
				-- same placement, but the offset sliders then move the piece
				-- instead of dragging the body with it
				local weld = Instance.new("Weld");
				weld.Name = "Weld";
				weld.Part0, weld.Part1 = body, root;
				weld.C0, weld.C1 = off, CFrame.new();
				weld.Parent = root;
			end;
			l.made[#l.made + 1] = root;
			worn[#worn + 1] = root;
		end;

		l.worn = worn;
		captureCosmeticTransforms(l);
		remember(l, worn);
		(store or live)[id] = l;
		applyTune(l);
		runScripts(item, l, owner);
	end;

	local refreshHooks = {};
	local function changed()
		for _, fn in ipairs(refreshHooks) do pcall(fn) end;
	end;

	local function apply(id)
		local entry, char, group = FX.ById[id], current, wanted[id];
		if not (entry and char and group) or live[id] or busy[id] then return end;
		busy[id] = true;
		changed();
		task.spawn(function()
			local ok, err = pcall(function()
				local data = loadGame(entry.g);
				local item = data and data[id];
				if item and ALIVE and wanted[id] == group and current == char then equip(id, item, char, group) end;
			end);
			if not ok then recordError("game fx " .. id .. ": " .. tostring(err)) end;
			busy[id] = nil;
			changed();
		end);
	end;

	-- group is "aura" or "trail": which sliders reach it
	function FX.Set(id, group)
		if not FX.ById[id] then return end;
		if wanted[id] == group then
			if group and not live[id] then apply(id) end;
			return;
		end;
		unequip(id);
		wanted[id] = group;
		if group then apply(id) else changed() end;
	end;

	-- make one group wear exactly this list
	function FX.SetGroup(group, ids)
		local keep = {};
		for _, id in ipairs(ids or {}) do if FX.ById[id] then keep[id] = true end end;
		for id, g in pairs(wanted) do
			if g == group and not keep[id] then FX.Set(id, nil) end;
		end;
		for id in pairs(keep) do FX.Set(id, group) end;
	end;

	-- ------------------------------------------------------------- guests --
	-- Other people running the script. Their pieces are built on their own
	-- body and kept in tables of their own, so taking something off yourself
	-- never takes it off them.
	local guests = {};

	local function bodyOf(player)
		local char = player.Character;
		local rigs = workspace:FindFirstChild("Rigs");
		local rig = rigs and rigs:FindFirstChild(player.Name);

		if char and char.Parent and shown(char) and drawn(char) then return char end;
		if rig and rig:IsA("Model") and shown(rig) then return rig end;
		if char and char.Parent and shown(char) then return char end;

		return nil;
	end;

	local function guestStrip(g)
		for id in pairs(g.worn) do unequip(id, g.worn) end;
	end;

	function FX.Undress(player)
		local g = guests[player];
		if not g then return end;
		g.want = {};
		g.char = nil;
		guestStrip(g);
		guests[player] = nil;
	end;

	function FX.Guests() return guests end;

	-- list: { { id = "Cosmetic/...", group = "cosmetic" }, ... }; tint: the
	-- colour each group is worn in, { aura = ColorSequence, ... }, or nil
	function FX.Dress(player, list, tint)
		if not player or player == LocalPlayer then return end;

		local g = guests[player];

		if not g then
			g = { worn = {}, busy = {}, want = {} };
			guests[player] = g;
		end;

		local want = {};

		for _, entry in ipairs(list or {}) do
			local id = (type(entry) == "table") and entry.id or entry;

			if FX.ById[id] then want[id] = (type(entry) == "table" and entry.group) or "aura" end;
		end;

		g.want = want;
		g.tint = tint;
	end;

	local function trailMotion(l, moving, always)
		l.motionMoving = moving;
		for _, r in ipairs(l.tune or {}) do
			local d = r[1];
			if d.Parent then
				if d:IsA("ParticleEmitter") or d:IsA("Trail") or d:IsA("Beam") or d:IsA("Light")
					or d:IsA("Fire") or d:IsA("Smoke") or d:IsA("Sparkles") then
					if not moving then
						if not r.motionHidden then r.motionSaved = d.Enabled; r.motionHidden = true end;
						if d.Enabled then d.Enabled = false end;
					elseif always then
						r.motionHidden = false;
						if not d.Enabled then d.Enabled = true end;
					elseif r.motionHidden then
						r.motionHidden = false; d.Enabled = r.motionSaved ~= false;
					end;
				elseif (d:IsA("BasePart") or d:IsA("Decal")) and r.transparency then
					local opacity = l.guest and 1 or ((tuning.trail or {}).opacity or 1);
					local alpha = moving and (1 - (1 - r.transparency) * opacity) or 1;
					if d.Transparency ~= alpha then d.Transparency = alpha end;
				end;
			end;
		end;
	end;

	local function serveGuest(player, g)
		local char = bodyOf(player);

		if not char then
			if next(g.worn) then guestStrip(g) end;
			g.char = nil;
			return;
		end;

		if g.char ~= char then
			guestStrip(g);
			g.char = char;
		end;

		for id, l in pairs(g.worn) do
			if g.want[id] ~= l.group then
				unequip(id, g.worn);
			else
				local want = g.tint and g.tint[l.group] or nil;
				if l.tint ~= want then l.tint = want; applyTune(l) end;
				if l.group == "trail" then
					local root = char:FindFirstChild("HumanoidRootPart");
					local hum = char:FindFirstChildOfClass("Humanoid");
					local moving = root and hum and hum.Health > 0
						and (root.AssemblyLinearVelocity * Vector3.new(1, 0, 1)).Magnitude > 1.5;
					trailMotion(l, moving == true, false);
				end;
			end;
		end;

		for id, group in pairs(g.want) do
			if not g.worn[id] and not g.busy[id] then
				g.busy[id] = true;

				task.spawn(function()
					local ok, err = pcall(function()
						local entry = FX.ById[id];
						local data = entry and loadGame(entry.g);
						local item = data and data[id];

						if item and ALIVE and guests[player] == g and g.want[id] == group and g.char == char and char.Parent then
							equip(id, item, char, group, g.worn, player, function()
								return guests[player] == g and g.want[id] == group and g.char == char and bodyOf(player) == char;
							end);
						end;
					end);

					if not ok then recordError("share " .. tostring(id) .. ": " .. tostring(err)) end;

					g.busy[id] = nil;
				end);
			end;
		end;
	end;

	task.spawn(function()
		while ALIVE do
			task.wait(0.5);

			for player, g in pairs(guests) do
				if not player.Parent then FX.Undress(player) else pcall(serveGuest, player, g) end;
			end;
		end;
	end);

	task.spawn(function()
		while ALIVE do
			task.wait(1);
			for _, l in pairs(live) do pcall(holdTint, l) end;
			for _, g in pairs(guests) do
				for _, l in pairs(g.worn) do pcall(holdTint, l) end;
			end;
		end;
	end);

	-- what this player has on, for the share function to send
	function FX.WornList()
		local out = {};

		for id, group in pairs(wanted) do
			if group then out[#out + 1] = { id = id, group = group } end;
		end;

		return out;
	end;

	function FX.SetTrailMotion(moving, always)
		FX.TrailMoving = moving;
		for _, l in pairs(live) do
			if l.group == "trail" then trailMotion(l, moving, always) end;
		end;
	end;

	function FX.Tune(group, t)
		tuning[group] = t;
		for _, l in pairs(live) do
			if l.group == group then applyTune(l) end;
		end;
	end;

	-- Every effect has a picture shot on a dummy (Unusuals and cosmetics worn,
	-- trails in motion). They come packed eight by eight on a few sheets that
	-- are fetched once, the first time a gallery with effects is opened.
	local thumbHooks, thumbState = {}, "idle";
	local function thumbKey(id)
		return (tostring(id):gsub("[^%w_%.%-]", "_"));
	end;
	function FX.OnThumbs(fn) thumbHooks[#thumbHooks + 1] = fn end;

	-- image, rect offset, rect size for a picture on the sheets, or fallback
	function FX.Art(key, fallback)
		local spot = FX.ThumbMap and FX.ThumbMap[thumbKey(key)];
		local sheet = spot and FX.ThumbSheets[spot[1]];
		if not sheet then return fallback end;
		local cell = FX.ThumbCell;
		return sheet, Vector2.new(spot[2] * cell, spot[3] * cell), Vector2.new(cell, cell);
	end;

	-- one gallery row. Nullscape ships its own shop art, which is used as is;
	-- everything else shows its booth shot.
	function FX.Row(entry)
		local shop = entry.image ~= "" and entry.image ~= "rbxassetid://0" and entry.image or nil;
		local image, rect, size = shop, nil, nil;
		if not (entry.g == "nullscape" and shop) then image, rect, size = FX.Art(entry.id, shop) end;
		return { name = entry.id, label = entry.label, image = image, rect = rect, rectsize = size };
	end;

	function FX.LoadThumbs()
		if thumbState ~= "idle" then return end;
		thumbState = "loading";
		task.spawn(function()
			local raw = Remote.body("fxatlas/index.json");
			local ok, index = pcall(function() return game:GetService("HttpService"):JSONDecode(raw) end);
			if not (ok and type(index) == "table" and type(index.map) == "table" and type(index.sheets) == "table") then
				thumbState = "idle";
				return;
			end;
			local sheets = {};
			for n, rel in ipairs(index.sheets) do
				if not ALIVE then return end;
				sheets[n] = Remote.asset(rel);
			end;
			FX.ThumbMap, FX.ThumbSheets, FX.ThumbCell = index.map, sheets, tonumber(index.cell) or 128;
			-- No PreloadAsync of the sheets here: on phone executors a preload of
			-- a custom asset can hang, it held the grid back up to 10 s, and the
			-- ContentProvider queue is shared - stickers waited behind it too.
			thumbState = "ready";
			for _, fn in ipairs(thumbHooks) do pcall(fn) end;
		end);
	end;

	function FX.Busy(id) return busy[id] == true end;
	function FX.Worn(id) return live[id] ~= nil end;
	function FX.OnChange(fn) refreshHooks[#refreshHooks + 1] = fn end;
	local packStage;

	-- follow whatever the body is drawn on: a respawn, or a game swapping the
	-- drawn rig, moves everything across
	task.spawn(function()
		while ALIVE do
			local stage = Remote.Status.stage;
			if stage ~= packStage then
				packStage = stage;
				if stage == "ready" or stage == "failed" then
					for id in pairs(wanted) do apply(id) end;
				end;
			end;
			local now = wearer();
			if now ~= current then
				for id in pairs(live) do unequip(id) end;
				current = nil;
				if now then
					task.wait(0.5);
					if ALIVE and wearer() == now then
						current = now;
						for id in pairs(wanted) do apply(id) end;
					end;
				end;
			else
				for id, l in pairs(live) do
					if not l.char.Parent then unequip(id) end;
				end;
			end;
			task.wait(0.5);
		end;
	end);

	ESP.ClearGameFX = onUnload("gamefx", function()
		for player in pairs(guests) do pcall(FX.Undress, player) end;
		table.clear(wanted);
		for id in pairs(live) do unequip(id) end;
		for _, m in pairs(meshCache) do pcall(function() m:Destroy() end) end;
		table.clear(meshCache);
	end);
end);
guard("aura", function()
	LPH_ATTRIBUTES(VM(NONE));
	-- The four built here are the procedural ones (New folder (4)/
	-- catalogue module:13675). The eight below are feature module:6022 - catalogue
	-- models whose children are named after body parts.
	local ORDER = {
		"Angelic", "Ambient", "Nimb", "Tornado", "Comet",
		"Angel", "Starlight", "Heavenly", "Ribbon", "Sakura", "Wind", "Flow", "Star",
	};

	-- feature module:6022
	local CATALOGUE = {
		Angel = "97658130917593",
		Starlight = "134645216613107",
		Heavenly = "139300897520961",
		Ribbon = "132069507632161",
		Sakura = "81755778619404",
		Wind = "80694081850877",
		Flow = "119913533725648",
		Star = "73754563740680",
	};

	-- feature module:6041 - a model built for R6 has to land on an R15 rig too
	local GROUPS = {
		{ "Head" },
		{ "Torso", "UpperTorso", "LowerTorso", "HumanoidRootPart" },
		{ "Left Arm", "LeftUpperArm", "LeftLowerArm", "LeftHand" },
		{ "Right Arm", "RightUpperArm", "RightLowerArm", "RightHand" },
		{ "Left Leg", "LeftUpperLeg", "LeftLowerLeg", "LeftFoot" },
		{ "Right Leg", "RightUpperLeg", "RightLowerLeg", "RightFoot" },
	};

	local GROUP_OF = {};

	for _, names in ipairs(GROUPS) do
		for _, name in ipairs(names) do GROUP_OF[name] = names end;
	end;

	local A = {
		On = false,
		Color = Color3.fromRGB(133, 220, 255),
		Types = {},
		Type = "Angelic",
		Target = "Self",
		Glow = 2,
		Rate = 1,
		Size = 1,
		Tint = true,
		Speed = 1, Radius = 0.55, TrailLength = 100, TrailStep = 1.5, BloomSize = 150,
		LoadErrors = {}, ReadyTypes = {},
	};

	ESP.Aura = A;

	-- What one wearer's aura is made of. Ours is the first; every shared
	-- player gets one of their own, so taking yours off leaves theirs alone.
	-- (borrowed: the catalogue auras hang their emitters straight off body
	-- parts rather than off an Attachment we own.)
	local function newBank(color)
		return { attachments = {}, borrowed = {}, particles = {}, accents = {}, color = color or A.Color };
	end;

	local mine = newBank();
	local sink = mine;
	local charConnection = nil;
	local auraGeneration = 0;
	local protectAuraTexture = ESP.GameFX and ESP.GameFX.ProtectTexture;

	local function clearBank(bank)
		bank.epoch = (bank.epoch or 0) + 1;
		for i = 1, #bank.attachments do
			if bank.attachments[i] and bank.attachments[i].Parent then
				bank.attachments[i]:Destroy();
			end;
		end;

		for i = 1, #bank.borrowed do
			if bank.borrowed[i] and bank.borrowed[i].Parent then
				pcall(function() bank.borrowed[i]:Destroy() end);
			end;
		end;

		bank.attachments, bank.borrowed, bank.particles, bank.accents = {}, {}, {}, {};
	end;

	local function clearAll()
		clearBank(mine);
		table.clear(A.ReadyTypes);
	end;

	-- Every emitter goes through here, so the three sliders apply at build time
	-- and re-apply in place. The reference hardcodes Brightness 2 and a Rate;
	-- Glow, Rate and Size scale those rather than replacing them.
	local function keep(emitter, attachment)
		emitter.Parent = attachment;
		Render.FxDepth(emitter, false);
		if protectAuraTexture then protectAuraTexture(emitter) end;

		sink.particles[#sink.particles + 1] = {
			emitter = emitter,
			rate = emitter.Rate,
			bright = emitter.Brightness,
			size = emitter.Size,
			color = emitter.Color, speed = emitter.Speed, rotation = emitter.RotSpeed,
			life = emitter.Lifetime, emission = emitter.LightEmission,
		};

		return emitter;
	end;

	local function scaleSequence(sequence, factor)
		if factor == 1 then return sequence end;

		local points = {};

		for index, key in ipairs(sequence.Keypoints) do
			points[index] = NumberSequenceKeypoint.new(key.Time, key.Value * factor, key.Envelope * factor);
		end;

		return NumberSequence.new(points);
	end;

	local guests = {};

	-- the sliders are ours, the colour belongs to whoever is wearing it
	local function tuneBank(bank)
		local colour = bank.color;
		local cfg = bank.shared and { Tint = bank.tint, Rate = 1, Glow = 2, Size = 1, Speed = 1 } or A;

		for _, record in ipairs(bank.particles) do
			local emitter = record.emitter;

			if emitter.Parent then
				Render.FxDepth(emitter, false);
				emitter.Color = cfg.Tint and ColorSequence.new(colour) or record.color;
				emitter.Rate = record.rate * cfg.Rate;
				emitter.Brightness = record.bright * cfg.Glow * 0.5;
				emitter.Size = scaleSequence(record.size, cfg.Size);
				local speed = math.clamp(cfg.Speed, 0.05, 5);
				emitter.Speed = NumberRange.new(record.speed.Min * speed, record.speed.Max * speed);
				emitter.RotSpeed = NumberRange.new(record.rotation.Min * speed, record.rotation.Max * speed);
				emitter.Lifetime = NumberRange.new(math.max(0.05, record.life.Min / speed), math.max(0.06, record.life.Max / speed));
				emitter.LightEmission = math.clamp(record.emission + (cfg.Glow * 0.5 - 1) * 0.5, 0, 1);
			end;
		end;

		-- feature module:6122 - the catalogue models also carry beams, trails
		-- and lights, and the color picker has to reach those as well
		for _, record in ipairs(bank.accents) do
			local item = record.item;
			if item.Parent then
				Render.FxDepth(item, false);
				pcall(function()
					local tint = cfg.Tint and colour or nil;
					if item:IsA("PointLight") or item:IsA("SpotLight") or item:IsA("SurfaceLight") then
						item.Color = tint or record.color;
						item.Brightness = record.brightness * cfg.Glow * 0.5;
					elseif item:IsA("Beam") or item:IsA("Trail") then
						item.Color = tint and ColorSequence.new(tint) or record.color;
					elseif item:IsA("Fire") then
						item.Color, item.SecondaryColor = tint or record.color, tint or record.color2;
					elseif item:IsA("Smoke") then
						item.Color = tint or record.color;
					elseif item:IsA("Sparkles") then
						item.SparkleColor = tint or record.color;
					elseif item:IsA("Highlight") then
						item.FillColor, item.OutlineColor = tint or record.color, tint or record.color2;
					elseif item:IsA("Decal") then
						item.Color3 = tint or record.color;
					elseif item:IsA("BasePart") then
						item.Color = tint or record.color;
						-- a texture would hide the tint, so a recoloured mesh goes plain
						if record.texture then item.TextureID = tint and "" or record.texture end;
					end;
				end);
			end;
		end;
	end;

	local function tune()
		mine.color = A.Color;
		tuneBank(mine);

		for _, bank in pairs(guests) do tuneBank(bank) end;

		if ESP.GameFX then
			ESP.GameFX.Tune("aura", {
				glow = A.Glow * 0.5, rate = A.Rate, size = A.Size, speed = A.Speed,
				color = A.Tint and ColorSequence.new(A.Color) or nil,
			});
		end;
	end;

	local function part(character, ...)
		for _, name in ipairs({ ... }) do
			local found = character:FindFirstChild(name);

			if found then return found end;
		end;

		return nil;
	end;

	local function anchor(host, cframe)
		local attachment = Instance.new("Attachment");

		attachment.CFrame = cframe;
		attachment.Parent = host;

		sink.attachments[#sink.attachments + 1] = attachment;

		return attachment;
	end;

	-- catalogue module:13705 - two wing sheets on the torso plus a flipbook burst
	local function createAngelic(character)
		local torso = part(character, "Torso", "UpperTorso");

		if not torso then return end;

		local left = anchor(torso, CFrame.new(-1.012, 0.5, 0.852, 0.966, 0, 0.259, 0, 1, 0, -0.259, 0, 0.966));
		local wingL = Instance.new("ParticleEmitter");
		wingL.Lifetime = NumberRange.new(1, 1);
		wingL.LockedToPart = true;
		wingL.Transparency = NumberSequence.new({
			NumberSequenceKeypoint.new(0, 0.944),
			NumberSequenceKeypoint.new(0.2, 0),
			NumberSequenceKeypoint.new(0.8, 0),
			NumberSequenceKeypoint.new(1, 1),
		});
		wingL.LightEmission = 1;
		wingL.Color = ColorSequence.new(sink.shared and Color3.new(1, 1, 1) or A.Color);
		wingL.Speed = NumberRange.new(0.05, 0.05);
		wingL.Size = NumberSequence.new(2.75, 3.5);
		wingL.Rate = 4;
		wingL.Texture = "rbxassetid://13267054240";
		wingL.EmissionDirection = Enum.NormalId.Back;
		wingL.Orientation = Enum.ParticleOrientation.VelocityPerpendicular;
		wingL.Rotation = NumberRange.new(-15, -15);
		keep(wingL, left);

		local right = anchor(torso, CFrame.new(1.167, 0.5, 0.852, 0.966, 0, -0.259, 0, 1, 0, 0.259, 0, 0.966));
		local wingR = wingL:Clone();
		wingR.EmissionDirection = Enum.NormalId.Front;
