		local wide = Instance.new("ParticleEmitter");
		wide.Lifetime = NumberRange.new(2, 2);
		wide.SpreadAngle = Vector2.new(0.001, 0.001);
		wide.LockedToPart = true;
		wide.Transparency = NumberSequence.new({
			NumberSequenceKeypoint.new(0, 1),
			NumberSequenceKeypoint.new(0.2, 0.3),
			NumberSequenceKeypoint.new(1, 1),
		});
		wide.LightEmission = 1;
		wide.Color = ColorSequence.new(sink.shared and Color3.new(1, 1, 1) or A.Color);
		wide.Squash = NumberSequence.new(0);
		wide.Speed = NumberRange.new(0.001, 0.001);
		wide.Brightness = 2;
		wide.Size = NumberSequence.new({
			NumberSequenceKeypoint.new(0, 0),
			NumberSequenceKeypoint.new(0.3, 2),
			NumberSequenceKeypoint.new(0.6, 5),
			NumberSequenceKeypoint.new(0.8, 8),
			NumberSequenceKeypoint.new(1, 12),
		});
		wide.RotSpeed = NumberRange.new(-40, 40);
		wide.Texture = "rbxassetid://7216855136";
		wide.Orientation = Enum.ParticleOrientation.VelocityPerpendicular;
		wide.Rotation = NumberRange.new(0, 360);
		keep(wide, base);
	end;

	-- catalogue module:13922 - a halo above the head, two emitters on one tilted
	-- attachment so the ring reads as having depth
	local function createNimb(character)
		local head = part(character, "Head");

		if not head then return end;

		local halo = anchor(head, CFrame.new(-0.25, 0.933, 0.259, 0.469, -0.25, -0.847, -0.117, 0.933, -0.34, 0.875, 0.259, 0.408));

		for index = 1, 2 do
			local emitter = Instance.new("ParticleEmitter");
			emitter.Lifetime = NumberRange.new(1, 1);
			emitter.SpreadAngle = Vector2.new(5, 5);
			emitter.LockedToPart = true;
			emitter.Transparency = NumberSequence.new({
				NumberSequenceKeypoint.new(0, 1),
				NumberSequenceKeypoint.new(0.2, 0),
				NumberSequenceKeypoint.new(0.8, 0),
				NumberSequenceKeypoint.new(1, 1),
			});
			emitter.LightEmission = 1;
			emitter.Color = ColorSequence.new(sink.shared and Color3.new(1, 1, 1) or A.Color);
			emitter.Speed = NumberRange.new(0.001, 0.001);
			emitter.Brightness = 2;
			emitter.Size = (index == 1) and NumberSequence.new(2.5, 3) or NumberSequence.new(2, 3);
			emitter.RotSpeed = NumberRange.new(-400, 400);
			emitter.Rate = 7;
			emitter.Texture = "rbxassetid://8819682608";
			emitter.Orientation = Enum.ParticleOrientation.VelocityPerpendicular;
			emitter.Rotation = NumberRange.new(0, 360);
			keep(emitter, halo);
		end;
	end;

	-- catalogue module:13995 - one slow spinning funnel at the feet
	local function createTornado(character)
		local hrp = part(character, "HumanoidRootPart");

		if not hrp then return end;

		local base = anchor(hrp, CFrame.new(0, -3, 0));

		local funnel = Instance.new("ParticleEmitter");
		funnel.LightInfluence = 1;
		funnel.LockedToPart = true;
		funnel.LightEmission = 1;
		funnel.Color = ColorSequence.new(sink.shared and Color3.new(1, 1, 1) or A.Color);
		funnel.Speed = NumberRange.new(0.01, 0.01);
		funnel.Size = NumberSequence.new(6, 10);
		funnel.RotSpeed = NumberRange.new(360, 360);
		funnel.Rate = 1;
		funnel.Texture = "rbxassetid://8553497052";
		funnel.Orientation = Enum.ParticleOrientation.VelocityPerpendicular;
		keep(funnel, base);
	end;

	-- --------------------------------------------------- catalogue auras ----
	-- feature module:6111 - fetched once and kept, because GetObjects is a web
	-- round trip and a respawn rebuilds every aura.
	local loaded = {};
	local loading = {};

	local function fetchAura(name)
		if loaded[name] ~= nil then return loaded[name] or nil end;
		if loading[name] then
			local deadline = os.clock() + 13;
			repeat task.wait(0.03) until not loading[name] or not ALIVE or os.clock() >= deadline;
			return loaded[name];
		end;

		local id = CATALOGUE[name];

		if not id then return nil end;

		loading[name] = true;
		local ok, objects = Remote.objects(function() return game:GetObjects("rbxassetid://" .. id) end);
		loading[name] = nil;
		local source = (ok and type(objects) == "table") and objects[1] or nil;

		if type(objects) == "table" then for index = 2, #objects do pcall(function() objects[index]:Destroy() end) end end;
		if not ALIVE then if source then source:Destroy() end; return nil end;
		loaded[name] = source;
		if source then A.LoadErrors[name] = nil else A.LoadErrors[name] = "Asset unavailable: " .. id end;

		return source;
	end;

	-- feature module:6076 - a part the model names, or any part of the same
	-- limb group, so an R6 aura still lands on an R15 body
	local function slotFor(character, name)
		local direct = character:FindFirstChild(name, true);

		if direct and direct:IsA("BasePart") then return direct end;

		for _, alias in ipairs(GROUP_OF[name] or {}) do
			local found = character:FindFirstChild(alias, true);

			if found and found:IsA("BasePart") then return found end;
		end;

		return nil;
	end;

	local function createCatalogue(name)
		return function(character, generation, bank)
			-- fetching yields, and nothing else may build into this bank while
			-- we wait, so hand the pen back until the asset is here
			bank = bank or sink;
			local epoch = bank.epoch or 0;
			sink = mine;

			local source = fetchAura(name);
			local ours = bank == mine;

			if not source or not ALIVE or not character.Parent then return end;
			if ours and (not A.On or generation ~= auraGeneration or LocalPlayer.Character ~= character) then return end;
			if not ours and (not bank.active or bank.epoch ~= epoch or bank.char ~= character) then return end;

			local held = sink;
			sink = bank;

			local clone = source:Clone();
			for _, item in ipairs(clone:GetDescendants()) do
				if item:IsA("LuaSourceContainer") then item:Destroy() end;
			end;

			for _, group in ipairs(clone:GetChildren()) do
				local target = slotFor(character, group.Name) or part(character, "UpperTorso", "Torso", "HumanoidRootPart");

				if target then
					for _, child in ipairs(group:GetChildren()) do
						child.Parent = target;

						sink.borrowed[#sink.borrowed + 1] = child;

						local nodes = child:GetDescendants(); nodes[#nodes + 1] = child;
						for _, item in ipairs(nodes) do
							if item:IsA("ParticleEmitter") then keep(item, item.Parent);
							elseif item:IsA("Light") or item:IsA("Beam") or item:IsA("Trail") then
								if protectAuraTexture and (item:IsA("Beam") or item:IsA("Trail")) then protectAuraTexture(item) end;
								sink.accents[#sink.accents + 1] = { item = item, color = item.Color,
									brightness = item:IsA("Light") and item.Brightness or 1 };
							elseif item:IsA("Fire") then
								sink.accents[#sink.accents + 1] = { item = item, color = item.Color, color2 = item.SecondaryColor };
							elseif item:IsA("Smoke") then
								sink.accents[#sink.accents + 1] = { item = item, color = item.Color };
							elseif item:IsA("Sparkles") then
								sink.accents[#sink.accents + 1] = { item = item, color = item.SparkleColor };
							elseif item:IsA("Highlight") then
								sink.accents[#sink.accents + 1] = { item = item, color = item.FillColor, color2 = item.OutlineColor };
							elseif item:IsA("Decal") and item.Transparency < 1 then
								sink.accents[#sink.accents + 1] = { item = item, color = item.Color3 };
							elseif item:IsA("BasePart") and item.Transparency < 1 then
								sink.accents[#sink.accents + 1] = { item = item, color = item.Color,
									texture = item:IsA("MeshPart") and item.TextureID or nil };
							end;
						end;
					end;
				end;
			end;

			clone:Destroy();
			sink = held;
		end;
	end;

	-- Three curved, fading bloom trails from the reference renderer, pooled
	-- instead of creating and destroying hundreds of objects every frame.
	local cometHost = Render.gui("comet aura", -7);
	local cometSprites, cometTexture = {}, nil;
	local cometClock, cometFade = 0, 0;
	local cometPath, cometLoading, cometRetryAt = Remote.file("particles/comet_bloom.png"), false, 0;
	local function prepareComet()
		if not ALIVE or cometTexture or cometLoading or os.clock() < cometRetryAt then return end;
		cometLoading = true;
		task.defer(function()
			local ok, url = pcall(Remote.id, cometPath);
			cometLoading = false;
			if not ALIVE then return end;
			if ok and url then cometTexture = url else cometRetryAt = os.clock() + 1 end;
		end);
	end;
	A.CometSprites = cometSprites;
	local function hideComet()
		for _, sprite in ipairs(cometSprites) do sprite.Visible = false end;
	end;
	SaladUI:AddSignal(RunService.RenderStepped:Connect(function(dt)
		if not ALIVE then return end;
		if not (A.On and A.Types.Comet) and cometFade <= 0 then return end;
		local character = LocalPlayer.Character;
		local root = character and (character:FindFirstChild("UpperTorso") or character:FindFirstChild("Torso") or character:FindFirstChild("HumanoidRootPart"));
		local camera = Render.camera();
		local active = A.On and A.Types.Comet and root and root:IsA("BasePart") and camera;
		cometFade = math.clamp(cometFade + (active and dt or -dt) / 0.35, 0, 1);
		if not root or not camera or cometFade <= 0 then hideComet(); return end;
		cometClock += dt;
		if cometClock < 1 / 30 then return end;
		cometClock %= 1 / 30;
		if not ESP.Visibility.Part(camera, root, character) then hideComet(); return end;
		if not cometTexture then
			cometTexture = Remote.cachedId(cometPath);
			if not cometTexture then prepareComet(); hideComet(); return end;
		end;
		local count = math.clamp(math.floor(A.TrailLength), 20, 300);
		local distance = math.max(1.5, (camera.CFrame.Position - root.Position).Magnitude);
		local time = DateTime.now().UnixTimestampMillis;
		local baseSize = math.clamp(A.BloomSize * A.Size * camera.ViewportSize.Y / 720 / distance, 1, 160);
		local index = 0;
		for i = 0, count - 1 do
			local angle = 0.1 * (time - i * 1.5 * 300 / count * A.TrailStep) / (30 / A.Speed);
			local s, c = math.sin(angle) * A.Radius, math.cos(angle) * A.Radius;
			local progress = i / count;
			local diameter = math.max(1, baseSize * (1 - progress) ^ 1.1);
			local alpha = math.clamp(cometFade * (1 - progress * progress) * 0.4 * A.Glow * 0.5, 0, 0.95);
			for _, offset in ipairs({ Vector3.new(s, c, -c), Vector3.new(-s, s, -c), Vector3.new(-s, -s, c) }) do
				index += 1;
				local sprite = cometSprites[index];
				if not sprite then
					sprite = Instance.new("ImageLabel");
					sprite.Name = "VisualsCometBloom";
					sprite.BackgroundTransparency, sprite.BorderSizePixel = 1, 0;
					sprite.AnchorPoint, sprite.Image = Vector2.new(0.5, 0.5), cometTexture;
					sprite.Parent = cometHost;
					cometSprites[index] = sprite;
				end;
				local at, visible = camera:WorldToViewportPoint(root.Position + offset);
				sprite.Visible = visible and at.Z > 0 and alpha > 0.005;
				if sprite.Visible then
					sprite.Position, sprite.Size = UDim2.fromOffset(at.X, at.Y), UDim2.fromOffset(diameter, diameter);
					sprite.ImageColor3, sprite.ImageTransparency = A.Color, 1 - alpha;
					sprite.Rotation = (time / 5 + i * 5) % 180;
				end;
			end;
		end;
		for i = #cometSprites, index + 1, -1 do cometSprites[i]:Destroy(); cometSprites[i] = nil end;
	end));
	local BUILDERS = {
		Angelic = createAngelic,
		Ambient = createAmbient,
		Nimb = createNimb,
		Tornado = createTornado,
		-- drawn by its own render loop further down
		Comet = function() end,
	};

	for name in pairs(CATALOGUE) do BUILDERS[name] = createCatalogue(name) end;

	local function refreshAuras()
		if A.On and A.Types.Comet then prepareComet() end;
		auraGeneration += 1;
		local generation = auraGeneration;
		clearAll();

		if not (ALIVE and A.On) then return end;

		local character = LocalPlayer.Character;

		if not character then return end;

		task.defer(function()
		for _, name in ipairs(ORDER) do
			if A.Types[name] then
				local build = BUILDERS[name];

				if generation ~= auraGeneration or not ALIVE or not A.On or LocalPlayer.Character ~= character then return end;
				if build then
					local ok, err = pcall(build, character, generation);
					if not ok and generation == auraGeneration then A.LoadErrors[name] = tostring(err); recordError("aura " .. name .. ": " .. tostring(err)) end;
					if ok and generation == auraGeneration then A.ReadyTypes[name] = true; tune() end;
				end;
			end;
		end;

		tune();
		if Preview and Preview.ReadAura and ALIVE and generation == auraGeneration then pcall(Preview.ReadAura) end;
		end);
	end;

	local function onCharacterAdded()
		if not A.On then return end;

		task.wait(0.5);

		if ALIVE and A.On then refreshAuras() end;
	end;

	local function setEnabled(value)
		auraGeneration += 1;
		A.On = value and true or false;

		if A.On then
			if not charConnection then
				charConnection = SaladUI:AddSignal(LocalPlayer.CharacterAdded:Connect(onCharacterAdded));
			end;

			if LocalPlayer.Character then
				task.spawn(function()
					task.wait(0.2);

					if ALIVE and A.On then refreshAuras() end;
				end);
			end;
		else
			if charConnection then
				pcall(function() charConnection:Disconnect() end);

				charConnection = nil;
			end;

			clearAll();
		end;
	end;

	-- ------------------------------------------------------------ shared --
	-- Someone else running the script: their picks, their colour, built on
	-- their body and kept in a bank of their own.
	function A.Dress(player, names, colour)
		if not player or player == LocalPlayer then return end;

		local bank = guests[player];

		if not bank then bank = newBank(colour); guests[player] = bank end;

		bank.shared, bank.active = true, true;
		bank.tint = colour ~= nil;
		bank.color = colour or Color3.new(1, 1, 1);
		bank.want = names or {};
		if bank.key ~= table.concat(bank.want, ",") then
			bank.key = nil;
			bank.epoch = (bank.epoch or 0) + 1;
		end;
		tuneBank(bank);
	end;

	function A.Undress(player)
		local bank = guests[player];

		if not bank then return end;

		bank.active = false;
		clearBank(bank);
		guests[player] = nil;
	end;

	function A.Guests() return guests end;

	local function serveGuest(player, bank)
		local character = player.Character;

		if not character or not character.Parent then
			if bank.char then clearBank(bank); bank.char = nil end;
			return;
		end;

		local key = table.concat(bank.want, ",");

		if bank.char == character and bank.key == key then return end;

		clearBank(bank);
		bank.char, bank.key = character, key;

		for _, name in ipairs(bank.want) do
			if not bank.active or bank.key ~= key or player.Character ~= character then break end;
			local build = BUILDERS[name];

			-- Comet is drawn in screen space around our own body, nobody else's
			if build and name ~= "Comet" then
				sink = bank;
				pcall(build, character, auraGeneration, bank);
				sink = mine;
			end;
		end;

		tuneBank(bank);
	end;

	task.spawn(function()
		while ALIVE do
			task.wait(0.5);

			for player, bank in pairs(guests) do
				if not player.Parent then A.Undress(player) else pcall(serveGuest, player, bank) end;
			end;
		end;
	end);

	onUnload("aura guests", function()
		for player in pairs(guests) do pcall(A.Undress, player) end;
	end);

	-- the preview panel reads emitters off whatever this hands back; the
	-- emitters live on the character, so the character is the source
	ESP.AuraSource = function()
		return LocalPlayer.Character;
	end;

	local function refreshPreview()
		if Preview and Preview.ReadAura then pcall(Preview.ReadAura) end;
	end;

	----------------------------------------------------------- menu ----
	local row = Sections.Aura:AddLabel("Aura");

	row:AddToggle({
		Name = "Aura",
		Default = false,
		Flag = "aura",
		Callback = function(v) setEnabled(v); if A.WearGame then A.WearGame() end; refreshPreview() end,
	});

	local options = row:AddOption(1);
	options:AddLabel("Color"):AddColorPicker({
		Default = A.Color,
		Flag = "aura_color",
		Callback = function(v)
			A.Color = v;
			if not A.Tint and userPicked() then setFlag("aura_tint", true) end;
			tune();
			refreshPreview();
		end,
	});

	-- every aura in one picture grid: the ones built above, then Nullscape's
	-- and Evade's, worn by the game fx module
	local FX = ESP.GameFX;
	local gameIds = {};
	local ART = {
		Angelic = "rbxassetid://13267054240", Ambient = "rbxassetid://12713358087",
		Nimb = "rbxassetid://8819682608", Tornado = "rbxassetid://8553497052",
		Comet = "rbxassetid://11402221943",
	};

	local function auraRows()
		local out = {};

		for _, name in ipairs(ORDER) do
			local image, rect, size = ART[name], nil, nil;
			if FX then image, rect, size = FX.Art("builtin/aura/" .. name, ART[name]) end;
			out[#out + 1] = { name = name, label = name, image = image, rect = rect, rectsize = size,
				id = not rect and tonumber(CATALOGUE[name]) or nil };
		end;

		for _, entry in ipairs(FX and FX.Catalog or {}) do
			if entry.kind ~= "Trail" and entry.kind ~= "Cosmetic" then
				out[#out + 1] = FX.Row(entry);
			end;
		end;

		return out;
	end;

	function A.WearGame()
		if FX then FX.SetGroup("aura", A.On and gameIds or {}) end;
	end;

	local auraGrid = Visuals.Auras:AddGallery({
		Name = "Auras", Icon = "sparkles", Position = "left", Height = 440, Cell = 74, Reset = true, Smooth = true,
		Thumb = "Asset", Blank = "sparkles", Empty = "No auras", Values = auraRows(),
		Default = { "Angelic" }, Multi = true, Flag = "aura_types",
		Callback = function(v)
			local picked, game = {}, {};

			if type(v) == "table" then
				for key, value in pairs(v) do
					-- a list of names, or a name->bool map from an older config
					local name = (type(key) == "string" and value) and key or value;

					if type(name) == "string" then
						if BUILDERS[name] then picked[name] = true
						elseif FX and FX.ById[name] then game[#game + 1] = name end;
					end;
				end;
			elseif type(v) == "string" then
				picked[v] = true;
			end;

			gameIds = game;
			A.WearGame();
			A.Types = picked;
			A.Type = nil;

			for _, name in ipairs(ORDER) do
				if picked[name] then A.Type = name; break end;
			end;

			-- An empty second click is a real unequip, not a return to the
			-- first gallery item.
			if not A.Type and next(picked) then A.Type = "Angelic" end;

			refreshAuras();
			refreshPreview();
		end,
	});
	Sections.Aura:AddButton({ Name = "Unequip All", Callback = function()
		pcall(function() auraGrid:set({}) end);
	end });

	if FX then
		FX.OnThumbs(function() auraGrid:setdata(auraRows()) end);
		Visuals.Auras.Signal:Connect(function(open) if open then FX.LoadThumbs() end end);
	end;

	options:AddLabel("Custom Colors"):AddToggle({ Default = true, Flag = "aura_tint",
		Callback = function(v) A.Tint = v; tune(); refreshPreview() end });
	-- the Nullscape and Evade auras keep their own colours unless this is on;
	-- seeded now, so one worn without the menu's own aura is already tuned
	tune();

	-- Glow replaces the BloomEffect the old aura parked in Lighting. That lit
	-- the entire map; this scales the emitters' own Brightness.
	for _, setting in ipairs({
		{ "Glow", "Glow", "aura_glow", 0, 600, 200, 100 },
		{ "Rate", "Rate", "aura_rate", 10, 400, 100, 100 },
		{ "Size", "Size", "aura_size", 25, 300, 100, 100 },
		{ "Speed", "Speed", "aura_speed", 5, 500, 100, 100 },
	}) do
		local key, divisor = setting[2], setting[7];

		options:AddLabel(setting[1]):AddSlider({
			Min = setting[4], Max = setting[5], Default = setting[6],
			Rounding = 0, Size = 90, Flag = setting[3],
			Callback = function(v)
				A[key] = v / divisor;

				tune();
				refreshPreview();
			end,
		});
	end;

	ESP.ClearAura = onUnload("aura", function()
		A.On = false;
		if FX then pcall(FX.SetGroup, "aura", {}) end;
		auraGeneration += 1;

		if charConnection then
			pcall(function() charConnection:Disconnect() end);

			charConnection = nil;
		end;

		clearAll();
		hideComet();
		table.clear(cometSprites);
		for _, source in pairs(loaded) do if source then pcall(function() source:Destroy() end) end end;
		table.clear(loaded);
	end);
end);
guard("cosmetics", function()
	local FX = ESP.GameFX;
	if not FX then return end;

	local C = {
		On = true, Picked = {}, Color = Color3.fromRGB(255, 255, 255), Tint = false,
		Opacity = 1, Glow = 1, Rate = 1, Size = 1, Speed = 1,
		X = 0, Y = 0, Z = 0, TransformScale = 1,
	};
	ESP.Cosmetics = C;

	local function wear()
		FX.SetGroup("cosmetic", C.On and C.Picked or {});
	end;

	local function tune()
		FX.Tune("cosmetic", {
			opacity = C.Opacity, glow = C.Glow, rate = C.Rate, size = C.Size, speed = C.Speed,
			x = C.X, y = C.Y, z = C.Z, scale = C.TransformScale,
			color = C.Tint and ColorSequence.new(C.Color) or nil,
		});
	end;

	local function rows()
		local out = {};
		for _, entry in ipairs(FX.Catalog) do
			if entry.kind == "Cosmetic" then
				out[#out + 1] = FX.Row(entry);
			end;
		end;
		return out;
	end;

	local grid = Visuals.Cosmetics:AddGallery({
		Name = "Cosmetics", Icon = "crown", Position = "left", Height = 440, Cell = 74, Wrap = true, Reset = true, Smooth = true,
		Thumb = "Asset", Blank = "crown", Empty = "No cosmetics", Values = rows(),
		Multi = true, Flag = "cosmetic_pick",
		Callback = function(v)
			local picked = {};
			for key, value in pairs(type(v) == "table" and v or {}) do
				local name = (type(key) == "string" and value) and key or value;
				if type(name) == "string" and FX.ById[name] then picked[#picked + 1] = name end;
			end;
			C.Picked = picked;
			wear();
		end,
	});
	FX.OnThumbs(function() grid:setdata(rows()) end);
	Visuals.Cosmetics.Signal:Connect(function(open) if open then FX.LoadThumbs() end end);

	local row = Sections.Cosmetics:AddLabel("Enabled");
	row:AddToggle({ Default = true, Flag = "cosmetic", Callback = function(v) C.On = v; wear() end });
	local options = row:AddOption(1);
	options:AddLabel("Color"):AddColorPicker({ Default = C.Color, Flag = "cosmetic_color", Callback = function(v)
		C.Color = v;
		if not C.Tint and userPicked() then setFlag("cosmetic_tint", true) end;
		tune();
	end });

	options:AddLabel("Custom Colors"):AddToggle({ Default = false, Flag = "cosmetic_tint",
		Callback = function(v) C.Tint = v; tune() end });
	tune();

	for _, setting in ipairs({
		{ "Opacity", "Opacity", "cosmetic_opacity", 0, 100, 100 },
		{ "Glow", "Glow", "cosmetic_glow", 0, 300, 100 },
		{ "Particle Rate", "Rate", "cosmetic_rate", 0, 300, 100 },
		{ "Particle Size", "Size", "cosmetic_size", 25, 300, 100 },
		{ "Speed", "Speed", "cosmetic_speed", 5, 300, 100 },
	}) do
		local key = setting[2];
		options:AddLabel(setting[1]):AddSlider({
			Min = setting[4], Max = setting[5], Default = setting[6], Type = "%", Size = 100, Flag = setting[3],
			Callback = function(v) C[key] = v / 100; tune() end,
		});
	end;


	options:AddLabel("Position");
	for _, axis in ipairs({ "X", "Y", "Z" }) do
		options:AddLabel(axis):AddSlider({
			Min = -5, Max = 5, Default = 0, Rounding = 1, Size = 100,
			Flag = "cosmetic_xyz_" .. string.lower(axis),
			Callback = function(v) C[axis] = v; tune() end,
		});
	end;
	options:AddLabel("Size"):AddSlider({
		Min = 25, Max = 250, Default = 100, Type = "%", Rounding = 0, Size = 100,
		Flag = "cosmetic_xyz_size",
		Callback = function(v) C.TransformScale = v / 100; tune() end,
	});

	Sections.Cosmetics:AddButton({ Name = "Unequip All", Callback = function()
		pcall(function() grid:set({}) end);
	end });

	ESP.ClearCosmetics = onUnload("cosmetics", function()
		pcall(FX.SetGroup, "cosmetic", {});
	end);
end);
guard("motiongraph", function()
	LPH_ATTRIBUTES(VM(NONE));
	local MG = { On = false };

	ESP.MotionGraph = MG;

		local run = RunService
		local ws  = workspace
		local lp  = LocalPlayer

		local mg_on = false
		local mg_color = Color3.fromRGB(242, 242, 242)
		local mg_width = 280
		local mg_height = 72
		local mg_offset = 180
		local mg_thickness = 1
		local mg_span = 2.8
		local mg_step = 1 / 30
		local mg_accum = 0
		local mg_render_accum = 0
		local mg_smooth = 0
		local mg_history = {}
		local mg_lines = {}
		local mg_shadows = {}
		local mg_labels = {}
		local mg_current = nil
		local mg_conn = nil

		local function mg_remove(obj)
			destroyAny(obj)
		end

		local function mg_speed()
			local char = lp.Character
			local root = char and char:FindFirstChild("HumanoidRootPart")
			if not root then return 0 end
			local velocity = root.AssemblyLinearVelocity
			return Vector3.new(velocity.X, 0, velocity.Z).Magnitude
		end

		local function mg_reference()
			local char = lp.Character
			local hum = char and char:FindFirstChildOfClass("Humanoid")
			return math.max(1, hum and hum.WalkSpeed or 16)
		end

		local function mg_new_line(color, thickness, zindex, transparency)
			local line = drawNew("Line")
			line.Color = color
			line.Thickness = thickness
			line.Transparency = transparency
			line.ZIndex = zindex
			line.Visible = false
			return line
		end

		local function mg_new_text()
			local text = drawNew("Text")
			text.Center = true
			text.Outline = true
			text.Color = mg_color
			text.Size = 13
			text.ZIndex = 904
			text.Visible = false
			return text
		end

		local function mg_sync_pool(needed)
			while #mg_lines < needed do
				mg_shadows[#mg_shadows + 1] = mg_new_line(Color3.new(0, 0, 0), mg_thickness + 2, 901, 0.45)
				mg_lines[#mg_lines + 1] = mg_new_line(mg_color, mg_thickness, 902, 1)
			end
			while #mg_lines > needed do
				mg_remove(table.remove(mg_lines))
				mg_remove(table.remove(mg_shadows))
			end
		end

		local function mg_create()
			if mg_current then return end
			mg_current = mg_new_text()
			mg_current.Center = false
			for i = 1, 6 do
				mg_labels[i] = mg_new_text()
			end
		end

		local function mg_hide()
			if mg_current then mg_current.Visible = false end
			for i = 1, #mg_lines do
				mg_lines[i].Visible = false
				mg_shadows[i].Visible = false
			end
			for i = 1, #mg_labels do
				mg_labels[i].Visible = false
			end
		end

		local function mg_clear()
			if mg_conn then
				pcall(function() mg_conn:Disconnect() end)
				mg_conn = nil
			end
			mg_remove(mg_current)
			mg_current = nil
			for i = 1, #mg_lines do
				mg_remove(mg_lines[i])
				mg_remove(mg_shadows[i])
			end
			for i = 1, #mg_labels do
				mg_remove(mg_labels[i])
			end
			table.clear(mg_lines)
			table.clear(mg_shadows)
			table.clear(mg_labels)
			table.clear(mg_history)
			mg_accum = 0
			mg_render_accum = 0
		end

		local function mg_reset_history()
			table.clear(mg_history)
			local now = os.clock()
			local speed = mg_speed()
			mg_smooth = speed
			local count = math.ceil(mg_span / mg_step)
			for i = 0, count do
				mg_history[#mg_history + 1] = {
					t = now - mg_span + i * mg_step,
					v = speed
				}
			end
			mg_sync_pool(#mg_history)
		end

		local function mg_apply_style()
			if mg_current then mg_current.Color = mg_color end
			for i = 1, #mg_lines do
				mg_lines[i].Color = mg_color
				mg_lines[i].Thickness = mg_thickness
				mg_shadows[i].Thickness = mg_thickness + 2
			end
			for i = 1, #mg_labels do
				mg_labels[i].Color = mg_color
			end
		end

		local function mg_y(value, center, height, reference)
			local normalized = math.clamp(value / reference - 1, -1, 1)
			return center - normalized * height * 0.44
		end

		local function mg_render(now)
			local camera = ws.CurrentCamera
			if not mg_on or not camera or #mg_history < 2 then
				mg_hide()
				return
			end
			local viewport = camera.ViewportSize
			local width = math.min(mg_width, math.max(120, viewport.X - 48))
			local height = math.min(mg_height, math.max(36, viewport.Y - 32))
			local left = math.floor(viewport.X * 0.5 - width * 0.5)
			local center = math.clamp(math.floor(viewport.Y * 0.5 + mg_offset), height * 0.5 + 8, viewport.Y - height * 0.5 - 8)
			local reference = mg_reference()
			local start_time = now - mg_span
			local count = #mg_history
			mg_sync_pool(count)
			for i = 1, count - 1 do
				local a = mg_history[i]
				local b = mg_history[i + 1]
				local ap = math.clamp((a.t - start_time) / mg_span, 0, 1)
				local bp = math.clamp((b.t - start_time) / mg_span, 0, 1)
				local fade = math.clamp(math.min((ap + bp) * 6, (2 - ap - bp) * 5), 0, 1)
				local from = Vector2.new(left + ap * width, mg_y(a.v, center, height, reference))
				local to = Vector2.new(left + bp * width, mg_y(b.v, center, height, reference))
				local line = mg_lines[i]
				local shadow = mg_shadows[i]
				line.From, line.To = from, to
				line.Transparency = fade
				line.Visible = fade > 0.02
				shadow.From, shadow.To = from, to
				shadow.Transparency = fade * 0.42
				shadow.Visible = fade > 0.02
			end
			local last = mg_history[count]
			local lpct = math.clamp((last.t - start_time) / mg_span, 0, 1)
			local from = Vector2.new(left + lpct * width, mg_y(last.v, center, height, reference))
			local to = Vector2.new(left + width, mg_y(mg_smooth, center, height, reference))
			local tail = mg_lines[count]
			local tail_shadow = mg_shadows[count]
			tail.From, tail.To = from, to
			tail.Transparency = 0.72
			tail.Visible = true
			tail_shadow.From, tail_shadow.To = from, to
			tail_shadow.Transparency = 0.3
			tail_shadow.Visible = true
			for i = count + 1, #mg_lines do
				mg_lines[i].Visible = false
				mg_shadows[i].Visible = false
			end
			mg_current.Text = tostring(math.floor(mg_smooth + 0.5))
			mg_current.Position = Vector2.new(left + width + 5, to.Y - 7)
			mg_current.Color = mg_color
			mg_current.Visible = true
			while #mg_labels < 12 do
				mg_labels[#mg_labels + 1] = mg_new_text()
			end
			local threshold = math.max(0.8, reference * 0.08)
			local min_label_gap = 0.42
			for i = 5, count - 4 do
				local point = mg_history[i]
				if not point.checked then
					point.checked = true
					local before = point.v - mg_history[i - 4].v
					local after = mg_history[i + 4].v - point.v
					if math.abs(before) >= threshold and (before * after <= 0 or math.abs(after) < threshold * 0.35) then
						local nearby = nil
						for j = i - 1, 1, -1 do
							local previous = mg_history[j]
							if point.t - previous.t > min_label_gap then break end
							if previous.label ~= nil then
								nearby = previous
								break
							end
						end
						local score = math.abs(before) - math.abs(after)
						if not nearby then
							point.label = math.floor(point.v + 0.5)
							point.label_score = score
						elseif score > (nearby.label_score or -math.huge) then
							nearby.label = nil
							nearby.label_score = nil
							point.label = math.floor(point.v + 0.5)
							point.label_score = score
						end
					end
				end
			end
			for i = 1, #mg_labels do
				mg_labels[i].Visible = false
			end
			local placed = {}
			local label_count = 0
			for i = count, 1, -1 do
				local point = mg_history[i]
				if point.label ~= nil and label_count < #mg_labels then
					local pct = (point.t - start_time) / mg_span
					if pct > 0.04 and pct < 0.82 then
						local value = tostring(point.label)
						local x = left + pct * width
						local y = mg_y(point.v, center, height, reference) - 15
						local half_width = math.max(8, #value * 3.5 + 2)
						local blocked = false
						for j = 1, #placed do
							local other = placed[j]
							if x + half_width + 5 > other.x1 and x - half_width - 5 < other.x2 and y + 13 > other.y1 and y - 3 < other.y2 then
								blocked = true
								break
							end
						end
						if not blocked then
							label_count = label_count + 1
							local text = mg_labels[label_count]
							text.Text = value
							text.Position = Vector2.new(x, y)
							text.Color = mg_color
							text.Visible = true
							placed[#placed + 1] = {
								x1 = x - half_width,
								x2 = x + half_width,
								y1 = y - 3,
								y2 = y + 13
							}
						end
					end
				end
			end
		end

		local function mg_start()
			mg_clear()
			mg_create()
			mg_reset_history()
			mg_apply_style()
			mg_conn = run.RenderStepped:Connect(function(dt)
				if not ALIVE or not mg_on then
					mg_hide()
					return
				end
				local raw = mg_speed()
				mg_smooth = mg_smooth + (raw - mg_smooth) * (1 - math.exp(-dt * 18))
				mg_accum = mg_accum + dt
				local now = os.clock()
				if mg_accum >= mg_step then
					mg_accum = mg_accum % mg_step
					mg_history[#mg_history + 1] = { t = now, v = mg_smooth }
					local cutoff = now - mg_span
					while #mg_history > 2 and mg_history[2].t < cutoff do
						table.remove(mg_history, 1)
					end
				end
				mg_render_accum += dt
				if mg_render_accum >= 1 / 60 then
					mg_render_accum %= 1 / 60
					mg_render(now)
				end
			end)
		end

		MG.On = false
		MG.Color     = mg_color
		MG.Width     = mg_width
		MG.Height    = mg_height
		MG.Thickness = mg_thickness
		MG.OffsetY   = mg_offset

		ESP.MotionGraphSet = { set = function(k, v)
			if k == "color" then
				mg_color = v
				mg_apply_style()
			elseif k == "width" then
				mg_width = v
			elseif k == "height" then
				mg_height = v
			elseif k == "y" then
				mg_offset = v
			elseif k == "thickness" then
				mg_thickness = v
				mg_apply_style()
			end
			MG.Color, MG.Width, MG.Height, MG.OffsetY, MG.Thickness = mg_color, mg_width, mg_height, mg_offset, mg_thickness
		end }

		ESP.StartMotionGraph = function()
			mg_on = true
			MG.On = true
			mg_start()
		end

		ESP.ClearMotionGraph = function()
			mg_on = false
			MG.On = false
			mg_clear()
		end

		ESP.MotionGraphStyle = mg_apply_style

		SaladUI:AddSignal(lp.CharacterAdded:Connect(function()
			task.wait(0.4)
			if ALIVE and mg_on then mg_reset_history() end
		end))

	local row = Sections.ScreenInfo:AddLabel("Speed Graph");
	row:AddToggle({
		Default = false, Flag = "motion_graph",
		Callback = function(v)
			if v then ESP.StartMotionGraph() else ESP.ClearMotionGraph() end;
		end,
	});
	row:AddColorPicker({
		Default = MG.Color, Flag = "motion_graph_color",
		Callback = function(v) ESP.MotionGraphSet.set("color", v) end,
	});

	local options = row:AddOption(1);

	options:AddLabel("Width"):AddSlider({
		Min = 120, Max = 600, Default = 280, Rounding = 0, Size = 90,
		Flag = "motion_graph_width",
		Callback = function(v) ESP.MotionGraphSet.set("width", v) end,
	});

	options:AddLabel("Height"):AddSlider({
		Min = 30, Max = 200, Default = 72, Rounding = 0, Size = 90,
		Flag = "motion_graph_height",
		Callback = function(v) ESP.MotionGraphSet.set("height", v) end,
	});

	options:AddLabel("Offset"):AddSlider({
		Min = 40, Max = 400, Default = 180, Rounding = 0, Size = 90,
		Flag = "motion_graph_offset",
		Callback = function(v) ESP.MotionGraphSet.set("y", v) end,
	});

	options:AddLabel("Thickness"):AddSlider({
		Min = 1, Max = 5, Default = 1, Rounding = 0, Size = 90,
		Flag = "motion_graph_thickness",
		Callback = function(v) ESP.MotionGraphSet.set("thickness", v) end,
	});
end);
guard("backtrack", function()
	local BT = {
		On = false,
		Style = "ForceField",
		Delay = 120,
		Color = Color3.fromRGB(120, 200, 255),
		Transparency = 45,
		Target = "Other",
		Outline = Color3.fromRGB(255, 255, 255),
		OutlineTransparency = 10,
		OutlineOn = true,
	};

	BT.ChamsMaterial = BT.Style;
	BT.ChamsOutline = BT.Outline;
	BT.ChamsOutlineTransparency = BT.OutlineTransparency;

	ESP.Backtrack = BT;

	local order = ESP.MaterialOrder;

	if type(order) ~= "table" or #order == 0 then
		order = {};

		for name in pairs(ESP.MaterialStyles or {}) do order[#order + 1] = name end;

		table.sort(order);
	end;

	local row = Sections.Chams:AddLabel("Backtrack");
	row:AddToggle({
		Default = false, Flag = "backtrack",
		Callback = function(v)
			BT.On = v;

			if not v and ESP.ClearBacktrackChams then ESP.ClearBacktrackChams() end;
		end,
	});
	row:AddColorPicker({ Default = BT.Color, Flag = "backtrack_color", Callback = function(v) BT.Color = v end });

	local options = row:AddOption(1);

	options:AddLabel("Style"):AddDropdown({
		Default = "ForceField",
		Values = order,
		Flag = "backtrack_style",
		Callback = function(v)
			BT.Style, BT.ChamsMaterial = v, v;

			if ESP.ClearBacktrackChams then ESP.ClearBacktrackChams() end;
		end,
	});

	options:AddLabel("Target"):AddDropdown({
		Default = "Other", Values = { "Self", "Other", "All" }, Flag = "backtrack_target",
		Callback = function(v)
			BT.Target = v;

			if ESP.ClearBacktrackChams then ESP.ClearBacktrackChams() end;
		end,
	});

	options:AddLabel("Through Walls"):AddToggle({
		Default = true, Flag = "backtrack_walls",
		Callback = function(v) BT.Walls = v end,
	});

	options:AddLabel("Delay"):AddSlider({
		Min = 20, Max = 800, Default = 120, Type = "ms", Rounding = 0, Size = 90,
		Flag = "backtrack_delay",
		Callback = function(v) BT.Delay = v end,
	});

	options:AddLabel("Fade"):AddSlider({
		Min = 0, Max = 90, Default = 45, Type = "%", Size = 90,
		Flag = "backtrack_fade",
		Callback = function(v) BT.Transparency = v end,
	});

	local outlineRow = options:AddLabel("Outline");
	outlineRow:AddToggle({
		Default = true, Flag = "backtrack_outline_on",
		Callback = function(v) BT.OutlineOn = v end,
	});
	outlineRow:AddColorPicker({
		Default = BT.Outline, Flag = "backtrack_outline",
		Callback = function(v) BT.Outline, BT.ChamsOutline = v, v end,
	});

	options:AddLabel("Outline Opacity"):AddSlider({
		Min = 0, Max = 100, Default = 90, Type = "%", Size = 90,
		Flag = "backtrack_outline_opacity",
		Callback = function(v)
			BT.OutlineTransparency = 100 - v;
			BT.ChamsOutlineTransparency = BT.OutlineTransparency;
		end,
	});
end);
guard("backtrack_chams", function()
	LPH_ATTRIBUTES(VM(NONE));
	local BT = ESP.Backtrack;
	local states, timer = {}, 0;
	local SAMPLE_STEP = 1 / 30;

	local present = {};

	local function clear(player)
		local state = states[player];
		if not state then return end;
		for _, connection in ipairs(state.connections or {}) do connection:Disconnect() end;
		if state.model then state.model:Destroy() end;
		states[player] = nil;
	end;

	local function clearAll()
		for player in pairs(states) do clear(player) end;
	end;

	local function selected(player)
		return BT.On and (BT.Target == "All" or (BT.Target == "Self" and player == LocalPlayer) or (BT.Target == "Other" and player ~= LocalPlayer));
	end;

	local function linkParts(source, clone, links)
		if source:IsA("BasePart") and clone:IsA("BasePart")
			and source.Name ~= "HumanoidRootPart" and source.Transparency < 1 then
			links[#links + 1] = { source = source, clone = clone, baseTransparency = source.Transparency };
		end;
		local ordinals = {};
		for _, child in ipairs(source:GetChildren()) do
			local key = child.ClassName .. "\0" .. child.Name;
			ordinals[key] = (ordinals[key] or 0) + 1;
			local ordinal = ordinals[key];
			for _, candidate in ipairs(clone:GetChildren()) do
				if candidate.ClassName == child.ClassName and candidate.Name == child.Name then
					ordinal -= 1;
					if ordinal == 0 then linkParts(child, candidate, links); break end;
				end;
			end;
		end;
	end;

	local function buildModel(state)
		local now = os.clock();
		if state.model and state.model.Parent then
			if not state.dirty or now < state.rebuildAt then return true end;
			state.model:Destroy();
			state.model, state.links, state.highlight = nil, nil, nil;
		elseif now < state.rebuildAt then
			return false;
		end;
		local character = state.character;
		local archivable = character.Archivable;
		pcall(function() character.Archivable = true end);
		local ok, model = pcall(character.Clone, character);
		pcall(function() character.Archivable = archivable end);
		if not ok or not model then state.rebuildAt = now + 0.5; return false end;

		for _, descendant in ipairs(model:GetDescendants()) do
			if descendant:IsA("BasePart") then
				descendant.Anchored = true;
				descendant.CanCollide = false;
				descendant.CanTouch = false;
				descendant.CanQuery = false;
				descendant.CastShadow = false;
				descendant.Transparency = 1;
			-- values go too: MM2's pet script follows every model in workspace
			-- holding a "Pet" value and threw each frame on a ghost with no player
			elseif descendant:IsA("Humanoid") or descendant:IsA("BaseScript") or descendant:IsA("Sound")
				or descendant:IsA("ValueBase")
				or descendant:IsA("Decal") or descendant:IsA("Texture") or descendant:IsA("ParticleEmitter")
				or descendant:IsA("Trail") or descendant:IsA("Beam") or descendant:IsA("Light")
				or descendant:IsA("Highlight") or descendant:IsA("BillboardGui") or descendant:IsA("SurfaceGui") then
				descendant:Destroy();
			end;
		end;

		local links = {};
		linkParts(character, model, links);

		local highlight = Instance.new("Highlight");
		highlight.Name = "BacktrackPlayerChams";
		highlight.Adornee = model;
		highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop;
		highlight.Parent = model;

		model.Name = SaladUI.RandomString();
		model:SetAttribute(TAG, INIT_GENERATION);
		model.Parent = workspace;
		state.model, state.links, state.highlight = model, links, highlight;
		state.history, state.dirty, state.rebuildAt = {}, false, 0;
		return true;
	end;

	local function ensure(player, character)
		local state = states[player];
		if state and state.character == character then return state end;
		clear(player);
		state = { character = character, history = {}, connections = {}, dirty = false, rebuildAt = 0 };
		local function accessoryChanged(child)
			if child:IsA("Accessory") or child:IsA("Hat") then
				state.dirty = true;
				state.rebuildAt = os.clock() + 0.1;
			end;
		end;
		state.connections[1] = character.ChildAdded:Connect(accessoryChanged);
		state.connections[2] = character.ChildRemoved:Connect(accessoryChanged);
		states[player] = state;
		return state;
	end;

	local function snapshot(state, root, now)
		local pose = {};
		for index, link in ipairs(state.links or {}) do
			if link.source.Parent then pose[index] = link.source.CFrame end;
		end;
		state.history[#state.history + 1] = { t = now, root = root.CFrame, pose = pose };
		local keep = math.max(1.05, BT.Delay / 1000 + 0.2);
		while #state.history > 2 and state.history[2].t < now - keep do table.remove(state.history, 1) end;
	end;

	local function delayedPose(history, target)
		if #history == 0 then return nil end;
		local before, after = history[1], history[1];
		for index = 2, #history do
			local sample = history[index];
			if sample.t >= target then
				before, after = history[index - 1], sample;
				break;
			end;
			before, after = sample, sample;
		end;
		local alpha = before == after and 0 or math.clamp((target - before.t) / math.max(after.t - before.t, 0.00001), 0, 1);
		return before, after, alpha;
	end;

	local function renderChams(state, before, after, alpha)
		local style = ESP.MaterialStyles[BT.ChamsMaterial] or ESP.MaterialStyles.ForceField;
		local userFade = math.clamp(BT.Transparency / 100, 0, 1);
		local styleFade = math.clamp(style.transparency or 0, 0, 1);
		for index, link in ipairs(state.links) do
			local first = before.pose[index];
			local second = after.pose[index] or first;
			if first and link.clone.Parent then
				link.clone.CFrame = first:Lerp(second, alpha);
				link.clone.Material = style.material or Enum.Material.ForceField;
				link.clone.Reflectance = style.reflectance or 0;
				link.clone.Color = BT.Color;
				link.clone.Transparency = 1 - (1 - link.baseTransparency) * (1 - userFade) * (1 - styleFade);
			end;
		end;
		local highlight = state.highlight;
		if highlight then
			highlight.Enabled = true;
			highlight.FillColor = BT.Color;
			highlight.FillTransparency = userFade;
			highlight.OutlineColor = BT.ChamsOutline;
			highlight.OutlineTransparency = BT.OutlineOn and math.clamp(BT.ChamsOutlineTransparency / 100, 0, 1) or 1;
			highlight.DepthMode = BT.Walls == false and Enum.HighlightDepthMode.Occluded or Enum.HighlightDepthMode.AlwaysOnTop;
		end;
	end;

	SaladUI:AddSignal(Players.PlayerRemoving:Connect(clear));
	SaladUI:AddSignal(RunService.RenderStepped:Connect(function(dt)
		if not ALIVE then return end;
		if not BT.On then
			timer = 0;
			if next(states) then clearAll() end;
			return;
		end;
		timer = timer + dt;
		local sampleNow = timer >= SAMPLE_STEP;
		if sampleNow then timer = timer % SAMPLE_STEP end;
		local now = os.clock();

		table.clear(present);

		for _, player in ipairs(Players:GetPlayers()) do
			present[player] = true;
			local character = player.Character;
			local root = character and character:FindFirstChild("HumanoidRootPart");
			if selected(player) and character and root then
				local state = ensure(player, character);
				if buildModel(state) then
					if sampleNow or #state.history == 0 then snapshot(state, root, now) end;
					local before, after, alpha = delayedPose(state.history, now - BT.Delay / 1000);
					if before then renderChams(state, before, after, alpha) end;
				end;
			elseif states[player] then
				clear(player);
			end;
		end;
		for player in pairs(states) do if not present[player] then clear(player) end end;
	end));
	ESP.ClearBacktrackChams = clearAll;
end);
guard("circles", function()
	LPH_ATTRIBUTES(VM(NONE));
	local Debris = game:GetService("Debris");
	local DEFAULT_STYLE = "Soft Ring";

	local C = {
		Jump = false, Land = false,
		Style = DEFAULT_STYLE,
		Color = Color3.fromRGB(150, 200, 255),
		Size = 4,
		Life = 0.8,
		Target = "Self",
		Bright = 100,
		Grow = 220,
		Spin = 0,
	};

	local styles = {
		["Soft Ring"] = { file = Remote.file("circles/circle.png") },
		Inscription = { file = Remote.file("circles/konchal.png") },
		["Classic Ring"] = { asset = "rbxassetid://7185003058" },
		["Double Ripple"] = { file = Remote.file("circles/ripple.png") },
		["Neon Ring"] = { file = Remote.file("circles/neonring.png") },
		["Triple Swirl"] = { file = Remote.file("circles/swirl.png") },
		["Neon Star"] = { file = Remote.file("circles/neonstar.png") },
		["Halo Ring"] = { file = Remote.file("circles/haloring.png") },
		["Cracked Ground"] = { file = Remote.file("circles/shatter.png") },
		["Rune Crown"] = { file = Remote.file("circles/img.png") },
		["Glyph Ring"] = { file = Remote.file("circles/pentos.png") },
		["Magic Circle"] = { file = Remote.file("circles/imagephotoroom.png") },
		["Blast Ring"] = { file = Remote.file("circles/boom1.png") },
		["Vortex Ring"] = { file = Remote.file("circles/omut3.png") },
		["Radial Burst"] = { file = Remote.file("circles/85362844633530.png") },
		["Mist Ring"] = { file = Remote.file("circles/134160165648626.png") },
		["Star Flash"] = { file = Remote.file("circles/17068400400.png") },
		["Arcane Sigil"] = { file = Remote.file("circles/circle4.png") },
	};

	local order = {
		"Soft Ring", "Inscription", "Classic Ring", "Double Ripple", "Neon Ring", "Triple Swirl",
		"Neon Star", "Halo Ring", "Cracked Ground", "Rune Crown", "Glyph Ring", "Magic Circle",
		"Blast Ring", "Vortex Ring", "Radial Burst", "Mist Ring", "Star Flash", "Arcane Sigil",
	};
	local aliases = {
		Circle = "Soft Ring", Konchal = "Inscription", Ring = "Classic Ring", Ripple = "Double Ripple",
		Neon = "Neon Ring", Swirl = "Triple Swirl", Star = "Neon Star", Halo = "Halo Ring",
		Shatter = "Cracked Ground", Img = "Rune Crown", Pentos = "Glyph Ring",
		["Image Photoroom"] = "Magic Circle", ["Boom 1"] = "Blast Ring", ["Omut 3"] = "Vortex Ring",
		["85362844633530"] = "Radial Burst", ["134160165648626"] = "Mist Ring",
		["17068400400"] = "Star Flash", ["Circle 4"] = "Arcane Sigil",
		Animation1 = "Orbit Rings", Animation2 = "Firework Bloom", Puff = "Smoke Bloom",
	};
	local generatedNames = { animation1 = "Orbit Rings", animation2 = "Firework Bloom", puff = "Smoke Bloom" };

	do
		for _, rel in ipairs(Remote.under("circles/")) do
			local file = string.match(rel, "([^/]+)$");
			local name, cols, rows, frames = string.match(file or "", "^(.+)_(%d+)x(%d+)_(%d+)%.png$");

			if name then
				local pretty = generatedNames[string.lower(name)] or (string.gsub(name, "^%l", string.upper));

				styles[pretty] = {
					file = Remote.file(rel),
					cols = tonumber(cols), rows = tonumber(rows), frames = tonumber(frames),
				};

				order[#order + 1] = pretty;
			end;
		end;
	end;

	local function urlFor(style)
		if style.asset then return style.asset end;
		if style.url then return style.url end;
		style.url = Remote.cachedId(style.file) or Remote.id(style.file);
		return style.url;
	end;
	local function prepareCircle(name)
		local style = styles[name] or styles[DEFAULT_STYLE];
		if style.asset or style.url or style.loading or not ALIVE then return end;
		style.loading = true;
		task.defer(function()
			if ALIVE then pcall(urlFor, style) end;
			style.loading = nil;
		end);
	end;
	local function canonicalStyle(name)
		name = aliases[name] or name;
		return styles[name] and name or DEFAULT_STYLE;
	end;
	ESP.CircleStyles = { Order = order, Styles = styles, Aliases = aliases, Default = DEFAULT_STYLE };

	do
		local G = ESP.GunChams;
		if G then
			local function makeCircle(record, style)
				local part = Instance.new("Part");
				part.Name = "VisualsGunCircle";
				part:SetAttribute(TAG, INIT_GENERATION);
				part:SetAttribute("VisualsGunAura", true);
				part.Anchored, part.CanCollide, part.CanQuery, part.CanTouch = true, false, false, false;
				part.CastShadow, part.Transparency = false, 1;
				part.Parent = workspace;
				local attach = Instance.new("Attachment"); attach.Parent = part;
				local emitter = Instance.new("ParticleEmitter");
				emitter:SetAttribute("VisualsGunAura", true);
				emitter.Rate, emitter.TimeScale = 0, 0;
				emitter.Lifetime, emitter.Speed = NumberRange.new(20), NumberRange.new(0.01);
				emitter.LightEmission, emitter.LightInfluence, emitter.LockedToPart = 1, 0, true;
				emitter.Orientation = Enum.ParticleOrientation.VelocityPerpendicular;
				emitter.EmissionDirection = Enum.NormalId.Top;
				emitter.Rotation, emitter.RotSpeed = NumberRange.new(0), NumberRange.new(0);
				emitter.Parent = attach;
				local circle = { Part = part, Emitter = emitter, Style = G.CircleStyle, Clock = 1 };
				record.Circle = circle;
				task.defer(function()
					local url = urlFor(style);
					if not ALIVE or record.Circle ~= circle or not part.Parent or not url then return end;
					emitter.Texture = url;
					local layouts = { [2] = Enum.ParticleFlipbookLayout.Grid2x2,
						[4] = Enum.ParticleFlipbookLayout.Grid4x4, [8] = Enum.ParticleFlipbookLayout.Grid8x8 };
					if style.frames and layouts[style.cols] then
						emitter.FlipbookLayout = layouts[style.cols];
						emitter.FlipbookMode = Enum.ParticleFlipbookMode.OneShot;
						emitter.FlipbookStartRandom = false;
						emitter.FlipbookFramerate = NumberRange.new(0);
					end;
					emitter:Emit(1);
					circle.Ready = true;
				end);
				return circle;
			end;
			ESP.StaticGunCircle = function(record, object, gun, dt)
				local style = styles[G.CircleStyle] or styles[DEFAULT_STYLE];
				local circle = record.Circle;
				if not circle or circle.Style ~= G.CircleStyle or not circle.Part.Parent then
					if circle then circle.Part:Destroy() end;
					circle = makeCircle(record, style);
				end;
				circle.Clock += dt;
				if circle.Clock >= 0.1 or circle.Ground ~= G.CircleGround then
					circle.Clock, circle.Ground = 0, G.CircleGround;
					local position, normal = gun.Position - Vector3.new(0, gun.Size.Y * 0.5, 0), Vector3.yAxis;
					if G.CircleGround then
						local params = RaycastParams.new();
						params.FilterType = Enum.RaycastFilterType.Exclude;
						local ignore = { object, circle.Part };
						for _, player in ipairs(Players:GetPlayers()) do if player.Character then ignore[#ignore + 1] = player.Character end end;
						params.FilterDescendantsInstances, params.IgnoreWater = ignore, true;
						local hit = workspace:Raycast(gun.Position, Vector3.new(0, -64, 0), params);
						if hit then position, normal = hit.Position, hit.Normal end;
					end;
					circle.Position, circle.Normal = position, normal;
				end;
				local up = circle.Normal or Vector3.yAxis;
				local reference = math.abs(up.Y) > 0.98 and Vector3.xAxis or Vector3.yAxis;
				local right = up:Cross(reference).Unit;
				circle.Part.CFrame = CFrame.fromMatrix(circle.Position + up * G.CircleHeight, right, up, right:Cross(up).Unit);
				local emitter = circle.Emitter;
				local settings = { G.CircleColor, G.CircleSize, G.CircleOpacity, G.CircleGlow, G.CircleRotation, G.CircleThroughWalls };
				local changed = not circle.Settings;
				for i, value in ipairs(settings) do if not circle.Settings or value ~= circle.Settings[i] then changed = true end end;
				if changed then
					circle.Settings = settings;
					emitter.Color, emitter.Size = ColorSequence.new(G.CircleColor), NumberSequence.new(G.CircleSize);
					emitter.Transparency, emitter.Brightness = NumberSequence.new(1 - G.CircleOpacity), G.CircleGlow;
					emitter.Rotation = NumberRange.new(G.CircleRotation);
					Render.FxDepth(emitter, G.CircleThroughWalls);
					if circle.Ready then emitter:Clear(); emitter:Emit(1) end;
				end;
			end;
			local row = Sections.Guns:AddLabel("Gun Circle");
			row:AddToggle({ Default = false, Flag = "gun_circle", Callback = function(v)
				G.Circle = v;
				if v then prepareCircle(G.CircleStyle) end;
				G.SetTracking();
			end });
			row:AddColorPicker({ Default = G.CircleColor, Flag = "gun_circle_color", Callback = function(v) G.CircleColor = v end });
			local options = row:AddOption(1);
			options:AddLabel("Style"):AddDropdown({ Default = DEFAULT_STYLE, Values = order, Flag = "gun_circle_style",
				Callback = function(v)
					G.CircleStyle = canonicalStyle(v);
					if G.Circle then prepareCircle(G.CircleStyle) end;
				end });
			for _, setting in ipairs({
				{ "Size", "CircleSize", "size", 5, 300, 40, 10 },
				{ "Opacity", "CircleOpacity", "opacity", 0, 100, 100, 100 },
				{ "Glow", "CircleGlow", "glow", 0, 600, 200, 100 },
				{ "Height", "CircleHeight", "height", 0, 200, 6, 100 },
				{ "Rotation", "CircleRotation", "rotation", 0, 360, 0, 1 },
			}) do
				local key, divisor = setting[2], setting[7];
				options:AddLabel(setting[1]):AddSlider({ Min = setting[4], Max = setting[5], Default = setting[6],
					Rounding = 0, Flag = "gun_circle_" .. setting[3], Callback = function(v) G[key] = v / divisor end });
			end;
			options:AddLabel("On Ground"):AddToggle({ Default = true, Flag = "gun_circle_ground", Callback = function(v) G.CircleGround = v end });
		end;
	end;

	local FLIPBOOK = {
		[2] = Enum.ParticleFlipbookLayout.Grid2x2,
		[4] = Enum.ParticleFlipbookLayout.Grid4x4,
		[8] = Enum.ParticleFlipbookLayout.Grid8x8,
	};

	local function groundAt(char, root)
		local params = RaycastParams.new();
		params.FilterType = Enum.RaycastFilterType.Exclude;
		params.FilterDescendantsInstances = { char };
		params.IgnoreWater = true;

		local sum, normal, hits = Vector3.zero, Vector3.zero, 0;

		for _, name in ipairs({ "LeftFoot", "RightFoot", "Left Leg", "Right Leg" }) do
			local foot = char:FindFirstChild(name);

			if foot and foot:IsA("BasePart") then
				local hit = workspace:Raycast(foot.Position + Vector3.new(0, 0.35, 0), Vector3.new(0, -7, 0), params);

				if hit then
					sum = sum + hit.Position;
					normal = normal + hit.Normal;
					hits = hits + 1;
				end;
			end;
		end;

		if hits > 0 then return sum / hits, normal.Unit end;

		local hit = workspace:Raycast(root.Position + Vector3.new(0, 1, 0), Vector3.new(0, -16, 0), params);

		if hit then return hit.Position, hit.Normal end;

		return root.Position - Vector3.new(0, 3, 0), Vector3.yAxis;
	end;

	local circleParts, circleVisuals = {}, {};
	local function clearActiveCircles()
		local stale = {};
		for part in pairs(circleParts) do stale[#stale + 1] = part end;
		for _, part in ipairs(stale) do if part.Parent then part:Destroy() end end;
		table.clear(circleParts);
		table.clear(circleVisuals);
	end;
	local function spawnCircle(position, normal)
		if not ALIVE then return end;
		local style = styles[C.Style] or styles[DEFAULT_STYLE];
		local url = urlFor(style);
		if not ALIVE then return end;
		local count, oldest, oldestAt = 0, nil, math.huge;
		for part, visual in pairs(circleVisuals) do
			count += 1;
			if visual.born < oldestAt then oldest, oldestAt = part, visual.born end;
		end;
		if count >= 24 and oldest then oldest:Destroy() end;

		local up = normal or Vector3.yAxis;
		local reference = (math.abs(up.Y) > 0.98) and Vector3.xAxis or Vector3.yAxis;
		local right = up:Cross(reference).Unit;
		local front = right:Cross(up).Unit;

		local part = Instance.new("Part");
		part.Name = "VisualsJumpCircle";
		part:SetAttribute(TAG, INIT_GENERATION);
		part.Anchored = true;
		part.CanCollide = false;
		part.CanQuery = false;
		part.CanTouch = false;
		part.CastShadow = false;
		part.Transparency = 1;
		part.Size = Vector3.new(0.2, 0.2, 0.2);
		part.CFrame = CFrame.fromMatrix(position + up * 0.08, right, up, front);
		circleParts[part] = true;
		part.Destroying:Once(function() circleParts[part] = nil; circleVisuals[part] = nil end);
		part.Parent = workspace;

		local surface = Instance.new("SurfaceGui");
		surface.Face, surface.Adornee = Enum.NormalId.Top, part;
		surface.AlwaysOnTop, surface.LightInfluence = false, 0;
		surface.CanvasSize, surface.Parent = Vector2.new(512, 512), part;
		local ring = Instance.new("Frame");
		ring.BackgroundTransparency, ring.Size = 1, UDim2.fromScale(0.94, 0.94);
		ring.Position, ring.BorderSizePixel, ring.Parent = UDim2.fromScale(0.03, 0.03), 0, surface;
		local corner = Instance.new("UICorner"); corner.CornerRadius, corner.Parent = UDim.new(1, 0), ring;
		local stroke = Instance.new("UIStroke");
		stroke.ApplyStrokeMode, stroke.Thickness = Enum.ApplyStrokeMode.Border, 7;
		stroke.Color, stroke.Parent = C.Color, ring;
		circleVisuals[part] = {
			born = os.clock(), life = C.Life, size = C.Size, grow = C.Grow / 100,
			bright = math.clamp(C.Bright / 100, 0, 1), stroke = stroke,
			base = part.CFrame, spin = math.rad(C.Spin),
		};
		part.Size = Vector3.new(C.Size * 0.35, 0.025, C.Size * 0.35);
		Debris:AddItem(part, C.Life + 0.4);
		if not url then return part end;
		local ok = pcall(function()

		local attach = Instance.new("Attachment");
		attach.Parent = part;

		local opacity = math.clamp(C.Bright / 100, 0, 1);

		local emitter = Instance.new("ParticleEmitter");
		emitter.Texture = url;
		emitter.Color = ColorSequence.new(C.Color);
		emitter.LightEmission = 1;
		emitter.LightInfluence = 0;
		emitter.Rate = 0;
		emitter.Lifetime = NumberRange.new(C.Life);
		emitter.Speed = NumberRange.new(0.01);
		emitter.Drag = 0;
		emitter.Acceleration = Vector3.zero;
		emitter.VelocityInheritance = 0;
		emitter.EmissionDirection = Enum.NormalId.Top;
		emitter.Rotation = NumberRange.new(0);
		emitter.RotSpeed = NumberRange.new(C.Spin);
		emitter.ZOffset = 0;

		pcall(function() emitter.Orientation = Enum.ParticleOrientation.VelocityPerpendicular end);

		emitter.Size = NumberSequence.new({
			NumberSequenceKeypoint.new(0, C.Size * 0.35),
			NumberSequenceKeypoint.new(0.4, C.Size),
			NumberSequenceKeypoint.new(1, C.Size * C.Grow / 100),
		});

		emitter.Transparency = NumberSequence.new({
			NumberSequenceKeypoint.new(0, 1 - opacity),
			NumberSequenceKeypoint.new(0.6, 1 - opacity * 0.55),
			NumberSequenceKeypoint.new(1, 1),
		});

		if style.frames and FLIPBOOK[style.cols] then
			pcall(function()
				emitter.FlipbookLayout = FLIPBOOK[style.cols];
				emitter.FlipbookMode = Enum.ParticleFlipbookMode.OneShot;
			end);
		end;

		emitter.Parent = attach;
		emitter:Emit(1);

		surface.Enabled = false;

		end);
		if not ok then
			for _, child in ipairs(part:GetChildren()) do if child:IsA("Attachment") then child:Destroy() end end;
		end;
		return part;
	end;

	local function wants(player)
		local isSelf = player == LocalPlayer;

		return C.Target == "All" or (isSelf and C.Target == "Self") or (not isSelf and C.Target == "Other");
	end;

	local state = {};
	local function rootFor(character, human)
		local root = human.RootPart or character:FindFirstChild("HumanoidRootPart") or character.PrimaryPart;
		return root and root:IsA("BasePart") and root or nil;
	end;
	local function emitFor(record, position, normal)
		local now = os.clock();
		if record.lastCircleAt and now - record.lastCircleAt <= 0.22 and record.lastCirclePosition
			and (position - record.lastCirclePosition).Magnitude <= 5 then return false end;
		record.lastCircleAt, record.lastCirclePosition = now, position;
		task.defer(spawnCircle, position, normal);
		return true;
	end;
	local function unhook(player)
		local record = state[player];
		if not record then return end;
		state[player] = nil;
		for _, conn in ipairs(record.conns) do conn:Disconnect() end;
		for _, conn in ipairs(record.humanConns or {}) do conn:Disconnect() end;
	end;
	local function takeoff(record, fromFloor)
		local root = rootFor(record.character, record.human);
		if not root then return end;
		if fromFloor and record.jumpDetected then record.air = true; return end;
		record.jumpDetected = true;
		local now = os.clock();
		if C.Jump and wants(record.player) and now - record.lastJump > 0.18 then
			record.lastJump = now;
			local position, normal = groundAt(record.character, root);
			emitFor(record, position, normal);
		end;
		record.air = true;
	end;
	local function landed(record)
		if record.air and C.Land and wants(record.player) then
			local root = rootFor(record.character, record.human);
			if root then
				local position, normal = groundAt(record.character, root);
				emitFor(record, position, normal);
			end;
		end;
		record.air = false;
		record.jumpDetected = false;
	end;
	local function watch(player)
		local function hook(character)
			unhook(player);
			local record = { player = player, character = character, conns = {}, humanConns = {}, lastJump = -math.huge };
			state[player] = record;
			local function attach(human)
				if (record.human and record.human.Parent) or not ALIVE or state[player] ~= record or player.Character ~= character then return end;
				for _, conn in ipairs(record.humanConns) do conn:Disconnect() end;
				table.clear(record.humanConns);
				record.human = human;
				record.air = human.FloorMaterial == Enum.Material.Air;
				record.floorAir = record.air;
				record.humanConns[#record.humanConns + 1] = human.StateChanged:Connect(function(_, new)
					if not ALIVE or state[player] ~= record then return end;
					if new == Enum.HumanoidStateType.Jumping then takeoff(record)
					elseif new == Enum.HumanoidStateType.Freefall then record.air = true
					elseif new == Enum.HumanoidStateType.Landed then landed(record) end;
				end);
				record.humanConns[#record.humanConns + 1] = human.Jumping:Connect(function(active)
					if ALIVE and active and state[player] == record then takeoff(record) end;
				end);
			end;
			record.conns[#record.conns + 1] = character.DescendantAdded:Connect(function(obj)
				if obj:IsA("Humanoid") then attach(obj) end;
			end);
			record.conns[#record.conns + 1] = character.ChildRemoved:Connect(function(obj)
				if obj == record.human then
					for _, conn in ipairs(record.humanConns) do conn:Disconnect() end;
					table.clear(record.humanConns); record.human = nil;
					local human = character:FindFirstChildOfClass("Humanoid");
					if human then attach(human) end;
				end;
			end);
			task.spawn(function()
				local human = character:FindFirstChildOfClass("Humanoid") or character:WaitForChild("Humanoid", 10);
				if human and ALIVE and character.Parent and player.Parent and player.Character == character then attach(human) end;
			end);
		end;
		if player.Character then hook(player.Character) end;
		SaladUI:AddPlayerSignal(player, player.CharacterAdded:Connect(hook));
		SaladUI:AddPlayerSignal(player, player.CharacterRemoving:Connect(function() unhook(player) end));
	end;
	local poll = 0;
	SaladUI:AddSignal(RunService.RenderStepped:Connect(function(dt)
		if not ALIVE then return end;
		local now = os.clock();
		for part, visual in pairs(circleVisuals) do
			local t = (now - visual.born) / visual.life;
			if t >= 1 or not part.Parent then part:Destroy()
			else
				local diameter = visual.size * (t < 0.4 and (0.35 + t / 0.4 * 0.65) or (1 + (visual.grow - 1) * (t - 0.4) / 0.6));
				part.Size = Vector3.new(diameter, 0.025, diameter);
				part.CFrame = visual.base * CFrame.Angles(0, visual.spin * (now - visual.born), 0);
				visual.stroke.Transparency = 1 - visual.bright * (1 - t) ^ 1.4;
			end;
		end;
		if not (C.Jump or C.Land) then return end;
		poll += dt;
		if poll < 0.04 then return end;
		poll = 0;
		for player, record in pairs(state) do
			local human, character = record.human, record.character;
			if human and human.Parent and character.Parent and player.Character == character and wants(player) then
				local root = rootFor(character, human);
				if root then
					local air = human.FloorMaterial == Enum.Material.Air;
					if air and not record.floorAir and root.AssemblyLinearVelocity.Y > 1 then takeoff(record, true)
					elseif not air and record.floorAir then landed(record) end;
					record.floorAir = air;
				end;
			end;
		end;
	end));
	for _, player in ipairs(Players:GetPlayers()) do watch(player) end;
	SaladUI:AddSignal(Players.PlayerAdded:Connect(watch));
	SaladUI:AddSignal(Players.PlayerRemoving:Connect(unhook));

	ESP.Circles = C;
	ESP.SpawnCircle = spawnCircle;

	ESP.ClearCircles = onUnload("circles", function()
		C.Jump, C.Land = false, false;
		clearActiveCircles();
		for player in pairs(state) do unhook(player) end;

		table.clear(state);
	end);

	local jumpRow = Sections.Circles:AddLabel("Jump Circle");
	jumpRow:AddToggle({ Default = false, Flag = "jump_circle", Callback = function(v)
		C.Jump = v;
		if v then prepareCircle(C.Style) end;
		if not (C.Jump or C.Land) then clearActiveCircles() end;
	end });
	local options = jumpRow:AddOption(1);
	options:AddLabel("Color"):AddColorPicker({ Default = C.Color, Flag = "circle_color", Callback = function(v) C.Color = v end });

	Sections.Circles:AddLabel("Land Circle"):AddToggle({
		Default = false, Flag = "land_circle",
		Callback = function(v)
			C.Land = v;
			if v then prepareCircle(C.Style) end;
			if not (C.Jump or C.Land) then clearActiveCircles() end;
		end,
	});

	options:AddLabel("Style"):AddDropdown({
		Default = DEFAULT_STYLE,
		Values = order,
		Flag = "circle_style",
		Callback = function(v)
			local nextStyle = canonicalStyle(v);
			if C.Style ~= nextStyle then clearActiveCircles() end;
			C.Style = nextStyle;
			if C.Jump or C.Land then prepareCircle(C.Style) end;
		end,
	});

	options:AddLabel("Size"):AddSlider({
		Min = 1, Max = 30, Default = 4, Rounding = 1, Size = 100,
		Flag = "circle_size",
		Callback = function(v) C.Size = v end,
	});

	options:AddLabel("Life"):AddSlider({
		Min = 2, Max = 40, Default = 8, Rounding = 0, Size = 100,
		Flag = "circle_life",
		Callback = function(v) C.Life = v / 10 end,
	});

	options:AddLabel("Grow"):AddSlider({
		Min = 100, Max = 400, Default = 220, Type = "%", Size = 100,
		Flag = "circle_grow",
		Callback = function(v) C.Grow = v end,
	});

	options:AddLabel("Brightness"):AddSlider({
		Min = 10, Max = 100, Default = 100, Type = "%", Size = 100,
		Flag = "circle_bright",
		Callback = function(v) C.Bright = v end,
	});

	options:AddLabel("Spin"):AddSlider({
		Min = 0, Max = 180, Default = 0, Rounding = 0, Size = 100,
		Flag = "circle_spin",
		Callback = function(v) C.Spin = v end,
	});

	options:AddLabel("Target"):AddDropdown({
		Default = "Self",
		Values = { "Self", "Other", "All" },
		Flag = "circle_target",
		Callback = function(v) C.Target = v end,
	});

	Sections.Circles:AddButton({
		Name = "Test Circle",
		Callback = function()
			local char = LocalPlayer.Character;
			local root = char and char:FindFirstChild("HumanoidRootPart");

			if root then spawnCircle(groundAt(char, root)) end;
		end,
	});
end);
guard("trail", function()
	LPH_ATTRIBUTES(VM(NONE));
	local T = {
		On = false,
		Target = "Self",
		Color = Color3.fromRGB(120, 200, 255),
		Color2 = Color3.fromRGB(255, 120, 220),
		Rainbow = false,
		Tint = false,
		Style = "Bloom",
		Size = 10,
		Life = 0.9,
		Rate = 140,
		Bright = 85,
		Amount = 100,
		Spread = 100,
		Gravity = 100,
		Always = false,
		Speed = 18,
	};

	local PARTICLES = "particles/";

	local STYLES = {
		Bloom = { kind = "particle", sprite = { "p_bloom" }, size = 2.04, rate = 34, life = 1.0,
			speed = { 0.4, 1.4 }, spread = 16, rise = 1.6, drag = 3.5, spin = 20, light = 0.85 },
		Glow = { kind = "particle", sprite = { "p_glow", "p_softglow" }, size = 2.40, rate = 26, life = 1.2,
			speed = { 0.2, 1.0 }, spread = 22, rise = 2.2, drag = 4, spin = 12, light = 1 },
		Sparkle = { kind = "particle", sprite = { "p_sparkle" }, size = 1.20, rate = 46, life = 0.8,
			speed = { 1.0, 3.2 }, spread = 45, rise = -2, drag = 2.2, spin = 180, light = 0.9 },
		Stars = { kind = "particle", sprite = { "p_star", "p_starnew" }, size = 1.32, rate = 34, life = 1.1,
			speed = { 0.8, 2.4 }, spread = 38, rise = -1.5, drag = 2, spin = 140, light = 0.55 },
		Fireflies = { kind = "particle", sprite = { "p_firefly" }, size = 0.96, rate = 30, life = 1.8,
			speed = { 0.3, 1.2 }, spread = 60, rise = 1.2, drag = 5, spin = 30, light = 1 },
		Hearts = { kind = "particle", sprite = { "p_heart" }, size = 1.44, rate = 22, life = 1.3,
			speed = { 0.6, 1.8 }, spread = 30, rise = 2.4, drag = 3, spin = 60, light = 0.35 },
		Snow = { kind = "particle", sprite = { "p_snowflake" }, size = 1.20, rate = 30, life = 1.6,
			speed = { 0.3, 1.1 }, spread = 42, rise = -1.8, drag = 3.5, spin = 90, light = 0.4 },
		Lightning = { kind = "particle", sprite = { "p_lightning" }, size = 1.44, rate = 28, life = 0.6,
			speed = { 1.4, 3.6 }, spread = 30, rise = 0, drag = 1.5, spin = 220, light = 1 },
		Crowns = { kind = "particle", sprite = { "p_crown" }, size = 1.44, rate = 16, life = 1.4,
			speed = { 0.6, 1.6 }, spread = 28, rise = 2.0, drag = 3, spin = 70, light = 0.3 },

		Smolder = { kind = "particle", sprite = { "p_bloom", "p_softglow" }, size = 3.20,
			rate = 14, life = 2.6, speed = { 0.1, 0.5 }, spread = 70, rise = 1.0, drag = 6, spin = 8, light = 0.45 },
		Halo = { kind = "particle", sprite = { "p_glowboost" }, size = 2.80, rate = 12, life = 1.6,
			speed = { 0.05, 0.3 }, spread = 90, rise = 0.4, drag = 7, spin = 15, light = 1.3 },
		Starfall = { kind = "particle", sprite = { "p_star", "p_starnew", "p_sparkle" }, size = 0.84,
			rate = 60, life = 2.2, speed = { 0.2, 0.9 }, spread = 25, rise = -6, drag = 1.2, spin = 200, light = 0.8 },
		Swarm = { kind = "particle", sprite = { "p_firefly", "p_sparkle" }, size = 0.60, rate = 90,
			life = 1.1, speed = { 1.6, 4.2 }, spread = 120, rise = 0, drag = 2.5, spin = 260, light = 1 },
		Static = { kind = "particle", sprite = { "p_lightning", "p_sparkle" }, size = 0.90, rate = 75,
			life = 0.35, speed = { 2.4, 5.5 }, spread = 75, rise = 0, drag = 0.8, spin = 300, light = 1.2 },
		Frost = { kind = "particle", sprite = { "p_snowflake", "p_sparkle" }, size = 0.78, rate = 55,
			life = 2.4, speed = { 0.2, 0.8 }, spread = 80, rise = -1.0, drag = 5, spin = 60, light = 0.7 },
		Bloomburst = { kind = "particle", sprite = { "p_bloom", "p_glow", "p_glowboost" }, size = 1.10,
			rate = 100, life = 0.5, speed = { 3.0, 7.0 }, spread = 180, rise = 0, drag = 1, spin = 120, light = 1.4 },

		Ribbon = { kind = "ribbon", texture = "", light = 1 },
		Comet = { kind = "ribbon", texture = Remote.file(PARTICLES .. "p_glow.png"), local_file = true, light = 2 },
		Smoke = { kind = "ribbon", texture = "rbxasset://textures/particles/smoke_main.dds", light = 0.4 },
	};

	local order = {
		"Bloom", "Glow", "Sparkle", "Stars", "Fireflies", "Hearts", "Snow",
		"Lightning", "Crowns", "Smolder", "Halo", "Starfall", "Swarm", "Static", "Frost",
		"Bloomburst", "Ribbon", "Comet", "Smoke",
	};

	local function customAsset(path)
		return Remote.id(path) or "";
	end;

	local function textureFor(style)
		if style.sprite then
			return customAsset(Remote.file(PARTICLES .. style.sprite[math.random(1, #style.sprite)] .. ".png"));
		end;

		if not style.local_file then return style.texture end;

		return customAsset(style.texture);
	end;

	local live = {};
	local WHITE = Color3.new(1, 1, 1);

	local function clear(character)
		local entry = live[character];
		if not entry then return end;

		for _, key in ipairs({ "trail", "emitter", "a", "b" }) do
			local part = entry[key];

			if part then pcall(function() part:Destroy() end) end;
		end;

		live[character] = nil;
	end;

	local function clearAll()
		for character, entry in pairs(live) do
			if not entry.cfg or entry.cfg == T then clear(character) end;
		end;
	end;

	local function colors(cfg)
		cfg = cfg or T;

		if cfg.Rainbow then
			local hue = (os.clock() * 0.12) % 1;

			return Color3.fromHSV(hue, 0.85, 1), Color3.fromHSV((hue + 0.22) % 1, 0.85, 1);
		end;

		return cfg.Color, cfg.Color2;
	end;

	local function sequenceFor(style, cfg)
		if style.own then return ColorSequence.new(Color3.new(1, 1, 1)) end;

		local first, second = colors(cfg);

		return ColorSequence.new(first, second);
	end;

	local function sizeFor(style, cfg)
		cfg = cfg or T;
		local base = style.size * (cfg.Size / 10);

		return NumberSequence.new({
			NumberSequenceKeypoint.new(0, base * 0.35),
			NumberSequenceKeypoint.new(0.25, base),
			NumberSequenceKeypoint.new(1, base * 0.1),
		});
	end;

	local function fadeFor(cfg)
		cfg = cfg or T;
		local floor = 1 - math.clamp(cfg.Bright / 100, 0.05, 1);

		return NumberSequence.new({
			NumberSequenceKeypoint.new(0, 1),
			NumberSequenceKeypoint.new(0.12, floor),
			NumberSequenceKeypoint.new(0.55, floor + (1 - floor) * 0.35),
			NumberSequenceKeypoint.new(1, 1),
		});
	end;

	local function buildParticles(character, root, style, cfg)
		cfg = cfg or T;
		local attach = Instance.new("Attachment");
		attach.Name = SaladUI.RandomString();
		attach.Position = Vector3.new(0, -0.9, 0);
		attach.Parent = root;

		local emitter = Instance.new("ParticleEmitter");
		emitter.Name = SaladUI.RandomString();
		emitter.Texture = textureFor(style);
		emitter.LightEmission = style.light;

		emitter.LightInfluence = 0;
		emitter.Enabled = false;
		emitter.Rate = style.rate * (cfg.Rate / 100) * (cfg.Amount / 100);
		emitter.Lifetime = NumberRange.new(cfg.Life * 0.65, cfg.Life);
		emitter.Speed = NumberRange.new(style.speed[1], style.speed[2]);
		emitter.SpreadAngle = Vector2.new(style.spread, style.spread) * (cfg.Spread / 100);
		emitter.Acceleration = Vector3.new(0, style.rise * (cfg.Gravity / 100), 0);
		emitter.Drag = style.drag;
		emitter.VelocityInheritance = 0.3;
		emitter.EmissionDirection = Enum.NormalId.Back;
		emitter.Rotation = NumberRange.new(0, 360);
		emitter.RotSpeed = NumberRange.new(-style.spin, style.spin);
		emitter.Color = sequenceFor(style, cfg);
		emitter.Size = sizeFor(style, cfg);
		emitter.Transparency = fadeFor(cfg);
		emitter.Enabled = cfg.Always == true;
		emitter.Parent = attach;

		live[character] = {
			emitter = emitter, a = attach, root = root, style = style,
			swap = 0, size = cfg.Size, rate = cfg.Rate, amount = cfg.Amount, bright = cfg.Bright,
			enabled = false, life = cfg.Life, cfg = cfg,
		};
	end;

	local function buildRibbon(character, root, style, cfg)
		cfg = cfg or T;
		local a = Instance.new("Attachment");
		a.Name = SaladUI.RandomString();
		a.Position = Vector3.new(0, cfg.Size * 0.09, 0);
		a.Parent = root;

		local b = Instance.new("Attachment");
		b.Name = SaladUI.RandomString();
		b.Position = Vector3.new(0, -cfg.Size * 0.09, 0);
		b.Parent = root;

		local first, second = colors(cfg);

		local trail = Instance.new("Trail");
		trail.Name = SaladUI.RandomString();
		trail.Attachment0, trail.Attachment1 = a, b;
		trail.Lifetime = cfg.Life;
		trail.MinLength = 0.08;
		trail.FaceCamera = true;
		trail.LightEmission = style.light;
		trail.LightInfluence = 0;
		trail.Texture = textureFor(style);
		trail.TextureMode = Enum.TextureMode.Static;
		trail.TextureLength = 4;
		trail.Color = ColorSequence.new(first, second);

		trail.WidthScale = NumberSequence.new({
			NumberSequenceKeypoint.new(0, 1),
			NumberSequenceKeypoint.new(0.5, 0.62),
			NumberSequenceKeypoint.new(1, 0),
		});

		local floor = 1 - math.clamp(cfg.Bright / 100, 0.05, 1);

		trail.Transparency = NumberSequence.new({
			NumberSequenceKeypoint.new(0, floor),
			NumberSequenceKeypoint.new(0.7, floor + (1 - floor) * 0.5),
			NumberSequenceKeypoint.new(1, 1),
		});

		trail.Enabled = cfg.Always == true;
		trail.Parent = root;

		live[character] = {
			trail = trail, a = a, b = b, root = root, style = style, size = cfg.Size,
			life = cfg.Life, first = first, second = second, cfg = cfg,
		};
	end;

	local FX = ESP.GameFX;

	local guests = {};

	local function build(character)
		local root = character:FindFirstChild("HumanoidRootPart");
		if not root then return end;

		clear(character);

		local owner = Players:GetPlayerFromCharacter(character);
		local cfg = (owner and guests[owner]) or T;

		if cfg == T and T.Game and character == LocalPlayer.Character then return end;

		local style = STYLES[cfg.Style] or STYLES.Bloom;

		if style.kind == "ribbon" then
			buildRibbon(character, root, style, cfg);
		else
			buildParticles(character, root, style, cfg);
		end;
	end;

	local function wants(player)
		if not T.On then return false end;

		local isSelf = player == LocalPlayer;

		return T.Target == "All" or (isSelf and T.Target == "Self") or (not isSelf and T.Target == "Other");
	end;

	local function gameTune()
		if not FX then return end;
		local first, second = colors();
		FX.Tune("trail", {
			glow = T.Bright / 85, rate = T.Rate / 140, size = T.Size / 10, life = T.Life / 0.9,
			amount = T.Amount / 100,
			color = T.Tint and ColorSequence.new(first, second) or nil,
		});
	end;

	local function refresh()
		clearAll();
		if FX then FX.SetGroup("trail", (T.On and T.Game) and { T.Game } or {}) end;
		gameTune();

		if not T.On then return end;
		if not T.Style and not T.Game then return end;

		for _, player in ipairs(Players:GetPlayers()) do
			if wants(player) and player.Character then build(player.Character) end;
		end;
	end;

	local function moving(character, cfg)
		if cfg.Always then return true end;
		local root = character and character:FindFirstChild("HumanoidRootPart");
		local hum = character and character:FindFirstChildOfClass("Humanoid");
		if not root or not hum or hum.Health <= 0 then return false end;
		return (root.AssemblyLinearVelocity * Vector3.new(1, 0, 1)).Magnitude > 1.5
			and (hum.MoveDirection.Magnitude > 0.05 or hum.FloorMaterial == Enum.Material.Air);
	end;
	local tuneClock, tuned = 0, nil;
	SaladUI:AddSignal(RunService.RenderStepped:Connect(function(dt)
		if not SaladUI.ScreenGui.Parent then return end;

		if T.Game and T.On then
			if FX then FX.SetTrailMotion(moving(LocalPlayer.Character, T), T.Always) end;
			tuneClock += dt;
			if tuneClock > 0.12 then
				tuneClock = 0;
				local first, second = colors();
				local key = table.concat({ tostring(first), tostring(second), T.Bright, T.Rate, T.Amount, T.Size, T.Life, tostring(T.Rainbow), tostring(T.Tint) }, "|");
				if key ~= tuned then tuned = key; gameTune() end;
			end;
		end;
		if not next(live) then return end;
		local frameFirst, frameSecond = colors();
		local frameSequence = T.Rainbow and ColorSequence.new(frameFirst, frameSecond) or nil;

		for character, entry in pairs(live) do
			local cfg = entry.cfg or T;
			local ownFirst, ownSecond, ownSequence = frameFirst, frameSecond, frameSequence;
			if cfg ~= T then
				ownFirst, ownSecond = colors(cfg);
				ownSequence = cfg.Rainbow and ColorSequence.new(ownFirst, ownSecond) or nil;
			end;
			if not entry.root or not entry.root.Parent then
				clear(character);
			elseif entry.emitter then
				if not entry.emitter.Parent then
					clear(character);
				else
					local moving = moving(character, cfg);
					local style = entry.style;

					if entry.enabled ~= moving then
						entry.enabled = moving;
						entry.emitter.Enabled = moving;
					end;
					local first, second = ownFirst, ownSecond;
					if style.own then first, second = WHITE, WHITE end;
					if entry.first ~= first or entry.second ~= second then
						entry.first, entry.second = first, second;
						entry.emitter.Color = (not style.own and ownSequence) or ColorSequence.new(first, second);
					end;
					if entry.life ~= cfg.Life then
						entry.life = cfg.Life;
						entry.emitter.Lifetime = NumberRange.new(cfg.Life * 0.65, cfg.Life);
					end;

					if entry.size ~= cfg.Size then
						entry.size = cfg.Size;
						entry.emitter.Size = sizeFor(style, cfg);
					end;

					if entry.rate ~= cfg.Rate or entry.amount ~= cfg.Amount then
						entry.rate, entry.amount = cfg.Rate, cfg.Amount;
						entry.emitter.Rate = style.rate * (cfg.Rate / 100) * (cfg.Amount / 100);
					end;

					if entry.bright ~= cfg.Bright then
						entry.bright = cfg.Bright;
						entry.emitter.Transparency = fadeFor(cfg);
					end;

					if style.sprite and #style.sprite > 1 and moving then
						entry.swap = entry.swap + dt;

						if entry.swap > 0.22 then
							entry.swap = 0;
							entry.emitter.Texture = textureFor(style);
						end;
					end;
				end;
			elseif not entry.trail or not entry.trail.Parent then
				clear(character);
			else
				local active = moving(character, cfg);
				if entry.trail.Enabled ~= active then entry.trail.Enabled = active end;
				if entry.first ~= ownFirst or entry.second ~= ownSecond then
					entry.first, entry.second = ownFirst, ownSecond;
					entry.trail.Color = ownSequence or ColorSequence.new(ownFirst, ownSecond);
				end;
				if entry.life ~= cfg.Life then
					entry.life = cfg.Life;
					entry.trail.Lifetime = cfg.Life;
				end;

				if entry.size ~= cfg.Size then
					entry.size = cfg.Size;
					entry.a.Position = Vector3.new(0, cfg.Size * 0.09, 0);
					entry.b.Position = Vector3.new(0, -cfg.Size * 0.09, 0);
				end;
			end;
		end;
	end));

	local function watch(player)
		SaladUI:AddPlayerSignal(player, player.CharacterAdded:Connect(function(character)
			if not wants(player) then return end;

			task.delay(1, function()
				if ALIVE and T.On and wants(player) and player.Parent and player.Character == character and character.Parent then build(character) end;
			end);
		end));
	end;

	for _, player in ipairs(Players:GetPlayers()) do watch(player) end;
	SaladUI:AddSignal(Players.PlayerAdded:Connect(watch));

	ESP.Trail = T;

	function T.Worn()
		if not (T.On and T.Style and STYLES[T.Style] and (T.Target == "Self" or T.Target == "All")) then return nil end;
		return {
			s = T.Style, a = T.Color:ToHex(), b = T.Color2:ToHex(), r = T.Rainbow == true, z = T.Size, l = T.Life,
			n = T.Rate, g = T.Bright, m = T.Amount, w = T.Always == true,
		};
	end;

	function T.Dress(player, spec)
		if player == LocalPlayer then return end;
		if type(spec) ~= "table" or not STYLES[tostring(spec.s)] then T.Undress(player); return end;

		local okA, first = pcall(Color3.fromHex, tostring(spec.a));
		local okB, second = pcall(Color3.fromHex, tostring(spec.b));
		local cfg = {
			Style = tostring(spec.s), Color = okA and first or WHITE, Color2 = okB and second or (okA and first or WHITE),
			Rainbow = spec.r == true, Size = math.clamp(tonumber(spec.z) or 10, 1, 40),
			Life = math.clamp(tonumber(spec.l) or 0.9, 0.1, 5), Rate = math.clamp(tonumber(spec.n) or 140, 1, 600),
			Bright = math.clamp(tonumber(spec.g) or 85, 1, 100), Amount = math.clamp(tonumber(spec.m) or 100, 1, 400),
			Spread = 100, Gravity = 100, Always = spec.w == true,
		};
		cfg.key = table.concat({ cfg.Style, cfg.Color:ToHex(), cfg.Color2:ToHex(), tostring(cfg.Rainbow), cfg.Size, cfg.Life, cfg.Rate, cfg.Bright, cfg.Amount, tostring(cfg.Always) }, "|");

		if guests[player] and guests[player].key == cfg.key then return end;

		guests[player] = cfg;
		if player.Character then pcall(build, player.Character) end;
	end;

	function T.Undress(player)
		if not guests[player] then return end;
		guests[player] = nil;

		local character = player.Character;
		if character and live[character] and live[character].cfg ~= T then clear(character) end;

		if character and T.On and wants(player) then pcall(build, character) end;
	end;

	function T.Guests() return guests end;

	task.spawn(function()
		while ALIVE do
			task.wait(1);
			for player, cfg in pairs(guests) do
				if not player.Parent then
					guests[player] = nil;
				else
					local character = player.Character;
					local entry = character and live[character];
					if character and character:FindFirstChild("HumanoidRootPart") and not (entry and entry.cfg == cfg) then
						pcall(build, character);
					end;
				end;
			end;
		end;
	end);
	ESP.TrailStyles = order;
	ESP.ClearTrail = function()
		T.On = false;
		clearAll();
		if FX then pcall(FX.SetGroup, "trail", {}) end;
	end;

	local row = Sections.Trail:AddLabel("Enabled");
	row:AddToggle({ Default = false, Flag = "trail", Callback = function(v) T.On = v; refresh() end });
	local options = row:AddOption(1);
	options:AddLabel("Color"):AddColorPicker({ Default = T.Color, Flag = "trail_color", Callback = function(v)
		T.Color = v;
		if not T.Tint and T.Game and userPicked() then setFlag("trail_tint", true) end;
		refresh(); gameTune();
	end });

	local TRAIL_PREVIEW_FALLBACK = "rbxasset://textures/particles/sparkles_main.dds";
	local function trailRows(art)
		local out = {};
		for _, name in ipairs(order) do
			local fallback = (art and art[name]) or TRAIL_PREVIEW_FALLBACK;
			local image, rect, size = fallback, nil, nil;
			if FX then image, rect, size = FX.Art("builtin/trail/" .. name, fallback) end;
			out[#out + 1] = { name = name, label = name, image = image, rect = rect, rectsize = size };
		end;
		for _, entry in ipairs(FX and FX.Catalog or {}) do
			if entry.kind == "Trail" then
				local row = FX.Row(entry);
				local image, rect, size = FX.Art(entry.id, nil);
				if image then row.image, row.rect, row.rectsize = image, rect, size end;
				row.image = row.image or TRAIL_PREVIEW_FALLBACK;
				out[#out + 1] = row;
			end;
		end;
		return out;
	end;

	local trailGrid = Visuals.Trails:AddGallery({
		Name = "Trails", Icon = "wand-sparkles", Position = "left", Height = 440, Cell = 74, Reset = true, Smooth = true,
		Thumb = "Asset", Blank = "wand-sparkles", Empty = "No trails", Values = trailRows(),
		Default = "Bloom", Flag = "trail_style",
		Callback = function(v)
			if type(v) ~= "string" or v == "" then
				T.Style, T.Game = nil, nil;
				refresh();
				return;
			end;
			if STYLES[v] then
				T.Style, T.Game = v, nil;
			elseif FX and FX.ById[v] and FX.ById[v].kind == "Trail" then
				T.Game = v;
			else
				T.Game = nil;
			end;
			refresh();
		end,
	});

	if FX then
		FX.OnThumbs(function() trailGrid:setdata(trailRows()) end);
		Visuals.Trails.Signal:Connect(function(open) if open then FX.LoadThumbs() end end);
	end;

	task.delay(4, function()
		if not ALIVE then return end;
		local art = {};
		for _, name in ipairs(order) do
			local style = STYLES[name];
			local ok, texture = pcall(textureFor, style);
			if ok and type(texture) == "string" and texture ~= "" then art[name] = texture end;
			task.wait();
		end;
		if ALIVE then pcall(function() trailGrid:setdata(trailRows(art)) end) end;
	end);

	options:AddLabel("Target"):AddDropdown({
		Default = "Self",
		Values = { "Self", "Other", "All" },
		Flag = "trail_target",
		Callback = function(v) T.Target = v; refresh() end,
	});

	options:AddLabel("Fade Color"):AddColorPicker({ Name = "Fade Color", Default = T.Color2, Flag = "trail_color2", Callback = function(v)
		T.Color2 = v;
		if not T.Tint and T.Game and userPicked() then setFlag("trail_tint", true) end;
		refresh(); gameTune();
	end });

	options:AddLabel("Rainbow"):AddToggle({
		Default = false, Flag = "trail_rainbow",
		Callback = function(v) T.Rainbow = v; refresh(); gameTune() end,
	});

	options:AddLabel("Custom Colors"):AddToggle({ Default = false, Flag = "trail_tint",
		Callback = function(v) T.Tint = v; gameTune() end });
	gameTune();



	options:AddLabel("Size"):AddSlider({
		Min = 2, Max = 40, Default = 10, Rounding = 0, Size = 100,
		Flag = "trail_width",
		Callback = function(v) T.Size = v end,
	});

	options:AddLabel("Length"):AddSlider({
		Min = 2, Max = 40, Default = 9, Rounding = 0, Size = 100,
		Flag = "trail_life",
		Callback = function(v) T.Life = v / 10 end,
	});

	options:AddLabel("Density"):AddSlider({
		Min = 10, Max = 300, Default = 140, Type = "%", Size = 100,
		Flag = "trail_rate",
		Callback = function(v) T.Rate = v end,
	});

	options:AddLabel("Amount"):AddSlider({
		Min = 10, Max = 300, Default = 100, Type = "%", Size = 100,
		Flag = "trail_amount",
		Callback = function(v) T.Amount = v; refresh(); gameTune() end,
	});

	options:AddLabel("Brightness"):AddSlider({
		Min = 5, Max = 100, Default = 85, Type = "%", Size = 100,
		Flag = "trail_bright",
		Callback = function(v) T.Bright = v end,
	});

	options:AddLabel("Spread"):AddSlider({
		Min = 0, Max = 250, Default = 100, Type = "%", Size = 100,
		Flag = "trail_spread",
		Callback = function(v) T.Spread = v; refresh() end,
