	options:AddLabel("Always On"):AddToggle({
		Default = false, Flag = "trail_always",
		Callback = function(v) T.Always = v; refresh() end,
	});
end);
guard("world_fx_math", function()
	local F = {};
	function F.Number(v, fallback, lo, hi)
		v = tonumber(v);
		if not v or v ~= v or v == math.huge or v == -math.huge then v = fallback end;
		return math.clamp(v, lo, hi);
	end;
	function F.Smooth(t)
		t = math.clamp(t, 0, 1);
		return t * t * (3 - 2 * t);
	end;
	function F.Envelope(age, life, fadeIn, fadeOut)
		return F.Smooth(age / (life * fadeIn)) * F.Smooth((life - age) / (life * fadeOut));
	end;
	function F.Frame(position, tangent)
		local right = tangent.Magnitude > 0.0001 and tangent.Unit or Vector3.xAxis;
		local side = right:Cross(Vector3.yAxis);
		if side.Magnitude < 0.0001 then side = right:Cross(Vector3.xAxis) end;
		return CFrame.fromMatrix(position, right, side.Unit:Cross(right));
	end;
	function F.GlyphPath(style, distance, phase, bend)
		local q = distance / bend;
		if style == "Straight" then return Vector3.new(distance, 0, 0) end;
		if style == "Circuit" then
			local cell = bend / 8;
			local n = math.floor(distance / cell);
			local t, k = distance / cell - n, n % 6;
			local x, y, z = math.floor(n / 6) * 2, 0, 0;
			if k == 0 then x += t;
			elseif k == 1 then x += 1; y = t;
			elseif k == 2 then x += 1; y = 1; z = t;
			elseif k == 3 then x += 1 + t; y = 1; z = 1;
			elseif k == 4 then x += 2; y = 1 - t; z = 1;
			else x += 2; z = 1 - t end;
			return Vector3.new(x, y, phase > math.pi and -z or z) * cell;
		elseif style == "Zigzag" then
			local function triangle(v) return 1 - 4 * math.abs((v % 1) - 0.5) end;
			return Vector3.new(distance * 0.8, bend * 0.14 * (triangle(q * 0.8) - triangle(0)),
				bend * 0.2 * (triangle(q * 1.2 + phase) - triangle(phase)));
		elseif style == "Curve" then
			return Vector3.new(bend * math.sin(q), bend * 0.16 * math.sin(q * 0.6), bend * (1 - math.cos(q)));
		elseif style == "Helix" then
			return Vector3.new(distance * 0.72, bend * 0.24 * (math.cos(q * 1.8 + phase) - math.cos(phase)),
				bend * 0.24 * (math.sin(q * 1.8 + phase) - math.sin(phase)));
		elseif style == "Wave" then
			return Vector3.new(distance, bend * 0.3 * (math.sin(q * 1.8 + phase) - math.sin(phase)),
				bend * 0.15 * (math.sin(q * 0.9 + phase) - math.sin(phase)));
		elseif style == "Orbit" then
			return Vector3.new(bend * (math.sin(q + phase) - math.sin(phase)), bend * 0.12 * math.sin(q * 0.7),
				bend * (math.cos(q + phase) - math.cos(phase)));
		elseif style == "Ribbon" then
			return Vector3.new(distance * 0.7, bend * 0.24 * (math.sin(q * 1.4 + phase) - math.sin(phase)),
				bend * 0.3 * (math.sin(q * 2.8 + phase) - math.sin(phase)));
		end;
		return Vector3.new(distance * 0.85, bend * 0.13 * (math.sin(q * 0.7 + phase) - math.sin(phase)),
			bend * 0.22 * (math.sin(q * 1.1 + phase) - math.sin(phase)));
	end;
	function F.MeteorPoint(origin, velocity, travel)
		return origin + velocity * travel + Vector3.new(0, -1.8 * travel * travel, 0);
	end;
	function F.PixelWidth(camera, distance, pixels)
		local height = camera.ViewportSize and camera.ViewportSize.Y or 600;
		local fov = F.Number(camera.FieldOfView, 70, 1, 120);
		return 2 * math.max(0.1, distance) * math.tan(math.rad(fov) * 0.5)
			* math.max(0.1, pixels) / math.max(1, height);
	end;
	ESP.WorldFX = F;
end);
guard("glyphs", function()
	LPH_ATTRIBUTES(VM(NONE));
	local G = {
		On = false,
		Count = 55,
		Mode = "Theme",
		Color = Color3.fromRGB(120, 200, 255),
		Speed = 16,
		Length = 34,
		Width = 2,
		Life = 7,
		Glow = true,
	};

	local random = Random.new(93882);
	local lines = {};

	local DIRS = {
		Vector3.new(1, 0, 0), Vector3.new(-1, 0, 0),
		Vector3.new(0, 1, 0), Vector3.new(0, -1, 0),
		Vector3.new(0, 0, 1), Vector3.new(0, 0, -1),
	};

	local FAR = 120;
	local FADE_IN, FADE_OUT = 0.7, 1.4;
	local TURN_TIME = 0.22;

	local BANDS = { 14, 24, 36, 50, 66, 84 };
	local band = 0;

	local GOLDEN = 2.39996323;
	local spiral = 0;

	local strokes = Render.pool("Line", function(item) item.Visible = false end);

	local dotGui = Render.gui("glyphdots", -3);
	local dots, dotted = {}, 0;

	local bloomUrl;

	task.spawn(function()
		local ok, url = pcall(function()
			return Remote.id(Remote.file("particles/p_bloom.png"));
		end);

		if ALIVE and ok then bloomUrl = url end;
	end);

	local function glowDot()
		if not bloomUrl or dotted >= 420 then return nil end;

		dotted = dotted + 1;

		local dot = dots[dotted];

		if not dot then
			dot = Instance.new("ImageLabel");
			dot.Name = "Bloom";
			dot.AnchorPoint = Vector2.new(0.5, 0.5);

			dot.BackgroundTransparency = 1;
			dot.BorderSizePixel = 0;
			dot.Image = bloomUrl;
			dot.ResampleMode = Enum.ResamplerMode.Default;
			dot.Visible = false;
			dot.Parent = dotGui;

			dots[dotted] = dot;
		end;

		return dot;
	end;

	local function hideRest()
		strokes.done();

		for i = dotted + 1, #dots do
			if dots[i].Visible then dots[i].Visible = false end;
		end;
	end;

	local connection;

	local function clearPool()

		if connection then
			pcall(function() connection:Disconnect() end);

			connection = nil;
		end;

		strokes.wipe();

		for _, dot in ipairs(dots) do pcall(function() dot:Destroy() end) end;

		table.clear(dots);
		table.clear(lines);

		dotted = 0;
	end;

	local function spawnLine(seeded)
		local cam = Render.camera();

		if not cam then return nil end;

		local cf = cam.CFrame;

		band = band % #BANDS + 1;
		spiral = spiral + GOLDEN;

		local depth = BANDS[band] * random:NextNumber(0.85, 1.15);
		local reach = depth * 0.7;

		local radius = math.sqrt(random:NextNumber(0.05, 1)) * reach;

		local at = cf.Position
			+ cf.LookVector * depth
			+ cf.RightVector * math.cos(spiral) * radius
			+ cf.UpVector * math.sin(spiral) * radius * 0.6;

		local dir = DIRS[random:NextInteger(1, 6)];
		local life = G.Life * random:NextNumber(0.7, 1.35);

		return {
			pts = { at },
			sx = {}, sy = {}, son = {}, sfar = {},
			head = at,
			dir = dir,
			goal = dir,
			turn = 1,
			run = 0,
			leg = random:NextNumber(3, 9),
			life = life,

			age = seeded and random:NextNumber(0, life * 0.8) or 0,
			phase = random:NextNumber(0, 1),
		};
	end;

	local function advance(l, dt)
		l.age = l.age + dt;

		if l.turn < 1 then
			l.turn = math.min(1, l.turn + dt / TURN_TIME);

			local blend = l.turn * l.turn * (3 - 2 * l.turn);
			local mixed = l.dir:Lerp(l.goal, blend);

			if mixed.Magnitude > 0.001 then l.dir = mixed.Unit end;
		end;

		local step = G.Speed * dt;

		l.head = l.head + l.dir * step;
		l.run = l.run + step;

		if l.run >= l.leg then
			l.pts[#l.pts + 1] = l.head;
			l.goal = DIRS[random:NextInteger(1, 6)];
			l.turn = 0;
			l.run = 0;
			l.leg = random:NextNumber(3, 9);
		end;

		local total = (l.head - l.pts[#l.pts]).Magnitude;

		for i = 2, #l.pts do total = total + (l.pts[i] - l.pts[i - 1]).Magnitude end;

		local excess = total - G.Length;

		while excess > 0 and #l.pts >= 2 do
			local leg = l.pts[2] - l.pts[1];
			local len = leg.Magnitude;

			if len <= excess then
				table.remove(l.pts, 1);
				excess = excess - len;
			else
				l.pts[1] = l.pts[1] + leg.Unit * excess;
				excess = 0;
			end;
		end;

		if excess > 0 and #l.pts == 1 then
			local leg = l.head - l.pts[1];

			if leg.Magnitude > excess then l.pts[1] = l.pts[1] + leg.Unit * excess end;
		end;
	end;

	local function envelope(l, eye)
		if l.age >= l.life then return 0 end;

		local fade = math.min(1, l.age / FADE_IN);
		local left = l.life - l.age;

		if left < FADE_OUT then fade = math.min(fade, left / FADE_OUT) end;

		local away = (l.head - eye).Magnitude;

		if away > FAR then return 0 end;
		if away > FAR * 0.75 then fade = fade * (1 - (away - FAR * 0.75) / (FAR * 0.25)) end;

		return fade;
	end;

	local function colourAt(l, index, now)
		if G.Mode == "Rainbow" then
			return Color3.fromHSV(((now * 0.11 + l.phase) % 1), 0.85, 1);
		end;

		if G.Mode == "Single" then return G.Color end;

		local accent = SaladUI.AccentColor or G.Color;
		local h, s, v = accent:ToHSV();
		local drift = math.sin(index * 0.5 + l.phase * 6.283) * 0.09;

		return Color3.fromHSV((h + drift) % 1, math.clamp(s, 0.35, 1), math.max(v, 0.65));
	end;

	local blockAt, blockTo;

	local function cover(frame, padTop)
		if not (frame and frame.Visible and frame.AbsoluteSize.X > 8) then return end;

		local at = frame.AbsolutePosition - Vector2.new(10, padTop);
		local to = frame.AbsolutePosition + frame.AbsoluteSize + Vector2.new(10, 10);

		blockAt = blockAt and Vector2.new(math.min(blockAt.X, at.X), math.min(blockAt.Y, at.Y)) or at;
		blockTo = blockTo and Vector2.new(math.max(blockTo.X, to.X), math.max(blockTo.Y, to.Y)) or to;
	end;

	local function blocked(ax, ay, bx, by)
		if not blockAt then return false end;

		local dx, dy = bx - ax, by - ay;
		local lo, hi = 0, 1;

		for side = 1, 4 do
			local p, q;

			if side == 1 then p, q = -dx, ax - blockAt.X;
			elseif side == 2 then p, q = dx, blockTo.X - ax;
			elseif side == 3 then p, q = -dy, ay - blockAt.Y;
			else p, q = dy, blockTo.Y - ay end;

			if p == 0 then
				if q < 0 then return false end;
			else
				local r = q / p;

				if p < 0 then
					if r > hi then return false end;
					if r > lo then lo = r end;
				else
					if r < lo then return false end;
					if r < hi then hi = r end;
				end;
			end;
		end;

		return true;
	end;

	local function stroke(from, to, colour, width, alpha)
		if G.Glow then
			local glow = strokes.take();

			glow.From, glow.To = from, to;
			glow.Color = colour;
			glow.Thickness = math.max(1, width * 3.2);
			glow.Transparency = alpha * 0.16;
			glow.Visible = true;
		end;

		local piece = strokes.take();

		piece.From, piece.To = from, to;
		piece.Color = colour;
		piece.Thickness = math.max(1, width);
		piece.Transparency = alpha;
		piece.Visible = true;
	end;

	local glyphsShown = true;
	connection = SaladUI:AddSignal(RunService.RenderStepped:Connect(function(dt)
		if not SaladUI.ScreenGui.Parent then return end;

		if not G.On then
			if glyphsShown then
				glyphsShown = false;
				strokes.reset();
				dotted = 0;
				if #lines > 0 then table.clear(lines) end;
				hideRest();
			end;

			return;
		end;

		glyphsShown = true;
		strokes.reset();

		dotted = 0;

		local basis = Render.basis();

		if not basis then hideRest(); return end;

		dt = math.min(dt, 0.1);

		local eye = basis.pos;

		for i = #lines, 1, -1 do
			local l = lines[i];

			advance(l, dt);

			if l.age >= l.life or (l.head - eye).Magnitude > FAR * 1.3 then
				table.remove(lines, i);
			end;
		end;

		local room = 3;

		while #lines < G.Count and room > 0 do
			room = room - 1;

			local born = spawnLine(#lines < G.Count * 0.5);

			if not born then break end;

			lines[#lines + 1] = born;
		end;

		blockAt, blockTo = nil, nil;

		cover(ESP.WindowFrame and ESP.WindowFrame(), 42);
		cover(Preview and Preview.Panel, 10);
		local now = os.clock();

		for index, l in ipairs(lines) do
			local fade = envelope(l, eye);

			if fade > 0.02 then
				local pts = l.pts;
				local count = #pts;
				local colour = colourAt(l, index, now);
				local sx, sy, son, sfar = l.sx, l.sy, l.son, l.sfar;

				for i = 1, count do
					local x, y, depth = Render.project(basis, pts[i]);

					sx[i], sy[i], son[i], sfar[i] = x, y, depth > 0, depth;
				end;

				local hx, hy, hd = Render.project(basis, l.head);
				local last = count + 1;

				sx[last], sy[last], son[last], sfar[last] = hx, hy, hd > 0, hd;

				for i = 2, last do
					if son[i - 1] and son[i] then
						local ax, ay = sx[i - 1], sy[i - 1];
						local bx, by = sx[i], sy[i];

						if not blocked(ax, ay, bx, by) then
							local av = Vector2.new(ax, ay);
							local bv = Vector2.new(bx, by);
							local t = (i - 1) / count;
							local alpha = fade * (0.08 + 0.92 * t);
							local depth = math.clamp(1 - sfar[i] / FAR, 0.12, 1);

							if alpha > 0.02 then
								stroke(av, bv, colour, G.Width * depth * (0.45 + 0.55 * t), alpha);
							end;
						end;
					end;
				end;

				if G.Glow then
					for i = 2, count do
						if son[i] then
							local dot = glowDot();

							if not dot then break end;

							local t = (i - 1) / count;
							local depth = math.clamp(1 - sfar[i] / FAR, 0.12, 1);
							local size = math.max(7, G.Width * depth * 11);

							dot.Position = UDim2.fromOffset(sx[i], sy[i]);
							dot.Size = UDim2.fromOffset(size, size);
							dot.ImageColor3 = colour;
							dot.ImageTransparency = 1 - math.clamp(fade * (0.12 + 0.88 * t) * 0.85, 0, 1);
							dot.Visible = true;
						end;
					end;
				end;
			end;
		end;

		hideRest();
	end));

	ESP.Glyphs = G;
	ESP.ClearGlyphs = onUnload("glyphs", clearPool);

	local row = Sections.Glyphs:AddLabel("Glyphs");
	row:AddToggle({
		Default = false, Flag = "glyphs",
		Callback = function(v)
			G.On = v;

			if not v then table.clear(lines) end;
		end,
	});
	local options = row:AddOption(1);
	options:AddLabel("Color"):AddColorPicker({ Default = G.Color, Flag = "glyphs_color", Callback = function(v) G.Color = v end });

	options:AddLabel("Color Mode"):AddDropdown({
		Default = "Theme",
		Values = { "Theme", "Rainbow", "Single" },
		Flag = "glyphs_mode",
		Callback = function(v) G.Mode = v end,
	});

	options:AddLabel("Count"):AddSlider({
		Min = 8, Max = 160, Default = 55, Rounding = 0, Size = 100,
		Flag = "glyphs_count",
		Callback = function(v) G.Count = v end,
	});

	options:AddLabel("Speed"):AddSlider({
		Min = 1, Max = 90, Default = 16, Rounding = 0, Size = 100,
		Flag = "glyphs_speed",
		Callback = function(v) G.Speed = v end,
	});

	options:AddLabel("Trail"):AddSlider({
		Min = 6, Max = 120, Default = 34, Rounding = 0, Size = 100,
		Flag = "glyphs_length",
		Callback = function(v) G.Length = v end,
	});

	options:AddLabel("Lifetime"):AddSlider({
		Min = 2, Max = 25, Default = 7, Rounding = 0, Size = 100, Type = "s",
		Flag = "glyphs_life",
		Callback = function(v) G.Life = v end,
	});

	options:AddLabel("Width"):AddSlider({
		Min = 1, Max = 8, Default = 2, Rounding = 0, Size = 100,
		Flag = "glyphs_width",
		Callback = function(v) G.Width = v end,
	});

	options:AddLabel("Glow"):AddToggle({
		Default = true, Flag = "glyphs_glow",
		Callback = function(v) G.Glow = v end,
	});
end);
guard("models", function()
	LPH_ATTRIBUTES(VM(NONE));

	local STORE = userFile("models.txt");
	local SIZES_FILE = userFile("model_sizes.txt");

	local BUILTIN = {
		{ Name = "Tung Tung Sahur", Id = "138151705692565" },
	};

	local M = { On = false, Pick = nil, Sizes = {}, Rotations = {} };

	ESP.Models = M;

	local defs, order = {}, {};
	local cache = {};
	local generation = 0;
	local sizeApplyToken = 0;
	local sizeSaveToken, sizesDirty = 0, false;
	local shell, follow, charConn = nil, nil, nil;
	local hiddenParts, hiddenDecals = {}, {};
	local grid;
	local applyAccessoryVisibility;
	local accessoryHidden, accessoryConn, appearanceConn = {}, nil, nil;
	local accessoryTransparencies = {};
	local hairless, noAccessories, accessoryRefreshQueued = false, false, false;
	local hairAssetIds, hairKind, hairKindLoading = {}, {}, {};
	local MarketplaceService = game:GetService("MarketplaceService");

	local korblox, headless = false, false;
	local legBackup, headBackup = {}, {};
	local r6KorbloxShell = nil;

	local function register(def)
		if defs[def.Name] then return end;

		defs[def.Name] = def;
		order[#order + 1] = def.Name;
	end;

	local function rebuildList()
		table.clear(defs);
		table.clear(order);

		for _, def in ipairs(BUILTIN) do
			register({ Name = def.Name, Id = def.Id, Kind = "asset" });
		end;

		table.sort(order, function(a, b) return string.lower(a) < string.lower(b) end);

		if isfile and readfile and isfile(STORE) then
			local ok, body = pcall(readfile, STORE);

			if ok and type(body) == "string" then
				for line in string.gmatch(body, "[^\r\n]+") do
					local id, name = string.match(line, "^(%d+)|(.*)$");

					if id then
						register({ Name = (name ~= "" and name) or ("Model " .. id), Id = id, Kind = "asset", User = true });
					end;
				end;
			end;
		end;
	end;

	local function saveUsers()
		if not writefile then return end;

		local lines = {};

		for _, name in ipairs(order) do
			local def = defs[name];

			if def and def.User and def.Id then
				lines[#lines + 1] = def.Id .. "|" .. def.Name;
			end;
		end;

		pcall(writefile, STORE, table.concat(lines, "\n"));
	end;

	local function rows()
		local out = {};

		for _, name in ipairs(order) do
			local def = defs[name];

			out[#out + 1] = { name = name, label = name, id = def and def.Id and tonumber(def.Id) or nil };
		end;

		return out;
	end;

	local function refreshGrid()
		if not grid then return end;

		local values = rows();

		if grid.setdata then
			pcall(function() grid:setdata(values) end);
		elseif grid.setlist then
			pcall(function() grid:setlist(values) end);
		end;
	end;

	local function restoreReal()
		for item, value in pairs(hiddenParts) do
			if item.Parent then pcall(function() item.LocalTransparencyModifier = value end) end;
		end;

		for item, value in pairs(hiddenDecals) do
			if item.Parent then pcall(function() item.Transparency = value end) end;
		end;

		table.clear(hiddenParts);
		table.clear(hiddenDecals);
		if applyAccessoryVisibility then applyAccessoryVisibility() end;
	end;

	local function hideReal(character)
		for _, d in ipairs(character:GetDescendants()) do
			local accessory = d:FindFirstAncestorWhichIsA("Accessory");
			local ownedAccessory = accessory and accessory:GetAttribute("VisualsCharacterAccessory");
			if d:IsA("BasePart") and not ownedAccessory then
				if hiddenParts[d] == nil then hiddenParts[d] = accessoryHidden[d] or d.LocalTransparencyModifier end;

				if d.LocalTransparencyModifier < 1 then d.LocalTransparencyModifier = 1 end;
			elseif not ownedAccessory and (d:IsA("Decal") or d:IsA("Texture")) then
				if hiddenDecals[d] == nil then hiddenDecals[d] = d.Transparency end;

				if d.Transparency < 1 then d.Transparency = 1 end;
			end;
		end;
	end;

	local HAIR_WORDS = { "hair", "bang", "ponytail", "pigtail", "braid", "dread", "locks",
		"wig", "afro", "mohawk", "fringe", "twintail", "hairstyle", "bobcut", "hairdo" };
	local function refreshHairIds(character)
		table.clear(hairAssetIds);
		local human = character and character:FindFirstChildOfClass("Humanoid");
		if not human then return end;
		local ok, description = pcall(human.GetAppliedDescription, human);
		if ok and description then
			for id in string.gmatch(description.HairAccessory or "", "%d+") do hairAssetIds[id] = true end;
		end;
	end;
	local function sourceAssetId(object)
		local ok, id = pcall(function() return object.SourceAssetId end);
		return ok and tonumber(id) or nil;
	end;
	local function queueHairKind(object, id)
		local key = id and string.format("%.0f", id) or nil;
		if not key or id <= 0 or hairKind[key] ~= nil or hairKindLoading[key] then return end;
		hairKindLoading[key] = true;
		task.spawn(function()
			local ok, info = pcall(MarketplaceService.GetProductInfo, MarketplaceService, id, Enum.InfoType.Asset);
			hairKindLoading[key] = nil;
			hairKind[key] = ok and type(info) == "table" and tonumber(info.AssetTypeId) == Enum.AssetType.HairAccessory.Value or false;
			if hairKind[key] and ALIVE and hairless and object.Parent then applyAccessoryVisibility() end;
		end);
	end;
	local function isHairObject(object)
		if object:IsA("Accessory") and object.AccessoryType == Enum.AccessoryType.Hair then return true end;
		for _, descendant in ipairs(object:GetDescendants()) do
			if descendant:IsA("Attachment") and descendant.Name == "HairAttachment" then return true end;
		end;
		local id = sourceAssetId(object);
		local key = id and string.format("%.0f", id) or nil;
		if key and (hairAssetIds[key] or hairKind[key] == true) then return true end;
		if key and hairKind[key] == nil then queueHairKind(object, id) end;
		local text = string.lower(object.Name);
		local ok, tags = pcall(object.GetTags, object);
		if ok then for _, tag in ipairs(tags) do text ..= " " .. string.lower(tag) end end;
		for _, word in ipairs(HAIR_WORDS) do if string.find(text, word, 1, true) then return true end end;
		return false;
	end;
	applyAccessoryVisibility = function()
		local character = LocalPlayer.Character;
		local wanted, opaqueHidden = {}, {};
		if character and (hairless or noAccessories) then
			for _, object in ipairs(character:GetChildren()) do
				local accessory = object:IsA("Accessory") or object:IsA("Hat");
				local scriptAccessory = object:GetAttribute("VisualsCharacterAccessory") == true;
				local hideAccessory = noAccessories and accessory and not scriptAccessory;

				local hideHair = hairless and accessory and isHairObject(object);
				if hideAccessory or hideHair then
					if object:IsA("BasePart") then wanted[object] = true end;
					for _, part in ipairs(object:GetDescendants()) do if part:IsA("BasePart") then wanted[part] = true end end;
					if hideAccessory then for part in pairs(wanted) do if part == object or part:IsDescendantOf(object) then opaqueHidden[part] = true end end end;
				end;
			end;
		end;

		for part, value in pairs(accessoryTransparencies) do
			if not opaqueHidden[part] then
				if part.Parent then part.Transparency = (headless and headBackup[part]) and 1 or value end;
				accessoryTransparencies[part] = nil;
			end;
		end;
		for part in pairs(opaqueHidden) do
			if accessoryTransparencies[part] == nil then
				accessoryTransparencies[part] = headBackup[part] and headBackup[part].Transparency or part.Transparency;
			end;
			part.Transparency = 1;
		end;
		for part, value in pairs(accessoryHidden) do
			if not wanted[part] then
				if part.Parent then part.LocalTransparencyModifier = hiddenParts[part] ~= nil and 1 or value end;
				accessoryHidden[part] = nil;
			end;
		end;
		for part in pairs(wanted) do
			if accessoryHidden[part] == nil then accessoryHidden[part] = hiddenParts[part] or part.LocalTransparencyModifier end;
			part.LocalTransparencyModifier = 1;
		end;
	end;
	local function watchAccessories(character)
		if accessoryConn then accessoryConn:Disconnect(); accessoryConn = nil end;
		if not character then return end;
		refreshHairIds(character);
		accessoryConn = character.DescendantAdded:Connect(function()
			if not (ALIVE and (hairless or noAccessories)) or accessoryRefreshQueued then return end;
			accessoryRefreshQueued = true;
			task.defer(function()
				accessoryRefreshQueued = false;
				if ALIVE and LocalPlayer.Character == character then applyAccessoryVisibility() end;
			end);
		end);
	end;
	local accessoryVisibilityClock = 0;
	SaladUI:AddSignal(RunService.RenderStepped:Connect(function(dt)
		if not (hairless or noAccessories) then accessoryVisibilityClock = 0; return end;
		accessoryVisibilityClock += dt;
		if accessoryVisibilityClock >= 0.08 then accessoryVisibilityClock = 0; applyAccessoryVisibility() end;
	end));

	local function template(def)
		if cache[def.Name] then return cache[def.Name] end;

		local ok, objects = Remote.objects(function() return game:GetObjects("rbxassetid://" .. tostring(def.Id)) end);

		if not ok or type(objects) ~= "table" or not objects[1] then return nil end;

		local root = objects[1];
		for index = 2, #objects do pcall(function() objects[index]:Destroy() end) end;
		if not ALIVE then root:Destroy(); return nil end;

		if not root:IsA("Model") then
			local holder = Instance.new("Model");

			root.Parent = holder;
			root = holder;
		end;

		local descendants = root:GetDescendants();
		if #descendants > 4096 then root:Destroy(); return nil end;
		root.Archivable = true;
		for _, d in ipairs(descendants) do
			d.Archivable = true;
			if d:IsA("LuaSourceContainer") or d:IsA("Humanoid") or d:IsA("JointInstance")
				or d:IsA("Constraint") or d:IsA("BodyMover") or d:IsA("Sound") or d:IsA("ParticleEmitter")
				or d:IsA("Beam") or d:IsA("Trail") or d:IsA("Fire") or d:IsA("Smoke") or d:IsA("Sparkles") then
				pcall(function() d:Destroy() end);
			end;
		end;

		for _, d in ipairs(root:GetDescendants()) do
			if d:IsA("BasePart") then
				d.Anchored, d.CanCollide, d.CanQuery, d.CanTouch = true, false, false, false;
				d.Massless, d.CastShadow, d.Locked = true, false, true;
			end;
		end;

		cache[def.Name] = root;

		return root;
	end;

	local function clear()
		if follow then
			pcall(function() follow:Disconnect() end);

			follow = nil;
		end;

		if shell then
			pcall(function() shell:Destroy() end);

			shell = nil;
		end;

		restoreReal();
	end;

	local KORBLOX = {
		RightUpperLeg = { MeshId = "rbxassetid://902942096", TextureID = "rbxassetid://902843398" },
		RightLowerLeg = { MeshId = "rbxassetid://902942093", Transparency = 1 },
		RightFoot = { MeshId = "rbxassetid://902942089", Transparency = 1 },
	};

	local HEADLESS_MESH = "rbxassetid://6686307858";

	local function restoreKorblox()
		if r6KorbloxShell then r6KorbloxShell:Destroy(); r6KorbloxShell = nil end;
		for part, saved in pairs(legBackup) do
			if part.Parent then
				for property, value in pairs(saved) do
					pcall(function() part[property] = value end);
				end;
			end;
		end;

		table.clear(legBackup);
	end;

	local function applyKorblox()
		if not korblox then return end;

		local character = LocalPlayer.Character;

		if not character then return end;

		restoreKorblox();
		local r6Leg = character:FindFirstChild("Right Leg");
		if r6Leg and r6Leg:IsA("BasePart") and not character:FindFirstChild("RightUpperLeg") then
			legBackup[r6Leg] = { Transparency = r6Leg.Transparency };
			local shellPart = Instance.new("Part");
			shellPart.Name = "VisualsR6Korblox";
			shellPart:SetAttribute(TAG, INIT_GENERATION);
			shellPart.Size, shellPart.CFrame = r6Leg.Size, r6Leg.CFrame;
			shellPart.Color, shellPart.Material = r6Leg.Color, Enum.Material.SmoothPlastic;
			shellPart.Transparency, shellPart.Reflectance = 0, r6Leg.Reflectance;
			shellPart.CanCollide, shellPart.CanQuery, shellPart.CanTouch = false, false, false;
			shellPart.Massless, shellPart.CastShadow = true, false;
			local mesh = Instance.new("SpecialMesh");
			mesh.MeshType = Enum.MeshType.FileMesh;
			mesh.MeshId, mesh.TextureId = "rbxassetid://902942096", "rbxassetid://902843398";
			mesh.Scale = Vector3.new(1.05, 1, 1.05);
			mesh.Parent = shellPart;
			local weld = Instance.new("WeldConstraint");
			weld.Part0, weld.Part1, weld.Parent = shellPart, r6Leg, shellPart;
			shellPart.Parent = character;
			r6Leg.Transparency = 1;
			r6KorbloxShell = shellPart;
			return;
		end;

		for name, swapTo in pairs(KORBLOX) do
			local part = character:FindFirstChild(name);

			if part then
				local saved = {};

				for property in pairs(swapTo) do
					local ok, value = pcall(function() return part[property] end);

					if ok then saved[property] = value end;
				end;

				legBackup[part] = saved;

				for property, value in pairs(swapTo) do
					pcall(function() part[property] = value end);
				end;
			end;
		end;
	end;

	local function restoreHeadless()
		for object, saved in pairs(headBackup) do
			if object.Parent then
				for property, value in pairs(saved) do
					if property == "Transparency" and accessoryTransparencies[object] ~= nil then value = 1 end;
					pcall(function() object[property] = value end);
				end;
			end;
		end;

		table.clear(headBackup);
	end;

	local function applyHeadless()
		if not headless then return end;

		local character = LocalPlayer.Character;
		local head = character and character:FindFirstChild("Head");

		if not head then return end;

		restoreHeadless();

		headBackup[head] = {
			MeshId = (pcall(function() return head.MeshId end)) and head.MeshId or nil,
			TextureID = (pcall(function() return head.TextureID end)) and head.TextureID or nil,
			Transparency = head.Transparency,
		};

		pcall(function() head.MeshId = HEADLESS_MESH end);
		pcall(function() head.TextureID = HEADLESS_MESH end);
		pcall(function() head.Transparency = 1 end);

		for _, child in ipairs(head:GetDescendants()) do
			local ok, value = pcall(function() return child.Transparency end);

			if ok and type(value) == "number" then
				headBackup[child] = { Transparency = value };

				pcall(function() child.Transparency = 1 end);
			end;
		end;
	end;

	local function build(mine)
		local def = M.Pick and defs[M.Pick];

		if not def then return end;

		local character, root;

		for _ = 1, 40 do
			if mine ~= generation or not (M.On and M.Pick) then return end;

			character = LocalPlayer.Character;
			root = character and character:FindFirstChild("HumanoidRootPart");

			if root then break end;

			task.wait(0.25);
		end;

		if not character or not root then return end;

		local human = character:FindFirstChildOfClass("Humanoid");

		local source = template(def);

		if not ALIVE or not M.On or mine ~= generation or LocalPlayer.Character ~= character or not character.Parent or not root.Parent then return end;

		if not source then
			Notification.new({ Title = "Models", Content = "Could not load " .. def.Name, Duration = 4 });

			return;
		end;

		local clone = source:Clone();
		if not clone then return end;

		local body = ESP.BodyExtents(character, root);
		local charSize = body and body.half * 2 or Vector3.new(3, 5, 2);
		local _, rawSize = clone:GetBoundingBox();

		if rawSize.Y > 0.01 then
			local custom = math.clamp(tonumber(M.Sizes[def.Name]) or 1, 0.35, 1.25);
			local scale = (charSize.Y / rawSize.Y) * custom;

			if math.abs(scale - 1) > 0.02 then pcall(function() clone:ScaleTo(clone:GetScale() * scale) end) end;
		end;

		local box, size = clone:GetBoundingBox();
		local pivotFix = (clone:GetPivot():Inverse() * box):Inverse();
		local lift = size.Y * 0.5 - root.Size.Y * 0.5 - (human and human.HipHeight or 0);

		clone.Name = "VisualsModelShell";
		Render.DepthTree(clone, false);
		local shellParts = {};
		for _, part in ipairs(clone:GetDescendants()) do
			if part:IsA("BasePart") then shellParts[#shellParts + 1] = { part, part.LocalTransparencyModifier } end;
		end;
		clone.Parent = workspace;

		shell = clone;

		hideReal(character);

		local last, lastRotation, hideAt, lastVisible = nil, nil, 0, nil;
		local bodyWatch = character.DescendantAdded:Connect(function() if ALIVE and M.On and shell then hideAt = 0 end end);
		SaladUI:AddSignal(bodyWatch);
		clone.Destroying:Once(function() bodyWatch:Disconnect() end);

		follow = RunService.RenderStepped:Connect(function()
			if not (ALIVE and M.On and shell and shell.Parent) then return end;

			if not root.Parent then return end;
			local visible = ESP.Visibility.Character(Render.camera(), character, root);
			if lastVisible ~= visible then
				lastVisible = visible;
				for _, saved in ipairs(shellParts) do
					if saved[1].Parent then saved[1].LocalTransparencyModifier = visible and saved[2] or 1 end;
				end;
			end;

			local cf = root.CFrame;
			local rotation = M.Rotations[def.Name] or 0;
			if os.clock() >= hideAt then hideAt = os.clock() + 0.2; hideReal(character) end;

			if last == cf and lastRotation == rotation then return end;

			last, lastRotation = cf, rotation;

			local look, pos = cf.LookVector, cf.Position;

			shell:PivotTo(CFrame.new(pos.X, pos.Y + lift, pos.Z)
				* CFrame.fromEulerAnglesYXZ(0, math.atan2(-look.X, -look.Z) + math.rad(rotation), 0)
				* pivotFix);

		end);

	end;

	local function apply()
		generation = generation + 1;

		clear();

		if not (M.On and M.Pick) then
			return;
		end;

		local mine = generation;

		task.spawn(function()
			local ok, err = pcall(build, mine);

			if not ok then warn("[visuals] model: " .. tostring(err)) end;

			if mine == generation and not M.On then clear() end;
		end);
	end;

	local function flushSizes()
		if not sizesDirty or not writefile then return end;
		local lines = {};
		for name in pairs(defs) do
			if M.Sizes[name] or M.Rotations[name] then
				lines[#lines + 1] = name .. "|" .. tostring(M.Sizes[name] or 1) .. "|" .. tostring(M.Rotations[name] or 0);
			end;
		end;
		table.sort(lines);
		if pcall(writefile, SIZES_FILE, table.concat(lines, "\n")) then sizesDirty = false end;
	end;
	local function queueModelSettingsSave()
		sizesDirty = true;

		if writefile then
			sizeSaveToken += 1;
			local saveToken = sizeSaveToken;
			task.delay(0.35, function()
				if saveToken == sizeSaveToken and ALIVE then flushSizes() end;
			end);
		end;
	end;
	local function setRotation(name, value)
		if not ALIVE or not defs[name] then return end;
		value = tonumber(value);
		if not value or value ~= value or math.abs(value) == math.huge then return end;
		M.Rotations[name] = math.clamp(value, 0, 360);
		queueModelSettingsSave();
	end;
	M.SetRotation = setRotation;
	local function setSize(name, value)
		if not ALIVE or not defs[name] then return end;
		value = tonumber(value);
		if not value or value ~= value or math.abs(value) == math.huge then return end;
		M.Sizes[name] = math.clamp(value, 0.35, 1.25);
		queueModelSettingsSave();

		if M.Pick == name and M.On then
			sizeApplyToken += 1;
			local token = sizeApplyToken;

			task.delay(0.12, function()
				if token == sizeApplyToken and ALIVE and M.On and M.Pick == name then
					apply();
				end;
			end);
		end;
	end;

	local function loadSizes()
		if not (isfile and readfile and isfile(SIZES_FILE)) then return end;

		local ok, body = pcall(readfile, SIZES_FILE);

		if not ok or type(body) ~= "string" then return end;

		for line in string.gmatch(body, "[^\r\n]+") do
			local name, value, rotation = string.match(line, "^(.-)|([^|]+)|?(.*)$");
			value, rotation = tonumber(value), tonumber(rotation);

			if name and defs[name] then
				if value and value == value and math.abs(value) < math.huge then M.Sizes[name] = math.clamp(value, 0.35, 1.25) end;
				if rotation and rotation == rotation and math.abs(rotation) < math.huge then M.Rotations[name] = math.clamp(rotation, 0, 360) end;
			end;
		end;
	end;

	local function choose(value)
		local name = (type(value) == "table") and value[1] or value;
		name = type(name) == "string" and defs[name] and name or nil;
		local enabled = name ~= nil;
		if M.Pick == name and M.On == enabled then return end;
		M.Pick, M.On = name, enabled;
		apply();
	end;

	local function addById(text)
		local id = string.match(tostring(text or ""), "(%d+)");

		if not id then
			Notification.new({ Title = "Models", Content = "Invalid ID", Duration = 4 });

			return;
		end;

		register({ Name = "Model " .. id, Id = id, Kind = "asset", User = true });
		saveUsers();
		refreshGrid();
	end;

	local function forget(name)
		local def = defs[name];

		if not (def and def.User) then return end;

		defs[name] = nil;

		for index, other in ipairs(order) do
			if other == name then table.remove(order, index); break end;
		end;

		if M.Pick == name then M.Pick, M.On = nil, false; apply(); if grid then grid:set("") end end;

		saveUsers();
		refreshGrid();
	end;

	rebuildList();
	loadSizes();

	local function reapply()
		if not ALIVE then return end;

		task.wait(1);

		if not ALIVE then return end;

		pcall(applyKorblox);
		pcall(applyHeadless);
		pcall(applyAccessoryVisibility);

		if M.On then pcall(apply) end;
	end;

	local function watchCharacter()
		if charConn then return end;

		charConn = SaladUI:AddSignal(LocalPlayer.CharacterAdded:Connect(function(character)
			watchAccessories(character);
			task.spawn(reapply);
		end));
		watchAccessories(LocalPlayer.Character);
		appearanceConn = LocalPlayer.CharacterAppearanceLoaded:Connect(function(character)
			if ALIVE and LocalPlayer.Character == character then task.spawn(reapply) end;
		end);
	end;

	watchCharacter();

	Sections.Character:AddLabel("Korblox Leg"):AddToggle({
		Name = "Korblox Leg",
		Default = false,
		Flag = "korblox_leg",
		Callback = function(v)
			korblox = v;

			if v then
				watchCharacter();
				applyKorblox();
			else
				restoreKorblox();
			end;
		end,
	});

	Sections.Character:AddLabel("Headless"):AddToggle({
		Name = "Headless",
		Default = false,
		Flag = "headless",
		Callback = function(v)
			headless = v;

			if v then
				watchCharacter();
				applyHeadless();
			else
				restoreHeadless();
			end;
		end,
	});

	M.SetHairless = function(value)
		hairless, M.Hairless = value == true, value == true;
		if hairless then refreshHairIds(LocalPlayer.Character) end;
		applyAccessoryVisibility();
	end;
	M.SetNoAccessories = function(value)
		noAccessories, M.NoAccessories = value == true, value == true;
		applyAccessoryVisibility();
	end;
	Sections.Character:AddLabel("Hairless"):AddToggle({ Default = false, Flag = "hairless", Callback = M.SetHairless });

	if IS_MM2 then
		local noWeapons, hiddenLtm, hiddenFx, hiddenDecals = false, {}, {}, {};

		local function weaponGroups()
			local out, char = {}, LocalPlayer.Character;

			for _, slot in ipairs({ "Knife", "Gun" }) do
				local ref = char and char:FindFirstChild("DisplayRef" .. slot);
				local part = ref and ref:IsA("ObjectValue") and ref.Value;

				if part and part:IsA("BasePart") then
					out[#out + 1] = part;

					for _, sibling in ipairs(part.Parent and part.Parent:GetChildren() or {}) do
						local weld = sibling ~= part and sibling:FindFirstChildOfClass("WeldConstraint");

						if weld and (weld.Part0 == part or weld.Part1 == part) then out[#out + 1] = sibling end;
					end;
				end;
			end;

			local collection = game:GetService("CollectionService");
			local tools = {};
			for _, tag in ipairs({ "Weapon_Gun", "Weapon_Knife" }) do
				for _, tool in ipairs(collection:GetTagged(tag)) do
					if tool:IsDescendantOf(LocalPlayer) or (char and tool:IsDescendantOf(char)) then
						out[#out + 1] = tool;
						tools[tool] = true;
					end;
				end;
			end;
			local scriptVisuals = LocalPlayer.PlayerScripts:FindFirstChild("ToolHandleVisuals");
			for _, container in ipairs({ workspace, scriptVisuals }) do
				if container then
					for _, root in ipairs(container:GetChildren()) do
						local constraint = root:IsA("BasePart") and root:FindFirstChild("VisualConstraint");
						if constraint and constraint:IsA("RigidConstraint") then
							for _, attachment in ipairs({ constraint.Attachment0, constraint.Attachment1 }) do
								local tool = attachment and attachment:FindFirstAncestorOfClass("Tool");
								if tool and tools[tool] then out[#out + 1] = root; break end;
							end;
						end;
					end;
				end;
			end;
			return out;
		end;

		local function hideOne(item)
			if item:IsA("BasePart") then
				if hiddenLtm[item] == nil then hiddenLtm[item] = item.LocalTransparencyModifier end;
				item.LocalTransparencyModifier = 1;
			elseif item:IsA("Decal") or item:IsA("Texture") then
				if hiddenDecals[item] == nil then hiddenDecals[item] = item.Transparency end;
				item.Transparency = 1;
			elseif item:IsA("ParticleEmitter") or item:IsA("Beam") or item:IsA("Trail") or item:IsA("Fire")
				or item:IsA("Sparkles") or item:IsA("Smoke") or item:IsA("Light") then
				if hiddenFx[item] == nil then hiddenFx[item] = item.Enabled end;
				item.Enabled = false;
			end;
		end;

		local function hideWeapons()
			for _, root in ipairs(weaponGroups()) do
				hideOne(root);
				for _, item in ipairs(root:GetDescendants()) do hideOne(item) end;
			end;
		end;

		local function showWeapons()
			for item, value in pairs(hiddenLtm) do
				if item.Parent then pcall(function() item.LocalTransparencyModifier = value end) end;
			end;
			for item, value in pairs(hiddenFx) do
				if item.Parent then pcall(function() item.Enabled = value end) end;
			end;
			for item, value in pairs(hiddenDecals) do
				if item.Parent then pcall(function() item.Transparency = value end) end;
			end;
			table.clear(hiddenDecals);
			table.clear(hiddenLtm);
			table.clear(hiddenFx);
		end;

		local keepUp = 0;
		SaladUI:AddSignal(RunService.Heartbeat:Connect(function(dt)
			if not noWeapons then return end;
			keepUp += dt;
			if keepUp < 0.25 then return end;
			keepUp = 0;
			pcall(hideWeapons);
		end));

		Sections.Character:AddLabel("No Weapons"):AddToggle({
			Default = false, Flag = "no_weapons",
			Callback = function(v)
				noWeapons = v == true;
				if noWeapons then pcall(hideWeapons) else showWeapons() end;
			end,
		});

		onUnload("no weapons", function() noWeapons = false; showWeapons() end);
	end;
	Sections.Character:AddLabel("No Accessories"):AddToggle({ Default = false, Flag = "no_accessories", Callback = M.SetNoAccessories });

	-- add and take off live on the gallery's own header
	local function addModel()
		local asked = false;

		pcall(function()
			SaladUI.Lib:ask({
				title = "Add model",
				icon = "plus",
				hint = "Model id or link",
				accept = "Add",
				deny = "Cancel",
				callback = function(text) addById(text) end,
			});

			asked = true;
		end);

		if not asked then addById(getgenv and getgenv().VISUALS_MODEL_ID) end;
	end;

	local function removeModel()
		M.On = false;
		M.Pick = nil;
		local lib = SaladUI.Lib;
		local quiet, applying = lib.quiet, lib.configApplying;
		lib.quiet, lib.configApplying = true, true;
		pcall(function() if grid then grid:set("") end end);
		lib.quiet, lib.configApplying = quiet, applying;

		apply();
	end;

	local function showModelMenu(name, _, x, y, cell)
		local def = defs[name];

		if not ALIVE or not def then return end;

		if typeof(cell) == "Instance" and cell:IsA("GuiObject") then
			local position, size = cell.AbsolutePosition, cell.AbsoluteSize;
			x = position.X + size.X - 8;
			y = position.Y + 20;
		end;

		local items = {};

		if def.Id then
			items[#items + 1] = { icon = "copy", name = "Copy ID", callback = function() pcall(setclipboard, def.Id) end };
		end;

		if def.User then
			items[#items + 1] = { icon = "trash-2", name = "Remove", callback = function() forget(name) end };
		end;

		local ok, err = pcall(function()
			SaladUI.Lib:popup({
				name = "VisualsModelOptions",
				title = name, icon = "shirt", x = x, y = y, follow = cell, width = 194,
				items = items,
				sliders = {{
					name = "Size",
					min = 35,
					max = 125,
					value = math.floor((M.Sizes[name] or 1) * 100 + 0.5),
					suffix = "%",
					callback = function(value) setSize(name, value / 100) end,
				}, {
					name = "Rotate",
					min = 0, max = 360,
					value = M.Rotations[name] or 0,
					suffix = "°",
					callback = function(value) setRotation(name, value) end,
				}},
			});
		end);
		if not ok then recordError("model options: " .. tostring(err)) end;
	end;

	grid = Visuals.Models:AddGallery({
		Name = "Models",
		Icon = "shirt",
		Position = "left",
		Height = 320,
		Cell = 78,
		Thumb = "Asset",
		Blank = "person-standing",
		Empty = "No models yet",
		Values = rows(),
		Flag = "model_pick",
		Reset = true,
		Smooth = true,
		Callback = choose,
		Action = { Icon = "ellipsis", Callback = showModelMenu },
		Buttons = { { icon = "plus", callback = addModel }, { icon = "x", callback = removeModel } },
	});
	task.spawn(function()
		task.wait(0.2);
		for index = 1, math.min(#order, 6) do
			if not ALIVE then return end;
			local def = defs[order[index]];
			if def then pcall(template, def) end;
			task.wait();
		end;
	end);

	ESP.ClearModels = onUnload("models", function()
		flushSizes(); sizeSaveToken += 1;
		M.On = false;
		korblox, headless = false, false;
		hairless, noAccessories = false, false;
		generation = generation + 1;

		if charConn then pcall(function() charConn:Disconnect() end); charConn = nil end;
		if accessoryConn then accessoryConn:Disconnect(); accessoryConn = nil end;
		if appearanceConn then appearanceConn:Disconnect(); appearanceConn = nil end;

		restoreKorblox();
		restoreHeadless();
		clear();
		for _, source in pairs(cache) do pcall(function() source:Destroy() end) end;
		table.clear(cache);
	end);
end);
guard("chinahat", function()
	LPH_ATTRIBUTES(VM(NONE));
	local lp = LocalPlayer;

	local ch_on = false
	local ch_col = Color3.fromRGB(170, 85, 255)

	local CH_RADIUS, CH_HEIGHT, CH_DROP = 1.55, 0.82, 0.02
	local CH_SEGMENTS = 48
	local CH_TAU = math.pi * 2
	local CH_ALPHA = 0.72
	local CH_MAX_ROWS = 220

	local ch = {
		rows = {},
		px = table.create(CH_SEGMENTS + 1),
		py = table.create(CH_SEGMENTS + 1),
		cos = table.create(CH_SEGMENTS),
		sin = table.create(CH_SEGMENTS),
		ord = table.create(CH_SEGMENTS + 1),
		stack = table.create(CH_SEGMENTS + 2),
		shown = {},
		cpos = {},
		csize = {},
		ccol = {},
		white = Color3.new(1, 1, 1),
		black = Color3.new(0, 0, 0),
		eps = 0.75
	}

	for i = 1, CH_SEGMENTS do
		local angle = (i - 1) / CH_SEGMENTS * CH_TAU
		ch.cos[i] = math.cos(angle) * CH_RADIUS
		ch.sin[i] = math.sin(angle) * CH_RADIUS
	end

	ch.order = function(i, j)
		local px, py = ch.px, ch.py
		local ax, bx = px[i], px[j]
		return ax == bx and py[i] < py[j] or ax < bx
	end

	ch.hull = function(n)
		local px, py, ord, st = ch.px, ch.py, ch.ord, ch.stack
		for i = 1, n do ord[i] = i end
		table.sort(ord, ch.order)
		local m = 0
		for k = 1, n do
			local i = ord[k]
			local x, y = px[i], py[i]
			while m >= 2 do
				local o, a = st[m - 1], st[m]
				local ox, oy = px[o], py[o]
				if (px[a] - ox) * (y - oy) - (py[a] - oy) * (x - ox) > 0 then break end
				m = m - 1
			end
			m = m + 1
			st[m] = i
		end
		local lower = m
		for k = n - 1, 1, -1 do
			local i = ord[k]
			local x, y = px[i], py[i]
			while m > lower do
				local o, a = st[m - 1], st[m]
				local ox, oy = px[o], py[o]
				if (px[a] - ox) * (y - oy) - (py[a] - oy) * (x - ox) > 0 then break end
				m = m - 1
			end
			m = m + 1
			st[m] = i
		end
		return m - 1
	end

	ch.visible = function(state)
		local rows, shown = ch.rows, ch.shown
		for i = 1, #rows do
			if shown[i] ~= state then
				rows[i].Visible = state
				shown[i] = state
			end
		end
	end

	ch.clear = function()
		local rows = ch.rows
		for i = 1, #rows do
			destroyAny(rows[i])
		end
		table.clear(rows)
		table.clear(ch.shown)
		table.clear(ch.cpos)
		table.clear(ch.csize)
		table.clear(ch.ccol)
		ch.head, ch.pos, ch.cf = nil, nil, nil
		ch.fov, ch.vx, ch.vy, ch.col = nil, nil, nil, nil
	end

	ch.build = function()
		ch.clear()
	end

	ch.row = function(index)
		local rows = ch.rows
		local row = rows[index]
		if row then return row end
		row = drawNew("Square")
		row.Filled = true
		row.Thickness = 0
		row.Transparency = CH_ALPHA
		row.Visible = false
		row.ZIndex = 1
		rows[index] = row
		ch.shown[index] = false
		return row
	end

	ch.update = function(camera)
		local char = lp.Character
		local head = char and char:FindFirstChild("Head")
		if not head or not head:IsA("BasePart") or not camera then
			ch.visible(false)
			return
		end
		local headPos = head.Position
		local camCF = camera.CFrame
		local fov = camera.FieldOfView
		local view = camera.ViewportSize
		local viewX, viewY = view.X, view.Y
		if ch.head == head and ch.pos == headPos and ch.cf == camCF
			and ch.headSize == head.Size and ch.fov == fov and ch.vx == viewX and ch.vy == viewY and ch.col == ch_col then
			return
		end
		ch.head, ch.pos, ch.cf = head, headPos, camCF
		ch.headSize = head.Size
		ch.fov, ch.vx, ch.vy, ch.col = fov, viewX, viewY, ch_col
		local px, py, cosT, sinT = ch.px, ch.py, ch.cos, ch.sin
		local baseY = headPos.Y + head.Size.Y * 0.5 - CH_DROP
		local center = Vector3.new(headPos.X, baseY, headPos.Z)
		local apex = camera:WorldToViewportPoint(center + Vector3.new(0, CH_HEIGHT, 0))
		if apex.Z <= 0 then
			ch.visible(false)
			return
		end
		local probe = camera:WorldToViewportPoint(center + Vector3.new(cosT[1], 0, sinT[1]))
		if probe.Z <= 0 then
			ch.visible(false)
			return
		end
		px[1], py[1] = apex.X, apex.Y
		px[2], py[2] = probe.X, probe.Y
		local camPos = camCF.Position
		local rv, uv, lv = camCF.RightVector, camCF.UpVector, camCF.LookVector
		local ox, oy, oz = center.X - camPos.X, center.Y - camPos.Y, center.Z - camPos.Z
		local baseR = ox * rv.X + oy * rv.Y + oz * rv.Z
		local baseU = ox * uv.X + oy * uv.Y + oz * uv.Z
		local baseD = ox * lv.X + oy * lv.Y + oz * lv.Z
		local rvx, rvz, uvx, uvz, lvx, lvz = rv.X, rv.Z, uv.X, uv.Z, lv.X, lv.Z
		local scale = viewY * 0.5 / math.tan(math.rad(fov * 0.5))
		local midX, midY = viewX * 0.5, viewY * 0.5
		local eps = ch.eps
		local exact = false
		local dep = baseD + CH_HEIGHT * lv.Y
		if dep > 0 then
			local inv = scale / dep
			if math.abs(midX + (baseR + CH_HEIGHT * rv.Y) * inv - apex.X) <= eps
				and math.abs(midY - (baseU + CH_HEIGHT * uv.Y) * inv - apex.Y) <= eps then
				local c, s = cosT[1], sinT[1]
				dep = baseD + c * lvx + s * lvz
				if dep > 0 then
					inv = scale / dep
					if math.abs(midX + (baseR + c * rvx + s * rvz) * inv - probe.X) <= eps
						and math.abs(midY - (baseU + c * uvx + s * uvz) * inv - probe.Y) <= eps then
						exact = true
					end
				end
			end
		end
		if exact then
			for i = 2, CH_SEGMENTS do
				local c, s = cosT[i], sinT[i]
				local d = baseD + c * lvx + s * lvz
				if d <= 0 then
					ch.visible(false)
					return
				end
				local inv = scale / d
				px[i + 1] = midX + (baseR + c * rvx + s * rvz) * inv
				py[i + 1] = midY - (baseU + c * uvx + s * uvz) * inv
			end
		else
			for i = 2, CH_SEGMENTS do
				local point = camera:WorldToViewportPoint(center + Vector3.new(cosT[i], 0, sinT[i]))
				if point.Z <= 0 then
					ch.visible(false)
					return
				end
				px[i + 1] = point.X
				py[i + 1] = point.Y
			end
		end
		local hn = ch.hull(CH_SEGMENTS + 1)
		if hn < 3 then
			ch.visible(false)
			return
		end
		local st = ch.stack
		local minY, maxY = math.huge, -math.huge
		for i = 1, hn do
			local y = py[st[i]]
			if y < minY then minY = y end
			if y > maxY then maxY = y end
		end
		local firstY = math.max(0, math.floor(minY))
		local lastY = math.min(viewY, math.ceil(maxY))
		if lastY - firstY < 2 then
			ch.visible(false)
			return
		end
		local step = math.max(1, math.ceil((lastY - firstY) / CH_MAX_ROWS))
		local span = math.max(1, maxY - minY)
		local rows, shown = ch.rows, ch.shown
		local cpos, csize, ccol = ch.cpos, ch.csize, ch.ccol
		local white, black = ch.white, ch.black
		local used = 0
		for y0 = firstY, lastY - 1, step do
			local height = math.min(step, lastY - y0)
			local y = y0 + height * 0.5
			local left, right = math.huge, -math.huge
			local ax, ay = px[st[hn]], py[st[hn]]
			for i = 1, hn do
				local ix = st[i]
				local bx, by = px[ix], py[ix]
				if (ay <= y and by > y) or (by <= y and ay > y) then
					local x = ax + (y - ay) * (bx - ax) / (by - ay)
					if x < left then left = x end
					if x > right then right = x end
				end
				ax, ay = bx, by
			end
			local width = right - left
			if width >= 2.5 then
				used = used + 1
				local row = ch.row(used)
				local t = (y - minY) / span
				local light = 1 - t * 1.35
				local dark = (t - 0.58) / 0.42
				if light < 0 then light = 0 end
				if dark < 0 then dark = 0 end
				local color = ch_col:Lerp(white, light * 0.26):Lerp(black, dark * 0.1)
				local pos = Vector2.new(left, y0)
				local size = Vector2.new(width, height)
				if cpos[used] ~= pos then
					row.Position = pos
					cpos[used] = pos
				end
				if csize[used] ~= size then
					row.Size = size
					csize[used] = size
				end
				if ccol[used] ~= color then
					row.Color = color
					ccol[used] = color
				end
				if not shown[used] then
					row.Visible = true
					shown[used] = true
				end
			end
		end
		for i = used + 1, #rows do
			if shown[i] then
				rows[i].Visible = false
				shown[i] = false
			end
		end
	end

	SaladUI:AddSignal(RunService.RenderStepped:Connect(function()
		if not ch_on then return end

		ch.update(workspace.CurrentCamera)
	end));

	SaladUI:AddSignal(LocalPlayer.CharacterAdded:Connect(function()
		task.wait(0.4)

		if ALIVE and ch_on then ch.build() end
	end));

	local row = Sections.Extras:AddLabel("China Hat");

	row:AddToggle({
		Name = "China Hat",
		Default = false,
		Flag = "china_hat",
		Callback = function(v)
			ch_on = v

			if v then ch.build() else ch.clear() end
		end,
	});

	row:AddColorPicker({
		Default = ch_col,
		Flag = "china_hat_color",
		Callback = function(c) ch_col = c end,
	});

	ESP.ChinaHat = { On = function() return ch_on end };

	ESP.ClearChinaHat = onUnload("chinahat", function()
		ch_on = false

		pcall(ch.clear)
	end);
end);
guard("killfx", function()
	local TweenService = game:GetService("TweenService");

	local K = {
		Clone = false, CloneColor = Color3.fromRGB(255, 0, 0), CloneTime = 3,
		Emitter = false, EmitterColor = Color3.fromRGB(255, 100, 100), EmitterTime = 1.2,
		Target = "Other",
	};

	local clones = {};
	local active, activeCount = {}, 0;

	local function removeEffect(record)
		for i = 1, activeCount do
			if active[i] == record then
				active[i] = active[activeCount];
				active[activeCount] = nil;
				activeCount = activeCount - 1;
				break;
			end;
		end;

		if record.part and record.part.Parent then record.part:Destroy() end;
	end;

	local function spawnEmitter(character, tint, duration)
		if not (character and character.Parent) then return end;

		if activeCount >= 3 then
			removeEffect(active[1]);
		end;

		duration = math.max(duration, 0.2);

		local bodyParts = {};

		for _, source in ipairs(character:GetChildren()) do
			if source:IsA("BasePart") and source.Name ~= "HumanoidRootPart" and #bodyParts < 15 then
				bodyParts[#bodyParts + 1] = source;
			end;
		end;

		if #bodyParts == 0 then return end;

		local root = Instance.new("Folder");
		root.Name = SaladUI.RandomString();
		root:SetAttribute(TAG, INIT_GENERATION);
		root.Parent = workspace;

		local record = { part = root, balls = {} };
		activeCount = activeCount + 1;
		active[activeCount] = record;

		local random = math.random;
		local goldenAngle = math.pi * (3 - math.sqrt(5));

		local function surfacePosition(source, radius, index, count, headSeed)
			local size = source.Size;
			local padding = radius * 0.92;

			if source.Name == "Head" then
				local y = 1 - 2 * ((index - 0.5) / count);
				local angle = index * goldenAngle + headSeed;
				local radial = math.sqrt(math.max(0, 1 - y * y));
				local dir = Vector3.new(radial * math.cos(angle), y, radial * math.sin(angle));
				local half = size * 0.5;

				return source.CFrame:PointToWorldSpace(Vector3.new(
					dir.X * (half.X + padding),
					dir.Y * (half.Y + padding),
					dir.Z * (half.Z + padding)
				));
			end;

			local areaX = size.Y * size.Z;
			local areaY = size.X * size.Z;
			local areaZ = size.X * size.Y;
			local pick = random() * (areaX + areaY + areaZ);
			local pos;

			if pick < areaX then
				local side = random() < 0.5 and -1 or 1;
				pos = Vector3.new(side * (size.X * 0.5 + padding), (random() - 0.5) * size.Y, (random() - 0.5) * size.Z);
			elseif pick < areaX + areaY then
				local side = random() < 0.5 and -1 or 1;
				pos = Vector3.new((random() - 0.5) * size.X, side * (size.Y * 0.5 + padding), (random() - 0.5) * size.Z);
			else
				local side = random() < 0.5 and -1 or 1;
				pos = Vector3.new((random() - 0.5) * size.X, (random() - 0.5) * size.Y, side * (size.Z * 0.5 + padding));
			end;

			return source.CFrame:PointToWorldSpace(pos);
		end;

		local minY, maxY = math.huge, -math.huge;

		for _, source in ipairs(bodyParts) do
			local halfY = source.Size.Y * 0.5;
			minY = math.min(minY, source.Position.Y - halfY);
			maxY = math.max(maxY, source.Position.Y + halfY);
		end;

		local phaseCount = 8;
		local groups = {};

		for i = 1, phaseCount do groups[i] = {} end;

		local headSeed = random() * math.pi * 2;
		local height = math.max(maxY - minY, 0.01);
		local created = 0;

		for _, source in ipairs(bodyParts) do
			local size = source.Size;
			local surface = 2 * (size.X * size.Y + size.X * size.Z + size.Y * size.Z);
			local count = source.Name == "Head" and 24 or math.clamp(math.floor(surface * 0.65 + 0.5), 7, 12);
			count = math.min(count, 140 - created);

			for index = 1, count do
				local diameter = source.Name == "Head" and (0.115 + random() * 0.045) or (0.13 + random() * 0.06);
				local targetSize = Vector3.new(diameter, diameter, diameter);
				local position = surfacePosition(source, diameter * 0.5, index, count, headSeed);

				local ball = Instance.new("Part");
				ball.Name = SaladUI.RandomString();
				ball.Shape = Enum.PartType.Ball;
				ball.Material = Enum.Material.Neon;
				ball.Color = tint;
				ball.Size = Vector3.new(0.015, 0.015, 0.015);
				ball.Position = position;
				ball.Anchored = true;
				ball.CanCollide = false;
				ball.CanQuery = false;
				ball.CanTouch = false;
				ball.CastShadow = false;
				ball.Massless = true;
				ball.Transparency = 1;
				ball.Parent = root;

				record.balls[#record.balls + 1] = ball;
				created = created + 1;

				local vertical = math.clamp((position.Y - minY) / height, 0, 1);
				local phase = math.clamp(math.floor(vertical * (phaseCount - 1) + 1.5) + random(-1, 1), 1, phaseCount);

				groups[phase][#groups[phase] + 1] = { ball = ball, size = targetSize };
			end;

			if created >= 140 then break end;
		end;

		local revealWindow = math.min(0.34, duration * 0.26);
		local revealTime = math.min(0.2, duration * 0.18);
		local fadeBegin = math.max(revealWindow + revealTime + 0.06, duration * 0.42);
		local fadeWindow = math.min(0.28, duration * 0.18);
		local fadeTime = math.max(duration - fadeBegin - fadeWindow, 0.1);

		for phase = 1, phaseCount do
			local alpha = (phase - 1) / (phaseCount - 1);
			local group = groups[phase];

			task.delay(revealWindow * alpha, function()
				if not root.Parent then return end;

				for _, item in ipairs(group) do
					if item.ball.Parent then
						TweenService:Create(item.ball, TweenInfo.new(revealTime, Enum.EasingStyle.Sine, Enum.EasingDirection.Out), {
							Size = item.size, Transparency = 0.05,
						}):Play();
					end;
				end;
			end);

			task.delay(fadeBegin + fadeWindow * alpha, function()
				if not root.Parent then return end;

				for _, item in ipairs(group) do
					if item.ball.Parent then
						TweenService:Create(item.ball, TweenInfo.new(fadeTime, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut), {
							Size = item.size * 0.58, Transparency = 1,
						}):Play();
					end;
				end;
			end);
		end;

		task.delay(duration + 0.12, function()
			removeEffect(record);
		end);
	end;

	local function fadeClone(clone, wait)
		task.delay(wait, function()
			if not clone.Parent then return end;

			for _, d in ipairs(clone:GetDescendants()) do
				if d:IsA("BasePart") and d.Name ~= "HumanoidRootPart" then
					pcall(function()
						TweenService:Create(d, TweenInfo.new(1.5, Enum.EasingStyle.Linear), { Transparency = 1 }):Play();
					end);
				end;
			end;

			task.delay(1.6, function()
				for i = #clones, 1, -1 do
					if clones[i] == clone then table.remove(clones, i) end;
				end;

				if clone.Parent then clone:Destroy() end;
			end);
		end);
	end;

	local function makeClone(character)

		local archivable = character.Archivable;

		if not archivable then
			pcall(function() character.Archivable = true end);
		end;

		local ok, clone = pcall(character.Clone, character);

		if not archivable then
			pcall(function() character.Archivable = archivable end);
		end;

		if not ok or not clone then return end;

		for _, d in ipairs(clone:GetDescendants()) do
			if d:IsA("BasePart") then
				d.Anchored = true;
				d.CanCollide = false;
				d.CanQuery = false;
				d.CanTouch = false;

				if d.Name == "HumanoidRootPart" then
					d.Transparency = 1;
				else
					d.Material = Enum.Material.ForceField;
					d.Color = K.CloneColor;
				end;
			elseif d:IsA("Humanoid") or d:IsA("AnimationController") or d:IsA("BaseScript") or d:IsA("ModuleScript") or d:IsA("Sound")
				or d:IsA("SurfaceAppearance") or d:IsA("ParticleEmitter") or d:IsA("Trail") or d:IsA("Beam")
				or d:IsA("Smoke") or d:IsA("Fire") or d:IsA("Sparkles") or d:IsA("Light") or d:IsA("Highlight")
				or d:IsA("JointInstance") or d:IsA("Constraint") or d:IsA("ProximityPrompt") or d:IsA("ClickDetector") then
				pcall(function() d:Destroy() end);
			end;
		end;

		local shell = Instance.new("Folder");
		shell.Name = SaladUI.RandomString();
		shell:SetAttribute(TAG, INIT_GENERATION);
		for _, child in ipairs(clone:GetChildren()) do child.Parent = shell end;
		clone:Destroy();
		clone = shell;
		clone.Parent = workspace;

		clones[#clones + 1] = clone;

		fadeClone(clone, K.CloneTime);
	end;

	local function wants(player)
		local isSelf = player == LocalPlayer;

		return K.Target == "All" or (isSelf and K.Target == "Self") or (not isSelf and K.Target == "Other");
	end;

	local function onDeath(character)
		if K.Clone then makeClone(character) end;
		if K.Emitter then spawnEmitter(character, K.EmitterColor, K.EmitterTime) end;
	end;

	local humanoidHooks = {};
	local watching, scanGeneration = false, 0;
	local function unhookHumanoid(human)
		local record = humanoidHooks[human];
		if not record then return end;
		humanoidHooks[human] = nil;
		for _, connection in ipairs(record) do connection:Disconnect() end;
	end;
	local function hookHumanoid(human)
		if not ALIVE or humanoidHooks[human] then return end;
		local character = human.Parent;
		if not character or not character:IsA("Model") then return end;
		local record = {};
		humanoidHooks[human] = record;
		local fired = false;
		local function died()
			if not ALIVE or fired or not (K.Clone or K.Emitter) then return end;
			fired = true;
			local player = Players:GetPlayerFromCharacter(character);
			if player and not wants(player) then return end;
			if not player and K.Target == "Self" then return end;
			onDeath(character);
		end;
		record[#record + 1] = human.Died:Connect(died);
		record[#record + 1] = human.HealthChanged:Connect(function(value)
			if value <= 0 then died() else fired = false end;
		end);
		record[#record + 1] = human.AncestryChanged:Connect(function(_, parent)
			if not parent then unhookHumanoid(human) end;
		end);
		record[#record + 1] = human.Destroying:Connect(function() unhookHumanoid(human) end);
	end;

	local function stopWatching()
		watching = false;
		scanGeneration += 1;
		for human in pairs(humanoidHooks) do unhookHumanoid(human) end;
	end;
	local function startWatching()
		if watching then return end;
		watching = true;
		scanGeneration += 1;
		local token = scanGeneration;
		for _, player in ipairs(Players:GetPlayers()) do
			local character = player.Character;
			local human = character and character:FindFirstChildOfClass("Humanoid");
			if human then hookHumanoid(human) end;
		end;
		scanDescendantsAsync("kill effects scan", workspace, function(inst)
			if inst:IsA("Humanoid") then hookHumanoid(inst) end;
		end, function()
			return watching and token == scanGeneration;
		end, 512);
	end;
	local function updateWatching()
		if K.Clone or K.Emitter then startWatching() else stopWatching() end;
	end;
	SaladUI:AddSignal(workspace.DescendantAdded:Connect(function(inst)
		if watching and inst:IsA("Humanoid") then hookHumanoid(inst) end;
	end));

	for _, leftover in ipairs(workspace:GetChildren()) do
		local owner = leftover:GetAttribute(TAG);
		if owner and owner ~= INIT_GENERATION and (leftover:IsA("Folder") or leftover:IsA("Model")) then
			leftover:Destroy();
		end;
	end;

	ESP.KillFx = K;

	ESP.ClearKillFx = onUnload("kill effects", function()
		K.Clone, K.Emitter = false, false;
		stopWatching();
		for i = activeCount, 1, -1 do
			if active[i] then pcall(function() active[i].part:Destroy() end) end;
			active[i] = nil;
		end;

		activeCount = 0;

		for _, clone in ipairs(clones) do pcall(function() clone:Destroy() end) end;

		clones = {};
	end);

	local cloneRow = Sections.KillFx:AddLabel("Ghost");
	cloneRow:AddToggle({ Default = false, Flag = "killfx_clone", Callback = function(v) K.Clone = v; updateWatching() end });
	cloneRow:AddColorPicker({ Default = K.CloneColor, Flag = "killfx_clone_color", Callback = function(v) K.CloneColor = v end });
	cloneRow:AddOption(1):AddLabel("Duration"):AddSlider({
		Min = 1, Max = 100, Default = 30, Rounding = 0, Size = 90,
		Flag = "killfx_clone_time",
		Callback = function(v) K.CloneTime = v / 10 end,
	});

	local emitterRow = Sections.KillFx:AddLabel("Neon Burst");
	emitterRow:AddToggle({ Default = false, Flag = "killfx_emitter", Callback = function(v) K.Emitter = v; updateWatching() end });
	emitterRow:AddColorPicker({ Default = K.EmitterColor, Flag = "killfx_emitter_color", Callback = function(v) K.EmitterColor = v end });
	emitterRow:AddOption(1):AddLabel("Length"):AddSlider({
		Min = 4, Max = 60, Default = 12, Rounding = 0, Size = 90,
		Flag = "killfx_emitter_time",
		Callback = function(v) K.EmitterTime = v / 10 end,
	});

	Sections.KillFx:AddLabel("Target"):AddDropdown({
		Default = "Other",
		Values = { "Other", "Self", "All" },
		Flag = "killfx_target",
		Callback = function(v) K.Target = v end,
	});
end);
guard("character", function()
	local STORE = userFile("accessories.json");
	local HttpService = game:GetService("HttpService");
	local A = { On = false, Type = "Auto", Items = {}, Order = {}, Enabled = {}, Error = nil };
	ESP.CharacterAccessories = A;
	local cache, loading, pending, worn, connections = {}, {}, {}, {}, {};
	local accessoryGeometry = {};
	local settingsSaveToken, settingsDirty = 0, false;
	local generation, grid, activeLoads = 0, nil, 0;
	local characterConnections, departing, repairQueued = {}, nil, false;
	local TYPES, VALID_TYPES = { "Auto" }, { Auto = true };
	for _, kind in ipairs(Enum.AccessoryType:GetEnumItems()) do
		if kind ~= Enum.AccessoryType.Unknown and kind.Name ~= "Eyebrow" and kind.Name ~= "Eyelash" then
			TYPES[#TYPES + 1] = kind.Name; VALID_TYPES[kind.Name] = true;
		end;
	end;
	local function notify(message)
		A.Error = message;
		Notification.new({ Title = "Character", Content = message, Duration = 5 });
	end;
	local function parseId(value)
		local text = tostring(value or "");
		local digits = text:match("^%s*(%d+)%s*$") or text:match("/catalog/(%d+)") or text:match("/library/(%d+)") or text:match("rbxassetid://(%d+)");
		local number = digits and tonumber(digits);
		if not number or number < 1 or number >= 2 ^ 53 or number % 1 ~= 0 then return nil end;
		return string.format("%.0f", number);
	end;
	local function keyFor(id, kind) return id .. ":" .. kind end;
	local function transformNumber(value, default, minimum, maximum)
		value = tonumber(value);
		if not value or value ~= value or value == math.huge or value == -math.huge then return default end;
		return math.clamp(value, minimum, maximum);
	end;
	local function accessorySettings(item)
		return {
			Size = transformNumber(item.Size, 1, 0.25, 2.5),
			X = transformNumber(item.X, 0, -5, 5),
			Y = transformNumber(item.Y, 0, -5, 5),
			Z = transformNumber(item.Z, 0, -5, 5),
		};
	end;
	local function destroyWorn(key)
		local copy = worn[key];
		worn[key] = nil;
		accessoryGeometry[key] = nil;
		if copy then pcall(function() copy:Destroy() end) end;
	end;
	local function rows()
		local out = {};
		for _, key in ipairs(A.Order) do
			local item = A.Items[key];
			if item then out[#out + 1] = { name = key, label = item.Name .. " [" .. item.Kind .. "]", id = tonumber(item.Id) } end;
		end;
		return out;
	end;
	local function selected()
		local out = {};
		for _, key in ipairs(A.Order) do if A.Enabled[key] then out[#out + 1] = key end end;
		return out;
	end;
	local function save()
		if not writefile then return end;
		local items = {};
		for _, key in ipairs(A.Order) do
			local item = A.Items[key];
			if item then
				local settings = accessorySettings(item);
				items[#items + 1] = { id = item.Id, kind = item.Kind, name = item.Name,
					size = settings.Size, x = settings.X, y = settings.Y, z = settings.Z };
			end;
		end;
		local ok, json = pcall(HttpService.JSONEncode, HttpService, { version = 2, items = items });
		if ok then pcall(writefile, STORE, json) end;
	end;
	local function flushAccessorySettings()
		if settingsDirty then settingsDirty = false; save() end;
	end;
	local function queueAccessorySave()
		settingsDirty = true;
		settingsSaveToken += 1;
		local token = settingsSaveToken;
		task.delay(0.45, function()
			if ALIVE and token == settingsSaveToken then flushAccessorySettings() end;
		end);
	end;
	local function loadTemplate(id)
		if cache[id] then return cache[id] end;
		if loading[id] then
			local deadline = os.clock() + 15;
			repeat task.wait(0.05) until not loading[id] or not ALIVE or os.clock() >= deadline;
			return cache[id];
		end;
		loading[id] = true;
		local deadline = os.clock() + 15;
		while Remote.current() and activeLoads >= 4 and os.clock() < deadline do task.wait(0.05) end;
		if not Remote.current() or activeLoads >= 4 then loading[id] = nil; return nil end;
		activeLoads += 1;
		local roots, temporary = {}, nil;
		local completed, result = pcall(function()
		local ok, objects = Remote.objects(function() return game:GetObjects("rbxassetid://" .. id) end);
		if not ok or type(objects) ~= "table" or not objects[1] then
			ok, objects = Remote.objects(function() return { game:GetService("InsertService"):LoadAsset(tonumber(id)) } end);
			objects = ok and type(objects) == "table" and objects or {};
		end;
		roots = objects;
		local found;
		for _, object in ipairs(objects) do
			if object:IsA("Accessory") or object:IsA("Hat") then found = found or object end;
			if not found then
				for _, obj in ipairs(object:GetDescendants()) do
					if obj:IsA("Accessory") or obj:IsA("Hat") then found = obj; break end;
				end;
			end;
		end;
		local template;
		if ALIVE and found and #found:GetDescendants() <= 256 then
			found.Archivable = true;
			for _, obj in ipairs(found:GetDescendants()) do obj.Archivable = true end;
			template = found:Clone();
			temporary = template;
		end;
		for _, object in ipairs(objects) do pcall(function() object:Destroy() end) end;
		if template and template:IsA("Hat") then
			local holder = Instance.new("Accessory");
			holder.Name, holder.AttachmentPoint = template.Name, template.AttachmentPoint;
			for _, child in ipairs(template:GetChildren()) do child.Parent = holder end;
			template:Destroy(); template = holder; temporary = holder;
		end;
		local handle = template and template:FindFirstChild("Handle");
		if not (ALIVE and handle and handle:IsA("BasePart")) then
			if template then template:Destroy() end;
			loading[id] = nil;
			return nil;
		end;
		for _, obj in ipairs(template:GetDescendants()) do
			if obj:IsA("LuaSourceContainer") or obj:IsA("Sound") or obj:IsA("BodyMover")
				or obj:IsA("ParticleEmitter") or obj:IsA("Beam") or obj:IsA("Trail")
				or (obj:IsA("JointInstance") and obj.Name == "AccessoryWeld") then
				obj:Destroy();
			elseif obj:IsA("BasePart") then
				obj.Anchored, obj.CanCollide, obj.CanTouch, obj.CanQuery = false, false, false, false;
				obj.Massless = true;
			end;
		end;
		if not ALIVE then template:Destroy(); loading[id] = nil; return nil end;
		cache[id], loading[id] = template, nil;
		return template;
		end);
		activeLoads -= 1;
		loading[id] = nil;
		if not completed then
			for _, root in ipairs(roots) do pcall(function() root:Destroy() end) end;
			if temporary then pcall(function() temporary:Destroy() end) end;
			return nil;
		end;
		return result;
	end;
	local ATTACHMENTS = {
		Hat = "HatAttachment", Hair = "HairAttachment", Face = "FaceFrontAttachment",
		Neck = "NeckAttachment", Shoulder = "RightShoulderAttachment",
		Front = "BodyFrontAttachment", Back = "BodyBackAttachment", Waist = "WaistCenterAttachment",
	};
	local function targetAttachment(character, name)
		if not name then return nil end;
		for _, part in ipairs(character:GetChildren()) do
			if part:IsA("BasePart") then
				local attachment = part:FindFirstChild(name);
				if attachment and attachment:IsA("Attachment") then return attachment end;
			end;
		end;
	end;
	local function scaledAccessoryFrame(cf, scale)
		return CFrame.new(cf.Position * scale) * (cf - cf.Position);
	end;
	local function captureAccessoryGeometry(copy)
		local handle = copy:FindFirstChild("Handle");
		local weld = handle and handle:FindFirstChild("VisualsAccessoryWeld");
		if not handle or not weld then return nil end;
		local geometry = { Copy = copy, Handle = handle, Weld = weld, C0 = weld.C0, C1 = weld.C1,
			Parts = {}, Meshes = {}, Attachments = {}, Joints = {} };
		for _, object in ipairs(copy:GetDescendants()) do
			if object:IsA("BasePart") then
				geometry.Parts[object] = { Size = object.Size, Relative = handle.CFrame:ToObjectSpace(object.CFrame) };
			elseif object:IsA("DataModelMesh") then

				local fileMesh = object:IsA("FileMesh") and (not object:IsA("SpecialMesh") or object.MeshType == Enum.MeshType.FileMesh);
				geometry.Meshes[object] = { Scale = object.Scale, Offset = object.Offset, File = fileMesh };
			elseif object:IsA("Attachment") then
				geometry.Attachments[object] = object.CFrame;
			elseif object ~= weld and object:IsA("JointInstance") and object.Part0 and object.Part1
				and object.Part0:IsDescendantOf(copy) and object.Part1:IsDescendantOf(copy) then
				geometry.Joints[object] = { C0 = object.C0, C1 = object.C1 };
			end;
		end;
		return geometry;
	end;
	local function applyAccessoryTransform(key)
		local item, geometry = A.Items[key], accessoryGeometry[key];
		if not item or not geometry or worn[key] ~= geometry.Copy or not geometry.Copy.Parent then return end;
		local settings = accessorySettings(item);
		local scale = settings.Size;
		local weld = geometry.Weld;
		if not weld.Parent or not weld.Part0 or not weld.Part0.Parent then return end;
		local c0 = CFrame.new(settings.X, settings.Y, settings.Z) * geometry.C0;
		local c1 = scaledAccessoryFrame(geometry.C1, scale);
		local anchor = weld.Part0;
		local handleFrame = anchor.CFrame * c0 * c1:Inverse();

		weld.Part0 = nil;
		local ok, err = pcall(function()
		for part, base in pairs(geometry.Parts) do
			if part.Parent then
				part.Size = base.Size * scale;
				part.CFrame = handleFrame * scaledAccessoryFrame(base.Relative, scale);
			end;
		end;
		for mesh, base in pairs(geometry.Meshes) do
			if mesh.Parent then mesh.Scale = base.Scale * (base.File and scale or 1); mesh.Offset = base.Offset * scale end;
		end;
		for attachment, base in pairs(geometry.Attachments) do
			if attachment.Parent then attachment.CFrame = scaledAccessoryFrame(base, scale) end;
		end;
		for joint, base in pairs(geometry.Joints) do
			if joint.Parent then joint.C0 = scaledAccessoryFrame(base.C0, scale); joint.C1 = scaledAccessoryFrame(base.C1, scale) end;
		end;
		weld.C0, weld.C1 = c0, c1;
		geometry.Handle.CFrame = handleFrame;
		end);
		weld.Part0 = anchor;
		if not ok then error(err) end;
	end;
	local function setAccessoryTransform(key, field, value)
		local item = A.Items[key];
		if not ALIVE or not item or (field ~= "Size" and field ~= "X" and field ~= "Y" and field ~= "Z") then return false end;
		value = tonumber(value);
		if not value or value ~= value or value == math.huge or value == -math.huge then return false end;
		value = math.clamp(value, field == "Size" and 0.25 or -5, field == "Size" and 2.5 or 5);
		if accessorySettings(item)[field] == value then return true end;
		item[field] = value;
		local ok, err = pcall(applyAccessoryTransform, key);
		if not ok then recordError("accessory transform: " .. tostring(err)) end;
		queueAccessorySave();
		return ok;
	end;
	A.SetTransform = setAccessoryTransform;
	local function attachCopy(template, item, character, human, track)
		local copy = template:Clone();
		track(copy);
		copy:SetAttribute("VisualsCharacterAccessory", true);
		copy:SetAttribute("VisualsAccessoryKey", keyFor(item.Id, item.Kind));
		copy:SetAttribute(TAG, INIT_GENERATION);
		local handle = copy:FindFirstChild("Handle");
		if not handle then copy:Destroy(); return nil end;
		if item.Kind ~= "Auto" then pcall(function() copy.AccessoryType = Enum.AccessoryType[item.Kind] end) end;
		local source, target;
		local preferred = ATTACHMENTS[item.Kind];
		if preferred then
			source = handle:FindFirstChild(preferred);
			target = targetAttachment(character, preferred);
		end;
		for _, attachment in ipairs(handle:GetChildren()) do
			if attachment:IsA("Attachment") then
				source = source or attachment;
				if item.Kind == "Auto" then
					local matching = targetAttachment(character, attachment.Name);
					if matching then source, target = attachment, matching; break end;
				end;
			end;
		end;
		local added = pcall(function() human:AddAccessory(copy) end);
		if not added or copy.Parent ~= character then copy.Parent = character end;
		local part, c0;
		if target then part, c0 = target.Parent, target.CFrame
		else
			local head = character:FindFirstChild("Head");
			local torso = character:FindFirstChild("UpperTorso") or character:FindFirstChild("Torso") or character:FindFirstChild("HumanoidRootPart");
			local kind = item.Kind;
			if kind == "Auto" and source then
				local name = source.Name;
				if name:find("Waist") then kind = "Waist"
				elseif name:find("Back") then kind = "Back"
				elseif name:find("Front") and not name:find("Face") then kind = "Front"
				elseif name:find("Shoulder") then kind = "Shoulder"
				elseif name:find("Neck") then kind = "Neck" end;
			end;
			local body = kind == "Waist" or kind == "Front" or kind == "Back" or kind == "Shoulder" or kind == "Neck";
			part = body and torso or head or torso;
			if not part then copy:Destroy(); return nil end;
			local offset = Vector3.new(0, part.Size.Y * 0.5, 0);
			if kind == "Waist" then offset = Vector3.new(0, -part.Size.Y * 0.4, 0)
			elseif kind == "Front" then offset = Vector3.new(0, 0, -part.Size.Z * 0.5)
			elseif kind == "Back" then offset = Vector3.new(0, 0, part.Size.Z * 0.5)
			elseif kind == "Shoulder" then
				local side = source and source.Name:find("Left") and -1 or 1;
				offset = Vector3.new(side * part.Size.X * 0.5, part.Size.Y * 0.4, 0)
			elseif kind == "Face" then offset = Vector3.new(0, 0, -part.Size.Z * 0.5) end;
			c0 = CFrame.new(offset);
		end;
		if not part:IsA("BasePart") then copy:Destroy(); return nil end;
		for _, weld in ipairs(handle:GetChildren()) do
			if weld:IsA("JointInstance") and (weld.Name == "AccessoryWeld" or weld.Name == "VisualsAccessoryWeld") then weld:Destroy() end;
		end;
		local c1 = source and source.CFrame or copy.AttachmentPoint;
		handle.CFrame = part.CFrame * c0 * c1:Inverse();
		local weld = Instance.new("Weld");
		weld.Name, weld.Part0, weld.Part1, weld.C0, weld.C1 = "VisualsAccessoryWeld", part, handle, c0, c1;
		weld.Parent = handle;
		return copy;
	end;
	local function reconcile()
		generation += 1;
		A.On = next(A.Enabled) ~= nil;
		local token = generation;
		local character = LocalPlayer.Character;
		local human = character and character:FindFirstChildOfClass("Humanoid");
		for key, copy in pairs(worn) do
			if not A.On or not A.Enabled[key] or not copy.Parent or copy.Parent ~= character then destroyWorn(key) end;
		end;
		if not (ALIVE and A.On and character and character ~= departing and character.Parent and human) then return end;
		for _, key in ipairs(A.Order) do
			local item = A.Items[key];
			if item and A.Enabled[key] and not worn[key] then
				task.spawn(function()
					local template = loadTemplate(item.Id);
					if not ALIVE or token ~= generation or not A.On or not A.Enabled[key] or not A.Items[key]
						or LocalPlayer.Character ~= character or not character.Parent or not human.Parent or worn[key] then return end;
					if not template then notify("Load failed"); return end;
					local created;
					local ok, copy = pcall(attachCopy, template, item, character, human, function(c) created = c end);
					if ok and copy then
						worn[key] = copy;
						local transformed, transformError = pcall(function()
							accessoryGeometry[key] = captureAccessoryGeometry(copy);
							applyAccessoryTransform(key);
						end);
						if not transformed then recordError("accessory transform: " .. tostring(transformError)) end;
						A.Error = nil;
					else
						if created then pcall(function() created:Destroy() end) end;
						notify("Attach failed");
					end;
				end);
			end;
		end;
	end;
	local function choose(values)
		A.Enabled = {};
		for _, key in ipairs(type(values) == "table" and values or {}) do
			if A.Items[key] then A.Enabled[key] = true end;
		end;
		reconcile();
	end;
	local function refresh()
		if grid then grid:setdata(rows()); grid:set(selected()) end;
	end;
	function A.ImportConfig(selection, catalog)
		local imported, changed = {}, false;
		if type(catalog) == "string" and #catalog <= 65536 then
			local ok, saved = pcall(HttpService.JSONDecode, HttpService, catalog);
			if ok and type(saved) == "table" then
				for index, item in ipairs(saved) do
					if index > 128 then break end;
					if type(item) == "table" then
						local id, kind = parseId(item.Id), item.Kind;
						if id and VALID_TYPES[kind] then imported[keyFor(id, kind)] = item end;
					end;
				end;
			end;
		end;
		if type(selection) == "string" then
			local count = 0;
			for part in selection:gmatch("[^,]+") do
				count += 1; if count > 128 then break end;
				local id, kind = part:match("^%s*(%d+):([%w]+)%s*$");
				id = id and parseId(id);
				if id and VALID_TYPES[kind] then
					local key = keyFor(id, kind);
					imported[key] = imported[key] or { Id = id, Kind = kind };
				end;
			end;
		end;
		for key, item in pairs(imported) do
			local existing = A.Items[key];
			local settings = accessorySettings(item);
			local name = tostring(item.Name or ("Accessory " .. item.Id)):gsub("[%c|]", " "):sub(1, 100);
			if not existing then
				A.Items[key] = { Id = parseId(item.Id), Kind = item.Kind, Name = name,
					Size = settings.Size, X = settings.X, Y = settings.Y, Z = settings.Z };
				A.Order[#A.Order + 1] = key;
				changed = true;
			elseif item.Size ~= nil then
				existing.Size, existing.X, existing.Y, existing.Z = settings.Size, settings.X, settings.Y, settings.Z;
				applyAccessoryTransform(key); changed = true;
			end;
		end;
		if changed then save(); refresh() end;
	end;
	SaladUI.Lib:hook("character_accessory_catalog", "string", function()
		local items = {};
		for _, key in ipairs(A.Order) do
			if #items >= 128 then break end;
			local item = A.Items[key];
			if item then
				local settings = accessorySettings(item);
				items[#items + 1] = { Id = item.Id, Kind = item.Kind, Name = item.Name,
					Size = settings.Size, X = settings.X, Y = settings.Y, Z = settings.Z };
			end;
		end;
		return HttpService:JSONEncode(items);
	end, function(value) A.ImportConfig(nil, value) end);
	local function addById(value, kind)
		local id = parseId(value);
		kind = kind or A.Type;
		if not id or not VALID_TYPES[kind] then notify("Invalid ID"); return false end;
		local key = keyFor(id, kind);
		if A.Items[key] then A.Enabled[key] = true; refresh(); reconcile(); return true end;
		if pending[key] then return false end;
		pending[key] = true;
		task.spawn(function()
			local template = loadTemplate(id);
			pending[key] = nil;
			if not ALIVE then return end;
			if not template then notify("Not an accessory"); return end;
			local name = tostring(template.Name):gsub("[%c|]", " "):sub(1, 100);
			if name == "" then name = "Accessory " .. id end;
			if not A.Items[key] then
				A.Items[key] = { Id = id, Kind = kind, Name = name };
				A.Order[#A.Order + 1] = key;
			end;
			A.Enabled[key], A.Error = true, nil;
			save(); refresh(); reconcile();
		end);
		return true;
	end;
	local function removeSelected()
		local any = false;
		for index = #A.Order, 1, -1 do
			local key = A.Order[index];
			if A.Enabled[key] then
				any = true; A.Items[key], A.Enabled[key] = nil, nil;
				destroyWorn(key); table.remove(A.Order, index);
			end;
		end;
		if any then
			save(); refresh(); reconcile();
			for id, template in pairs(cache) do
				local used = false;
				for _, item in pairs(A.Items) do if item.Id == id then used = true; break end end;
				if not used and not loading[id] then template:Destroy(); cache[id] = nil end;
			end;
		end;
		return any;
	end;
	A.Add, A.RemoveSelected, A.Refresh = addById, removeSelected, refresh;
	if isfile and readfile and isfile(STORE) then
		local ok, data = pcall(function() return HttpService:JSONDecode(readfile(STORE)) end);
		if ok and type(data) == "table" and type(data.items) == "table" then
			for _, saved in ipairs(data.items) do
				if type(saved) == "table" then
					local id, kind = parseId(saved.id), saved.kind;
					if id and VALID_TYPES[kind] then
						local key = keyFor(id, kind);
						if not A.Items[key] then
							A.Items[key] = { Id = id, Kind = kind, Name = tostring(saved.name or ("Accessory " .. id)):gsub("[%c|]", " "):sub(1, 100),
								Size = transformNumber(saved.size, 1, 0.25, 2.5),
								X = transformNumber(saved.x, 0, -5, 5), Y = transformNumber(saved.y, 0, -5, 5), Z = transformNumber(saved.z, 0, -5, 5) };
							A.Order[#A.Order + 1] = key;
						end;
					end;
				end;
			end;
		end;
	end;
	local accessories = FBSplit(Sections.Character);
	accessories:AddLabel("Accessories");
	accessories:AddLabel("Accessory Type"):AddDropdown({
		Default = "Auto", Values = TYPES, FullWidth = true, Flag = "character_accessory_type", Callback = function(v) A.Type = v end,
	});
	accessories:AddButton({ Name = "Add by ID", Callback = function()
		local kind = A.Type;
		SaladUI.Lib:ask({
			title = "add accessory — " .. kind, icon = "plus", hint = "accessory ID or catalog link",
			accept = "add", deny = "cancel", callback = function(text) addById(text, kind) end,
		});
	end });
	accessories:AddButton({ Name = "Remove Selected", Callback = removeSelected });
	accessories:AddButton({ Name = "Unequip All", Callback = function()
		A.Enabled = {}; refresh(); reconcile();
	end });
	local function showAccessoryMenu(key, _, x, y, cell)
		local item = A.Items[key];
		if not ALIVE or not item then return end;
		if typeof(cell) == "Instance" and cell:IsA("GuiObject") then
			local position, size = cell.AbsolutePosition, cell.AbsoluteSize;
			x, y = position.X + size.X - 8, position.Y + 20;
		end;
		local settings = accessorySettings(item);
		local sliders = {{ name = "Size", min = 25, max = 250, value = math.floor(settings.Size * 100 + 0.5), suffix = "%",
			callback = function(value) setAccessoryTransform(key, "Size", value / 100) end }};
		for _, axis in ipairs({ "X", "Y", "Z" }) do
			local field = axis;
			sliders[#sliders + 1] = { name = field, min = -5, max = 5, step = 0.1, precision = 1,
				value = settings[field], suffix = "", callback = function(value) setAccessoryTransform(key, field, value) end };
		end;
		local ok, err = pcall(function()
			SaladUI.Lib:popup({ name = "VisualsAccessoryOptions", title = item.Name, icon = "shirt",
				x = x, y = y, follow = cell, width = 194, sliders = sliders });
		end);
		if not ok then recordError("accessory options: " .. tostring(err)) end;
	end;
	grid = Visuals.Character:AddGallery({
		Name = "Character", Icon = "shirt", Position = "left", Height = 320, Cell = 78,
		Thumb = "Asset", Blank = "shirt", Empty = "Add an accessory by ID", Values = rows(), Reset = true, Smooth = true,
		Multi = true, Flag = "character_accessory_pick", Callback = choose,
		Action = { Icon = "ellipsis", Callback = showAccessoryMenu },
	});

	local function watchCharacter(character)
		for _, conn in ipairs(characterConnections) do conn:Disconnect() end;
		table.clear(characterConnections);
		departing = nil;
		if not character then return end;
		characterConnections[#characterConnections + 1] = character.ChildRemoved:Connect(function(copy)
			local key = copy:GetAttribute("VisualsAccessoryKey");
			if not ALIVE or not key or not A.Enabled[key] or departing == character or repairQueued then return end;
			repairQueued = true;
			task.defer(function()
				repairQueued = false;
				if ALIVE and LocalPlayer.Character == character and departing ~= character then reconcile() end;
			end);
		end);
		characterConnections[#characterConnections + 1] = character.ChildAdded:Connect(function(obj)
			if obj:IsA("Humanoid") and ALIVE and LocalPlayer.Character == character then reconcile() end;
		end);
		task.spawn(function()
			character:WaitForChild("Humanoid", 10);
			if ALIVE and LocalPlayer.Character == character then reconcile() end;
		end);
	end;
	watchCharacter(LocalPlayer.Character);
	connections[#connections + 1] = LocalPlayer.CharacterAdded:Connect(watchCharacter);
	connections[#connections + 1] = LocalPlayer.CharacterAppearanceLoaded:Connect(function(character)
		if ALIVE and LocalPlayer.Character == character then reconcile() end;
	end);
	connections[#connections + 1] = LocalPlayer.CharacterRemoving:Connect(function(character)
		departing = character;
		generation += 1;
		for key in pairs(worn) do destroyWorn(key) end;
	end);
	ESP.ClearCharacterAccessories = onUnload("character accessories", function()
		flushAccessorySettings(); settingsSaveToken += 1;
		A.On = false; generation += 1;
		for _, conn in ipairs(connections) do conn:Disconnect() end;
		for _, conn in ipairs(characterConnections) do conn:Disconnect() end;
		table.clear(connections);
		table.clear(characterConnections);
		for key in pairs(worn) do destroyWorn(key) end;
		table.clear(accessoryGeometry);
		for id, template in pairs(cache) do template:Destroy(); cache[id] = nil end;
		table.clear(pending);
	end);
end);
guard("bullet tracers", function()
	if not Sections.BulletTracer then return end;
	local ReplicatedStorage = game:GetService("ReplicatedStorage");
	local TweenService = game:GetService("TweenService");
	local Debris = game:GetService("Debris");

	local B = {
		On = false,
		Color = Color3.fromRGB(133, 220, 255),
		Duration = 1,
		Style = "Classic",
	};

	local TRACER_STYLES = {
		Classic = { fallback = "rbxassetid://12781800668", speed = 1.5, length = 2, width = 0.25, brightness = 2.5 },
		Bloom = { path = "trail/bloom.png", fallback = "rbxassetid://12781800668", speed = 1.2, length = 2.6, width = 0.3, brightness = 2.8 },
		Comet = { path = "particles/comet_bloom.png", fallback = "rbxassetid://12781800668", speed = 1.8, length = 2.4, width = 0.26, brightness = 3 },
		Lightning = { path = "particles/p_lightning.png", fallback = "rbxassetid://12781800668", speed = 2.6, length = 1.4, width = 0.18, brightness = 3.2 },
		Sparkle = { path = "particles/p_sparkle.png", fallback = "rbxassetid://12781800668", speed = 1.9, length = 1.8, width = 0.22, brightness = 2.7 },
		SoftGlow = { path = "particles/p_softglow.png", fallback = "rbxassetid://12781800668", speed = 1, length = 2.2, width = 0.34, brightness = 2.4 },
	};
	local tracerTextures = { Classic = TRACER_STYLES.Classic.fallback };

	local function warmTracerStyle(name)
		local style = TRACER_STYLES[name];
		if not style or not style.path or tracerTextures[name] then return end;
		task.spawn(function()
			local asset = Remote.asset(style.path);
			if ALIVE and type(asset) == "string" and asset ~= "" then tracerTextures[name] = asset end;
		end);
	end;

	local gunFiredConn, gunFiredRemote, roundClient;
	local live = {};

	local FADE = TweenInfo.new(0.2, Enum.EasingStyle.Linear, Enum.EasingDirection.Out);

	local function getRoundClient()
		local ok, module = pcall(function()
			return require(ReplicatedStorage:WaitForChild("Modules"):WaitForChild("CurrentRoundClient"));
		end);

		if ok then roundClient = module end;

		return roundClient;
	end;

	local function isLocalSheriff()
		local character = LocalPlayer.Character;

		if character and character:FindFirstChild("Gun") then return true end;

		local backpack = LocalPlayer:FindFirstChildOfClass("Backpack");

		if backpack and backpack:FindFirstChild("Gun") then return true end;

		local round = getRoundClient();

		if not round then return false end;

		local data = round.PlayerData;
		local mine = data and data[LocalPlayer.Name];

		return mine ~= nil and (mine.Role == "Sheriff" or mine.Role == "Hero");
	end;

	local function makePoint(position, lifetime)
		local part = Instance.new("Part");

		part.Name = SaladUI.RandomString();
		part.Transparency = 1;
		part.Anchored = true;
		part.CanCollide = false;
		part.CanQuery = false;
		part.Size = Vector3.new(1, 1, 1);
		part.CFrame = CFrame.new(position);

		local attachment = Instance.new("Attachment");

		attachment.Parent = part;

		Debris:AddItem(part, lifetime);

		part.Parent = workspace;
		live[part] = true;

		return part, attachment;
	end;

	local function toPosition(value)
		if typeof(value) == "Vector3" then
			return value;
		elseif typeof(value) == "CFrame" then
			return value.Position;
		elseif typeof(value) == "Instance" then
			if value:IsA("Attachment") then
				return value.WorldPosition;
			elseif value:IsA("BasePart") then
				return value.Position;
			end;
		end;
	end;

	local function createTracer(startValue, endValue)
		local startPosition = toPosition(startValue);
		local endPosition = toPosition(endValue);

		if not startPosition or not endPosition then return end;

		local duration = B.Duration or 1;
		local style = TRACER_STYLES[B.Style] or TRACER_STYLES.Classic;
		local startPart, startAttachment = makePoint(startPosition, duration + 0.5);
		local endPart, endAttachment = makePoint(endPosition, duration + 0.5);

		local beam = Instance.new("Beam");

		beam.Name = SaladUI.RandomString();
		beam.FaceCamera = true;
		beam.TextureSpeed = style.speed;
		beam.TextureLength = style.length;
		beam.Width0 = style.width;
		beam.Width1 = style.width;
		beam.LightEmission = 3;
		beam.LightInfluence = 0;
		beam.Brightness = style.brightness;
		beam.Texture = tracerTextures[B.Style] or style.fallback;
		beam.Color = ColorSequence.new(B.Color);
		beam.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.1), NumberSequenceKeypoint.new(1, 0.1) });
		beam.Attachment0 = startAttachment;
		beam.Attachment1 = endAttachment;
		beam.Parent = startPart;

		task.delay(duration, function()
			if beam.Parent then
				TweenService:Create(beam, FADE, { Width0 = 0, Width1 = 0 }):Play();
			end;
		end);

		task.delay(duration + 0.5, function()
			live[startPart], live[endPart] = nil, nil;
		end);
	end;

	local function onGunFired(gun, startValue, endValue)
		if not (ALIVE and B.On) then return end;

		local character = LocalPlayer.Character;

		if not character then return end;
		if not (typeof(gun) == "Instance" and gun:IsDescendantOf(character)) then return end;
		if not isLocalSheriff() then return end;

		createTracer(startValue, endValue);
	end;

	local function connectGunFired()
		local ok, remote = pcall(function()
			return ReplicatedStorage:WaitForChild("ClientServices"):WaitForChild("WeaponService"):WaitForChild("GunFired");
		end);

		if not ok or not remote or not ALIVE then return end;
		if gunFiredConn and gunFiredRemote == remote and gunFiredConn.Connected then return end;

		if gunFiredConn then
			pcall(function() gunFiredConn:Disconnect() end);

			gunFiredConn = nil;
		end;

		gunFiredRemote = remote;
		gunFiredConn = remote.OnClientEvent:Connect(function(gun, startValue, endValue)
			task.spawn(onGunFired, gun, startValue, endValue);
		end);
	end;

	task.spawn(function()
		while ALIVE do
			if B.On then pcall(connectGunFired) end;

			task.wait(1);
		end;
	end);

	local row = Sections.BulletTracer:AddLabel("Bullet Tracers");

	row:AddToggle({
		Default = false,
		Flag = "bullet_tracers",
		Callback = function(v)
			B.On = v == true;

			if B.On then task.spawn(connectGunFired) end;
		end,
	});

	row:AddColorPicker({
		Default = B.Color,
		Flag = "bullet_tracers_color",
		Callback = function(v) B.Color = v end,
	});

	Sections.BulletTracer:AddLabel("Style"):AddDropdown({
		Default = B.Style,
		Values = { "Classic", "Bloom", "Comet", "Lightning", "Sparkle", "SoftGlow" },
		Flag = "bullet_tracers_style",
		Callback = function(v)
			B.Style = TRACER_STYLES[v] and v or "Classic";
			warmTracerStyle(B.Style);
		end,
	});

	Sections.BulletTracer:AddLabel("Duration"):AddSlider({
		Min = 0.1, Max = 5, Default = 1, Rounding = 1, Size = 100,
		Flag = "bullet_tracers_lifetime",
		Callback = function(v) B.Duration = tonumber(v) or 1 end,
	});

	ESP.BulletTracers = B;
	ESP.ClearBulletTracers = onUnload("bullet tracers", function()
		B.On = false;

		if gunFiredConn then
			pcall(function() gunFiredConn:Disconnect() end);

			gunFiredConn = nil;
		end;

		for part in pairs(live) do
			pcall(function() part:Destroy() end);
		end;

		table.clear(live);
	end);
end);
