	local function place(ra, dec)
		local a = math.rad(ra * 15);
		local d = math.rad(dec);
		local flat = math.cos(d);

		return Vector3.new(flat * math.cos(a), math.sin(d), flat * math.sin(a));
	end;

	local figureCenters = {};
	for name, figure in pairs(FIGURES) do
		local center = Vector3.zero;
		for _, star in ipairs(figure.stars) do center += place(star[2], star[3]) end;
		figureCenters[name] = center.Magnitude > 0.001 and center.Unit or Vector3.yAxis;
	end;

	local host = Instance.new("Part");

	host.Name = SaladUI.RandomString();
	host.Anchored = true;
	host.CanCollide = false;
	host.CanQuery = false;
	host.CanTouch = false;
	host.Transparency = 1;
	host.Size = Vector3.one;
	host.Locked = true;
	host:SetAttribute(TAG, INIT_GENERATION);
	host.Parent = workspace;

	local gui = Instance.new("Folder");
	gui.Name = SaladUI.RandomString();
	gui.Parent = host;

	local glow;

	task.spawn(function()
		glow = Remote.asset("particles/p_glow.png");
	end);

	local built = {};
	local spin = 0;

	local TILT = math.rad(90 - 46);
	local COMPASS = math.rad(28);

	local dome = FAR;
	local domeScale = 1;

	local Lighting = game:GetService("Lighting");

	local function reach()
		local air = Lighting:FindFirstChildOfClass("Atmosphere");
		local thick = (air and air.Density) or 0;

		if thick <= 0.01 then return FAR end;

		return math.floor(math.clamp(NEAR * (1 - thick), 24, NEAR) / 2) * 2;
	end;

	local function skyfade(height)
		return math.clamp((height + 0.03) / 0.16, 0, 1);
	end;
	local MAX_FIGURE_RADIUS = math.rad(3);

	local function buildOne(name)
		local figure = FIGURES[name];

		if not figure then return nil end;

		local record = { stars = {}, beams = {}, born = os.clock(), sway = math.random() * math.pi * 2 };
		local rawAims, middle = {}, Vector3.zero;

		for index, star in ipairs(figure.stars) do
			local aim = place(star[2], star[3]);

			rawAims[index] = aim;
			middle += aim;
		end;

		local center = (#rawAims > 0 and middle.Magnitude > 0.001) and middle.Unit or Vector3.yAxis;
		local farthest = 0;

		for _, aim in ipairs(rawAims) do
			farthest = math.max(farthest, math.acos(math.clamp(center:Dot(aim), -1, 1)));
		end;

		local compression = farthest > MAX_FIGURE_RADIUS and MAX_FIGURE_RADIUS / farthest or 1;
		local function compact(aim)
			if compression >= 0.9999 then return aim end;
			local angle = math.acos(math.clamp(center:Dot(aim), -1, 1));

			if angle < 0.00001 then return center end;
			local sine = math.sin(angle);

			return (center * (math.sin((1 - compression) * angle) / sine)
				+ aim * (math.sin(compression * angle) / sine)).Unit;
		end;

		middle = Vector3.zero;

		for index, star in ipairs(figure.stars) do
			local aim = compact(rawAims[index]);

			local anchor = Instance.new("Attachment");

			anchor.Name = SaladUI.RandomString();

			anchor.Position = aim * dome;
			anchor.Parent = host;

			local weight = math.clamp((5.2 - star[4]) / 6.2, 0.3, 1);

			local board = Instance.new("BillboardGui");

			board.Name = SaladUI.RandomString();
			board.Adornee = anchor;
			board.AlwaysOnTop = false;
			board.LightInfluence = 0;

			board.Size = UDim2.fromScale(1, 1);
			board.Parent = gui;

			local halo = Instance.new("ImageLabel");

			halo.BackgroundTransparency = 1;
			halo.AnchorPoint = Vector2.new(0.5, 0.5);
			halo.Position = UDim2.fromScale(0.5, 0.5);
			halo.Size = UDim2.fromScale(2.4, 2.4);
			halo.Image = glow or "rbxasset://textures/particles/sparkles_main.dds";
			halo.Parent = board;

			local dot = Instance.new("ImageLabel");

			dot.BackgroundTransparency = 1;
			dot.AnchorPoint = Vector2.new(0.5, 0.5);
			dot.Position = UDim2.fromScale(0.5, 0.5);
			dot.Size = UDim2.fromScale(1, 1);
			dot.Image = glow or "rbxasset://textures/particles/sparkles_main.dds";
			dot.Parent = board;

			local label;

			if star[1] then
				label = Instance.new("TextLabel");
				label.AnchorPoint = Vector2.new(0.5, 0);
				label.Position = UDim2.fromScale(0.5, 1);
				label.Size = UDim2.fromScale(4, 0.5);
				label.BackgroundTransparency = 1;
				label.Font = Enum.Font.Gotham;
				label.Text = star[1];
				label.TextSize = 12;
				label.TextTransparency = 0.35;
				label.Visible = false;
				label.Parent = board;
			end;

			middle = middle + aim;

			record.stars[index] = {
				anchor = anchor, board = board, dot = dot, halo = halo, label = label,
				weight = weight, aim = aim, home = aim * dome,
				tint = TINT[star[1]] or PLAIN,

				phase = math.random() * math.pi * 2,
				rate = 0.5 + math.random() * 1.3,

				delay = 0.04 * index,
				alpha = 0,
			};
		end;

		if #figure.stars > 0 then
			local aim = middle / #figure.stars;

			aim = (aim.Magnitude > 0.001) and aim.Unit or Vector3.yAxis;

			local seat = Instance.new("Attachment");

			seat.Name = SaladUI.RandomString();
			seat.Position = aim * dome;
			seat.Parent = host;

			local board = Instance.new("BillboardGui");

			board.Name = SaladUI.RandomString();
			board.Adornee = seat;
			board.AlwaysOnTop = false;
			board.LightInfluence = 0;
			board.Size = UDim2.fromScale(1, 1);
			board.Enabled = false;
			board.Parent = gui;

			local tag = Instance.new("TextLabel");

			tag.BackgroundTransparency = 1;
			tag.Size = UDim2.fromScale(1, 1);
			tag.Font = Enum.Font.Gotham;
			tag.Text = name;
			tag.TextScaled = true;
			tag.TextTransparency = 0.45;
			tag.Parent = board;

			record.title = { seat = seat, board = board, tag = tag, aim = aim };
		end;

		for order, pair in ipairs(figure.lines) do
			local from = record.stars[pair[1]];
			local to = record.stars[pair[2]];

			if from and to then
				local beam = Instance.new("Beam");

				beam.Attachment0 = from.anchor;
				beam.Attachment1 = to.anchor;
				beam.FaceCamera = true;
				beam.LightInfluence = 0;
				beam.LightEmission = 1;

				beam.Segments = 1;
				beam.Width0 = 4;
				beam.Width1 = 4;
				beam.Parent = host;

				record.beams[#record.beams + 1] = {
					beam = beam, a = from, b = to,

					delay = 0.45 + 0.05 * order,
					shown = -1,
				};
			end;
		end;

		return record;
	end;

	local function dropRecord(record)
		if record.title then
			pcall(function() record.title.board:Destroy() end);
			pcall(function() record.title.seat:Destroy() end);
		end;

		for _, line in ipairs(record.beams) do pcall(function() line.beam:Destroy() end) end;

		for _, star in ipairs(record.stars) do
			pcall(function() star.board:Destroy() end);
			pcall(function() star.anchor:Destroy() end);
		end;
	end;

	local meteors = {};
	local nextFall = 0;

	local function clearMeteors()
		for _, m in ipairs(meteors) do
			pcall(function() m.beam:Destroy() end);
			pcall(function() m.head:Destroy() end);
			pcall(function() m.tail:Destroy() end);
		end;

		table.clear(meteors);
	end;

	local function fall(now)

		local up = 0.3 + math.random() * 0.55;
		local turn = math.random() * math.pi * 2;
		local flat = math.sqrt(math.max(0, 1 - up * up));
		local from = Vector3.new(flat * math.cos(turn), up, flat * math.sin(turn)) * dome;
		local radial = from.Unit;

		local want = Vector3.new(math.random() - 0.5, -1.1, math.random() - 0.5);
		local dir = want - radial * want:Dot(radial);

		if dir.Magnitude < 0.05 then dir = radial:Cross(Vector3.yAxis) end;

		local head = Instance.new("Attachment");
		head.Name = SaladUI.RandomString();
		head.Parent = host;

		local tail = Instance.new("Attachment");
		tail.Name = SaladUI.RandomString();
		tail.Parent = host;

		local beam = Instance.new("Beam");
		beam.Attachment0 = tail;
		beam.Attachment1 = head;
		beam.FaceCamera = true;
		beam.LightInfluence = 0;
		beam.LightEmission = 1;
		beam.Segments = 8;
		beam.Width0 = 0.8;
		beam.Width1 = 11;
		beam.Parent = host;

		meteors[#meteors + 1] = {
			beam = beam, head = head, tail = tail,
			from = from, dir = dir.Unit, born = now,
			life = 0.9 + math.random() * 0.8,
			span = 240 + math.random() * 300,
			trail = 110 + math.random() * 150,
		};
	end;

	local function stepMeteors(now, color)
		if not C.Meteors then
			if #meteors > 0 then clearMeteors() end;

			nextFall = 0;

			return;
		end;

		if nextFall == 0 then
			nextFall = now + math.random() * 4;
		elseif now >= nextFall then

			local gap = 60 / math.max(1, C.Rate);

			nextFall = now + gap * (0.45 + math.random());

			if #meteors < 6 then fall(now) end;
		end;

		for i = #meteors, 1, -1 do
			local m = meteors[i];
			local t = (now - m.born) / m.life;

			if t >= 1 then
				pcall(function() m.beam:Destroy() end);
				pcall(function() m.head:Destroy() end);
				pcall(function() m.tail:Destroy() end);

				table.remove(meteors, i);
			else
				local at = m.from + m.dir * (m.span * t);
				local drawn = m.trail * math.min(1, t * 5);

				m.head.Position = at;
				m.tail.Position = at - m.dir * drawn;
				Render.FxDepth(m.beam, C.Always);

				local fade = (t < 0.12) and (t / 0.12) or (1 - (t - 0.12) / 0.88) ^ 1.6;

				fade = fade * skyfade((host.CFrame:VectorToWorldSpace(at)).Unit.Y);

				m.beam.Color = ColorSequence.new(color);
				m.beam.Transparency = NumberSequence.new({
					NumberSequenceKeypoint.new(0, 1),
					NumberSequenceKeypoint.new(0.35, math.clamp(1 - fade * 0.25, 0, 1)),
					NumberSequenceKeypoint.new(1, math.clamp(1 - fade, 0, 1)),
				});
			end;
		end;
	end;

	local field = {};

	local function respan()
		local want = reach();

		if want == dome then return end;

		dome = want;
		domeScale = dome / FAR;

		for _, record in pairs(built) do
			for _, star in ipairs(record.stars) do
				star.home = star.aim * dome;
				star.anchor.Position = star.home;
			end;

			if record.title then
				record.title.seat.Position = record.title.aim * dome;
			end;
		end;

		for _, speck in ipairs(field) do
			speck.seat.Position = speck.aim * dome;
		end;

		clearMeteors();
	end;

	local fieldTurn = 0;
	local starTurn = 0;
	local starFrameCarry = 0;

	local function clearField()
		for _, speck in ipairs(field) do
			pcall(function() speck.board:Destroy() end);
			pcall(function() speck.seat:Destroy() end);
		end;

		table.clear(field);
	end;

	local function growField()
		local want = C.Field and math.floor(C.Density) or 0;

		while #field > want do
			local speck = table.remove(field);

			pcall(function() speck.board:Destroy() end);
			pcall(function() speck.seat:Destroy() end);
		end;

		while #field < want do

			local rise = math.random() * 2 - 1;
			local turn = math.random() * math.pi * 2;
			local flat = math.sqrt(math.max(0, 1 - rise * rise));
			local aim = Vector3.new(flat * math.cos(turn), rise, flat * math.sin(turn));

			local seat = Instance.new("Attachment");

			seat.Name = SaladUI.RandomString();
			seat.Position = aim * dome;
			seat.Parent = host;

			local board = Instance.new("BillboardGui");

			board.Name = SaladUI.RandomString();
			board.Adornee = seat;
			board.LightInfluence = 0;
			board.Size = UDim2.fromScale(1, 1);
			board.Parent = gui;

			local dot = Instance.new("ImageLabel");

			dot.BackgroundTransparency = 1;
			dot.AnchorPoint = Vector2.new(0.5, 0.5);
			dot.Position = UDim2.fromScale(0.5, 0.5);
			dot.Size = UDim2.fromScale(1, 1);
			dot.Image = glow or "rbxasset://textures/particles/sparkles_main.dds";
			dot.Parent = board;

			field[#field + 1] = {
				seat = seat, board = board, dot = dot, aim = aim,

				weight = 0.1 + (math.random() ^ 3) * 0.28,
				phase = math.random() * math.pi * 2,
				rate = 0.4 + math.random() * 1.4,
				warm = math.random() < 0.3,
			};
		end;
	end;

	local desiredFigures = {};
	local figureQueue = {};
	local figureRefresh = 0;
	local MAX_LIVE_FIGURES = 24;

	local function teardown()
		for name, record in pairs(built) do
			dropRecord(record);

			built[name] = nil;
		end;

		clearMeteors();
		clearField();
		table.clear(desiredFigures);
		table.clear(figureQueue);
		figureRefresh = 0;
	end;

	local function refreshFigures(camera)
		local look = host.CFrame:VectorToObjectSpace(camera.CFrame.LookVector);
		local candidates = {};

		for order, name in ipairs(ORDER) do
			if C.Picked[name] then
				candidates[#candidates + 1] = {
					name = name,
					dot = figureCenters[name]:Dot(look),
					order = order,
				};
			end;
		end;

		table.sort(candidates, function(a, b)
			if math.abs(a.dot - b.dot) < 0.0001 then return a.order < b.order end;
			return a.dot > b.dot;
		end);

		table.clear(desiredFigures);
		for index = 1, math.min(MAX_LIVE_FIGURES, #candidates) do
			desiredFigures[candidates[index].name] = true;
		end;

		for name, record in pairs(built) do
			if not desiredFigures[name] then
				dropRecord(record);
				built[name] = nil;
			end;
		end;

		table.clear(figureQueue);
		for index = 1, math.min(MAX_LIVE_FIGURES, #candidates) do
			local name = candidates[index].name;
			if not built[name] then figureQueue[#figureQueue + 1] = name end;
		end;
	end;

	local function sync()
		if not C.On then
			teardown();

			return;
		end;

		for name, record in pairs(built) do
			if not C.Picked[name] then
				dropRecord(record);

				built[name] = nil;
			end;
		end;

		figureRefresh = 0;
	end;

	local function ribbon(base)
		return NumberSequence.new(base);
	end;

	local function step(dt)
		if not (ALIVE and C.On) then starFrameCarry = 0; return end;
		starFrameCarry = math.min(starFrameCarry + dt, 0.1);
		if starFrameCarry < 1 / 30 then return end;
		dt = starFrameCarry;
		starFrameCarry %= 1 / 30;

		local camera = Render.camera();

		if not camera then return end;

		local now = os.clock();

		spin = (spin + dt * (C.Spin / 1000)) % (math.pi * 2);

		host.CFrame = CFrame.new(camera.CFrame.Position)
			* CFrame.Angles(0, COMPASS, 0)
			* CFrame.Angles(TILT, 0, 0)
			* CFrame.Angles(0, spin, 0);

		figureRefresh -= dt;
		if figureRefresh <= 0 then
			figureRefresh = 0.25;
			refreshFigures(camera);
		end;

		local created = 0;
		while created < 2 and #figureQueue > 0 do
			local name = table.remove(figureQueue, 1);
			if desiredFigures[name] and C.Picked[name] and not built[name] then
				built[name] = buildOne(name);
				created += 1;
			end;
		end;

		respan();

		local scale = (C.Scale / 100) * domeScale;
		local glowAmount = C.Glow / 100;
		local twinkle = C.Twinkle / 100;
		local natural = C.Natural;
		local frame = host.CFrame;

		stepMeteors(now, natural and METEOR_TONE or C.Star);

		growField();

		local warmTone = C.Star:Lerp(WARM_FIELD, 0.5);

		fieldTurn = (fieldTurn + 1) % 3;

		for index = 1 + fieldTurn, #field, 3 do
			local speck = field[index];
			local horizon = skyfade(frame:VectorToWorldSpace(speck.aim).Y);

			if horizon <= 0.002 then
				if speck.board.Enabled then speck.board.Enabled = false end;
			else
				if not speck.board.Enabled then speck.board.Enabled = true end;

				local pulse = 1 + twinkle * 0.2 * math.sin(now * speck.rate + speck.phase);
				local lit = glowAmount * horizon * speck.weight * pulse;
				local size = 78 * speck.weight * scale * pulse;

				speck.board.Size = UDim2.fromScale(size, size);
				if speck.board.AlwaysOnTop ~= C.Always then speck.board.AlwaysOnTop = C.Always end;

				local tone = (natural and speck.warm) and warmTone or C.Star;

				if speck.tone ~= tone then
					speck.tone = tone;
					speck.dot.ImageColor3 = tone;
				end;

				speck.dot.ImageTransparency = math.clamp(1 - lit, 0, 1);
			end;
		end;

		starTurn = 1 - starTurn;
		for _, record in pairs(built) do

			local breath = 0.92 + 0.08 * math.sin(now * 0.32 + record.sway);
			local age = now - record.born;
			if C.Lines then

				for _, star in ipairs(record.stars) do
					star.horizon = skyfade(frame:VectorToWorldSpace(star.aim).Y);
				end;
			end;

			for index = 1 + starTurn, #record.stars, 2 do
				local star = record.stars[index];
				local horizon = C.Lines and star.horizon or skyfade(frame:VectorToWorldSpace(star.aim).Y);

				if horizon <= 0.002 then
					if star.board.Enabled then star.board.Enabled = false end;

					continue;
				end;

				if not star.board.Enabled then star.board.Enabled = true end;

				star.alpha = math.clamp((age - star.delay) / 0.55, 0, 1);

				local pulse = 1 + twinkle * 0.16 * math.sin(now * star.rate + star.phase)
					+ twinkle * 0.07 * math.sin(now * star.rate * 2.7 + star.phase * 1.7);

				local lit = glowAmount * horizon * star.alpha * breath
					* (0.35 + star.weight * 0.65) * pulse;

				local size = 34 * star.weight * scale * (0.55 + 0.45 * star.alpha)
					* (1 + twinkle * 0.08 * (pulse - 1) * 6);

				local tone = C.Star;
				if natural then
					if star.mixedFor ~= C.Star then
						star.mixedFor = C.Star;
						star.mixedTone = star.tint:Lerp(C.Star, 0.35);
					end;
					tone = star.mixedTone;
				end;

				star.board.Size = UDim2.fromScale(size, size);

				if star.board.AlwaysOnTop ~= C.Always then
					star.board.AlwaysOnTop = C.Always;
				end;

				if star.tone ~= tone then
					star.tone = tone;
					star.dot.ImageColor3 = tone;
					star.halo.ImageColor3 = tone;
				end;

				star.dot.ImageTransparency = math.clamp(1 - lit, 0, 1);

				star.halo.ImageTransparency = math.clamp(1 - lit * star.weight * 0.7, 0, 1);

				if star.label then
					local visible = C.Labels and horizon > 0.25 and star.weight > 0.62;
					if star.label.Visible ~= visible then star.label.Visible = visible end;
					if visible then
						if star.labelTone ~= tone then star.labelTone = tone; star.label.TextColor3 = tone end;
						star.label.TextTransparency = math.clamp(0.35 + (1 - horizon) * 0.65, 0, 1);
					end;
				end;
			end;

			if record.title then
				local title = record.title;
				if not C.Names then
					if title.board.Enabled then title.board.Enabled = false end;
				else
					local horizon = skyfade(frame:VectorToWorldSpace(title.aim).Y);
					local want = horizon > 0.2;

					if title.board.Enabled ~= want then title.board.Enabled = want end;

					if want then
						local span = 26 * scale;

						title.board.Size = UDim2.fromScale(span * 4, span);
						if title.board.AlwaysOnTop ~= C.Always then title.board.AlwaysOnTop = C.Always end;
						if title.tone ~= C.Line then title.tone = C.Line; title.tag.TextColor3 = C.Line end;
						title.tag.TextTransparency = math.clamp(0.5 + (1 - horizon) * 0.5, 0, 1);
					end;
				end;
			end;

			for _, line in ipairs(record.beams) do
				local beam = line.beam;
				Render.FxDepth(beam, C.Always);

				if not C.Lines then
					beam.Enabled = false;
				else
					local reach = math.min(line.a.horizon, line.b.horizon);

					local drawn = math.clamp((age - line.delay) / 0.7, 0, 1);
					local lit = glowAmount * reach * drawn * breath;
					local want = lit > 0.02;

					if beam.Enabled ~= want then beam.Enabled = want end;

					if want then

						local base = math.clamp(1 - lit * 1.35, 0.42, 0.9);

						if math.abs(base - line.shown) > 0.015 then
							line.shown = base;
							beam.Transparency = ribbon(base);
						end;

						local wide = 4 * scale;

						if line.wide ~= wide then
							line.wide = wide;
							beam.Width0 = wide;
							beam.Width1 = wide;
						end;

						if line.natural ~= natural or line.tone ~= C.Line then
							line.natural = natural;
							line.tone = C.Line;

							beam.Color = natural
								and ColorSequence.new(line.a.tint:Lerp(C.Line, 0.55), line.b.tint:Lerp(C.Line, 0.55))
								or ColorSequence.new(C.Line);
						end;
					end;
				end;
			end;
		end;
	end;

	SaladUI:AddSignal(RunService.RenderStepped:Connect(step));

	local row = Sections.Stars:AddLabel("Constellations");

	row:AddToggle({
		Name = "Constellations",
		Default = false,
		Flag = "stars",
		Callback = function(v) C.On = v; sync() end,
	});

	row:AddColorPicker({
		Default = C.Star,
		Flag = "stars_color",
		Callback = function(v) C.Star = v end,
	});

	local lineRow = Sections.Stars:AddLabel("Lines");

	lineRow:AddToggle({
		Name = "Lines",
		Default = true,
		Flag = "stars_lines",
		Callback = function(v) C.Lines = v end,
	});

	lineRow:AddColorPicker({
		Default = C.Line,
		Flag = "stars_line_color",
		Callback = function(v) C.Line = v end,
	});

	Sections.Stars:AddLabel("Constellations"):AddDropdown({
		Name = "Which ones",
		Default = ORDER,
		Values = ORDER,
		Multi = true,
		Flag = "stars_pick",
		Callback = function(value)
			local picked = {};

			if type(value) == "table" then
				for key, item in pairs(value) do
					if type(key) == "string" and item then
						picked[key] = true;
					elseif type(item) == "string" then
						picked[item] = true;
					end;
				end;
			elseif type(value) == "string" then
				picked[value] = true;
			end;

			C.Picked = picked;

			sync();
		end,
	});

	Sections.Stars:AddLabel("Size"):AddSlider({
		Min = 20, Max = 260, Default = 100, Rounding = 0, Type = "%", Size = 100,
		Flag = "stars_scale",
		Callback = function(v) C.Scale = v end,
	});

	Sections.Stars:AddLabel("Glow"):AddSlider({
		Min = 10, Max = 100, Default = 100, Rounding = 0, Type = "%", Size = 100,
		Flag = "stars_glow",
		Callback = function(v) C.Glow = v end,
	});

	Sections.Stars:AddLabel("Drift"):AddSlider({
		Min = 0, Max = 60, Default = 12, Rounding = 0, Size = 100,
		Flag = "stars_spin",
		Callback = function(v) C.Spin = v end,
	});

	Sections.Stars:AddLabel("Twinkle"):AddSlider({
		Min = 0, Max = 100, Default = 60, Rounding = 0, Type = "%", Size = 100,
		Flag = "stars_twinkle",
		Callback = function(v) C.Twinkle = v end,
	});

	Sections.Stars:AddLabel("Star Colors"):AddToggle({
		Name = "Real Star Colors",
		Default = true,
		Flag = "stars_natural",
		Callback = function(v) C.Natural = v end,
	});

	local fallRow = Sections.Stars:AddLabel("Shooting Stars");

	fallRow:AddToggle({
		Name = "Shooting Stars",
		Default = true,
		Flag = "stars_meteors",
		Callback = function(v) C.Meteors = v end,
	});

	fallRow:AddSlider({
		Name = "Meteor Rate",
		Min = 1, Max = 60, Default = 12, Rounding = 0, Size = 90,
		Flag = "stars_meteor_rate",
		Callback = function(v) C.Rate = v end,
	});

	local fieldRow = Sections.Stars:AddLabel("Background Stars");

	fieldRow:AddToggle({
		Name = "Background Stars",
		Default = true,
		Flag = "stars_field",
		Callback = function(v)
			C.Field = v;

			if not v then clearField() end;
		end,
	});

	fieldRow:AddSlider({
		Name = "Star Density",
		Min = 60, Max = 700, Default = 220, Rounding = 0, Size = 80,
		Flag = "stars_density",
		Callback = function(v) C.Density = v end,
	});

	Sections.Stars:AddLabel("Names"):AddToggle({
		Name = "Names",
		Default = false,
		Flag = "stars_names",
		Callback = function(v) C.Names = v end,
	});

	Sections.Stars:AddLabel("Star Labels"):AddToggle({
		Name = "Star Labels",
		Default = false,
		Flag = "stars_labels",
		Callback = function(v) C.Labels = v end,
	});

	ESP.ClearConstellations = onUnload("constellations", function()
		C.On = false;

		teardown();

		pcall(function() host:Destroy() end);
	end);
end);
guard("starfall", function()
	LPH_ATTRIBUTES(VM(NONE));
	local F = ESP.WorldFX;
	local S = {
		On = false, Count = 20, Rate = 150, Speed = 100, Length = 100, Size = 100,
		Life = 4, Distance = 260, Preset = "Perseids",
		Head = Color3.fromRGB(255, 249, 230), Tail = Color3.fromRGB(140, 185, 255),
		Fireballs = true, Stars = true, HeadSize = 14, Active = 0, Allocated = 0,
		ThroughWalls = false,
	};
	ESP.Starfall = S;
	local PRESETS = { "Perseids", "Leonids", "Gentle Shower" };
	local PROFILES = {
		Perseids = { direction = Vector3.new(0.92, -0.62, 0.28).Unit, speed = 76, spread = 0.12 },
		Leonids = { direction = Vector3.new(-0.75, -0.9, 0.45).Unit, speed = 108, spread = 0.1 },
		["Gentle Shower"] = { direction = Vector3.new(0.4, -0.85, -0.3).Unit, speed = 48, spread = 0.16 },
	};
	local MAX, LEVELS = 80, 96;
	local rng, slots, fades, hazeFades = Random.new(), {}, {}, {};
	local sky, connection, due, lastCamera;
	local generation, starting = 0, false;
	local lastHead, lastTail, colors;
	for level = 0, LEVELS do
		local alpha = level / LEVELS;
		fades[level] = NumberSequence.new({
			NumberSequenceKeypoint.new(0, 1),
			NumberSequenceKeypoint.new(0.35, 1 - alpha * 0.12),
			NumberSequenceKeypoint.new(0.75, 1 - alpha * 0.72),
			NumberSequenceKeypoint.new(0.96, 1 - alpha * 0.98),
			NumberSequenceKeypoint.new(1, 1 - alpha * 0.45),
		});
		hazeFades[level] = NumberSequence.new({
			NumberSequenceKeypoint.new(0, 1),
			NumberSequenceKeypoint.new(0.65, 1 - alpha * 0.1),
			NumberSequenceKeypoint.new(0.93, 1 - alpha * 0.28),
			NumberSequenceKeypoint.new(1, 1 - alpha * 0.08),
		});
	end;
	local hazeTexture, glowTexture, starTexture;
	local function ensure(token)
		if sky and sky.Parent then return true end;
		local haze = Remote.asset("trail/bloom.png") or "";
		local glow = Remote.asset("particles/p_glow.png") or "rbxasset://textures/particles/sparkles_main.dds";
		local star = Remote.asset("particles/star_user.png") or glow;
		if not ALIVE or not S.On or token ~= generation then return false end;
		hazeTexture, glowTexture = haze, glow;
		starTexture = star;
		sky = Instance.new("Part");
		sky.Name = "VisualsStarfall";
		sky.Anchored, sky.CanCollide, sky.CanTouch, sky.CanQuery = true, false, false, false;
		sky.Transparency, sky.CastShadow, sky.Size = 1, false, Vector3.one;
		sky:SetAttribute(TAG, INIT_GENERATION); sky.Parent = workspace;
		return true;
	end;
	local function make()
		local tail, nose = Instance.new("Attachment"), Instance.new("Attachment");
		tail.Parent, nose.Parent = sky, sky;
		local function beam(texture)
			local b = Instance.new("Beam");
			b.Attachment0, b.Attachment1 = tail, nose;
			b.FaceCamera, b.LightInfluence, b.LightEmission = true, 0, 1;
			b.Texture, b.TextureSpeed, b.Segments = texture, 0, 8;
			b.Width0, b.Enabled, b.Parent = 0, false, sky;
			return b;
		end;
		local card = Instance.new("BillboardGui");
		card.Adornee, card.AlwaysOnTop, card.LightInfluence = nose, S.ThroughWalls, 0;
		card.Size, card.Enabled, card.Parent = UDim2.fromScale(1, 1), false, sky;
		local blob = Instance.new("ImageLabel");
		blob.BackgroundTransparency, blob.Size = 1, UDim2.fromScale(1, 1);
		blob.Image, blob.Parent = glowTexture, card;
		local star = Instance.new("ImageLabel");
		star.BackgroundTransparency, star.Size = 1, UDim2.fromScale(0.85, 0.85);
		star.AnchorPoint, star.Position = Vector2.new(0.5, 0.5), UDim2.fromScale(0.5, 0.5);
		star.Image, star.Rotation, star.Parent = starTexture, 15, card;
		return { tail = tail, nose = nose, line = beam(""), haze = beam(hazeTexture), card = card, blob = blob, star = star, busy = false };
	end;
	local function park(slot)
		slot.busy, slot.line.Enabled, slot.haze.Enabled, slot.card.Enabled = false, false, false, false;
	end;
	local function launch(camera)
		local want = math.floor(F.Number(S.Count, 20, 1, MAX));
		local slot, active = nil, 0;
		for _, entry in ipairs(slots) do if entry.busy then active += 1 elseif not slot then slot = entry end end;
		if not slot or active >= want then return false end;
		local profile = PROFILES[S.Preset] or PROFILES.Perseids;
		local look = camera.CFrame.LookVector;
		local yaw = math.atan2(look.Z, look.X) + rng:NextNumber(-1.45, 1.45);
		local distance = S.Distance * rng:NextNumber(0.7, 1.2);
		slot.origin = camera.CFrame.Position + Vector3.new(math.cos(yaw) * distance,
			distance * rng:NextNumber(0.5, 1.0), math.sin(yaw) * distance);
		local spread = Vector3.new(rng:NextNumber(-profile.spread, profile.spread),
			rng:NextNumber(-0.06, 0.06), rng:NextNumber(-profile.spread, profile.spread));
		slot.velocity = (profile.direction + spread).Unit * profile.speed * rng:NextNumber(0.85, 1.15);
		slot.fire = S.Fireballs and rng:NextNumber() < 0.07;
		slot.mass = slot.fire and rng:NextNumber(1.7, 2.2) or rng:NextNumber(0.45, 1.1);
		slot.life = S.Life * rng:NextNumber(0.85, 1.15) * (slot.fire and 1.2 or 1);
		slot.age, slot.travel, slot.busy = 0, 0, true;
		return true;
	end;
	local function step(dt)
		if not ALIVE or not S.On or not sky or not sky.Parent then return end;
		local camera = Render.camera(); if not camera then return end;
		dt = math.clamp(dt, 0, 0.1);
		local at = camera.CFrame.Position;
		if lastCamera and (at - lastCamera).Magnitude > S.Distance * 2 then
			for _, slot in ipairs(slots) do park(slot) end;
			due = 0;
		end;
		lastCamera = at;
		local want = math.floor(F.Number(S.Count, 20, 1, MAX));

		for _ = 1, math.min(3, want - #slots) do slots[#slots + 1] = make() end;
		S.Allocated = #slots;
		if lastHead ~= S.Head or lastTail ~= S.Tail then
			lastHead, lastTail, colors = S.Head, S.Tail, ColorSequence.new(S.Tail, S.Head);
		end;
		due -= dt;
		if due <= 0 then
			launch(camera);

			due = (60 / S.Rate) * rng:NextNumber(0.8, 1.2);
		end;
		local active = 0;
		for _, slot in ipairs(slots) do
			if slot.busy then
				active += 1;
				if active > want then
					park(slot); active -= 1;
				else
					slot.age += dt; slot.travel += dt * S.Speed / 100;
					local nose = F.MeteorPoint(slot.origin, slot.velocity, slot.travel);
					local horizon = F.Smooth((nose.Y - at.Y - 10) / 40);
					if slot.age >= slot.life or horizon <= 0 then
						park(slot); active -= 1;
					else
						local lit = F.Envelope(slot.age, slot.life, 0.1, 0.32) * horizon;
						local span = math.min(slot.travel * slot.velocity.Magnitude,
							(30 + slot.mass * 22) * S.Length / 100);
						local tailTime = slot.travel - span / slot.velocity.Magnitude;
						local tail = F.MeteorPoint(slot.origin, slot.velocity, tailTime);
						slot.nose.WorldCFrame = F.Frame(nose, slot.velocity + Vector3.new(0, -3.6 * slot.travel, 0));
						slot.tail.WorldCFrame = F.Frame(tail, slot.velocity + Vector3.new(0, -3.6 * tailTime, 0));
						local level = math.floor(math.clamp(lit, 0, 1) * LEVELS + 0.5);
						local width = 0.55 * slot.mass * S.Size / 100;
						local handle = (nose - tail).Magnitude / 3;
						if slot.colors ~= colors then
							slot.line.Color, slot.haze.Color, slot.blob.ImageColor3 = colors, colors, S.Head;
							slot.star.ImageColor3 = S.Head;
							slot.colors = colors;
						end;
						if slot.level ~= level then
							slot.line.Transparency, slot.haze.Transparency = fades[level], hazeFades[level];
							slot.level = level;
						end;
						slot.line.Width1, slot.haze.Width1 = width, width * 3.4;
						slot.line.CurveSize0, slot.line.CurveSize1 = handle, handle;
						slot.haze.CurveSize0, slot.haze.CurveSize1 = handle, handle;
						slot.line.Enabled, slot.haze.Enabled, slot.card.Enabled = lit > 0.005, lit > 0.005, lit > 0.005;
						Render.FxDepth(slot.line, S.ThroughWalls);
						Render.FxDepth(slot.haze, S.ThroughWalls);
						slot.card.AlwaysOnTop = S.ThroughWalls;
						local headPixels = S.HeadSize * (slot.fire and 1.35 or 1);
						slot.card.Size = UDim2.fromOffset(headPixels, headPixels);
						slot.blob.ImageTransparency = 1 - lit * (S.Stars and 0.35 or (slot.fire and 0.9 or 0.72));
						slot.star.ImageTransparency = S.Stars and (1 - lit * 0.95) or 1;
					end;
				end;
			end;
		end;
		S.Active = active;
	end;
	local function stop()
		generation += 1; starting, lastCamera, due = false, nil, 0;
		if connection then connection:Disconnect(); connection = nil end;
		for _, slot in ipairs(slots) do park(slot) end;
		S.Active = 0;
	end;
	local function start()
		if connection or starting or not ALIVE or not S.On then return end;
		starting = true;
		local token = generation;
		local ok, ready = pcall(ensure, token);
		if token ~= generation then return end;
		starting = false;
		if not ok then stop(); warn("[visuals] Starfall: " .. tostring(ready)); return end;
		if not ready or not ALIVE or not S.On then return end;
		due = 0;
		connection = RunService.RenderStepped:Connect(step);
	end;
	local row = Sections.Starfall:AddLabel("Starfall");
	row:AddToggle({ Default = false, Flag = "starfall", Callback = function(v) S.On = v == true; if S.On then start() else stop() end end });
	row:AddColorPicker({ Default = S.Head, Flag = "starfall_head", Callback = function(v) S.Head = v end });
	Sections.Starfall:AddLabel("Shower Preset"):AddDropdown({
		Default = "Perseids", Values = PRESETS, Flag = "starfall_preset",
		Callback = function(v) S.Preset = table.find(PRESETS, v) and v or "Perseids" end,
	});
	Sections.Starfall:AddLabel("Max Stars"):AddSlider({
		Min = 1, Max = MAX, Default = 20, Rounding = 0, Size = 100, Flag = "starfall_count",
		Callback = function(v) S.Count = F.Number(v, 20, 1, MAX) end,
	});
	Sections.Starfall:AddLabel("Spawn Rate"):AddSlider({
		Min = 2, Max = 600, Default = 150, Rounding = 0, Type = "/min", Size = 100, Flag = "starfall_rate",
		Callback = function(v) S.Rate = F.Number(v, 150, 2, 600); due = 0 end,
	});
	local more = row:AddOption(1);
	more:AddLabel("Tail Color"):AddColorPicker({ Default = S.Tail, Flag = "starfall_tail", Callback = function(v) S.Tail = v end });
	for _, setting in ipairs({
		{ "Travel Speed", "starfall_speed", 20, 250, 100, "%", function(v) S.Speed = F.Number(v, 100, 20, 250) end },
		{ "Tail Length", "starfall_length", 20, 260, 100, "%", function(v) S.Length = F.Number(v, 100, 20, 260) end },
		{ "Size", "starfall_size", 20, 250, 100, "%", function(v) S.Size = F.Number(v, 100, 20, 250) end },
		{ "Lifetime", "starfall_life", 1, 12, 4, "s", function(v) S.Life = F.Number(v, 4, 1, 12) end },
		{ "Sky Distance", "starfall_distance", 100, 500, 260, "", function(v) S.Distance = F.Number(v, 260, 100, 500) end },
	}) do
		more:AddLabel(setting[1]):AddSlider({ Min = setting[3], Max = setting[4], Default = setting[5], Type = setting[6],
			Rounding = 0, Size = 100, Flag = setting[2], Callback = setting[7] });
	end;
	more:AddLabel("Bright Meteors"):AddToggle({ Default = true, Flag = "starfall_fireballs", Callback = function(v) S.Fireballs = v end });
	more:AddLabel("Star Heads"):AddToggle({ Default = true, Flag = "starfall_stars", Callback = function(v) S.Stars = v end });
	more:AddLabel("Head Size"):AddSlider({ Min = 3, Max = 64, Default = 14, Rounding = 0, Type = "px", Size = 100,
		Flag = "starfall_head_size", Callback = function(v) S.HeadSize = F.Number(v, 14, 3, 64) end });
	ESP.ClearStarfall = onUnload("starfall", function()
		S.On = false; stop();
		if sky then sky:Destroy(); sky = nil end;
		table.clear(slots); S.Allocated = 0;
	end);
end);
guard("weather", function()
	LPH_ATTRIBUTES(VM(NONE));
	local SOFT = "rbxasset://textures/particles/smoke_main.dds";

	local DOT = "particles/p_glow.png";

	for _, leftover in ipairs(workspace:GetChildren()) do
		local owner = leftover:GetAttribute(TAG);
		if owner and owner ~= INIT_GENERATION and leftover:FindFirstChildWhichIsA("ParticleEmitter") then
			leftover:Destroy();
		end;
	end;

	local TYPES = {
		Snow = {

			texture = DOT,
			color = Color3.fromRGB(226, 240, 255),
			lifetime = NumberRange.new(4, 6),
			speed = NumberRange.new(6, 12),
			acceleration = Vector3.new(2, -6, 1),
			spread = Vector2.new(35, 35),
			spin = NumberRange.new(-40, 40),
			size = 0.32,
			squash = 0,
			emission = 0.15,
			density = 2.2,
			transparency = { 0.1, 0.2 },
			fade = 0.8,
		},
		["Snow Soft"] = {

			color = Color3.fromRGB(150, 200, 255),
			lifetime = NumberRange.new(4, 6),
			speed = NumberRange.new(6, 12),
			acceleration = Vector3.new(2, -6, 1),
			spread = Vector2.new(35, 35),
			spin = NumberRange.new(-40, 40),
			size = 0.55,
			squash = 0,
			emission = 0.4,
			transparency = { 0.2, 0.3 },
			fade = 0.8,
		},
		Sakura = {
			color = Color3.fromRGB(255, 170, 210),
			lifetime = NumberRange.new(5, 7),
			speed = NumberRange.new(5, 10),
			acceleration = Vector3.new(4, -5, 2),
			spread = Vector2.new(40, 40),
			spin = NumberRange.new(-80, 80),
			size = 0.5,
			squash = 1.4,
			emission = 0.4,
			transparency = { 0.15, 0.25 },
			fade = 0.85,
		},
		Rain = {
			color = Color3.fromRGB(170, 200, 255),
			lifetime = NumberRange.new(1.1, 1.6),
			speed = NumberRange.new(70, 95),
			acceleration = Vector3.new(0, -40, 0),

			spread = Vector2.new(1, 1),
			spin = NumberRange.new(0, 0),
			size = 0.5,
			squash = 6,
			emission = 0.35,
			density = 4.5,
			transparency = { 0.35, 0.45 },
			fade = 0.9,
			orientation = Enum.ParticleOrientation.FacingCameraWorldUp,
			rotation = NumberRange.new(0, 0),
		},
		Ash = {
			color = Color3.fromRGB(90, 90, 95),
			lifetime = NumberRange.new(6, 9),
			speed = NumberRange.new(3, 7),
			acceleration = Vector3.new(3, -3, 2),
			spread = Vector2.new(45, 45),
			spin = NumberRange.new(-25, 25),
			size = 0.32,
			squash = 0,
			emission = 0.1,
			transparency = { 0.25, 0.4 },
			fade = 0.85,
		},
		Fireflies = {
			color = Color3.fromRGB(255, 220, 120),
			lifetime = NumberRange.new(3, 5),
			speed = NumberRange.new(1, 3),
			acceleration = Vector3.new(0, 0.5, 0),
			spread = Vector2.new(180, 180),
			spin = NumberRange.new(-10, 10),
			size = 0.22,
			squash = 0,
			emission = 1,
			transparency = { 0.1, 0.1 },
			fade = 0.75,
		},
	};

	local W = {
		Kind = "Off",
		Rate = 250,
		Speed = 100,
		Size = 100,
		Fade = 100,
		Distance = 120,
		Height = 90,
		Color = TYPES.Snow.color,
		ThroughWalls = false,
	};

	local part, emitter, conn, lastPos, lastLook;

	local function rateNow()
		local preset = TYPES[W.Kind];
		local area = (W.Distance / 120) ^ 2;
		return math.min(W.Rate * area * ((preset and preset.density) or 1), 4000);
	end;

	local colorNow, colorTarget = W.Color, W.Color;

	local function easeColour(target)
		colorTarget = target;
	end;

	local function stepColour()
		if not emitter then return end;

		local dr, dg, db = colorNow.R - colorTarget.R, colorNow.G - colorTarget.G, colorNow.B - colorTarget.B;

		if dr * dr + dg * dg + db * db < 0.00002 then
			if colorNow ~= colorTarget then
				colorNow = colorTarget;
				emitter.Color = ColorSequence.new(colorNow);
			end;

			return;
		end;

		colorNow = colorNow:Lerp(colorTarget, 0.09);
		emitter.Color = ColorSequence.new(colorNow);
	end;

	local function style()
		local preset = TYPES[W.Kind];
		if not (emitter and preset) then return end;

		local scale = W.Speed / 100;

		local texture = preset.texture;
		if texture and not texture:find("://", 1, true) then texture = Remote.asset(texture) end;
		emitter.Texture = texture or SOFT;
		emitter.LightInfluence = 0;
		emitter.LightEmission = preset.emission;
		Render.FxDepth(emitter, W.ThroughWalls);
		emitter.Drag = 0;
		emitter.EmissionDirection = Enum.NormalId.Bottom;
		emitter.Rate = rateNow();
		emitter.Color = ColorSequence.new(colorNow);

		emitter.Rotation = preset.rotation or NumberRange.new(0, 360);
		emitter.RotSpeed = preset.spin;
		emitter.SpreadAngle = preset.spread;

		pcall(function()
			emitter.Orientation = preset.orientation or Enum.ParticleOrientation.FacingCamera;
		end);

		emitter.Speed = NumberRange.new(preset.speed.Min * scale, preset.speed.Max * scale);
		emitter.Acceleration = (preset.acceleration + (preset.lean or Vector3.zero)) * scale;

		emitter.Lifetime = NumberRange.new(preset.lifetime.Min / scale, preset.lifetime.Max / scale);
		emitter.Size = NumberSequence.new(preset.size * (W.Size / 100));

		pcall(function() emitter.Squash = NumberSequence.new(preset.squash) end);

		local ghost = W.Fade / 100;
		local head = math.clamp(1 - (1 - preset.transparency[1]) / ghost, 0, 1);
		local tail = math.clamp(1 - (1 - preset.transparency[2]) / ghost, 0, 1);

		emitter.Transparency = NumberSequence.new({
			NumberSequenceKeypoint.new(0, head),
			NumberSequenceKeypoint.new(preset.fade, tail),
			NumberSequenceKeypoint.new(1, 1),
		});
	end;

	local function resize()
		if not part then return end;

		part.Size = Vector3.new(W.Distance, W.Height, W.Distance);
		if emitter then emitter.Rate = rateNow() end;
		lastPos, lastLook = nil, nil;
	end;

	local function stop()
		if conn then pcall(function() conn:Disconnect() end) conn = nil end;
		if part then pcall(function() part:Destroy() end) part = nil end;

		emitter, lastPos, lastLook = nil, nil, nil;
	end;

	local function ensurePart()
		if part and part.Parent then return end;

		part = Instance.new("Part");
		part.Name = SaladUI.RandomString();
		part.Anchored = true;
		part.CanCollide = false;
		part.CanQuery = false;
		part.CanTouch = false;
		part.CastShadow = false;
		part.Transparency = 1;
		part.Size = Vector3.new(W.Distance, W.Height, W.Distance);
		part:SetAttribute(TAG, INIT_GENERATION);
		part.Parent = workspace;

		emitter = Instance.new("ParticleEmitter");

		pcall(function()
			emitter.Shape = Enum.ParticleEmitterShape.Box;
			emitter.ShapeStyle = Enum.ParticleEmitterShapeStyle.Volume;
		end);

		emitter.Parent = part;

		style();
	end;

	local function burst()
		if not emitter then return end;

		emitter:Emit(math.clamp(math.floor(rateNow() * 0.2), 30, 600));
	end;

	local function start()
		ensurePart();

		if conn then return end;

		lastPos, lastLook = nil, nil;

		conn = SaladUI:AddSignal(RunService.RenderStepped:Connect(function()
			if not (part and part.Parent) then return end;

			stepColour();

			local camera = workspace.CurrentCamera;
			if not camera then return end;

			local cf = camera.CFrame;
			local at = cf.Position;
			local look = cf.LookVector;
			local flat = Vector3.new(look.X, 0, look.Z);

			if flat.Magnitude < 0.05 then
				flat = Vector3.new(0, 0, -1);
			else
				flat = flat.Unit;
			end;

			if lastPos and lastLook and (at - lastPos).Magnitude < 10 and flat:Dot(lastLook) > 0.95 then return end;

			lastPos, lastLook = at, flat;
			part.CFrame = CFrame.new(at + flat * (W.Distance * 0.22) + Vector3.new(0, W.Height * 0.5 - 26, 0));
		end));

		burst();
	end;

	ESP.Weather = W;
	ESP.ClearWeather = stop;

	local weatherRow = Sections.Weather:AddLabel("Type");
	weatherRow:AddDropdown({
		Default = "Off",
		Values = { "Off", "Snow", "Snow Soft", "Sakura", "Rain", "Ash", "Fireflies" },
		Flag = "weather_kind",
		Callback = function(v)
			W.Kind = v;

			if v == "Off" then
				stop();
				return;
			end;

			W.Color = TYPES[v].color;
			easeColour(W.Custom and W.Pick or W.Color);

			start();
			style();
			burst();
		end,
	});

	local options = weatherRow:AddOption(1);
	options:AddLabel("Amount"):AddSlider({
		Min = 20, Max = 800, Default = 250, Rounding = 0, Size = 100,
		Flag = "weather_rate",
		Callback = function(v)
			W.Rate = v;

			if emitter then emitter.Rate = rateNow() end;
		end,
	});

	options:AddLabel("Fall Speed"):AddSlider({
		Min = 10, Max = 400, Default = 100, Type = "%", Size = 100,
		Flag = "weather_speed",
		Callback = function(v) W.Speed = v; style() end,
	});

	options:AddLabel("Particle Size"):AddSlider({
		Min = 10, Max = 500, Default = 100, Type = "%", Size = 100,
		Flag = "weather_size",
		Callback = function(v) W.Size = v; style() end,
	});

	options:AddLabel("Transparency"):AddSlider({
		Min = 20, Max = 400, Default = 100, Type = "%", Size = 100,
		Flag = "weather_fade",
		Callback = function(v) W.Fade = v; style() end,
	});

	options:AddLabel("Distance"):AddSlider({
		Min = 60, Max = 600, Default = 120, Rounding = 0, Size = 100,
		Flag = "weather_distance",
		Callback = function(v) W.Distance = v; resize() end,
	});

	options:AddLabel("Height"):AddSlider({
		Min = 40, Max = 400, Default = 90, Rounding = 0, Size = 100,
		Flag = "weather_height",
		Callback = function(v) W.Height = v; resize() end,
	});

	local custom = options:AddLabel("Custom Color");
	custom:AddToggle({
		Default = false, Flag = "weather_custom",
		Callback = function(v)
			W.Custom = v;
			easeColour(v and W.Pick or W.Color);
		end,
	});
	custom:AddColorPicker({
		Default = W.Color,
		Flag = "weather_color",
		Callback = function(v)
			W.Pick = v;
			if W.Custom then easeColour(v) end;
		end,
	});

	Sections.Weather:AddButton({
		Name = "Burst",
		Callback = burst,
	});
end);
guard("crosshair", function()
	LPH_ATTRIBUTES(VM(NONE));
	local UserInputService = game:GetService("UserInputService");
	local LP = LocalPlayer;

	local crosshair_lines = {};
	local crosshair_enabled = false;
	local crosshair_hidden_game_cursor = false;
	local original_cursor_icon = nil;
	local gun_equipped = false;
	local game_crosshair_hook_conn = nil;

	local gap_size = 4;
	local line_length = 8;
	local line_thickness = 2;
	local line_color = Color3.fromRGB(255, 255, 255);
	local outline_color = Color3.fromRGB(0, 0, 0);
	local rotation_speed = 0;

	local current_rotation = 0;
	local crosshair_connection = nil;
	local gun_watch_connections = {};
	local containerConnections = {};
	local crosshair_angles = { 0, 0, 0, 0 };

	local function has_gun_equipped()
		local char = LP.Character;

		if char and char:FindFirstChild("Gun") then
			return true;
		end;

		return false;
	end;

	local function create_crosshair_lines()
		for i = 1, 8 do
			local line = drawNew("Line");

			line.Visible = false;
			line.Color = (i % 2 == 0) and outline_color or line_color;
			line.Thickness = (i % 2 == 0) and line_thickness + 2 or line_thickness;
			line.Transparency = 1;
			line.ZIndex = (i % 2 == 0) and 999 or 1000;

			crosshair_lines[i] = line;
		end;
	end;

	local function destroy_crosshair_lines()
		for i = 1, #crosshair_lines do
			if crosshair_lines[i] then
				destroyAny(crosshair_lines[i]);

				crosshair_lines[i] = nil;
			end;
		end;
	end;

	local function update_crosshair_visibility(show, equipped)
		if equipped == nil then
			equipped = has_gun_equipped();
		end;

		gun_equipped = equipped;

		local should_show = show and crosshair_enabled and gun_equipped;

		for i = 1, #crosshair_lines do
			if crosshair_lines[i] then
				crosshair_lines[i].Visible = should_show;
			end;
		end;
	end;

	local originalGui = setmetatable({}, {__mode="k"});
	local watchGeneration = 0;
	local function hide_game_crosshair_gui()
		if not (ALIVE and crosshair_enabled and crosshair_hidden_game_cursor and has_gun_equipped()) then return end;
		local pg=LP:FindFirstChild("PlayerGui");
		local topbar=pg and pg:FindFirstChild("GameTopbar");
		local gui=topbar and topbar:FindFirstChild("Crosshair");
		if gui and gui:IsA("GuiObject") then
			if originalGui[gui] == nil then originalGui[gui]=gui.Visible end;
			gui.Visible=false;
		end;
	end;
	local function show_game_crosshair_gui()
		for gui,visible in pairs(originalGui) do
			if gui.Parent then gui.Visible=visible end;
			originalGui[gui]=nil;
		end;
	end;

	local iconWatch = nil;
	local function setup_mouse_icon_hook()
		if iconWatch then return end;
		local mouse = LP:GetMouse();
		local ok, signal = pcall(mouse.GetPropertyChangedSignal, mouse, "Icon");
		if not ok then return end;
		iconWatch = signal:Connect(function()
			if mouse.Icon ~= "" then mouse.Icon = "" end;
		end);
	end;
	local function remove_mouse_icon_hook()
		if iconWatch then iconWatch:Disconnect(); iconWatch = nil end;
	end;
	local function hide_game_cursor(hide)
		local mouse=LP:GetMouse();
		if ALIVE and crosshair_enabled and crosshair_hidden_game_cursor and hide and has_gun_equipped() then
			setup_mouse_icon_hook();
			if original_cursor_icon == nil then original_cursor_icon = mouse.Icon end;
			if mouse.Icon ~= "" then mouse.Icon="" end;
			hide_game_crosshair_gui();
		else
			remove_mouse_icon_hook();
			if original_cursor_icon ~= nil and not SaladUI.Lib.cursor then mouse.Icon = original_cursor_icon end;
			original_cursor_icon = nil;
			show_game_crosshair_gui();
		end;
	end;

	local function update_crosshair(dt)
		if not crosshair_enabled or #crosshair_lines == 0 then return end;

		local equipped = has_gun_equipped();

		gun_equipped = equipped;
		hide_game_cursor(equipped);

		if not equipped then
			update_crosshair_visibility(false, equipped);

			return;
		end;

		local mouse_pos = UserInputService:GetMouseLocation();
		local center_x = mouse_pos.X;
		local center_y = mouse_pos.Y;

		if rotation_speed > 0 then
			current_rotation = (current_rotation + dt * rotation_speed * 100) % 360;
		else
			current_rotation = 0;
		end;

		local rad = math.rad(current_rotation);
		local cos = math.cos;
		local sin = math.sin;
		local pi = math.pi;

		crosshair_angles[1] = rad;
		crosshair_angles[2] = pi / 2 + rad;
		crosshair_angles[3] = pi + rad;
		crosshair_angles[4] = 3 * pi / 2 + rad;

		for i = 1, 4 do
			local angle = crosshair_angles[i];
			local line_idx = (i - 1) * 2 + 1;
			local outline_idx = line_idx + 1;

			local start_x = center_x + gap_size * cos(angle);
			local start_y = center_y + gap_size * sin(angle);
			local end_x = center_x + (gap_size + line_length) * cos(angle);
			local end_y = center_y + (gap_size + line_length) * sin(angle);

			local outline_start_x = center_x + (gap_size - 1) * cos(angle);
			local outline_start_y = center_y + (gap_size - 1) * sin(angle);
			local outline_end_x = center_x + (gap_size + line_length + 1) * cos(angle);
			local outline_end_y = center_y + (gap_size + line_length + 1) * sin(angle);

			if crosshair_lines[line_idx] then
				crosshair_lines[line_idx].From = Vector2.new(start_x, start_y);
				crosshair_lines[line_idx].To = Vector2.new(end_x, end_y);
			end;

			if crosshair_lines[outline_idx] then
				crosshair_lines[outline_idx].From = Vector2.new(outline_start_x, outline_start_y);
				crosshair_lines[outline_idx].To = Vector2.new(outline_end_x, outline_end_y);
			end;
		end;

		update_crosshair_visibility(true, equipped);
	end;

	local function start_crosshair()
		if crosshair_connection then return end;
		watchGeneration += 1;
		local generation = watchGeneration;

		if #crosshair_lines == 0 then
			create_crosshair_lines();
		end;

		crosshair_connection = RunService.RenderStepped:Connect(update_crosshair);

		local function watch_gun(container, kind)
			if not ALIVE or not crosshair_enabled or generation ~= watchGeneration or not container then return end;
			local old = containerConnections[kind];
			if old and old.container == container then return end;
			if old then old.add:Disconnect(); old.remove:Disconnect() end;
			local function changed(child)
				if child.Name ~= "Gun" or not ALIVE or generation ~= watchGeneration then return end;
				local equipped = has_gun_equipped();
				update_crosshair_visibility(true, equipped);
				hide_game_cursor(equipped);
			end;
			containerConnections[kind] = { container = container,
				add = container.ChildAdded:Connect(changed), remove = container.ChildRemoved:Connect(changed) };
		end;

		if not game_crosshair_hook_conn then
			local pg = LP:FindFirstChild("PlayerGui");

			if pg then
				game_crosshair_hook_conn = pg.DescendantAdded:Connect(function(descendant)
					if descendant.Name == "Crosshair" and descendant.Parent and descendant.Parent.Name == "GameTopbar" then
						if ALIVE and crosshair_enabled and crosshair_hidden_game_cursor and descendant:IsA("GuiObject") then
							hide_game_crosshair_gui();
						end;
					end;
				end);
			end;
		end;

		local char = LP.Character;

		if char then
			watch_gun(char, "character");
		end;

		local backpack = LP:FindFirstChildOfClass("Backpack");

		if backpack then
			watch_gun(backpack, "backpack");
		end;

		local char_conn = LP.CharacterAdded:Connect(function(new_char)
			task.wait(0.3);
			if not ALIVE or not crosshair_enabled or generation ~= watchGeneration or LP.Character ~= new_char then return end;

			watch_gun(new_char, "character");
			watch_gun(LP:FindFirstChildOfClass("Backpack"), "backpack");

			gun_equipped = has_gun_equipped();

			update_crosshair_visibility(true, gun_equipped);
			hide_game_cursor(gun_equipped and crosshair_hidden_game_cursor);
		end);

		table.insert(gun_watch_connections, char_conn);
		table.insert(gun_watch_connections, LP.ChildAdded:Connect(function(child)
			if child:IsA("Backpack") then watch_gun(child, "backpack") end;
		end));

		gun_equipped = has_gun_equipped();

		update_crosshair_visibility(true, gun_equipped);
		hide_game_cursor(gun_equipped and crosshair_hidden_game_cursor);
	end;

	local function stop_crosshair()
		watchGeneration += 1;
		if crosshair_connection then
			pcall(function() crosshair_connection:Disconnect() end);

			crosshair_connection = nil;
		end;

		if game_crosshair_hook_conn then
			pcall(function() game_crosshair_hook_conn:Disconnect() end);

			game_crosshair_hook_conn = nil;
		end;

		for _, conn in ipairs(gun_watch_connections) do
			pcall(function() conn:Disconnect() end);
		end;

		gun_watch_connections = {};
		for kind, entry in pairs(containerConnections) do
			entry.add:Disconnect(); entry.remove:Disconnect(); containerConnections[kind] = nil;
		end;

		update_crosshair_visibility(false);
		hide_game_cursor(false);
		show_game_crosshair_gui();
		destroy_crosshair_lines();
	end;

	local row = Sections.Screen:AddLabel("Crosshair");
	row:AddToggle({
		Name = "crosshair",
		Default = false,
		Flag = "crosshair",
		Callback = function(v)
			crosshair_enabled = v;

			if v then
				start_crosshair();
			else
				stop_crosshair();
			end;
		end,
	});
	local options = row:AddOption(1);
	options:AddLabel("Hide Default"):AddToggle({
		Name = "hide original",
		Default = false,
		Flag = "crosshair_hide_original",
		Callback = function(v)
			crosshair_hidden_game_cursor = v;

			hide_game_cursor(v);
		end,
	});
	options:AddLabel("Gap"):AddSlider({
		Min = 0, Max = 20, Default = 4, Rounding = 0, Size = 100,
		Flag = "crosshair_gap",
		Callback = function(v) gap_size = v end,
	});
	options:AddLabel("Line"):AddSlider({
		Min = 2, Max = 30, Default = 8, Rounding = 0, Size = 100,
		Flag = "crosshair_length",
		Callback = function(v) line_length = v end,
	});
	options:AddLabel("Thickness"):AddSlider({
		Min = 1, Max = 5, Default = 2, Rounding = 0, Size = 100,
		Flag = "crosshair_thickness",
		Callback = function(v)
			line_thickness = v;

			for i = 1, #crosshair_lines do
				if crosshair_lines[i] then
					crosshair_lines[i].Thickness = (i % 2 == 0) and v + 2 or v;
				end;
			end;
		end,
	});
	options:AddLabel("Rotation"):AddSlider({
		Min = 0, Max = 10, Default = 0, Rounding = 0, Size = 100,
		Flag = "crosshair_rotation",
		Callback = function(v) rotation_speed = v end,
	});
	options:AddLabel("Line"):AddColorPicker({
		Default = line_color,
		Flag = "crosshair_color",
		Callback = function(c)
			line_color = c;
			for i = 1, #crosshair_lines do
				if crosshair_lines[i] and i % 2 == 1 then crosshair_lines[i].Color = c end;
			end;
		end,
	});
	options:AddLabel("Outline"):AddColorPicker({
		Default = outline_color,
		Flag = "crosshair_outline_color",
		Callback = function(c)
			outline_color = c;

			for i = 1, #crosshair_lines do
				if crosshair_lines[i] and i % 2 == 0 then
					crosshair_lines[i].Color = c;
				end;
			end;
		end,
	});

	ESP.ClearCrosshair = onUnload("crosshair", function()
		crosshair_enabled = false;
		stop_crosshair();
		remove_mouse_icon_hook();
	end);
end);
guard("camera", function()
	local lockedFov, holding = 70, false;
	local original = nil;
	local originalCamera;
	local function restoreFov()
		if originalCamera and original then pcall(function() originalCamera.FieldOfView = original end) end;
		original, originalCamera = nil, nil;
	end;
	local loop;
	local function updateFov()
		LPH_ATTRIBUTES(VM(NONE));
		if not (ALIVE and holding and lockedFov) then return end;

		local camera = Render.camera();
		if camera and originalCamera ~= camera then restoreFov(); originalCamera, original = camera, camera.FieldOfView end;

		if camera and math.abs(camera.FieldOfView - lockedFov) > 0.01 then
			camera.FieldOfView = lockedFov;
		end;
	end;
	local function stopLoop()
		if loop then loop:Disconnect(); loop = nil end;
	end;

	local row = Sections.Camera:AddLabel("Field of View");

	row:AddToggle({
		Name = "Field of View",
		Default = false,
		Flag = "camera_fov",
		Callback = function(v)
			holding = v;

			local camera = Render.camera();

			if v then
				if camera and originalCamera ~= camera then restoreFov(); originalCamera, original = camera, camera.FieldOfView end;
				if not loop then loop = RunService.RenderStepped:Connect(updateFov) end;
				updateFov();
			else
				stopLoop();
				restoreFov();
			end;
		end,
	});

	row:AddSlider({
		Name = "Amount",
		Min = 40, Max = 120, Default = 70, Rounding = 0, Size = 110,
		Flag = "camera_fov_value",
		Callback = function(v) lockedFov = v end,
	});

	ESP.ClearCamera = onUnload("camera", function()
		holding = false;
		stopLoop();
		restoreFov();
	end);
end);

guard("camera helpers", function()
	local zoomOn, savedMin, savedMax = false, nil, nil;
	local fpsBefore;
	local function applyZoom()
		if zoomOn then
			if savedMax == nil then
				savedMin, savedMax = LocalPlayer.CameraMinZoomDistance, LocalPlayer.CameraMaxZoomDistance;
			end;
			LocalPlayer.CameraMaxZoomDistance = 2048;
		elseif savedMax ~= nil then
			LocalPlayer.CameraMinZoomDistance = savedMin;
			LocalPlayer.CameraMaxZoomDistance = savedMax;
			savedMin, savedMax = nil, nil;
		end;
	end;
	Sections.Camera:AddLabel("Unlock FPS"):AddToggle({
		Default = false, Flag = "unlock_fps",
		Callback = function(on)
			if type(setfpscap) ~= "function" then return end;
			if on then
				if fpsBefore == nil then
					local ok, value = pcall(function() return getfpscap() end);
					fpsBefore = ok and tonumber(value) or 0;
				end;
				pcall(setfpscap, 999);
			elseif fpsBefore ~= nil then
				pcall(setfpscap, fpsBefore);
				fpsBefore = nil;
			end;
		end,
	});
	Sections.Camera:AddLabel("No Zoom Limit"):AddToggle({
		Default = false, Flag = "no_zoom_limit",
		Callback = function(on) zoomOn = on; pcall(applyZoom) end,
	});
	SaladUI:AddSignal(LocalPlayer.CharacterAdded:Connect(function()
		task.wait(0.6);
		if ALIVE and zoomOn then
			if LocalPlayer.CameraMaxZoomDistance ~= 2048 then
				savedMin, savedMax = LocalPlayer.CameraMinZoomDistance, LocalPlayer.CameraMaxZoomDistance;
			end;
			pcall(applyZoom);
		end;
	end));
	onUnload("camera helpers", function()
		zoomOn = false;
		pcall(applyZoom);
		if fpsBefore ~= nil and type(setfpscap) == "function" then pcall(setfpscap, fpsBefore) end;
	end);
end);
	guard("skins mount", function()
		local mount = (function()
			return function(host)
				local Remote, Render, ESP = host.Remote, host.Render, host.ESP;
				local guard, onUnload, recordError = host.guard, host.onUnload, host.recordError;

				guard("skins", function()
					local REL = "data/mm2_weapons.json";

					local HttpService = game:GetService("HttpService");
					local RunService = game:GetService("RunService");
					local CollectionService = game:GetService("CollectionService");
					local ReplicatedStorage = game:GetService("ReplicatedStorage");
					local Players = game:GetService("Players");
					local LocalPlayer = Players.LocalPlayer;

					local REVIVE;

					local function tagged(t)
						local kind = t[1];

						if kind == "$v" then return Vector3.new(t[2], t[3], t[4]) end;
						if kind == "$c" then return Color3.fromRGB(t[2], t[3], t[4]) end;
						if kind == "$f" then return CFrame.new(unpack(t, 2)) end;
						if kind == "$a" then return CFrame.Angles(t[2], t[3], t[4]) end;
						if kind == "$v2" then return Vector2.new(t[2], t[3]) end;
						if kind == "$d" then return UDim.new(t[2], t[3]) end;
						if kind == "$d2" then return UDim2.new(t[2], t[3], t[4], t[5]) end;
						if kind == "$nr" then return NumberRange.new(t[2], t[3]) end;
						if kind == "$rc" then return Rect.new(t[2], t[3], t[4], t[5]) end;
						if kind == "$csk" then return ColorSequenceKeypoint.new(t[2], REVIVE(t[3])) end;
						if kind == "$nsk" then return NumberSequenceKeypoint.new(t[2], t[3], t[4]) end;

						if kind == "$cs" or kind == "$ns" then
							local source = t;
							local from = 2;

							if type(t[2]) == "table" and type(t[2][1]) ~= "string" then
								source, from = t[2], 1;
							end;

							local keys = {};

							for index = from, #source do keys[#keys + 1] = REVIVE(source[index]) end;

							local want = (kind == "$cs") and "ColorSequenceKeypoint" or "NumberSequenceKeypoint";

							if #keys == 1 and typeof(keys[1]) ~= want then
								return kind == "$cs" and ColorSequence.new(keys[1]) or NumberSequence.new(keys[1]);
							end;

							return kind == "$cs" and ColorSequence.new(keys) or NumberSequence.new(keys);
						end;
						if kind == "$e" then
							local category = Enum[t[2]];
							return category and category[t[3]] or nil;
						end;

						return nil;
					end;

					function REVIVE(value)
						if type(value) ~= "table" then return value end;

						local head = value[1];

						if type(head) == "string" and string.sub(head, 1, 1) == "$" then
							local built = tagged(value);

							if built ~= nil then return built end;
						end;

						for key, item in pairs(value) do value[key] = REVIVE(item) end;

						return value;
					end;

					if not Remote.ensure(REL) then
						warn("[visuals] weapon data missing: " .. REL);

						return;
					end;

					local decoded;

					do
						local function readTable()
							local body = Remote.body(REL);

							local ok, result = pcall(function()
								return HttpService:JSONDecode(body);
							end);

							return ok and type(result) == "table" and result or nil;
						end;

						decoded = readTable();

						if not decoded and Remote.repair(REL) then
							decoded = readTable();
						end;

						if not decoded then
							warn("[visuals] weapon data unreadable and could not be refetched");

							return;
						end;
					end;

					local MESHES = REVIVE(decoded);
					local nativeModels = {};
					local nativeToolModels = {};
					local nativeGrips = {};
					local nativeGripProfiles = {
					    BigKill = { signature = "Gun|196752330|79401392|159963965", c = { 0, -0.69999998807907, -0.30000001192093, 1, 0, 0, 0, 0, -1, 0, 1, 0 } },
					    DefaultGun = { signature = "Gun|196751820|79401392|91723031", c = { 0, -0.69999998807907, -0.30000001192093, 1, 0, 0, 0, 0, -1, 0, 1, 0 } },
					    DefaultKnife = { signature = "Knife|196750384|121944778|121944805", c = { 0, -1, -0.10000000149012, 1, 0, 0, 0, 1, 0, 0, 0, 1 } },
					    Harvester = { signature = "Gun|7800847534|7775027413|7775245551", c = { 0, -0.51093721389771, 0.34054040908813, 1, 0, 0, 0, 1, 0, 0, 0, 1 } },
					    Icepiercer = { signature = "Gun|11874071041|11868991644|11869075814", c = { 0, -0.53358709812164, 0.30556964874268, 1, 0, 0, 0, 1, 0, 0, 0, 1 } },
					    Nightfire = { signature = "Gun|4659626966|79401392|4659577665", c = { 0, -0.69999998807907, -0.30000001192093, 1, 0, 0, 0, 0, -1, 0, 1, 0 } },
					    Reindeer_K_2024 = { signature = "Knife|109101361674956|6600901997|121109734938655", c = { 0, -1, -0.10000000149012, 1, 0, 0, 0, 1, 0, 0, 0, 1 } },
					    Snowball_G_2025 = { signature = "Gun|104416405402940|6600918074|81738515769034", c = { 0.69972610473633, -0.3059800863266, 0.0010890960693359, 0, 0, 1, 0, 1, 0, -1, 0, 0 } },
					    Star = { signature = "Gun|203807904|79401392|161642996", c = { 0, -0.69999998807907, -0.30000001192093, 1, 0, 0, 0, 0, -1, 0, 1, 0 } },
					    Sugar = { signature = "Gun|332848695|101086719|101086650", c = { -0.099999956786633, 0.53701812028885, 0.85152173042297, -1, 0, 0, 0, -1, 0, 0, 0, 1 } },
					    Waves_K = { signature = "Knife|13945892398|13916938702|13916939964", c = { 0, -1.1823897361755, -0.037742614746094, 1, 0, 0, 0, 1, 0, 0, 0, 1 } },
					    ZombieBat = { signature = "Knife|11229814357|11182796403|11192090515", c = { 0, -1.3500022888184, -0.049995422363281, 1, 0, 0, 0, 1, 0, 0, 0, 1 } },
					};
					local canonicalGrips = {
					    Knife = CFrame.new(0, -1, -0.1),
					    Gun = CFrame.new(0, -0.7, -0.3, 1, 0, 0, 0, 0, -1, 0, 1, 0),
					};
					-- where each item hangs, learnt from players wearing it: "mesh|texture"
					-- -> body attachment. Keyed by the item, not the mesh: one knife mesh
					-- (121944778) is worn on the back as Clan or Elite and on the belt as
					-- Chips, so a mesh-only key put half of those knives in the wrong place.
					local nativeBodyMounts = {};
					local mountChanged;
					local nativeSounds = {
					    Harvester = { SoundId = "rbxassetid://7808472682", Volume = 1, PlaybackSpeed = 1.4 },
					    Icepiercer = { SoundId = "rbxassetid://7808472682", Volume = 1, PlaybackSpeed = 1.4 },
					};
					local learnNative;

					local ProfileData, EquipService;

					do
						local services = ReplicatedStorage:FindFirstChild("ClientServices");
						local modules = ReplicatedStorage:FindFirstChild("Modules");

						pcall(function()
							ProfileData = require(modules:WaitForChild("ProfileData", 5));
							EquipService = require(services:WaitForChild("EquipService", 5));
						end);
					end;

					local INGAME = ProfileData ~= nil;

					local function trimAsset(value)
						if type(value) == "string" then
							return (string.gsub(string.gsub(value, "^%s+", ""), "%s+$", ""));
						end;

						return value;
					end;

					local function applyProps(instance, props, skip)
						for key, value in pairs(props or {}) do
							if not (skip and skip[key]) then
								if key == "MeshId" or key == "TextureId" or key == "TextureID" or key == "Texture" then
									value = trimAsset(value);
								end;

								pcall(function() instance[key] = value end);
							end;
						end;
					end;

					local function deadline(fn, seconds)
						local done, value = false, nil;

						task.spawn(function()
							local ok, result = pcall(fn);

							if ok then value = result end;

							done = true;
						end);

						local stop = os.clock() + seconds;

						while not done and os.clock() < stop do task.wait(0.05) end;

						return done and value or nil;
					end;

					local nativeSize = {};

					local function createMeshPart(props)
						local meshId = trimAsset(props.MeshId or "");
						local key = string.match(meshId, "(%d+)%s*$") or meshId;
						local size = props.Size or Vector3.new(1, 1, 1);
						local part;

						for attempt = 1, 2 do
							local made = deadline(function()
								return game:GetService("InsertService"):CreateMeshPartAsync(
									meshId, Enum.CollisionFidelity.Box, Enum.RenderFidelity.Precise);
							end, 6);

							if typeof(made) == "Instance" then part = made end;

							if not part then
								made = deadline(function()
									return game:GetService("AssetService"):CreateMeshPartAsync(Content.fromUri(meshId));
								end, 6);

								if typeof(made) == "Instance" then part = made end;
							end;

							if part then break end;

							task.wait(0.4);
						end;

						if part then
							pcall(function() nativeSize[key] = part.MeshSize end);
							pcall(function() part.Size = size end);

							return part;
						end;

						local native = nativeSize[key];

						if not (native and native.X > 0 and native.Y > 0 and native.Z > 0) then return nil end;

						local fallback = Instance.new("Part");

						fallback.Size = size;

						local mesh = Instance.new("SpecialMesh");

						mesh.MeshType = Enum.MeshType.FileMesh;
						mesh.Scale = size / native;

						pcall(function() mesh.MeshId = meshId end);
						pcall(function() mesh.TextureId = trimAsset(props.TextureID or props.TextureId or "") end);

						mesh.Parent = fallback;

						return fallback;
					end;

					local function isChroma(name, data)
						if data.Meta and data.Meta.Chroma == true then return true end;

						return string.sub(name, -6) == "Chroma";
					end;

					-- MM2's own ChromaScript (PlayerScripts.WeaponVisuals) cycles every
					-- instance tagged ChromaPart / ChromaDecal / ChromaFire through red,
					-- yellow, green, cyan, blue, purple; tagging the skin's pieces lets it run
					-- the real thing, its own on/off setting included. The decals keep the
					-- chroma layer they come with.
					local function startChroma(overlay)
						local added = {};

						local function tag(item, name)
							if not CollectionService:HasTag(item, name) then
								CollectionService:AddTag(item, name);
								added[#added + 1] = { item, name };
							end;
						end;

						local items = overlay:GetDescendants();
						table.insert(items, overlay);
						local roles = 0;

						for _, item in ipairs(items) do
							local role = item:GetAttribute("MM2Chroma");

							if role then
								roles += 1;
								tag(item, role == "part" and "ChromaPart" or role == "decal" and "ChromaDecal" or "ChromaFire");
							end;
						end;

						-- a model without the tags written down: its decals and fire
						if roles == 0 then
							for _, item in ipairs(items) do
								if item:IsA("Decal") then tag(item, "ChromaDecal") elseif item:IsA("Fire") then tag(item, "ChromaFire") end;
							end;
						end;

						if #added == 0 then return nil end;

						return {
							Disconnect = function()
								for _, entry in ipairs(added) do pcall(CollectionService.RemoveTag, CollectionService, entry[1], entry[2]) end;
								table.clear(added);
							end,
						};
					end;

					local STRUCTURAL = {
						WeldConstraint = true, Weld = true, Motor6D = true, RigidConstraint = true,
						Bone = true, Snap = true, ManualWeld = true, Rotate = true, RotateP = true, RotateV = true,
					};

					local PARTICLE_CLASSES = {
						ParticleEmitter = true, Fire = true, Smoke = true, Sparkles = true,
						PointLight = true, SpotLight = true, SurfaceLight = true,
					};

					local function chromaTag(instance, node)
						if not (instance and node.Tags) then return end;

						for _, name in ipairs(node.Tags) do
							local role = (name == "ChromaPart" and "part")
								or (name == "ChromaDecal" and "decal")
								or (name == "ChromaFire" and "fire") or nil;

							if role then
								pcall(function() instance:SetAttribute("MM2Chroma", role) end);
							end;
						end;
					end;

					local function instantiateNode(node)
						local class = node.Class;

						if STRUCTURAL[class] then return nil end;

						-- a SurfaceAppearance the database kept without its maps paints the
						-- mesh plain white over its texture (Constellation): leave it out
						if class == "SurfaceAppearance" and not tostring((node.Props or {}).ColorMap or ""):match("%d") then return nil end;

						local instance;

						if class == "MeshPart" then
							instance = createMeshPart(node.Props);

							if not instance then return nil end;

							applyProps(instance, node.Props, { MeshId = true, Size = true, RelCF = true, CanCollide = true });
						else
							local ok, made = pcall(Instance.new, class);

							if not ok or not made then return nil end;

							instance = made;

							applyProps(instance, node.Props, { RelCF = true });
						end;

						chromaTag(instance, node);

						if type(node.Name) == "string" then
							pcall(function() instance.Name = node.Name end);
						end;

						return instance;
					end;

					local function rebuildTree(node, parentInstance, root, idToInstance, parts, deferred)
						for _, child in ipairs(node.Children or {}) do
							local instance = instantiateNode(child);

							if not instance then

								rebuildTree(child, parentInstance, root, idToInstance, parts, deferred);
							else
								idToInstance[child.Id] = instance;

								if instance:IsA("BasePart") then
									instance.Anchored, instance.CanCollide, instance.CanQuery, instance.CanTouch, instance.Massless =
										false, false, false, false, true;

									parts[#parts + 1] = { inst = instance, relcf = child.Props and child.Props.RelCF };
									instance.Parent = root;
								elseif instance:IsA("Attachment") then
									if child.Props and child.Props.RelCF then
										pcall(function() instance.CFrame = child.Props.RelCF end);
									end;

									instance.Parent = root;
								elseif instance:IsA("Beam") or instance:IsA("Trail") then
									instance.Parent = parentInstance;

									deferred[#deferred + 1] = { inst = instance, a0 = child.Att0, a1 = child.Att1 };
								else
									instance.Parent = parentInstance;
								end;

								rebuildTree(child, instance, root, idToInstance, parts, deferred);
							end;
						end;
					end;

					local function buildFullOverlay(data)
						local node = data.Model;

						if not node then return nil end;

						local root;

						if node.Class == "MeshPart" then
							root = createMeshPart(node.Props);

							if not root then return nil end;

							applyProps(root, node.Props, { MeshId = true, Size = true, RelCF = true, CanCollide = true });
						else
							root = Instance.new("Part");

							applyProps(root, node.Props, { RelCF = true, CanCollide = true });
						end;

						chromaTag(root, node);

						root.Anchored, root.CanCollide, root.CanQuery, root.CanTouch, root.Massless =
							false, false, false, false, true;

						local idToInstance = { [node.Id] = root };
						local parts, deferred = {}, {};

						rebuildTree(node, root, root, idToInstance, parts, deferred);

						for _, item in ipairs(deferred) do
							if item.a0 and idToInstance[item.a0] then
								pcall(function() item.inst.Attachment0 = idToInstance[item.a0] end);
							end;

							if item.a1 and idToInstance[item.a1] then
								pcall(function() item.inst.Attachment1 = idToInstance[item.a1] end);
							end;
						end;

						return { root = root, parts = parts };
					end;

					local function buildFlatOverlay(data)
						local root, meshes, decals, effects = nil, {}, {}, {};

						for _, entry in ipairs(data.Display or {}) do
							if entry.Path == "(root)" then
								root = entry;
							elseif entry.Class == "SpecialMesh" then
								meshes[#meshes + 1] = entry;
							elseif entry.Class == "Decal" or entry.Class == "Texture" then
								decals[#decals + 1] = entry;
							elseif PARTICLE_CLASSES[entry.Class] then
								effects[#effects + 1] = entry;
							end;
						end;

						if not root then return nil end;

						if root.Class ~= "MeshPart" and #meshes == 0 and #decals == 0 then return nil end;

						local part;

						if root.Class == "MeshPart" then
							part = createMeshPart(root.Props);

							if not part then return nil end;

							applyProps(part, root.Props, { MeshId = true, Size = true, CanCollide = true });
						else
							part = Instance.new("Part");
							part.Size = root.Props.Size or Vector3.new(1, 1, 1);

							applyProps(part, root.Props, { Size = true, CanCollide = true });

							for _, entry in ipairs(meshes) do
								local mesh = Instance.new("SpecialMesh");

								mesh.MeshType = Enum.MeshType.FileMesh;

								applyProps(mesh, entry.Props);

								mesh.Parent = part;
							end;
						end;

						part.Anchored, part.CanCollide, part.CanQuery, part.CanTouch, part.Massless =
							false, false, false, false, true;

						for _, entry in ipairs(decals) do
							local decal = Instance.new("Decal");

							applyProps(decal, entry.Props);

							decal.Parent = part;
						end;

						for _, entry in ipairs(effects) do
							local ok, instance = pcall(Instance.new, entry.Class);

							if ok and instance then
								applyProps(instance, entry.Props);

								instance.Parent = part;
							end;
						end;

						return { root = part, parts = {} };
					end;

					local function buildNativeOverlay(data, held)
					    local template;
					    if held then template = nativeToolModels[data] else template = nativeModels[data] end;
					    if not template then return nil end;
					    local root = template:Clone();
					    local parts = {};
					    for _, item in ipairs(root:GetDescendants()) do
					        if STRUCTURAL[item.ClassName] or item:IsA("Script") or item:IsA("LocalScript") then
					            item:Destroy();
					        elseif item:IsA("BasePart") then
					            parts[#parts + 1] = { inst = item, relcf = root.CFrame:ToObjectSpace(item.CFrame) };
					            item.Anchored, item.CanCollide, item.CanQuery, item.CanTouch, item.Massless = false, false, false, false, true;
					        end;
					    end;
					    root.Anchored, root.CanCollide, root.CanQuery, root.CanTouch, root.Massless = false, false, false, false, true;
					    return { root = root, parts = parts };
					end;

					local function buildAnyOverlay(data, held)
					    local native = buildNativeOverlay(data, held);
					    if native then return native end;
						if data.Model then return buildFullOverlay(data) end;
						if data.Display then return buildFlatOverlay(data) end;

						return nil;
					end;

					local function finalizeOverlay(built, targetCF)
						local root = built.root;
						pcall(function() root:SetAttribute("VisualsSkin", true) end);
						Render.DepthTree(root, false);

						pcall(function() root.CFrame = targetCF end);

						for _, part in ipairs(built.parts) do
							if part.relcf then
								pcall(function() part.inst.CFrame = targetCF * part.relcf end);
							end;

							local weld = Instance.new("WeldConstraint");

							weld.Part0 = part.inst;
							weld.Part1 = root;
							weld.Parent = part.inst;
						end;

						return root;
					end;

					local MOUNTS_FILE = userFile("skin mounts.json");
					local MOUNTS = {
						["6600918074"] = { c = { 0, -0.15, -0.05, 0, -0.7661, 0.6428, 0, 0.6428, 0.7661, -1, 0, 0 }, k = "part", s = 1.83 },
					};

					local function digits(id)
						return string.match(tostring(id or ""), "(%d+)%s*$");
					end;

					local function meshOf(part)
						local mesh = part:FindFirstChildOfClass("SpecialMesh");

						if mesh then return digits(mesh.MeshId), "mesh", mesh.Scale.X end;

						local ok, id = pcall(function() return part.MeshId end);
						local size = part.Size;

						return ok and digits(id) or nil, "part", math.max(size.X, size.Y, size.Z);
					end;

					do
						local ok, body = pcall(function() return readfile(MOUNTS_FILE) end);

						if ok and type(body) == "string" then
							local fine, saved = pcall(function() return HttpService:JSONDecode(body) end);

							if fine and type(saved) == "table" then
								for id, entry in pairs(saved) do
									if type(entry) == "table" and type(entry.c) == "table" and #entry.c == 12 then MOUNTS[id] = entry end;
								end;
							end;
						end;
					end;

					local BARRELS_FILE = userFile("skin muzzles.json");
					local barrels = {};

					do
						local ok, body = pcall(function() return readfile(BARRELS_FILE) end);

						if ok and type(body) == "string" then
							local fine, saved = pcall(function() return HttpService:JSONDecode(body) end);

							if fine and type(saved) == "table" then
								for id, v in pairs(saved) do
									if type(v) == "table" and #v == 3 then barrels[id] = Vector3.new(v[1], v[2], v[3]) end;
								end;
							end;
						end;
					end;

					local function barrelOf(id)
						if not id then return nil end;
						if barrels[id] ~= nil then return barrels[id] or nil end;

						barrels[id] = false;

						local part = deadline(function()
							return game:GetService("InsertService"):CreateMeshPartAsync("rbxassetid://" .. id,
								Enum.CollisionFidelity.PreciseConvexDecomposition, Enum.RenderFidelity.Performance);
						end, 8);

						if typeof(part) ~= "Instance" then return nil end;

						pcall(function() nativeSize[id] = nativeSize[id] or part.MeshSize end);

						part.Anchored, part.CanCollide, part.CanQuery, part.CanTouch, part.Transparency = true, false, true, false, 1;
						part.CFrame = CFrame.new(0, 20000, 0);
						part.Parent = workspace;

						local size = part.Size;
						local axes = { { size.X, Vector3.xAxis }, { size.Y, Vector3.yAxis }, { size.Z, Vector3.zAxis } };

						table.sort(axes, function(x, y) return x[1] > y[1] end);

						local long, mid, thin = axes[1], axes[2], axes[3];
						local params = RaycastParams.new();

						params.FilterType = Enum.RaycastFilterType.Include;
						params.FilterDescendantsInstances = { part };

						local N, K, grid = 20, 14, {};

						for i = 1, N do
							local u = ((i - 0.5) / N - 0.5) * long[1];

							grid[i] = {};

							for j = 1, K do
								local v = ((j - 0.5) / K - 0.5) * mid[1];
								local from = part.CFrame:PointToWorldSpace(long[2] * u + mid[2] * v + thin[2] * (thin[1] * 0.5 + 1));

								grid[i][j] = workspace:Raycast(from, part.CFrame:VectorToWorldSpace(-thin[2] * (thin[1] + 2)), params) ~= nil;
							end;
						end;

						part:Destroy();

						local band = {};

						for j = 1, K do
							local filled = 0;

							for i = 1, N do
								if grid[i][j] then filled += 1 end;
							end;

							band[j] = filled >= N / 2;
						end;

						local function outside(from, to)
							local count = 0;

							for i = from, to do
								for j = 1, K do
									if grid[i][j] and not band[j] then count += 1 end;
								end;
							end;

							return count;
						end;

						local function detached(from, to)
							local count = 0;

							for i = from, to do
								local runs, inRun, onBand = 0, false, false;
								local offBandRun = false;

								for j = 1, K do
									if grid[i][j] then
										if not inRun then
											runs += 1;
											inRun, onBand = true, false;
										end;

										onBand = onBand or band[j];
									elseif inRun then
										inRun = false;

										if not onBand then offBandRun = true end;
									end;
								end;

								if inRun and not onBand then offBandRun = true end;
								if runs >= 2 and offBandRun then count += 1 end;
							end;

							return count;
						end;

						local low, high = outside(1, 5), outside(N - 4, N);
						local gripLow;

						if math.abs(low - high) >= 3 then
							gripLow = low > high;
						else
							local dLow, dHigh = detached(1, 6), detached(N - 5, N);

							if math.abs(dLow - dHigh) < 2 then return nil end;

							gripLow = dLow > dHigh;
						end;

						local dir = gripLow and long[2] or -long[2];

						barrels[id] = dir;

						pcall(function()
							local out = {};

							for key, v in pairs(barrels) do
								if v then out[key] = { v.X, v.Y, v.Z } end;
							end;

							writefile(BARRELS_FILE, HttpService:JSONEncode(out));
						end);

						return dir;
					end;

					local mountsDirty = false;

					local function itemKey(part, id)
					    local mesh = not part:IsA("MeshPart") and part:FindFirstChildWhichIsA("SpecialMesh");
					    local texture = part:IsA("MeshPart") and part.TextureID or (mesh and mesh.TextureId) or "";
					    return id .. "|" .. (tostring(texture):match("%d+") or "");
					end;

					local function learnMount(part)
					    if learnNative then learnNative(part) end;
					    if not part:IsA("BasePart") or part:GetAttribute("VisualsSkin") then return end;
					    local id, kind, size = meshOf(part);
					    if not id then return end;
					    local key = itemKey(part, id);
					    for _, constraint in ipairs(part:GetDescendants()) do
					        if constraint:IsA("RigidConstraint") then
					            for _, attachment in pairs({ constraint.Attachment0, constraint.Attachment1 }) do
					                local body = attachment and attachment.Parent;
					                local character = body and body.Parent;
					                if attachment and not attachment:IsDescendantOf(part) and body and body:IsA("BasePart")
										and character and game:GetService("Players"):GetPlayerFromCharacter(character) then
										local old = nativeBodyMounts[key];
										nativeBodyMounts[key] = { name = attachment.Name, part = body.Name };
										if mountChanged and (not old or old.name ~= attachment.Name or old.part ~= body.Name) then
										    task.defer(mountChanged, key);
										end;
										break;
					                end;
					            end;
					        end;
					    end;
					    local attachment = part:FindFirstChild("CustomAttachment");
					    if not (attachment and attachment:IsA("Attachment")) or MOUNTS[id] then return end;
					    MOUNTS[id] = { c = { attachment.CFrame:GetComponents() }, k = kind, s = size };
					    mountsDirty = true;
					end;

					local function saveMounts()
						if not mountsDirty then return end;

						mountsDirty = false;

						pcall(function() writefile(MOUNTS_FILE, HttpService:JSONEncode(MOUNTS)) end);
					end;

					local function beltOf(base)
						for _, item in ipairs(base:GetDescendants()) do
							if item:IsA("RigidConstraint") then
								for _, attachment in ipairs({ item.Attachment0, item.Attachment1 }) do
									if attachment and not attachment:IsDescendantOf(base) then return attachment end;
								end;
							end;
						end;
						return nil;
					end;

					local function seatFor(root, base)
						local mine = root:FindFirstChild("CustomAttachment") or root:FindFirstChild("Attachment");
						local theirs = base:FindFirstChild("CustomAttachment");

						local belt = beltOf(base);

						if belt then
							if mine and mine:IsA("Attachment") then return belt.WorldCFrame * mine.CFrame:Inverse() end;

							local id, kind, size = meshOf(root);
							local mount = id and MOUNTS[id];

							if mount then
								local at = CFrame.new(table.unpack(mount.c));

								if mount.k == kind and (mount.s or 0) > 0 and size > 0 then
									at = CFrame.new(at.Position * (size / mount.s)) * at.Rotation;
								end;

								return belt.WorldCFrame * at:Inverse();
							end;

							return belt.WorldCFrame;
						end;

						if mine and theirs and mine:IsA("Attachment") and theirs:IsA("Attachment") then
							return theirs.WorldCFrame * mine.CFrame:Inverse();
						end;

						local id, kind, size = meshOf(root);
						local mount = id and MOUNTS[id];

						if mount and theirs and theirs:IsA("Attachment") then
							local at = CFrame.new(table.unpack(mount.c));

							if mount.k == kind and (mount.s or 0) > 0 and size > 0 then
								at = CFrame.new(at.Position * (size / mount.s)) * at.Rotation;
							end;

							return theirs.WorldCFrame * at:Inverse();
						end;

						local function ranked(part)
							local size = part.Size;
							local list = { { size.X, Vector3.xAxis }, { size.Y, Vector3.yAxis }, { size.Z, Vector3.zAxis } };

							table.sort(list, function(x, y) return x[1] > y[1] end);

							return list;
						end;

						local a, b = ranked(root), ranked(base);
						local seat = base.CFrame;

						if a[1][1] >= a[2][1] * 1.25 and b[1][1] >= b[2][1] * 1.25 then

							local function column(e)
								local v = Vector3.zero;

								for i = 1, 3 do v += b[i][2] * a[i][2]:Dot(e) end;

								return v;
							end;

							local vx, vy, vz = column(Vector3.xAxis), column(Vector3.yAxis), column(Vector3.zAxis);

							if vx:Cross(vy):Dot(vz) < 0 then vz = -vz end;

							seat = base.CFrame * CFrame.fromMatrix(Vector3.zero, vx, vy, vz);
						end;

						local muzzle = barrelOf((meshOf(root)));

						if muzzle then
							local want;
							local theirsMuzzle = barrelOf((meshOf(base)));

							if theirsMuzzle then
								want = base.CFrame:VectorToWorldSpace(theirsMuzzle);
							elseif base.Name == "GunDisplay" or base.Name == "KnifeDisplay" then
								want = Vector3.new(0, -1, 0);
							end;

							if want and seat:VectorToWorldSpace(muzzle):Dot(want) < 0 then
								seat = seat * CFrame.fromAxisAngle(a[3][2], math.pi);
							end;
						end;

						return seat;
					end;

					local function displaySeat(root, base)
					    local id, kind, size = meshOf(root);
					    local location = id and nativeBodyMounts[itemKey(root, id)];
					    local character = LocalPlayer.Character;
					    local body = location and character and character:FindFirstChild(location.part);
					    local point = body and body:FindFirstChild(location.name);
					    if not point and location and character then point = character:FindFirstChild(location.name, true) end;
					    if not point and character then
					        -- an item nobody here wears: it hangs where the one it covers hangs
					        for _, constraint in ipairs(base:GetDescendants()) do
					            if constraint:IsA("RigidConstraint") then
					                for _, attachment in ipairs({ constraint.Attachment0, constraint.Attachment1 }) do
					                    if attachment and attachment:IsDescendantOf(character) then point = attachment; break end;
					                end;
					            end;
					            if point then break end;
					        end;
					    end;
					    if not (point and point:IsA("Attachment")) then return seatFor(root, base) end;
					    local anchor = root:FindFirstChild("CustomAttachment") or root:FindFirstChild("Attachment");
					    if not (anchor and anchor:IsA("Attachment")) then
					        anchor = Instance.new("Attachment");
					        local mount = id and MOUNTS[id];
					        if mount then
					            local at = CFrame.new(table.unpack(mount.c));
					            if mount.k == kind and (mount.s or 0) > 0 and size > 0 then
					                at = CFrame.new(at.Position * (size / mount.s)) * at.Rotation;
					            end;
					            anchor.CFrame = at;
					        end;
					        anchor.Parent = root;
					    end;
					    return point.WorldCFrame * anchor.CFrame:Inverse(), point, anchor;
					end;

					local function targetMeshId(data)
						if data.Model then
							local node = data.Model;

							if node.Class == "MeshPart" then
								return trimAsset(node.Props.MeshId or ""), trimAsset(node.Props.TextureID or "");
							end;

							for _, child in ipairs(node.Children or {}) do
								if child.Class == "SpecialMesh" then
									return trimAsset(child.Props.MeshId or ""), trimAsset(child.Props.TextureId or "");
								end;
							end;

							return "", "";
						end;

						for _, entry in ipairs(data.Display or {}) do
							if entry.Path == "(root)" and entry.Class == "MeshPart" then
								return trimAsset(entry.Props.MeshId or ""), trimAsset(entry.Props.TextureID or "");
							end;

							if entry.Class == "SpecialMesh" then
								return trimAsset(entry.Props.MeshId or ""), trimAsset(entry.Props.TextureId or "");
							end;
						end;

						return "", "";
					end;

					local function baseMeshId(base)
						if not base then return "", "" end;
						if base:IsA("MeshPart") then return trimAsset(base.MeshId or ""), trimAsset(base.TextureID or "") end;

						local mesh = base:FindFirstChildWhichIsA("SpecialMesh", true);

						return mesh and trimAsset(mesh.MeshId or "") or "", mesh and trimAsset(mesh.TextureId or "") or "";
					end;

					local GRIPS_FILE = userFile("skin grips.json");
					local gripsSavePending = false;
					local function gripSignature(data)
					    local meta = data and data.Meta;
					    local item = meta and tonumber(meta.ItemID);
					    local mesh, texture;
					    if data then mesh, texture = targetMeshId(data) end;
					    mesh = digits(mesh);
					    if not item or item ~= item or item <= 0 or item == math.huge or not mesh then return end;
					    return table.concat({ meta.ItemType or "", string.format("%.0f", item), mesh, digits(texture) or "" }, "|");
					end;
					local function acceptGrip(name, profile)
					    local signature = gripSignature(MESHES[name]);
					    if not signature or type(profile) ~= "table" or profile.signature ~= signature
					        or type(profile.c) ~= "table" or #profile.c ~= 12 then return false end;
					    for _, value in ipairs(profile.c) do
					        if type(value) ~= "number" or value ~= value or math.abs(value) == math.huge then return false end;
					    end;
					    nativeGripProfiles[name] = { signature = profile.signature, c = table.clone(profile.c) };
					    nativeGrips[name] = CFrame.new(table.unpack(profile.c));
					    return true;
					end;
					local function saveGrips()
					    if gripsSavePending then return end;
					    gripsSavePending = true;
					    task.defer(function()
					        gripsSavePending = false;
					        pcall(function() writefile(GRIPS_FILE, HttpService:JSONEncode({ version = 1, profiles = nativeGripProfiles })) end);
					    end);
					end;
					do
					    for name, profile in pairs(nativeGripProfiles) do
					        if not acceptGrip(name, profile) then nativeGripProfiles[name] = nil end;
					    end;
					    local ok, body = pcall(function() return readfile(GRIPS_FILE) end);
					    if ok and type(body) == "string" then
					        local decoded, saved = pcall(function() return HttpService:JSONDecode(body) end);
					        if decoded and type(saved) == "table" and saved.version == 1 and type(saved.profiles) == "table" then
					            for name, profile in pairs(saved.profiles) do acceptGrip(name, profile) end;
					        end;
					    end;
					end;

					-- a gun's own shot sound (AltSound), learnt from anyone's display or gun
					-- and kept across sessions: the database has the sound but not its id
					local SOUNDS_FILE = userFile("skin sounds.json");
					do
					    local ok, body = pcall(function() return readfile(SOUNDS_FILE) end);
					    local fine, saved = false, nil;
					    if ok and type(body) == "string" then fine, saved = pcall(function() return HttpService:JSONDecode(body) end) end;
					    if fine and type(saved) == "table" then
					        for name, spec in pairs(saved) do
					            if type(spec) == "table" and type(spec.SoundId) == "string" and nativeSounds[name] == nil then nativeSounds[name] = spec end;
					        end;
					    end;
					end;
					local function rememberSound(name, sound)
					    local spec = { SoundId = sound.SoundId, PlaybackSpeed = sound.PlaybackSpeed };
					    if sound.Volume > 0 then spec.Volume = sound.Volume end;
					    local old = nativeSounds[name];
					    nativeSounds[name] = spec;
					    if old and old.SoundId == spec.SoundId then return end;
					    task.defer(function() pcall(function() writefile(SOUNDS_FILE, HttpService:JSONEncode(nativeSounds)) end) end);
					end;

					-- which item a worn display is: its mesh and texture, and whether the
					-- game tagged it chroma (a chroma and a plain twin share both)
					local itemIndex;
					local function itemOf(part, slot)
					    if not itemIndex then
					        itemIndex = {};
					        for key, data in pairs(MESHES) do
					            local wantMesh, wantTexture = targetMeshId(data);
					            if data.Meta and digits(wantMesh) then
					                local sig = tostring(data.Meta.ItemType) .. "|" .. digits(wantMesh) .. "|" .. (digits(wantTexture) or "");
					                local entry = itemIndex[sig] or {};
					                itemIndex[sig] = entry;
					                if isChroma(key, data) then entry.chroma = entry.chroma or key else entry.plain = entry.plain or key end;
					            end;
					        end;
					    end;
					    local mesh, texture = baseMeshId(part);
					    local entry = digits(mesh) and itemIndex[slot .. "|" .. digits(mesh) .. "|" .. (digits(texture) or "")];
					    if not entry then return nil end;
					    local chroma = false;
					    for _, item in ipairs(part:GetDescendants()) do
					        if CollectionService:HasTag(item, "ChromaDecal") or CollectionService:HasTag(item, "ChromaFire") or CollectionService:HasTag(item, "ChromaPart") then chroma = true; break end;
					    end;
					    if CollectionService:HasTag(part, "ChromaPart") then chroma = true end;
					    if chroma then return entry.chroma or entry.plain end;
					    return entry.plain or entry.chroma;
					end;

					-- any display worn by anyone: its exact model (drawn instead of the
					-- database copy) and its shot sound
					learnNative = function(part)
					    if not part:IsA("BasePart") or part:GetAttribute("VisualsSkin") then return end;
					    local slot = part.Name == "GunDisplay" and "Gun" or part.Name == "KnifeDisplay" and "Knife";
					    local name = slot and itemOf(part, slot);
					    local data = name and MESHES[name];
					    if not data then return end;
					    if nativeModels[data] then nativeModels[data]:Destroy() end;
					    local template = part:Clone();
					    template.Parent = nil;
					    for _, item in ipairs(template:GetDescendants()) do
					        if item:IsA("Sound") and item.Name == "AltSound" and item.SoundId ~= "" then rememberSound(name, item) end;
					    end;
					    nativeModels[data] = template;
					end;

					local function hideInto(list, instance)
					    local prop, hidden;
					    if instance:IsA("BasePart") or instance:IsA("Decal") or instance:IsA("Texture") then
					        prop, hidden = "Transparency", 1;
					    elseif instance:IsA("ParticleEmitter") or instance:IsA("Trail") or instance:IsA("Beam")
					        or instance:IsA("Fire") or instance:IsA("Smoke") or instance:IsA("Sparkles") or instance:IsA("Light") then
					        prop, hidden = "Enabled", false;
					    else
					        return;
					    end;
					    for _, entry in ipairs(list) do
					        if entry.inst == instance and entry.prop == prop then return end;
					    end;
					    local entry = { inst = instance, prop = prop, val = instance[prop] };
					    list[#list + 1] = entry;
					    local function hide()
					        if instance[prop] ~= hidden then instance[prop] = hidden end;
					    end;
					    entry.connection = instance:GetPropertyChangedSignal(prop):Connect(hide);
					    hide();
					end;
					
					local function restore(hidden)
					    for _, entry in ipairs(hidden or {}) do
					        if entry.connection then entry.connection:Disconnect() end;
					    end;
					    for _, entry in ipairs(hidden or {}) do
					        pcall(function() entry.inst[entry.prop] = entry.val end);
					    end;
					end;

					local alive = true;
					local conns = {};
					local named = {};

					local function keep(connection)
						if connection then conns[#conns + 1] = connection end;

						return connection;
					end;

					local function keepNamed(name, connection)
						if named[name] then pcall(function() named[name]:Disconnect() end) end;

						named[name] = connection;

						return connection;
					end;

					local function currentChar()
						return LocalPlayer.Character;
					end;

					local function displayValue(slot)
						local character = currentChar();

						if not character then return nil end;

						local ref = character:FindFirstChild("DisplayRef" .. slot);

						return ref and ref:IsA("ObjectValue") and ref.Value or nil;
					end;

					local function waitDisplay(slot, timeout)
						local deadline = os.clock() + (timeout or 1);

						while alive and os.clock() < deadline do
							local value = displayValue(slot);

							if value then return value end;

							task.wait(0.05);
						end;

						return displayValue(slot);
					end;

					local state, lastApplied, token = {}, {}, {};
					local worn = {};

					local function cleanup(slot)
						local current = state[slot];

						if not current then return end;

						state[slot] = nil;

						if current.descAdded then current.descAdded:Disconnect() end;

						if current.chroma then pcall(function() current.chroma:Disconnect() end) end;
						if current.overlay then pcall(function() current.overlay:Destroy() end) end;

						restore(current.hidden);
					end;

					local function apply(slot, name)
						if not alive or not host.Alive() then return end;
						if state[slot] and lastApplied[slot] == name and name ~= nil then return end;
						token[slot] = (token[slot] or 0) + 1;
						local mine = token[slot];
						cleanup(slot);
						local data = name and MESHES[name];
						lastApplied[slot] = name;
						if not data then return end;
						local built, record;
						local ok, err = pcall(function()
							local base = displayValue(slot) or waitDisplay(slot, 1.5);
							if not alive or not host.Alive() or token[slot] ~= mine or not base then return end;

							local baseMesh, baseTexture = baseMeshId(base);
							local skinMesh, skinTexture = targetMeshId(data);
							if not isChroma(name, data) and baseMesh ~= "" and baseMesh == skinMesh and baseTexture == skinTexture then return end;
							built = buildAnyOverlay(data);
							if not alive or not host.Alive() or not built or not built.root or token[slot] ~= mine or not base.Parent then return end;
							local seat, point, anchor = displaySeat(built.root, base);
							finalizeOverlay(built, seat);
							local overlay = built.root;
							if point then
							    local constraint = Instance.new("RigidConstraint");
							    constraint.Attachment0, constraint.Attachment1, constraint.Parent = point, anchor, overlay;
							else
							    local weld = Instance.new("WeldConstraint");
							    weld.Part0, weld.Part1, weld.Parent = overlay, base, overlay;
							end;
							record = {overlay=overlay, hidden={}, chroma=isChroma(name, data) and startChroma(overlay) or nil};
							overlay.Parent = base.Parent;
							state[slot] = record;
							hideInto(record.hidden, base);
							for _, item in ipairs(base:GetDescendants()) do
								if item ~= overlay and not item:IsDescendantOf(overlay) then hideInto(record.hidden, item) end;
							end;
							record.descAdded = base.DescendantAdded:Connect(function(item)
                                if state[slot] == record then hideInto(record.hidden, item) end;
                            end);
                            record.committed = true;
						end);
						if not record or not record.committed then
							if record and state[slot] == record then cleanup(slot) end;
							if record and record.chroma then pcall(function() record.chroma:Disconnect() end) end;
							if built and built.root then pcall(function() built.root:Destroy() end) end;
							if token[slot] == mine then lastApplied[slot] = nil end;
						end;
						if not ok then recordError("skin display: " .. tostring(err)) end;
					end;

					local toolState = {};
					local weaponThumbnail, rememberNativeEquipped;
					mountChanged = function(key)
					    if not alive then return end;
					    for slot, current in pairs(state) do
					        local id = current.overlay and meshOf(current.overlay);
					        if id and itemKey(current.overlay, id) == key then
					            local skin = worn[slot] or lastApplied[slot];
					            cleanup(slot);
					            if skin then task.spawn(apply, slot, skin) end;
					        end;
					    end;
					end;

					local function isMine(instance)
						if instance:IsDescendantOf(LocalPlayer) then return true end;

						local character = currentChar();

						return character ~= nil and instance:IsDescendantOf(character);
					end;

					local function unoverlayTool(tool)
						local current = toolState[tool];

						if not current then return end;

						toolState[tool] = nil;

						if current.descAdded then current.descAdded:Disconnect() end;
						if current.hotbarConn then current.hotbarConn:Disconnect() end;

						if current.chroma then pcall(function() current.chroma:Disconnect() end) end;
					    if current.overlay then pcall(function() current.overlay:Destroy() end) end;
					    if current.beam then pcall(function() current.beam:Destroy() end) end;
					    if current.nativeBeam then pcall(function() current.nativeBeam.Parent = tool end) end;
					    restore(current.hidden);
					end;

					local function learnNativeTool(tool, slot)
					    if toolState[tool] or not tool:IsA("Tool") or not tool:HasTag("Weapon_" .. slot) then return end;
					    if isMine(tool) and rememberNativeEquipped then rememberNativeEquipped(slot, tool:GetAttribute("ItemID")) end;
					    local handle = tool:FindFirstChild("Handle");
					    if not (handle and handle:IsA("BasePart")) then return end;
					    local sound;
					    if slot == "Gun" then
					        for _, item in ipairs(tool:GetDescendants()) do
					            if item:IsA("Sound") and item.SoundId ~= "" then
					                local name = item.Name:lower();
					                if name == "altsound" then sound = item; break
					                elseif not sound and (name == "gunshot" or name == "shoot") then sound = item end;
					            end;
					        end;
					    end;
					    local mesh, texture = baseMeshId(handle);
					    local itemKey = tool:GetAttribute("ItemID");
					    local identified = type(itemKey) == "string" and MESHES[itemKey];
					    local data = identified;
					    if not data or not data.Meta or data.Meta.ItemType ~= slot then return end;
					    local wantMesh, wantTexture = targetMeshId(data);
					    if not digits(mesh) or digits(mesh) ~= digits(wantMesh) or digits(texture) ~= digits(wantTexture) then return end;
					    local old = nativeGrips[itemKey];
					    if acceptGrip(itemKey, { signature = gripSignature(data), c = { tool.Grip:GetComponents() } }) and old ~= tool.Grip then saveGrips() end;
					    if nativeToolModels[data] then nativeToolModels[data]:Destroy() end;
					    nativeToolModels[data] = handle:Clone();
					    nativeToolModels[data].Parent = nil;
					    if sound and sound.Name:lower() == "altsound" then rememberSound(itemKey, sound) end;
					end;

					-- A grip nobody has been seen holding yet is worked out below; every
					-- knife and gun was checked in the hand on 2026-10-05. Guns whose mesh is
					-- drawn a quarter turn from the classic one (grip up at the hand, barrel
					-- down next to BigKill): Laser / Laser Chroma, Amerilaser, Spectre 2022
					local GRIP_TURNS = {
					    ["130099641"] = CFrame.Angles(math.rad(-90), 0, 0),
					    ["116657254"] = CFrame.Angles(math.rad(-90), 0, 0),
					    ["11165536294"] = CFrame.Angles(math.rad(-90), 0, 0),
					};

					-- the chroma copy of a new gun is a Part wearing the MeshPart twin's mesh
					-- (Raygun, Snowcannon, Traveler, Tree 2023, Vampire); it is held like
					-- the twin, measured on the twin's own size
					local meshPartTwins;
					local function twinSize(id)
					    if not meshPartTwins then
					        meshPartTwins = {};
					        for _, data in pairs(MESHES) do
					            local node = data.Model;
					            if node and node.Class == "MeshPart" and node.Props and typeof(node.Props.Size) == "Vector3" then
					                local mesh = digits(tostring(node.Props.MeshId or ""));
					                if mesh and not meshPartTwins[mesh] then meshPartTwins[mesh] = node.Props.Size end;
					            end;
					        end;
					    end;
					    return id and meshPartTwins[id];
					end;

					-- a new (MeshPart) weapon is held along its long axis at a point that
					-- scales with its size: fitted to the grips seen worn (Harvester,
					-- Icepiercer, Snowball, Waves, Zombie Bat) within ~0.1 stud
					local function shapeGrip(size, slot)
					    local longX = size.X >= size.Y and size.X >= size.Z;
					    local longY = not longX and size.Y >= size.Z;
					    if slot == "Knife" then return longY and CFrame.new(0, -size.Y * 0.32, -0.05) or canonicalGrips.Knife end;
					    if longX then return CFrame.new(size.X * 0.38, -size.Y * 0.32, 0, 0, 0, 1, 0, 1, 0, -1, 0, 0) end;
					    if not longY then return CFrame.new(0, -size.Y * 0.78, size.Z * 0.12) end;
					    return canonicalGrips.Gun;
					end;

					local function guessGrip(root, slot)
					    local id = meshOf(root);
					    local turned = GRIP_TURNS[id or ""];
					    if turned then return turned * canonicalGrips[slot] end;
					    if root:IsA("MeshPart") then return shapeGrip(root.Size, slot) end;
					    local twin = twinSize(id);
					    if twin then return shapeGrip(twin, slot) end;
					    -- a classic weapon is held like the classic one, in the frame its
					    -- CustomAttachment mounts it by on the belt: Sugar 5 deg and Shark
					    -- 0 deg off; Tides, Clockwork, Ice Shard and Handsaw stopped
					    -- pointing at the floor or the sky
					    local mount = root:FindFirstChild("CustomAttachment");
					    if mount and mount:IsA("Attachment") then return mount.CFrame * canonicalGrips[slot] end;
					    -- the oldest knives lie along Z (a 0.6 x 0.4 x 2.4 block): Blood,
					    -- Ghost, Knife1, Shadow and Time Knife, blade towards +Z
					    if slot == "Knife" and root.Size.Z > root.Size.Y * 2 then
					        return CFrame.Angles(math.rad(90), 0, 0) * canonicalGrips.Knife;
					    end;
					    return canonicalGrips[slot];
					end;

					-- The oldest knives (Shadow, Ghost, Knife1, Blood, Time) are drawn at
					-- 1.6-2.4 studs where every other knife is about 3 (Default 3.0, Candy
					-- 2.9, Ice Dragon 3.2): in the hand they are brought up to 3 studs. The
					-- belt keeps the database size, which is what the game shows there.
					local function meshSizeOf(id)
					    if not id then return nil end;
					    if nativeSize[id] then return nativeSize[id] end;
					    local part = deadline(function()
					        return game:GetService("InsertService"):CreateMeshPartAsync("rbxassetid://" .. id,
					            Enum.CollisionFidelity.Box, Enum.RenderFidelity.Performance);
					    end, 6);
					    if typeof(part) ~= "Instance" then return nil end;
					    nativeSize[id] = part.MeshSize;
					    part:Destroy();
					    return nativeSize[id];
					end;
					local function fitKnife(built)
					    local mesh = built.root:FindFirstChildOfClass("SpecialMesh");
					    if not mesh or #built.parts > 1 then return end;
					    local size = meshSizeOf(digits(mesh.MeshId));
					    if not size then return end;
					    local drawn = size * mesh.Scale;
					    local long = math.max(drawn.X, drawn.Y, drawn.Z);
					    if long <= 0 or long >= 2.5 then return end;
					    mesh.Scale *= 3 / long;
					    mesh.Offset *= 3 / long;
					end;

					local function heldSeat(root, tool, handle, slot, skin)
					    local current = tool.Grip;
					    local character = currentChar();
					    local hand = character and (character:FindFirstChild("RightHand") or character:FindFirstChild("Right Arm"));
					    local joint = hand and hand:FindFirstChild("RightGrip");
					    if joint and (joint:IsA("Weld") or joint:IsA("Motor6D")) and joint.Part1 == handle then current = joint.C1 end;
					    local target = nativeGrips[skin];
					    local profile = nativeGripProfiles[skin];
					    local mesh, texture = baseMeshId(root);
					    local data = MESHES[skin];
					    local wantMesh, wantTexture;
					    if data then wantMesh, wantTexture = targetMeshId(data) end;
					    if not profile or profile.signature ~= gripSignature(data)
					        or digits(mesh) ~= digits(wantMesh) or digits(texture) ~= digits(wantTexture) then target = nil end;
					    if not target and wantMesh and digits(wantMesh) then
					        -- one mesh is held one way whatever it is painted: the five guns on
					        -- mesh 79401392 and the classic knives share their grips, and Candy's
					        -- mesh is drawn upside down, which only a grip seen worn can know
					        local id = digits(wantMesh);
					        for key, grip in pairs(nativeGrips) do
					            local other = MESHES[key];
					            if other and other.Meta and other.Meta.ItemType == slot and digits((targetMeshId(other))) == id then target = grip; break end;
					        end;
					    end;
					    if not target then
					        local authored = root:FindFirstChild("RightGripAttachment") or root:FindFirstChild("GripAttachment");
					        target = authored and authored:IsA("Attachment") and authored.CFrame or guessGrip(root, slot);
					    end;
					    return handle.CFrame * current * target:Inverse();
					end;

					local function hotbarFrame(tool)
					    local inspect = getupvalues or (debug and debug.getupvalues);
					    if type(getconnections) ~= "function" or type(inspect) ~= "function" then return end;
					    local gui = LocalPlayer:FindFirstChild("PlayerGui");
					    local backpack = gui and gui:FindFirstChild("BackpackUI");
					    local frame = backpack and backpack:FindFirstChild("BackpackFrame");
					    if not frame then return end;
					    local ok, connections = pcall(getconnections, tool:GetPropertyChangedSignal("Parent"));
					    if not ok then return end;
					    for _, connection in ipairs(connections) do
					        local fn = connection.Function;
					        if type(fn) == "function" then
					            local found, values = pcall(inspect, fn);
					            if found then
					                local matches, candidate;
					                for _, value in pairs(values) do
										if value == tool then matches = true
										elseif typeof(value) == "Instance" and value.Parent == frame and value:IsA("GuiObject") then candidate = value end;
					                end;
					                if matches and candidate then return candidate end;
					            end;
					        end;
					    end;
					end;

					local function setToolValue(record, instance, property, value)
					    local saved = false;
					    for _, entry in ipairs(record.hidden) do
					        if entry.inst == instance and entry.prop == property then saved = true; break end;
					    end;
					    if not saved then record.hidden[#record.hidden + 1] = { inst = instance, prop = property, val = instance[property] } end;
					    instance[property] = value;
					end;

					local function refreshHotbar(tool, record)
					    if toolState[tool] ~= record then return end;
					    local frame = hotbarFrame(tool);
					    local container = frame and frame:FindFirstChild("Container");
					    local icon = container and container:FindFirstChild("ToolIcon");
					    local name = container and container:FindFirstChild("NameLabel");
					    if icon then setToolValue(record, icon, "Image", record.image) end;
					    if name then setToolValue(record, name, "Text", record.image == "" and record.label or "") end;
					end;

					local function purgeCopiedSkins(handle)
					    local scripts = LocalPlayer:FindFirstChild("PlayerScripts");
					    local visuals = scripts and scripts:FindFirstChild("ToolHandleVisuals");
					    local function scan(parent)
					        if not parent then return end;
					        for _, copy in ipairs(parent:GetChildren()) do
					            local constraint = copy:IsA("BasePart") and copy:FindFirstChild("VisualConstraint");
					            if constraint and constraint:IsA("RigidConstraint") then
					                local a, b = constraint.Attachment0, constraint.Attachment1;
					                if (a and a.Parent == handle) or (b and b.Parent == handle) then
					                    for _, item in ipairs(copy:GetDescendants()) do
					                        if item:GetAttribute("VisualsSkin") then item:Destroy() end;
					                    end;
					                end;
					            end;
					        end;
					    end;
					    scan(visuals);
					    scan(workspace);
					end;

					local function overlayTool(tool, slot)
					    learnNativeTool(tool, slot);
					    if not worn[slot] then return end;
						if not alive or not host.Alive() or toolState[tool] or not isMine(tool) then return end;
						local record = { hidden = {} };
						toolState[tool] = record;
						local built;
						local skin = lastApplied[slot];
						if not skin and ProfileData then pcall(function() skin = ProfileData.Weapons.Equipped[slot] end) end;
						local ok, err = pcall(function()
							local handle = tool:FindFirstChild("Handle") or tool:WaitForChild("Handle", 5);
							if not alive or not host.Alive() or toolState[tool] ~= record or not handle or not isMine(tool) then return end;
							local data = skin and MESHES[skin];
							if not data then return end;
							built = buildAnyOverlay(data, true);
							if not built or not built.root then return end;
							if slot == "Knife" and not nativeGrips[skin] then fitKnife(built) end;
							if not alive or not host.Alive() or toolState[tool] ~= record or not handle.Parent or not isMine(tool) or (lastApplied[slot] and lastApplied[slot] ~= skin) then return end;
					local overlay = finalizeOverlay(built, heldSeat(built.root, tool, handle, slot, skin));
							local weld = Instance.new("WeldConstraint");
							weld.Part0, weld.Part1, weld.Parent = overlay, handle, overlay;
							record.overlay = overlay;
							record.chroma = isChroma(skin, data) and startChroma(overlay) or nil;
							for _, item in ipairs(tool:GetDescendants()) do hideInto(record.hidden, item) end;
					overlay.Parent = tool;
					if slot == "Gun" then
					    local beam = overlay:FindFirstChild("CustomBeam", true);
					    local oldBeam = tool:FindFirstChild("CustomBeam");
					    if oldBeam then record.nativeBeam = oldBeam; oldBeam.Parent = nil end;
					    if beam and beam:IsA("Beam") then
					        record.beam = beam:Clone();
					        record.beam.Parent = tool;
					    end;
					    local spec = nativeSounds[skin];
					    if spec then
					        for _, sound in ipairs(tool:GetDescendants()) do
					            local name = sound.Name:lower();
					            if sound:IsA("Sound") and (name == "gunshot" or name == "shoot" or name == "altsound") and not sound:IsDescendantOf(overlay) then
					                for prop, value in pairs(spec) do
					                    record.hidden[#record.hidden + 1] = { inst = sound, prop = prop, val = sound[prop] };
					                    sound[prop] = value;
					                end;
					            end;
					        end;
					    end;
					end;
					record.descAdded = tool.DescendantAdded:Connect(function(item)
                            if toolState[tool] == record and item ~= overlay and not item:IsDescendantOf(overlay) and item ~= record.beam then
                                hideInto(record.hidden, item);
                            end;
                        end);
					    purgeCopiedSkins(handle);
					    record.image = weaponThumbnail(data.Meta) or "";
					    record.label = (data.Meta and (data.Meta.DisplayName or data.Meta.ItemName)) or skin;
					    setToolValue(record, tool, "TextureId", record.image);
					    setToolValue(record, tool, "ToolTip", record.label);
					    record.hotbarConn = tool:GetPropertyChangedSignal("Parent"):Connect(function()
					        task.defer(refreshHotbar, tool, record);
					    end);
					    task.defer(refreshHotbar, tool, record);
                        record.committed = true;
						end);
						if not record.committed then
							if toolState[tool] == record then unoverlayTool(tool) end;
							restore(record.hidden);
							if record.chroma then record.chroma:Disconnect() end;
							if built and built.root then built.root:Destroy() end;
						end;
						if not ok then recordError("skin overlay: " .. tostring(err)) end;
					end;

					local function reapplyTools(slot)
					    local tools, seen = {}, {};
					    for tool in pairs(toolState) do
					        local kind = CollectionService:HasTag(tool, "Weapon_Gun") and "Gun" or "Knife";
					        if kind == slot then tools[#tools + 1], seen[tool] = tool, true end;
					    end;
					    local tag = slot == "Gun" and "Weapon_Gun" or "Weapon_Knife";
					    for _, tool in ipairs(CollectionService:GetTagged(tag)) do
					        if isMine(tool) and not seen[tool] then tools[#tools + 1] = tool end;
					    end;
					    for _, tool in ipairs(tools) do
					        unoverlayTool(tool);
					        task.spawn(overlayTool, tool, slot);
					    end;
					end;

					local knives, guns = {}, {};

					-- a skin the database has no mesh for (an empty FileMesh, a bare
					-- block) shows nothing in the hand, so it is not offered
					local function meshed(class, props)
						return (class == "MeshPart" or class == "SpecialMesh" or class == "FileMesh")
							and tostring(props and props.MeshId or ""):match("%d") ~= nil;
					end;

					local function renderable(data)
						if data.Model then
							local function walk(node)
								if type(node) ~= "table" then return false end;
								if meshed(node.Class, node.Props) then return true end;
								for _, child in ipairs(node.Children or {}) do if walk(child) then return true end end;
								return false;
							end;
							return walk(data.Model);
						end;

						for _, entry in ipairs(data.Display or {}) do
							local class = entry.Class;

							if meshed(class, entry.Props) or class == "Decal" or class == "Texture" then
								return true;
							end;
						end;

						return false;
					end;
					weaponThumbnail = function(meta)
						local image = meta and meta.Image;
						local numeric = tonumber(image);
						if numeric then return "rbxthumb://type=Asset&id=" .. numeric .. "&w=150&h=150" end;
						if type(image) ~= "string" or image == "" then return nil end;
						if string.match(image, "^rbxassetid://%d+$") or string.match(image, "^rbxthumb://") then return image end;
						local id = string.match(image, "[?&]assetId=(%d+)") or string.match(image, "[?&]id=(%d+)");
						if not id then return nil end;
						if string.find(string.lower(image), "/asset/", 1, true) then return "rbxassetid://" .. id end;
						return "rbxthumb://type=Asset&id=" .. id .. "&w=150&h=150";
					end;

					for key, data in pairs(MESHES) do
						local meta = data.Meta;

						if renderable(data) then
							local label = (meta and meta.ItemName) or key;
							local id = meta and tonumber(meta.ItemID) or nil;

							if not id and meta and type(meta.Image) == "string" then
								id = tonumber(string.match(meta.Image, "assetId=(%d+)")
									or string.match(meta.Image, "[?&]id=(%d+)")
									or string.match(meta.Image, "rbxassetid://(%d+)"));
							end;

							local row = { name = key, label = label, base = label, id = id, image = weaponThumbnail(meta) };

							if meta and meta.ItemType == "Gun" then
								guns[#guns + 1] = row;
							else
								knives[#knives + 1] = row;
							end;
						end;
					end;

					local function byName(a, b) return string.lower(a.label) < string.lower(b.label) end;

					table.sort(knives, byName);
					table.sort(guns, byName);

					local FAVORITES = userFile("skin favourites.json");
					local starred = {};

					do
						local ok, body = pcall(function() return readfile(FAVORITES) end);

						if ok and type(body) == "string" then
							local fine, list = pcall(function()
								return game:GetService("HttpService"):JSONDecode(body);
							end);

							if fine and type(list) == "table" then
								for _, key in ipairs(list) do starred[key] = true end;
							end;
						end;
					end;

					local function saveStarred()
						local list = {};

						for key in pairs(starred) do list[#list + 1] = key end;

						table.sort(list);

						pcall(function()
							writefile(FAVORITES, game:GetService("HttpService"):JSONEncode(list));
						end);
					end;

					local function ordered(rows)
						local out = {};

						for _, row in ipairs(rows) do
							out[#out + 1] = {
								name = row.name,
								label = (starred[row.name] and "• " or "") .. row.base,
								id = row.id,
								image = row.image,
								base = row.base,
							};
						end;

						table.sort(out, function(a, b)
							local sa, sb = starred[a.name] and 1 or 0, starred[b.name] and 1 or 0;

							if sa ~= sb then return sa > sb end;

							return string.lower(a.base) < string.lower(b.base);
						end);

						return out;
					end;

					local grids = {};

					local InventoryModule, Sync;
					pcall(function()
					    InventoryModule = require(ReplicatedStorage.Modules.InventoryModule);
					    Sync = require(ReplicatedStorage.Database.Sync);
					end);
					local injected, originalEquipped, nativeEquipped, equipEpoch = {}, {}, {}, {};

					local function isNativeKey(slot, key)
					    if type(key) ~= "string" or injected[key] then return false end;
					    local meta = Sync and Sync.Weapons[key];
					    if not meta or meta.ItemType ~= slot then return false end;
					    if key == "Default" .. slot then return true end;
					    return ProfileData and (tonumber(ProfileData.Weapons.Owned[key]) or 0) > 0;
					end;

					rememberNativeEquipped = function(slot, key)
					    if isNativeKey(slot, key) then nativeEquipped[slot] = key end;
					end;

					local function nativeEquippedKey(slot, preferred)
					    if isNativeKey(slot, preferred) then return preferred end;
					    local current = ProfileData and ProfileData.Weapons.Equipped[slot];
					    if isNativeKey(slot, current) then return current end;
					    local tag = slot == "Gun" and "Weapon_Gun" or "Weapon_Knife";
					    for _, tool in ipairs(CollectionService:GetTagged(tag)) do
					        local key = tool:GetAttribute("ItemID");
					        if isMine(tool) and isNativeKey(slot, key) then nativeEquipped[slot] = key; return key end;
					    end;
					    if isNativeKey(slot, nativeEquipped[slot]) then return nativeEquipped[slot] end;
					    local base = displayValue(slot);
					    local displayKey = base and base:GetAttribute("ItemID");
					    if isNativeKey(slot, displayKey) then nativeEquipped[slot] = displayKey; return displayKey end;
					    local mesh, texture = baseMeshId(base);
					    if digits(mesh) then
					        for key, data in pairs(MESHES) do
					            if isNativeKey(slot, key) then
					                local wantMesh, wantTexture = targetMeshId(data);
					                if digits(mesh) == digits(wantMesh) and digits(texture) == digits(wantTexture) then
										nativeEquipped[slot] = key;
										return key;
					                end;
					            end;
					        end;
					    end;
					    return "Default" .. slot;
					end;
					local bindNativeInventory;
					
					local function updateNativeEquip(slot, key)
					    if not ProfileData then return end;
					    ProfileData.Weapons.Equipped[slot] = key;
					    if InventoryModule then pcall(InventoryModule.UpdateMyEquip) end;
					end;
					
					local function equipSkin(slot, key)
					    if not alive or not host.Alive() then return end;
					    if originalEquipped[slot] == nil then originalEquipped[slot] = nativeEquippedKey(slot) end;
					    equipEpoch[slot] = (equipEpoch[slot] or 0) + 1;
					    local request = equipEpoch[slot];
					    worn[slot] = key;
					    updateNativeEquip(slot, key);
					    task.spawn(function()
					        if not alive or worn[slot] ~= key or equipEpoch[slot] ~= request then return end;
					        apply(slot, key);
					        if alive and worn[slot] == key and equipEpoch[slot] == request then reapplyTools(slot) end;
					    end);
					end;
					
					local function cleanInjectedTags(frame)
					    local tags = frame:FindFirstChild("Tags");
					    local tag = tags and tags:FindFirstChild("Changer");
					    if tag then tag:Destroy() end;
					end;
					
					local function bindInjectedInventory()
					    if not alive then return end;
					    local inv = InventoryModule and InventoryModule.MyInventory;
					    local weapons = inv and inv.Data and inv.Data.Weapons;
					    if not weapons then return end;
					    for alias, registered in pairs(injected) do
					        local entries = weapons[registered.tab];
					        local entry = entries and entries[alias];
					        if entry then
					            local slot, key = registered.skinSlot, registered.skinKey;
					            if entry ~= registered then
					                if registered.EquipConnection then registered.EquipConnection:Disconnect() end;
					                entry.tab, entry.skinSlot, entry.skinKey = registered.tab, slot, key;
					                injected[alias] = entry;
					            end;
					            local frame = entry.Frame;
					            local container = frame and frame.Parent and frame:FindFirstChild("Container");
					            local button = container and container:FindFirstChild("ActionButton");
					            if button then
					                if entry.skinButton ~= button or not entry.skinConnection or not entry.skinConnection.Connected
					                    or entry.EquipConnection ~= entry.skinConnection then
					                    if entry.EquipConnection then entry.EquipConnection:Disconnect() end;
					                    if entry.skinConnection then entry.skinConnection:Disconnect() end;
					                    entry.skinButton = button;
					                    entry.skinConnection = button.MouseButton1Click:Connect(function() equipSkin(slot, key) end);
					                    entry.EquipConnection = entry.skinConnection;
					                end;
					                cleanInjectedTags(frame);
					            end;
					        end;
					    end;
					end;
					
					local nativeGenerate, nativeConnect, nativeUpdate;
					local generateWrapper, connectWrapper, updateWrapper;
					if InventoryModule then
					    nativeGenerate = InventoryModule.GenerateNewInventoryFrames;
					    nativeConnect = InventoryModule.ConnectEquipButtons;
					    nativeUpdate = InventoryModule.UpdateInventory;
					    generateWrapper = function(...)
					        local result = table.pack(nativeGenerate(...));
					        if alive then
					            bindInjectedInventory();
					            if bindNativeInventory then pcall(bindNativeInventory) end;
					        end;
					        return table.unpack(result, 1, result.n);
					    end;
					    connectWrapper = function(...)
					        if alive then bindInjectedInventory() end;
					        return nativeConnect(...);
					    end;
					    updateWrapper = function(...)
					        if alive and ProfileData and ProfileData.Weapons then
					            for alias in pairs(injected) do ProfileData.Weapons.Owned[alias] = 1 end;
					        end;
					        return nativeUpdate(...);
					    end;
					    InventoryModule.GenerateNewInventoryFrames = generateWrapper;
					    InventoryModule.ConnectEquipButtons = connectWrapper;
					    InventoryModule.UpdateInventory = updateWrapper;
					end;
					
					local function removeInjected(alias)
					    local entry = injected[alias];
					    if not entry then return end;
					    injected[alias] = nil;
					    if entry.EquipConnection then entry.EquipConnection:Disconnect() end;
					    if entry.skinConnection and entry.skinConnection ~= entry.EquipConnection then entry.skinConnection:Disconnect() end;
					    if entry.Frame then entry.Frame:Destroy() end;
					    if InventoryModule and InventoryModule.MyInventory.Data then
					        local tab = entry.tab;
					        InventoryModule.MyInventory.Data.Weapons[tab][alias] = nil;
					        local sort = InventoryModule.MyInventory.Sort.Weapons[tab];
					        local at = table.find(sort, alias);
					        if at then table.remove(sort, at) end;
					    end;
					    if ProfileData then ProfileData.Weapons.Owned[alias] = nil end;
					    if Sync then Sync.Weapons[alias] = nil end;
					end;
					
					local function stageSkin(slot, key, deferred)
					    if not alive or not host.Alive() then return end;
					    if not (INGAME and InventoryModule and Sync and InventoryModule.MyInventory.Data and InventoryModule.GUI.MyInventory.Main) then
					        recordError("skins: native inventory unavailable");
					        return;
					    end;
					    local alias = "SaladMurder_" .. key;
					    if injected[alias] then bindInjectedInventory(); return end;
					    local meta = Sync.Weapons[key] or MESHES[key].Meta;
					    if not meta or meta.ItemType ~= slot then return end;
					    Sync.Weapons[alias] = table.clone(meta);
					    ProfileData.Weapons.Owned[alias] = 1;
					    local entry = InventoryModule.CreateNewItemData(alias, 1, "Weapons");
					    if not entry then ProfileData.Weapons.Owned[alias], Sync.Weapons[alias] = nil, nil; return end;
					    local event = entry.Event;
					    local tab = (event == "Christmas" or event == "Halloween") and event or (entry.Season and "Current" or "Classic");
					    entry.tab, entry.skinSlot, entry.skinKey = tab, slot, key;
					    local inv = InventoryModule.MyInventory;
					    inv.Data.Weapons[tab][alias] = entry;
					    injected[alias] = entry;
					    table.insert(inv.Sort.Weapons[tab], alias);
					    if not deferred then
					        InventoryModule.SortTab(inv, "Weapons", tab);
					        InventoryModule.GenerateNewInventoryFrames(inv, InventoryModule.GUI.MyInventory.Main);
					        bindInjectedInventory();
					    end;
					    return true;
					end;

					local function syncStaged(slot)
					    local keys = {};
					    for _, entry in pairs(injected) do
					        if entry.skinSlot == slot then keys[#keys + 1] = entry.skinKey end;
					    end;
					    if grids[slot] then grids[slot]:SetDefault(keys) end;
					end;

					-- back to the weapon the player really has
					local function unwear(slot)
					    equipEpoch[slot] = (equipEpoch[slot] or 0) + 1;
					    worn[slot] = nil;
					    apply(slot, nil);
					    reapplyTools(slot);
					    updateNativeEquip(slot, nativeEquippedKey(slot, originalEquipped[slot]));
					    originalEquipped[slot] = nil;
					end;

					local function regenerateInventory()
					    local inv = InventoryModule and InventoryModule.MyInventory;
					    if not (inv and inv.Data and InventoryModule.GUI and InventoryModule.GUI.MyInventory.Main) then return end;
					    for _, tab in ipairs({ "Current", "Classic", "Christmas", "Halloween" }) do
					        pcall(InventoryModule.SortTab, inv, "Weapons", tab);
					    end;
					    pcall(InventoryModule.GenerateNewInventoryFrames, inv, InventoryModule.GUI.MyInventory.Main);
					    bindInjectedInventory();
					end;

					local function clearSkins(slot)
					    unwear(slot);
					    local aliases = {};
					    for alias, entry in pairs(injected) do
					        if entry.skinSlot == slot then aliases[#aliases + 1] = alias end;
					    end;
					    for _, alias in ipairs(aliases) do removeInjected(alias) end;
					    syncStaged(slot);
					end;

					-- Inventory Mode off: one skin per slot, worn the moment it is picked;
					-- picking it again takes it off. On: the game's inventory holds exactly
					-- the ticked skins (equip them there), unticking takes one back out.
					local inventoryMode = false;

					local function wear(slot)
					    return function(value)
					        local wanted = {};
					        for index, selected in pairs(type(value) == "table" and value or { value }) do
					            local key = selected == true and index or selected;
					            if type(key) == "string" and MESHES[key] then wanted[key] = true end;
					        end;
					        if not inventoryMode then
					            local pick;
					            for key in pairs(wanted) do if key ~= worn[slot] then pick = key; break end end;
					            if not pick and worn[slot] and wanted[worn[slot]] then pick = worn[slot] end;
					            if pick then
					                if pick ~= worn[slot] then equipSkin(slot, pick) end;
					            elseif worn[slot] then
					                unwear(slot);
					            end;
					            if grids[slot] then grids[slot]:SetDefault(pick and { pick } or {}) end;
					            return;
					        end;
					        local changed = false;
					        for key in pairs(wanted) do
					            if stageSkin(slot, key, true) then changed = true end;
					        end;
					        local gone = {};
					        for alias, entry in pairs(injected) do
					            if entry.skinSlot == slot and not wanted[entry.skinKey] then gone[#gone + 1] = alias end;
					        end;
					        for _, alias in ipairs(gone) do
					            local key = injected[alias].skinKey;
					            removeInjected(alias);
					            if worn[slot] == key then unwear(slot) end;
					            changed = true;
					        end;
					        if changed then regenerateInventory() end;
					        syncStaged(slot);
					    end;
					end;

					local function setInventoryMode(on)
					    if inventoryMode == on then return end;
					    inventoryMode = on;
					    for _, slot in ipairs({ "Knife", "Gun" }) do
					        if on then
					            -- what is worn now goes into the inventory with the rest
					            if worn[slot] then wear(slot)({ worn[slot] }) else syncStaged(slot) end;
					        else
					            -- the inventory hands its skins back; the worn one stays on
					            local gone = {};
					            for alias, entry in pairs(injected) do
					                if entry.skinSlot == slot then gone[#gone + 1] = alias end;
					            end;
					            for _, alias in ipairs(gone) do removeInjected(alias) end;
					            if grids[slot] then grids[slot]:SetDefault(worn[slot] and { worn[slot] } or {}) end;
					        end;
					    end;
					    if not on then regenerateInventory() end;
					end;

					local function star(slot, rows)
						return function(name)
							if type(name) ~= "string" or name == "" then return end;

							starred[name] = (not starred[name]) or nil;

							saveStarred();

							local grid = grids[slot];

							if grid and grid.setdata then pcall(grid.setdata, grid, ordered(rows)) end;
						end;
					end;

					local modeCard = UI.section("Style", "Skins", "full", "Skin Changer", true);
					modeCard:toggle("Inventory Mode", false, function(v) setInventoryMode(v == true) end);

					grids.Knife = host.Page:AddGallery({
						Name = "Knives", Icon = "sword", Position = "left",
						Height = 430, Cell = 74, Thumb = "Asset", Blank = "sword", Default = {}, Multi = true, Tools = false, Smooth = true,
						Empty = "No knives", Values = ordered(knives),
						Flag = "skin_knife", Callback = wear("Knife"), Context = star("Knife", knives),
						Buttons = {{ text = "Unequip All", callback = function() clearSkins("Knife") end }},
					});

					grids.Gun = host.Page:AddGallery({
						Name = "Guns", Icon = "crosshair", Position = "right",
						Height = 430, Cell = 74, Thumb = "Asset", Blank = "crosshair", Default = {}, Multi = true, Tools = false, Smooth = true,
						Empty = "No guns", Values = ordered(guns),
						Flag = "skin_gun", Callback = wear("Gun"), Context = star("Gun", guns),
						Buttons = {{ text = "Unequip All", callback = function() clearSkins("Gun") end }},
					});

					local nativeButtons = setmetatable({}, { __mode = "k" });
					bindNativeInventory = function()
					    local inv = InventoryModule and InventoryModule.MyInventory;
					    if not (inv and inv.Data and inv.Data.Weapons) then return end;
					    for _, entries in pairs(inv.Data.Weapons) do
					        for alias, entry in pairs(entries) do
					            local slot = entry.ItemType;
					            local frame = entry.Frame;
					            local button = frame and frame:FindFirstChild("Container") and frame.Container:FindFirstChild("ActionButton");
					            if not injected[alias] and not nativeButtons[button] and button and (slot == "Knife" or slot == "Gun") then
					                nativeButtons[button] = true;
					                keep(button.MouseButton1Click:Connect(function()
					                    rememberNativeEquipped(slot, entry.DataID);
					                    task.defer(function()
					                        if not alive or not worn[slot] or ProfileData.Weapons.Equipped[slot] == worn[slot] then return end;
					                        worn[slot], originalEquipped[slot] = nil, nil;
					                        apply(slot, nil);
					                        reapplyTools(slot);
					                    end);
					                end));
					            end;
					        end;
					    end;
					end;
					pcall(bindNativeInventory);
					local inventoryChanged = ReplicatedStorage.Remotes.Inventory:FindFirstChild("InventoryDataChanged");
					if inventoryChanged and inventoryChanged:IsA("BindableEvent") then
					    keep(inventoryChanged.Event:Connect(function() task.defer(function() if alive then pcall(bindNativeInventory) end end) end));
					end;

					local function watchCharacter(character)
					    local function bindDisplayRef(ref)
					        local slot = (ref.Name == "DisplayRefKnife" and "Knife") or (ref.Name == "DisplayRefGun" and "Gun");
					        if not slot or not ref:IsA("ObjectValue") then return end;
					        local function refresh()
					            local skin = worn[slot] or lastApplied[slot];
					            if not alive or not host.Alive() or not skin then return end;
					            cleanup(slot);
					            task.spawn(apply, slot, skin);
					        end;
					        keepNamed("ref_" .. slot, ref:GetPropertyChangedSignal("Value"):Connect(refresh));
					        task.delay(0.2, refresh);
					    end;
					    keepNamed("char", character.ChildAdded:Connect(bindDisplayRef));
					    for _, name in ipairs({ "DisplayRefKnife", "DisplayRefGun" }) do
					        local ref = character:FindFirstChild(name);
					        if ref then bindDisplayRef(ref) end;
					    end;
					end;

					local function watchNativePlayer(player)
					    local prefix = "native_mount_" .. player.UserId;
					    local function characterAdded(character)
					        local function refAdded(ref)
					            if not ref:IsA("ObjectValue") or (ref.Name ~= "DisplayRefKnife" and ref.Name ~= "DisplayRefGun") then return end;
					            local function refresh()
					                if alive and ref.Value then pcall(learnMount, ref.Value) end;
					            end;
					            keepNamed(prefix .. ref.Name, ref:GetPropertyChangedSignal("Value"):Connect(refresh));
					            refresh();
					        end;
					        keepNamed(prefix .. "children", character.ChildAdded:Connect(refAdded));
