					end));
					-- every knife and gun anyone holds teaches its grip (saved to skin grips.json):
					-- the murderer and the sheriff of each round fill in whole mesh families
					local function learnTagged(tool)
					    if not alive or not tool:IsA("Tool") or isMine(tool) then return end;
					    local slot = tool:HasTag("Weapon_Gun") and "Gun" or tool:HasTag("Weapon_Knife") and "Knife";
					    if slot then task.delay(1, function() if alive and tool.Parent then pcall(learnNativeTool, tool, slot) end end) end;
					end;
					for _, tag in ipairs({ "Weapon_Knife", "Weapon_Gun" }) do
					    for _, tool in ipairs(CollectionService:GetTagged(tag)) do learnTagged(tool) end;
					    keep(CollectionService:GetInstanceAddedSignal(tag):Connect(learnTagged));
					end;
					if currentChar() then watchCharacter(currentChar()) end;

					local displays = workspace:FindFirstChild("WeaponDisplays") or workspace:WaitForChild("WeaponDisplays", 5);

					if displays then
						for _, part in ipairs(displays:GetChildren()) do pcall(learnMount, part) end;

						saveMounts();

						keep(displays.ChildAdded:Connect(function(part)
