								if not alive then return end;

								pcall(learnMount, part);
								saveMounts();
							end);
						end));
					end;

					keep(LocalPlayer.CharacterAdded:Connect(function(character)

						for slot in pairs(state) do cleanup(slot) end;

						for tool in pairs(toolState) do unoverlayTool(tool) end;

						watchCharacter(character);

						task.delay(1, function()
							if not alive then return end;

							for _, slot in ipairs({ "Knife", "Gun" }) do
								if lastApplied[slot] then apply(slot, lastApplied[slot]) end;
							end;
						end);
					end));

					for _, tag in ipairs({ "Weapon_Knife", "Weapon_Gun" }) do
						local slot = (tag == "Weapon_Gun") and "Gun" or "Knife";

						for _, tool in ipairs(CollectionService:GetTagged(tag)) do
							task.spawn(function() tool:WaitForChild("Handle", 5); if alive then pcall(learnNativeTool, tool, slot) end end);
							if isMine(tool) then task.spawn(overlayTool, tool, slot) end;
						end;

						keep(CollectionService:GetInstanceAddedSignal(tag):Connect(function(tool)
							task.spawn(function() tool:WaitForChild("Handle", 5); if alive then pcall(learnNativeTool, tool, slot) end end);
							if isMine(tool) then task.spawn(overlayTool, tool, slot) end;
						end));

						keep(CollectionService:GetInstanceRemovedSignal(tag):Connect(unoverlayTool));
					end;

					if EquipService then
						pcall(function()
							keep(EquipService.EquippedChanged.Event:Connect(function(kind, name)
								if not alive then return end;

					if kind == "Knife" or kind == "Gun" then
					    rememberNativeEquipped(kind, name or ("Default" .. kind));
					    if worn[kind] and name ~= worn[kind] then worn[kind], originalEquipped[kind] = nil, nil end;
					    if not worn[kind] then task.spawn(function() apply(kind, nil); reapplyTools(kind) end) end;
					end;
							end));
						end);
					end;

					ESP.Skins = {
						MESHES = MESHES,
						apply = apply,
						worn = worn,
						stage = function(slot, key)
						    local added = stageSkin(slot, key);
						    syncStaged(slot);
						    return added;
						end,
						equip = equipSkin,
						clear = clearSkins,
						injected = injected,
						count = #knives + #guns,
						ingame = INGAME,
						grips = nativeGrips,
						gripProfiles = nativeGripProfiles,
						gripSignature = gripSignature,
						canonicalGrips = canonicalGrips,
						tools = toolState,
						displays = state,
						mounts = nativeBodyMounts,
					};

					ESP.ClearSkins = onUnload("skins", function()
						alive = false;
                        if InventoryModule then
                            if InventoryModule.GenerateNewInventoryFrames == generateWrapper then InventoryModule.GenerateNewInventoryFrames = nativeGenerate end;
                            if InventoryModule.ConnectEquipButtons == connectWrapper then InventoryModule.ConnectEquipButtons = nativeConnect end;
                            if InventoryModule.UpdateInventory == updateWrapper then InventoryModule.UpdateInventory = nativeUpdate end;
                        end;

						for _, connection in ipairs(conns) do pcall(function() connection:Disconnect() end) end;
						for _, connection in pairs(named) do pcall(function() connection:Disconnect() end) end;

						table.clear(conns);
						table.clear(named);

						for slot in pairs(state) do pcall(cleanup, slot) end;
						for tool in pairs(toolState) do pcall(unoverlayTool, tool) end;

					for _, slot in ipairs({ "Knife", "Gun" }) do
					    if originalEquipped[slot] or not isNativeKey(slot, ProfileData and ProfileData.Weapons.Equipped[slot]) then
					        updateNativeEquip(slot, nativeEquippedKey(slot, originalEquipped[slot]));
					    end;
					end;
					local aliases = {};
					for alias in pairs(injected) do aliases[#aliases + 1] = alias end;
					for _, alias in ipairs(aliases) do removeInjected(alias) end;
					for data, template in pairs(nativeModels) do template:Destroy(); nativeModels[data] = nil end;
					for data, template in pairs(nativeToolModels) do template:Destroy(); nativeToolModels[data] = nil end;
					pcall(function() writefile(GRIPS_FILE, HttpService:JSONEncode({ version = 1, profiles = nativeGripProfiles })) end);
					ESP.Skins = nil;
					end);
				end);
			end;
