			return R.names[id] or ("Track " .. id);
		end;
		local function saveHistory(empty)
			if not empty and #R.history == 0 then return end;
			if writeJson(HISTORY, R.history) and (#R.history > 0 or empty) then writeJson(BACKUP, R.history) end;
		end;
		local function saveFavorites()
			local out = {};
			for id in pairs(R.favorites) do out[#out + 1] = { id = id, name = remember(id) } end;
			table.sort(out, function(a, b) return a.id < b.id end);
			writeJson(FAVORITES, out);
		end;
		local function pushHistory(id, title)
			for i, entry in ipairs(R.history) do if entry.id == id then table.remove(R.history, i); break end end;
			table.insert(R.history, 1, { id = id, name = remember(id, title) });
			while #R.history > 50 do table.remove(R.history) end;
			saveHistory();
		end;
		local data = readJson(HISTORY) or readJson(BACKUP)
			or readJson("GlassRadio_History.json") or readJson("GlassRadio_History.bak.json");
		local seen = {};
		for _, entry in ipairs(data or {}) do
			if type(entry) == "table" then
				local id = codeOf(entry.id);
				if id and not seen[id] then
					seen[id] = true; R.history[#R.history + 1] = { id = id, name = remember(id, entry.name) };
					if #R.history == 50 then break end;
				end;
			end;
		end;
		R.importSongs = not data or #R.history > 0;
		data = readJson(FAVORITES) or readJson("GlassRadio_Fav.json");
		for _, entry in ipairs(data or {}) do
