			local play = inventory and inventory:FindFirstChild("PlaySong");
			return play and play:IsA("RemoteEvent") and play or nil;
		end;
		local function hasPass() return player and player:GetAttribute("Radio") == true and remote() ~= nil end;
		LocalProvider.hasRadioPass = hasPass;
