			local audio = radioSound(player); if not audio then return end;
			local saved = R.savedOwn[audio];
			if not saved then
				saved = { Volume = audio.Volume, Min = audio.RollOffMinDistance, Max = audio.RollOffMaxDistance, Emitter = audio.EmitterSize, Loop = audio.Looped };
				R.savedOwn[audio] = saved;
			end;
			audio.Looped = R.loop;
			if R.maxVolume then
				audio.Volume = 10; audio.RollOffMinDistance = 100000; audio.RollOffMaxDistance = 1000000; audio.EmitterSize = 1000;
			else
				audio.Volume = R.volume / 10; audio.RollOffMinDistance = saved.Min;
				audio.RollOffMaxDistance = saved.Max; audio.EmitterSize = saved.Emitter;
			end;
		end;
		local function applyMute()
