			return false;
		end;
		local function fetchName(id, token)
			job(function()
				local ok, info = Remote.invoke(function() return MarketplaceService:GetProductInfo(tonumber(id)) end, 5);
				if not (current(token) and ok and type(info) == "table" and type(info.Name) == "string") then return end;
				remember(id, info.Name);
				if R.code == id then R.title = R.names[id] end;
				for _, entry in ipairs(R.history) do if entry.id == id then entry.name = R.names[id] end end;
				saveHistory(); if R.favorites[id] then saveFavorites() end; changed(true);
			end);
		end;
		local function load(index)
			if not alive() or #R.queue == 0 then return false end;
			R.epoch += 1;
			local token = R.epoch;
			R.active = true; R.engaged = true; R.cursor = ((index - 1) % #R.queue) + 1;
			local entry = R.queue[R.cursor];
			R.code = entry.id; R.url = "https://www.roblox.com/asset/?id=" .. entry.id;
			R.title = remember(entry.id, entry.title); R.artist = entry.artist or "";
			R.radio = hasPass(); R.paused = false; R.loading = true;
			status("Loading...");
			job(function()
				local accepted;
				if R.radio then
					sound:Stop();
					local play = remote();
					if not play then R.loading = false; status("Radio unavailable", true); return end;
					play:FireServer(R.url);
					local function ready(audio) return codeOf(audio.SoundId) == entry.id and audio.IsPlaying and audio.TimeLength > 1 end;
					accepted = waitSound(token, 3.5, ready);
					if not current(token) then return end;
					local audio = radioSound(player);
					if not accepted and audio and codeOf(audio.SoundId) == entry.id and not audio.IsPlaying then
						play:FireServer(R.url); accepted = waitSound(token, 3.5, ready);
					end;
				else
					sound:Stop(); sound.SoundId = "rbxassetid://" .. entry.id;
					sound.Looped = R.loop; sound.Volume = R.volume / 10; sound.TimePosition = 0; sound:Play();
					accepted = waitSound(token, 4, function(audio) return audio.IsPlaying and audio.TimeLength > 1 end);
				end;
				if not current(token) then return end;
				R.loading = false;
