		local function entryOf(text)
			local id = codeOf(text); if not id then return nil end;
			local raw = tostring(text or "");
			local rest = raw:match("^%s*%d+%s+(.+)%s*$");
			local artist, title;
			if rest then artist, title = rest:match("^(.-)%s*%-%s*(.+)$"); title = title or rest end;
			return { id = id, title = title, artist = artist };
		end;
		function LocalProvider.add(text)
			local entry = entryOf(text);
			if not entry then status("Enter an audio ID or Roblox asset link", true); return false end;
			R.queue[#R.queue + 1] = entry;
			if #R.queue == 1 then load(1) else changed() end;
			return true;
		end;
		function LocalProvider.playCode(text)
			local entry = entryOf(text);
			if not entry then status("Enter an audio ID or Roblox asset link", true); return false end;
			R.queue = { entry }; return load(1);
		end;
		function LocalProvider.playList(list, id)
			local queue, at = {}, 1;
			for _, entry in ipairs(type(list) == "table" and list or {}) do
				local code = codeOf(entry.id or entry.code);
				if code then
					queue[#queue + 1] = { id = code, title = entry.title or entry.name, artist = entry.artist };
