		function LocalProvider.clearHistory() table.clear(R.history); R.importSongs = false; saveHistory(true); changed(true) end;
		local function mapEntries(entries, idKey, titleKey)
			local out, found = {}, {};
			for _, entry in ipairs(entries) do
				if type(entry) == "table" then
					local id = codeOf(entry[idKey]);
					if id and not found[id] then
						found[id] = true;
						out[#out + 1] = { id = id, title = remember(id, entry[titleKey]), artist = type(entry.artist) == "string" and entry.artist or "" };
						if #out == 5000 then break end;
					end;
				end;
			end;
			return out;
		end;
		local function localList(source, query)
			local list = {};
