				for _, favorite in ipairs({ true, false }) do
					for _, entry in ipairs(R.history) do if (R.favorites[entry.id] == true) == favorite then list[#list + 1] = { id = entry.id, title = entry.name } end end;
				end;
			elseif source == "Favorites" then
				for id in pairs(R.favorites) do list[#list + 1] = { id = id, title = remember(id) } end;
				table.sort(list, function(a, b) return a.title < b.title end);
			else list = R.collection or {} end;
			local view = {}; local q = string.lower(query);
			for _, entry in ipairs(list) do if q == "" or (entry.title .. " " .. entry.id):lower():find(q, 1, true) then view[#view + 1] = entry end end;
			return view;
		end;
		local function paginate(list, page)
			local library = R.library;
			library.total = #list; library.pages = math.max(1, math.ceil(#list / 15));
			library.page = math.clamp(math.floor(tonumber(page) or 1), 1, library.pages);
			library.queue = list; library.items = {}; library.loading = false; library.error = nil;
			for i = (library.page - 1) * 15 + 1, math.min(library.page * 15, #list) do library.items[#library.items + 1] = list[i] end;
			changed(true);
