		function LocalProvider.browse(source, query, page, refresh)
			if not alive() then return end;
			if not table.find({ "History", "Favorites", "Catalog", "My Collection" }, source) then source = "History" end;
			local library = R.library;
			query = tostring(query or "");
			page = math.max(1, math.floor(tonumber(page) or 1));
			local key = source .. "\0" .. query .. "\0" .. page;
