	lyricHead.Parent = headClip;

	local headKey = nil;
	local ESCAPE = { ["&"] = "&amp;", ["<"] = "&lt;", [">"] = "&gt;", ['"'] = "&quot;", ["'"] = "&apos;" };
	local function rich(text) return (string.gsub(text, "[&<>\"']", ESCAPE)) end;

	local lyricView = Instance.new("Frame");
	lyricView.Name = "View";
	lyricView.BackgroundTransparency = 1;
	lyricView.ClipsDescendants = true;
	lyricView.Position = UDim2.fromOffset(16, 30);
	lyricView.Size = UDim2.new(1, -32, 1, -41);
	lyricView.Parent = lyricPanel;

	local lyricRoll = Instance.new("Frame");
	lyricRoll.Name = "Roll";
	lyricRoll.BackgroundTransparency = 1;
	lyricRoll.AutomaticSize = Enum.AutomaticSize.Y;
	lyricRoll.Size = UDim2.new(1, 0, 0, 0);
	lyricRoll.Parent = lyricView;

	local lyricList = Instance.new("UIListLayout");
	lyricList.SortOrder = Enum.SortOrder.LayoutOrder;
	lyricList.Padding = UDim.new(0, 5);
	lyricList.Parent = lyricRoll;

	local lyricPad = Instance.new("UIPadding");
	lyricPad.Parent = lyricRoll;

	local lyricFade = Instance.new("UIGradient", lyricView);
	lyricFade.Rotation = 90;
	lyricFade.Transparency = NumberSequence.new({
		NumberSequenceKeypoint.new(0, 1),
		NumberSequenceKeypoint.new(0.22, 0),
		NumberSequenceKeypoint.new(0.78, 0),
		NumberSequenceKeypoint.new(1, 1),
	});

	local lyricRows = {};
	local lyricShow = 0;

	local function lyricRow(index)
		local row = lyricRows[index];

		if row then return row end;

		row = Instance.new("TextLabel");
		row.Name = "Line" .. index;
		row.BackgroundTransparency = 1;
		row.AutomaticSize = Enum.AutomaticSize.Y;
		row.Size = UDim2.new(1, 0, 0, 0);
		row.LayoutOrder = index;
		row.FontFace = SaladUI.BuiltInRegular;
		row.TextSize = 12;
		row.LineHeight = 1.1;
		row.TextColor3 = TH.dim;
		row.TextXAlignment = Enum.TextXAlignment.Left;
		row.TextWrapped = true;
		row.Text = "";
		row.Parent = lyricRoll;

		lyricRows[index] = row;

		return row;
	end;

	local lyricState = {
		key = nil,
		lines = {},
		synced = false,
		status = "",
		busy = false,
		offset = 0,
	};
	local function resetLyrics(status)
		lyricState.key = nil;
		lyricState.lines = {};
		lyricState.synced = false;
		lyricState.busy = false;
		lyricState.status = status or "";
		lyricState.offset = 0;
		lyricShow = 0;
		lyricPanel.Visible = false;
		lyricHead.Text, headKey = "", nil;
		for _, row in pairs(lyricRows) do row.Text, row.Visible = "", false end;
	end;

	local function parseSynced(text)
		local lines = {};

		for stamp, body in string.gmatch(text, "%[(%d+:%d+%.?%d*)%]([^\n]*)") do
			local m, sec = string.match(stamp, "(%d+):([%d%.]+)");

			if m then
				local at = tonumber(m) * 60 + (tonumber(sec) or 0);
				local clean = string.match(body, "^%s*(.-)%s*$");

				lines[#lines + 1] = { at = at, text = clean };
			end;
		end;

		return lines;
	end;

	local function parsePlain(text)
		local lines = {};

		for body in string.gmatch(text .. "\n", "([^\n]*)\n") do
			lines[#lines + 1] = { at = nil, text = body };
		end;

		return lines;
	end;

	local function lyricName(value)
		local text = string.lower(tostring(value or ""));
		text = string.gsub(text, "%b()", "");
		text = string.gsub(text, "%b[]", "");
		return string.gsub(text, "[%c%p%s]+", "");
	end;

	local function lyricNameMatches(expected, actual)
		local a, b = lyricName(expected), lyricName(actual);
		if a == "" or b == "" then return false end;
		if a == b then return true end;
		local short, long = (#a < #b) and a or b, (#a < #b) and b or a;
		return #short >= 5 and string.find(long, short, 1, true) ~= nil;
	end;

	local function matchingLyrics(results, title, artist)
		if type(results) ~= "table" then return nil end;
		for _, result in ipairs(results) do
			if type(result) == "table" and lyricNameMatches(title, result.trackName)
				and (artist == "" or lyricNameMatches(artist, result.artistName)) then
				return result;
			end;
		end;
	end;

	local function fetchLyrics(title, artist, album, duration)
		local query = LYRICS .. "?" .. form({
			track_name = title,
			artist_name = artist,
			album_name = album or "",
			duration = math.floor(duration or 0),
		});

		local body, code = httpJson("GET", query, { ["Accept"] = "application/json" });

		if code ~= 200 or type(body) ~= "table"
			or (body.trackName and not lyricNameMatches(title, body.trackName))
			or (artist ~= "" and body.artistName and not lyricNameMatches(artist, body.artistName)) then
			local hits = httpJson("GET", "https://lrclib.net/api/search?" .. form({ track_name = title, artist_name = artist }),
				{ ["Accept"] = "application/json" });

			body = matchingLyrics(hits, title, artist);
		end;

		if type(body) ~= "table" then
			return {}, false, "No lyrics";
		end;

		local lines, synced = {}, false;
		if type(body.syncedLyrics) == "string" and body.syncedLyrics ~= "" then
			lines = parseSynced(body.syncedLyrics);
			synced = #lines > 0;
		end;

		if not synced then
			local plain = body.plainLyrics;

			lines = (type(plain) == "string" and plain ~= "") and parsePlain(plain) or {};
		end;

		return lines, synced, (#lines == 0) and "No lyrics" or "";
	end;

	local function wantLyrics()
		if not (HUD.On and HUD.Lyrics) then return end;

		local title = Playback.title or "";
		local artist = Playback.artist or "";

		if title == "" then return end;

		local blocked = {
			["Loading..."] = true,
			["Nothing playing"] = true,
			["No track queued"] = true,
			["Spotify unavailable"] = true,
			["Spotify not connected"] = true,
			["Spotify not set up"] = true,
		};

		if blocked[title] then
			resetLyrics("Nothing playing");

			return;
		end;

		local key = title .. "|" .. artist;

		if lyricState.key == key then return end;

		resetLyrics("searching...");
		lyricState.key = key;
		lyricState.busy = true;

		task.spawn(function()
			local mine = key;
			local ok, lines, synced, status = pcall(fetchLyrics, title, artist, Playback.album, Playback.duration);
			if lyricState.key ~= mine then return end;
			lyricState.busy = false;
			if ok then
				lyricState.lines = lines;
				lyricState.synced = synced;
				lyricState.status = status;
			else
				lyricState.lines = {};
				lyricState.synced = false;
				lyricState.status = "Lyrics unavailable";
			end;
		end);
	end;

	function placeLyrics()
		if not HUD.LyricsPlaced then
			local anchor = SPOTS[HUD.Spot] or SPOTS["Bottom Left"];
			local gapY = (panel.Size.Y.Offset + 8) * (HUD.Scale / 100);

			HUD.LyricsSpot = HUD.Spot;
			HUD.LyricsX = HUD.OffsetX;
			HUD.LyricsY = HUD.OffsetY + (anchor.Y == 1 and -gapY or gapY);
			HUD.LyricsPlaced = true;

			for flag, value in pairs({ music_lyrics_x = HUD.LyricsX, music_lyrics_y = HUD.LyricsY }) do
				local item = SaladUI.Flags[flag];

				if item and item.SetValue then pcall(item.SetValue, item, value) end;
			end;

			local spot = SaladUI.Flags.music_lyrics_spot;

			if spot and spot.SetValue then pcall(spot.SetValue, spot, HUD.LyricsSpot) end;
		end;

		local anchor = SPOTS[HUD.LyricsSpot] or SPOTS["Bottom Left"];

		lyricPanel.AnchorPoint = anchor;
		lyricScale.Scale = HUD.Scale / 100;

		lyricPanel.Size = UDim2.fromOffset(panel.Size.X.Offset, HUD.LyricsSize);

		lyricPanel.Position = UDim2.new(
			anchor.X,
			(anchor.X == 0 and PAD or -PAD) + HUD.LyricsX,
			anchor.Y,
			(anchor.Y == 0 and PAD or -PAD) + HUD.LyricsY
		);
	end;

	local lyricDrag, lyricFrom, lyricBase = false, nil, nil;

	local function snapLyrics()
		local screen = SaladUI.ScreenGui.AbsoluteSize;

		if screen.X < 8 or screen.Y < 8 then return end;

		local center = screenAt(lyricPanel) + lyricPanel.AbsoluteSize * 0.5;
		local right = center.X > screen.X * 0.5;
		local bottom = center.Y > screen.Y * 0.5;

		HUD.LyricsSpot = (bottom and "Bottom " or "Top ") .. (right and "Right" or "Left");

		local anchor = SPOTS[HUD.LyricsSpot];
		local at = screenAt(lyricPanel) + lyricPanel.AbsoluteSize * Vector2.new(anchor.X, anchor.Y);
		local corner = Vector2.new(anchor.X * screen.X, anchor.Y * screen.Y);
		local base = Vector2.new(anchor.X == 0 and PAD or -PAD, anchor.Y == 0 and PAD or -PAD);
		local reachX = math.max(0, screen.X - lyricPanel.AbsoluteSize.X);
		local reachY = math.max(0, screen.Y - lyricPanel.AbsoluteSize.Y);

		HUD.LyricsX = math.clamp(math.floor(at.X - corner.X - base.X + 0.5), -reachX, reachX);
		HUD.LyricsY = math.clamp(math.floor(at.Y - corner.Y - base.Y + 0.5), -reachY, reachY);
	end;

	lyricPanel.Active = true;

	lyricPanel.InputBegan:Connect(function(input)
		if input.UserInputType ~= Enum.UserInputType.MouseButton1
			and input.UserInputType ~= Enum.UserInputType.Touch then
			return;
		end;

		lyricDrag = true;
		lyricFrom = input.Position;
		lyricBase = Vector2.new(HUD.LyricsX, HUD.LyricsY);
	end);

	SaladUI:AddSignal(UserInputService.InputChanged:Connect(function(input)
		if not lyricDrag then return end;

		if input.UserInputType ~= Enum.UserInputType.MouseMovement
			and input.UserInputType ~= Enum.UserInputType.Touch then
			return;
		end;

		local delta = input.Position - lyricFrom;

		HUD.LyricsX = lyricBase.X + delta.X;
		HUD.LyricsY = lyricBase.Y + delta.Y;

		placeLyrics();

		local screen = SaladUI.ScreenGui.AbsoluteSize;
		local at = screenAt(lyricPanel);
		local size = lyricPanel.AbsoluteSize;
		local pushX = math.clamp(at.X, 0, math.max(0, screen.X - size.X)) - at.X;
		local pushY = math.clamp(at.Y, 0, math.max(0, screen.Y - size.Y)) - at.Y;

		if pushX ~= 0 or pushY ~= 0 then
			HUD.LyricsX = HUD.LyricsX + pushX;
			HUD.LyricsY = HUD.LyricsY + pushY;

			placeLyrics();
		end;
	end));

	SaladUI:AddSignal(UserInputService.InputEnded:Connect(function(input)
		if not lyricDrag then return end;

		if input.UserInputType ~= Enum.UserInputType.MouseButton1
			and input.UserInputType ~= Enum.UserInputType.Touch then
			return;
		end;

		lyricDrag = false;

		snapLyrics();
		placeLyrics();

		for flag, value in pairs({ music_lyrics_x = HUD.LyricsX, music_lyrics_y = HUD.LyricsY }) do
			local item = SaladUI.Flags[flag];

			if item and item.SetValue then pcall(item.SetValue, item, value) end;
		end;

		local spot = SaladUI.Flags.music_lyrics_spot;

		if spot and spot.SetValue then pcall(spot.SetValue, spot, HUD.LyricsSpot) end;
	end));

	local function drawLyrics(position, dt)
		local lines = lyricState.lines;
		local want = HUD.On and HUD.Lyrics and #lines > 0;

		lyricShow = lyricShow + ((want and 1 or 0) - lyricShow) * math.min(1, dt * 9);

		if lyricShow < 0.01 then
			lyricPanel.Visible = false;

			return;
		end;

		lyricPanel.Visible = true;

		local tone = accent();
		local clear = 1 - HUD.Opacity / 100;

		lyricPanel.BackgroundTransparency = 1 - (1 - (clear * 0.88 + 0.04)) * lyricShow;
		lyricEdge.Transparency = 1 - (1 - (0.4 + clear * 0.55)) * lyricShow;
		lyricGlass.BackgroundTransparency = 1 - (1 - (0.82 + clear * 0.18)) * lyricShow;
		lyricGloss.BackgroundTransparency = 1 - (1 - (0.7 + clear * 0.3)) * lyricShow;
		local unit = lyricPanel.AbsoluteSize.X / math.max(1, lyricPanel.Size.X.Offset);
		if unit < 0.01 then return end;
		if lyricState.offset ~= lyricState.offset then lyricState.offset = 0 end;

		local title, artist = Playback.title or "", Playback.artist or "";
		if headKey ~= title .. "\0" .. artist .. TH.dim:ToHex() then
			headKey = title .. "\0" .. artist .. TH.dim:ToHex();
			lyricHead.Text = rich(title) .. (artist ~= ""
				and ('<font weight="400" color="#' .. TH.dim:ToHex() .. '">  \u{00B7}  ' .. rich(artist) .. "</font>") or "");
		end;
		lyricHead.TextTransparency = 1 - lyricShow;
		lyricHead.TextColor3 = tone;

		local over = (lyricHead.AbsoluteSize.X - headClip.AbsoluteSize.X) / unit;
		local slide = 0;
		if over > 1 then
			local speed, rest = 24, 1.4;
			local move = over / speed;
			local t = os.clock() % (2 * (move + rest));
			slide = (t < rest and 0) or (t < rest + move and (t - rest) * speed)
				or (t < 2 * rest + move and over) or (over - (t - 2 * rest - move) * speed);
		end;
		lyricHead.Position = UDim2.fromOffset(-math.floor(slide + 0.5), 0);

		local active = 0;

		if lyricState.synced then
			for index = 1, #lines do
				if (lines[index].at or 0) <= position then active = index else break end;
			end;
		end;

		local viewH = lyricView.AbsoluteSize.Y / unit;
		local pad = math.floor(viewH * 0.22);
		if lyricPad.PaddingTop.Offset ~= pad then
			lyricPad.PaddingTop, lyricPad.PaddingBottom = UDim.new(0, pad), UDim.new(0, pad);
		end;

		local fullH = lyricRoll.AbsoluteSize.Y / unit;
		local target = 0;
		local now = active > 0 and lyricRows[active];
		if lyricState.synced and now then
			local top = (now.AbsolutePosition.Y - lyricRoll.AbsolutePosition.Y) / unit;
			target = top + now.AbsoluteSize.Y / unit / 2 - viewH / 2;
		elseif not lyricState.synced and (Playback.duration or 0) > 0 then
			target = (fullH - viewH) * math.clamp(position / Playback.duration, 0, 1);
		end;
		target = math.clamp(target, 0, math.max(0, fullH - viewH));

		lyricState.offset = lyricState.offset + (target - lyricState.offset) * math.min(1, dt * 7);

		lyricRoll.Position = UDim2.fromOffset(0, -math.floor(lyricState.offset + 0.5));

		for index = 1, math.max(#lines, #lyricRows) do
			local entry = lines[index];

			if entry then
				local row = lyricRow(index);

				if row.Text ~= entry.text then row.Text = entry.text ~= "" and entry.text or " " end;
				if not row.Visible then row.Visible = true end;

				local away = lyricState.synced and math.abs(index - active) or 0;
				local near = math.clamp(1 - away / 3.2, 0, 1);
				local isNow = lyricState.synced and index == active;

				local wantAlpha = lyricState.synced and (0.62 - near * 0.62) or 0.1;
				local wantColour = TH.dim:Lerp(tone, isNow and 1 or near * 0.28);

				row.TextTransparency = row.TextTransparency + ((1 - (1 - wantAlpha) * lyricShow) - row.TextTransparency) * math.min(1, dt * 10);
				row.TextColor3 = row.TextColor3:Lerp(wantColour, math.min(1, dt * 10));

			else
				local row = lyricRows[index];

				if row and row.Visible then row.Text, row.Visible = "", false end;
			end;
		end;
	end;

	local lastSync = os.clock();
	local pollTask, syncBusy, syncQueued;
	local function playbackKey(state)
		return tostring(state.title or "") .. "|" .. tostring(state.artist or "");
	end;
	local function waitForPlayback()
		resetLyrics("Loading");
		Playback.title = "Loading...";
		Playback.artist = "";
		Playback.album = "";
		Playback.artwork = "";
		Playback.duration = 0;
		Playback.position = 0;
		Playback.playing = false;
		Playback.canSeek = false;
		Playback.canSkipNext = false;
		Playback.canSkipPrevious = false;
		Playback.status = "";
		Playback.trackId = nil;
	end;

	local function sync()
		local p = provider();
		local epoch = providerEpoch;
		local previousTrack = playbackKey(Playback);
		local nextState = table.clone(Playback);

		local ok = pcall(function()
			if p.read then
				p.read(nextState);
			elseif p.refreshState then
				p.refreshState(nextState);
			end;
		end);
		if not ok then nextState.status = "Provider unavailable" end;
		if not ALIVE or epoch ~= providerEpoch or provider() ~= p then return end;
		for key, value in pairs(nextState) do Playback[key] = value end;
		for _, key in ipairs({ "position", "duration", "volume" }) do
			local value = tonumber(Playback[key]);
			Playback[key] = value and value == value and math.abs(value) < math.huge and math.max(0, value) or 0;
		end;
		Playback.volume = math.min(Playback.volume, 100);
		Playback.position = Playback.duration > 0 and math.min(Playback.position, Playback.duration) or Playback.position;
		for _, key in ipairs({ "title", "artist", "artwork", "status" }) do Playback[key] = tostring(Playback[key] or "") end;
		for _, key in ipairs({ "playing", "canSeek", "canSkipNext", "canSkipPrevious", "shuffle", "loop" }) do Playback[key] = Playback[key] == true end;
		if playbackKey(Playback) ~= previousTrack then resetLyrics("Track changed") end;

		lastSync = os.clock();
	end;
	local function requestSync()
		if not ALIVE then return end;
		if syncBusy then syncQueued = true; return end;
		syncBusy = true;
		task.spawn(function()
			repeat
				syncQueued = false;
				pcall(sync);
			until not (ALIVE and syncQueued);
			syncBusy = false;
		end);
	end;

	pollTask = task.spawn(function()
		while ALIVE do
			if HUD.On then requestSync() end;

			task.wait(current == "Spotify" and 2 or 0.5);
		end;
	end);

	local shownArt = "";
	local shownTitle = "";
	local lastFlagReconcile = -math.huge;
	local frame;
	local function renderHud(dt)
		LPH_ATTRIBUTES(VM(NONE));
		if not (ALIVE and HUD.On) then return end;
		panel.Visible = true;

		local position = Playback.position;

		if Playback.playing then
			position = position + (os.clock() - lastSync);
		end;

		if Playback.duration > 0 then position = math.min(position, Playback.duration) end;

		local tone = accent();

		fill.BackgroundColor3 = tone;
		knob.BackgroundColor3 = tone;
		knob.Visible = Playback.duration > 0;
		artMark.Visible = (art.Image == "");
		artMark.ImageColor3 = tone;

		if Playback.duration > 0 then
			fill.Size = UDim2.fromScale(math.clamp(position / Playback.duration, 0, 1), 1);
		else
			fill.Size = UDim2.fromScale(0, 1);
		end;

		clock.Text = clockText(position);
		totalClock.Text = clockText(Playback.duration);

		local heading = Playback.title or "";

		if heading ~= shownTitle then
			shownTitle = heading;
			title.Text = heading;
		end;

		local status = Playback.status or "";
		local artistName = Playback.artist or "";
		artist.Text = artistName ~= "" and artistName or status;
		source.Text = string.upper(current) .. ((status ~= "" and artistName ~= "") and (" / " .. status) or "");
		source.TextColor3 = tone;

		local wantArt = coverFor(Playback.artwork);

		if wantArt ~= shownArt then
			artOld.Image = art.Image;
			artOld.ImageTransparency = 0;
			shownArt = wantArt;
			art.Image = wantArt;
			art.ImageTransparency = 1;

			TweenService:Create(art, TweenInfo.new(0.35), { ImageTransparency = 0 }):Play();
			TweenService:Create(artOld, TweenInfo.new(0.35), { ImageTransparency = 1 }):Play();
		end;

		playBtn.setGlyph(Playback.playing and "pause" or "play");
		prevBtn.setEnabled(Playback.canSkipPrevious);
		nextBtn.setEnabled(Playback.canSkipNext);
		seekHit.Active = Playback.canSeek;

		local reconcileFlags = os.clock() - lastFlagReconcile >= 0.25;
		if reconcileFlags then lastFlagReconcile = os.clock() end;
		if reconcileFlags and not dragging then
			local spotFlag = SaladUI.Flags.music_spot;
			local xFlag = SaladUI.Flags.music_x;
			local yFlag = SaladUI.Flags.music_y;
			local moved = false;

			if spotFlag then
				local value = spotFlag:GetValue();

				if type(value) == "table" then value = value[1] end;

				if type(value) == "string" and SPOTS[value] and value ~= HUD.Spot then
					HUD.Spot = value;
					moved = true;
				end;
			end;

			if xFlag then
				local value = tonumber(xFlag:GetValue());

				if value and value ~= HUD.OffsetX then HUD.OffsetX = value; moved = true end;
			end;

			if yFlag then
				local value = tonumber(yFlag:GetValue());

				if value and value ~= HUD.OffsetY then HUD.OffsetY = value; moved = true end;
			end;

			if moved then place(); placeLyrics() end;
		end;

		if reconcileFlags and not lyricDrag then
			local spotFlag = SaladUI.Flags.music_lyrics_spot;
			local xFlag = SaladUI.Flags.music_lyrics_x;
			local yFlag = SaladUI.Flags.music_lyrics_y;
			local moved = false;

			if spotFlag then
				local value = spotFlag:GetValue();

				if type(value) == "table" then value = value[1] end;

				if type(value) == "string" and SPOTS[value] and value ~= HUD.LyricsSpot then
					HUD.LyricsSpot = value;
					HUD.LyricsPlaced = true;
					moved = true;
				end;
			end;

			if xFlag then
				local value = tonumber(xFlag:GetValue());

				if value and value ~= HUD.LyricsX then HUD.LyricsX = value; HUD.LyricsPlaced = true; moved = true end;
			end;

			if yFlag then
				local value = tonumber(yFlag:GetValue());

				if value and value ~= HUD.LyricsY then HUD.LyricsY = value; HUD.LyricsPlaced = true; moved = true end;
			end;

			if moved then placeLyrics() end;
		end;

		wantLyrics();
		drawLyrics(position, math.min(dt, 0.1));

		if HUD.Visualizer then
			local beat = os.clock() * 6;

			for index, b in ipairs(bars) do
				if b.Visible then
					local height = Playback.playing
						and (5 + math.abs(math.sin(beat + index * 0.9)) * 11)
						or 4;

					b.Size = UDim2.fromOffset(3, height);
					b.BackgroundColor3 = tone;
				end;
			end;
		end;
	end;
	local function setHud(value)
		local opening = value == true and not HUD.On;
		if value == true then
			for _, name in ipairs({ "play", "pause", "next", "prev" }) do
				if not GLYPH[name] then GLYPH[name] = Remote.asset("images/ui_" .. name .. ".png") end;
			end;
			prevBtn.setGlyph("prev");
			playBtn.setGlyph(Playback.playing and "pause" or "play");
			nextBtn.setGlyph("next");
		end;
		HUD.On = value == true;
		panel.Visible = HUD.On;
		if HUD.On then
			if opening then waitForPlayback() end;
			if not frame then frame = RunService.RenderStepped:Connect(renderHud) end;
			requestSync();
			renderHud(0);
		else
			if frame then frame:Disconnect(); frame = nil end;
			lyricShow = 0;
			lyricPanel.Visible = false;
		end;
	end;

	playBtn.button.MouseButton1Click:Connect(function()
		if Playback.playing then command("pause") else command("play") end;

		task.delay(0.35, function() if HUD.On then requestSync() end end);
	end);

	nextBtn.button.MouseButton1Click:Connect(function()
		command("next");

		task.delay(0.5, function() if HUD.On then requestSync() end end);
	end);

	prevBtn.button.MouseButton1Click:Connect(function()
		command("previous");

		task.delay(0.5, function() if HUD.On then requestSync() end end);
	end);

	seekHit.MouseButton1Click:Connect(function()
		if not Playback.canSeek then return end;

		local mouse = UserInputService:GetMouseLocation();
		local at = track.AbsolutePosition.X;
		local width = math.max(1, track.AbsoluteSize.X);

		command("seek", math.clamp((mouse.X - at) / width, 0, 1));

		task.delay(0.4, function() if HUD.On then requestSync() end end);
	end);

	local function showPanels(name)
		local cards = {
			Spotify = Sections.Spotify,
			SoundCloud = Sections.SoundCloud,
			VK = Sections.Vk,
		};

		for key, card in pairs(cards) do
			if card and card.SetVisible then pcall(card.SetVisible, card, key == name) end;
		end;
		if Sections.MusicLibrary and Sections.MusicLibrary.SetVisible then Sections.MusicLibrary:SetVisible(name == "Local") end;
		if Sections.MusicRadio and Sections.MusicRadio.SetVisible then Sections.MusicRadio:SetVisible(name == "Local") end;
	end;

	-- a row of plain buttons, one look for the whole page
	local BUTTON_H = MOBILE and 36 or 30;
	local function musicButton(parent, text, order, total, callback)
		local button = new("TextButton", {
			LayoutOrder = order, Size = UDim2.new(1 / total, -8 * (total - 1) / total, 0, BUTTON_H),
			BackgroundColor3 = C.field, BorderSizePixel = 0, AutoButtonColor = false,
			FontFace = K.face.medium, Text = text, TextSize = 13, TextColor3 = C.value,
		}, parent);
		corner(button, 8);
		K.sheen(button, 0.82);
		button.MouseEnter:Connect(function() tween(button, 0.12, { BackgroundColor3 = C.hover, TextColor3 = C.text }) end);
		button.MouseLeave:Connect(function() tween(button, 0.16, { BackgroundColor3 = C.field, TextColor3 = C.value }) end);
		K.press(button);
		button.MouseButton1Click:Connect(function() SFX.click(); callback() end);
		return button;
	end;
	local function buttonRow(section, height)
		local row = rowBase(section.body, height or BUTTON_H + 8);
		new("UIListLayout", {
			FillDirection = Enum.FillDirection.Horizontal, SortOrder = Enum.SortOrder.LayoutOrder,
			VerticalAlignment = Enum.VerticalAlignment.Center, Padding = UDim.new(0, 8),
		}, row);
		return row;
	end;

	-- now playing: the cover, the track, where it is, and the controls
	do
		local sec = UI.section("Misc", "Music", 1, "Now Playing", true);
		local box = rowBase(sec.body, 128);
		local cover = new("ImageLabel", {
			Position = UDim2.fromOffset(0, 6), Size = UDim2.fromOffset(72, 72),
			BackgroundColor3 = C.field, BorderSizePixel = 0, ScaleType = Enum.ScaleType.Crop, Image = "",
		}, box);
		corner(cover, 10);
		K.sheen(cover, 0.84, true);
		local mark = K.glyph(cover, "music", 24, C.faint, { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5) });
		local title = K.text(box, {
			Position = UDim2.fromOffset(86, 14), Size = UDim2.new(1, -86, 0, 20),
			FontFace = K.face.semi, TextSize = 14, TextColor3 = C.text, Text = "",
		});
		local artist = K.text(box, { Position = UDim2.fromOffset(86, 36), Size = UDim2.new(1, -86, 0, 18), TextSize = 12, TextColor3 = C.sub, Text = "" });
		local status = K.text(box, { Position = UDim2.fromOffset(86, 56), Size = UDim2.new(1, -86, 0, 16), TextSize = 11, TextColor3 = C.faint, Text = "" });
		local seek = new("TextButton", {
			Position = UDim2.fromOffset(0, 88), Size = UDim2.new(1, 0, 0, 14),
			BackgroundTransparency = 1, Text = "", AutoButtonColor = false,
		}, box);
		local rail = new("Frame", {
			AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.fromScale(0, 0.5), Size = UDim2.new(1, 0, 0, 4),
			BackgroundColor3 = C.track, BorderSizePixel = 0,
		}, seek);
		corner(rail, "full");
		local fill = new("Frame", { Size = UDim2.fromScale(0, 1), BackgroundColor3 = C.accent, BorderSizePixel = 0 }, rail);
		corner(fill, "full");
		local elapsed = K.text(box, { Position = UDim2.fromOffset(0, 104), Size = UDim2.new(0.5, 0, 0, 16), TextSize = 11, TextColor3 = C.sub, Text = "0:00" });
		local total = K.text(box, {
			Position = UDim2.new(0.5, 0, 0, 104), Size = UDim2.new(0.5, 0, 0, 16), TextSize = 11, TextColor3 = C.sub,
			Text = "0:00", TextXAlignment = Enum.TextXAlignment.Right,
		});
		local controls = rowBase(sec.body, 50);
		new("UIListLayout", {
			FillDirection = Enum.FillDirection.Horizontal, HorizontalAlignment = Enum.HorizontalAlignment.Center,
			VerticalAlignment = Enum.VerticalAlignment.Center, SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 12),
		}, controls);
		local function control(icon, order, size, primary, callback)
			local b = new("TextButton", {
				LayoutOrder = order, Size = UDim2.fromOffset(size, size), BackgroundColor3 = primary and C.accent or C.field,
				BorderSizePixel = 0, AutoButtonColor = false, Text = "",
			}, controls);
			corner(b, "full");
			K.sheen(b, primary and 0.8 or 0.82, primary);
			local glyph = K.glyph(b, icon, primary and 18 or 15, primary and C.onAccent or C.value, {
				AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5),
			});
			if not primary then
				b.MouseEnter:Connect(function() tween(b, 0.12, { BackgroundColor3 = C.hover }) end);
				b.MouseLeave:Connect(function() tween(b, 0.16, { BackgroundColor3 = C.field }) end);
			end;
			K.press(b);
			b.MouseButton1Click:Connect(function() SFX.click(); callback() end);
			return glyph;
		end;
		local function after(seconds) task.delay(seconds, requestSync) end;
		control("square-rounded", 1, 32, false, function() command("stop"); after(0.35) end);
		control("player-skip-back", 2, 36, false, function() command("previous"); after(0.5) end);
		local playGlyph = control("player-play", 3, 44, true, function()
			if Playback.playing then command("pause") else command("play") end;
			after(0.35);
		end);
		control("player-skip-forward", 4, 36, false, function() command("next"); after(0.5) end);
		seek.MouseButton1Click:Connect(function()
			if not Playback.canSeek then return end;
			local x = UserInputService:GetMouseLocation().X;
			command("seek", math.clamp((x - rail.AbsolutePosition.X) / math.max(rail.AbsoluteSize.X, 1), 0, 1));
			after(0.4);
		end);
		local function clock(seconds)
			seconds = math.max(0, math.floor(tonumber(seconds) or 0));
			return string.format("%d:%02d", seconds // 60, seconds % 60);
		end;
		local _, musicPage = findSub("Misc", "Music");
		local shown, glyphPlaying = nil, nil;
		RunService.RenderStepped:Connect(function()
			if not (ALIVE and root.Visible and musicPage.page.Visible and musicPage.page.Parent == K.content) then return end;
			if os.clock() - lastSync > 0.6 then requestSync() end;
			title.Text = Playback.title ~= "" and Playback.title or "Nothing playing";
			artist.Text = Playback.artist;
			status.Text = Playback.status ~= "" and Playback.status or current;
			local position = Playback.position + (Playback.playing and (os.clock() - lastSync) or 0);
			local duration = Playback.duration;
			if duration > 0 then position = math.min(position, duration) end;
			fill.Size = UDim2.fromScale(duration > 0 and position / duration or 0, 1);
			elapsed.Text, total.Text = clock(position), clock(duration);
			local art = coverFor(Playback.artwork);
			if art ~= shown then shown = art; cover.Image = art; mark.Visible = art == "" end;
			if glyphPlaying ~= Playback.playing then
				glyphPlaying = Playback.playing;
				K.Icons.set(playGlyph, glyphPlaying and "player-pause" or "player-play");
			end;
		end);
	end;

	Sections.Music:AddLabel("Provider"):AddDropdown({
		Default = "Local",
		Values = { "Local", "Spotify", "SoundCloud", "VK" },
		Flag = "music_provider",
		Callback = function(v)
			local previous = provider();
			if previous.deactivate then previous.deactivate() elseif previous.pause then pcall(previous.pause) end;
			providerEpoch += 1;
			current = v;
			waitForPlayback();
			command("activate");
			command("setVolume", musicSettings.volume);
			command("setLoop", musicSettings.loop);

			showPanels(v);
			requestSync();
		end,
	});

	showPanels("Local");


	do
		local R = LocalProvider.radioState;
		local selected, songList, pageStatus;
		local songRows, refreshing, renderedPage, drawSerial = {}, false, nil, 0;
		local librarySec = UI.section("Misc", "Music", 3, "Library", true);
		local totalLabel = K.text(librarySec.tools, {
			LayoutOrder = 99, Size = UDim2.fromOffset(0, 20), AutomaticSize = Enum.AutomaticSize.X,
			Text = "", TextSize = 11, TextColor3 = C.faint, TextTruncate = Enum.TextTruncate.None,
		});
		local function value(flag)
			local field = SaladUI.Flags[flag]; return field and field:GetValue() or "";
		end;
		local function paintSelection()
			for _, row in ipairs(songRows) do
				local picked = row.id == selected;
				tween(row.button, 0.12, { BackgroundColor3 = picked and C.chip or C.field });
				row.title.TextColor3 = picked and C.text or C.value;
				row.title.FontFace = picked and K.face.semi or K.face.medium;
			end;
		end;
		local function refreshRows()
			local library = R.library;
			local heading = library.loading and "Loading..." or library.error or (library.page .. " / " .. library.pages);
			if pageStatus then pageStatus.Text = heading end;
			totalLabel.Text = library.total .. " tracks";
			if not songList then return end;
			local keep;
			for _, entry in ipairs(library.items) do if entry.id == selected then keep = selected; break end end;
			selected = keep;
			local pageKey = library.source .. "\0" .. library.query .. "\0" .. library.page;
			local scroll = renderedPage == pageKey and songList.CanvasPosition.Y or 0;
			renderedPage = pageKey;
			drawSerial += 1;
			local serial = drawSerial;
			for _, child in ipairs(songList:GetChildren()) do if child:IsA("GuiObject") then child:Destroy() end end;
			table.clear(songRows);
			for index, entry in ipairs(library.items) do
				local button = new("TextButton", {
					Name = "Song", LayoutOrder = index, Size = UDim2.new(1, 0, 0, 36),
					AutomaticSize = Enum.AutomaticSize.Y, BackgroundColor3 = C.field,
					BorderSizePixel = 0, AutoButtonColor = false, Text = "",
				}, songList);
				corner(button, 8);
				K.sheen(button, 0.86);
				pad(button, 0, 10, 0, 0);
				local title = K.text(button, {
					Name = "SongTitle", Position = UDim2.fromOffset(12, 10), Size = UDim2.new(1, -24, 0, 0),
					AutomaticSize = Enum.AutomaticSize.Y, Text = tostring(entry.title or entry.id),
					TextWrapped = true, TextTruncate = Enum.TextTruncate.None, TextYAlignment = Enum.TextYAlignment.Top,
					TextColor3 = C.value, TextSize = 13,
				});
				songRows[#songRows + 1] = { id = entry.id, button = button, title = title };
				button.MouseEnter:Connect(function() tween(button, 0.12, { BackgroundColor3 = C.hover }) end);
				button.MouseLeave:Connect(function() tween(button, 0.16, { BackgroundColor3 = entry.id == selected and C.chip or C.field }) end);
				button.MouseButton1Click:Connect(function()
					selected = entry.id; SFX.click(); paintSelection();
				end);
			end;
			if #library.items == 0 then
				K.text(songList, {
					Size = UDim2.new(1, 0, 0, 36), Text = library.loading and "Loading..." or library.error or "No tracks",
					TextWrapped = true, TextTruncate = Enum.TextTruncate.None, TextColor3 = C.faint,
				});
			end;
			paintSelection();
			task.defer(function()
				if ALIVE and songList.Parent and serial == drawSerial then K.scrollTo(songList, scroll, true) end;
			end);
		end;
		LocalProvider.onChange = function(library)
			if library and not refreshing then
				refreshing = true;
				local ok, err = pcall(function() LocalProvider.refreshLibrary(); refreshRows() end);
				refreshing = false;
				if not ok then warn("[Salad Murder] Music library: " .. tostring(err)) end;
			end;
			if current == "Local" then requestSync() end;
		end;
		Sections.MusicLibrary:AddLabel("Audio ID"):AddTextInput({
			Default = "", Placeholder = "Audio ID or Roblox asset link", Flag = "radio_audio_id",
		});
		do
			local row = buttonRow(librarySec);
			musicButton(row, "Play", 1, 2, function() LocalProvider.playCode(value("radio_audio_id")) end);
			musicButton(row, "Add to Queue", 2, 2, function() LocalProvider.add(value("radio_audio_id")) end);
		end;
		local radioOptions = Sections.Music;
		radioOptions:AddLabel("Volume"):AddSlider({
			Min = 0, Max = 100, Default = 50, Type = "%", Size = 100,
			Flag = "music_volume",
			Callback = function(v) musicSettings.volume = v; command("setVolume", v) end,
		});
		radioOptions:AddLabel("Loop"):AddToggle({
			Default = false, Flag = "music_loop",
			Callback = function(v) musicSettings.loop = v; command("setLoop", v) end,
		});
		local radioCard = Sections.MusicRadio;
		radioCard:AddLabel("MAX Volume"):AddToggle({
			Default = true, Flag = "radio_max_volume", Callback = function(v)
				LocalProvider.setMax(v);
				if current == "Local" then
					musicSettings.volume = R.volume;
					local field = SaladUI.Flags.music_volume;
					if field and field:GetValue() ~= R.volume then field:SetValue(R.volume) end;
				end;
			end,
		});
		radioCard:AddLabel("Mute Other Radios"):AddToggle({
			Default = false, Flag = "radio_mute_others", Callback = LocalProvider.setMute,
		});
		radioCard:AddLabel("Artwork"):AddTextInput({
			Default = "", Placeholder = "Image asset or URL", Flag = "radio_artwork", Callback = LocalProvider.setCover,
		});
		local sourceRow = Sections.MusicLibrary:AddLabel("Source"):AddDropdown({
			Default = "History", Values = { "History", "Favorites", "Catalog", "My Collection" }, Flag = "radio_library_source",
			Callback = function(v) LocalProvider.browse(v, tostring(value("radio_library_search")), 1) end,
		});
		Sections.MusicLibrary:AddLabel("Search"):AddTextInput({
			Default = "", Placeholder = "Title or audio ID", Flag = "radio_library_search",
			Callback = function(v) LocalProvider.browse(R.library.source, v, 1) end,
		});
		local action = musicButton;
		local pager = buttonRow(librarySec);
		local previous = action(pager, "Prev", 1, 3, function()
			local library = R.library;
			if library.page > 1 and not library.loading then LocalProvider.browse(library.source, library.query, library.page - 1) end;
		end);
		previous.Size = UDim2.fromOffset(56, BUTTON_H);
		pageStatus = new("TextButton", {
			LayoutOrder = 2, Size = UDim2.new(1, -128, 1, 0), Text = "", BackgroundTransparency = 1, AutoButtonColor = false,
			FontFace = K.face.medium, TextColor3 = C.sub, TextSize = 12, TextXAlignment = Enum.TextXAlignment.Center,
			TextWrapped = true,
		}, pager);
		pageStatus.MouseEnter:Connect(function() tween(pageStatus, 0.12, { TextColor3 = C.text }) end);
		pageStatus.MouseLeave:Connect(function() tween(pageStatus, 0.16, { TextColor3 = C.sub }) end);
		pageStatus.MouseButton1Click:Connect(function()
			if R.library.pages <= 1 then return end;
			SaladUI.Lib:ask({ title = "Page", hint = "1 - " .. R.library.pages, accept = "open", deny = "cancel", callback = function(text)
				local page = tonumber(tostring(text or ""):match("%d+"));
				if page then LocalProvider.browse(R.library.source, R.library.query, math.clamp(page, 1, R.library.pages)) end;
			end });
		end);
		local nextPage = action(pager, "Next", 3, 3, function()
			local library = R.library;
			if library.page < library.pages and not library.loading then LocalProvider.browse(library.source, library.query, library.page + 1) end;
		end);
		nextPage.Size = UDim2.fromOffset(56, BUTTON_H);
		local listHost = rowBase(librarySec.body, MOBILE and 220 or 280);
		listHost.Name = "SongListHost"; listHost.ClipsDescendants = true;
		songList = new("ScrollingFrame", {
			Name = "Songs", Size = UDim2.new(1, 0, 1, -8), BackgroundTransparency = 1, BorderSizePixel = 0,
			ClipsDescendants = true,
			CanvasSize = UDim2.new(), AutomaticCanvasSize = Enum.AutomaticSize.Y,
			ScrollBarThickness = 3, ScrollBarImageColor3 = C.sub,
			VerticalScrollBarInset = Enum.ScrollBarInset.None,
			ScrollingDirection = Enum.ScrollingDirection.Y, Active = true,
		}, listHost);
		K.scroller(songList);
		pad(songList, 1, 4, 0, 0);
		new("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 6) }, songList);
		librarySec:register("Tracks", nil, nil, listHost);
		local actions = buttonRow(librarySec);
		action(actions, "Play", 1, 4, function()
			if selected and not R.library.loading then LocalProvider.playList(R.library.queue, selected) end;
		end);
		action(actions, "Favorite", 2, 4, function()
			LocalProvider.toggleFavorite(selected or R.code);
		end);
		action(actions, "Queue", 3, 4, function()
			if selected and not R.library.loading then LocalProvider.add(selected) end;
		end);
		action(actions, "Remove", 4, 4, function()
			if selected then LocalProvider.deleteHistory(selected) end;
		end);
		local listTools = buttonRow(librarySec);
		action(listTools, "Refresh", 1, 3, function()
			LocalProvider.browse(R.library.source, R.library.query, R.library.page, true);
		end);
		action(listTools, "Clear History", 2, 3, LocalProvider.clearHistory);
		action(listTools, "Import Songs", 3, 3, LocalProvider.mergeSongs);
		refreshRows();
	end;
	Sections.Music:AddButton({ Name = "Clear Queue", Callback = function()
		LocalProvider.clear(); SoundCloud.clear(); Vk.clear(); requestSync();
	end });
	showPanels("Local");

	Sections.MusicHud:AddLabel("Now Playing HUD"):AddToggle({
		Name = "Now Playing HUD",
		Default = false,
		Flag = "music_hud",
		Callback = function(v)
			setHud(v);
		end,
	});

	Sections.MusicHud:AddLabel("Lyrics"):AddToggle({
		Name = "Lyrics",
		Default = false,
		Flag = "music_lyrics",
		Callback = function(v)
			HUD.Lyrics = v;
			resetLyrics(v and "Loading" or "");

			placeLyrics();
		end,
	});

	Sections.MusicHud:AddLabel("HUD Position"):AddDropdown({
		Default = "Bottom Left",
		Values = { "Top Left", "Top Right", "Bottom Left", "Bottom Right" },
		Flag = "music_spot",
		Callback = function(v) HUD.Spot = v; place() end,
	});

	local hudOptions = Sections.MusicHud;
	hudOptions:AddLabel("Layout"):AddDropdown({
		Default = "Full", Values = { "Full", "Compact" },
		Flag = "music_layout",
		Callback = function(v) HUD.Layout = v; relayout() end,
	});

	for _, entry in ipairs({
		{ "Show Artwork", "Artwork", "music_show_art", true },
		{ "Show Controls", "Controls", "music_show_controls", true },
		{ "Show Progress", "Progress", "music_show_progress", true },
		{ "Show Time", "Times", "music_show_time", true },
		{ "Show Visualizer", "Visualizer", "music_show_vis", true },
	}) do
		local key = entry[2];

		hudOptions:AddLabel(entry[1]):AddToggle({
			Name = entry[1], Default = entry[4], Flag = entry[3],
			Callback = function(v) HUD[key] = v; relayout() end,
		});
	end;

	hudOptions:AddLabel("Lyrics Height"):AddSlider({
		Min = 90, Max = 340, Default = 150, Rounding = 0, Size = 100,
		Flag = "music_lyrics_size",
		Callback = function(v) HUD.LyricsSize = v; placeLyrics() end,
	});

	hudOptions:AddLabel("Lyrics Corner"):AddDropdown({
		Default = "Bottom Left",
		Values = { "Top Left", "Top Right", "Bottom Left", "Bottom Right" },
		Flag = "music_lyrics_spot",
		Callback = function(v) HUD.LyricsSpot = v; HUD.LyricsPlaced = true; placeLyrics() end,
	});

	do
		local hidden = {
			{ "music_x", "OffsetX" },
			{ "music_y", "OffsetY" },
			{ "music_lyrics_x", "LyricsX" },
			{ "music_lyrics_y", "LyricsY" },
		};

		for _, entry in ipairs(hidden) do
			local id, key = entry[1], entry[2];

			SaladUI.Lib:hook(id, "number",
				function() return HUD[key] end,
				function(value)
					local number = tonumber(value);

					if number then
						HUD[key] = number;

						if key == "LyricsX" or key == "LyricsY" then HUD.LyricsPlaced = true end;
					end;
				end);

			SaladUI.Flags[id] = {
				GetValue = function() return HUD[key] end,
				SetValue = function(_, value)
					local number = tonumber(value);

					if number then HUD[key] = number end;
				end,
			};
		end;
	end;

	for _, entry in ipairs({
		{ "Opacity", "Opacity", "music_opacity", 10, 100, 100 },
		{ "Scale", "Scale", "music_scale", 60, 180, 100 },
		{ "Cover Size", "CoverSize", "music_cover", 32, 96, 52 },
	}) do
		local key = entry[2];

		hudOptions:AddLabel(entry[1]):AddSlider({
			Min = entry[4], Max = entry[5], Default = entry[6], Rounding = 0, Size = 100,
			Flag = entry[3],
			Callback = function(v) HUD[key] = v; relayout() end,
		});
	end;

	Sections.Spotify:AddLabel("Client ID"):AddTextInput({
		Default = "",
		Placeholder = "Client ID",
		Flag = "spotify_client",
		Callback = function(v) Spotify.setClientId(v) end,
	});

	Sections.Spotify:AddButton({
		Name = "Connect",
		Callback = function() Spotify.begin() end,
	});

	Sections.Spotify:AddLabel("Paste Code"):AddTextInput({
		Default = "",
		Placeholder = "Paste code",
		Flag = "spotify_code",
		Callback = function(v)
			if #tostring(v or "") > 20 then Spotify.finish(v) end;
		end,
	});

	Sections.Spotify:AddButton({
		Name = "Test Connection",
		Callback = function()
			task.spawn(function()
				if not Spotify.hasClientId() then
					Notification.new({ Title = "Spotify", Content = "No Client ID", Duration = 6 });

					return;
				end;

				local body, code, raw = Spotify.call("GET", "/me");

				if code == 200 and body then
					Notification.new({
						Title = "Spotify",
						Content = ("Connected as %s (%s)"):format(tostring(body.display_name or body.id), tostring(body.product)),
						Duration = 8,
					});

					return;
				end;

				local reason = (raw and type(raw.Body) == "string" and raw.Body ~= "") and raw.Body or "no response body";

				Notification.new({
					Title = "Spotify",
					Content = "Request failed (" .. tostring(code) .. ")",
					Duration = 12,
				});

				warn("[visuals] spotify /me -> " .. tostring(code) .. ": " .. reason);
			end);
		end,
	});

	Sections.Spotify:AddButton({
		Name = "Disconnect",
		Callback = function()
			Spotify.disconnect();

			Notification.new({ Title = "Spotify", Content = "Disconnected", Duration = 4 });
		end,
	});

	Sections.Spotify:AddLabel("Redirect URI: " .. REDIRECT, true);

	Sections.SoundCloud:AddLabel("Client ID"):AddTextInput({
		Default = "", Placeholder = "Client ID",
		Flag = "soundcloud_client",
		Callback = function(v) SC.Client = tostring(v or "") end,
	});

	Sections.SoundCloud:AddLabel("Link"):AddTextInput({
		Default = "", Placeholder = "Track or playlist URL",
		Flag = "soundcloud_link",
	});
	local function queueSelected(name, add, text)
		if current == name then add(text); return end;
		local field = SaladUI.Lib.pool.music_provider;
		if not (field and type(field.set) == "function") then return end;
		if not pcall(field.set, name) then return end;
		task.spawn(function()
			local deadline = os.clock() + 1;
			while ALIVE and current ~= name and os.clock() < deadline do task.wait() end;
			if ALIVE and current == name then add(text) end;
		end);
	end;

	Sections.SoundCloud:AddButton({
		Name = "Queue From SoundCloud",
		Callback = function()
			local box = SaladUI.Flags.soundcloud_link;
			local text = box and box:GetValue() or "";
			local client = SaladUI.Flags.soundcloud_client;
			if client then SC.Client = tostring(client:GetValue() or "") end;

			queueSelected("SoundCloud", SoundCloud.add, text);
		end,
	});

	Sections.Vk:AddLabel("Token"):AddTextInput({
		Default = "", Placeholder = "Access token",
		Flag = "vk_token",
		Callback = function(v) VK.Token = tostring(v or "") end,
	});

	Sections.Vk:AddLabel("Owner"):AddTextInput({
		Default = "", Placeholder = "Owner ID (optional)",
		Flag = "vk_link",
	});

	Sections.Vk:AddButton({
		Name = "Queue From VK",
		Callback = function()
			local box = SaladUI.Flags.vk_link;
			local text = box and box:GetValue() or "";
			local token = SaladUI.Flags.vk_token;
			if token then VK.Token = tostring(token:GetValue() or "") end;

			queueSelected("VK", Vk.add, text);
		end,
	});

	relayout();

	ESP.ClearMusic = onUnload("music", function()
		setHud(false);
		K.frontPanels[panel], K.frontPanels[lyricPanel] = nil, nil;
		providerEpoch += 1;

		if pollTask then pcall(task.cancel, pollTask) end;

		pcall(function() lyricPanel:Destroy() end);

		pcall(LocalProvider.stop);
		table.clear(audioCache); table.clear(covers); table.clear(coverBusy);
	end);
end);

guard("assets", function()
	local function assetUrl(rel)
		return Remote.asset(rel);
	end;

	local function listNames(folder, extensions, labels)
		local names, map, entries = { "Off" }, {}, {};
		if not isfile then return names, map end;
		-- no folders left to walk: the manifest is the catalogue now
		local ok, files = pcall(Remote.under, folder .. "/");
		if not ok or type(files) ~= "table" then return names, map end;
		for _, rel in ipairs(files) do
			local file = string.match(rel, "[^/]+$");
			local extension = file and file:match("%.(%w+)$");
			local direct = rel:sub(#folder + 2):find("/", 1, true) == nil;
			if direct and extension and extensions[extension:lower()] then
				local label = labels and labels[file];
				if not label then
					label = file:gsub("%.%w+$", ""):gsub("[_%-]+", " "):gsub("(%l)(%u)", "%1 %2");
					label = label:gsub("(%a[%w']*)", function(word) return word:sub(1, 1):upper() .. word:sub(2) end);
				end;
				entries[#entries + 1] = { name = label, file = file };
			end;
		end;
		table.sort(entries, function(a, b)
			if a.name:lower() == b.name:lower() then return a.file < b.file end;
			return a.name:lower() < b.name:lower();
		end);
		for _, entry in ipairs(entries) do
			local name = entry.name;
			if map[name] or name == "Off" then name = name .. " (" .. entry.file .. ")" end;
			names[#names + 1] = name;
			map[name] = folder .. "/" .. entry.file;
		end;
		return names, map;
	end;

	local _, cursorFiles = listNames("cursors", { png = true, jpg = true, jpeg = true });
	local soundNames, soundFiles = listNames("sounds", { wav = true, ogg = true, mp3 = true }, {
		["hentai1.wav"] = "Soft Pop", ["na naxuy.wav"] = "Impact Voice",
	});

	-- ----------------------------------------------------------- cursor ----
	-- There were three owners of one thing: this wrote Mouse.Icon every frame,
	-- the library draws its own ImageLabel and turns MouseIconEnabled off, and
	-- the crosshair's hide-original owns MouseIconEnabled too. Whichever wrote
	-- last that frame won, which is the random misalignment.
	--
	-- The reference has no cursor of its own - feature module:18265 just calls
	-- lib:setcursor and lib:setstyle. Same here, and the local PNGs go into the
	-- library's list.
	local lib = SaladUI.Lib;

	for name, file in pairs(cursorFiles or {}) do
		if name ~= "Off" and not lib.cursors[name] then
			lib.cursors[name] = ""; -- reserve the catalog name; resolve only on use
			lib.cursorlist[#lib.cursorlist + 1] = name;
		end;
	end;
	local setStyle, setCursor = lib.setstyle, lib.setcursor;
	local function resolveCursor(name)
		if cursorFiles[name] and lib.cursors[name] == "" then
			local url = assetUrl(cursorFiles[name]);
			if not url then return false end;
			lib.cursors[name] = url;
		end;
		return true;
	end;
	function lib:setstyle(name)
		if not self.cursor or resolveCursor(name) then return setStyle(self, name) end;
	end;
	function lib:setcursor(value)
		if value and not resolveCursor(self.style) then return end;
		return setCursor(self, value);
	end;

	table.sort(lib.cursorlist, function(a, b) return string.lower(a) < string.lower(b) end);

	lib.style = lib.style or lib.cursorlist[1];

	if #lib.cursorlist > 0 then
		local cursorRow = Sections.Cursor:AddLabel("Custom Cursor");

		cursorRow:AddToggle({
			Default = false, Flag = "cursor_on",
			Callback = function(v) pcall(function() lib:setcursor(v) end) end,
		});

		-- the same cursor over the game as well, not only over the open menu
		Sections.Cursor:AddLabel("Cursor In Game"):AddToggle({
			Default = false, Flag = "cursor_game",
			Callback = function(v) pcall(function() lib:setcursorgame(v) end) end,
		});

		Sections.Cursor:AddLabel("Cursor"):AddDropdown({
			Default = lib.style,
			Values = lib.cursorlist,
			Flag = "cursor_skin",
			Callback = function(v) pcall(function() lib:setstyle(v) end) end,
		});

		Sections.Cursor:AddLabel("Cursor Size"):AddSlider({
			Min = 16, Max = 96, Default = 32, Rounding = 0, Size = 90,
			Flag = "cursor_size",
			Callback = function(v)
				-- the library hardcodes 64x64 centred, which is the right
				-- hotspot for a dot and far too big for an arrow
				for _, child in ipairs(lib.scr:GetChildren()) do
					if child:IsA("ImageLabel") and child.ZIndex == 2147483647 then
						child.Size = UDim2.fromOffset(v, v);
						-- pixel art keeps hard edges when blown up; drawn art
						-- sampled down that way turns ragged
						child.ResampleMode = v > 64 and Enum.ResamplerMode.Pixelated or Enum.ResamplerMode.Default;
					end;
				end;
			end,
		});
	end;

	-- The game re-asserts Mouse.Icon on spawn and on some GUI states, which is
	-- the other half of the flicker. feature module:6505 swallows those writes at
	-- the metamethod; put back on unload.
	onUnload("cursor", function()
		pcall(function() lib:setcursor(false) end);
	end);

	-- -------------------------------------------------------- sounds --------
	-- This follows the reference sound path: a persistent template per role,
	-- cloned into SoundService for each play, and the game's own GunKill/Kill
	-- instance is stopped before it can overlap. The generic fallback keeps it
	-- usable in games that do not use MM2's exact hierarchy.
	local KILL_LABELS = {
		["kill_anime1.ogg"] = "Туда бомжа!",
		["kill_anime2.ogg"] = "Ой а где ты?",
		["kill_anime3.ogg"] = "На колени! На колени!",
		["kill_anime4.ogg"] = "Ой а мне его даже жалко",
		["kill_anime5.ogg"] = "Он слишком слаб",
		["kill_anime6.ogg"] = "Как же ты хорош?",
		["krasavchik.ogg"] = "Красавчик",
		["molodec.ogg"] = "Молодец",
		["na-koleni.ogg"] = "На колени",
		["sosat-sosat.ogg"] = "Сосать! Сосать!",
	};
	local killNames, killFiles = listNames("killsounds", { ogg = true, wav = true, mp3 = true }, KILL_LABELS);
	local killChoices = {};
	for _, name in ipairs(killNames) do if name ~= "Off" then killChoices[#killChoices + 1] = name end end;
	local killAliases = {
		["Kill Anime1"] = "Туда бомжа!", ["Kill Anime2"] = "Ой а где ты?",
		["Kill Anime3"] = "На колени! На колени!", ["Kill Anime4"] = "Ой а мне его даже жалко",
		["Kill Anime5"] = "Он слишком слаб", ["Kill Anime6"] = "Как же ты хорош?",
		Krasavchik = "Красавчик", Molodec = "Молодец", ["Na Koleni"] = "На колени",
		["Sosat Sosat"] = "Сосать! Сосать!", ["Сосать, сосать"] = "Сосать! Сосать!",
		["Туда, бомжа!"] = "Туда бомжа!", ["Ой, а где ты?"] = "Ой а где ты?",
		["На колени, на колени!"] = "На колени! На колени!",
		["Ой, а мне его даже жалко"] = "Ой а мне его даже жалко",
	};
	local soundService = game:GetService("SoundService");
	local ReplicatedStorage = game:GetService("ReplicatedStorage");
	local H = { Shoot = "Off", ShootVolume = 50, Kill = "Off", Kills = {}, KillVolume = 60, Hush = false,
		MuteShoot = true, MuteReload = true, MuteKill = true, MuteKillEffect = true };
	H.KillAliases, H.KillChoices = killAliases, killChoices;
	ESP.SoundSettings = H;
	local previousAudio = GLOBAL.__VisualsAudioRuntime;
	if type(previousAudio) == "table" and type(previousAudio.Stop) == "function" then pcall(previousAudio.Stop) end;
	local audioRuntime = {};
	local cfg = {
		Sheriff = { on = false, volume = 1.8 },
		Murderer = { on = false, volume = 1.8 },
	};
	local pools, sources, hooked, weaponHooks = {}, {}, {}, {};
	local activeSounds, deathHooks = {}, {};
	local lastAttackAt, lastAttackRole, lastShotAt = 0, nil, 0;
	local lastKillSignalAt, playingKill, lastKillName = -math.huge, nil, nil;
	local random = Random.new();

	local function toolKind(tool)
		if not tool or not tool:IsA("Tool") then return nil end;
		local name = string.lower(tool.Name);
		if tool:FindFirstChild("GunClient") or tool:FindFirstChild("Shoot")
			or name == "gun" or name == "revolver" or name:find("gun", 1, true) then return "Sheriff" end;
		if tool:FindFirstChild("KnifeClient") or tool:FindFirstChild("Events")
			or name == "knife" or name:find("knife", 1, true) or name:find("blade", 1, true) then return "Murderer" end;
	end;

	local function configFor(role)
		return role and cfg[role] or nil;
	end;

	local function resolve(name, pool)
		local rel = (pool or soundFiles)[name];
		if not rel then return nil end;
		local cached = sources[rel];
		if cached then return cached end;
		local id = assetUrl(rel);
		if id then sources[rel] = id end;
		return id;
	end;

	local function template(name)
		if not name or name == "Off" then return nil end;
		local id = resolve(name, killFiles);
		if not id then return nil end;
		local old = pools[name];
		if old and old.Parent and old.SoundId == id then return old end;
		if old then pcall(function() old:Destroy() end) end;
		local s = ownedSound();
		s.Name = "VisualsKillSoundTemplate";
		s.SoundId, s.Volume, s.Looped = id, 1, false;
		s.Parent = soundService;
		pools[name] = s;
		task.spawn(function() pcall(function() game:GetService("ContentProvider"):PreloadAsync({ s }) end) end);
		return s;
	end;
	local function selectedKills()
		local selected = {};
		for _, name in ipairs(killChoices) do if H.Kills[name] then selected[#selected + 1] = name end end;
		return selected;
	end;
	local function chooseKill()
		local selected = selectedKills();
		if #selected == 0 then return nil end;
		local index = random:NextInteger(1, #selected);
		if #selected > 1 and selected[index] == lastKillName then index = index % #selected + 1 end;
		lastKillName = selected[index];
		H.LastKill = lastKillName;
		return lastKillName;
	end;
	local function killGain(value)
		return math.clamp((tonumber(value) or 0) / 100 * 3, 0, 3);
	end;
	local function setKillSelection(value)
		local picked = {};
		if type(value) == "table" then
			for key, entry in pairs(value) do
				local name = type(key) == "string" and entry and key or type(entry) == "string" and entry or nil;
				if name and killFiles[name] then picked[name] = true end;
			end;
		elseif type(value) == "string" and value ~= "Off" and killFiles[value] then picked[value] = true end;
		H.Kills = picked;
		if next(picked) == nil then H.LastKill, lastKillName = nil, nil end;
		local first = selectedKills()[1];
		H.Kill = first or "Off";
		local enabled = first ~= nil;
		cfg.Murderer.on, cfg.Sheriff.on = enabled, enabled;
		for name in pairs(picked) do task.spawn(template, name) end;
	end;

	local function play(role)
		local c = configFor(role) or cfg.Murderer;
		if not (c and c.on) then return false end;
		-- Sound.Played and Humanoid.Died (often one per victim) share a single
		-- trailing-edge burst gate. A mass kill produces one replacement sound.
		local now = os.clock();
		local duplicate = now - lastKillSignalAt < 0.12;
		lastKillSignalAt = now;
		if duplicate then return false end;
		local name = chooseKill();
		local base = template(name);
		if not (c and c.on and base) then return false end;
		local ok = pcall(function()
			if playingKill and playingKill.Parent then playingKill:Stop(); activeSounds[playingKill] = nil; playingKill:Destroy() end;
			local s = base:Clone();
			s.Name = "VisualsKillSound";
			playingKill = s;
			activeSounds[s] = true;
			s.Volume, s.TimePosition, s.Parent = c.volume, 0, soundService;
			s:Play();
			task.delay(8, function()
				if playingKill == s then playingKill = nil end;
				activeSounds[s] = nil; s:Destroy();
			end);
		end);
		return ok;
	end;

	local function playNamed(name, pool, volume)
		local id = resolve(name, pool);
		if not id or name == "Off" then return false end;
		local ok = pcall(function()
			local s = ownedSound();
			activeSounds[s] = true;
			s.Name, s.SoundId, s.Volume = "VisualsHitSound", id, volume;
			s.Looped, s.Parent = false, soundService;
			s:Play();
			task.delay(8, function() activeSounds[s] = nil; s:Destroy() end);
		end);
		return ok;
	end;

	local function isKillName(name)
		name = string.lower(name or "");
		return name == "kill" or name == "gunkill" or name == "knife kill"
			or name:find("killeffect", 1, true) or name:find("elimination", 1, true)
			or name:find("death", 1, true) or name:find("murder", 1, true);
	end;

	local function ancestorTool(inst)
		local node = inst.Parent;
		while node and node ~= game do
			if node:IsA("Tool") then return node end;
			node = node.Parent;
		end;
	end;

	local function isLocalTool(tool)
		local character = LocalPlayer.Character;
		return tool and (tool:IsDescendantOf(LocalPlayer) or (character and tool:IsDescendantOf(character)));
	end;
	local function roleForSound(inst)
		local tool = ancestorTool(inst);
		if tool then return isLocalTool(tool) and toolKind(tool) or nil end;
		local character = LocalPlayer.Character;
		local name = string.lower(inst.Name);
		if character and inst:IsDescendantOf(character) and (name == "kill" or name == "gunkill")
			and os.clock() - lastAttackAt <= 1.5 then return lastAttackRole end;
	end;
	local function ownSound(inst)
		return inst:GetAttribute("VisualsOwned") or inst:IsDescendantOf(SaladUI.ScreenGui);
	end;
	-- Weapon/effect classification from script/salad - Copy.lua. Ambient,
	-- footsteps, music and our replacement/UI sounds are deliberately spared.
	local SHOT_NAMES = {
		fire = true, gunshot = true, gun = true, shoot = true, shot = true,
		bang = true, pistol = true, revolver = true,
	};
	local function wantedMute(inst)
		local name = inst.Name:lower();
		local parent = inst.Parent;
		local pName = parent and parent.Name:lower() or "";
		local grand = parent and parent.Parent;
		local gpName = grand and grand.Name:lower() or "";
		local ancestry = name;
		local node = parent;
		for _ = 1, 7 do
			if not node or node == game then break end;
			ancestry ..= " " .. string.lower(node.Name);
			node = node.Parent;
		end;
		local killContext = isKillName(name) or ancestry:find("killeffect", 1, true)
			or ancestry:find("kill effect", 1, true) or ancestry:find("knife kill", 1, true)
			or ancestry:find("murder", 1, true) or ancestry:find("victim", 1, true)
			or ancestry:find("ragdoll", 1, true) or ancestry:find("corpse", 1, true);
		if H.MuteShoot then
			local compound = name:find("gunshot", 1, true) or name:find("gunfire", 1, true)
				or name:find("pistolshot", 1, true) or name:find("revolvershot", 1, true);
			local underGun = pName:find("gun", 1, true) or pName:find("revolver", 1, true) or pName:find("pistol", 1, true)
				or gpName:find("gun", 1, true) or gpName:find("revolver", 1, true) or gpName:find("pistol", 1, true);
			if SHOT_NAMES[name] or compound or (underGun and not name:find("reload", 1, true)) then return true end;
		end;
		if H.MuteReload and (name:find("reload", 1, true) or name:find("cock", 1, true)
			or name:find("cylinder", 1, true) or name:find("spin", 1, true)) then return true end;
		if H.MuteKill and (isKillName(name) or name:find("slash", 1, true) or name:find("stab", 1, true)
			or name:find("knife", 1, true) or name:find("hit", 1, true)
			or pName:find("knife", 1, true) or gpName:find("knife", 1, true)) then return true end;
		if H.MuteKillEffect and (killContext or name:find("killeffect", 1, true) or name:find("effect", 1, true)
			or name:find("death", 1, true) or name:find("dissolve", 1, true) or name:find("freeze", 1, true)
			or name:find("electric", 1, true) or name:find("vapor", 1, true) or name:find("shatter", 1, true)
			or pName:find("effect", 1, true) or pName:find("killeffect", 1, true)
			or pName:find("nl_killfx", 1, true) or gpName:find("nl_killfx", 1, true)) then return true end;
		return false;
	end;
	local function mute(inst)
		local entry = hooked[inst];
		if not entry then return end;
		if H.Hush and not ownSound(inst) and wantedMute(inst) then
			if not entry.muted then entry.volume = inst.Volume end;
			entry.muted = true;
			if inst.Volume ~= 0 then inst.Volume = 0 end;
		elseif entry.muted then
			entry.muted = false;
			if inst.Volume == 0 then inst.Volume = entry.volume end;
		end;
	end;
	local function unhookSound(inst)
		local entry = hooked[inst];
		if not entry then return end;
		hooked[inst] = nil;
		for _, connection in ipairs(entry.conns) do connection:Disconnect() end;
		if entry.muted and inst.Parent and inst.Volume == 0 then inst.Volume = entry.volume end;
	end;
	local function retireLegacyMute(inst)
		-- Old builds could leave a live Hush hook after their UI was unloaded.
		-- Migrate only our named chunk and exact sound-record shape, never a
		-- game's callbacks. Optional executor introspection is not required
		-- for fresh sessions; the runtime registry handles all new builds.
		local inspect = getupvalues or (debug and debug.getupvalues);
		if type(getconnections) ~= "function" or type(inspect) ~= "function" or not (debug and debug.info) then return end;
		local ok, callbacks = pcall(getconnections, inst:GetPropertyChangedSignal("Volume"));
		if not ok then return end;
		for _, connection in ipairs(callbacks) do
			local fn = connection.Function;
			if type(fn) == "function" then
				local gotSource, source = pcall(debug.info, fn, "s");
				if gotSource and (source == "visuals" or source == "@visuals") then
					local gotValues, values = pcall(inspect, fn);
					local settings, entry;
					if gotValues and type(values) == "table" then
						for _, value in pairs(values) do
							if type(value) == "table" then
								if type(value.Hush) == "boolean" and type(value.Shoot) == "string" and type(value.Kill) == "string"
									and type(value.ShootVolume) == "number" and type(value.KillVolume) == "number" then settings = value end;
								if type(value.volume) == "number" and type(value.conns) == "table" then entry = value end;
							end;
						end;
					end;
					if settings and settings ~= H and entry then
						settings.Hush = false;
						for _, old in ipairs(entry.conns) do pcall(function() old:Disconnect() end) end;
						if entry.muted and inst.Volume == 0 then inst.Volume = entry.volume end;
						entry.muted = false;
					end;
				end;
			end;
		end;
	end;
	local function hookSound(inst)
		if not ALIVE or not inst:IsA("Sound") or ownSound(inst) or hooked[inst] then return end;
		retireLegacyMute(inst);
		local entry = { volume = inst.Volume, conns = {}, lastFire = -math.huge };
		hooked[inst] = entry;
		local function keep(connection) entry.conns[#entry.conns + 1] = connection end;
		local function fire()
			if not ALIVE then return end;
			mute(inst);
			if not isKillName(inst.Name) or os.clock() - entry.lastFire < 0.08 then return end;
			local role = roleForSound(inst);
			local c = configFor(role);
			if not (role and c and c.on) then return end;
			entry.lastFire = os.clock();
			pcall(function() inst:Stop() end);
			play(role);
		end;
		keep(inst.Played:Connect(fire));
		keep(inst:GetPropertyChangedSignal("Playing"):Connect(function() mute(inst) end));
		keep(inst:GetPropertyChangedSignal("Parent"):Connect(function() mute(inst) end));
		keep(inst:GetPropertyChangedSignal("Name"):Connect(function() mute(inst) end));
		keep(inst:GetAttributeChangedSignal("VisualsOwned"):Connect(function() mute(inst) end));
		keep(inst:GetPropertyChangedSignal("Volume"):Connect(function()
			if not entry.muted then entry.volume = inst.Volume end;
			if ALIVE and H.Hush and inst.Volume ~= 0 then mute(inst) end;
		end));
		keep(inst.Destroying:Connect(function() unhookSound(inst) end));
		mute(inst);
	end;
	local function hookWeapon(tool)
		local role = toolKind(tool);
		if not ALIVE or not role or not isLocalTool(tool) or weaponHooks[tool] then return end;
		local record = {};
		weaponHooks[tool] = record;
		record.attack = tool.Activated:Connect(function()
			if not ALIVE or not isLocalTool(tool) then return end;
			lastAttackAt, lastAttackRole = os.clock(), role;
		end);
		record.destroy = tool.Destroying:Connect(function()
			weaponHooks[tool] = nil;
			record.attack:Disconnect(); record.destroy:Disconnect();
		end);
	end;
	local function hookDeath(human)
		if deathHooks[human] then return end;
		local record = {};
		deathHooks[human] = record;
		record.death = human.Died:Connect(function()
			if not ALIVE then return end;
			local creator = human:FindFirstChild("creator") or human:FindFirstChild("Creator");
			if not (creator and creator:IsA("ObjectValue") and creator.Value == LocalPlayer) then return end;
			local role = lastAttackRole;
			if not role then
				for _, tool in ipairs((LocalPlayer.Character or LocalPlayer):GetChildren()) do role = toolKind(tool); if role then break end end;
			end;
			play(role or "Murderer");
		end);
		record.destroy = human.Destroying:Connect(function()
			deathHooks[human] = nil;
			record.death:Disconnect(); record.destroy:Disconnect();
		end);
	end;
	local function discover(inst)
		if not ALIVE then return end;
		if inst:IsA("Tool") then hookWeapon(inst)
		elseif inst:IsA("Sound") then hookSound(inst)
		elseif inst:IsA("Humanoid") then hookDeath(inst) end;
	end;
	local function scan()
		for inst in pairs(hooked) do mute(inst) end;
	end;
	SaladUI:AddSignal(workspace.DescendantAdded:Connect(discover));
	SaladUI:AddSignal(soundService.DescendantAdded:Connect(discover));
	SaladUI:AddSignal(LocalPlayer.DescendantAdded:Connect(discover));
	local function watchLocalCharacter(character)
		if not ALIVE or LocalPlayer.Character ~= character then return end;
		SaladUI:AddSignal(character.DescendantAdded:Connect(discover));
		for _, inst in ipairs(character:GetDescendants()) do discover(inst) end;
	end;
	SaladUI:AddSignal(LocalPlayer.CharacterAdded:Connect(watchLocalCharacter));
	if LocalPlayer.Character then watchLocalCharacter(LocalPlayer.Character) end;
	local function removed(inst)
		if hooked[inst] then unhookSound(inst) end;
	end;
	SaladUI:AddSignal(workspace.DescendantRemoving:Connect(removed));
	SaladUI:AddSignal(soundService.DescendantRemoving:Connect(removed));
	SaladUI:AddSignal(LocalPlayer.DescendantRemoving:Connect(removed));
	audioRuntime.Active = true;
	audioRuntime.ScanTask = scanDescendantsAsync("sound scan", { workspace, soundService, LocalPlayer }, discover, function()
		return audioRuntime.Active;
	end, 512);
	-- The shoot sound goes off on the shot. It used to wait for Combat.Hit, a
	-- recorded drop in somebody's health, and MM2 never produces one: a shot
	-- there kills outright or misses, so the sound never played at all.
	-- GunFired is the server saying the gun really went off, which also keeps
	-- a click during the cooldown silent.
	local shotRemote, shotConn;
	local function playShot()
		local now = os.clock();
		if H.Shoot == "Off" or now - lastShotAt <= 0.045 then return end;
		lastShotAt = now;
		playNamed(H.Shoot, soundFiles, H.ShootVolume / 100);
	end;
	local function bindShots()
		local services = ReplicatedStorage:FindFirstChild("ClientServices");
		local weapons = services and services:FindFirstChild("WeaponService");
		local remote = weapons and weapons:FindFirstChild("GunFired");
		if not (remote and remote:IsA("RemoteEvent")) or remote == shotRemote then return end;
		if shotConn then shotConn:Disconnect() end;
		shotRemote = remote;
		shotConn = remote.OnClientEvent:Connect(function(gun)
			local character = LocalPlayer.Character;
			if ALIVE and typeof(gun) == "Instance" and character and gun:IsDescendantOf(character) then playShot() end;
		end);
	end;
	pcall(bindShots);
	task.spawn(function()
		-- the remote is replaced on a rejoin and can arrive after us
		while audioRuntime.Active do
			task.wait(2);
			pcall(bindShots);
		end;
	end);
	local combatConnections = {};
	if ESP.Combat then
		combatConnections[#combatConnections + 1] = ESP.Combat.Attack.Event:Connect(function(info)
			if type(info) ~= "table" then return end;
			lastAttackAt = info.at or os.clock();
			lastAttackRole = toolKind(info.tool) or (info.kind == "shot" and "Sheriff") or (info.kind == "melee" and "Murderer") or lastAttackRole;
			-- outside MM2 there is no GunFired, so a local shot is the trigger
			if not shotRemote and info.kind == "shot" and (info.source == "tool" or info.source == "input") then playShot() end;
		end);
		combatConnections[#combatConnections + 1] = ESP.Combat.Kill.Event:Connect(function(info)
			local attack = type(info) == "table" and info.attack or nil;
			local role = attack and (toolKind(attack.tool) or (attack.kind == "shot" and "Sheriff") or (attack.kind == "melee" and "Murderer")) or lastAttackRole;
			play(role or "Murderer");
		end);
	end;

	Sections.WorldMisc:AddLabel("Shoot"):AddDropdown({
		Default = "Off", Values = soundNames, Flag = "hitsound",
		Callback = function(v) H.Shoot = v; end,
	});
	Sections.WorldMisc:AddLabel("Shoot Volume"):AddSlider({
		Min = 0, Max = 100, Default = 50, Type = "%", Size = 90, Flag = "sound_volume",
		Callback = function(v) H.ShootVolume = v; end,
	});
	Sections.WorldMisc:AddLabel("Kill"):AddDropdown({
		Default = {}, Values = killChoices, Multi = true, Flag = "killsound",
		Callback = setKillSelection,
	});
	Sections.WorldMisc:AddLabel("Kill Volume"):AddSlider({
		Min = 0, Max = 100, Default = 60, Type = "%", Size = 90, Flag = "kill_volume",
		Callback = function(v) H.KillVolume = v; cfg.Murderer.volume, cfg.Sheriff.volume = killGain(v), killGain(v); end,
	});
	-- hear what is picked without waiting for a shot or a kill
	Sections.WorldMisc:AddButton({
		Name = "Test Shoot Sound",
		Callback = function()
			if H.Shoot == "Off" then
				Notification.new({ Title = "Sounds", Content = "No sound selected", Duration = 3 });
				return;
			end;
			playNamed(H.Shoot, soundFiles, H.ShootVolume / 100);
		end,
	});
	Sections.WorldMisc:AddButton({
		Name = "Test Kill Sound",
		Callback = function()
			lastKillSignalAt = 0;
			if not play("Murderer") then
				Notification.new({ Title = "Sounds", Content = "No sound selected", Duration = 3 });
			end;
		end,
	});

	local muteRow = Sections.WorldMisc:AddLabel("Mute Game Sounds");
	muteRow:AddToggle({
		Name = "Mute Game Sounds", Default = false, Flag = "sound_hush",
		Callback = function(v) H.Hush = v == true; scan() end,
	});
	local muteOptions = muteRow:AddOption(1);
	for _, option in ipairs({
		{ "Shoot", "MuteShoot", "sound_mute_shoot" },
		{ "Reload", "MuteReload", "sound_mute_reload" },
		{ "Kill (Murderer)", "MuteKill", "sound_mute_murder" },
		{ "Kill Effect", "MuteKillEffect", "sound_mute_effect" },
	}) do
		local key = option[2];
		muteOptions:AddLabel(option[1]):AddToggle({
			Default = true, Flag = option[3],
			Callback = function(v) H[key] = v == true; scan() end,
		});
	end;

	ESP.ClearSounds = onUnload("sounds", function()
		audioRuntime.Active = false;
		H.Hush = false;
		playingKill, lastKillSignalAt = nil, -math.huge;
		if GLOBAL.__VisualsAudioRuntime == audioRuntime then GLOBAL.__VisualsAudioRuntime = nil end;
		for inst in pairs(activeSounds) do inst:Destroy() end;
		table.clear(activeSounds);
		for _, record in pairs(weaponHooks) do record.attack:Disconnect(); record.destroy:Disconnect() end;
		for _, record in pairs(deathHooks) do record.death:Disconnect(); record.destroy:Disconnect() end;
		for _, connection in ipairs(combatConnections) do connection:Disconnect() end;
		table.clear(combatConnections);
		if shotConn then shotConn:Disconnect(); shotConn = nil end;
		table.clear(weaponHooks); table.clear(deathHooks);
		for inst in pairs(hooked) do unhookSound(inst) end;
		table.clear(hooked);
		for role, s in pairs(pools) do pcall(function() s:Destroy() end); pools[role] = nil end;
	end);
	audioRuntime.Stop = ESP.ClearSounds;
	GLOBAL.__VisualsAudioRuntime = audioRuntime;

	ESP.Assets = { Url = assetUrl, Cursors = cursorFiles, Sounds = soundFiles };
end);

guard("trade", function()
	if not Sections.Trade then return end; -- MM2 only
	local players = game:GetService("Players")
	local rs = game:GetService("ReplicatedStorage")
	local lp = players.LocalPlayer
	local show_on, worker = false, 0
	local sync, id_index = nil, nil
	local store = { index = nil, checked = 0, busy = false, version = 0 }
	GLOBAL.__SV_STORE = store
	local FEED_URL = "https://raw.githubusercontent.com/yanaa-12/mm2-trading/main/docs/data/latest.csv"
	local REFRESH_AFTER, RETRY_AFTER = 300, 30
	local RARITY_PAGE = {
		Common = "commons", Uncommon = "uncommons", Rare = "rares",
		Legendary = "legendaries", Godly = "godlies", Ancient = "ancients",
		Unique = "uniques", Classic = "vintages", Vintage = "vintages",
		Christmas = "misc", Halloween = "misc",
	}

	local function norm(s)
		return (string.gsub(string.lower(tostring(s or "")), "[^%w]", ""))
	end

	local function comma(n)
		local s = tostring(n)
		while true do
			local r
			s, r = string.gsub(s, "^(-?%d+)(%d%d%d)", "%1,%2")
			if r == 0 then break end
		end
		return s
	end

	local function format_value(n)
		local whole, fraction = string.format("%.3f", n):match("^(%-?%d+)%.(%d+)$")
		fraction = fraction:gsub("0+$", "")
		return comma(whole) .. (fraction ~= "" and "." .. fraction or "")
	end

	local function canonical(name, chroma)
		local raw = tostring(name or "")
		local key = norm(raw)
		if chroma then
			if key:sub(1, 6) == "chroma" then key = key:sub(7)
			elseif raw:match("^%s*[Cc]%.") or raw:match("^%s*[Cc]%s+") then key = key:sub(2) end
		end
		return key
	end

	local function csv_fields(line)
		local cells, field = {}, {}
		local quoted, i = false, 1
		while i <= #line do
			local c = line:sub(i, i)
			if c == '"' then
				if quoted and line:sub(i + 1, i + 1) == '"' then
					field[#field + 1] = '"'
					i = i + 1
				else
					quoted = not quoted
				end
			elseif c == "," and not quoted then
				cells[#cells + 1] = table.concat(field)
				field = {}
			else
				field[#field + 1] = c
			end
			i = i + 1
		end
		cells[#cells + 1] = table.concat(field)
		return cells
	end

	local function parse_feed(body)
		if type(body) ~= "string" or #body < 10000 then return nil end
		local index, count, categories = {}, 0, {}
		for line in body:gmatch("[^\r\n]+") do
			local cells = csv_fields(line)
			local name, category, value = cells[1], cells[2], tonumber(cells[3])
			if category and value and value >= 0 and name and name ~= "" then
				local key = canonical(name, category == "chromas")
				if key ~= "" then
					local group = index[category]
					if not group then group = {}; index[category] = group end
					local bucket = group[key]
					if not bucket then bucket = {}; group[key] = bucket end
					bucket[#bucket + 1] = { value = value, year = tostring(cells[8] or ""):match("%d%d%d%d") }
					categories[category] = true
					count = count + 1
				end
			end
		end
		local category_count = 0
		for _ in pairs(categories) do category_count = category_count + 1 end
		if count < 500 or category_count < 8 then return nil end
		return index
	end

	local function load_snapshot()
		if store.index then return end
		store.index = parse_feed(Remote.body("data/supremevalues.txt"))
		if store.index then store.version = store.version + 1 end
	end

	local function http_get(url)
		local ok, body = Remote.invoke(function() return game:HttpGet(url, true) end, 12)
		if ok and type(body) == "string" and body:find("name,category,value", 1, true) then return body end
		local env = getgenv and getgenv() or {}
		local req = rawget(env, "request") or rawget(env, "http_request")
			or (syn and syn.request) or (http and http.request) or (fluxus and fluxus.request)
		if type(req) == "function" then
			local fine, res = Remote.invoke(function() return req({
				Url = url, Method = "GET", Timeout = 12,
				Headers = { ["Accept"] = "text/plain" },
			}) end, 12)
			if fine and type(res) == "table" then return res.Body end
		end
		return nil
	end

	local function refresh_feed(force)
		if store.busy or not Remote.current() then return end
		if not force and os.clock() - store.checked < REFRESH_AFTER then return end
		store.busy = true
		store.checked = os.clock()
		task.spawn(function()
			local url = FEED_URL .. "?t=" .. tostring(math.floor(os.time() / REFRESH_AFTER))
			local ok, index = pcall(function() return parse_feed(http_get(url)) end)
			if ok and index and Remote.current() then
				store.index = index
				store.version = store.version + 1
			else
				store.checked = os.clock() - REFRESH_AFTER + RETRY_AFTER
			end
			store.busy = false
		end)
	end

	local function item_keys(data)
		local base = canonical(data.ItemName or data.Name, data.Chroma == true)
		local kind = norm(data.ItemType)
		local year = tostring(data.Year or ""):match("%d%d%d%d")
		local keys = {}
		if base == "" then return keys end
		if (kind == "gun" or kind == "knife") and base:sub(-#kind) ~= kind then
			if year then keys[#keys + 1] = base .. kind .. year end
			keys[#keys + 1] = base .. kind
		end
		if year and base:sub(-4) ~= year then keys[#keys + 1] = base .. year end
		keys[#keys + 1] = base
		return keys
	end

	local function match_bucket(bucket, year)
		if not bucket then return nil end
		if year then
			for _, rec in ipairs(bucket) do
				if rec.year == year then return rec.value end
			end
			if #bucket == 1 and bucket[1].year then return nil end
		end
		local first = bucket[1].value
		for i = 2, #bucket do
			if bucket[i].value ~= first then return nil end
		end
		return first
	end

	local function resolve(dtype, _, data)
		local index = store.index
		if not index then return nil end
		local keys = item_keys(data)
		local year = tostring(data.Year or ""):match("%d%d%d%d")
			or tostring(data.ItemName or ""):match("%d%d%d%d")
		local primary = data.Chroma and "chromas"
			or (dtype == "Pets" and "pets")
			or RARITY_PAGE[data.Rarity or ""]
		local function search(category)
			local group = index[category]
			if not group then return nil, false end
			local found = false
			for _, key in ipairs(keys) do
				local bucket = group[key]
				if bucket then
					found = true
					local value = match_bucket(bucket, year)
					if value then return value, true end
				end
			end
			return nil, found
		end
		if primary then
			local value, found = search(primary)
			if value then return value end
			if found then return false end
		end
		if data.Chroma then return false end
		for _, category in ipairs({ "godlies", "ancients", "uniques", "vintages",
			"legendaries", "rares", "uncommons", "commons", "pets", "misc" }) do
			if category ~= primary then
				local value = search(category)
				if value then return value end
			end
		end
		return false
	end

	local function trade_root()
		local pg = lp:FindFirstChildOfClass("PlayerGui")
		local gui = pg and pg:FindFirstChild("TradeGUI")
		local cont = gui and gui:FindFirstChild("Container")
		return cont and cont:FindFirstChild("Trade"), gui
	end

	local function make_label(parent, name, size, pos, anchor, maxtext, align)
		local l = parent:FindFirstChild(name)
		if not l then
			l = Instance.new("TextLabel")
			l.Name = name
			l.Text = ""
			l.Parent = parent
		end
		local total = name == "SV_Total"
		l.AnchorPoint = anchor
		l.Position = pos
		l.Size = size
		l.BackgroundColor3 = total and Color3.fromRGB(43, 36, 25) or Color3.fromRGB(20, 24, 29)
		l.BackgroundTransparency = total and 0.06 or 0.12
		l.BorderSizePixel = 0
		l.Font = total and Enum.Font.GothamBold or Enum.Font.GothamMedium
		l.TextColor3 = total and Color3.fromRGB(255, 222, 150) or Color3.fromRGB(248, 230, 190)
		l.TextStrokeTransparency = 1
		l.TextXAlignment = align
		l.TextScaled = true
		l.ClipsDescendants = true
		l.RichText = false
		l.ZIndex = 40
		local con = l:FindFirstChildOfClass("UITextSizeConstraint") or Instance.new("UITextSizeConstraint")
		con.MaxTextSize = maxtext + 1
		con.MinTextSize = 9
		con.Parent = l
		local corner = l:FindFirstChildOfClass("UICorner") or Instance.new("UICorner")
		corner.CornerRadius = UDim.new(0, total and 7 or 5)
		corner.Parent = l
		if total then
			local stroke = l:FindFirstChildOfClass("UIStroke") or Instance.new("UIStroke")
			stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
			stroke.Color = Color3.fromRGB(155, 120, 62)
			stroke.Transparency = 0.48
			stroke.Thickness = 1
			stroke.Parent = l
		end
		return l
	end

	local text_service = game:GetService("TextService")
	local function total_label(offer, caption, compact)
		local l = make_label(offer, "SV_Total",
			UDim2.fromOffset(90, 24), UDim2.new(0.025, 0, 1, -148),
			Vector2.new(0, 0.5), 14, Enum.TextXAlignment.Center)

		local width = offer.AbsoluteSize.X
		local left = width * 0.025
		local center_y = offer.AbsoluteSize.Y - 148
		local title = offer:FindFirstChild("Title")
		if title and title.TextBounds.X > 4 then
			left = (title.AbsolutePosition.X - offer.AbsolutePosition.X) + title.TextBounds.X + 10
			center_y = (title.AbsolutePosition.Y - offer.AbsolutePosition.Y) + title.AbsoluteSize.Y / 2
		end
		local right = width - 8
		local user = offer:FindFirstChild("Username")
		if user and user.TextBounds.X > 4 then
			local edge = (user.AbsolutePosition.X - offer.AbsolutePosition.X) + user.AbsoluteSize.X - user.TextBounds.X
			right = math.min(right, edge - 8)
		end
		local available = right - left
		local natural = text_service:GetTextSize(caption, 15, Enum.Font.GothamBold, Vector2.new(500, 24)).X + 18
		if natural > available then
			caption = compact
			natural = text_service:GetTextSize(caption, 15, Enum.Font.GothamBold, Vector2.new(500, 24)).X + 18
		end
		l.Text = caption
		l:SetAttribute("SV_NoRoom", available < math.min(55, natural))
		l.Position = UDim2.fromOffset(math.floor(left), math.floor(center_y))
		l.Size = UDim2.fromOffset(math.max(0, math.floor(math.min(natural, available))), 24)
		return l
	end

	local function card_label(card, caption)
		local l = make_label(card, "SV_Value",
			UDim2.fromOffset(40, 20), UDim2.new(1, -5, 0, 4),
			Vector2.new(1, 0), 15, Enum.TextXAlignment.Center)
		l.Text = caption
		local natural = text_service:GetTextSize(caption, 16, Enum.Font.GothamMedium, Vector2.new(300, 20)).X + 14
		l.Size = UDim2.fromOffset(math.min(natural, math.max(30, card.AbsoluteSize.X - 10)), 20)
		local inner = card:FindFirstChild("Container")
		local amt = inner and inner:FindFirstChild("Amount")
		local stacked = amt and amt.Visible and string.match(amt.Text or "", "[xX]%s*%d") ~= nil
		l.Position = UDim2.new(1, -5, 0, stacked and 32 or 4)
		return l
	end

	local function clear_side(offer)
		if not offer then return end
		local l = offer:FindFirstChild("SV_Total")
		if l then l.Visible = false end
		local cont = offer:FindFirstChild("Container")
		if not cont then return end
		for _, ch in ipairs(cont:GetChildren()) do
			local v = ch:FindFirstChild("SV_Value")
			if v then v.Visible = false end
		end
	end

	local function wipe_labels()
		local root = trade_root()
		if not root then return end
		for _, side in ipairs({ "YourOffer", "TheirOffer" }) do
			local offer = root:FindFirstChild(side)
			if offer then
				local l = offer:FindFirstChild("SV_Total")
				if l then l:Destroy() end
				local cont = offer:FindFirstChild("Container")
				if cont then
					for _, ch in ipairs(cont:GetChildren()) do
						local v = ch:FindFirstChild("SV_Value")
						if v then v:Destroy() end
					end
				end
			end
		end
	end

	local function ensure_sync()
		if sync then return sync end
		local database = rs:FindFirstChild("Database")
		local module = database and database:FindFirstChild("Sync")
		if not module or not module:IsA("ModuleScript") then return nil end
		local ok, mod = Remote.invoke(function() return require(module) end, 5)
		if ok and type(mod) == "table" then sync = mod end
		return sync
	end

	local function build_index()
		if id_index then return id_index end
		if not ensure_sync() then return nil end
		local byid, byname = {}, {}
		local function add(map, key, rec)
			if not key or key == "" then return end
			local bucket = map[key]
			if bucket then
				bucket[#bucket + 1] = rec
			else
				map[key] = { rec }
			end
		end
		for _, dtype in ipairs({ "Weapons", "Pets" }) do
			local db = sync[dtype]
			if type(db) == "table" then
				for id, d in pairs(db) do
					if type(d) == "table" then
						local rec = { dtype = dtype, id = id, data = d }
						if d.ItemID then add(byid, tostring(d.ItemID), rec) end
						if type(d.Image) == "string" then
							local dig = string.match(d.Image, "assetId=(%d+)")
								or string.match(d.Image, "id=(%d+)")
								or string.match(d.Image, "rbxassetid://(%d+)")
							if dig then add(byid, dig, rec) end
						end
						add(byname, norm(d.ItemName or d.Name), rec)
					end
				end
			end
		end
		id_index = { byid = byid, byname = byname }
		return id_index
	end

	local function icon_id(card)
		local inner = card:FindFirstChild("Container")
		local icon = inner and inner:FindFirstChild("Icon")
		local img = icon and icon.Image or ""
		if img == "" then return nil end
		return string.match(img, "assetId=(%d+)")
			or string.match(img, "id=(%d+)")
			or string.match(img, "rbxassetid://(%d+)")
	end

	local function card_entry(card, text, chroma)
		local ix = build_index()
		if not ix then return nil end
		local iid = icon_id(card)
		local pool = iid and ix.byid[iid] or nil
		if not pool then pool = ix.byname[norm(text)] end
		if not pool then return nil end

		local fallback = nil
		for _, rec in ipairs(pool) do
			local d = rec.data
			if (d.Chroma == true) == chroma then
				if norm(d.ItemName or d.Name) == norm(text) then return rec.dtype, rec.id, d end
				if not fallback then fallback = rec end
			end
		end
		if fallback then return fallback.dtype, fallback.id, fallback.data end
		if iid and ix.byid[iid] == pool then
			local rec = pool[1]
			return rec.dtype, rec.id, rec.data
		end
		return nil
	end

	local event_mine, event_theirs = nil, nil
	local update_remote, start_remote, update_conn, start_conn = nil, nil, nil, nil
	local last_root, last_signature, last_version = nil, nil, -1
	local function event_update(data)
		if not show_on or type(data) ~= "table" then return end
		if data.Player1 and data.Player1.Player == lp then
			event_mine = data.Player1.Offer
			event_theirs = data.Player2 and data.Player2.Offer
		elseif data.Player2 and data.Player2.Player == lp then
			event_mine = data.Player2.Offer
			event_theirs = data.Player1 and data.Player1.Offer
		else
			return
		end
		last_signature = nil
	end

	local function ensure_hooks()
		local trade = rs:FindFirstChild("Trade")
		local upd = trade and trade:FindFirstChild("UpdateTrade")
		local start = trade and trade:FindFirstChild("StartTrade")
		if upd ~= update_remote then
			if update_conn then update_conn:Disconnect(); update_conn = nil end
			update_remote = upd
			if upd and upd:IsA("RemoteEvent") then
				update_conn = upd.OnClientEvent:Connect(event_update)
			end
		end
		if start ~= start_remote then
			if start_conn then start_conn:Disconnect(); start_conn = nil end
			start_remote = start
			if start and start:IsA("RemoteEvent") then
				start_conn = start.OnClientEvent:Connect(event_update)
			end
		end
	end

	local function gui_items(offer, event_offer)
		local out = {}
		local cont = offer and offer:FindFirstChild("Container")
		if not cont then return out end
		for _, card in ipairs(cont:GetChildren()) do
			local slot = tonumber(card.Name:match("^NewItem(%d+)$"))
			if slot and card.Visible then
				local nm = card:FindFirstChild("ItemName")
				local lbl = nm and nm:FindFirstChild("Label")
				local name = lbl and lbl.Text or ""
				if name ~= "" then
					local tags = card:FindFirstChild("Tags")
					local ch = tags and tags:FindFirstChild("Chroma")
					local chroma = (ch ~= nil and ch.Visible == true)
						or norm(name):sub(1, 6) == "chroma"
					local inner = card:FindFirstChild("Container")
					local amt_l = inner and inner:FindFirstChild("Amount")
					local amount = amt_l and tonumber((amt_l.Text or ""):match("[xX]%s*(%d+)")) or 1
					local dtype, id, data = card_entry(card, name, chroma)
					out[#out + 1] = {
						slot = slot, amount = amount, id = id or norm(name),
						dtype = dtype or "Weapons",
						data = data or { ItemName = name, Chroma = chroma },
					}
				end
			end
		end
		table.sort(out, function(a, b) return a.slot < b.slot end)
		if type(event_offer) == "table" and #out == #event_offer and ensure_sync() then
			for i, raw in ipairs(event_offer) do
				if type(raw) == "table" then
					local id = raw[1] or raw.ItemID
					local dtype = raw[3] or raw.ItemType
					local db = dtype and sync[dtype]
					local data = db and db[id]
					if data and norm(data.ItemName or data.Name) == norm(out[i].data.ItemName) then
						out[i].id, out[i].dtype, out[i].data = id, dtype, data
					end
				end
			end
		end
		return out
	end

	local function signature(items)
		local parts = {}
		for _, it in ipairs(items) do
			local d = it.data
			parts[#parts + 1] = table.concat({
				tostring(it.slot), tostring(it.id), tostring(it.amount),
				tostring(it.dtype), tostring(d.ItemName or d.Name),
				tostring(d.Year), tostring(d.Rarity), tostring(d.ItemType), tostring(d.Chroma),
			}, "|")
		end
		return table.concat(parts, ";")
	end

	local function render(offer, items)
		if not offer then return end
		local cont = offer:FindFirstChild("Container")
		if not cont then return end
		clear_side(offer)
		if #items == 0 then return end
		local sum, known, loading, unknown = 0, 0, 0, 0
		for _, it in ipairs(items) do
			local card = cont:FindFirstChild("NewItem" .. it.slot)
			if card then
				local value = resolve(it.dtype, it.id, it.data)
				local caption, color
				if type(value) == "number" and value >= 0 then
					caption = format_value(value)
					color = Color3.fromRGB(248, 230, 190)
					sum = sum + value * it.amount
					known = known + it.amount
				elseif value == nil then
					caption = "Loading"
					color = Color3.fromRGB(184, 191, 200)
					loading = loading + it.amount
				else
					caption = "N/A"
					color = Color3.fromRGB(184, 191, 200)
					unknown = unknown + it.amount
				end
				local label = card_label(card, caption)
				label.TextColor3 = color
				label.Visible = true
			end
		end
		local caption, compact
		if known > 0 then
			caption = (loading + unknown > 0 and "Known: " or "Value: ") .. format_value(sum)
			compact = (loading + unknown > 0 and "Known " or "") .. format_value(sum)
		else
			caption = loading > 0 and "Loading values" or "No data"
			compact = loading > 0 and "Loading" or "N/A"
		end
		local total = total_label(offer, caption, compact)
		total.TextColor3 = known > 0 and Color3.fromRGB(255, 222, 150) or Color3.fromRGB(205, 209, 215)
		total.Visible = not total:GetAttribute("SV_NoRoom")
	end

	local function refresh_gui()
		ensure_hooks()
		local root, gui = trade_root()
		if not root or not gui or not gui.Enabled then
			if last_root then
				clear_side(last_root:FindFirstChild("YourOffer"))
				clear_side(last_root:FindFirstChild("TheirOffer"))
				event_mine, event_theirs = nil, nil
			end
			last_root, last_signature = nil, nil
			return
		end
		local mine, theirs = root:FindFirstChild("YourOffer"), root:FindFirstChild("TheirOffer")
		local my_items, their_items = gui_items(mine, event_mine), gui_items(theirs, event_theirs)
		local function layout_key(offer)
			if not offer then return "" end
			local title, user = offer:FindFirstChild("Title"), offer:FindFirstChild("Username")
			local slots = offer:FindFirstChild("Container")
			local first_card = slots and slots:FindFirstChild("NewItem1")
			return table.concat({
				tostring(offer.AbsoluteSize.X), tostring(offer.AbsoluteSize.Y),
				tostring(title and title.TextBounds.X or 0),
				tostring(title and title.AbsolutePosition.X - offer.AbsolutePosition.X or 0),
				tostring(user and user.TextBounds.X or 0),
				tostring(user and user.AbsolutePosition.X - offer.AbsolutePosition.X or 0),
				tostring(first_card and first_card.AbsoluteSize.X or 0),
			}, ",")
		end
		local sig = signature(my_items) .. "/" .. signature(their_items)
			.. "/" .. layout_key(mine) .. "/" .. layout_key(theirs)
		local function missing(offer, items)
			if not offer then return false end
			local total = offer:FindFirstChild("SV_Total")
			if #items > 0 and (not total or (not total.Visible and not total:GetAttribute("SV_NoRoom")) or total.Text == "") then return true end
			local cont = offer:FindFirstChild("Container")
			for _, it in ipairs(items) do
				local card = cont and cont:FindFirstChild("NewItem" .. it.slot)
				local label = card and card:FindFirstChild("SV_Value")
				if not label or not label.Visible or label.Text == "" then return true end
			end
			return false
		end
		if root ~= last_root or sig ~= last_signature or store.version ~= last_version
			or missing(mine, my_items) or missing(theirs, their_items) then
			render(mine, my_items)
			render(theirs, their_items)
			last_root, last_signature, last_version = root, sig, store.version
		end
	end

	local function set_show(v)
		if show_on == v then return end
		show_on = v
		worker = worker + 1
		if not v then
			wipe_labels()
			last_root, last_signature = nil, nil
			event_mine, event_theirs = nil, nil
			if update_conn then update_conn:Disconnect(); update_conn = nil end
			if start_conn then start_conn:Disconnect(); start_conn = nil end
			update_remote, start_remote = nil, nil
			return
		end
		local mine = worker
		task.spawn(function()
			load_snapshot()
			if not show_on or mine ~= worker or not Remote.current() then return end
			refresh_feed(true)
			while show_on and mine == worker and Remote.current() do
				local ok, err = pcall(refresh_gui)
				if not ok then recordError("trade: " .. tostring(err)) end
				refresh_feed(false)
				task.wait(0.25)
			end
		end)
	end

	Sections.Trade:AddLabel("Show Values"):AddToggle({
		Name = "Show Values", Default = true, Flag = "trade_show_values",
		Callback = set_show,
	});
	set_show(true)

	Sections.Trade:AddButton({
		Name = "Refresh Values",
		Callback = function()
			if not show_on then return end
			refresh_feed(true)
			last_signature = nil
			refresh_gui()
		end,
	});

	ESP.ClearTrade = function()
		set_show(false)
	end;
end);

guard("menu", function()
	-- paths are hosted-relative now; Remote.file turns one into wherever it
	-- actually landed in the flat store
	local HttpService = game:GetService("HttpService");
	local ContentProvider = game:GetService("ContentProvider");
	local function fileExists(path)
		return Remote.listedPath(path);
	end;
	local function assetUrl(path)
		return Remote.id(path);
	end;
	local function readManifest(path)
		local body = Remote.body(path);
		if not body then return nil end;
		local ok, records = pcall(function() return HttpService:JSONDecode(body) end);
		return ok and type(records) == "table" and records or nil;
	end;
	local function localPath(relative)
		if type(relative) ~= "string" or relative == "" or relative:find("..", 1, true) or relative:find(":", 1, true) then return nil end;
		return Remote.file(relative);
	end;
	-- the flat store has no folders left to walk, so the manifest says what
	-- exists and Remote.file says where each one landed
	local function listFolder(relative)
		return Remote.under(relative .. "/");
	end;
	-- a handful of catalogue entries come back with no name at all, which used
	-- to show as a bare " [24372436824888]" tile
	local function prettyName(name)
		local text = tostring(name or ""):match("^%s*(.-)%s*$");

		if text == "" then return "Untitled" end;

		return (text:gsub("[_%-]+", " "):gsub("(%a)(%d)", "%1 %2"):gsub("(%a[%w']*)", function(word)
			return word:sub(1, 1):upper() .. word:sub(2);
		end));
	end;

	------------------------------------------------------ inject sound ----
	-- the hour picks the greeting; its sound is in the pack, so it waits for it
	task.spawn(function()
		local waited = 0;
		while ALIVE and Remote.Status.stage ~= "ready" and Remote.Status.stage ~= "failed" and waited < 60 do
			task.wait(0.25);
			waited += 0.25;
		end;
		if not ALIVE then return end;
		local hour = 12;
		local ok, clock = pcall(os.date, "*t");
		if ok and type(clock) == "table" and type(clock.hour) == "number" then
			hour = math.clamp(math.floor(clock.hour), 0, 23);
		else
			pcall(function() hour = DateTime.now():ToLocalTime().Hour end);
		end;
		local greeting = "dobry-vecher";
		if hour >= 5 and hour < 11 then
			greeting = "dobroe-utrechko";
		elseif hour >= 11 and hour < 17 then
			greeting = "dobry-denb";
		end;
		ESP.Greeting = { Hour = hour, File = "sounds/time/" .. greeting .. ".ogg" };
		local url = Remote.file(ESP.Greeting.File) and assetUrl(Remote.file(ESP.Greeting.File));
		if not url then SFX.ready(); return end;
		local sound = Instance.new("Sound");
		sound:SetAttribute("VisualsOwned", true);
		sound.Name = SaladUI.RandomString();
		sound.SoundId = url;
		sound.Volume = 0.5;
		sound.Parent = SaladUI.ScreenGui;
		SaladUI:AddSignal(sound.Ended:Connect(function() sound:Destroy() end));
		game:GetService("Debris"):AddItem(sound, 30);
		sound:Play();
		ESP.Greeting.Sound = sound;
	end);

	------------------------------------------------------- menu sounds ----
	local presets, order = {}, { "Off" };
	local records = readManifest("menusounds/manifest.json");
	if records then
		for _, entry in ipairs(records) do
			if type(entry) == "table" and type(entry.name) == "string" and entry.name ~= "Off" then
				local on, off = localPath(entry.on), localPath(entry.off);
				if on and fileExists(on) and not presets[entry.name] then
					presets[entry.name] = { on = on, off = off and fileExists(off) and off or nil };
					order[#order + 1] = entry.name;
				end;
			end;
		end;
	else
		local pairsFound, names = {}, {};
		for _, rel in ipairs(listFolder("menusounds")) do
			local file = string.match(rel, "([^/]+)$") or "";
			local name, side, extension = string.match(file:lower(), "^(.+)_(o[nf]f?)%.(%w+)$");
			if name and (extension == "wav" or extension == "ogg" or extension == "mp3") and fileExists(Remote.file(rel)) then
				if not pairsFound[name] then pairsFound[name] = {}; names[#names + 1] = name end;
				pairsFound[name][side] = Remote.file(rel);
			end;
		end;
		table.sort(names);
		for _, name in ipairs(names) do
			local entry = pairsFound[name];
			if entry.on then
				local label = prettyName(name);
				presets[label] = entry; order[#order + 1] = label;
			end;
		end;
	end;

	local M = { Preset = "Off", Volume = 50 };
	-- Four of each, taken in turn like the library's own bells: one Sound
	-- restarted on every click cut itself off, so quick clicks went missing.
	local pool = { on = {}, off = {} };
	for _, list in pairs(pool) do
		for i = 1, 4 do
			local sound = ownedSound();
			sound.Name = SaladUI.RandomString();
			sound.Parent = SaladUI.ScreenGui;
			list[i] = sound;
		end;
	end;
	local function eachSound(fn)
		for _, list in pairs(pool) do for _, sound in ipairs(list) do fn(sound) end end;
	end;
	local turn = 0;
	local soundSelection = 0;
	local click;
	local function loadPreset(name, preview)
		soundSelection += 1;
		local selection = soundSelection;
		local playPreview = preview and not SaladUI.Lib.quiet;
		eachSound(function(sound) sound:Stop(); sound.SoundId = "" end);
		local entry = presets[name];
		if not entry then return end;
		local function wanted()
			return Remote.current() and selection == soundSelection and M.Preset == name and pool.on[1].Parent ~= nil;
		end;
		task.spawn(function()
			local on = assetUrl(entry.on);
			if not wanted() then return end;
			-- an ON-only pack plays its one sound for both; OFF used to be silent,
			-- so every close and untick of such a pack made no sound at all
			local off = entry.off and assetUrl(entry.off) or on;
			if not wanted() then return end;
			for _, sound in ipairs(pool.on) do sound.SoundId = on or "" end;
			for _, sound in ipairs(pool.off) do sound.SoundId = off or "" end;
			-- a click before the file is decoded is silent: the first one after a
			-- pick, and the preview, most of all
			Remote.invoke(function() ContentProvider:PreloadAsync({ pool.on[1], pool.off[1] }) end, 5);
			if playPreview and wanted() then click(true) end;
		end);
	end;
	click = function(state)
		if M.Preset == "Off" or M.Volume <= 0 then return end;
		turn = turn % 4 + 1;
		local sound = (state and pool.on or pool.off)[turn];
		if not sound.Parent or sound.SoundId == "" then return end;
		sound.Volume = M.Volume / 100;
		sound.TimePosition = 0;
		sound:Play();
	end;
	ESP.MenuClick = click;
	ESP.MenuSounds = M;
	local function route()
		SFX.hook = (M.Preset ~= "Off" and presets[M.Preset]) and click or nil;
	end;

	-- The presets hung off OnToggleChanged, which the adapter invents and only
	-- fires for boolean widgets. Sliders, dropdowns, pickers, buttons and tab
	-- switches were silent, so whether a preset worked depended on which
	-- control you touched.
	--
	-- The library already has the hook: chime(kind) at every interaction site.
	-- Replacing that one function routes all of them, and kind picks which half
	-- of the on/off pair plays.
	local lib = SaladUI.Lib;
	local OFF_KINDS = { off = true, close = true };

	function lib:chime(kind)
		if M.Preset == "Off" or M.Volume <= 0 then return end;
		if lib.quiet then return end;

		click(not OFF_KINDS[kind]);
	end;

	-- config restore still marks itself quiet, so loading a profile does not
	-- machine-gun a click per restored widget
	SaladUI.OnToggleChanged = function(_, flag, _)
		if Preview and Preview.Queue then Preview.Queue(flag) end;
	end;
	Sections.MenuSounds:AddLabel("Menu Sounds"):AddDropdown({
		Default = "Off", Values = order, Flag = "menu_sound",
		Callback = function(value) M.Preset = value; route(); loadPreset(value, true) end,
	});
	Sections.MenuSounds:AddLabel("Sound Volume"):AddSlider({
		Min = 0, Max = 100, Default = 50, Type = "%", Size = 100, Flag = "menu_sound_volume",
		Callback = function(value) M.Volume = value end,
	});

	local sheets, stickerOrder = {}, { "Off" };
	local function addSheet(record)
		if type(record) ~= "table" or type(record.name) ~= "string" or record.name == "Off" or sheets[record.name] then return end;
		local cols, rows = tonumber(record.cols), tonumber(record.rows);
		local width, height, frames = tonumber(record.width), tonumber(record.height), tonumber(record.frames);
		if not (cols and rows and width and height and frames) then return end;
		if cols < 1 or rows < 1 or frames < 1 or cols % 1 ~= 0 or rows % 1 ~= 0 or frames % 1 ~= 0 then return end;
		if width % cols ~= 0 or height % rows ~= 0 or width < cols or height < rows then return end;
		local files = {};
		for _, relative in ipairs(record.sheets or { record.file }) do
			local path = localPath(relative);
			if not (path and fileExists(path)) then return end;
			files[#files + 1] = path;
		end;
		if #files == 0 or frames > cols * rows * #files then return end;
		sheets[record.name] = {
			files = files, cols = cols, rows = rows, frames = frames,
			cellWidth = width / cols, cellHeight = height / rows,
			fps = math.clamp(tonumber(record.fps) or 15, 1, 120),
		};
		stickerOrder[#stickerOrder + 1] = record.name;
	end;
	local stickerRecords = readManifest("stickers/manifest.json");
	if stickerRecords then for _, record in ipairs(stickerRecords) do addSheet(record) end end;
	addSheet({ name = "Fury", sheets = {
		"images/furynew_sheet_1.png", "images/furynew_sheet_2.png", "images/furynew_sheet_3.png",
	}, width = 1024, height = 768, cols = 4, rows = 3, frames = 35, fps = 12 });

	local CUSTOM = ROOT .. "/Stickers";
	local customNames = {};
	local function imageSize(path)
		if not readfile then return nil end;
		local ok, raw = pcall(readfile, path);
		if not ok or type(raw) ~= "string" or #raw < 24 or #raw > 16 * 1024 * 1024 then return nil end;
		local function uint(at, count)
			if at + count - 1 > #raw then return nil end;
			local value = 0;
			for index = at, at + count - 1 do value = value * 256 + raw:byte(index) end;
			return value;
		end;
		local width, height;
		if raw:sub(1, 8) == "\137PNG\13\10\26\10" and raw:sub(13, 16) == "IHDR" then
			width, height = uint(17, 4), uint(21, 4);
		elseif raw:byte(1) == 255 and raw:byte(2) == 216 then
			local at = 3;
			while at < #raw do
				if raw:byte(at) ~= 255 then break end;
				while raw:byte(at) == 255 do at += 1 end;
				local marker = raw:byte(at); at += 1;
				if not marker or marker == 217 or marker == 218 then break end;
				if marker ~= 1 and not (marker >= 208 and marker <= 216) then
					local length = uint(at, 2);
					if not length or length < 2 or at + length - 1 > #raw then break end;
					if marker >= 192 and marker <= 207 and marker ~= 196 and marker ~= 200 and marker ~= 204 then
						if length < 8 then break end;
						height, width = uint(at + 3, 2), uint(at + 5, 2); break;
					end;
					at += length;
				end;
			end;
		end;
		if width and height and width >= 1 and height >= 1 and width <= 8192 and height <= 8192 then return width, height end;
	end;

	local function scanCustom()
		if not (isfolder and listfiles and isfile) then return end;
		if not isfolder(CUSTOM) then
			if makefolder then pcall(makefolder, CUSTOM) end;

			return;
		end;

		local found = {};

		local ok = pcall(function()
			for _, path in ipairs(listfiles(CUSTOM)) do
				local file = string.match(path, "([^/\\]+)$") or "";
				local extension = string.match(string.lower(file), "%.(%w+)$");

				if extension == "png" or extension == "jpg" or extension == "jpeg" then
					found[#found + 1] = { path = path, file = file };
				end;
			end;
		end);

		if not ok then return end;

		table.sort(found, function(a, b) return string.lower(a.file) < string.lower(b.file) end);
		for _, name in ipairs(customNames) do
			sheets[name] = nil;
			local index = table.find(stickerOrder, name);
			if index then table.remove(stickerOrder, index) end;
		end;
		table.clear(customNames);

		for _, entry in ipairs(found) do
			local stem = string.gsub(entry.file, "%.%w+$", "");
			local base, cols, rows, frames = string.match(stem, "^(.+)_(%d+)x(%d+)_(%d+)$");
			local name = prettyName(base or stem);

			if sheets[name] then name = name .. " (mine)" end;
			local baseName, suffix = name, 2;
			while sheets[name] do name = baseName .. " " .. suffix; suffix += 1 end;
			local width, height = imageSize(entry.path);
			cols, rows, frames = tonumber(cols), tonumber(rows), tonumber(frames);
			if cols and (not width or cols < 1 or rows < 1 or cols > 64 or rows > 64
				or frames < 1 or frames > cols * rows or width % cols ~= 0 or height % rows ~= 0) then
				warn("[visuals] invalid sticker sheet: " .. entry.file);
				continue;
			end;

			if not sheets[name] then
				if cols then
					sheets[name] = {
						files = { entry.path }, cols = tonumber(cols), rows = tonumber(rows),
						frames = frames, cellWidth = width / cols, cellHeight = height / rows,
						fps = 15, custom = true, sheet = true,
					};
				else
					sheets[name] = {
						files = { entry.path }, cols = 1, rows = 1, frames = 1,
						fps = 1, custom = true, whole = true,
						cellWidth = width or 1, cellHeight = height or 1,
					};
				end;

				stickerOrder[#stickerOrder + 1] = name;
				customNames[#customNames + 1] = name;
			end;
		end;
	end;

	if #stickerOrder == 1 then
		local legacy = {};
		for _, path in ipairs(listFolder("stickers")) do
			local file = string.match(path, "([^/\\]+)$") or "";
			local name, cols, rows, frames = string.match(file, "^(.+)_(%d+)x(%d+)_(%d+)%.png$");
			if name then
				legacy[#legacy + 1] = { name = prettyName(name), file = "stickers/" .. file, cols = tonumber(cols), rows = tonumber(rows), frames = tonumber(frames), width = 128 * tonumber(cols), height = 128 * tonumber(rows), fps = 15 };
			end;
		end;
		table.sort(legacy, function(a, b) return a.name < b.name end);
		for _, record in ipairs(legacy) do addSheet(record) end;
	end;
	local menuOpen = isOpen;
	local stickers = {};
	local refreshSlots;

	local function makeSticker(slot, firstPick)
		local function flag(suffix)
			return (slot == 1 and "menu_sticker" or ("menu_sticker" .. slot)) .. suffix;
		end;

		local ST = {
			On = false, Name = firstPick, Size = 176, Speed = 100, Opacity = 100, Side = "Header",
			Raise = 0, OffsetX = 0, OffsetY = 0, Layer = 60,
		};
		local holder = Instance.new("ImageLabel");
		holder.Name = "VisualsMenuSticker" .. slot;
		holder.BackgroundTransparency = 1;
		holder.BorderSizePixel = 0;
		holder.ScaleType = Enum.ScaleType.Fit;
		holder.ImageColor3 = Color3.new(1, 1, 1);
		holder.ImageTransparency = 1;
		holder.Visible = false;
		holder.Active = false;
		holder.ZIndex = 60;
		holder.Parent = gui;
		local current, frame, elapsed, opacity = nil, 0, 0, 0;
		local pageLayers, activeLayer = {}, nil;
		local stickerSelection = 0;
		local function clearLayers()
			activeLayer = nil;
			for _, layer in ipairs(pageLayers) do layer:Destroy() end;
			table.clear(pageLayers);
		end;
		local function prepareLayers(urls)
			clearLayers();
			for _, url in ipairs(urls) do
				local layer = Instance.new("ImageLabel");
				layer.Name = "VisualsMenuSticker" .. slot .. "Layer" .. tostring(#pageLayers + 1);
				layer.Size = UDim2.fromScale(1, 1);
				layer.BackgroundTransparency = 1;
				layer.BorderSizePixel = 0;
				layer.Image = url;
				layer.ImageColor3 = Color3.new(1, 1, 1);
				layer.ImageTransparency = 1;
				layer.ScaleType = Enum.ScaleType.Fit;
				layer.Visible = false;
				layer.Active = false;
				layer.ZIndex = ST.Layer;
				layer.Parent = holder;
				pageLayers[#pageLayers + 1] = layer;
			end;
			return table.clone(pageLayers);
		end;
		local function place()
			local window = ESP.WindowFrame and ESP.WindowFrame();
			if not (window and current) then return end;
			local screen = workspace.CurrentCamera.ViewportSize;
			local size = math.min(ST.Size, math.max(16, screen.X - 4), math.max(16, screen.Y - 4));
			if MOBILE then size = math.min(size, screen.Y * 0.4) end;
			local ratio = current.cellWidth / current.cellHeight;
			local width, height = size * math.min(1, ratio), size / math.max(1, ratio);
			local at, box = window.AbsolutePosition, window.AbsoluteSize;
			local x, y;
			if ST.Side == "Header" then x, y = at.X - width * 0.18, at.Y - height * 0.22;
			elseif ST.Side == "Header Right" then x, y = at.X + box.X - width * 0.82, at.Y - height * 0.22;
			elseif ST.Side == "Right" then x, y = at.X + box.X - width * 0.25, at.Y + box.Y - height;
			else x, y = at.X - width * 0.75, at.Y + box.Y - height end;
			x = math.clamp(x + ST.OffsetX, -width + 8, math.max(8, screen.X - 8));
			y = math.clamp(y + ST.OffsetY - ST.Raise, -height + 8, math.max(8, screen.Y - 8));
			local size2 = UDim2.fromOffset(width, height);
			if holder.Size ~= size2 then holder.Size = size2 end;
			if holder.ZIndex ~= ST.Layer then
				holder.ZIndex = ST.Layer;
				for _, layer in ipairs(pageLayers) do layer.ZIndex = ST.Layer end;
			end;
			local position = UDim2.fromOffset(x, y);
			if holder.Position ~= position then holder.Position = position end;
		end;
		local function drawFrame()
			if not current then return end;
			local layer = pageLayers[1];
			if not layer then return end;
			if current.whole then
				layer.ImageRectSize = Vector2.new();
				layer.ImageRectOffset = Vector2.new();
			else
				local capacity = current.cols * current.rows;
				local page = math.floor(frame / capacity) + 1;
				local localFrame = frame % capacity;
				layer = pageLayers[page];
				if not (layer and current.cellWidth and current.cellHeight) then return end;
				layer.ImageRectSize = Vector2.new(current.cellWidth, current.cellHeight);
				layer.ImageRectOffset = Vector2.new((localFrame % current.cols) * current.cellWidth, math.floor(localFrame / current.cols) * current.cellHeight);
			end;
			if activeLayer ~= layer then
				if activeLayer then activeLayer.Visible = false; activeLayer.ImageTransparency = 1 end;
				activeLayer = layer;
				activeLayer.Visible = true;
			end;
			activeLayer.ImageTransparency = 1 - math.clamp(opacity, 0, 1);
		end;
		local function select(name)
			stickerSelection += 1;
			local selection = stickerSelection;
			current = nil; frame = 0; elapsed = 0; opacity = 0;
			clearLayers();
			holder.Visible = false; holder.ImageTransparency = 1;
			ST.Error = nil;
			if not ST.On then return end;
			local entry = sheets[name];
			if not entry then return end;
			local function wanted()
				return Remote.current() and selection == stickerSelection and ST.Name == name and holder.Parent ~= nil;
			end;
			local function show(urls)
				if not wanted() then return end;
				local layers = prepareLayers(urls);
				if not wanted() then return end;
				Remote.invoke(function() ContentProvider:PreloadAsync(layers) end, 5);
				if not wanted() then return end;
				current = entry;
				drawFrame(); place();
			end;
			task.spawn(function()
				local ok, reason = pcall(function()
					local resolved = entry.urls;
					if not resolved then
						resolved = {};
						for _, path in ipairs(entry.files) do
							if not wanted() then return end;
							local url = assetUrl(path);
							if not wanted() then return end;
							if not url then ST.Error = "Unable to load " .. path; return end;
							resolved[#resolved + 1] = url;
						end;
						entry.urls = resolved;
					end;
					show(resolved);
				end);
				if not ok and wanted() then ST.Error = tostring(reason) end;
			end);
		end;
		SaladUI:AddSignal(RunService.RenderStepped:Connect(function(dt)
			if not (gui.Parent and holder.Parent) then return end;
			menuOpen = isOpen;
			local target = current and menuOpen and not ST.Blocked and ST.Opacity / 100 or 0;
			if target == 0 and opacity == 0 then return end;
			opacity = opacity + (target - opacity) * (1 - math.exp(-18 * math.max(dt, 0)));
			if math.abs(target - opacity) < 0.001 then opacity = target end;
			holder.Visible = current ~= nil and opacity > 0.001;
			if activeLayer then activeLayer.ImageTransparency = 1 - math.clamp(opacity, 0, 1) end;
			if not current or not holder.Visible then return end;
			place();
			if not menuOpen or current.frames <= 1 then return end;
			local fps = current.fps * ST.Speed / 100;
			elapsed = elapsed + dt;
			local steps = math.floor(elapsed * fps);
			if steps < 1 then return end;
			elapsed = elapsed - steps / fps;
			frame = (frame + steps) % current.frames;
			drawFrame();
		end));
		local stickerDrop;
		local row = Sections.MenuSticker:AddLabel("Sticker " .. slot);
		local toggle = row:AddToggle({
			Default = ST.On, Flag = flag("_on"),
			Callback = function(value)
				ST.On = value;
				if value then
					if ST.Name == "Off" and stickerDrop and stickerOrder[2] then
						stickerDrop:SetValue(stickerOrder[2]);
					elseif ST.Name ~= "Off" then
						select(ST.Name);
					end;
				end;
				if refreshSlots then refreshSlots() end;
			end,
		});
		local section = row:AddOption(1);
		stickerDrop = section:AddLabel("Sticker"):AddDropdown({
			Default = firstPick, Values = stickerOrder, Flag = flag(""),
			Callback = function(value) ST.Name = value; select(value); if refreshSlots then refreshSlots() end end,
		});
		section:AddLabel("Position"):AddDropdown({
			Default = "Header", Values = { "Header", "Header Right", "Right", "Left" }, Flag = flag("_side"),
			Callback = function(value) ST.Side = value; place() end,
		});
		section:AddLabel("Size"):AddSlider({
			Min = 40, Max = 700, Default = 176, Rounding = 0, Size = 100, Flag = flag("_size"),
			Callback = function(value) ST.Size = value; place() end,
		});
		section:AddLabel("Speed"):AddSlider({
			Min = 10, Max = 200, Default = 100, Rounding = 0, Type = "%", Size = 100, Flag = flag("_speed"),
			Callback = function(value) ST.Speed = value end,
		});
		section:AddLabel("Opacity"):AddSlider({
			Min = 0, Max = 100, Default = 100, Rounding = 0, Type = "%", Size = 100, Flag = flag("_opacity"),
			Callback = function(value) ST.Opacity = value end,
		});
		section:AddLabel("Offset X"):AddSlider({
			Min = -200, Max = 200, Default = 0, Rounding = 0, Size = 100, Flag = flag("_x"),
			Callback = function(value) ST.OffsetX = value; place() end,
		});
		section:AddLabel("Offset Y"):AddSlider({
			Min = -200, Max = 200, Default = 0, Rounding = 0, Size = 100, Flag = flag("_y"),
			Callback = function(value) ST.OffsetY = value; place() end,
		});
		section:AddLabel("Layer"):AddSlider({
			Min = 1, Max = 120, Default = 60, Rounding = 0, Size = 100, Flag = flag("_z"),
			Callback = function(value) ST.Layer = value; place() end,
		});

		stickers[slot] = { ST = ST, select = select, drop = stickerDrop, holder = holder, toggle = toggle,
			stop = function() stickerSelection += 1; current = nil end };
		select(firstPick);
		return ST;
	end;

	local ST = makeSticker(1, "Fury");
	makeSticker(2, "Off");
	makeSticker(3, "Off");

	function refreshSlots()
		local open = true;

		for index, one in ipairs(stickers) do
			local on = one.ST.On and one.ST.Name ~= "Off";

			if index > 1 then pcall(one.toggle.SetVisible, one.toggle, open) end;

			one.ST.Blocked = not (open and one.ST.On);
			open = open and on;
		end;
	end;

	refreshSlots();

	local function refreshLists()
		for _, one in ipairs(stickers) do
			if one.drop and one.drop.SetValues then pcall(one.drop.SetValues, one.drop, stickerOrder) end;
		end;
	end;

	task.defer(function()
		if not Remote.current() then return end;
		scanCustom();
		if Remote.current() then refreshLists() end;
	end);

	Sections.MenuSticker:AddButton({
		Name = "Reload Stickers",
		Callback = function()
			scanCustom();
			for _, one in ipairs(stickers) do
				if not sheets[one.ST.Name] then one.ST.Name = "Off" end;
				one.select(one.ST.Name);
			end;
			refreshLists();

		end,
	});
	ESP.Sticker = ST;
	ESP.ClearMenuExtras = function()
		for _, one in ipairs(stickers) do
			one.stop();
			one.ST.Name = "Off";
			pcall(function() one.holder:Destroy() end);
		end;
		soundSelection += 1;
		menuOpen = false;
		M.Preset = "Off";
		SaladUI.OnToggleChanged = function() end;
		eachSound(function(sound) sound:Destroy() end);
	end;
end);

	guard("social_share", function()
		local HttpService = game:GetService("HttpService");
		local MarketplaceService = game:GetService("MarketplaceService");
		local CoreGui = game:GetService("CoreGui");
		local lib = SaladUI.Lib;
	local origin = type(GLOBAL.VISUALS_API) == "string" and GLOBAL.VISUALS_API or "https://inertiahub.xyz";
	local API = origin .. "/api/visuals";
	local me = tostring(LocalPlayer.UserId);
	local grab = (syn and syn.request) or (http and http.request)
		or (getgenv and (rawget(getgenv(), "http_request") or rawget(getgenv(), "request")))
		or http_request or request;

	local placeName = "Roblox";
	task.spawn(function()
		local ok, info = pcall(function() return MarketplaceService:GetProductInfo(game.PlaceId) end);
		if ok and type(info) == "table" and type(info.Name) == "string" then placeName = info.Name:sub(1, 60) end;
	end);

	local function call(method, path, body)
		if type(grab) ~= "function" then
			if method ~= "GET" then return nil end;
			local ok, text = pcall(function() return game:HttpGet(API .. path, true) end);
			if not ok then return nil end;
			local fine, data = pcall(function() return HttpService:JSONDecode(text) end);
			return (fine and type(data) == "table" and data.ok) and data.data or nil;
		end;

		local ok, res = pcall(grab, {
			Url = API .. path,
			Method = method,
			Headers = { ["Content-Type"] = "application/json", Accept = "application/json" },
			Body = body and HttpService:JSONEncode(body) or nil,
		});

		if not (ok and type(res) == "table") then return nil end;

		local fine, data = pcall(function() return HttpService:JSONDecode(res.Body) end);

		if fine and type(data) == "table" and data.ok then return data.data end;

		return nil, tonumber(res.StatusCode) or 0, (fine and type(data) == "table") and data.error or nil;
	end;

	local function make(class, props, parent)
		local object = Instance.new(class);
		for key, value in pairs(props) do object[key] = value end;
		object.Parent = parent;
		return object;
	end;
	local S = { On = true, generation = 0 };
	ESP.Share = S;
	local session = {};
	GLOBAL.__SaladShareSession = session;

	local KORBLOX = {
		RightUpperLeg = { MeshId = "rbxassetid://902942096", TextureID = "rbxassetid://902843398" },
		RightLowerLeg = { MeshId = "rbxassetid://902942093", Transparency = 1 },
		RightFoot = { MeshId = "rbxassetid://902942089", Transparency = 1 },
	};

	local marks = {};

	local function restoreSaved(mark)
		for part, saved in pairs(mark.saved) do
			if part.Parent then
				for key, value in pairs(saved) do pcall(function() part[key] = value end) end;
			end;
		end;

		table.clear(mark.saved);
	end;

	local function clearMark(player)
		local mark = marks[player];
		if not mark then return end;

		restoreSaved(mark);

		for part, saved in pairs(mark.hidden) do
			if part.Parent then pcall(function() part.LocalTransparencyModifier = saved end) end;
		end;

		marks[player] = nil;
	end;

	local function wearFlags(player, flags)
		local set = {};
		for _, flag in ipairs(flags or {}) do set[tostring(flag)] = true end;

		if not next(set) then clearMark(player); return end;

		marks[player] = marks[player] or { saved = {}, hidden = {} };
		marks[player].set = set;
	end;

	local function paintMark(player, mark)
		local char = player.Character;
		if not char then return end;

		local now = {};
		local head = char:FindFirstChild("Head");

		if mark.set.headless and head then now[head] = true end;

		for _, item in ipairs(char:GetChildren()) do
			if item:IsA("Accessory") then
				local handle = item:FindFirstChild("Handle");
				local hair = item.AccessoryType == Enum.AccessoryType.Hair
					or string.find(string.lower(item.Name), "hair", 1, true) ~= nil;

				if handle and (mark.set.noacc or (mark.set.hairless and hair)) then now[handle] = true end;
			end;
		end;

		for part, saved in pairs(mark.hidden) do
			if not now[part] and part.Parent then pcall(function() part.LocalTransparencyModifier = saved end) end;
		end;

		for part in pairs(now) do
			now[part] = mark.hidden[part] or part.LocalTransparencyModifier;
			if part.LocalTransparencyModifier ~= 1 then part.LocalTransparencyModifier = 1 end;
		end;
		mark.hidden = now;

		if mark.set.korblox then
			for name, look in pairs(KORBLOX) do
				local part = char:FindFirstChild(name);

				if part and part:IsA("MeshPart") then
					if not mark.saved[part] then
						mark.saved[part] = { MeshId = part.MeshId, TextureID = part.TextureID, Transparency = part.Transparency };
					end;

					for key, value in pairs(look) do
						if part[key] ~= value then pcall(function() part[key] = value end) end;
					end;
				end;
			end;
		elseif next(mark.saved) then
			restoreSaved(mark);
		end;
	end;

	local tagHome = Instance.new("Folder");
	tagHome.Name = SaladUI.RandomString();
	tagHome.Parent = CoreGui;
	onUnload("salad tags", function() pcall(function() tagHome:Destroy() end) end);

	local tags = {};
	SaladUI:AddSignal(root:GetPropertyChangedSignal("Visible"):Connect(function()
		for _, tag in pairs(tags) do if tag.board.Parent then tag.board.Enabled = not root.Visible end end
	end));
	local okFont, listFont = pcall(function() return Enum.Font.BuilderSansBold end);
	if not okFont then listFont = Enum.Font.GothamBold end;

	local function tagOn(player)
		if player == LocalPlayer then return end;

		local tag = tags[player];

		if not tag then
			local board = make("BillboardGui", {
				Name = SaladUI.RandomString(), Size = UDim2.fromScale(3, 0.62), AlwaysOnTop = false,
				StudsOffsetWorldSpace = Vector3.new(0, 2.5, 0), MaxDistance = 90, LightInfluence = 0,
			}, tagHome);
			make("TextLabel", {
				Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Font = Enum.Font.GothamBold, Text = "<> Salad",
				TextColor3 = Color3.new(1, 1, 1), TextScaled = true, TextStrokeColor3 = Color3.new(0, 0, 0),
				TextStrokeTransparency = 0.65,
			}, board);

			tag = { board = board };
			tags[player] = tag;
		end;

		local char = player.Character;
		local head = char and char:FindFirstChild("Head");

		if tag.board.Adornee ~= head then tag.board.Adornee = head end;
		tag.board.Enabled = not root.Visible;
	end;

	local function tagOff(player)
		local tag = tags[player];
		if not tag then return end;

		pcall(function() tag.board:Destroy() end);
		if tag.listPill then pcall(function() tag.listPill:Destroy() end) end;
		if tag.cap then pcall(function() tag.cap:Destroy() end) end;
		tags[player] = nil;
	end;

	local function markEntry(coreList, player, tag)
		if not (tag.entry and tag.entry.Parent) then
			tag.entry = coreList:FindFirstChild("PlayerEntry_" .. player.UserId, true);
			tag.label = nil;
		end;

		local entry = tag.entry;
		if not entry then return end;

		if not (tag.label and tag.label.Parent) then
			tag.label = nil;

			for _, d in ipairs(entry:GetDescendants()) do
				if d:IsA("TextLabel") and d.Name == "PlayerName" then tag.label = d; break end;
			end;
		end;

		local label = tag.label;
		if not label then return end;

		if not (tag.listPill and tag.listPill.Parent == label.Parent) then
			if tag.listPill then pcall(function() tag.listPill:Destroy() end) end;
			tag.listPill = make("TextLabel", {
				Name = SaladUI.RandomString(), AnchorPoint = Vector2.new(0, 0.5), AutomaticSize = Enum.AutomaticSize.X,
				Size = UDim2.fromOffset(0, 16), BackgroundTransparency = 1, Font = listFont, Text = "<> Salad",
				TextColor3 = label.TextColor3, TextTransparency = 0.45, TextSize = math.max(label.TextSize - 3, 11),
				ZIndex = label.ZIndex,
			}, label.Parent);
		end;

		if not (tag.cap and tag.cap.Parent == label) then
			if tag.cap then pcall(function() tag.cap:Destroy() end) end;
			tag.cap = make("UISizeConstraint", {}, label);
			label.TextTruncate = Enum.TextTruncate.AtEnd;
		end;

		local left = label.Position.X.Offset;
		local room = label.Parent.AbsoluteSize.X - tag.listPill.AbsoluteSize.X - 8 - left;
		tag.cap.MaxSize = Vector2.new(math.max(room, 24), math.huge);
		tag.listPill.Position = UDim2.new(0, left + math.min(label.TextBounds.X, label.AbsoluteSize.X) + 6, 0.5, 0);
	end;

	task.spawn(function()
		while ALIVE do
			task.wait(0.5);

			if next(tags) then
				local coreList = CoreGui:FindFirstChild("PlayerList");

				if coreList then
					for player, tag in pairs(tags) do pcall(markEntry, coreList, player, tag) end;
				end;
			end;
		end;
	end);

	local function stateNow()
		local auras, cosmetics, trail = {}, {}, nil;

		for _, entry in ipairs(ESP.GameFX and ESP.GameFX.WornList() or {}) do
			if type(entry.id) == "string" and #entry.id <= 80 then
				if entry.group == "cosmetic" and #cosmetics < 40 then cosmetics[#cosmetics + 1] = entry.id
				elseif entry.group == "trail" then trail = entry.id
				elseif entry.group == "aura" and #auras < 40 then auras[#auras + 1] = entry.id end;
			end;
		end;

		local flags = {};
		for flag, name in pairs({ korblox_leg = "korblox", headless = "headless", hairless = "hairless", no_accessories = "noacc" }) do
			local item = lib.pool[flag];
			if item and item.get() == true then flags[#flags + 1] = name end;
		end;

		local builtin, colour = {}, nil;
		local AU = ESP.Aura;

		if AU and AU.On then
			for name in pairs(AU.Types or {}) do builtin[#builtin + 1] = name end;
			table.sort(builtin);
			colour = AU.Tint and AU.Color and AU.Color:ToHex() or nil;
		end;

		local btrail = ESP.Trail and ESP.Trail.Worn and ESP.Trail.Worn() or nil;

		local tint = {};
		local TR, CO = ESP.Trail, ESP.Cosmetics;
		if AU and AU.Tint and AU.Color then tint.a = AU.Color:ToHex() end;
		if CO and CO.Tint and CO.Color then tint.c = CO.Color:ToHex() end;
		if TR and TR.Tint and TR.Color then tint.t, tint.u = TR.Color:ToHex(), (TR.Color2 or TR.Color):ToHex() end;

		return { auras = auras, trail = trail, cosmetics = cosmetics, flags = flags,
			builtin = builtin, color = colour, btrail = btrail, tint = next(tint) and tint or nil };
	end;

	local function forgetEveryone()
		for player in pairs(marks) do clearMark(player) end;
		for player in pairs(tags) do tagOff(player) end;
		for player in pairs(ESP.GameFX and ESP.GameFX.Guests() or {}) do pcall(ESP.GameFX.Undress, player) end;
		for player in pairs(ESP.Aura and ESP.Aura.Guests and ESP.Aura.Guests() or {}) do pcall(ESP.Aura.Undress, player) end;
		for player in pairs(ESP.Trail and ESP.Trail.Guests and ESP.Trail.Guests() or {}) do pcall(ESP.Trail.Undress, player) end;
	end;

	local function strings(value, limit)
		local out = {};
		if type(value) ~= "table" then return out end;
		for _, item in ipairs(value) do
			if type(item) == "string" and #item <= 80 then
				out[#out + 1] = item;
				if #out >= limit then break end;
			end;
		end;
		return out;
	end;

	local function hex(value)
		if type(value) ~= "string" or not value:match("^%x%x%x%x%x%x$") then return nil end;
		local ok, colour = pcall(Color3.fromHex, value);
		return ok and colour or nil;
	end;

	local function applyPeer(player, state)
		tagOn(player);
		local list = {};
		for _, id in ipairs(strings(state.auras, 40)) do list[#list + 1] = { id = id, group = "aura" } end;
		for _, id in ipairs(strings(state.cosmetics, 40)) do list[#list + 1] = { id = id, group = "cosmetic" } end;
		if type(state.trail) == "string" and #state.trail <= 80 then list[#list + 1] = { id = state.trail, group = "trail" } end;
		local tint = {};
		local shared = type(state.tint) == "table" and state.tint or {};
		local a, c, t, u = hex(shared.a), hex(shared.c), hex(shared.t), hex(shared.u);
		if a then tint.aura = ColorSequence.new(a) end;
		if c then tint.cosmetic = ColorSequence.new(c) end;
		if t then tint.trail = ColorSequence.new(t, u or t) end;
		if ESP.GameFX then ESP.GameFX.Dress(player, list, tint) end;
		wearFlags(player, strings(state.flags, 12));
		if ESP.Aura and ESP.Aura.Dress then
			ESP.Aura.Dress(player, strings(state.builtin, 20), hex(state.color));
		end;
		if ESP.Trail and ESP.Trail.Dress then
			if type(state.btrail) == "table" then ESP.Trail.Dress(player, state.btrail)
			else ESP.Trail.Undress(player) end;
		end;
	end;

	local function removeAbsent(seen)
		for player in pairs(marks) do if not seen[player] then clearMark(player) end end;
		for player in pairs(tags) do if not seen[player] then tagOff(player) end end;
		for _, service in pairs({ ESP.GameFX, ESP.Aura, ESP.Trail }) do
			if service and service.Guests and service.Undress then
				for player in pairs(service.Guests()) do
					if not seen[player] then pcall(service.Undress, player) end;
				end;
			end;
		end;
	end;

	task.spawn(function()
		local delay = 3;
		while ALIVE do
			task.wait(delay);
			if not ALIVE or GLOBAL.__SaladShareSession ~= session then break end;
			if S.On then
				local generation = S.generation;
				local ok, received = pcall(function()
					call("POST", "/share", {
						userId = me, name = LocalPlayer.DisplayName, place = placeName,
						placeId = tostring(game.PlaceId), gameId = tostring(game.GameId), jobId = game.JobId, state = stateNow(),
					});
					if not ALIVE or not S.On or S.generation ~= generation then
						if GLOBAL.__SaladShareSession == session and (not ALIVE or not S.On) then call("POST", "/share", { userId = me, name = LocalPlayer.DisplayName, jobId = game.JobId, state = nil }) end;
						return false;
					end;
					local data = call("GET", "/share?job=" .. HttpService:UrlEncode(game.JobId) .. "&me=" .. me);
					if not ALIVE or not S.On or S.generation ~= generation or GLOBAL.__SaladShareSession ~= session then return false end;
					if type(data) ~= "table" or type(data.users) ~= "table" then return false end;
					local seen = {};
					for _, entry in ipairs(data.users) do
						if type(entry) == "table" then
							local id = tonumber(entry.userId);
							local player = id and id > 0 and id < 9007199254740992 and id % 1 == 0 and Players:GetPlayerByUserId(id) or nil;
							if player and player ~= LocalPlayer and type(entry.state) == "table" then
								seen[player] = true;
								local applied, why = pcall(applyPeer, player, entry.state);
								if not applied then recordError("share player: " .. tostring(why)) end;
							end;
						end;
					end;
					removeAbsent(seen);
					return true;
				end);
				delay = ok and received and 3 or math.min(delay * 2, 15);
			end;
		end;
	end);

	SaladUI:AddSignal(RunService.Heartbeat:Connect(function() LPH_ATTRIBUTES(VM(NONE));
		if not S.On then return end;

		for player, mark in pairs(marks) do
			if player.Parent then pcall(paintMark, player, mark) else clearMark(player) end;
		end;
	end));

	SaladUI:AddSignal(Players.PlayerRemoving:Connect(function(player)
		clearMark(player);
		tagOff(player);
	end));

	local function stopSharing()
		S.generation += 1;
		forgetEveryone();
		local generation = S.generation;
		task.spawn(function()
			if GLOBAL.__SaladShareSession == session and S.generation == generation and not S.On then
				call("POST", "/share", { userId = me, name = LocalPlayer.DisplayName, jobId = game.JobId, state = nil });
			end;
		end);
	end;

	Sections.ShareEffects:AddLabel("Share Effects"):AddToggle({
		Default = true, Flag = "share",
		Callback = function(v)
			local was = S.On;
			S.On = v == true;
			S.generation += 1;
			if was and not S.On then stopSharing() end;
		end,
	});

	onUnload("social share", function()
		S.On = false;
		stopSharing();
	end);
	end);

	-- the room: the visuals chat, on the menu's Chat tab
	guard("chat", function()
	local HttpService = game:GetService("HttpService");
	local MarketplaceService = game:GetService("MarketplaceService");
	local UserInputService = game:GetService("UserInputService");
	local TweenService = game:GetService("TweenService");
	local lib = SaladUI.Lib;
	-- the room wears the menu's palette
	local th = {
		bg = C.window, panel = C.card, head = C.field, line = C.line,
		text = C.text, dim = C.sub, accent = C.accent,
	};

	-- the assets come off R2 now, so the room's address is its own
	local origin = type(GLOBAL.VISUALS_API) == "string" and GLOBAL.VISUALS_API or "https://inertiahub.xyz";
	local API = origin .. "/api/visuals";
	local me = tostring(LocalPlayer.UserId);
	local grab = (syn and syn.request) or (http and http.request)
		or (getgenv and (rawget(getgenv(), "http_request") or rawget(getgenv(), "request")))
		or http_request or request;

	local placeName = "Roblox";
	task.spawn(function()
		local ok, info = pcall(function() return MarketplaceService:GetProductInfo(game.PlaceId) end);
		if ok and type(info) == "table" and type(info.Name) == "string" then placeName = info.Name:sub(1, 60) end;
	end);

	local function call(method, path, body)
		if type(grab) ~= "function" then
			if method ~= "GET" then return nil end;
			local ok, text = pcall(function() return game:HttpGet(API .. path, true) end);
			if not ok then return nil end;
			local fine, data = pcall(function() return HttpService:JSONDecode(text) end);
			return (fine and type(data) == "table" and data.ok) and data.data or nil;
		end;

		local ok, res = pcall(grab, {
			Url = API .. path,
			Method = method,
			Headers = { ["Content-Type"] = "application/json", Accept = "application/json" },
			Body = body and HttpService:JSONEncode(body) or nil,
		});

		if not (ok and type(res) == "table") then return nil end;

		local fine, data = pcall(function() return HttpService:JSONDecode(res.Body) end);

		if fine and type(data) == "table" and data.ok then return data.data end;

		-- the error body says why (a mute, for one)
		return nil, tonumber(res.StatusCode) or 0, (fine and type(data) == "table") and data.error or nil;
	end;


	local function make(class, props, parent)
		local object = Instance.new(class);
		for key, value in pairs(props) do object[key] = value end;
		object.Parent = parent;
		return object;
	end;

	local function tween(object, time, props, style)
		local t = TweenService:Create(object, TweenInfo.new(time, style or Enum.EasingStyle.Quint, Enum.EasingDirection.Out), props);
		t:Play();
		return t;
	end;

	-- dark text on a light colour, light text on a dark one
	local function onColor(c)
		return (0.299 * c.R + 0.587 * c.G + 0.114 * c.B) > 0.6 and Color3.fromRGB(18, 18, 22) or Color3.new(1, 1, 1);
	end;

	-- --------------------------------------------------------------- chat --
	local chatUI = UI.chatPage();
	local page = chatUI.page;

	local EMOJI = { "\240\159\145\141", "\226\157\164\239\184\143", "\240\159\152\130", "\240\159\148\165", "\240\159\146\128", "\240\159\145\128" };
	local LIMIT = 300;
	local AVATAR = 28;
	-- the window is drawn through a UIScale on a phone: Absolute* values are
	-- screen pixels, canvas sizes and offsets are the window's own units.
	-- Mixing them left the canvas 15% short, so the top of the chat could not
	-- be reached.
	local SCALE = math.max(scaler.Scale * K.pop.Scale, 0.01);
	local function syncScale() SCALE = math.max(scaler.Scale * K.pop.Scale, 0.01) end;
	SaladUI:AddSignal(scaler:GetPropertyChangedSignal("Scale"):Connect(syncScale));
	SaladUI:AddSignal(K.pop:GetPropertyChangedSignal("Scale"):Connect(syncScale));

	-- the admin's copy of the script finds a key file nobody else has; the
	-- server checks it, the menu only uses it to decide what to offer
	local adminKey;
	-- the same key file Salad Visuals reads counts here too, so one copy in
	-- an executor's workspace is enough for both menus
	for _, path in ipairs({ userFile("admin.key"), "Salad Visuals/.data/admin.key" }) do
		pcall(function()
			if not adminKey and isfile and readfile and isfile(path) then adminKey = readfile(path):gsub("%s", "") end;
		end);
	end;
	if adminKey == "" then adminKey = nil end;
	-- OWNER holds the key; ADMIN is anyone the owner promoted, asked of the
	-- server whenever the chat opens
	local OWNER = adminKey ~= nil;
	local ADMIN = OWNER;

	-- the machine, so a mute follows it onto other accounts; the server only
	-- keeps a hash of it
	local hardware;
	pcall(function()
		if type(gethwid) == "function" then hardware = tostring(gethwid()):sub(1, 200) end;
	end);

	local function escape(text)
		return (tostring(text):gsub("&", "&amp;"):gsub("<", "&lt;"):gsub(">", "&gt;"):gsub("\"", "&quot;"));
	end;

	-- Mentions: @ and a name as the chat writes it (spaces as underscores).
	-- Either of your names counts as you.
	local function myHandles()
		return {
			[string.lower((tostring(LocalPlayer.DisplayName):gsub("%s", "_")))] = true,
			[string.lower(LocalPlayer.Name)] = true,
		};
	end;

	local function mentionsMe(body)
		local mine = myHandles();
		for word in tostring(body):gmatch("@([%w_]+)") do
			if mine[string.lower(word)] then return true end;
		end;
		return false;
	end;

	-- on already escaped text: @names in the accent, yours brighter still
	local function markMentions(text)
		local mine = myHandles();
		return (text:gsub("@([%w_]+)", function(word)
			local color = mine[string.lower(word)] and th.accent or th.accent:Lerp(th.text, 0.4);
			return ('<font color="#%s"><b>@%s</b></font>'):format(color:ToHex(), word);
		end));
	end;

	-- surfaces are mixed from the theme so a recoloured menu recolours the chat
	local function theirs() return th.head:Lerp(th.line, 0.22) end;
	local function ours() return th.accent:Lerp(th.head, 0.84) end;

	-- one card like the sections on the other pages, so effects drawn behind
