		Size = UDim2.new(1, -K.L.PAD * 2, 1, -K.L.PAD - (MOBILE and 10 or 16)),
		BackgroundColor3 = th.panel, BorderSizePixel = 0, ClipsDescendants = true, ZIndex = 20,
	}, page);
	make("UICorner", { CornerRadius = UDim.new(0, 12) }, root);

	-- the room wears the menu's type (Inter: Latin and Cyrillic in one face)
	do
		local faces = { medium = K.face.medium, bold = K.face.bold };
		local function wear(o)
			if not (o:IsA("TextLabel") or o:IsA("TextButton") or o:IsA("TextBox")) then return end;
			o.FontFace = o.FontFace.Weight.Value >= 600 and faces.bold or faces.medium;
		end;
		SaladUI:AddSignal(root.DescendantAdded:Connect(wear));
	end;

	local list = make("ScrollingFrame", {
